window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家卫生健康委"] = {"zhongwaihezihezuoyiliaojigouguanlizanxingbanfadebudfdc0b":[],"zhongwaihezihezuoyiliaojigouguanlizanxingbanfadebue89d82":[],"zhongyiyishuqueyouzhuanchangrenyuanyishizigekaohezfd7ab0":[{"i":1,"n":"第一条","txt":"为做好中医医术确有专长人员医师资格考核注册管理工作，根据《中华人民共和国中医药法》有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"以师承方式学习中医或者经多年实践，医术确有专长的人员参加医师资格考核和执业注册，适用本办法。"},{"i":3,"n":"第三条","txt":"国家中医药管理局负责全国中医医术确有专长人员医师资格考核及执业工作的管理。 省级中医药主管部门组织本省、自治区、直辖市中医医术确有专长人员医师资格考核；负责本行政区域内取得医师资格的中医医术确有专长人员执业管理。 省级中医药主管部门应当根据本办法制定本省、自治区、直辖市中医医术确有专长人员医师资格考核注册管理实施细则。 设区的市和县级中医药主管部门负责本行政区域内中医医术确有专长人员医师资格考核组织申报、初审及复审工作，负责本行政区域内取得医师资格的中医医术确有专长人员执业日常管理。"},{"i":4,"n":"第四条","txt":"以师承方式学习中医或者经多年实践，医术确有专长的人员，可以申请参加中医医术确有专长人员医师资格考核。"},{"i":5,"n":"第五条","txt":"以师承方式学习中医的，申请参加医师资格考核应当同时具备下列条件： （一）连续跟师学习中医满5年，对某些病证的诊疗，方法独特、技术安全、疗效明显，经指导老师评议合格； （二）由至少2名中医类别执业医师推荐，推荐医师不包括其指导老师。"},{"i":6,"n":"第六条","txt":"经多年中医医术实践的，申请参加医师资格考核应当同时具备下列条件： （一）具有医术渊源，在中医医师指导下从事中医医术实践活动满5年或者《中华人民共和国中医药法》施行前已经从事中医医术实践活动满5年的； （二）对某些病证的诊疗，方法独特、技术安全、疗效明显，并得到患者的认可； （三）由至少2名中医类别执业医师推荐。"},{"i":7,"n":"第七条","txt":"推荐医师应当为被推荐者长期临床实践所在省、自治区、直辖市相关专业中医类别执业医师。"},{"i":8,"n":"第八条","txt":"以师承方式学习中医的，其指导老师应当具有中医类别执业医师资格，从事中医临床工作15年以上或者具有中医类副主任医师以上专业技术职务任职资格。指导老师同时带徒不超过4名。"},{"i":9,"n":"第九条","txt":"符合本办法第五条或者第六条规定的人员，可以向其长期临床实践所在地县级中医药主管部门提出考核申请。"},{"i":10,"n":"第十条","txt":"申请参加中医医术确有专长人员医师资格考核的，应当提交以下材料： （一）国家中医药管理局统一式样的《中医医术确有专长人员医师资格考核申请表》。 （二）本人有效身份证明。 （三）中医医术专长综述，包括医术的基本内容及特点描述、适应症或者适用范围、安全性及有效性的说明等，以及能够证明医术专长确有疗效的相关资料。 （四）至少2名中医类别执业医师的推荐材料。 （五）以师承方式学习中医的，还应当提供跟师学习合同，学习笔记、临床实践记录等连续跟师学习中医满5年的证明材料，以及指导老师出具的跟师学习情况书面评价意见、出师结论；经多年中医医术实践的，还应当提供医术渊源的相关证明材料，以及长期临床实践所在地县级以上中医药主管部门或者所在居委会、村委会出具的从事中医医术实践活动满5年证明，或者至少10名患者的推荐证明。"},{"i":11,"n":"第十一条","txt":"县级中医药主管部门和设区的市级中医药主管部门分别对申请者提交的材料进行初审和复审，复审合格后报省级中医药主管部门。省级中医药主管部门对报送材料进行审核确认，对符合考核条件的人员、指导老师和推荐医师信息应当予以公示。申请者在临床实践中存在医疗纠纷且造成严重后果的，取消其报名资格。"},{"i":12,"n":"第十二条","txt":"中医医术确有专长人员医师资格考核实行专家评议方式，通过现场陈述问答、回顾性中医医术实践资料评议、中医药技术方法操作等形式对实践技能和效果进行科学量化考核。专家人数应当为不少于5人的奇数。"},{"i":13,"n":"第十三条","txt":"考核专家应当对参加考核者使用中医药技术方法的安全性进行风险评估，并针对风险点考核其安全风险意识、相关知识及防范措施。根据参加考核者使用的中医药技术方法分为内服方药和外治技术两类进行考核。"},{"i":14,"n":"第十四条","txt":"内服方药类考核内容包括：医术渊源或者传承脉络、医术内容及特点；与擅长治疗的病证范围相关的中医基础知识、中医诊断技能、中医治疗方法、中药基本知识和用药安全等。 考核程序分为医术专长陈述、现场问答、诊法技能操作和现场辨识相关中药等。 考核专家应当围绕参加考核者使用的中药种类、药性、药量、配伍等进行安全性评估，根据风险点考核相关用药禁忌、中药毒性知识等。"},{"i":15,"n":"第十五条","txt":"外治技术类考核内容包括：医术渊源或者传承脉络、外治技术内容及特点；与其使用的外治技术相关的中医基础知识、擅长治疗的病证诊断要点、外治技术操作要点、技术应用规范及安全风险防控方法或者措施等。 考核程序分为医术专长陈述、现场问答、外治技术操作等。 考核专家应当围绕参加考核者使用外治技术的操作部位、操作难度、创伤程度、感染风险等进行安全性评估，根据风险点考核其操作安全风险认知和有效防范方法等；外敷药物中含毒性中药的，还应当考核相关的中药毒性知识。"},{"i":16,"n":"第十六条","txt":"治疗方法以内服方药为主、配合使用外治技术，或者以外治技术为主、配合使用中药的，应当增加相关考核内容。"},{"i":17,"n":"第十七条","txt":"考核专家根据参加考核者的现场陈述，结合回顾性中医医术实践资料等，围绕相关病证的疗效评价关键要素进行分析评估并提问，对其医术专长的效果进行现场评定。必要时可采用实地调查核验等方式评定效果。"},{"i":18,"n":"第十八条","txt":"经综合评议后，考核专家对参加考核者作出考核结论，并对其在执业活动中能够使用的中医药技术方法和具体治疗病证的范围进行认定。"},{"i":19,"n":"第十九条","txt":"考核合格者，由省级中医药主管部门颁发《中医（专长）医师资格证书》。"},{"i":20,"n":"第二十条","txt":"县级以上地方中医药主管部门应当加强对考核合格人员有关卫生和中医药法律法规基本知识、基本急救技能、临床转诊能力、中医医疗技术相关性感染防控指南、传染病防治基本知识及报告制度、中医病历书写等知识的培训，提高其执业技能，保障医疗安全。"},{"i":21,"n":"第二十一条","txt":"省级中医药主管部门应当加强考核工作的组织领导，完善考核制度，强化考核工作人员和专家培训，严格考核管理，确保考核公平、公正、安全、有序进行。"},{"i":22,"n":"第二十二条","txt":"省级中医药主管部门每年定期组织中医医术确有专长人员医师资格考核，考核时间应当提前3个月向社会公告。"},{"i":23,"n":"第二十三条","txt":"省级中医药主管部门应当建立中医医术确有专长人员医师资格考核专家库。考核专家应当同时符合下列条件： （一）中医类别执业医师； （二）具有丰富的临床经验和技术专长，具备副主任医师以上专业技术职务任职资格或者从事中医临床工作15年以上具有师承或者医术确有专长渊源背景人员； （三）遵纪守法，恪守职业道德，公平公正，原则性强，工作认真负责。"},{"i":24,"n":"第二十四条","txt":"根据参加考核人员申报的医术专长，由省级中医药主管部门在中医医术确有专长人员医师资格考核专家库内抽取考核专家。考核专家是参加考核人员的近亲属或者与其有利害关系的，应当予以回避。"},{"i":25,"n":"第二十五条","txt":"中医（专长）医师实行医师区域注册管理。取得《中医（专长）医师资格证书》者，应当向其拟执业机构所在地县级以上地方中医药主管部门提出注册申请，经注册后取得《中医（专长）医师执业证书》。"},{"i":26,"n":"第二十六条","txt":"中医（专长）医师按照考核内容进行执业注册，执业范围包括其能够使用的中医药技术方法和具体治疗病证的范围。"},{"i":27,"n":"第二十七条","txt":"中医（专长）医师在其考核所在省级行政区域内执业。中医（专长）医师跨省执业的，须经拟执业所在地省级中医药主管部门同意并注册。"},{"i":28,"n":"第二十八条","txt":"取得《中医（专长）医师执业证书》者，即可在注册的执业范围内，以个人开业的方式或者在医疗机构内从事中医医疗活动。"},{"i":29,"n":"第二十九条","txt":"县级中医药主管部门负责对本行政区域内中医（专长）医师执业行为的监督检查，重点对其执业范围、诊疗行为以及广告宣传等进行监督检查。"},{"i":30,"n":"第三十条","txt":"中医（专长）医师应当参加定期考核，每2年为1个周期。定期考核有关要求由省级中医药主管部门确定。"},{"i":31,"n":"第三十一条","txt":"县级以上地方中医药主管部门应当加强对中医（专长）医师的培训，为中医（专长）医师接受继续教育提供条件。"},{"i":32,"n":"第三十二条","txt":"中医（专长）医师通过学历教育取得省级以上教育行政部门认可的中医专业学历的，或者执业时间满5年、期间无不良执业记录的，可以申请参加中医类别执业医师资格考试。"},{"i":33,"n":"第三十三条","txt":"国家建立中医（专长）医师管理信息系统，及时更新中医（专长）医师注册信息，实行注册内容公开制度，并提供中医（专长）医师注册信息查询服务。"},{"i":34,"n":"第三十四条","txt":"参加中医医术确有专长人员资格考核的人员和考核工作人员，违反本办法有关规定，在考核过程中发生违纪违规行为的，按照国家医师资格考试违纪违规处理有关规定处罚；通过违纪违规行为取得《中医（专长）医师资格证书》、《中医（专长）医师执业证书》的人员，由发证部门撤销并收回《中医（专长）医师资格证书》、《中医（专长）医师执业证书》，并进行通报。"},{"i":35,"n":"第三十五条","txt":"中医医术确有专长人员医师资格考核专家违反本办法有关规定，在考核工作中未依法履行工作职责的，省级中医药主管部门应当停止其参与考核工作；情节严重的，应当进行通报批评，并建议其所在单位依法给予相应的处分；存在其他违纪违规行为的，按照国家医师资格考试违纪违规处理有关规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"推荐中医医术确有专长人员的中医医师、以师承方式学习中医的医术确有专长人员的指导老师，违反本办法有关规定，在推荐中弄虚作假、徇私舞弊的，由县级以上中医药主管部门依法责令暂停6个月以上1年以下执业活动；情节严重的，吊销其医师执业证书；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"中医（专长）医师在执业中超出注册的执业范围从事医疗活动的，由县级以上中医药主管部门责令暂停6个月以上1年以下执业活动，并处1万元以上3万元以下罚款；情节严重的，吊销其执业证书。造成患者人身、财产损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"本办法实施前已经取得《乡村医生执业证书》的中医药一技之长人员可以申请参加中医医术确有专长人员医师资格考核，也可继续以乡村医生身份执业，纳入乡村医生管理。自本办法施行之日起，不再开展中医药一技之长人员纳入乡村医生管理工作。 本办法实施前已经按照《传统医学师承和确有专长人员医师资格考核考试办法》规定取得《传统医学师承出师证》的，可以按照本办法规定，在继续跟师学习满2年后申请参加中医医术确有专长人员医师资格考核。 本办法实施前已经按照《传统医学师承和确有专长人员医师资格考核考试办法》规定取得《传统医学医术确有专长证书》的，可以按照本办法规定申请参加中医医术确有专长人员医师资格考核。"},{"i":39,"n":"第三十九条","txt":"港澳台人员在内地以师承方式学习中医的，可在指导老师所在省、自治区、直辖市申请参加中医医术确有专长医师资格考核。"},{"i":40,"n":"第四十条","txt":"《中医（专长）医师资格证书》和《中医（专长）医师执业证书》由国家中医药管理局统一印制。"},{"i":41,"n":"第四十一条","txt":"本办法自2017年12月20日起施行。"}],"zhongyizhensuobeianguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为做好中医诊所的备案管理工作，根据《中华人民共和国中医药法》以及《医疗机构管理条例》等法律法规的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所指的中医诊所，是在中医药理论指导下，运用中药和针灸、拔罐、推拿等非药物疗法开展诊疗服务，以及中药调剂、汤剂煎煮等中药药事服务的诊所。不符合上述规定的服务范围或者存在不可控的医疗安全隐患和风险的，不适用本办法。"},{"i":3,"n":"第三条","txt":"国家中医药管理局负责全国中医诊所的管理工作。 县级以上地方中医药主管部门负责本行政区域内中医诊所的监督管理工作。 县级中医药主管部门具体负责本行政区域内中医诊所的备案工作。"},{"i":4,"n":"第四条","txt":"举办中医诊所的，报拟举办诊所所在地县级中医药主管部门备案后即可开展执业活动。"},{"i":5,"n":"第五条","txt":"举办中医诊所应当同时具备下列条件： （一）个人举办中医诊所的，应当具有中医类别《医师资格证书》并经注册后在医疗、预防、保健机构中执业满三年，或者具有《中医（专长）医师资格证书》；法人或者其他组织举办中医诊所的，诊所主要负责人应当符合上述要求； （二）符合《中医诊所基本标准》； （三）中医诊所名称符合《医疗机构管理条例实施细则》的相关规定； （四）符合环保、消防的相关规定； （五）能够独立承担民事责任。 《医疗机构管理条例实施细则》规定不得申请设置医疗机构的单位和个人，不得举办中医诊所。"},{"i":6,"n":"第六条","txt":"中医诊所备案，应当提交下列材料： （一）《中医诊所备案信息表》； （二）中医诊所主要负责人有效身份证明、医师资格证书、医师执业证书； （三）其他卫生技术人员名录、有效身份证明、执业资格证件； （四）中医诊所管理规章制度； （五）医疗废物处理方案、诊所周边环境情况说明； （六）消防应急预案。 法人或者其他组织举办中医诊所的，还应当提供法人或者其他组织的资质证明、法定代表人身份证明或者其他组织的代表人身份证明。"},{"i":7,"n":"第七条","txt":"备案人应当如实提供有关材料和反映真实情况，并对其备案材料实质内容的真实性负责。"},{"i":8,"n":"第八条","txt":"县级中医药主管部门收到备案材料后，对材料齐全且符合备案要求的予以备案，并当场发放《中医诊所备案证》；材料不全或者不符合备案要求的，应当当场或者在收到备案材料之日起五日内一次告知备案人需要补正的全部内容。 国家逐步推进中医诊所管理信息化，有条件的地方可实行网上申请备案。"},{"i":9,"n":"第九条","txt":"中医诊所应当将《中医诊所备案证》、卫生技术人员信息在诊所的明显位置公示。"},{"i":10,"n":"第十条","txt":"中医诊所的人员、名称、地址等实际设置应当与《中医诊所备案证》记载事项相一致。 中医诊所名称、场所、主要负责人、诊疗科目、技术等备案事项发生变动的，应当及时到原备案机关对变动事项进行备案。"},{"i":11,"n":"第十一条","txt":"禁止伪造、出卖、转让、出借《中医诊所备案证》。"},{"i":12,"n":"第十二条","txt":"中医诊所应当按照备案的诊疗科目、技术开展诊疗活动，加强对诊疗行为、医疗质量、医疗安全的管理，并符合中医医疗技术相关性感染预防与控制等有关规定。 中医诊所发布医疗广告应当遵守法律法规规定，禁止虚假、夸大宣传。"},{"i":13,"n":"第十三条","txt":"县级中医药主管部门应当在发放《中医诊所备案证》之日起二十日内将辖区内备案的中医诊所信息在其政府网站公开，便于社会查询、监督，并及时向上一级中医药主管部门报送本辖区内中医诊所备案信息。上一级中医药主管部门应当进行核查，发现不符合本办法规定的备案事项，应当在三十日内予以纠正。"},{"i":14,"n":"第十四条","txt":"县级以上地方中医药主管部门应当加强对中医诊所依法执业、医疗质量和医疗安全、诊所管理等情况的监督管理。"},{"i":15,"n":"第十五条","txt":"县级中医药主管部门应当自中医诊所备案之日起三十日内，对备案的中医诊所进行现场核查，对相关材料进行核实，并定期开展现场监督检查。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，中医诊所应当向所在地县级中医药主管部门报告，县级中医药主管部门应当注销备案并及时向社会公告： （一）中医诊所停止执业活动超过一年的； （二）中医诊所主要负责人被吊销执业证书或者被追究刑事责任的； （三）举办中医诊所的法人或者其他组织依法终止的； （四）中医诊所自愿终止执业活动的。"},{"i":17,"n":"第十七条","txt":"县级中医药主管部门应当定期组织中医诊所负责人学习卫生法律法规和医疗机构感染防控、传染病防治等知识，促进中医诊所依法执业；定期组织执业人员参加继续教育，提高其专业技术水平。"},{"i":18,"n":"第十八条","txt":"县级中医药主管部门应当建立中医诊所不良执业行为记录制度，对违规操作、不合理收费、虚假宣传等进行记录，并作为对中医诊所进行监督管理的重要依据。"},{"i":19,"n":"第十九条","txt":"县级以上地方中医药主管部门未履行本办法规定的职责，对符合备案条件但未及时发放备案证或者逾期未告知需要补正材料、未在规定时限内公开辖区内备案的中医诊所信息、未依法开展监督管理的，按照《中医药法》第五十三条的规定予以处理。"},{"i":20,"n":"第二十条","txt":"违反本办法规定，未经县级中医药主管部门备案擅自执业的，由县级中医药主管部门责令改正，没收违法所得，并处三万元以下罚款，向社会公告相关信息；拒不改正的，责令其停止执业活动，其直接责任人员自处罚决定作出之日起五年内不得从事中医药相关活动。"},{"i":21,"n":"第二十一条","txt":"提交虚假备案材料取得《中医诊所备案证》的，由县级中医药主管部门责令改正，没收违法所得，并处三万元以下罚款，向社会公告相关信息；拒不改正的，责令其停止执业活动并注销《中医诊所备案证》，其直接责任人员自处罚决定作出之日起五年内不得从事中医药相关活动。"},{"i":22,"n":"第二十二条","txt":"违反本办法第十条规定，中医诊所擅自更改设置未经备案或者实际设置与取得的《中医诊所备案证》记载事项不一致的，不得开展诊疗活动。擅自开展诊疗活动的，由县级中医药主管部门责令改正，给予警告，并处一万元以上三万元以下罚款；情节严重的，应当责令其停止执业活动，注销《中医诊所备案证》。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十一条规定，出卖、转让、出借《中医诊所备案证》的，由县级中医药主管部门责令改正，给予警告，可以并处一万元以上三万元以下罚款；情节严重的，应当责令其停止执业活动，注销《中医诊所备案证》。"},{"i":24,"n":"第二十四条","txt":"中医诊所超出备案范围开展医疗活动的，由所在地县级中医药主管部门责令改正，没收违法所得，并处一万元以上三万元以下罚款。有下列情形之一的，应当责令其停止执业活动，注销《中医诊所备案证》，其直接负责的主管人员自处罚决定作出之日起五年内不得在医疗机构内从事管理工作： （一）因超出备案范围开展医疗活动曾受过行政处罚的； （二）超出备案范围从事医疗活动给患者造成伤害的； （三）违反本办法规定造成其他严重后果的。"},{"i":25,"n":"第二十五条","txt":"本办法未规定的中医诊所管理要求，按照有关法律法规和国家医疗机构管理的相关规定执行。"},{"i":26,"n":"第二十六条","txt":"《中医诊所备案信息表》和《中医诊所备案证》格式由国家中医药管理局统一规定。"},{"i":27,"n":"第二十七条","txt":"本办法施行前已经设置的中医诊所，符合本办法规定备案条件的，在《医疗机构执业许可证》有效期到期之前，可以按照《医疗机构管理条例》的要求管理，也可以按照备案要求管理；不符合备案条件的其他诊所仍然按照《医疗机构管理条例》的要求实行审批管理。"},{"i":28,"n":"第二十八条","txt":"本办法规定的期限以工作日计算。"},{"i":29,"n":"第二十九条","txt":"本办法自2017年12月1日起施行。"}],"zhongwaihezihezuoyiliaojigouguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为进一步适应改革开放的需要，加强对中外合资、合作医疗机构的管理，促进我国医疗卫生事业的健康发展，根据《中华人民共和国中外合资经营企业法》、《中华人民共和国中外合作经营企业法》、《医疗机构管理条例》等国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称中外合资、合作医疗机构是指外国医疗机构、公司、企业和其他经济组织（以下称合资、合作外方），按照平等互利的原则，经中国政府主管部门批准，在中国境内（香港、澳门及台湾地区除外，下同）与中国的医疗机构、公司、企业和其他经济组织（以下称合资、合作中方）以合资或者合作形式设立的医疗机构。"},{"i":3,"n":"第三条","txt":"申请在中国境内设立中外合资、合作医疗机构，适用本办法。"},{"i":4,"n":"第四条","txt":"中外合资、合作医疗机构必须遵守国家有关法律、法规和规章。中外合资、合作医疗机构的正当经营活动及合资、合作双方的合法权益受中国法律保护。"},{"i":5,"n":"第五条","txt":"卫生部和对外贸易经济合作部（以下称外经贸部）在各自的职责范围内负责全国中外合资、合作医疗机构管理工作。 县级以上地方人民政府卫生行政部门（含中医／药主管部门）和外经贸行政部门在各自职责范围内负责本行政区域内中外合资、合作医疗机构的日常监督管理工作。"},{"i":6,"n":"第六条","txt":"中外合资、合作医疗机构的设置与发展必须符合当地区域卫生规划和医疗机构设置规划，并执行卫生部制定的《医疗机构基本标准》。"},{"i":7,"n":"第七条","txt":"申请设立中外合资、合作医疗机构的中外双方应是能够独立承担民事责任的法人。合资、合作的中外双方应当具有直接或间接从事医疗卫生投资与管理的经验，并符合下列要求之一： （一）能够提供国际先进的医疗机构管理经验、管理模式和服务模式； （二）能够提供具有国际领先水平的医学技术和设备； （三）可以补充或改善当地在医疗服务能力、医疗技术、资金和医疗设施方面的不足。"},{"i":8,"n":"第八条","txt":"设立的中外合资、合作医疗机构应当符合以下条件： （一）必须是独立的法人； （二）投资总额不得低于2000万元人民币； （三）合资、合作中方在中外合资、合作医疗机构中所占的股权比例或权益不得低于30％； （四）合资、合作期限不超过20年； （五）省级以上卫生行政部门规定的其他条件。"},{"i":9,"n":"第九条","txt":"合资、合作中方以国有资产参与投资（包括作价出资或作为合作条件），应当经相应主管部门批准，并按国有资产评估管理有关规定，由国有资产管理部门确认的评估机构对拟投入国有资产进行评估。经省级以上国有资产管理部门确认的评估结果，可以作为拟投入的国有资产的作价依据。"},{"i":10,"n":"第十条","txt":"设置中外合资、合作医疗机构，应先向所在地设区的市级卫生行政部门提出申请，并提交以下材料： （一）设置医疗机构申请书； （二）合资、合作双方法人代表签署的项目建议书及中外合资、合作医疗机构设置可行性研究报告； （三）合资、合作双方各自的注册登记证明（复印件）、法定代表人身份证明（复印件）和银行资信证明； （四）国有资产管理部门对拟投入国有资产的评估报告确认文件。 设区的市级卫生行政部门对申请人提交的材料进行初审，并根据区域卫生规划和医疗机构设置规划提出初审意见，并与申请材料、当地区域卫生规划和医疗机构设置规划一起报所在地省级卫生行政部门审核。"},{"i":11,"n":"第十一条","txt":"省级卫生行政部门对申请材料及设区的市级卫生行政部门初审意见进行审核后报卫生部审批。 报请审批，需由省级卫生行政部门向卫生部提交以下材料： （一）申请人设置申请材料； （二）设置地设区的市级人民政府批准发布实施的《医疗机构设置规划》及设置地设区的市级和省级卫生行政部门关于拟设置中外合资、合作医疗机构是否符合当地区域卫生规划和医疗机构设置规划的审核意见； （三）省级卫生行政管理部门关于设置该中外合资、合作医疗机构的审核意见，其中包括对拟设置中外合资、合作医疗机构的名称、选址、规模（床位、牙椅）、诊疗科目和经营期限等的意见； （四）法律、法规和卫生部规定的其他材料。 卫生部应当自受理之日起45个工作日内，作出批准或者不批准的书面决定。"},{"i":12,"n":"第十二条","txt":"申请设置中外合资、合作中医医疗机构（含中外合资、合作中西医结合医疗机构和中外合资、合作民族医医疗机构）的，按本办法第十条和第十一条要求，经所在地设区的市级卫生行政部门初审和所在地的省级卫生行政部门审核，报国家中医药管理局审核后转报卫生部审批。"},{"i":13,"n":"第十三条","txt":"申请人在获得卫生部设置许可后，按照有关法律、法规向外经贸部提出申请，并提交以下材料： （一）设置申请申报材料及批准文件； （二）由中外合资、合作各方的法定代表人或其授权的代表签署的中外合资、合作医疗机构的合同、章程； （三）拟设立中外合资、合作医疗机构董事会成员名单及合资、合作各方董事委派书； （四）工商行政管理部门出具的机构名称预先核准通知书； （五）法律、法规和外经贸部规定的其他材料。 外经贸部应当自受理申请之日起45个工作日内，作出批准或者不批准的书面决定；予以批准的，发给《外商投资企业批准证书》。 获得批准设立的中外合资、合作医疗机构，应自收到外经贸部颁发的《外商投资企业批准证书》之日起一个月内，凭此证书到国家工商行政管理部门办理注册登记手续。"},{"i":14,"n":"第十四条","txt":"申请在我国中西部地区或老、少、边、穷地区设置中外合资、合作医疗机构或申请设置的中外合资、合作医疗机构所提供的医疗服务范围和内容属于国家鼓励的服务领域，可适当放宽第七条、第八条规定的条件。"},{"i":15,"n":"第十五条","txt":"获准设立的中外合资、合作医疗机构，应当按《医疗机构管理条例》和《医疗机构管理条例实施细则》关于医疗机构执业登记所规定的程序和要求，向所在地省级卫生行政部门规定的卫生行政部门申请执业登记，领取《医疗机构执业许可证》。 省级卫生行政部门根据中外合资、合作医疗机构的类别和规模，确定省级卫生行政部门或设区的市级卫生行政部门受理中外合资、合作医疗机构执业登记申请。"},{"i":16,"n":"第十六条","txt":"中外合资、合作医疗机构命名应当遵循卫生部发布的《医疗机构管理条例实施细则》规定。中外合资、合作医疗机构的名称由所在地地名、识别名和通用名依次组成。"},{"i":17,"n":"第十七条","txt":"中外合资、合作医疗机构不得设置分支机构。"},{"i":18,"n":"第十八条","txt":"已设立的中外合资、合作医疗机构变更机构规模（床位、牙椅）、诊疗科目、合资、合作期限等，应按本办法第三章规定的审批程序，经原审批机关审批后，到原登记机关办理相应的变更登记手续。 中外合资、合作医疗机构涉及合同、章程有关条款的变更，由所在地外经贸部门转报外经贸部批准。"},{"i":19,"n":"第十九条","txt":"中外合资、合作医疗机构合资、合作期20年届满，因特殊情况确需延长合资、合作期限的，合资、合作双方可以申请延长合资、合作期限，并应当在合资、合作期限届满的90天前申请延期。延期申请经省级卫生行政部门和外经贸行政部门审核同意后，报请卫生部和外经贸部审批。审批机关自接到申请之日起45个工作日内，作出批准或者不予批准的书面决定。"},{"i":20,"n":"第二十条","txt":"经批准设置的中外合资、合作医疗机构，应当在审批机关规定的期限内办理完有关登记注册手续；逾期未能完成的，经审批机关核准后，撤销该合资、合作项目。"},{"i":21,"n":"第二十一条","txt":"中外合资、合作医疗机构作为独立法人实体，自负盈亏，独立核算，独立承担民事责任。"},{"i":22,"n":"第二十二条","txt":"中外合资、合作医疗机构应当执行《医疗机构管理条例》和《医疗机构管理条例实施细则》关于医疗机构执业的规定。"},{"i":23,"n":"第二十三条","txt":"中外合资、合作医疗机构必须执行医疗技术准入规范和临床诊疗技术规范，遵守新技术、新设备及大型医用设备临床应用的有关规定。"},{"i":24,"n":"第二十四条","txt":"中外合资、合作医疗机构发生医疗事故，依照国家有关法律、法规处理。"},{"i":25,"n":"第二十五条","txt":"中外合资、合作医疗机构聘请外籍医师、护士，按照《中华人民共和国执业医师法》和《中华人民共和国护士管理办法》等有关规定办理。"},{"i":26,"n":"第二十六条","txt":"发生重大灾害、事故、疾病流行或者其他意外情况时，中外合资、合作医疗机构及其卫生技术人员要服从卫生行政部门的调遣。"},{"i":27,"n":"第二十七条","txt":"中外合资、合作医疗机构发布本机构医疗广告，按照《中华人民共和国广告法》、《医疗广告管理办法》办理。"},{"i":28,"n":"第二十八条","txt":"中外合资、合作医疗机构的医疗收费价格按照国家有关规定执行。"},{"i":29,"n":"第二十九条","txt":"中外合资、合作医疗机构的税收政策按照国家有关规定执行。"},{"i":30,"n":"第三十条","txt":"县以上地方各级卫生行政部门负责本行政区域内中外合资、合作医疗机构的日常监督管理工作。 中外合资、合作医疗机构的《医疗机构执业许可证》每年校验一次，《医疗机构执业许可证》的校验由医疗机构执业登记机关办理。"},{"i":31,"n":"第三十一条","txt":"中外合资、合作医疗机构应当按照国家对外商投资企业的有关规定，接受国家有关部门的监督。"},{"i":32,"n":"第三十二条","txt":"中外合资、合作医疗机构违反国家有关法律、法规和规章，由有关主管部门依法查处。对于违反本办法的中外合资、合作医疗机构，县级以上卫生行政部门和外经贸部门可依据相关法律、法规和规章予以处罚。"},{"i":33,"n":"第三十三条","txt":"地方卫生行政部门和地方外经贸行政部门违反本办法规定，擅自批准中外合资、合作医疗机构的设置和变更的，依法追究有关负责人的责任。 中外各方未经卫生部和外经贸部批准，成立中外合资、合作医疗机构并开展医疗活动或以合同方式经营诊疗项目的，视同非法行医，按《医疗机构管理条例》和《医疗机构管理条例实施细则》及有关规定进行处罚。"},{"i":34,"n":"第三十四条","txt":"香港特别行政区、澳门特别行政区、台湾地区的投资者在大陆投资举办合资、合作医疗机构的，参照本办法执行。"},{"i":35,"n":"第三十五条","txt":"申请在中国境内设立外商独资医疗机构的，不予以批准。"},{"i":36,"n":"第三十六条","txt":"各省、自治区、直辖市卫生、外经贸行政部门可依据本办法，结合本地实际制订具体规定。"},{"i":37,"n":"第三十七条","txt":"本办法由卫生部和外经贸部负责解释。"},{"i":38,"n":"第三十八条","txt":"本规定自2000年7月1日起实施。"}],"chanqianzhenduanjishuguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障母婴健康，提高出生人口素质，保证产前诊断技术的安全、有效，规范产前诊断技术的监督管理，依据《中华人民共和国母婴保健法》以及《中华人民共和国母婴保健法实施办法》，制定本管理办法。"},{"i":2,"n":"第二条","txt":"本管理办法中所称的产前诊断，是指对胎儿进行先天性缺陷和遗传性疾病的诊断，包括相应筛查。 产前诊断技术项目包括遗传咨询、医学影像、生化免疫、细胞遗传和分子遗传等。"},{"i":3,"n":"第三条","txt":"本管理办法适用于各类开展产前诊断技术的医疗保健机构。"},{"i":4,"n":"第四条","txt":"产前诊断技术的应用应当以医疗为目的，符合国家有关法律规定和伦理原则，由经资格认定的医务人员在经许可的医疗保健机构中进行。 医疗保健机构和医务人员不得实施任何非医疗目的的产前诊断技术。"},{"i":5,"n":"第五条","txt":"国家卫生健康委负责全国产前诊断技术应用的监督管理工作。"},{"i":6,"n":"第六条","txt":"国家卫生健康委根据医疗需求、技术发展状况、组织与管理的需要等实际情况，制定产前诊断技术应用规划。"},{"i":7,"n":"第七条","txt":"产前诊断技术应用实行分级管理。 国家卫生健康委制定开展产前诊断技术医疗保健机构的基本条件和人员条件；颁布有关产前诊断的技术规范；指定国家级开展产前诊断技术的医疗保健机构；对全国产前诊断技术应用进行质量管理和信息管理；对全国产前诊断专业技术人员的培训进行规划。 省、自治区、直辖市人民政府卫生健康主管部门（以下简称省级卫生健康主管部门）根据当地实际，因地制宜地规划、审批或组建本行政区域内开展产前诊断技术的医疗保健机构；对从事产前诊断技术的专业人员进行系统培训和资格认定；对产前诊断技术应用进行质量管理和信息管理。 县级以上人民政府卫生健康主管部门负责本行政区域内产前诊断技术应用的日常监督管理。"},{"i":8,"n":"第八条","txt":"从事产前诊断的卫生专业技术人员应符合以下所有条件： (一)从事临床工作的，应取得执业医师资格； (二)从事医技和辅助工作的，应取得相应卫生专业技术职称； (三)符合《从事产前诊断卫生专业技术人员的基本条件》； (四)经省级卫生健康主管部门考核合格，取得从事产前诊断的《母婴保健技术考核合格证书》或者《医师执业证书》中加注母婴保健技术（产前诊断类）考核合格的。"},{"i":9,"n":"第九条","txt":"申请开展产前诊断技术的医疗保健机构应符合下列所有条件： (一)设有妇产科诊疗科目; (二)具有与所开展技术相适应的卫生专业技术人员； (三)具有与所开展技术相适应的技术条件和设备； (四)设有医学伦理委员会； (五)符合《开展产前诊断技术医疗保健机构的基本条件》及相关技术规范。"},{"i":10,"n":"第十条","txt":"申请开展产前诊断技术的医疗保健机构应当向所在地省级卫生健康主管部门提交下列文件： (一)医疗机构执业许可证副本; (二)开展产前诊断技术的母婴保健技术服务执业许可申请文件； (三)可行性报告； (四)拟开展产前诊断技术的人员配备、设备和技术条件情况； (五)开展产前诊断技术的规章制度； (六)省级以上卫生健康主管部门规定提交的其他材料。 申请开展产前诊断技术的医疗保健机构，必须明确提出拟开展的产前诊断具体技术项目。"},{"i":11,"n":"第十一条","txt":"申请开展产前诊断技术的医疗保健机构，由所属省、自治区、直辖市人民政府卫生健康主管部门审查批准。省、自治区、直辖市人民政府卫生健康主管部门收到本办法第十条规定的材料后，组织有关专家进行论证，并在收到专家论证报告后30个工作日内进行审核。经审核同意的，发给开展产前诊断技术的母婴保健技术服务执业许可证，注明开展产前诊断以及具体技术服务项目；经审核不同意的，书面通知申请单位。"},{"i":12,"n":"第十二条","txt":"国家卫生健康委根据全国产前诊断技术发展需要，在经审批合格的开展产前诊断技术服务的医疗保健机构中，指定国家级开展产前诊断技术的医疗保健机构。"},{"i":13,"n":"第十三条","txt":"开展产前诊断技术的《母婴保健技术服务执业许可证》每三年校验一次，校验由原审批机关办理。经校验合格的，可继续开展产前诊断技术；经校验不合格的，撤销其许可证书。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市人民政府卫生健康主管部门指定的医疗保健机构，协助卫生健康主管部门负责对本行政区域内产前诊断的组织管理工作。"},{"i":15,"n":"第十五条","txt":"从事产前诊断的人员不得在未许可开展产前诊断技术的医疗保健机构中从事相关工作。"},{"i":16,"n":"第十六条","txt":"对一般孕妇实施产前筛查以及应用产前诊断技术坚持知情选择。开展产前筛查的医疗保健机构要与经许可开展产前诊断技术的医疗保健机构建立工作联系，保证筛查病例能落实后续诊断。"},{"i":17,"n":"第十七条","txt":"孕妇有下列情形之一的，经治医师应当建议其进行产前诊断： (一)羊水过多或者过少的； (二)胎儿发育异常或者胎儿有可疑畸形的； (三)孕早期时接触过可能导致胎儿先天缺陷的物质的； (四)有遗传病家族史或者曾经分娩过先天性严重缺陷婴儿的； (五)年龄超过35周岁的。"},{"i":18,"n":"第十八条","txt":"既往生育过严重遗传性疾病或者严重缺陷患儿的，再次妊娠前，夫妻双方应当到医疗保健机构进行遗传咨询。医务人员应当对当事人介绍有关知识，给予咨询和指导。 经治医师根据咨询的结果，对当事人提出医学建议。"},{"i":19,"n":"第十九条","txt":"确定产前诊断重点疾病，应当符合下列条件： (一)疾病发生率较高； (二)疾病危害严重，社会、家庭和个人疾病负担大； (三)疾病缺乏有效的临床治疗方法； (四)诊断技术成熟、可靠、安全和有效。"},{"i":20,"n":"第二十条","txt":"开展产前检查、助产技术的医疗保健机构在为孕妇进行早孕检查或产前检查时，遇到本办法第十七条所列情形的孕妇，应当进行有关知识的普及，提供咨询服务，并以书面形式如实告知孕妇或其家属，建议孕妇进行产前诊断。"},{"i":21,"n":"第二十一条","txt":"孕妇自行提出进行产前诊断的，经治医师可根据其情况提供医学咨询，由孕妇决定是否实施产前诊断技术。"},{"i":22,"n":"第二十二条","txt":"开展产前诊断技术的医疗保健机构出具的产前诊断报告，应当由2名以上经资格认定的执业医师签发。"},{"i":23,"n":"第二十三条","txt":"对于产前诊断技术及诊断结果，经治医师应本着科学、负责的态度，向孕妇或家属告知技术的安全性、有效性和风险性，使孕妇或家属理解技术可能存在的风险和结果的不确定性。"},{"i":24,"n":"第二十四条","txt":"在发现胎儿异常的情况下，经治医师必须将继续妊娠和终止妊娠可能出现的结果以及进一步处理意见，以书面形式明确告知孕妇，由孕妇夫妻双方自行选择处理方案，并签署知情同意书。若孕妇缺乏认知能力，由其近亲属代为选择。涉及伦理问题的，应当交医学伦理委员会讨论。"},{"i":25,"n":"第二十五条","txt":"开展产前诊断技术的医疗保健机构对经产前诊断后终止妊娠娩出的胎儿，在征得其家属同意后，进行尸体病理学解剖及相关的遗传学检查。"},{"i":26,"n":"第二十六条","txt":"当事人对产前诊断结果有异议的，可以依据《中华人民共和国母婴保健法实施办法》第五章的有关规定，申请技术鉴定。"},{"i":27,"n":"第二十七条","txt":"开展产前诊断技术的医疗保健机构不得擅自进行胎儿的性别鉴定。对怀疑胎儿可能为伴性遗传病，需要进行性别鉴定的，由省、自治区、直辖市人民政府卫生健康主管部门指定的医疗保健机构按照有关规定进行鉴定。"},{"i":28,"n":"第二十八条","txt":"开展产前诊断技术的医疗保健机构应当建立健全技术档案管理和追踪观察制度。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，未经批准擅自开展产前诊断技术的非医疗保健机构，按照《医疗机构管理条例》有关规定进行处罚。"},{"i":30,"n":"第三十条","txt":"对违反本办法，医疗保健机构未取得产前诊断执业许可或超越许可范围，擅自从事产前诊断的，按照《中华人民共和国母婴保健法实施办法》有关规定处罚，由卫生健康主管部门给予警告，责令停止违法行为，没收违法所得；违法所得5000元以上的，并处违法所得3倍以上5倍以下的罚款；违法所得不足5000元的，并处5000元以上2万元以下的罚款。情节严重的,依据《医疗机构管理条例》依法吊销医疗机构执业许可证。"},{"i":31,"n":"第三十一条","txt":"对未取得《母婴保健技术考核合格证书》或者《医师执业证书》中未加注母婴保健技术（产前诊断类）考核合格的个人，擅自从事产前诊断或者超范围执业的，由县级以上人民政府卫生健康主管部门给予警告或者责令暂停六个月以上一年以下执业活动；情节严重的，按照《中华人民共和国执业医师法》吊销其医师执业证书。构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"违反本办法第二十七条规定，按照《中华人民共和国母婴保健法实施办法》第四十二条规定处罚。"},{"i":33,"n":"第三十三条","txt":"各省、自治区、直辖市人民政府卫生健康主管部门可以根据本办法和本地实际情况制定实施细则。"},{"i":34,"n":"第三十四条","txt":"本办法自2003年5月1日起施行。"}],"renleijingzikuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范人类精子库管理，保证人类辅助生殖技术安全、有效应用和健康发展，保障人民健康，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称人类精子库是指以治疗不育症以及预防遗传病等为目的，利用超低温冷冻技术，采集、检测、保存和提供精子的机构。 人类精子库必须设置在医疗机构内。"},{"i":3,"n":"第三条","txt":"精子的采集和提供应当遵守当事人自愿和符合社会伦理原则。 任何单位和个人不得以营利为目的进行精子的采集与提供活动。"},{"i":4,"n":"第四条","txt":"卫生部主管全国人类精子库的监督管理工作。县级以上地方人民政府卫生行政部门负责本行政区域内人类精子库的日常监督管理。"},{"i":5,"n":"第五条","txt":"卫生部根据我国卫生资源、对供精的需求、精子的来源、技术条件等实际情况，制订人类精子库设置规划。"},{"i":6,"n":"第六条","txt":"设置人类精子库应当经卫生部批准。"},{"i":7,"n":"第七条","txt":"申请设置人类精子库的医疗机构应当符合下列条件： （一）具有医疗机构执业许可证； （二）设有医学伦理委员会； （三）具有与采集、检测、保存和提供精子相适应的卫生专业技术人员； （四）具有与采集、检测、保存和提供精子相适应的技术和仪器设备； （五）具有对供精者进行筛查的技术能力； （六）应当符合卫生部制定的《人类精子库基本标准》。"},{"i":8,"n":"第八条","txt":"申请设置人类精子库的医疗机构应当向所在地省、自治区、直辖市人民政府卫生行政部门提交下列资料： （一）设置人类精子库可行性报告； （二）医疗机构基本情况； （三）拟设置人类精子库的建筑设计平面图； （四）拟设置人类精子库将开展的技术业务范围、技术设备条件、技术人员配备情况和组织结构； （五）人类精子库的规章制度、技术操作手册等； （六）省级以上卫生行政部门规定的其他材料。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市人民政府卫生行政部门收到前条规定的材料后，提出初步意见，报卫生部审批。"},{"i":10,"n":"第十条","txt":"卫生部收到省、自治区、直辖市人民政府卫生行政部门的初步意见和材料后，聘请有关专家进行论证，并在收到专家论证报告后45个工作日内进行审核，审核同意的，发给人类精子库批准证书；审核不同意的，书面通知申请单位。"},{"i":11,"n":"第十一条","txt":"批准设置人类精子库的医疗机构应当按照《医疗机构管理条例》的有关规定，持卫生部的批准证书到核发其医疗机构执业许可证的卫生行政部门办理变更登记手续。"},{"i":12,"n":"第十二条","txt":"人类精子库批准证书每2年校验1次。校验合格的，可以继续开展人类精子库工作；校验不合格的，收回人类精子库批准证书。"},{"i":13,"n":"第十三条","txt":"精子的采集与提供应当在经过批准的人类精子库中进行。未经批准，任何单位和个人不得从事精子的采集与提供活动。"},{"i":14,"n":"第十四条","txt":"精子的采集与提供应当严格遵守卫生部制定的《人类精子库技术规范》和各项技术操作规程。"},{"i":15,"n":"第十五条","txt":"供精者应当是年龄在22—45周岁之间的健康男性。"},{"i":16,"n":"第十六条","txt":"人类精子库应当对供精者进行健康检查和严格筛选，不得采集有下列情况之一的人员的精液： （一）有遗传病家族史或者患遗传性疾病； （二）精神病患者； （三）传染病患者或者病源携带者； （四）长期接触放射线和有害物质者； （五）精液检查不合格者； （六）其他严重器质性疾病患者。"},{"i":17,"n":"第十七条","txt":"人类精子库工作人员应当向供精者说明精子的用途、保存方式以及可能带来的社会伦理等问题。人类精子库应当和供精者签署知情同意书。"},{"i":18,"n":"第十八条","txt":"供精者只能在一个人类精子库中供精。"},{"i":19,"n":"第十九条","txt":"精子库采集精子后，应当进行检验和筛查。精子冷冻6个月后，经过复检合格，方可向经卫生行政部门批准开展人类辅助生殖技术的医疗机构提供，并向医疗机构提交检验结果。未经检验或检验不合格的，不得向医疗机构提供。 严禁精子库向医疗机构提供新鲜精子。 严禁精子库向未经批准开展人类辅助生殖技术的医疗机构提供精子。"},{"i":20,"n":"第二十条","txt":"一个供精者的精子最多只能提供给5名妇女受孕。"},{"i":21,"n":"第二十一条","txt":"人类精子库应当建立供精者档案，对供精者的详细资料和精子使用情况进行计算机管理并永久保存。 人类精子库应当为供精者和受精者保密，未经供精者和受精者同意不得泄漏有关信息。"},{"i":22,"n":"第二十二条","txt":"卫生部指定卫生技术评估机构，对人类精子库进行技术质量监测和定期检查。监测结果和检查报告报人类精子库所在地的省、自治区、直辖市人民政府卫生行政部门和卫生部备案。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定，未经批准擅自设置人类精子库，采集、提供精子的非医疗机构，按照《医疗机构管理条例》第四十四条的规定处罚；对有上述违法行为的医疗机构，按照《医疗机构管理条例》第四十七条和《医疗机构管理条例实施细则》第八十条的规定处罚。"},{"i":24,"n":"第二十四条","txt":"设置人类精子库的医疗机构违反本办法，有下列行为之一的，省、自治区、直辖市人民政府卫生行政部门给予警告、1万元以下罚款，并给予有关责任人员行政处分；构成犯罪的，依法追究刑事责任： （一）采集精液前，未按规定对供精者进行健康检查的； （二）向医疗机构提供未经检验的精子的； （三）向不具有人类辅助生殖技术批准证书的机构提供精子的； （四）供精者档案不健全的； （五）经评估机构检查质量不合格的； （六）其他违反本办法规定的行为。"},{"i":25,"n":"第二十五条","txt":"本办法颁布前已经设置人类精子库的医疗机构，在本办法颁布后3个月内向所在地省、自治区、直辖市人民政府卫生行政部门提出申请，省、自治区、直辖市人民政府卫生行政部门和卫生部按照本办法审查，审查同意的，发给人类精子库批准证书；审查不同意的，不得再设置人类精子库。"},{"i":26,"n":"第二十六条","txt":"本办法自2001年8月1日起实施。"}],"renleifuzhushengzhijishuguanlibanfa":[{"i":1,"n":"第一条","txt":"为保证人类辅助生殖技术安全、有效和健康发展，规范人类辅助生殖技术的应用和管理，保障人民健康，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于开展人类辅助生殖技术的各类医疗机构。"},{"i":3,"n":"第三条","txt":"人类辅助生殖技术的应用应当在医疗机构中进行，以医疗为目的，并符合国家计划生育政策、伦理原则和有关法律规定。 禁止以任何形式买卖配子、合子、胚胎。医疗机构和医务人员不得实施任何形式的代孕技术。"},{"i":4,"n":"第四条","txt":"卫生部主管全国人类辅助生殖技术应用的监督管理工作。县级以上地方人民政府卫生行政部门负责本行政区域内人类辅助生殖技术的日常监督管理。"},{"i":5,"n":"第五条","txt":"卫生部根据区域卫生规划、医疗需求和技术条件等实际情况，制订人类辅助生殖技术应用规划。"},{"i":6,"n":"第六条","txt":"申请开展人类辅助生殖技术的医疗机构应当符合下列条件： （一）具有与开展技术相适应的卫生专业技术人员和其他专业技术人员； （二）具有与开展技术相适应的技术和设备； （三）设有医学伦理委员会； （四）符合卫生部制定的《人类辅助生殖技术规范》的要求。"},{"i":7,"n":"第七条","txt":"申请开展人类辅助生殖技术的医疗机构应当向所在地省、自治区、直辖市人民政府卫生行政部门提交下列文件： （一）可行性报告； （二）医疗机构基本情况（包括床位数、科室设置情况、人员情况、设备和技术条件情况等）； （三）拟开展的人类辅助生殖技术的业务项目和技术条件、设备条件、技术人员配备情况； （四）开展人类辅助生殖技术的规章制度； （五）省级以上卫生行政部门规定提交的其他材料。"},{"i":8,"n":"第八条","txt":"申请开展丈夫精液人工授精技术的医疗机构，由省、自治区、直辖市人民政府卫生行政部门审查批准。省、自治区、直辖市人民政府卫生行政部门收到前条规定的材料后，可以组织有关专家进行论证，并在收到专家论证报告后30个工作日内进行审核，审核同意的，发给批准证书；审核不同意的，书面通知申请单位。 对申请开展供精人工授精和体外受精—胚胎移植技术及其衍生技术的医疗机构，由省、自治区、直辖市人民政府卫生行政部门提出初审意见，卫生部审批。"},{"i":9,"n":"第九条","txt":"卫生部收到省、自治区、直辖市人民政府卫生行政部门的初审意见和材料后，聘请有关专家进行论证，并在收到专家论证报告后45个工作日内进行审核，审核同意的，发给批准证书；审核不同意的，书面通知申请单位。"},{"i":10,"n":"第十条","txt":"批准开展人类辅助生殖技术的医疗机构应当按照《医疗机构管理条例》的有关规定，持省、自治区、直辖市人民政府卫生行政部门或者卫生部的批准证书到核发其医疗机构执业许可证的卫生行政部门办理变更登记手续。"},{"i":11,"n":"第十一条","txt":"人类辅助生殖技术批准证书每2年校验一次，校验由原审批机关办理。校验合格的，可以继续开展人类辅助生殖技术；校验不合格的，收回其批准证书。"},{"i":12,"n":"第十二条","txt":"人类辅助生殖技术必须在经过批准并进行登记的医疗机构中实施。未经卫生行政部门批准，任何单位和个人不得实施人类辅助生殖技术。"},{"i":13,"n":"第十三条","txt":"实施人类辅助生殖技术应当符合卫生部制定的《人类辅助生殖技术规范》的规定。"},{"i":14,"n":"第十四条","txt":"实施人类辅助生殖技术应当遵循知情同意原则，并签署知情同意书。涉及伦理问题的，应当提交医学伦理委员会讨论。"},{"i":15,"n":"第十五条","txt":"实施供精人工授精和体外受精—胚胎移植技术及其各种衍生技术的医疗机构应当与卫生部批准的人类精子库签订供精协议。严禁私自采精。 医疗机构在实施人类辅助生殖技术时应当索取精子检验合格证明。"},{"i":16,"n":"第十六条","txt":"实施人类辅助生殖技术的医疗机构应当为当事人保密，不得泄漏有关信息。"},{"i":17,"n":"第十七条","txt":"实施人类辅助生殖技术的医疗机构不得进行性别选择。法律法规另有规定的除外。"},{"i":18,"n":"第十八条","txt":"实施人类辅助生殖技术的医疗机构应当建立健全技术档案管理制度。 供精人工授精医疗行为方面的医疗技术档案和法律文书应当永久保存。"},{"i":19,"n":"第十九条","txt":"实施人类辅助生殖技术的医疗机构应当对实施人类辅助生殖技术的人员进行医学业务和伦理学知识的培训。"},{"i":20,"n":"第二十条","txt":"卫生部指定卫生技术评估机构对开展人类辅助生殖技术的医疗机构进行技术质量监测和定期评估。技术评估的主要内容为人类辅助生殖技术的安全性、有效性、经济性和社会影响。监测结果和技术评估报告报医疗机构所在地的省、自治区、直辖市人民政府卫生行政部门和卫生部备案。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，未经批准擅自开展人类辅助生殖技术的非医疗机构，按照《医疗机构管理条例》第四十四条规定处罚；对有上述违法行为的医疗机构，按照《医疗机构管理条例》第四十七条和《医疗机构管理条例实施细则》第八十条的规定处罚。"},{"i":22,"n":"第二十二条","txt":"开展人类辅助生殖技术的医疗机构违反本办法，有下列行为之一的，由省、自治区、直辖市人民政府卫生行政部门给予警告、3万元以下罚款，并给予有关责任人行政处分；构成犯罪的，依法追究刑事责任： （一）买卖配子、合子、胚胎的； （二）实施代孕技术的； （三）使用不具有《人类精子库批准证书》机构提供的精子的； （四）擅自进行性别选择的； （五）实施人类辅助生殖技术档案不健全的； （六）经指定技术评估机构检查技术质量不合格的； （七）其他违反本办法规定的行为。"},{"i":23,"n":"第二十三条","txt":"本办法颁布前已经开展人类辅助生殖技术的医疗机构，在本办法颁布后3个月内向所在地省、自治区、直辖市人民政府卫生行政部门提出申请，省、自治区、直辖市人民政府卫生行政部门和卫生部按照本办法审查，审查同意的，发给批准证书；审查不同意的，不得再开展人类辅助生殖技术服务。"},{"i":24,"n":"第二十四条","txt":"本办法所称人类辅助生殖技术是指运用医学技术和方法对配子、合子、胚胎进行人工操作，以达到受孕目的的技术，分为人工授精和体外受精—胚胎移植技术及其各种衍生技术。 人工授精是指用人工方式将精液注入女性体内以取代性交途径使其妊娠的一种方法。根据精液来源不同，分为丈夫精液人工授精和供精人工授精。 体外受精—胚胎移植技术及其各种衍生技术是指从女性体内取出卵子，在器皿内培养后，加入经技术处理的精子，待卵子受精后，继续培养，到形成早早期胚胎时，再转移到子宫内着床，发育成胎儿直至分娩的技术。"},{"i":25,"n":"第二十五条","txt":"本办法自2001年8月1日起实施。"}],"renjianchuanrandebingyuanweishengwujunzhongbaocangb2eb21":[{"i":1,"n":"第一条","txt":"为加强人间传染的病原微生物菌（毒）种（以下称菌（毒）种）保藏机构的管理，保护和合理利用我国菌（毒）种或样本资源，防止菌（毒）种或样本在保藏和使用过程中发生实验室感染或者引起传染病传播，依据《中华人民共和国传染病防治法》、《病原微生物实验室生物安全管理条例》（以下称《条例》）的规定制定本办法。"},{"i":2,"n":"第二条","txt":"卫生部主管全国人间传染的菌（毒）种保藏机构（以下称保藏机构）的监督管理工作。 县级以上人民政府卫生行政部门负责本行政区域内保藏机构的监督管理工作。"},{"i":3,"n":"第三条","txt":"本办法所称的菌（毒）种是指可培养的，人间传染的真菌、放线菌、细菌、立克次体、螺旋体、支原体、衣原体、病毒等具有保存价值的，经过保藏机构鉴定、分类并给予固定编号的微生物。 本办法所称的病原微生物样本（以下称样本）是指含有病原微生物的、具有保存价值的人和动物体液、组织、排泄物等物质，以及食物和环境样本等。 可导致人类传染病的寄生虫不同感染时期的虫体、虫卵或样本按照本办法进行管理。 编码产物或其衍生物对人体有直接或潜在危害的基因（或其片段）参照本办法进行管理。 菌（毒）种的分类按照《人间传染的病原微生物名录》（以下简称《名录》）的规定执行。 菌（毒）种或样本的保藏是指保藏机构依法以适当的方式收集、检定、编目、储存菌（毒）种或样本，维持其活性和生物学特性，并向合法从事病原微生物相关实验活动的单位提供菌（毒）种或样本的活动。 保藏机构是指由卫生部指定的，按照规定接收、检定、集中储存与管理菌（毒）"},{"i":4,"n":"第四条","txt":"保藏机构以外的机构和个人不得擅自保藏菌（毒）种或样本。 必要时，卫生部可以根据疾病控制和科研、教学、生产的需要，指定特定机构从事保藏活动。"},{"i":5,"n":"第五条","txt":"国家病原微生物实验室生物安全专家委员会卫生专业委员会负责保藏机构的生物安全评估和技术咨询、论证等工作。"},{"i":6,"n":"第六条","txt":"菌（毒）种或样本有关保密资料、信息的管理和使用必须严格遵守国家保密工作的有关法律、法规和规定。信息及数据的相关主管部门负责确定菌（毒）种或样本有关资料和信息的密级、保密范围、保密期限、管理责任和解密。各保藏机构应当根据菌（毒）种信息及数据所定密级和保密范围制定相应的保密制度，履行保密责任。 未经批准，任何组织和个人不得以任何形式泄漏涉密菌（毒）种或样本有关的资料和信息，不得使用个人计算机、移动储存介质储存涉密菌（毒）种或样本有关的资料和信息。"},{"i":7,"n":"第七条","txt":"保藏机构分为菌（毒）种保藏中心和保藏专业实验室。菌（毒）种保藏中心分为国家级和省级两级。 保藏机构的设立及其保藏范围应当根据国家在传染病预防控制、医疗、检验检疫、科研、教学、生产等方面工作的需要，兼顾各地实际情况，统一规划、整体布局。 国家级菌（毒）种保藏中心和保藏专业实验室根据工作需要设立。省级菌（毒）种保藏中心根据工作需要设立，原则上各省、自治区、直辖市只设立一个。"},{"i":8,"n":"第八条","txt":"国家级菌（毒）种保藏中心的职责为： （一）负责菌（毒）种或样本的收集、选择、鉴定、复核、保藏、供应和依法进行对外交流； （二）出具国家标准菌（毒）株证明； （三）从国际菌（毒）种保藏机构引进标准或参考菌（毒）种，供应国内相关单位使用； （四）开展菌（毒）种或样本分类、保藏新方法、新技术的研究和应用； （五）负责收集和提供菌（毒）种或样本的信息，编制菌（毒）种或样本目录和数据库； （六）组织全国学术交流和培训； （七）对保藏专业实验室和省级菌（毒）种保藏中心进行业务指导。"},{"i":9,"n":"第九条","txt":"省级菌（毒）种保藏中心的职责： （一）负责本行政区域内菌（毒）种或样本的收集、选择、鉴定、分类、保藏、供应和依法进行对外交流； （二）向国家级保藏机构提供国家级保藏机构所需的菌（毒）种或样本； （三）从国家或者国际菌（毒）种保藏机构引进标准或参考菌（毒）种，供应辖区内相关单位使用； （四）开展菌（毒）种或样本分类、保藏新方法、新技术的研究和应用； （五）负责收集和提供本省（自治区、直辖市）菌（毒）种或样本的各种信息，编制地方菌（毒）种或样本目录和数据库。"},{"i":10,"n":"第十条","txt":"保藏专业实验室的职责： （一）负责专业菌（毒）种或样本的收集、选择、鉴定、复核、保藏、供应和依法进行对外交流； （二）开展菌（毒）种或样本分类、保藏新方法、新技术的研究和应用； （三）负责提供专业菌（毒）种或样本的各种信息，建立菌（毒）种或样本数据库； （四）向国家级和所属行政区域内省级保藏中心提供菌（毒）种代表株。"},{"i":11,"n":"第十一条","txt":"下列菌（毒）种或样本必须由国家级保藏中心或专业实验室进行保藏： （一）我国境内未曾发现的高致病性病原微生物菌（毒）种或样本和已经消灭的病原微生物菌（毒）种或样本； （二）《名录》规定的第一类病原微生物菌（毒）种或样本； （三）卫生部规定的其他菌（毒）种或样本。"},{"i":12,"n":"第十二条","txt":"保藏机构及其保藏范围由卫生部组织专家评估论证后指定，并由卫生部颁发《人间传染的病原微生物菌（毒）种保藏机构证书》。"},{"i":13,"n":"第十三条","txt":"申请保藏机构应当具备以下条件： （一）符合国家关于保藏机构设立的整体布局（规划）和实际需要； （二）依法从事涉及菌（毒）种或样本实验活动，并符合有关主管部门的相关规定； （三）符合卫生部公布的《人间传染的病原微生物菌（毒）种保藏机构设置技术规范》的要求，具备与所从事的保藏工作相适应的保藏条件； （四）生物安全防护水平与所保藏的病原微生物相适应，符合《名录》对生物安全防护水平的要求。高致病性菌（毒）种保藏机构还必须具备获得依法开展实验活动资格的相应级别的高等级生物安全实验室； （五）工作人员具备与拟从事保藏活动相适应的能力； （六）明确保藏机构的职能、工作范围、工作内容和所保藏的病原微生物种类。在对所保藏的病原微生物进行风险评估的基础上，制订可靠、完善的生物安全防护方案、相应标准操作程序、意外事故应急预案及感染监测方案等； （七）建立持续有效的保藏机构实验室生物安全管理体系及完善的管理制"},{"i":14,"n":"第十四条","txt":"拟申请保藏机构的法人单位应当向所在地省、自治区、直辖市人民政府卫生行政部门提交下列资料： （一）《人间传染的病原微生物菌（毒）种保藏机构申请表》； （二）保藏机构所属法人机构的法人资格证书（复印件）； （三）保藏机构生物安全实验室的相关批准或者证明文件（复印件）； （四）保藏工作的内容、范围，拟保藏菌（毒）种及样本的清单； （五）保藏机构的组织结构、管理职责、硬件条件、基本建设条件等文件，并提供设施、设备、用品清单； （六）生物安全管理文件、生物安全手册、风险评估报告、相应标准操作程序、生物安全防护方案、意外事故和安全保卫应急预案、暴露及暴露后监测和处理方案等； （七）保藏机构人员名单、生物安全培训证明及所在单位颁发的上岗证书； （八）卫生部规定的其他相关资料。 省、自治区、直辖市人民政府卫生行政部门收到材料后，在15个工作日内进行审核，审核同意的报卫生部。卫生部在收到省、自治区、直辖"},{"i":15,"n":"第十五条","txt":"取得《人间传染的病原微生物菌（毒）种保藏机构证书》的保藏机构发生以下变化时，应当及时向省、自治区、直辖市人民政府卫生行政部门报告，省、自治区、直辖市人民政府卫生行政部门经核查后报卫生部： （一）实验室生物安全级别发生变化； （二）实验室增加高致病性菌（毒）种或样本保藏内容； （三）保藏场所和空间发生变化； （四）实验室存在严重安全隐患、发生生物安全事故； （五）管理体系文件换版或者进行较大修订； （六）保藏机构应报告的其他重大事项。"},{"i":16,"n":"第十六条","txt":"《人间传染的病原微生物菌（毒）种保藏机构证书》有效期5年。保藏机构需要继续从事保藏工作的，应当在有效期届满前6个月按照本办法的规定重新申请《人间传染的病原微生物菌（毒）种保藏机构证书》。"},{"i":17,"n":"第十七条","txt":"各实验室应当将在研究、教学、检测、诊断、生产等实验活动中获得的有保存价值的各类菌（毒）株或样本送交保藏机构进行鉴定和保藏。保藏机构对送交的菌（毒）株或样本，应当予以登记，并出具接收证明。 国家级保藏中心、专业实验室和省级保藏中心应当定期向卫生部指定的机构申报保藏入库菌（毒）种目录。 国家级保藏中心可根据需要选择收藏省级保藏中心保藏的有价值的菌（毒）种。"},{"i":18,"n":"第十八条","txt":"保藏机构有权向有关单位收集和索取所需要保藏的菌（毒）种，相关单位应当无偿提供。"},{"i":19,"n":"第十九条","txt":"保藏机构对专用和专利菌（毒）种要承担相应的保密责任，依法保护知识产权和物权。 样本等不可再生资源所有权属于提交保藏的单位，其他单位需要使用，必须征得所有权单位的书面同意。根据工作需要，卫生部和省、自治区、直辖市人民政府卫生行政部门依据各自权限可以调配使用。"},{"i":20,"n":"第二十条","txt":"申请使用菌（毒）种或样本的实验室，应当向保藏机构提供从事病原微生物相关实验活动的批准或证明文件。保藏机构应当核查登记后无偿提供菌（毒）种或样本。 非保藏机构实验室在从事病原微生物相关实验活动结束后，应当在6个月内将菌（毒）种或样本就地销毁或者送交保藏机构保藏。 医疗卫生、出入境检验检疫、教学和科研机构按规定从事临床诊疗、疾病控制、检疫检验、教学和科研等工作，在确保安全的基础上，可以保管其工作中经常使用的菌（毒）种或样本，其保管的菌（毒）种或样本名单应当报当地卫生行政部门备案。但涉及高致病性病原微生物及行政部门有特殊管理规定的菌（毒）种除外。"},{"i":21,"n":"第二十一条","txt":"实验室从事实验活动，使用涉及本办法第十一条规定的菌（毒）种或样本，应当经卫生部批准；使用其他高致病性菌（毒）种或样本，应当经省级人民政府卫生行政部门批准；使用第三、四类菌（毒）种或样本，应当经实验室所在法人机构批准。"},{"i":22,"n":"第二十二条","txt":"保藏机构储存、提供菌（毒）种和样本，不得收取任何费用。"},{"i":23,"n":"第二十三条","txt":"保藏机构保藏的菌（毒）种或样本符合下列条件之一的可以销毁： （一）国家规定必须销毁的； （二）有证据表明保藏物已丧失生物活性或被污染已不适于继续使用的； （三）保藏机构认为无继续保存价值且经送保藏单位同意的。 销毁的菌（毒）种或样本属于本办法第十一条规定的应当经卫生部批准；销毁其他高致病性菌（毒）种或样本，应当经省级人民政府卫生行政部门批准；销毁第三、四类菌（毒）种或样本的，应当经保藏机构负责人批准。"},{"i":24,"n":"第二十四条","txt":"销毁高致病性病原微生物菌（毒）种或样本必须采用安全可靠的方法，并应当对所用方法进行可靠性验证。 销毁应当在与拟销毁菌（毒）种相适应的生物安全防护水平的实验室内进行，由两人共同操作，并应当对销毁过程进行严格监督。 销毁后应当作为医疗废物送交具有资质的医疗废物集中处置单位处置。 销毁的全过程应当有详细记录，相关记录保存不得少于20年。"},{"i":25,"n":"第二十五条","txt":"保藏机构应当制定严格的安全保管制度，做好菌（毒）种或样本的出入库、储存和销毁等原始记录，建立档案制度，并指定专人负责。所有档案保存不得少于20年。 保藏机构对保藏的菌（毒）种或样本应当设专库储存。建立严格的菌（毒）种库人员管理制度，保（监）管人应当为本单位正式员工并不少于2人。 保藏环境和设施应当符合有关规范，具有防盗设施并向公安机关备案。保藏机构应当制定应急处置预案，并具备相关的应急设施设备，对储存库应当实行24小时监控。"},{"i":26,"n":"第二十六条","txt":"对从事菌（毒）种或样本实验活动的专业人员，保藏机构应当按照国家规定采取有效的安全防护和医疗保障措施。"},{"i":27,"n":"第二十七条","txt":"菌（毒）种或样本的国际交流应当符合本办法第十九条的规定，并参照《中华人民共和国生物两用品及相关设备和技术出口管制条例》、《出口管制清单》、《卫生部和国家质检总局关于加强医用特殊物品出入境管理卫生检疫的通知》等规定办理出入境手续。"},{"i":28,"n":"第二十八条","txt":"卫生部主管保藏机构生物安全监督工作。地方人民政府卫生行政部门应当按照属地化管理的原则对所辖区域内的保藏机构依法进行监督管理。保藏机构的设立单位及上级主管部门应当加强对保藏机构的建设及监督管理，建立明确的责任制和责任追究制度，确保实验室生物安全。"},{"i":29,"n":"第二十九条","txt":"保藏机构应当加强自身管理工作，完善并执行下列要求： （一）主管领导负责菌（毒）种或样本保藏工作； （二）建立菌（毒）种或样本安全保管、使用和销毁制度，标准操作程序和监督保障体系； （三）建立菌（毒）种或样本的出入库记录、相关生物学和鉴定、复核等信息档案； （四）必须保持与其所保藏菌（毒）种或样本危害程度相适应的生物安全防护和储存条件的工作状态； （五）工作人员必须经过生物安全和专业知识培训，考核合格后上岗； （六）建立相关人员健康监测制度，制定保藏机构相关人员感染应急处置预案，并向实验活动批准机构备案。"},{"i":30,"n":"第三十条","txt":"保藏机构每年年底应向卫生部报送所保藏的高致病性菌（毒）种或样本的种类、数量、使用、发放及变化等情况。"},{"i":31,"n":"第三十一条","txt":"保藏机构在保藏过程中发生菌（毒）种或样本被盗、被抢、丢失、泄露以及实验室感染时，应当按照《条例》第十七条、第四十二条、第四十三条、第四十四条、第四十五条、第四十六条、第四十七条、第四十八条规定及时报告和处理，做好感染控制工作。"},{"i":32,"n":"第三十二条","txt":"保藏机构未依照规定储存实验室送交的菌（毒）种和样本，或者未依照规定提供菌（毒）种和样本的，按照《条例》第六十八条规定，由卫生部责令限期改正，收回违法提供的菌（毒）种和样本，并给予警告；造成传染病传播、流行或者其他严重后果的，由其所在单位或者其上级主管部门对主要负责人、直接负责的主管人员和其他直接责任人员，依法予以处理；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"军队菌（毒）种保藏机构的管理由中国人民解放军主管部门负责。"},{"i":34,"n":"第三十四条","txt":"本办法施行前设立的菌（毒）种保藏机构，应当自本办法施行之日起2年内，依照本办法申请《人间传染的病原微生物菌（毒）种保藏机构证书》。"},{"i":35,"n":"第三十五条","txt":"本办法自2009年10月1日起施行。"}],"renjianchuanrandegaozhibingxingbingyuanweishengwuscd3256":[{"i":1,"n":"第一条","txt":"为加强实验室生物安全管理，规范高致病性病原微生物实验活动，依据《病原微生物实验室生物安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于三级、四级生物安全实验室从事与人体健康有关的高致病性病原微生物实验活动资格的审批，及其从事高致病性病原微生物或者疑似高致病性病原微生物实验活动的审批。"},{"i":3,"n":"第三条","txt":"本办法所称高致病性病原微生物是指国家卫生计生委颁布的《人间传染的病原微生物名录》（以下简称《名录》）中公布的第一类、第二类病原微生物和按照第一类、第二类管理的病原微生物，以及其他未列入《名录》的与人体健康有关的高致病性病原微生物或者疑似高致病性病原微生物。"},{"i":4,"n":"第四条","txt":"国家卫生计生委负责三级、四级生物安全实验室从事高致病性病原微生物实验活动资格的审批工作。 国家卫生计生委和省级卫生计生行政部门负责高致病性病原微生物或者疑似高致病性病原微生物实验活动的审批工作。 县级以上地方卫生计生行政部门负责本行政区域内高致病性病原微生物实验室及其实验活动的生物安全监督管理工作。"},{"i":5,"n":"第五条","txt":"三级、四级生物安全实验室从事高致病性病原微生物实验活动，必须取得国家卫生计生委颁发的《高致病性病原微生物实验室资格证书》。"},{"i":6,"n":"第六条","txt":"三级、四级生物安全实验室申请《高致病性病原微生物实验室资格证书》，应当具备以下条件： （一）根据实验室所属法人机构的职能，合法从事与病原微生物菌（毒）种、样本有关的研究、教学、检测、诊断、保藏及生物制品生产等活动，并符合有关主管部门的相关规定； （二）实验室的生物安全防护水平与所从事的病原微生物实验活动相适应，符合《名录》对生物安全防护水平的要求； （三）工程质量依法验收合格；通过实验室国家认可，取得相应级别的生物安全实验室认可证书； （四）实验室应当具备与所从事的实验活动相适应的实验设施、设备及防护措施； （五）从事实验室活动的人员应当参加生物安全培训并取得上岗资格； （六）应当明确实验室的职能、工作范围、工作内容和所从事的病原微生物种类；对所从事的病原微生物应当进行危害性评估，制订生物安全防护方案、实验方法及相应标准操作程序（SOP）、意外事故应急预案及感染监测方案等； （七）应当"},{"i":7,"n":"第七条","txt":"申请《高致病性病原微生物实验室资格证书》，应当向省级卫生计生行政部门提交以下资料： （一）高致病性病原微生物实验室资格申请表； （二）实验室所属法人机构的法人资格证书； （三）实验室认可证书； （四）工程质量依法验收合格的相关证明材料； （五）实验室人员名单，实验室人员取得的生物安全岗位培训证书及所在单位颁发的上岗证书； （六）实验室职能报告（包括工作范围、工作内容等），拟从事实验活动的高致病性病原微生物名单及危害性评估报告、实验内容及相应标准操作程序（SOP）、生物安全防护方案、意外事故应急预案、暴露及暴露后监测和处理方案等； （七）实验室的生物安全管理文件、实验室安全手册和其他相关文件； （八）实验设施、设备清单； （九）个体防护设备、用品清单； （十）国家卫生计生委规定的其他相关资料。"},{"i":8,"n":"第八条","txt":"高致病性病原微生物实验室资格审批程序： （一）省级卫生计生行政部门应当对申请单位提交的申请材料及时审查，对申请材料不齐全或者不符合法定形式的，应当在5日内出具申请材料补正通知书；申请材料齐全或者符合法定形式的，应当在15个工作日内提出初审意见；并将初审意见和有关资料报国家卫生计生委； （二）国家卫生计生委对申报资料进行审查后，应当组织专家进行生物安全评估和技术论证，并组织专家到现场进行评估和论证；专家评估和论证所需时限应当书面告知申请人； （三）国家卫生计生委应当自收到专家评估论证意见之日起20个工作日内做出是否批准的决定。对于批准的，由国家卫生计生委颁发《高致病性病原微生物实验室资格证书》，并附批准该实验室从事的病原微生物名单和项目范围；对不予批准的，由国家卫生计生委书面通知申请者并说明理由。"},{"i":9,"n":"第九条","txt":"取得《高致病性病原微生物实验室资格证书》的三级、四级生物安全实验室软件、硬件系统发生较大变化时，应当按照程序报国家卫生计生委进行评价和审批。"},{"i":10,"n":"第十条","txt":"《高致病性病原微生物实验室资格证书》有效期5年。实验室需要继续从事高致病性病原微生物实验活动的，应当在有效期届满前6个月按照本办法的规定重新申请《高致病性病原微生物实验室资格证书》。"},{"i":11,"n":"第十一条","txt":"取得《高致病性病原微生物实验活动资格证书》的三级、四级生物安全实验室，需要从事某种高致病性病原微生物或者疑似高致病性病原微生物实验活动的，应当报省级以上卫生计生行政部门批准。"},{"i":12,"n":"第十二条","txt":"实验室申请从事《名录》规定在四级生物安全实验室进行的实验活动或者申请从事该实验室病原微生物名单和项目范围外的实验活动的，由国家卫生计生委审批；申请从事该实验室病原微生物名单和项目范围内且在三级生物安全实验室进行的实验活动，由省级卫生计生行政部门审批，并报国家卫生计生委备案。"},{"i":13,"n":"第十三条","txt":"为了预防、控制传染病，需要对我国尚未发现或者已经宣布消灭的病原微生物从事相关实验活动的，应当经国家卫生计生委批准，并在国家卫生计生委指定的实验室中进行。 拟从事未列入《名录》的高致病性病原微生物或者疑似高致病性病原微生物实验活动的实验室应当先进行危害性评估，提出实验室生物安全防护级别，并按照程序报国家卫生计生委审批。"},{"i":14,"n":"第十四条","txt":"取得高致病性病原微生物实验室资格的三级、四级生物安全实验室，申请开展某种高致病性病原微生物或者疑似高致病性病原微生物实验活动，应当具备以下条件： （一）实验活动是以依法从事检测检验、诊断、科学研究、教学、菌（毒）种保藏、生物制品生产等为目的； （二）实验室的生物安全防护级别应当与其拟从事的实验活动相适应； （三）实验室应当具备与所从事的实验活动相适应的人员、设备等； （四）实验室应当根据《名录》，对拟从事实验活动的高致病性病原微生物或者疑似高致病性病原微生物的危害性进行评估，并制定切实可行的生物安全防护措施、意外事故应急预案及标准操作程序。"},{"i":15,"n":"第十五条","txt":"国家对从事特定的高致病性病原微生物或者疑似高致病性病原微生物实验活动的单位有明确规定的，由国家指定的实验室开展有关实验活动。"},{"i":16,"n":"第十六条","txt":"申请开展高致病性病原微生物或者疑似高致病性病原微生物实验活动，应当向省级卫生计生行政部门提交以下资料： （一）高致病性病原微生物实验活动申请表（一式二份）； （二）《高致病性病原微生物实验室资格证书》； （三）实验室所属法人机构生物安全委员会审查意见； （四）实验活动的主要内容和技术方法报告； （五）实验室人员名单，实验室人员取得的生物安全岗位培训证书及所在单位颁发的上岗证书； （六）省级以上卫生计生行政部门规定的其他有关资料。"},{"i":17,"n":"第十七条","txt":"高致病性病原微生物实验活动审批程序： （一）按照本办法第十二条、第十三条的规定，需要由国家卫生计生委批准的，省级卫生计生行政部门应当在受理申请材料之日起5个工作日内进行初审，提出初审意见；并将初审意见和有关资料报国家卫生计生委； （二）国家卫生计生委对申报材料进行审查，并组织专家委员会对申报材料进行评估和论证，提出评估论证意见；专家评估和论证所需时限应当书面告知申请人； （三）国家卫生计生委自收到专家评估论证意见之日起10个工作日内，做出是否批准的决定。对于批准实验活动的，由国家卫生计生委颁发《高致病性病原微生物实验活动批准证书》。对不予批准的，由国家卫生计生委书面通知申请者并说明理由。对于批准的实验活动，国家卫生计生委应当告知实验室所在地省级卫生计生行政部门进行监督检查； （四）按照本办法第十二条的规定，需要由省级卫生计生行政部门批准的，其申报和审批程序由省级卫生计生行政部门参照本办"},{"i":18,"n":"第十八条","txt":"实验室申报或者接受与高致病性病原微生物有关的科研项目，应当符合科研需要和生物安全要求，具有相应的生物安全防护水平。按照本办法第十二条和第十三条规定，科研项目涉及到应由国家卫生计生委审批的实验活动的，承担单位应当将立项结果报国家卫生计生委；科研项目涉及到应由省级卫生计生行政部门审批的实验活动的，承担单位应当将立项结果报省级卫生计生行政部门。 科研项目立项后所从事的实验活动，应当按照本办法第十四条、第十五条、第十六条的规定报批。"},{"i":19,"n":"第十九条","txt":"出入境检验检疫机构、医疗卫生机构等在实验室开展检测、诊断工作时，发现高致病性病原微生物或者疑似高致病性病原微生物，需要进一步从事相关实验活动的，应当依照本办法的规定报批或者转运至具备资格的实验室开展实验活动。"},{"i":20,"n":"第二十条","txt":"出入境检验检疫机构为了检疫工作的紧急需要，申请在实验室对高致病性病原微生物或者疑似高致病性病原微生物开展进一步实验活动的，应当获得所在地省级出入境检验检疫主管部门的同意，并按照本办法第十四条、第十五条、第十六条的规定向所在地省级卫生计生行政部门提出申请。省级卫生计生行政部门应当自收到申请之时起2小时内做出是否批准的决定。省级卫生计生行政部门在做出批准决定的同时，应当通知实验室所在地卫生计生行政部门进行生物安全监督。在规定的时间内未做出决定的，出入境检验检疫机构实验室可以从事相应的实验活动。"},{"i":21,"n":"第二十一条","txt":"需要在动物体上从事高致病性病原微生物相关实验活动的，应当在符合动物实验室生物安全国家标准的生物安全三级以上实验室进行，并按照本办法的规定报批。"},{"i":22,"n":"第二十二条","txt":"实验室的设立单位及其主管部门应当按照《病原微生物实验室生物安全管理条例》的有关规定，加强对高致病性病原微生物实验室的生物安全防护和实验活动的管理。"},{"i":23,"n":"第二十三条","txt":"高致病性病原微生物实验室应当在明显位置标示生物危险标识和生物安全实验室级别标志。 高致病性病原微生物实验室应当制定科学、严格的管理制度并认真贯彻执行。"},{"i":24,"n":"第二十四条","txt":"高致病性病原微生物实验室应当每年定期对工作人员进行培训，并对实验室工作人员进行健康监测。"},{"i":25,"n":"第二十五条","txt":"高致病性病原微生物实验室应当建立完备的实验记录和档案，做好实验室感染控制工作，制定实验室感染应急处置预案。"},{"i":26,"n":"第二十六条","txt":"高致病性病原微生物实验室从事的高致病性病原微生物实验活动结束后，应当及时将病原微生物菌（毒）种和样本就地销毁或者送交保藏机构保管，并及时将实验活动结果以及工作情况向原批准部门报告。"},{"i":27,"n":"第二十七条","txt":"高致病性病原微生物实验室使用新技术、新方法从事高致病性病原微生物相关实验活动的，应当符合防止高致病性病原微生物扩散、保证生物安全和操作者人身安全的要求。 高致病性病原微生物实验室所属法人机构生物安全委员会应对其进行评价，并报国家病原微生物实验室生物安全专家委员会论证；经论证可行的，方可使用。"},{"i":28,"n":"第二十八条","txt":"各级卫生计生行政部门应当按照《病原微生物实验室生物安全管理条例》的规定，对高致病性病原微生物实验室及其实验活动进行监督检查。"},{"i":29,"n":"第二十九条","txt":"对于违反本办法规定的行为，依照《病原微生物实验室生物安全管理条例》第五十六条、第五十七条、第五十八条、第五十九条、第六十条、第六十三条的有关规定予以处罚。"},{"i":30,"n":"第三十条","txt":"省级卫生计生行政部门可根据《病原微生物实验室生物安全管理条例》、《实验室生物安全通用要求》及本办法的有关规定，制定对二级生物安全实验室及其实验活动监督管理的规定。"},{"i":31,"n":"第三十一条","txt":"本办法有关附件由国家卫生计生委统一印制。"},{"i":32,"n":"第三十二条","txt":"本办法自发布之日起施行。"}],"chuanranxingfeidianxingfeiyanfangzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了有效预防和控制传染性非典型肺炎（严重急性呼吸综合征）的发生与流行，保障公众的身体健康和生命安全，根据《中华人民共和国传染病防治法》（以下简称传染病防治法）和《突发公共卫生事件应急条例》（以下简称条例），制定本办法。"},{"i":2,"n":"第二条","txt":"传染性非典型肺炎列入传染病防治法法定传染病管理。传染性非典型肺炎的预防、疫情报告、控制和救治工作按照传染病防治法、条例和本办法的规定执行。"},{"i":3,"n":"第三条","txt":"传染性非典型肺炎防治工作坚持预防为主，防治结合，分级负责，依靠科学，依法管理的原则。"},{"i":4,"n":"第四条","txt":"卫生部对全国传染性非典型肺炎的疾病防治工作实施统一监督管理。 县级以上地方卫生行政部门对本行政区域传染性非典型肺炎的疾病防治工作实施监督管理。 各级疾病预防控制机构按照专业分工，承担责任范围内的传染性非典型肺炎监测管理工作；各级各类医疗机构承担责任范围内的传染性非典型肺炎防治管理任务。"},{"i":5,"n":"第五条","txt":"大力开展爱国卫生运动，加强传染性非典型肺炎健康教育和法制宣传，清洁环境，提高群众防治意识，发动社会力量群防群控，切断传播途径。"},{"i":6,"n":"第六条","txt":"按照国家规定，对参加传染性非典型肺炎防治工作的医疗卫生人员，给予适当补助和保健津贴；对参加防治工作作出贡献的人员，给予表彰和奖励；对参与防治工作发生疾病、残疾、死亡的人员，给予相应的补助和抚恤。"},{"i":7,"n":"第七条","txt":"卫生部及省、自治区、直辖市卫生行政部门应当及时组织开展地区之间、医疗机构之间和疾病预防控制机构之间防治经验的交流；积极开展传染性非典型肺炎防治的科学技术研究工作；鼓励、支持开展传染性非典型肺炎防治的科学研究和技术的国际交流与合作。"},{"i":8,"n":"第八条","txt":"任何单位和个人，必须接受疾病预防控制机构、医疗机构、卫生监督机构有关传染性非典型肺炎的查询、检验、调查取证、监督检查以及预防控制措施，并有权检举、控告违反本办法的行为。"},{"i":9,"n":"第九条","txt":"任何单位和个人发现传染性非典型肺炎病人或者疑似传染性非典型肺炎病人（以下简称病人或者疑似病人）时，都应当及时向当地疾病预防控制机构报告。 医疗机构及其医务人员、疾病预防控制机构的工作人员发现病人或者疑似病人，必须立即向当地疾病预防控制机构报告。疾病预防控制机构发现疫情或者接到疫情报告，应当立即报告上级疾病预防控制机构和当地卫生行政部门。 卫生行政部门接到报告后应当立即报告本级人民政府，同时报告上级卫生行政部门和国务院卫生行政部门。"},{"i":10,"n":"第十条","txt":"任何单位和个人对传染性非典型肺炎疫情，不得隐瞒、缓报、谎报或者授意他人隐瞒、缓报、谎报。"},{"i":11,"n":"第十一条","txt":"卫生部根据传染性非典型肺炎疫情情况，及时向国务院有关部门和各省、自治区、直辖市卫生行政部门以及军队卫生主管部门通报。 传染性非典型肺炎疫情发生地的省、自治区、直辖市卫生行政部门，应当及时向毗邻省、自治区、直辖市卫生行政部门通报。 接到通报的省、自治区、直辖市卫生行政部门，必要时，应当及时通知本行政区域内的医疗卫生机构，做好预防控制工作。"},{"i":12,"n":"第十二条","txt":"卫生部及时、如实向社会公布疫情；省、自治区、直辖市卫生行政部门及时、如实公布本行政区域的疫情。"},{"i":13,"n":"第十三条","txt":"县级以上卫生行政部门应当加强农村疫情监测和疫情报告体系建设，建立健全县、乡、村三级疫情信息网络。"},{"i":14,"n":"第十四条","txt":"各级疾病预防控制机构履行下列职责： （一）对传染性非典型肺炎疫情进行监测与预警； （二）对疫情报告进行汇总、分析、评估； （三）对病人或者疑似病人及其密切接触者进行流行病学调查； （四）对病人或者疑似病人的密切接触者采取必要的医学观察措施； （五）对医疗机构的消毒、隔离工作进行技术指导； （六）对疫点进行隔离控制和消毒； （七）对医疗机构外死亡的病人或者疑似病人的尸体进行消毒处理； （八）对疾病预防控制人员进行专门的业务培训； （九）对公众开展健康教育和医学咨询服务； （十）依据有关规定实施其他疾病预防控制措施。 必要时，向集中收治病人或者疑似病人的医疗机构派驻人员，协助医疗机构开展预防控制工作。"},{"i":15,"n":"第十五条","txt":"疾病预防控制机构、医疗机构、从事传染性非典型肺炎科学研究机构，必须严格执行有关管理制度、操作规程，防止医源性感染、医院内感染、实验室感染和致病性微生物的扩散。 对从事传染性非典型肺炎预防控制、医疗救治、科学研究的人员，所在单位应当根据有关规定，采取有效的防护措施和医疗保健措施。"},{"i":16,"n":"第十六条","txt":"有关单位和个人必须按照疾病预防控制机构的要求，对被传染性非典型肺炎病原体污染的污水、污物、粪便进行严密消毒后处理。"},{"i":17,"n":"第十七条","txt":"医疗机构、疾病预防控制机构发现传染性非典型肺炎病人或者疑似病人时，应当及时采取控制措施。"},{"i":18,"n":"第十八条","txt":"传染性非典型肺炎暴发、流行时，县级以上地方卫生行政部门应当及时报请当地政府根据传染病防治法第二十五条的规定采取相应措施。"},{"i":19,"n":"第十九条","txt":"疾病预防控制机构发现传染性非典型肺炎疫情或者接到疫情报告时，应当立即采取以下控制措施： （一）及时到达现场，调查登记病人或者疑似病人的密切接触者； （二）对密切接触者按照有关规定进行流行病学调查，并根据情况采取集中隔离或者分散隔离的方法进行医学观察； （三）对医疗机构外被病人或者疑似病人污染的场所、物品进行卫生处理。"},{"i":20,"n":"第二十条","txt":"病人或者疑似病人以及密切接触者及其他有关单位和人员，应当配合疾病预防控制机构和医疗机构采取预防控制措施。拒绝配合的，请公安机关按照条例第四十四条的规定予以协助。"},{"i":21,"n":"第二十一条","txt":"传染性非典型肺炎病人死亡后，尸体处理按照传染病防治法第二十八条的有关规定和卫生部、民政部《关于做好传染性非典型肺炎患者遗体处理和丧葬活动的紧急通知》的规定，立即消毒、就地火化。 医疗机构、疾病预防控制机构必要时可以对尸体进行解剖查验。"},{"i":22,"n":"第二十二条","txt":"交通工具上发现病人或者疑似病人的，以及国境口岸和入出境人员、交通工具、货物、集装箱、行李、邮包等需要采取传染性非典型肺炎应急控制措施的，按照条例第三十八条的规定执行。"},{"i":23,"n":"第二十三条","txt":"县级以上地方卫生行政部门应当指定专门的医疗机构负责收治病人或者疑似病人；指定专门机构和车辆负责转运工作，并建立安全的转诊制度。 收治病人或者疑似病人的医疗机构应当符合卫生行政部门规定的隔离、消毒条件，配备必要的救治设备；对病人和疑似病人应当分开隔离治疗；采取有效措施，避免交叉感染。 卫生行政部门对定点医疗机构的建设应当给予必要的支持。"},{"i":24,"n":"第二十四条","txt":"县级以上地方卫生行政部门应当指定医疗机构设立发热门诊和隔离观察室，负责收治可疑发热病人，实行首诊负责制。发现病人或者疑似病人时，应当采取应急控制措施，并及时报告当地疾病预防控制机构。 乡（镇）卫生院应当根据县级以上卫生行政部门的要求设立发热病人隔离观察室，发现可疑发热病人时，及时通知县级医疗机构派专门技术人员诊断或者转诊。 县级以上地方卫生行政部门应当加强县级医院、乡（镇）卫生院传染病医疗救治设施的改造和建设。"},{"i":25,"n":"第二十五条","txt":"各级各类医疗机构应当设立预防保健组织或者人员，承担本单位和责任地段的传染病预防、控制和疫情管理工作。"},{"i":26,"n":"第二十六条","txt":"医疗机构履行下列职责： （一）及时、如实报告疫情； （二）承担责任范围内的传染性非典型肺炎的预防、诊断、治疗任务，改善服务质量，提高治疗水平； （三）对医疗机构内病人或者疑似病人污染的场所、物品、排泄物进行严格的卫生处理； （四）负责对医疗机构内死亡的病人或者疑似病人的尸体进行消毒处理； （五）对医护人员进行专门的业务培训； （六）宣传疾病防治科学知识； （七）依据有关规定开展其他防治工作。"},{"i":27,"n":"第二十七条","txt":"医疗机构应当执行卫生部关于医院感染管理规范、医院消毒卫生标准等有关规定，采取严格的防护措施，使用有效防护用品，防止医务人员感染。 医务人员应当增强传染病防治的法律意识，接受专门的业务培训，遵守操作常规，按照有关规定做好个人防护。"},{"i":28,"n":"第二十八条","txt":"对流动人口中的病人、疑似病人应当按照就地隔离、就地观察、就地治疗的原则，及时送当地指定的专门收治病人和疑似病人的医疗机构治疗。"},{"i":29,"n":"第二十九条","txt":"医疗机构收治病人或者疑似病人，实行先收治、后结算的办法，任何医疗机构不得以费用为由拒收病人。对农民（含进城务工农民）和城镇困难群众中的传染性非典型肺炎病人实行免费医疗，所发生救治费用由政府负担，具体办法按国家有关部门规定执行。"},{"i":30,"n":"第三十条","txt":"医疗机构购进医疗防护用品、药品和医用器械，必须按照卫生行政部门规定的渠道和办法进行，确保质量和安全。"},{"i":31,"n":"第三十一条","txt":"卫生部对全国传染性非典型肺炎防治工作进行督察、指导。 省、自治区、直辖市卫生行政部门对本行政区域的传染性非典型肺炎防治工作进行督察、指导。"},{"i":32,"n":"第三十二条","txt":"各级卫生监督机构在卫生行政部门的领导下，对下列事项进行监督检查： （一）医疗机构和疾病预防控制机构的疫情报告； （二）医疗机构、留验站（所）的隔离、消毒、防护和医疗废弃物处理； （三）公共场所的消毒； （四）密切接触者的医学观察、疫点的环境消毒； （五）生产、经营和使用单位的消毒产品、防护用品的质量； （六）依法开展其他监督检查工作。"},{"i":33,"n":"第三十三条","txt":"卫生部和省、自治区、直辖市卫生行政部门建立领导、协调机构，组建预防控制专家组和医疗救治专家组，组织和协调技术攻关。 卫生部组织制定传染性非典型肺炎防治的指导原则和技术规范。"},{"i":34,"n":"第三十四条","txt":"设区的市级以上地方卫生行政部门应当组织疾病预防控制人员和医疗救治队伍，加强对农村及传染性非典型肺炎疫情严重地区的疫情控制、业务培训和技术指导，提高农村地区控制疫情的能力和诊断、治疗水平。"},{"i":35,"n":"第三十五条","txt":"卫生部根据需要在全国范围内统筹协调卫生资源，调集医疗卫生人员参加防治工作；县级以上地方卫生行政部门在本行政区域内指定医疗机构承担医疗救治任务，组织医疗卫生人员参加防治工作。 疾病预防控制机构和医疗机构及其人员必须服从卫生行政部门的调遣。"},{"i":36,"n":"第三十六条","txt":"县级以上地方卫生行政部门有下列行为之一的，由上级卫生行政部门责令改正，通报批评，给予警告，对其主要负责人由有关部门依法给予降级或者撤职的行政处分；造成传染性非典型肺炎传播、流行或者对社会公众健康造成其他严重危害后果的，依法给予开除的行政处分；构成犯罪的，依法追究刑事责任： （一）未按照规定履行报告职责，隐瞒、缓报、谎报或授意他人隐瞒、缓报、谎报疫情的； （二）在防治工作中玩忽职守，失职、渎职的； （三）对上级卫生行政部门的督察、指导不予配合，或者采取其他方式阻碍、干涉的。"},{"i":37,"n":"第三十七条","txt":"疾病预防控制机构和医疗机构及其人员有下列行为之一的，由县级以上卫生行政部门责令改正，通报批评，给予警告；情节严重的，依法吊销医疗机构执业许可证，并由有关部门对主要负责人给予降级或者撤职的行政处分；对有关医疗卫生人员，由其所在单位或者上级机关给予纪律处分，并由县级以上卫生行政部门依法吊销执业证书；造成传染性非典型肺炎传播、流行或者对社会公众健康造成其他严重危害后果，构成犯罪的，依法追究刑事责任： （一）未依法履行疫情报告职责，隐瞒、缓报或者谎报的； （二）拒绝服从卫生行政部门调遣的； （三）未按照规定及时采取预防控制措施的； （四）拒绝接诊病人或者疑似病人的； （五）未按照规定履行监测职责的。"},{"i":38,"n":"第三十八条","txt":"有关单位和人员有下列行为之一的，由县级以上卫生行政部门责令改正，可以处五千元以下罚款，情节较严重的，可以处五千元以上两万元以下的罚款；对主管人员和直接责任人员，由所在单位或有关部门给予行政处分；构成犯罪的，依法追究刑事责任： （一）对传染性非典型肺炎病原体污染的污水、污物、粪便不按规定进行消毒处理的； （二）造成传染性非典型肺炎的医源性感染、医院内感染、实验室感染或者致病性微生物扩散的； （三）生产、经营、使用消毒产品、隔离防护用品等不符合规定与标准，可能造成传染病的传播、扩散或者造成传染病的传播、扩散的； （四）拒绝、阻碍或者不配合现场调查、资料收集、采样检验以及监督检查的； （五）拒绝执行疾病预防控制机构提出的预防、控制措施的； （六）病人或者疑似病人故意传播传染性非典型肺炎，造成他人感染的。"},{"i":39,"n":"第三十九条","txt":"中国人民解放军、武装警察部队医疗卫生机构参与传染性非典型肺炎防治工作的，参照本办法的规定执行。"},{"i":40,"n":"第四十条","txt":"本办法自发布之日起施行。"}],"chuanranbingbingrenhuoyisichuanranbingbingrenshitic63d2f":[{"i":1,"n":"第一条","txt":"为了及时查明传染病病因，提高传染病诊疗水平，有效控制传染病流行，防止疫情扩散，根据《中华人民共和国传染病防治法》第四十六条（以下简称《传染病防治法》），制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于病因不明的传染病病人或者疑似传染病病人尸体的解剖查验工作。"},{"i":3,"n":"第三条","txt":"传染病病人或者疑似传染病病人尸体解剖查验工作应当在卫生行政部门指定的具有传染病病人尸体解剖查验资质的机构（以下简称查验机构）内进行。 设区的市级以上卫生行政部门应当根据本辖区传染病防治工作实际需要，指定具有独立病理解剖能力的医疗机构或者具有病理教研室或者法医教研室的普通高等学校作为查验机构。 从事甲类传染病和采取甲类传染病预防、控制措施的其他传染病病人或者疑似传染病病人尸体解剖查验的机构，由省级以上卫生行政部门指定。"},{"i":4,"n":"第四条","txt":"查验机构应当具备下列条件： （一）有独立的解剖室及相应的辅助用房，人流、物流、空气流合理，采光良好，其中解剖室面积不少于15平方米； （二）具有尸检台、切片机、脱水机、吸引器、显微镜、照相设备、计量设备、消毒隔离设备、个人防护设备、病理组织取材工作台、储存和运送标本的必要设备、尸体保存设施以及符合环保要求的污水、污物处理设施； （三）至少有二名具有副高级以上病理专业技术职务任职资格的医师，其中有一名具有正高级病理专业技术职务任职资格的医师作为主检人员； （四）具有健全的规章制度和规范的技术操作规程，并定期对工作人员进行培训和考核； （五）具有尸体解剖查验和职业暴露的应急预案。 从事甲类传染病和采取甲类传染病预防、控制措施的其他传染病或者疑似传染病病人尸体解剖查验机构的解剖室应当同时具备对外排空气进行过滤消毒的条件。"},{"i":5,"n":"第五条","txt":"医疗机构为了查找传染病病因，对在医疗机构死亡的传染病人或疑似传染病病人，经所在地设区的市级卫生行政部门批准，进行尸体解剖查验，并告知死者家属，做好记录。"},{"i":6,"n":"第六条","txt":"疾病预防控制机构接到有关部门通知，对在医疗机构外死亡、具有传染病特征的病人尸体应当采取消毒隔离措施；需要查找传染病病因的，经所在地设区的市级卫生行政部门批准，进行尸体解剖查验，并告知死者家属，做好记录。"},{"i":7,"n":"第七条","txt":"解剖查验应当遵循就近原则，按照当地卫生行政部门规定使用专用车辆运送至查验机构。"},{"i":8,"n":"第八条","txt":"除解剖查验工作需要外，任何单位和个人不得对需要解剖查验的尸体进行搬运、清洗、更衣、掩埋、火化等处理。"},{"i":9,"n":"第九条","txt":"医疗机构应当向查验机构提供临床资料复印件，并与查验机构办理交接手续。"},{"i":10,"n":"第十条","txt":"查验机构应当指定一名主检人员。查验人员在尸体解剖查验前，应当认真查阅有关临床资料。"},{"i":11,"n":"第十一条","txt":"解剖查验工作应当严格遵守有关技术操作规范和常规，并符合传染病预防控制的规定。 对解剖查验中的标本采集、保藏、携带和运输应当执行《病原微生物实验室生物安全管理条例》等规定。 解剖查验过程中采集的标本，应当在符合生物安全要求的实验室进行检验。"},{"i":12,"n":"第十二条","txt":"在解剖查验过程中，对所产生的医疗废物应当按照《医疗废物管理条例》等有关规定进行处理。"},{"i":13,"n":"第十三条","txt":"从事尸体解剖查验工作的病理专业技术人员在解剖查验全过程中应当实施标准防护措施，严格遵守有关技术操作规程，采取有效措施防止交叉感染、环境污染造成疫病播散。查验机构要做好有关技术人员的健康监护工作。"},{"i":14,"n":"第十四条","txt":"查验机构应当尽快出具初步查验报告，并及时反馈相应的医疗机构、疾病预防控制机构或者卫生行政部门。 医疗机构根据初步查验报告、病理报告和病原学检验报告，综合临床表现，尽快明确诊断，并按规定报告。"},{"i":15,"n":"第十五条","txt":"尸体解剖查验工作结束后，病理专业技术人员应当对尸体进行缝合、清理。查验机构应当在所在地疾病预防控制机构的指导下或者按其提出的卫生要求对尸体、解剖现场及周围环境进行严格消毒处理。 解剖查验后的尸体经卫生处理后，按照规定火化或者深埋。"},{"i":16,"n":"第十六条","txt":"停放传染病或疑似传染病病人尸体的场所、专用运输工具以及使用过的单体冰柜均应当按照规定严格消毒。"},{"i":17,"n":"第十七条","txt":"有关单位和个人违反本规定，有下列情形之一的，由卫生行政部门依据《传染病防治法》、《执业医师法》、《医疗机构管理条例》等有关法律法规进行相应处理，并对负有责任的主管人员和其他直接责任人员给予行政处分；造成严重后果构成犯罪的，依法追究刑事责任。 （一）医疗机构未经批准，擅自对病因不明并具有传染病特征的病人尸体进行解剖查验的； （二）查验机构及其工作人员在解剖查验过程中，未按规定采取有效的消毒、防护、隔离等措施的； （三）查验机构及其工作人员出具虚假查验报告的； （四）查验机构未按规定履行查验职责的； （五）法律、行政法规规定的其他违法情形。"},{"i":18,"n":"第十八条","txt":"按照《传染病防治法》的规定，为查找传染病病因，对传染病病人尸体或者疑似传染病病人尸体进行解剖查验，卫生行政部门应当保障工作实施经费，对工作人员采取有效的卫生防护措施和医疗保健措施。"},{"i":19,"n":"第十九条","txt":"本规定自2005年9月1日起施行。"}],"chuantongyixueshichenghequeyouzhuanchangrenyuanyis8bc8fa":[{"i":1,"n":"第一条","txt":"为规范传统医学师承和确有专长人员医师资格考核考试，根据《中华人民共和国执业医师法》第十一条的规定和医师资格考试的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"以师承方式学习传统医学或者经多年传统医学临床实践医术确有专长、不具备医学专业学历的人员，参加医师资格考试，适用本办法。"},{"i":3,"n":"第三条","txt":"考核是对传统医学师承和确有专长人员申请参加医师资格考试的资格评价和认定，分为传统医学师承出师考核（以下简称出师考核）和传统医学医术确有专长考核（以下简称确有专长考核）。"},{"i":4,"n":"第四条","txt":"国家中医药管理局负责全国传统医学师承人员和确有专长人员医师资格考核考试的监督管理工作。"},{"i":5,"n":"第五条","txt":"本办法所称“传统医学”是指中医学和少数民族医学。"},{"i":6,"n":"第六条","txt":"出师考核由省级中医药管理部门具体组织实施。"},{"i":7,"n":"第七条","txt":"师承人员应当具有高中以上文化程度或者具有同等学力，并连续跟师学习满3年。"},{"i":8,"n":"第八条","txt":"师承人员的指导老师应当同时具备下列条件： （一）具有中医类别中医或者民族医专业执业医师资格； （二）从事中医或者民族医临床工作15年以上，或者具有中医或者民族医副主任医师以上专业技术职务任职资格； （三）有丰富的临床经验和独特的技术专长； （四）遵纪守法，恪守职业道德，信誉良好； （五）在医疗机构中坚持临床实践，能够完成教学任务。"},{"i":9,"n":"第九条","txt":"师承人员应当与指导老师签订由国家中医药管理局统一式样的师承关系合同。 师承关系合同应当经县级以上公证机构公证，跟师学习时间自公证之日起计算。"},{"i":10,"n":"第十条","txt":"指导老师同时带教师承人员不得超过两名。"},{"i":11,"n":"第十一条","txt":"师承人员跟师学习的形式、内容，由省级中医药管理部门制定。"},{"i":12,"n":"第十二条","txt":"出师考核内容应当包括职业道德和业务水平，重点是传统医学专业基础知识与基本技能，学术经验、技术专长继承情况；方式包括综合笔试和临床实践技能考核。 具体考核内容、标准及办法由国家中医药管理局制定。"},{"i":13,"n":"第十三条","txt":"申请参加出师考核的师承人员，填写由国家中医药管理局统一式样的《传统医学师承出师考核申请表》，并经核准其指导老师执业的卫生行政部门、中医药管理部门审核同意后，向省级中医药管理部门提出申请。"},{"i":14,"n":"第十四条","txt":"申请出师考核的应当提交下列材料： （一）传统医学师承出师考核申请表； （二）本人身份证明； （三）二寸免冠正面半身照片2张； （四）学历或学力证明； （五）指导老师医师资格证书、医师执业证书、专业技术职务任职资格证书，或者核准其执业的卫生行政部门、中医药管理部门出具的从事中医、民族医临床工作15年以上证明； （六）经公证的师承关系合同； （七）省级以上中医药管理部门要求提供的其他材料。"},{"i":15,"n":"第十五条","txt":"省级中医药管理部门对申请出师考核者提交的材料进行审查，符合考核条件的，发放准考证；不符合考核条件的，在受理申请后15个工作日内向申请出师考核者说明理由。"},{"i":16,"n":"第十六条","txt":"出师考核每年进行一次，具体时间由省级中医药管理部门确定，考核工作开始前3个月在辖区内进行公告。"},{"i":17,"n":"第十七条","txt":"出师考核合格者由省级中医药管理部门颁发由国家中医药管理局统一式样的《传统医学师承出师证书》。"},{"i":18,"n":"第十八条","txt":"确有专长考核由设区的市级卫生行政部门、中医药管理部门组织实施。"},{"i":19,"n":"第十九条","txt":"申请确有专长考核的，应当同时具备以下条件： （一）依法从事传统医学临床实践5年以上； （二）掌握独具特色、安全有效的传统医学诊疗技术。"},{"i":20,"n":"第二十条","txt":"确有专长考核内容应当包括职业道德和业务水平，重点是传统医学专业基础知识及掌握的独特诊疗技术和临床基本操作；方式包括综合笔试和临床实际本领考核。 具体考核内容、标准及办法由国家中医药管理局制定。"},{"i":21,"n":"第二十一条","txt":"申请确有专长考核的人员，填写由国家中医药管理局统一式样的《传统医学医术确有专长考核申请表》，并经所在地县级卫生行政部门审核同意后，向设区的市级卫生行政部门、中医药管理部门提出申请。"},{"i":22,"n":"第二十二条","txt":"申请确有专长考核的应当提交下列材料： （一）传统医学医术确有专长考核申请表； （二）本人身份证明； （三）二寸免冠正面半身照片2张； （四）申请人所在地县级卫生行政部门出具的证明其从事传统医学临床实践年限的材料； （五）两名以上执业医师出具的证明其掌握独具特色、安全有效的传统医学诊疗技术的材料； （六）设区的市级以上卫生行政部门、中医药管理部门要求提供的其他材料。"},{"i":23,"n":"第二十三条","txt":"确有专长考核每年进行一次，具体时间由设区的市级卫生行政部门、中医药管理部门确定，考核工作开始前3个月在辖区内进行公告。"},{"i":24,"n":"第二十四条","txt":"考核合格者由负责组织考核的卫生行政部门、中医药管理部门发给由国家中医药管理局统一式样的《传统医学医术确有专长证书》，并报省级中医药管理部门备案。"},{"i":25,"n":"第二十五条","txt":"师承和确有专长人员医师资格考试是评价申请医师资格者是否具备执业所需的专业知识与技能的考试，是国家医师资格考试的组成部分。"},{"i":26,"n":"第二十六条","txt":"师承和确有专长人员医师资格考试方式分为实践技能考试和医学综合笔试，实践技能考试合格的方可参加医学综合笔试。 考试的具体内容和方案由卫生部医师资格考试委员会制定。"},{"i":27,"n":"第二十七条","txt":"师承和确有专长人员取得《传统医学师承出师证书》或《传统医学医术确有专长证书》后，在执业医师指导下，在授予《传统医学师承出师证书》或《传统医学医术确有专长证书》的省（自治区、直辖市）内的医疗机构中试用期满1年并考核合格，可以申请参加执业助理医师资格考试。"},{"i":28,"n":"第二十八条","txt":"师承和确有专长人员取得执业助理医师执业证书后，在医疗机构中从事传统医学医疗工作满5年，可以申请参加执业医师资格考试。"},{"i":29,"n":"第二十九条","txt":"师承和确有专长人员申请参加医师资格考试应当到规定的考点办公室报名，并提交下列材料： （一）二寸免冠正面半身照片2张； （二）本人身份证明； （三）《传统医学师承出师证书》或《传统医学医术确有专长证书》； （四）试用机构出具的试用期考核合格证明； （五）执业助理医师申报执业医师资格考试的，还需同时提交执业助理医师资格证书和医师执业证书复印件； （六）报考所需的其他材料。 其他报考程序按医师资格考试的有关规定执行。"},{"i":30,"n":"第三十条","txt":"师承和确有专长人员医师资格考试的组织管理与实施，按照医师资格考试有关规定执行。"},{"i":31,"n":"第三十一条","txt":"师承和确有专长人员医师资格考试合格线由卫生部医师资格考试委员会确定。 考试成绩合格的，获得卫生部统一印制的《医师资格证书》。"},{"i":32,"n":"第三十二条","txt":"申请出师考核和确有专长考核人员在申请或者参加考核中，有下列情形的，取消当年参加考核的资格，构成犯罪的，依法追究刑事责任： （一）假报姓名、年龄、学历、工龄、民族、户籍、学籍和伪造证件、证明、档案以取得申请考核资格的； （二）在考核中扰乱考核秩序的； （三）向考核人员行贿的； （四）威胁或公然侮辱、诽谤考核人员的； （五）有其他严重舞弊行为的。"},{"i":33,"n":"第三十三条","txt":"卫生行政部门、中医药管理部门工作人员违反本办法有关规定，出具假证明，提供假档案，在考核中弄虚作假、玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"在医师资格考试过程中发生违规、违纪行为的，根据医师资格考试违规处理有关规定进行处罚。"},{"i":35,"n":"第三十五条","txt":"本办法所指传统医学临床实践是指取得有效行医资格人员从事的传统医学医疗活动，或者未取得有效行医资格人员但在中医、民族医执业医师指导下从事的传统医学医疗实习活动。"},{"i":36,"n":"第三十六条","txt":"本办法由国家中医药管理局负责解释。"},{"i":37,"n":"第三十七条","txt":"本办法自2007年2月1日起施行。1999年7月23日发布的《传统医学师承和确有专长人员医师资格考核考试暂行办法》同时废止。"}],"quanguoweishengtongjigongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强全国卫生统计工作的组织和指导，保障卫生统计现代化建设的顺利进行，充分发挥卫生统计在多层次决策和管理中的信息、咨询与监督作用，更好地适应我国卫生改革与发展的需要，根据《中华人民共和国统计法》及其《实施细则》，特制定本办法。"},{"i":2,"n":"第二条","txt":"卫生统计工作的基本任务是依照《统计法》和国家有关法律、政策，采集卫生资源投入、分配与利用，卫生服务质量和效益，居民健康水平等统计数据，提供统计资料和统计分析，实行统计咨询与统计监督。"},{"i":3,"n":"第三条","txt":"各部门、各级各类卫生事业单位，从事医疗卫生服务的私人开业机构和个体开业人员，必须向当地卫生行政部门报送卫生统计数据。"},{"i":4,"n":"第四条","txt":"各级卫生行政部门和卫生事业单位要把统计工作列入议事日程，加强领导，定期检查并监督统计工作法规、计划和统计报表制度的执行情况。各级卫生行政部门在开展统计工作中应与同级人民政府统计机构密切配合，并在统计业务上接受同级人民政府统计机构的指导。"},{"i":5,"n":"第五条","txt":"各级卫生行政部门和卫生事业单位应按照《统计法》的有关规定，加强统计力量，充实统计人员，提高统计人员的素质。"},{"i":6,"n":"第六条","txt":"各级卫生行政部门和事业单位必须将统计工作经费列入卫生经费计划，从经费上保证统计工作的顺利进行和统计事业的发展。"},{"i":7,"n":"第七条","txt":"各级卫生行政部门和事业单位要加快推广和应用现代计算与信息传输技术，建立统计信息自动化系统，提高卫生统计服务质量和效率。"},{"i":8,"n":"第八条","txt":"各级卫生行政部门和事业单位的统计机构和统计人员按照《统计法》行使卫生统计调查、统计报告和统计监督的职权，执行本部门、本单位统计执法情况检查，不受任何侵犯。"},{"i":9,"n":"第九条","txt":"为了完善统计法制建设，地方各级卫生行政部门和事业单位必须根据本《办法》，结合本地区、本部门和本单位的具体情况，制定统计工作制度。"},{"i":10,"n":"第十条","txt":"卫生部设立统计机构，各司（局）根据本司（局）统计业务的需要配备统计人员。"},{"i":11,"n":"第十一条","txt":"各省（区、市）卫生厅（局）设统计机构或综合统计工作所在处（室）配备专职统计人员，各处（室）配备兼职统计人员。省（区、市）辖市（区）、计划单列市卫生局配备专职统计人员；地（市、州、盟）、县卫生局根据统计工作任务的需要配备专职或兼职统计人员。"},{"i":12,"n":"第十二条","txt":"卫生事业单位统计机构与统计人员 （一）县及县以上医院设立统计机构，充实专职统计人员。乡（镇）卫生院配备与本单位统计工作任务相适应的统计人员。 （二）省（区、市）卫生防疫、防治、妇幼保健等机构设立统计科（室）；地（市、州、盟）、县预防保健机构，门诊部、专科防治所（站）等其他机构根据本单位统计工作任务的需要配备统计人员。"},{"i":13,"n":"第十三条","txt":"卫生部统计机构是卫生部统计行政工作的执行机构，直接负责综合统计任务，指导全国卫生统计工作，为制定全国卫生方针政策和卫生事业发展规划，实行宏观调控与科学管理服务。其主要职责是： （一）在卫生部领导、国家统计局的业务指导下，草拟全国卫生统计工作方针政策和规划； （二）依据《中华人民共和国统计法》和国家社会统计调查的原则，草拟全国卫生部门统计法规和卫生统计报表制度，组织并执行全国卫生部门统计法规执行情况检查； （三）负责全国卫生综合统计年报、国家卫生服务调查，针对全国卫生改革与发展中出现的情况和问题开展有关专项调查，管理和协调本部各司（局）的业务统计工作； （四）负责公布全国卫生事业发展情况统计公报，统一管理、提供全国卫生统计资料，审核和管理本部各司（局）制发的业务统计报表、调查方案，审核本部各司（局）发布的业务统计数据，归口管理全国卫生统计分类标准及其代码的制订工作； （五）组织建立全国卫"},{"i":14,"n":"第十四条","txt":"各省（区、市）卫生厅（局）统计机构或综合统计工作所在处（室）执行本厅（局）统计行政工作。其主要职责是： （一）在卫生厅（局）领导、卫生部统计机构和地方同级人民政府统计机构的业务指导下，按照全国卫生统计法规、规划和统计报表制度的指导原则以及有关规定，草拟本地区卫生统计工作制度、规划和统计报表制度，执行国家卫生统计调查任务，指导本地区卫生统计工作，组织并执行本地区卫生部门统计法规执行情况检查； （二）负责本地区卫生综合统计年报、卫生服务调查，针对本地区卫生改革与发展中出现的情况和问题开展有关专项调查，管理和协调本厅（局）其他处（室）的业务统计工作； （三）负责公布本地区卫生事业发展情况统计公报，统一管理、提供本地区卫生统计资料，审核和管理本厅（局）其他处（室）的业务统计报表、调查方案，审核本厅（局）其他处（室）发布的业务统计数据； （四）组织建立本地区卫生统计信息自动化系统，并对此实行管理"},{"i":15,"n":"第十五条","txt":"卫生事业单位统计机构执行本单位综合统计职能。其主要职责是： （一）执行上级卫生行政部门制定的卫生统计规章和卫生统计报表制度； （二）建立健全本单位统计工作制度； （三）填报上级卫生行政部门颁发的统计调查表，收集、整理和统一提供本单位卫生统计资料，管理和协调本单位其他科（室）的统计工作； （四）对本单位的计划执行、业务开展和管理工作等情况进行统计分析，实行统计咨询和统计监督； （五）管理本单位的统计调查表、各项基本统计资料和数据库。"},{"i":16,"n":"第十六条","txt":"各级卫生事业单位应依照国家规定评定统计干部技术职称，逐步实行统计专业技术职称聘任制度。增加或补充专职卫生统计人员，原则上应从高等院校和中等专业学校毕业生中考核录用。对现有不完全具备统计专业知识的专职卫生统计人员，应由所在部门或单位进行培训，卫生事业单位统计人员并要参加当地人民政府统计机构组织的技术职称资格考试。"},{"i":17,"n":"第十七条","txt":"卫生部、各省（区、市）卫生厅（局）举办在职卫生统计干部或师资培训班、讲习班，委托部分中等卫生学校开办卫生统计专业班，还可根据全国或本地区卫生统计工作发展的需要，委托有条件的高等医学院校开办卫生统计专业后期分化班，培养高级卫生统计专业人员。卫生事业单位应在卫生行政部门的安排下，组织本单位统计人员参加统计培训班、讲习班学习，提高他们的业务水平。"},{"i":18,"n":"第十八条","txt":"各级卫生行政部门和事业单位要为统计人员提供必要的工作条件，帮助他们解决工作、学习和生活中的实际问题，以保证统计人员搞好本职工作。"},{"i":19,"n":"第十九条","txt":"卫生行政部门管辖范围内的全国卫生统计报表必须由卫生部统计机构审核，经卫生部批准颁发，并报国家统计局备案。统计调查范围超出卫生行政部门管辖范围的全国卫生统计报表，须由卫生部统计机构审核，经卫生部报国家统计局批准后颁发。卫生行政部门管辖范围内的地方卫生统计报表，必须由地方卫生行政部门统计机构或综合统计工作所在机构审核，经地方卫生行政部门批准颁发，并报地方同级人民政府统计机构备案。统计调查范围超出卫生行政部门管辖范围的地方卫生统计报表，须由地方卫生行政部门统计机构或综合统计工作所在机构审核，经地方卫生行政部门报地方同级人民政府统计机构批准后颁发。"},{"i":20,"n":"第二十条","txt":"由各级卫生行政部门制定，经同级人民政府统计机构备案或批准的卫生统计报表，必须在表的右上角标明表号、制表机关名称、备案或批准机关名称、备案或批准文号。卫生统计机构或统计人员必须严格按照统计调查程序、上报日期和有关规定执行统计调查任务，不得拒报、迟报，更不得虚报、瞒报、伪造或篡改。"},{"i":21,"n":"第二十一条","txt":"卫生部制定的《全国卫生统计报表制度》是全国统一的卫生统计标准，其内容包括统计分类目录、指标涵义、计算方法、统计范围、机构代码等。地方各级卫生行政部门可在严格执行《全国卫生统计报表制度》的前提下，制定补充性的地方卫生统计报表制度。卫生统计报表制度未经制定机关同意，任何单位和个人不得修改。"},{"i":22,"n":"第二十二条","txt":"卫生行政部门统计机构或综合统计工作所在机构与本部门其他机构的统计调查必须分工明确，相互协调，不得交叉重复。"},{"i":23,"n":"第二十三条","txt":"卫生统计调查的方式除全面统计报表外，还应积极开展各种类型的专项调查。卫生行政部门管辖范围内的专项调查，须由卫生行政部门统计机构或综合统计工作所在机构审核。超出卫生行政部门管辖范围的专项调查，须由卫生行政部门统计机构或综合统计工作所在机构审核，经卫生行政部门报同级人民政府统计机构批准后实施。专项调查能够满足的不用全面统计调查，一次性调查能够满足的不用经常性调查，专项调查的内容原则上不能和全面统计报表的内容重复。"},{"i":24,"n":"第二十四条","txt":"各级卫生行政部门和事业单位有权拒绝填报违反《统计法》与本《办法》所颁发的各种统计调查表。"},{"i":25,"n":"第二十五条","txt":"卫生行政部门、卫生事业单位统计机构或综合统计工作所在机构分别统一管理本部门、本单位的卫生统计资料，统计数字不得数出多门，各行其是。同一卫生行政部门、卫生事业单位内的其他机构必须向本部门、本单位统计机构或综合统计工作所在机构提供各项业务统计数据。各级卫生部门统计机构或未设统计机构的卫生部门编辑和提供卫生统计资料，须由本机构领导或本部门的主管领导审批。代表国家、地区或单位的卫生综合统计数字，必须由各自主管的卫生行政部门、卫生事业单位统计机构或综合统计工作所在机构对外公布，并以此为准。卫生行政部门、卫生事业单位内其他机构公布业务统计数字，必须经本部门、本单位统计机构或综合统计工作所在机构审核。"},{"i":26,"n":"第二十六条","txt":"各级卫生事业单位应建立健全原始记录、登记表、台账和统计资料档案制度，确保统计数字数出有据，准确无误。"},{"i":27,"n":"第二十七条","txt":"各级卫生行政部门和事业单位要建立统计资料审核、查询、订正制度。上报的统计调查表，由制表人签名或盖章，并经本单位领导审核、签名或盖章后，加盖本单位公章。单位领导和统计人员要对统计数字的准确性负责。"},{"i":28,"n":"第二十八条","txt":"各级卫生行政部门和事业单位要搞好统计服务，充分利用可以公开的卫生统计资料为社会和公众服务。提供卫生统计数据，编辑、出版和发行卫生统计资料实行有偿和无偿服务相结合。"},{"i":29,"n":"第二十九条","txt":"各级卫生行政部门和事业单位应对下列统计人员或集体给予奖励： （一）在卫生统计工作中做出显著成绩的； （二）坚持依法统计，抵制统计违法行为有突出表现的。"},{"i":30,"n":"第三十条","txt":"凡有下列行为之一，应由卫生行政主管部门责令改正，予以通报批评；情节严重的，可对负有直接责任的主管人员或其他直接责任人员依法给予行政处分： （一）虚报、瞒报、伪造、篡改卫生统计数字的； （二）拒报或屡次迟报卫生统计数据的； （三）侵犯卫生统计机构、卫生统计人员行使《统计法》与本《办法》职权的； （四）对拒绝、抵制篡改统计资料或编造虚假数据行为的统计人员进行打击报复的。"},{"i":31,"n":"第三十一条","txt":"对违反《统计法》构成犯罪的，由司法机关依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"本《办法》由卫生部负责解释。"},{"i":33,"n":"第三十三条","txt":"本《办法》自发布之日起实施。1992年6月20日卫生部发布的《全国卫生统计工作管理办法》同时废止。"}],"gonggongchangsuoweishengguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《公共场所卫生管理条例》的规定，制定本细则。"},{"i":2,"n":"第二条","txt":"公共场所经营者在经营活动中，应当遵守有关卫生法律、行政法规和部门规章以及相关的卫生标准、规范，开展公共场所卫生知识宣传，预防传染病和保障公众健康，为顾客提供良好的卫生环境。"},{"i":3,"n":"第三条","txt":"国家卫生计生委主管全国公共场所卫生监督管理工作。 县级以上地方各级人民政府卫生计生行政部门负责本行政区域的公共场所卫生监督管理工作。 国境口岸及出入境交通工具的卫生监督管理工作由出入境检验检疫机构按照有关法律法规的规定执行。 铁路部门所属的卫生主管部门负责对管辖范围内的车站、等候室、铁路客车以及主要为本系统职工服务的公共场所的卫生监督管理工作。"},{"i":4,"n":"第四条","txt":"县级以上地方各级人民政府卫生计生行政部门应当根据公共场所卫生监督管理需要，建立健全公共场所卫生监督队伍和公共场所卫生监测体系，制定公共场所卫生监督计划并组织实施。"},{"i":5,"n":"第五条","txt":"鼓励和支持公共场所行业组织开展行业自律教育，引导公共场所经营者依法经营，推动行业诚信建设，宣传、普及公共场所卫生知识。"},{"i":6,"n":"第六条","txt":"任何单位或者个人对违反本细则的行为，有权举报。接到举报的卫生计生行政部门应当及时调查处理，并按照规定予以答复。"},{"i":7,"n":"第七条","txt":"公共场所的法定代表人或者负责人是其经营场所卫生安全的第一责任人。 公共场所经营者应当设立卫生管理部门或者配备专（兼）职卫生管理人员，具体负责本公共场所的卫生工作，建立健全卫生管理制度和卫生管理档案。"},{"i":8,"n":"第八条","txt":"公共场所卫生管理档案应当主要包括下列内容： （一）卫生管理部门、人员设置情况及卫生管理制度； （二）空气、微小气候（湿度、温度、风速）、水质、采光、照明、噪声的检测情况； （三）顾客用品用具的清洗、消毒、更换及检测情况； （四）卫生设施的使用、维护、检查情况； （五）集中空调通风系统的清洗、消毒情况； （六）安排从业人员健康检查情况和培训考核情况； （七）公共卫生用品进货索证管理情况； （八）公共场所危害健康事故应急预案或者方案； （九）省、自治区、直辖市卫生计生行政部门要求记录的其他情况。 公共场所卫生管理档案应当有专人管理，分类记录，至少保存两年。"},{"i":9,"n":"第九条","txt":"公共场所经营者应当建立卫生培训制度，组织从业人员学习相关卫生法律知识和公共场所卫生知识，并进行考核。对考核不合格的，不得安排上岗。"},{"i":10,"n":"第十条","txt":"公共场所经营者应当组织从业人员每年进行健康检查，从业人员在取得有效健康合格证明后方可上岗。 患有痢疾、伤寒、甲型病毒性肝炎、戊型病毒性肝炎等消化道传染病的人员，以及患有活动性肺结核、化脓性或者渗出性皮肤病等疾病的人员，治愈前不得从事直接为顾客服务的工作。"},{"i":11,"n":"第十一条","txt":"公共场所经营者应当保持公共场所空气流通，室内空气质量应当符合国家卫生标准和要求。 公共场所采用集中空调通风系统的，应当符合公共场所集中空调通风系统相关卫生规范和规定的要求。"},{"i":12,"n":"第十二条","txt":"公共场所经营者提供给顾客使用的生活饮用水应当符合国家生活饮用水卫生标准要求。游泳场（馆）和公共浴室水质应当符合国家卫生标准和要求。"},{"i":13,"n":"第十三条","txt":"公共场所的采光照明、噪声应当符合国家卫生标准和要求。 公共场所应当尽量采用自然光。自然采光不足的，公共场所经营者应当配置与其经营场所规模相适应的照明设施。 公共场所经营者应当采取措施降低噪声。"},{"i":14,"n":"第十四条","txt":"公共场所经营者提供给顾客使用的用品用具应当保证卫生安全，可以反复使用的用品用具应当一客一换，按照有关卫生标准和要求清洗、消毒、保洁。禁止重复使用一次性用品用具。"},{"i":15,"n":"第十五条","txt":"公共场所经营者应当根据经营规模、项目设置清洗、消毒、保洁、盥洗等设施设备和公共卫生间。 公共场所经营者应当建立卫生设施设备维护制度，定期检查卫生设施设备，确保其正常运行，不得擅自拆除、改造或者挪作他用。公共场所设置的卫生间，应当有单独通风排气设施，保持清洁无异味。"},{"i":16,"n":"第十六条","txt":"公共场所经营者应当配备安全、有效的预防控制蚊、蝇、蟑螂、鼠和其他病媒生物的设施设备及废弃物存放专用设施设备，并保证相关设施设备的正常使用，及时清运废弃物。"},{"i":17,"n":"第十七条","txt":"公共场所的选址、设计、装修应当符合国家相关标准和规范的要求。 公共场所室内装饰装修期间不得营业。进行局部装饰装修的，经营者应当采取有效措施，保证营业的非装饰装修区域室内空气质量合格。"},{"i":18,"n":"第十八条","txt":"室内公共场所禁止吸烟。公共场所经营者应当设置醒目的禁止吸烟警语和标志。 室外公共场所设置的吸烟区不得位于行人必经的通道上。 公共场所不得设置自动售烟机。 公共场所经营者应当开展吸烟危害健康的宣传，并配备专（兼）职人员对吸烟者进行劝阻。"},{"i":19,"n":"第十九条","txt":"公共场所经营者应当按照卫生标准、规范的要求对公共场所的空气、微小气候、水质、采光、照明、噪声、顾客用品用具等进行卫生检测，检测每年不得少于一次；检测结果不符合卫生标准、规范要求的应当及时整改。 公共场所经营者不具备检测能力的，可以委托检测。 公共场所经营者应当在醒目位置如实公示检测结果，并对其卫生检测的真实性负责，依法依规承担相应后果。"},{"i":20,"n":"第二十条","txt":"公共场所经营者应当制定公共场所危害健康事故应急预案或者方案，定期检查公共场所各项卫生制度、措施的落实情况，及时消除危害公众健康的隐患。"},{"i":21,"n":"第二十一条","txt":"公共场所发生危害健康事故的，经营者应当立即处置，防止危害扩大，并及时向县级人民政府卫生计生行政部门报告。 任何单位或者个人对危害健康事故不得隐瞒、缓报、谎报或者授意他人隐瞒、缓报、谎报。"},{"i":22,"n":"第二十二条","txt":"国家对除公园、体育场馆、公共交通工具外的公共场所实行卫生许可证管理。 公共场所经营者取得工商行政管理部门颁发的营业执照后，还应当按照规定向县级以上地方人民政府卫生计生行政部门申请卫生许可证，方可营业。 公共场所卫生监督的具体范围由省、自治区、直辖市人民政府卫生计生行政部门公布。"},{"i":23,"n":"第二十三条","txt":"公共场所经营者申请卫生许可证的，应当提交下列资料： （一）卫生许可证申请表； （二）法定代表人或者负责人身份证明； （三）公共场所地址方位示意图、平面图和卫生设施平面布局图； （四）公共场所卫生检测或者评价报告； （五）公共场所卫生管理制度； （六）省、自治区、直辖市卫生计生行政部门要求提供的其他材料。 使用集中空调通风系统的，还应当提供集中空调通风系统卫生检测或者评价报告。"},{"i":24,"n":"第二十四条","txt":"县级以上地方人民政府卫生计生行政部门应当自受理公共场所卫生许可申请之日起20日内，对申报资料进行审查，对现场进行审核，符合规定条件的，作出准予公共场所卫生许可的决定；对不符合规定条件的，作出不予行政许可的决定并书面说明理由。"},{"i":25,"n":"第二十五条","txt":"公共场所卫生许可证应当载明编号、单位名称、法定代表人或者负责人、经营项目、经营场所地址、发证机关、发证时间、有效期限。 公共场所卫生许可证有效期为四年。 公共场所卫生许可证应当在经营场所醒目位置公示。"},{"i":26,"n":"第二十六条","txt":"公共场所进行新建、改建、扩建的，应当符合有关卫生标准和要求，经营者应当按照有关规定办理预防性卫生审查手续。 预防性卫生审查程序和具体要求由省、自治区、直辖市人民政府卫生计生行政部门制定。"},{"i":27,"n":"第二十七条","txt":"公共场所经营者变更单位名称、法定代表人或者负责人的，应当向原发证卫生计生行政部门办理变更手续。 公共场所经营者变更经营项目、经营场所地址的，应当向县级以上地方人民政府卫生计生行政部门重新申请卫生许可证。 公共场所经营者需要延续卫生许可证的，应当在卫生许可证有效期届满30日前，向原发证卫生计生行政部门提出申请。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府卫生计生行政部门应当组织对公共场所的健康危害因素进行监测、分析，为制定法律法规、卫生标准和实施监督管理提供科学依据。 县级以上疾病预防控制机构应当承担卫生计生行政部门下达的公共场所健康危害因素监测任务。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府卫生计生行政部门应当对公共场所卫生监督实施量化分级管理，促进公共场所自身卫生管理，增强卫生监督信息透明度。"},{"i":30,"n":"第三十条","txt":"县级以上地方人民政府卫生计生行政部门应当根据卫生监督量化评价的结果确定公共场所的卫生信誉度等级和日常监督频次。 公共场所卫生信誉度等级应当在公共场所醒目位置公示。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府卫生计生行政部门对公共场所进行监督检查，应当依据有关卫生标准和要求，采取现场卫生监测、采样、查阅和复制文件、询问等方法，有关单位和个人不得拒绝或者隐瞒。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府卫生计生行政部门应当加强公共场所卫生监督抽检，并将抽检结果向社会公布。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府卫生计生行政部门对发生危害健康事故的公共场所，可以依法采取封闭场所、封存相关物品等临时控制措施。 经检验，属于被污染的场所、物品，应当进行消毒或者销毁；对未被污染的场所、物品或者经消毒后可以使用的物品，应当解除控制措施。"},{"i":34,"n":"第三十四条","txt":"开展公共场所卫生检验、检测、评价等业务的技术服务机构，应当具有相应专业技术能力，按照有关卫生标准、规范的要求开展工作，不得出具虚假检验、检测、评价等报告。"},{"i":35,"n":"第三十五条","txt":"对未依法取得公共场所卫生许可证擅自营业的，由县级以上地方人民政府卫生计生行政部门责令限期改正，给予警告，并处以五百元以上五千元以下罚款；有下列情形之一的，处以五千元以上三万元以下罚款： （一）擅自营业曾受过卫生计生行政部门处罚的； （二）擅自营业时间在三个月以上的； （三）以涂改、转让、倒卖、伪造的卫生许可证擅自营业的。 对涂改、转让、倒卖有效卫生许可证的，由原发证的卫生计生行政部门予以注销。"},{"i":36,"n":"第三十六条","txt":"公共场所经营者有下列情形之一的，由县级以上地方人民政府卫生计生行政部门责令限期改正，给予警告，并可处以二千元以下罚款；逾期不改正，造成公共场所卫生质量不符合卫生标准和要求的，处以二千元以上二万元以下罚款；情节严重的，可以依法责令停业整顿，直至吊销卫生许可证： （一）未按照规定对公共场所的空气、微小气候、水质、采光、照明、噪声、顾客用品用具等进行卫生检测的； （二）未按照规定对顾客用品用具进行清洗、消毒、保洁，或者重复使用一次性用品用具的。"},{"i":37,"n":"第三十七条","txt":"公共场所经营者有下列情形之一的，由县级以上地方人民政府卫生计生行政部门责令限期改正；逾期不改的，给予警告，并处以一千元以上一万元以下罚款；对拒绝监督的，处以一万元以上三万元以下罚款；情节严重的，可以依法责令停业整顿，直至吊销卫生许可证： （一）未按照规定建立卫生管理制度、设立卫生管理部门或者配备专（兼）职卫生管理人员，或者未建立卫生管理档案的； （二）未按照规定组织从业人员进行相关卫生法律知识和公共场所卫生知识培训，或者安排未经相关卫生法律知识和公共场所卫生知识培训考核的从业人员上岗的； （三）未按照规定设置与其经营规模、项目相适应的清洗、消毒、保洁、盥洗等设施设备和公共卫生间，或者擅自停止使用、拆除上述设施设备，或者挪作他用的； （四）未按照规定配备预防控制鼠、蚊、蝇、蟑螂和其他病媒生物的设施设备以及废弃物存放专用设施设备，或者擅自停止使用、拆除预防控制鼠、蚊、蝇、蟑螂和其他病媒生物"},{"i":38,"n":"第三十八条","txt":"公共场所经营者安排未获得有效健康合格证明的从业人员从事直接为顾客服务工作的，由县级以上地方人民政府卫生计生行政部门责令限期改正，给予警告，并处以五百元以上五千元以下罚款；逾期不改正的，处以五千元以上一万五千元以下罚款。"},{"i":39,"n":"第三十九条","txt":"公共场所经营者对发生的危害健康事故未立即采取处置措施，导致危害扩大，或者隐瞒、缓报、谎报的，由县级以上地方人民政府卫生计生行政部门处以五千元以上三万元以下罚款；情节严重的，可以依法责令停业整顿，直至吊销卫生许可证。构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"公共场所经营者违反其他卫生法律、行政法规规定，应当给予行政处罚的，按照有关卫生法律、行政法规规定进行处罚。"},{"i":41,"n":"第四十一条","txt":"县级以上人民政府卫生计生行政部门及其工作人员玩忽职守、滥用职权、收取贿赂的，由有关部门对单位负责人、直接负责的主管人员和其他责任人员依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"本细则下列用语的含义： 集中空调通风系统，指为使房间或者封闭空间空气温度、湿度、洁净度和气流速度等参数达到设定的要求，而对空气进行集中处理、输送、分配的所有设备、管道及附件、仪器仪表的总和。 公共场所危害健康事故，指公共场所内发生的传染病疫情或者因空气质量、水质不符合卫生标准、用品用具或者设施受到污染导致的危害公众健康事故。"},{"i":43,"n":"第四十三条","txt":"本细则自2011年5月1日起实施。卫生部1991年3月11日发布的《公共场所卫生管理条例实施细则》同时废止。"}],"yishiwaichuhuizhenguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为规范医疗机构之间医师会诊行为，促进医学交流与发展，提高医疗水平，保证医疗质量和医疗安全，方便群众就医，保护患者、医师、医疗机构的合法权益，根据《执业医师法》、《医疗机构管理条例》的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称医师外出会诊是指医师经所在医疗机构批准，为其他医疗机构特定的患者开展执业范围内的诊疗活动。 医师未经所在医疗机构批准，不得擅自外出会诊。"},{"i":3,"n":"第三条","txt":"各级卫生行政部门应当加强对医师外出会诊的监督管理。"},{"i":4,"n":"第四条","txt":"医疗机构在诊疗过程中，根据患者的病情需要或者患者要求等原因，需要邀请其他医疗机构的医师会诊时，经治科室应当向患者说明会诊、费用等情况，征得患者同意后，报本单位医务管理部门批准；当患者不具备完全民事行为能力时，应征得其近亲属或者监护人同意。"},{"i":5,"n":"第五条","txt":"邀请会诊的医疗机构（以下称邀请医疗机构）拟邀请其他医疗机构（以下称会诊医疗机构）的医师会诊，需向会诊医疗机构发出书面会诊邀请函。内容应当包括拟会诊患者病历摘要、拟邀请医师或者邀请医师的专业及技术职务任职资格、会诊的目的、理由、时间和费用等情况，并加盖邀请医疗机构公章。 用电话或者电子邮件等方式提出会诊邀请的，应当及时补办书面手续。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，医疗机构不得提出会诊邀请： （一）会诊邀请超出本单位诊疗科目或者本单位不具备相应资质的； （二）本单位的技术力量、设备、设施不能为会诊提供必要的医疗安全保障的； （三）会诊邀请超出被邀请医师执业范围的； （四）省级卫生行政部门规定的其他情形。"},{"i":7,"n":"第七条","txt":"会诊医疗机构接到会诊邀请后，在不影响本单位正常业务工作和医疗安全的前提下，医务管理部门应当及时安排医师外出会诊。会诊影响本单位正常业务工作但存在特殊需要的情况下，应当经会诊医疗机构负责人批准。"},{"i":8,"n":"第八条","txt":"有下列情形之一的，医疗机构不得派出医师外出会诊： （一）会诊邀请超出本单位诊疗科目或者本单位不具备相应资质的； （二）会诊邀请超出被邀请医师执业范围的； （三）邀请医疗机构不具备相应医疗救治条件的； （四）省级卫生行政部门规定的其他情形。"},{"i":9,"n":"第九条","txt":"会诊医疗机构不能派出会诊医师时，应当及时告知邀请医疗机构。"},{"i":10,"n":"第十条","txt":"医师接受会诊任务后，应当详细了解患者的病情，亲自诊查患者，完成相应的会诊工作，并按照规定书写医疗文书。"},{"i":11,"n":"第十一条","txt":"医师在会诊过程中应当严格执行有关的卫生管理法律、法规、规章和诊疗规范、常规。"},{"i":12,"n":"第十二条","txt":"医师在会诊过程中发现难以胜任会诊工作，应当及时、如实告知邀请医疗机构，并终止会诊。 医师在会诊过程中发现邀请医疗机构的技术力量、设备、设施条件不适宜收治该患者，或者难以保障会诊质量和安全的，应当建议将该患者转往其他具备收治条件的医疗机构诊治。"},{"i":13,"n":"第十三条","txt":"会诊结束后，邀请医疗机构应当将会诊情况通报会诊医疗机构。医师应当在返回本单位2个工作日内将外出会诊的有关情况报告所在科室负责人和医务管理部门。"},{"i":14,"n":"第十四条","txt":"医师在外出会诊过程中发生的医疗事故争议，由邀请医疗机构按照《医疗事故处理条例》的规定进行处理。必要时，会诊医疗机构应当协助处理。"},{"i":15,"n":"第十五条","txt":"会诊中涉及的会诊费用按照邀请医疗机构所在地的规定执行。差旅费按照实际发生额结算，不得重复收费。属医疗机构根据诊疗需要邀请的，差旅费由医疗机构承担；属患者主动要求邀请的，差旅费由患者承担，收费方应向患者提供正式收费票据。会诊中涉及的治疗、手术等收费标准可在当地规定的基础上酌情加收，加收幅度由省级价格主管部门会同同级卫生行政部门确定。 邀请医疗机构支付会诊费用应当统一支付给会诊医疗机构，不得支付给会诊医师本人。会诊医疗机构由于会诊产生的收入，应纳入单位财务部门统一核算。"},{"i":16,"n":"第十六条","txt":"会诊医疗机构应当按照有关规定给付会诊医师合理报酬。医师在国家法定节假日完成会诊任务的，会诊医疗机构应当按照国家有关规定提高会诊医师的报酬标准。"},{"i":17,"n":"第十七条","txt":"医师在外出会诊时不得违反规定接受邀请医疗机构报酬，不得收受或者索要患者及其家属的钱物，不得牟取其他不正当利益。"},{"i":18,"n":"第十八条","txt":"医疗机构应当加强对本单位医师外出会诊的管理，建立医师外出会诊管理档案，并将医师外出会诊情况与其年度考核相结合。"},{"i":19,"n":"第十九条","txt":"医疗机构违反本规定第六条、第八条、第十五条的，由县级以上卫生行政部门责令改正，给予警告；诊疗活动超出登记范围的，按照《医疗机构管理条例》第四十七条处理。"},{"i":20,"n":"第二十条","txt":"医师违反第二条、第七条规定擅自外出会诊或者在会诊中违反第十七条规定的，由所在医疗机构记入医师考核档案；经教育仍不改正的，依法给予行政处分或者纪律处分。 医师外出会诊违反《执业医师法》有关规定的，按照《执业医师法》第三十七条处理。"},{"i":21,"n":"第二十一条","txt":"医疗机构疏于对本单位医师外出会诊管理的，县级以上卫生行政部门应当对医疗机构及其主要负责人和负有责任的主管人员进行通报批评。"},{"i":22,"n":"第二十二条","txt":"医师受卫生行政部门调遣到其他医疗机构开展诊疗活动的，不适用本规定。"},{"i":23,"n":"第二十三条","txt":"本规定自2005年7月1日起施行。"}],"yishizhiyezhuceguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范医师执业活动，加强医师队伍管理，根据《中华人民共和国执业医师法》，制定本办法。"},{"i":2,"n":"第二条","txt":"医师执业应当经注册取得《医师执业证书》。 未经注册取得《医师执业证书》者，不得从事医疗、预防、保健活动。"},{"i":3,"n":"第三条","txt":"国家卫生计生委负责全国医师执业注册监督管理工作。 县级以上地方卫生计生行政部门是医师执业注册的主管部门，负责本行政区域内的医师执业注册监督管理工作。"},{"i":4,"n":"第四条","txt":"国家建立医师管理信息系统，实行医师电子注册管理。"},{"i":5,"n":"第五条","txt":"凡取得医师资格的，均可申请医师执业注册。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，不予注册： （一）不具有完全民事行为能力的； （二）因受刑事处罚，自刑罚执行完毕之日起至申请注册之日止不满二年的； （三）受吊销《医师执业证书》行政处罚，自处罚决定之日起至申请注册之日止不满二年的； （四）甲类、乙类传染病传染期、精神疾病发病期以及身体残疾等健康状况不适宜或者不能胜任医疗、预防、保健业务工作的； （五）重新申请注册，经考核不合格的； （六）在医师资格考试中参与有组织作弊的； （七）被查实曾使用伪造医师资格或者冒名使用他人医师资格进行注册的； （八）国家卫生计生委规定不宜从事医疗、预防、保健业务的其他情形的。"},{"i":7,"n":"第七条","txt":"医师执业注册内容包括：执业地点、执业类别、执业范围。 执业地点是指执业医师执业的医疗、预防、保健机构所在地的省级行政区划和执业助理医师执业的医疗、预防、保健机构所在地的县级行政区划。 执业类别是指临床、中医（包括中医、民族医和中西医结合）、口腔、公共卫生。 执业范围是指医师在医疗、预防、保健活动中从事的与其执业能力相适应的专业。"},{"i":8,"n":"第八条","txt":"医师取得《医师执业证书》后，应当按照注册的执业地点、执业类别、执业范围，从事相应的医疗、预防、保健活动。"},{"i":9,"n":"第九条","txt":"拟在医疗、保健机构中执业的人员，应当向批准该机构执业的卫生计生行政部门申请注册；拟在预防机构中执业的人员，应当向该机构的同级卫生计生行政部门申请注册。"},{"i":10,"n":"第十条","txt":"在同一执业地点多个机构执业的医师，应当确定一个机构作为其主要执业机构，并向批准该机构执业的卫生计生行政部门申请注册；对于拟执业的其他机构，应当向批准该机构执业的卫生计生行政部门分别申请备案，注明所在执业机构的名称。 医师只有一个执业机构的，视为其主要执业机构。"},{"i":11,"n":"第十一条","txt":"医师的主要执业机构以及批准该机构执业的卫生计生行政部门应当在医师管理信息系统及时更新医师定期考核结果。"},{"i":12,"n":"第十二条","txt":"申请医师执业注册，应当提交下列材料： （一）医师执业注册申请审核表； （二）近6个月2寸白底免冠正面半身照片； （三）医疗、预防、保健机构的聘用证明； （四）省级以上卫生计生行政部门规定的其他材料。 获得医师资格后二年内未注册者、中止医师执业活动二年以上或者本办法第六条规定不予注册的情形消失的医师申请注册时，还应当提交在省级以上卫生计生行政部门指定的机构接受连续6个月以上的培训，并经考核合格的证明。"},{"i":13,"n":"第十三条","txt":"注册主管部门应当自收到注册申请之日起20个工作日内，对申请人提交的申请材料进行审核。审核合格的，予以注册并发放《医师执业证书》。"},{"i":14,"n":"第十四条","txt":"对不符合注册条件不予注册的，注册主管部门应当自收到注册申请之日起20个工作日内书面通知聘用单位和申请人，并说明理由。申请人如有异议的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":15,"n":"第十五条","txt":"执业助理医师取得执业医师资格后，继续在医疗、预防、保健机构中执业的，应当按本办法规定，申请执业医师注册。"},{"i":16,"n":"第十六条","txt":"《医师执业证书》应当由本人妥善保管，不得出借、出租、抵押、转让、涂改和毁损。如发生损坏或者遗失的，当事人应当及时向原发证部门申请补发。"},{"i":17,"n":"第十七条","txt":"医师跨执业地点增加执业机构，应当向批准该机构执业的卫生计生行政部门申请增加注册。 执业助理医师只能注册一个执业地点。"},{"i":18,"n":"第十八条","txt":"医师注册后有下列情形之一的，医师个人或者其所在的医疗、预防、保健机构，应当自知道或者应当知道之日起30日内报告注册主管部门，办理注销注册： （一）死亡或者被宣告失踪的； （二）受刑事处罚的； （三）受吊销《医师执业证书》行政处罚的； （四）医师定期考核不合格，并经培训后再次考核仍不合格的； （五）连续两个考核周期未参加医师定期考核的； （六）中止医师执业活动满二年的； （七）身体健康状况不适宜继续执业的； （八）出借、出租、抵押、转让、涂改《医师执业证书》的； （九）在医师资格考试中参与有组织作弊的； （十）本人主动申请的； （十一）国家卫生计生委规定不宜从事医疗、预防、保健业务的其他情形的。"},{"i":19,"n":"第十九条","txt":"医师注册后有下列情况之一的，其所在的医疗、预防、保健机构应当自办理相关手续之日起30日内报注册主管部门，办理备案： （一）调离、退休、退职； （二）被辞退、开除； （三）省级以上卫生计生行政部门规定的其他情形。 上述备案满2年且未继续执业的予以注销。"},{"i":20,"n":"第二十条","txt":"医师变更执业地点、执业类别、执业范围等注册事项的，应当通过国家医师管理信息系统提交医师变更执业注册申请及省级以上卫生计生行政部门规定的其他材料。 医师因参加培训需要注册或者变更注册的，应当按照本办法规定办理相关手续。 医师变更主要执业机构的，应当按本办法第十二条的规定重新办理注册。 医师承担经主要执业机构批准的卫生支援、会诊、进修、学术交流、政府交办事项等任务和参加卫生计生行政部门批准的义诊，以及在签订帮扶或者托管协议医疗机构内执业等，不需办理执业地点变更和执业机构备案手续。"},{"i":21,"n":"第二十一条","txt":"注册主管部门应当自收到变更注册申请之日起20个工作日内办理变更注册手续。对因不符合变更注册条件不予变更的，应当自收到变更注册申请之日起20个工作日内书面通知申请人，并说明理由。"},{"i":22,"n":"第二十二条","txt":"国家实行医师注册内容公开制度和查询制度。 地方各级卫生计生行政部门应当按照规定提供医师注册信息查询服务，并对注销注册的人员名单予以公告。"},{"i":23,"n":"第二十三条","txt":"医疗、预防、保健机构未按照本办法第十八条规定履行报告职责，导致严重后果的，由县级以上卫生计生行政部门依据《执业医师法》第四十一条规定进行处理。 医疗、预防、保健机构未按照本办法第十九条规定履行报告职责，导致严重后果的，由县级以上地方卫生计生行政部门对该机构给予警告，并对其主要负责人、相关责任人依法给予处分。"},{"i":24,"n":"第二十四条","txt":"中医（包括中医、民族医、中西医结合）医师执业注册管理由中医（药）主管部门负责。"},{"i":25,"n":"第二十五条","txt":"港澳台人员申请在内地（大陆）注册执业的，按照国家有关规定办理。 外籍人员申请在中国境内注册执业的，按照国家有关规定办理。"},{"i":26,"n":"第二十六条","txt":"本办法自2017年4月1日起施行。1999年7月16日原卫生部公布的《医师执业注册暂行办法》同时废止。"}],"yishizigekaoshizanxingbanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国执业医师法》（以下简称《执业医师法》）第八条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"医师资格考试是评价申请医师资格者是否具备执业所必须的专业知识与技能的考试。"},{"i":3,"n":"第三条","txt":"医师资格考试分为执业医师资格考试和执业助理医师资格考试。考试类别分为临床、中医（包括中医、民族医、中西医结合）、口腔、公共卫生四类。考试方式分为实践技能考试和医学综合笔试。 医师资格考试方式的具体内容和方案由卫生部医师资格考试委员会制定。"},{"i":4,"n":"第四条","txt":"医师资格考试实行国家统一考试，每年举行一次。考试时间由卫生部医师资格考试委员会确定，提前3个月向社会公告。"},{"i":5,"n":"第五条","txt":"卫生部医师资格考试委员会，负责全国医师资格考试工作。委员会下设办公室和专门委员会。 各省、自治区、直辖市卫生行政部门牵头成立医师资格考试领导小组，负责本辖区的医师资格考试工作。领导小组组长由省级卫生行政部门的主要领导兼任。"},{"i":6,"n":"第六条","txt":"医师资格考试考务管理实行国家医学考试中心、考区、考点三级分别责任制。"},{"i":7,"n":"第七条","txt":"国家医学考试中心在卫生部和卫生部医师资格考试委员会领导下，具体负责医师资格考试的技术性工作，其职责是： （一）组织拟定考试大纲和命题组卷的有关具体工作； （二）组织制订考务管理规定； （三）承担考生报名信息处理、制卷、发送试卷、回收答题卡等考务工作； （四）组织评定考试成绩，提供考生成绩单； （五）提交考试结果统计分析报告； （六）向卫生部和卫生部医师资格考试委员会报告考试工作； （七）指导考区办公室和考点办公室的业务工作； （八）承担命题专家的培训工作； （九）其他。"},{"i":8,"n":"第八条","txt":"各省、自治区、直辖市为考区，考区主任由省级卫生行政部门主管领导兼任。 考区的基本情况和人员组成报卫生部医师资格考试委员会备案。 考区设办公室，其职责是： （一）制定本地区医师考试考务管理具体措施； （二）负责本地区的医师资格考试考务管理； （三）指导各考点办公室的工作； （四）接收或转发报名信息、试卷、答题卡、成绩单等考试资料；向国家医学考试中心寄送报名信息、答题卡等考试资料； （五）复核考生报名资格； （六）处理、上报考试期间本考区发生的重大问题； （七）其他。"},{"i":9,"n":"第九条","txt":"考区根据考生情况设置考点，报卫生部医师资格考试委员会备案。考点应设在地或设区的市。考点设主考一人，由地或设区的市级卫生行政部门主管领导兼作。 考点设置应符合考点设置标准。 考点设办公室，其职责是： （一）负责本地区医师资格考试考务工作； （二）受理考生报名，核实考生提供的报名材料，审核考生报名资格； （三）指导考生填写报名信息表，按统一要求处理考生信息； （四）收取考试费； （五）核发《准考证》； （六）安排考场，组织培训监考人员； （七）负责接收本考点的试卷、答题卡，负责考试前的机要存放； （八）组织实施考试； （九）考试结束后清点试卷、答题卡，寄送答题卡并销毁试卷； （十）分发成绩单并受理成绩查询； （十一）处理、上报考虑期间本考点发生的问题； （十二）其他。"},{"i":10,"n":"第十条","txt":"各级考试管理部门和机构要有计划地逐级培训考务工作人员。"},{"i":11,"n":"第十一条","txt":"凡符合《执业医师法》第九条所列条件的，可以申请参加执业医师资格考试。 在1998年6月26日前获得医士专业职务任职资格，后又取得执业助理医师资格的，医士从业时间和取得执业助理医师执业证书后执业时间累计满五年的，可以申请参加执业医师资格考试。 高等学校医学专业本科以上学历是指国务院教育行政部门认可的各类高等学校医学专业本科以上的学历。"},{"i":12,"n":"第十二条","txt":"凡符合《执业医师法》第十条所列条件的，可以申请参加执业助理医师资格考试。 高等学校医学专科学历是指省级以上教育行政部门认可的各类高等学校医学专业专科学历；中等专业学校医学专业学历是指经省级以上教育行政部门认可的各类中等专业学校医学专业中专学历。"},{"i":13,"n":"第十三条","txt":"申请参加医师资格考试的人员，应当在公告规定期限内，到户籍所在地的考点办公室报名，并提交下列材料： （一）二寸免冠正面半身照片两张； （二）本人身份证明； （三）毕业证书复印件； （四）试用机构出具的证明期满一年并考核合格的证明； （五）执业助理医师申报执业医师资格考试的，还应当提交《医师资格证书》复印件、《医师执业证书》复印件、执业时间和考核合格证明； （六）报考所需的其他材料。 试用机构与户籍所在地跨省分离的，由试用机构推荐，可在试用机构所在地报名参加考试。"},{"i":14,"n":"第十四条","txt":"经审查，符合报考条件，由考点发放《准考证》。"},{"i":15,"n":"第十五条","txt":"考生报名后不参加考试的，取消本次考试资格。"},{"i":16,"n":"第十六条","txt":"在卫生部医师资格考试委员会的领导下，国家医学考试中心和国家中医管理局中医师资格认证中心依据实践技能考试大纲，统一命制实践技能考试试题，向考区提供试卷、计算机化考试软件、考生评分册等考试材料。省级医师资格考试领导小组负责组织实施实践技能考试。"},{"i":17,"n":"第十七条","txt":"已经取得执业助理医师执业证书，报考执业医师资格的，应报名参加相应类别执业医师资格考试的实践技能考试。"},{"i":18,"n":"第十八条","txt":"经省级医师资格考试领导小组批准的，符合《医疗机构基本标准》二级以上医院（中医、民族医、中西医结合医院除外）、妇幼保健院，急救中心标准的机构，承担对本机构聘用的申请报考临床类别人员的实践技能考试。 除前款规定的人员外，其他人员应根据考点办公室的统一安排，到省级医师资格考试领导小组指定的地或设区的市级以上医疗、预防、保健机构或组织参加实践技能考试。该机构或组织应当在考生医学综合笔试考点所在地。"},{"i":19,"n":"第十九条","txt":"承担实践技能考试的考官应具备下列条件： （一）取得主治医师以上专业技术职务任职资格满三年； （二）具有一年以上培训医师或指导医学专业学生实习的工作经历； （三）经省级医师资格考试领导小组进行考试相关业务知识的培训，考试成绩合格，并由省级医师资格考试领导小组颁发实践技能考试考官聘任证书。 实践技能考试考官的聘用任期为二年。"},{"i":20,"n":"第二十条","txt":"承担实践技能考试的机构或组织内设若干考试小组。每个考试小组由三人以上单数考官组成。其中一名为主考官。主考官应具有副主任医师以上专业技术职务任职资格，并经承担实践技能考试机构或组织的主要负责人推荐，报考点办公室审核，由考点主考批准。"},{"i":21,"n":"第二十一条","txt":"考官有下列情形之一的，必须自行回避；应试者也有权以口头或者书面方式申请回避： （一）是应试者的近亲属； （二）与应试者有利害关系； （三）与应试者有其他关系，可能影响考试公正的。 前款规定适用于组织考试的工作人员。"},{"i":22,"n":"第二十二条","txt":"实践技能考试机构或组织应对应试者所提交的试用期一年的实践材料进行认真审核。"},{"i":23,"n":"第二十三条","txt":"考试小组进行评议时，如果意见分歧，应当少数服从多数，并由主考官签署考试结果。但是少数人的意见应当写入笔录。评议笔录由考试小组的全体考官签名。"},{"i":24,"n":"第二十四条","txt":"省级医师资格考试领导小组要加强对承担实践技能考试工作的机构或组织的检查、指导、监督和评价。"},{"i":25,"n":"第二十五条","txt":"本办法第十八条第一款规定的机构，应当将考生考试结果及有关资料报考点办公室审核。考点办公室应在医学综合笔试考试日期15日前将考生实践技能考试结果通知考生，并对考试合格的，发给由主考签发的实践技能考试合格证明。 本办法第十八条第二款规定的机构或组织应于考试结束后将考生考试结果及有关资料报考点办公室审核，由考点办公室将考试结果通知考生，对考试合格的，发给由主考签发的实践技能考试合格证明。具体上报和通知考生时间由省级卫生行政部门规定。 实践技能考试合格者方可参加医学综合笔试。"},{"i":26,"n":"第二十六条","txt":"实践技能考试合格的考生应持实践技能考试合格证明参加医学综合笔试。"},{"i":27,"n":"第二十七条","txt":"医师资格考试试卷（包括备用卷）和标准答案，启用前应当严格保密；使用后的试卷应予销毁。"},{"i":28,"n":"第二十八条","txt":"国家医学考试中心向考区提供医学综合笔试试卷和答题卡、各考区成绩册、考生成绩单及考试统计分析结果。考点在考区的领导监督下组织实施考试。"},{"i":29,"n":"第二十九条","txt":"考试中心、考区、考点工作人员及命题人员，如有直系亲属参加当年医师资格考试的，应实行回避。"},{"i":30,"n":"第三十条","txt":"医师资格考试结束后，考区应当立即将考试情况报告卫生部医师资格考试委员会。"},{"i":31,"n":"第三十一条","txt":"医师资格考试的合格线由卫生部医师资格考试委员会确定，并向社会公告。"},{"i":32,"n":"第三十二条","txt":"考生成绩单由考点发给考生。考生成绩在未正式公布前，应当严格保密。"},{"i":33,"n":"第三十三条","txt":"考试成绩合格的，授予执业医师资格或执业助理医师资格，由省级卫生行政部门颁发卫生部统一印制的《医师资格证书》。 《医师资格证书》是执业医师资格或执业助理医师资格的证明文件。"},{"i":34,"n":"第三十四条","txt":"违反本办法，考生有下列情形之一的，县级以上卫生行政部门视情节，给予警告、通报批评、终止考试、取消单元考试资格、取消当年考试资格和考试成绩并取消自下一年度起两年内参加医师资格考试资格的处罚或行政处分；构成犯罪的，依法追究刑事责任： （一）违反考场纪律、影响考场秩序； （二）传抄、夹带、偷换试卷； （三）假报姓名、年龄、学历、工龄、民族、身份证明、学籍等； （四）伪造有关资料，弄虚作假； （五）其他严重舞弊行为。 考生由他人代考，取消当年考试资格和考试成绩并取消自下一年度起两年内参加医师资格考试的资格。代他人参加医师资格考试的经执业注册的医师，应认定为医师定期考核不合格，按《执业医师法》第三十一条处理；代他人参加医师资格考试的其他人员，移交相关部门处理。 对以各种欺骗手段取得《医师资格证书》者，应收回其《医师资格证书》，自下一年度起两年内不予受理其报名参加医师资格考试的申请。"},{"i":35,"n":"第三十五条","txt":"考试工作人员违反本办法，有下列情形之一的，由县级以上卫生行政部门给予警告或取消考试工作人员资格，考试工作人员所在单位可以给予记过、记大过、降级、降职、撤职、开除等处分；构成犯罪的，依法追究刑事责任： （一）监考中不履行职责； （二）在阅卷评分中错评、漏评、差错较多，经指出仍不改正的； （三）泄漏阅卷评分工作情况； （四）利用工作之便，为考生舞弊提供条件或者谋取私利； （五）其他严重违纪行为。"},{"i":36,"n":"第三十六条","txt":"考点有下列情况之一，造成较大影响的，取消考点资格，并追究考点负责人的责任： （一）考点考务工作管理混乱，出现严重差错的； （二）所属考场秩序混乱、出现大面积舞弊、抄袭现象的； （三）发生试卷泄密、损毁、丢失的； （四）其他影响考试的行为。 考场、考点发生考试纪律混乱、有组织的舞弊，相应范围内考试无效。"},{"i":37,"n":"第三十七条","txt":"卫生行政部门工作人员违反本办法有关规定，在考试中弄虚作假、玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"为申请参加实践技能考试的考生出具伪证的，依法追究直接责任者的法律责任。执业医师出具伪证的，注销注册，吊销其《医师执业证书》。对出具伪证的机构主要负责人视情节予以降职、撤职等处分；构成犯罪的，依法追究刑事责任。 省级医师资格考试领导小组对违反有关规定的承担实践技能考试机构或组织责令限期整改；情节严重的，取消承担实践技能考试机构或组织的资格，五年内不得再次申请承担实践技能考试指定机构或组织。"},{"i":39,"n":"第三十九条","txt":"省级卫生行政部门可根据本办法制定具体规定，并报卫生部备案。"},{"i":40,"n":"第四十条","txt":"国家和省级中医药主管部门分别在卫生部医师资格考试委员会和省级医师资格考试领导小组统一安排下，参与组织中医（包括中医、民族医、中西医结合）医师资格考试中的有关技术性工作、考生资格审核、实践技能考试等。"},{"i":41,"n":"第四十一条","txt":"本办法所称医疗机构是指符合《医疗机构管理条例》第二条和《医疗机构管理条例实施细则》第二条和第三条规定的机构；社区卫生服务机构和采供血机构适用《医疗机构管理条例实施细则》第三条第十二项的规定；预防机构是指《传染病防治法实施办法》第七十三条规定的机构。"},{"i":42,"n":"第四十二条","txt":"计划生育技术服务机构中的人员适用本办法的规定。"},{"i":43,"n":"第四十三条","txt":"本办法由卫生部解释。"},{"i":44,"n":"第四十四条","txt":"本办法自颁布之日起施行。"}],"yishizigekaoshiweijiweiguichuliguiding":[{"i":1,"n":"第一条","txt":"为加强医师资格考试工作的管理，规范医师资格考试违纪违规行为的认定与处理，保障考试公平、公正，维护考生和考试工作人员的合法权益，根据《中华人民共和国执业医师法》（以下简称《执业医师法》）及相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在医师资格考试中对考生、命审题人员、考试工作人员、其他相关人员及考点违纪违规行为的认定和处理。"},{"i":3,"n":"第三条","txt":"对考试违纪违规行为的认定与处理，应当做到事实清楚、证据确凿、程序规范、适用规定准确。"},{"i":4,"n":"第四条","txt":"国家卫生计生委负责全国医师资格考试违纪违规行为认定和处理的监督管理。 设区的市级以上地方卫生计生行政部门负责本辖区医师资格考试违纪违规行为的认定、处理和监督管理。 国家医学考试中心在国家卫生计生委的领导下，负责全国医师资格考试结果的分析和管理，违纪违规行为认定、处理的指导和信息管理，并向国家卫生计生委报告全国医师资格考试违纪违规处理工作的相关情况。 国家中医药管理局中医师资格认证中心（以下简称中医师资格认证中心）根据职责分工负责相关工作。 考区、考点的考试机构在同级卫生计生行政部门领导下，分别负责本辖区考试违纪违规行为认定、处理等相关工作的具体实施。"},{"i":5,"n":"第五条","txt":"考生有下列行为之一的，当年该单元或者考站考试成绩无效： （一）考试开始信号发出后，在规定之外位置就座并参加考试的； （二）进入考室时，经提醒仍未按要求将规定物品放在指定位置的； （三）考试开始信号发出前答题或者考试结束信号发出后继续答题，经提醒仍不改正的； （四）未按要求使用考试规定用笔或者纸答题，经提醒仍不改正的； （五）未按要求在试卷、答卷（含答题卡，下同）上正确书写本人信息、填涂答题信息或者标记其他信息，经提醒仍不改正的； （六）考试开始30分钟内，经提醒仍不在答卷上填写本人信息的； （七）在考试过程中，旁窥、交头接耳、互打暗号或者手势，经提醒仍不改正的； （八）未经考试工作人员同意，在考试过程中擅自离开座位或者考室的； （九）拒绝、妨碍考试工作人员履行管理职责的； （十）在考室或者考场禁止的范围内，喧哗、吸烟或者实施其他影响考试秩序的行为，经劝阻仍不改正的； （十一）同一考室、"},{"i":6,"n":"第六条","txt":"考生有下列行为之一的，当年考试成绩无效： （一）考试开始信号发出后，被查出携带记载医学内容的材料的； （二）抄袭或者协助他人抄袭试题答案或者考试内容相关资料的； （三）将试卷、答卷或者涉及试题的作答信息材料带出考室的； （四）故意损毁试卷、答卷或者考试设备、材料的； （五）省级以上卫生计生行政部门规定的其他较为严重的违纪违规行为。"},{"i":7,"n":"第七条","txt":"考生有下列行为之一的,当年考试成绩无效，在2年内不得报考医师资格： （一）考试开始信号发出后，被查出携带电子作弊工具的； （二）抢夺、窃取他人试卷、答卷或者强迫他人为自己抄袭提供方便的； （三）在考场警戒线范围内交接或者交换试卷、答卷等考试相关材料的； （四）拒不服从考试工作人员管理，故意扰乱考场、评卷场所等考试工作秩序的； （五）与考试工作人员串通作弊的； （六）威胁、侮辱、殴打考试工作人员的； （七）利用伪造证件、证明及其他虚假材料报名的； （八）填写他人考试识别信息或者试卷标识信息的； （九）省级以上卫生计生行政部门规定的其他严重违纪违规行为。"},{"i":8,"n":"第八条","txt":"考生有下列行为之一的,认定为参与有组织作弊，当年考试成绩无效，终身不得报考医师资格： （一）由他人代替参加考试的； （二）在考场警戒线范围内对外进行通讯、传递、发送或者接收试卷内容或者答案的； （三）散布谣言，扰乱考试环境，造成严重不良社会影响的； （四）考前非法获取、持有、使用、传播试题或者答案的； （五）省级以上卫生计生行政部门规定的其他有组织作弊行为。"},{"i":9,"n":"第九条","txt":"考试结束后发现并认定考生有违纪违规行为的，依照本规定进行处理。"},{"i":10,"n":"第十条","txt":"考生通过违纪违规行为获得考试成绩并取得医师资格证书、医师执业证书的，由发放证书的卫生计生行政部门依据有关法律法规进行处理，撤销并收回医师资格证书、医师执业证书，并进行通报。 在校医学生、在职教师参与有组织作弊，由卫生计生行政部门将有关情况通报其所在学校，由其所在学校根据有关规定进行处理。在校医学生参与有组织作弊情节严重的，终身不得报考医师资格。 医师参与有组织作弊，已经取得医师资格但尚未注册的，卫生计生行政部门将不予注册；已经注册取得医师执业证书的，由注册的卫生计生行政部门依法注销其执业注册，收回医师执业证书，并不再予以注册。有其他违纪违规行为的，卫生计生行政部门应当依法进行处理。卫生计生行政部门对医师的处理情况应当及时通报其所在单位。 除考生外的其他人员参与有组织作弊的，卫生计生行政部门应当向有关部门或者单位通报，并建议给予其相应处分。"},{"i":11,"n":"第十一条","txt":"命审题人员应当具有良好的政治素质和品行，具有胜任命审题及涉密岗位所要求的工作能力。 命审题人员应当履行以下保密义务： （一）遵守国家保密法律法规及其他相关规定，不得以任何方式泄露属国家秘密的医师资格考试试卷、试题内容; （二）凡有直系亲属、利害关系人参加当年考试的，应当主动回避，不得参加当年命审题和组卷工作; （三）应当接受保密教育和培训，签订《保密责任承诺书》; （四）不得参与和考试有关的应试培训工作。"},{"i":12,"n":"第十二条","txt":"命审题人员有下列行为之一的，国家医学考试中心或者中医师资格认证中心应当停止其参加命审题工作，视情节轻重作出或者建议其所在单位给予相应处分，并调离命审题工作岗位： （一）非法获取、持有国家秘密载体的； （二）买卖、转送或者私自销毁国家秘密载体的； （三）通过普通邮政、快递等无保密措施的渠道传递国家秘密载体的； （四）邮寄、托运国家秘密载体出境，或者未经有关主管部门批准，携带、传递国家秘密载体出境的； （五）非法复制、记录、存储国家秘密的； （六）在私人交往和通信中泄露国家秘密的； （七）在互联网及其他公共信息网络或者未采取保密措施的有线和无线通信中传递国家秘密的； （八）将涉密计算机、涉密存储设备接入互联网及其他公共信息网络的； （九）在涉密信息系统与互联网及其他公共信息网络之间进行信息交换的； （十）使用非涉密计算机、非涉密存储设备存储、处理国家秘密信息的； （十一）擅自卸载、修改涉密"},{"i":13,"n":"第十三条","txt":"考试工作人员应当认真履行工作职责。在考试考务管理工作中，有下列行为之一的，考试机构应当停止其参加考试工作，视情节轻重作出或者建议其所在单位给予相应的处分，并调离考试工作单位或者岗位： （一）为考生或者考试工作人员提供虚假证明、证件，或者违规修改考生档案（含电子档案）的； （二）擅自变更考试时间、地点或者考试安排的； （三）因工作失误，导致辖区内部分考生未能如期参加考试，并造成恶劣社会影响的； （四）通过提示或者暗示帮助考生答题的； （五）擅自将试题、答卷以及与考试内容相关的材料带出考室或者传递给他人的； （六）偷换、涂改考生答卷、考试成绩或者考场原始记录材料的； （七）未按照规定保管、使用、销毁考试材料的； （八）未认真履行职责，造成所负责标准考室的雷同率达到60%的； （九）评阅卷人员造成卷面成绩明显错误，成绩错误试卷数量占其评卷总量1%以上的； （十）与考生或者其他人员串通，在考试"},{"i":14,"n":"第十四条","txt":"考点的考试工作人员严重不负责任，造成考试组织管理混乱、违纪违规现象突出的，由卫生计生行政部门进行通报批评，并给予警告。 考点违纪违规现象严重，影响恶劣的，由省级卫生计生行政部门取消该考点承办考试的资格，责令整改，在2年内不得承办考试工作，并追究相关管理人员的责任。"},{"i":15,"n":"第十五条","txt":"除考试工作人员外，其他有关人员有干扰考试行为的，卫生计生行政部门或者考试机构应当建议有关单位给予相应行政处分。"},{"i":16,"n":"第十六条","txt":"考试工作人员对考试过程中发现的违纪违规行为应当及时予以纠正，并采取必要措施收集、保全违纪违规证据。 对考试过程中发现的违纪违规行为，应当由2名以上考试工作人员共同填写全国统一样式的《医师资格考试违纪违规行为记录单》。记录单内容包括：违纪违规事实、情节及现场处理情况。记录单填写完成并经考试工作人员签字后，应当及时报考点主考签字认定。考试工作人员应当如实将记录内容和拟处理意见告知被处理人。 对事实清楚、证据确凿的违纪违规行为，卫生计生行政部门应当及时作出处理决定，出具全国统一样式的《医师资格考试违纪违规行为处理决定书》，并按要求及时送达被处理人或者其所在单位。"},{"i":17,"n":"第十七条","txt":"考点考试机构负责汇总考点各考场违纪违规情况，并及时报送考点所在地设区的市级卫生计生行政部门。"},{"i":18,"n":"第十八条","txt":"违纪违规考生的处理决定由设区的市级卫生计生行政部门作出。除当年单元或者考站考试成绩无效、当年考试成绩无效的处理决定外，设区的市级卫生计生行政部门作出其他处理决定后，应当自处理决定作出之日起15日内报省级卫生计生行政部门备案。对发现的不当处理决定，省级卫生计生行政部门应当自收到备案材料之日起30日内进行调查、纠正，也可以要求设区的市级卫生计生行政部门重新调查处理。"},{"i":19,"n":"第十九条","txt":"设区的市级以上地方卫生计生行政部门应当加强对考点、考场的监督管理，有第十三条、第十四条所列情形且情节严重的，可以直接介入调查和处理，并将有关情况及时上报国家卫生计生委，同时抄送国家医学考试中心或者中医师资格认证中心。"},{"i":20,"n":"第二十条","txt":"命审题人员、考试工作人员在试题命制、考场、考点及评卷过程中有违反本规定行为的，国家医学考试中心或者中医师资格认证中心负责人、考点主考、评卷负责人应当暂停其工作，并依照本规定报卫生计生行政部门处理。"},{"i":21,"n":"第二十一条","txt":"卫生计生行政部门作出处理决定时，应当将拟作出的处理决定及时告知被处理人。 被处理人对卫生计生行政部门认定的违纪违规事实或者拟作出的处理决定存在异议的，有权进行陈述和申辩。 被处理人对处理决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":22,"n":"第二十二条","txt":"考区考试机构应当在省级卫生计生行政部门指导下建立国家医师资格考试考生诚信档案，记录、保留并向国家医学考试中心提供在医师资格考试中违纪违规考生的相关信息。 考区考试机构应当汇总本辖区考试违纪违规行为的认定和处理情况，分别报送至省级卫生计生行政部门和国家医学考试中心，由国家医学考试中心纳入考生个人信息库进行管理。"},{"i":23,"n":"第二十三条","txt":"考生、命审题人员、考试工作人员和其他相关人员违反本规定构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"本规定中下列用语的含义： 当年考试，是指考生当年从报名参加医师资格考试至考试所有测试内容完成的全过程。 考站或者考试单元，是指进行实践技能考试或者医学综合笔试时，将考试分成的不同阶段。实践技能考试中称为考站，医学综合笔试中称为考试单元。 考生，是指根据《执业医师法》和国家卫生计生委制定的考试办法，报名参加医师资格考试的人员。 命审题人员，是指参与医师资格考试命题、审题、组卷的专家和工作人员。 考试工作人员，是指参与医师资格考试考务管理、评阅卷和考试服务工作的人员。 考试机构，是指各级卫生计生行政部门指定的负责医师资格考试考务工作的单位。 考区和考点，是指为进行医师资格考试考务管理划定的考试管理区域。考区指省、自治区、直辖市所辖区域；考点指地或者设区市所辖区域。 考场，是指医师资格考试实施的具体场所，一般指学校、医院等。 考室，是指考场内实施医师资格考试的独立区域，如教室、诊室等。"},{"i":25,"n":"第二十五条","txt":"本规定自2014年9月10日起施行。"}],"yiliaoshigujishujiandingzanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范医疗事故技术鉴定工作，确保医疗事故技术鉴定工作有序进行，依据《医疗事故处理条例》的有关规定制定本办法。"},{"i":2,"n":"第二条","txt":"医疗事故技术鉴定工作应当按照程序进行，坚持实事求是的科学态度，做到事实清楚、定性准确、责任明确。"},{"i":3,"n":"第三条","txt":"医疗事故技术鉴定分为首次鉴定和再次鉴定。 设区的市级和省、自治区、直辖市直接管辖的县（市）级地方医学会负责组织专家鉴定组进行首次医疗事故技术鉴定。 省、自治区、直辖市地方医学会负责组织医疗事故争议的再次鉴定工作。 负责组织医疗事故技术鉴定工作的医学会（以下简称医学会）可以设立医疗事故技术鉴定工作办公室，具体负责有关医疗事故技术鉴定的组织和日常工作。"},{"i":4,"n":"第四条","txt":"医学会组织专家鉴定组，依照医疗卫生管理法律、行政法规、部门规章和诊疗护理技术操作规范、常规，运用医学科学原理和专业知识，独立进行医疗事故技术鉴定。"},{"i":5,"n":"第五条","txt":"医学会应当建立专家库。专家库应当依据学科专业组名录设置学科专业组。 医学会可以根据本地区医疗工作和医疗事故技术鉴定实际，对本专家库学科专业组设立予以适当增减和调整。"},{"i":6,"n":"第六条","txt":"具备下列条件的医疗卫生专业技术人员可以成为专家库候选人： （一）有良好的业务素质和执业品德； （二）受聘于医疗卫生机构或者医学教学、科研机构并担任相应专业高级技术职务3年以上； （三）健康状况能够胜任医疗事故技术鉴定工作。 符合前款（一）、（三）项规定条件并具备高级技术职务任职资格的法医可以受聘进入专家库。 负责首次医疗事故技术鉴定工作的医学会原则上聘请本行政区域内的专家建立专家库；当本行政区域内的专家不能满足建立专家库需要时，可以聘请本省、自治区、直辖市范围内的专家进入本专家库。 负责再次医疗事故技术鉴定工作的医学会原则上聘请本省、自治区、直辖市范围内的专家建立专家库；当本省、自治区、直辖市范围内的专家不能满足建立专家库需要时，可以聘请其他省、自治区、直辖市的专家进入本专家库。"},{"i":7,"n":"第七条","txt":"医疗卫生机构或医学教学、科研机构、同级的医药卫生专业学会应当按照医学会要求，推荐专家库成员候选人；符合条件的个人经所在单位同意后也可以直接向组建专家库的医学会申请。 医学会对专家库成员候选人进行审核。审核合格的，予以聘任，并发给中华医学会统一格式的聘书。 符合条件的医疗卫生专业技术人员和法医，有义务受聘进入专家库。"},{"i":8,"n":"第八条","txt":"专家库成员聘用期为4年。在聘用期间出现下列情形之一的，应当由专家库成员所在单位及时报告医学会，医学会应根据实际情况及时进行调整。 （一）因健康原因不能胜任医疗事故技术鉴定的； （二）变更受聘单位或被解聘的； （三）不具备完全民事行为能力的； （四）受刑事处罚的； （五）省级以上卫生行政部门规定的其他情形。 聘用期满需继续聘用的，由医学会重新审核、聘用。"},{"i":9,"n":"第九条","txt":"双方当事人协商解决医疗事故争议，需进行医疗事故技术鉴定的，应共同书面委托医疗机构所在地负责首次医疗事故技术鉴定工作的医学会进行医疗事故技术鉴定。"},{"i":10,"n":"第十条","txt":"县级以上地方卫生行政部门接到医疗机构关于重大医疗过失行为的报告或者医疗事故争议当事人要求处理医疗事故争议的申请后，对需要进行医疗事故技术鉴定的，应当书面移交负责首次医疗事故技术鉴定工作的医学会组织鉴定。"},{"i":11,"n":"第十一条","txt":"协商解决医疗事故争议涉及多个医疗机构的，应当由涉及的所有医疗机构与患者共同委托其中任何一所医疗机构所在地负责组织首次医疗事故技术鉴定工作的医学会进行医疗事故技术鉴定。 医疗事故争议涉及多个医疗机构，当事人申请卫生行政部门处理的，只可以向其中一所医疗机构所在地卫生行政部门提出处理申请。"},{"i":12,"n":"第十二条","txt":"医学会应当自受理医疗事故技术鉴定之日起5日内，通知医疗事故争议双方当事人按照《医疗事故处理条例》第28条规定提交医疗事故技术鉴定所需的材料。 当事人应当自收到医学会的通知之日起10日内提交有关医疗事故技术鉴定的材料、书面陈述及答辩。 对不符合受理条件的，医学会不予受理。不予受理的，医学会应说明理由。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，医学会不予受理医疗事故技术鉴定： （一）当事人一方直接向医学会提出鉴定申请的； （二）医疗事故争议涉及多个医疗机构，其中一所医疗机构所在地的医学会已经受理的； （三）医疗事故争议已经人民法院调解达成协议或判决的； （四）当事人已向人民法院提起民事诉讼的（司法机关委托的除外）； （五）非法行医造成患者身体健康损害的； （六）卫生部规定的其他情形。"},{"i":14,"n":"第十四条","txt":"委托医学会进行医疗事故技术鉴定，应当按规定缴纳鉴定费。"},{"i":15,"n":"第十五条","txt":"双方当事人共同委托医疗事故技术鉴定的，由双方当事人协商预先缴纳鉴定费。 卫生行政部门移交进行医疗事故技术鉴定的，由提出医疗事故争议处理的当事人预先缴纳鉴定费。经鉴定属于医疗事故的，鉴定费由医疗机构支付；经鉴定不属于医疗事故的，鉴定费由提出医疗事故争议处理申请的当事人支付。 县级以上地方卫生行政部门接到医疗机构关于重大医疗过失行为的报告后，对需要移交医学会进行医疗事故技术鉴定的，鉴定费由医疗机构支付。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，医学会中止组织医疗事故技术鉴定： （一）当事人未按规定提交有关医疗事故技术鉴定材料的； （二）提供的材料不真实的； （三）拒绝缴纳鉴定费的； （四）卫生部规定的其他情形。"},{"i":17,"n":"第十七条","txt":"医学会应当根据医疗事故争议所涉及的学科专业，确定专家鉴定组的构成和人数。 专家鉴定组组成人数应为3人以上单数。 医疗事故争议涉及多学科专业的，其中主要学科专业的专家不得少于专家鉴定组成员的二分之一。"},{"i":18,"n":"第十八条","txt":"医学会应当提前通知双方当事人，在指定时间、指定地点，从专家库相关学科专业组中随机抽取专家鉴定组成员。"},{"i":19,"n":"第十九条","txt":"医学会主持双方当事人抽取专家鉴定组成员前，应当将专家库相关学科专业组中专家姓名、专业、技术职务、工作单位告知双方当事人。"},{"i":20,"n":"第二十条","txt":"当事人要求专家库成员回避的，应当说明理由。符合下列情形之一的，医学会应当将回避的专家名单撤出，并经当事人签字确认后记录在案： （一）医疗事故争议当事人或者当事人的近亲属的； （二）与医疗事故争议有利害关系的； （三）与医疗事故争议当事人有其他关系，可能影响公正鉴定的。"},{"i":21,"n":"第二十一条","txt":"医学会对当事人准备抽取的专家进行随机编号，并主持双方当事人随机抽取相同数量的专家编号，最后一个专家由医学会随机抽取。 双方当事人还应当按照上款规定的方法各自随机抽取一个专家作为候补。 涉及死因、伤残等级鉴定的，应当按照前款规定由双方当事人各自随机抽取一名法医参加鉴定组。"},{"i":22,"n":"第二十二条","txt":"随机抽取结束后，医学会当场向双方当事人公布所抽取的专家鉴定组成员和候补成员的编号并记录在案。"},{"i":23,"n":"第二十三条","txt":"现有专家库成员不能满足鉴定工作需要时，医学会应当向双方当事人说明，并经双方当事人同意，可以从本省、自治区、直辖市其他医学会专家库中抽取相关学科专业组的专家参加专家鉴定组；本省、自治区、直辖市医学会专家库成员不能满足鉴定工作需要时，可以从其他省、自治区、直辖市医学会专家库中抽取相关学科专业组的专家参加专家鉴定组。"},{"i":24,"n":"第二十四条","txt":"从其他医学会建立的专家库中抽取的专家无法到场参加医疗事故技术鉴定，可以以函件的方式提出鉴定意见。"},{"i":25,"n":"第二十五条","txt":"专家鉴定组成员确定后，在双方当事人共同在场的情况下，由医学会对封存的病历资料启封。"},{"i":26,"n":"第二十六条","txt":"专家鉴定组应当认真审查双方当事人提交的材料，妥善保管鉴定材料，保护患者的隐私，保守有关秘密。"},{"i":27,"n":"第二十七条","txt":"医学会应当自接到双方当事人提交的有关医疗事故技术鉴定的材料、书面陈述及答辩之日起45日内组织鉴定并出具医疗事故技术鉴定书。"},{"i":28,"n":"第二十八条","txt":"医学会可以向双方当事人和其他相关组织、个人进行调查取证，进行调查取证时不得少于2人。调查取证结束后，调查人员和调查对象应当在有关文书上签字。如调查对象拒绝签字的，应当记录在案。"},{"i":29,"n":"第二十九条","txt":"医学会应当在医疗事故技术鉴定7日前，将鉴定的时间、地点、要求等书面通知双方当事人。双方当事人应当按照通知的时间、地点、要求参加鉴定。 参加医疗事故技术鉴定的双方当事人每一方人数不超过3人。 任何一方当事人无故缺席、自行退席或拒绝参加鉴定的，不影响鉴定的进行。"},{"i":30,"n":"第三十条","txt":"医学会应当在医疗事故技术鉴定7日前书面通知专家鉴定组成员。专家鉴定组成员接到医学会通知后认为自己应当回避的，应当于接到通知时及时提出书面回避申请，并说明理由；因其他原因无法参加医疗事故技术鉴定的，应当于接到通知时及时书面告知医学会。"},{"i":31,"n":"第三十一条","txt":"专家鉴定组成员因回避或因其他原因无法参加医疗事故技术鉴定时，医学会应当通知相关学科专业组候补成员参加医疗事故技术鉴定。 专家鉴定组成员因不可抗力因素未能及时告知医学会不能参加鉴定或虽告知但医学会无法按规定组成专家鉴定组的，医疗事故技术鉴定可以延期进行。"},{"i":32,"n":"第三十二条","txt":"专家鉴定组组长由专家鉴定组成员推选产生，也可以由医疗事故争议所涉及的主要学科专家中具有最高专业技术职务任职资格的专家担任。"},{"i":33,"n":"第三十三条","txt":"鉴定由专家鉴定组组长主持，并按照以下程序进行： （一）双方当事人在规定的时间内分别陈述意见和理由。陈述顺序先患方，后医疗机构； （二）专家鉴定组成员根据需要可以提问，当事人应当如实回答。必要时，可以对患者进行现场医学检查； （三）双方当事人退场； （四）专家鉴定组对双方当事人提供的书面材料、陈述及答辩等进行讨论； （五）经合议，根据半数以上专家鉴定组成员的一致意见形成鉴定结论。专家鉴定组成员在鉴定结论上签名。专家鉴定组成员对鉴定结论的不同意见，应当予以注明。"},{"i":34,"n":"第三十四条","txt":"医疗事故技术鉴定书应当根据鉴定结论作出，其文稿由专家鉴定组组长签发。 医疗事故技术鉴定书盖医学会医疗事故技术鉴定专用印章。 医学会应当及时将医疗事故技术鉴定书送达移交鉴定的卫生行政部门，经卫生行政部门审核，对符合规定作出的医疗事故技术鉴定结论，应当及时送达双方当事人；由双方当事人共同委托的，直接送达双方当事人。"},{"i":35,"n":"第三十五条","txt":"医疗事故技术鉴定书应当包括下列主要内容： （一）双方当事人的基本情况及要求； （二）当事人提交的材料和医学会的调查材料； （三）对鉴定过程的说明； （四）医疗行为是否违反医疗卫生管理法律、行政法规、部门规章和诊疗护理规范、常规； （五）医疗过失行为与人身损害后果之间是否存在因果关系； （六）医疗过失行为在医疗事故损害后果中的责任程度； （七）医疗事故等级； （八）对医疗事故患者的医疗护理医学建议。 经鉴定为医疗事故的，鉴定结论应当包括上款（四）至（八）项内容；经鉴定不属于医疗事故的，应当在鉴定结论中说明理由。 医疗事故技术鉴定书格式由中华医学会统一制定。"},{"i":36,"n":"第三十六条","txt":"专家鉴定组应当综合分析医疗过失行为在导致医疗事故损害后果中的作用、患者原有疾病状况等因素，判定医疗过失行为的责任程度。医疗事故中医疗过失行为责任程度分为： （一）完全责任，指医疗事故损害后果完全由医疗过失行为造成。 （二）主要责任，指医疗事故损害后果主要由医疗过失行为造成，其他因素起次要作用。 （三）次要责任，指医疗事故损害后果主要由其他因素造成，医疗过失行为起次要作用。 （四）轻微责任，指医疗事故损害后果绝大部分由其他因素造成，医疗过失行为起轻微作用。"},{"i":37,"n":"第三十七条","txt":"医学会参加医疗事故技术鉴定会的工作人员，应如实记录鉴定会过程和专家的意见。"},{"i":38,"n":"第三十八条","txt":"当事人拒绝配合，无法进行医疗事故技术鉴定的，应当终止本次鉴定，由医学会告知移交鉴定的卫生行政部门或共同委托鉴定的双方当事人，说明不能鉴定的原因。"},{"i":39,"n":"第三十九条","txt":"医学会对经卫生行政部门审核认为参加鉴定的人员资格和专业类别或者鉴定程序不符合规定，需要重新鉴定的，应当重新组织鉴定。重新鉴定时不得收取鉴定费。 如参加鉴定的人员资格和专业类别不符合规定的，应当重新抽取专家组织专家鉴定组进行重新鉴定。 如鉴定的程序不符合规定而参加鉴定的人员资格和专业类别符合规定的，可以由原专家鉴定组进行重新鉴定。"},{"i":40,"n":"第四十条","txt":"任何一方当事人对首次医疗事故技术鉴定结论不服的，可以自收到首次医疗事故技术鉴定书之日起15日内，向原受理医疗事故争议处理申请的卫生行政部门提出再次鉴定的申请，或由双方当事人共同委托省、自治区、直辖市医学会组织再次鉴定。"},{"i":41,"n":"第四十一条","txt":"县级以上地方卫生行政部门对发生医疗事故的医疗机构和医务人员进行行政处理时，应当以最后的医疗事故技术鉴定结论作为处理依据。"},{"i":42,"n":"第四十二条","txt":"当事人对鉴定结论无异议，负责组织医疗事故技术鉴定的医学会应当及时将收到的鉴定材料中的病历资料原件等退还当事人，并保留有关复印件。 当事人提出再次鉴定申请的，负责组织首次医疗事故技术鉴定的医学会应当及时将收到的鉴定材料移送负责组织再次医疗事故技术鉴定的医学会。"},{"i":43,"n":"第四十三条","txt":"医学会应当将专家鉴定组成员签名的鉴定结论、由专家鉴定组组长签发的医疗事故技术鉴定书文稿和复印或者复制的有关病历资料等存档，保存期限不得少于20年。"},{"i":44,"n":"第四十四条","txt":"在受理医患双方共同委托医疗事故技术鉴定后至专家鉴定组作出鉴定结论前，双方当事人或者一方当事人提出停止鉴定的，医疗事故技术鉴定终止。"},{"i":45,"n":"第四十五条","txt":"医学会应当于每年3月31日前将上一年度医疗事故技术鉴定情况报同级卫生行政部门。"},{"i":46,"n":"第四十六条","txt":"必要时，对疑难、复杂并在全国有重大影响的医疗事故争议，省级卫生行政部门可以商请中华医学会组织医疗事故技术鉴定。"},{"i":47,"n":"第四十七条","txt":"本办法由卫生部负责解释。"},{"i":48,"n":"第四十八条","txt":"本办法自2002年9月1日起施行。"}],"yiliaoweishengjigouyiliaofeiwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范医疗卫生机构对医疗废物的管理，有效预防和控制医疗废物对人体健康和环境产生危害，根据《医疗废物管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"各级各类医疗卫生机构应当按照《医疗废物管理条例》和本办法的规定对医疗废物进行管理。"},{"i":3,"n":"第三条","txt":"卫生部对全国医疗卫生机构的医疗废物管理工作实施监督。 县级以上地方人民政府卫生行政主管部门对本行政区域医疗卫生机构的医疗废物管理工作实施监督。"},{"i":4,"n":"第四条","txt":"医疗卫生机构应当建立、健全医疗废物管理责任制，其法定代表人或者主要负责人为第一责任人，切实履行职责，确保医疗废物的安全管理。"},{"i":5,"n":"第五条","txt":"医疗卫生机构应当依据国家有关法律、行政法规、部门规章和规范性文件的规定，制定并落实医疗废物管理的规章制度、工作流程和要求、有关人员的工作职责及发生医疗卫生机构内医疗废物流失、泄漏、扩散和意外事故的应急方案。内容包括： （一）医疗卫生机构内医疗废物各产生地点对医疗废物分类收集方法和工作要求； （二）医疗卫生机构内医疗废物的产生地点、暂时贮存地点的工作制度及从产生地点运送至暂时贮存地点的工作要求； （三）医疗废物在医疗卫生机构内部运送及将医疗废物交由医疗废物处置单位的有关交接、登记的规定； （四）医疗废物管理过程中的特殊操作程序及发生医疗废物流失、泄漏、扩散和意外事故的紧急处理措施； （五）医疗废物分类收集、运送、暂时贮存过程中有关工作人员的职业卫生安全防护。"},{"i":6,"n":"第六条","txt":"医疗卫生机构应当设置负责医疗废物管理的监控部门或者专（兼）职人员，履行以下职责： （一）负责指导、检查医疗废物分类收集、运送、暂时贮存及机构内处置过程中各项工作的落实情况； （二）负责指导、检查医疗废物分类收集、运送、暂时贮存及机构内处置过程中的职业卫生安全防护工作； （三）负责组织医疗废物流失、泄漏、扩散和意外事故发生时的紧急处理工作； （四）负责组织有关医疗废物管理的培训工作； （五）负责有关医疗废物登记和档案资料的管理； （六）负责及时分析和处理医疗废物管理中的其他问题。"},{"i":7,"n":"第七条","txt":"医疗卫生机构发生医疗废物流失、泄漏、扩散和意外事故时，应当按照《医疗废物管理条例》和本办法的规定采取相应紧急处理措施，并在48小时内向所在地的县级人民政府卫生行政主管部门、环境保护行政主管部门报告。调查处理工作结束后，医疗卫生机构应当将调查处理结果向所在地的县级人民政府卫生行政主管部门、环境保护行政主管部门报告。 县级人民政府卫生行政主管部门每月汇总逐级上报至当地省级人民政府卫生行政主管部门。 省级人民政府卫生行政主管部门每半年汇总后报卫生部。"},{"i":8,"n":"第八条","txt":"医疗卫生机构发生因医疗废物管理不当导致1人以上死亡或者3人以上健康损害，需要对致病人员提供医疗救护和现场救援的重大事故时，应当在12小时内向所在地的县级人民政府卫生行政主管部门报告，并按照《医疗废物管理条例》和本办法的规定，采取相应紧急处理措施。 县级人民政府卫生行政主管部门接到报告后，应当在12小时内逐级向省级人民政府卫生行政主管部门报告。 医疗卫生机构发生因医疗废物管理不当导致3人以上死亡或者10人以上健康损害，需要对致病人员提供医疗救护和现场救援的重大事故时，应当在2小时内向所在地的县级人民政府卫生行政主管部门报告，并按照《医疗废物管理条例》和本办法的规定，采取相应紧急处理措施。 县级人民政府卫生行政主管部门接到报告后，应当在6小时内逐级向省级人民政府卫生行政主管部门报告。 省级人民政府卫生行政主管部门接到报告后，应当在6小时内向卫生部报告。 发生因医疗废物管理不当导致传染病传播"},{"i":9,"n":"第九条","txt":"医疗卫生机构应当根据医疗废物分类收集、运送、暂时贮存及机构内处置过程中所需要的专业技术、职业卫生安全防护和紧急处理知识等，制定相关工作人员的培训计划并组织实施。"},{"i":10,"n":"第十条","txt":"医疗卫生机构应当根据《医疗废物分类目录》，对医疗废物实施分类管理。"},{"i":11,"n":"第十一条","txt":"医疗卫生机构应当按照以下要求，及时分类收集医疗废物： （一）根据医疗废物的类别，将医疗废物分置于符合《医疗废物专用包装物、容器的标准和警示标识的规定》的包装物或者容器内； （二）在盛装医疗废物前，应当对医疗废物包装物或者容器进行认真检查，确保无破损、渗漏和其他缺陷； （三）感染性废物、病理性废物、损伤性废物、药物性废物及化学性废物不能混合收集。少量的药物性废物可以混入感染性废物，但应当在标签上注明； （四）废弃的麻醉、精神、放射性、毒性等药品及其相关的废物的管理，依照有关法律、行政法规和国家有关规定、标准执行； （五）化学性废物中批量的废化学试剂、废消毒剂应当交由专门机构处置； （六）批量的含有汞的体温计、血压计等医疗器具报废时，应当交由专门机构处置； （七）医疗废物中病原体的培养基、标本和菌种、毒种保存液等高危险废物，应当首先在产生地点进行压力蒸汽灭菌或者化学消毒处理，然后按感染性废"},{"i":12,"n":"第十二条","txt":"医疗卫生机构内医疗废物产生地点应当有医疗废物分类收集方法的示意图或者文字说明。"},{"i":13,"n":"第十三条","txt":"盛装的医疗废物达到包装物或者容器的3/4时，应当使用有效的封口方式，使包装物或者容器的封口紧实、严密。"},{"i":14,"n":"第十四条","txt":"包装物或者容器的外表面被感染性废物污染时，应当对被污染处进行消毒处理或者增加一层包装。"},{"i":15,"n":"第十五条","txt":"盛装医疗废物的每个包装物、容器外表面应当有警示标识，在每个包装物、容器上应当系中文标签，中文标签的内容应当包括：医疗废物产生单位、产生日期、类别及需要的特别说明等。"},{"i":16,"n":"第十六条","txt":"运送人员每天从医疗废物产生地点将分类包装的医疗废物按照规定的时间和路线运送至内部指定的暂时贮存地点。"},{"i":17,"n":"第十七条","txt":"运送人员在运送医疗废物前，应当检查包装物或者容器的标识、标签及封口是否符合要求，不得将不符合要求的医疗废物运送至暂时贮存地点。"},{"i":18,"n":"第十八条","txt":"运送人员在运送医疗废物时，应当防止造成包装物或容器破损和医疗废物的流失、泄漏和扩散，并防止医疗废物直接接触身体。"},{"i":19,"n":"第十九条","txt":"运送医疗废物应当使用防渗漏、防遗撒、无锐利边角、易于装卸和清洁的专用运送工具。 每天运送工作结束后，应当对运送工具及时进行清洁和消毒。"},{"i":20,"n":"第二十条","txt":"医疗卫生机构应当建立医疗废物暂时贮存设施、设备，不得露天存放医疗废物；医疗废物暂时贮存的时间不得超过2天。"},{"i":21,"n":"第二十一条","txt":"医疗卫生机构建立的医疗废物暂时贮存设施、设备应当达到以下要求： （一）远离医疗区、食品加工区、人员活动区和生活垃圾存放场所，方便医疗废物运送人员及运送工具、车辆的出入； （二）有严密的封闭措施，设专（兼）职人员管理，防止非工作人员接触医疗废物； （三）有防鼠、防蚊蝇、防蟑螂的安全措施； （四）防止渗漏和雨水冲刷； （五）易于清洁和消毒； （六）避免阳光直射； （七）设有明显的医疗废物警示标识和“禁止吸烟、饮食”的警示标识。"},{"i":22,"n":"第二十二条","txt":"暂时贮存病理性废物，应当具备低温贮存或者防腐条件。"},{"i":23,"n":"第二十三条","txt":"医疗卫生机构应当将医疗废物交由取得县级以上人民政府环境保护行政主管部门许可的医疗废物集中处置单位处置，依照危险废物转移联单制度填写和保存转移联单。"},{"i":24,"n":"第二十四条","txt":"医疗卫生机构应当对医疗废物进行登记，登记内容应当包括医疗废物的来源、种类、重量或者数量、交接时间、最终去向以及经办人签名等项目。登记资料至少保存3年。"},{"i":25,"n":"第二十五条","txt":"医疗废物转交出去后，应当对暂时贮存地点、设施及时进行清洁和消毒处理。"},{"i":26,"n":"第二十六条","txt":"禁止医疗卫生机构及其工作人员转让、买卖医疗废物。 禁止在非收集、非暂时贮存地点倾倒、堆放医疗废物，禁止将医疗废物混入其他废物和生活垃圾。"},{"i":27,"n":"第二十七条","txt":"不具备集中处置医疗废物条件的农村地区，医疗卫生机构应当按照当地卫生行政主管部门和环境保护主管部门的要求，自行就地处置其产生的医疗废物。自行处置医疗废物的，应当符合以下基本要求： （一）使用后的一次性医疗器具和容易致人损伤的医疗废物应当消毒并作毁形处理； （二）能够焚烧的，应当及时焚烧； （三）不能焚烧的，应当消毒后集中填埋。"},{"i":28,"n":"第二十八条","txt":"医疗卫生机构发生医疗废物流失、泄漏、扩散和意外事故时，应当按照以下要求及时采取紧急处理措施： （一）确定流失、泄漏、扩散的医疗废物的类别、数量、发生时间、影响范围及严重程度； （二）组织有关人员尽快按照应急方案，对发生医疗废物泄漏、扩散的现场进行处理； （三）对被医疗废物污染的区域进行处理时，应当尽可能减少对病人、医务人员、其他现场人员及环境的影响； （四）采取适当的安全处置措施，对泄漏物及受污染的区域、物品进行消毒或者其他无害化处置，必要时封锁污染区域，以防扩大污染； （五）对感染性废物污染区域进行消毒时，消毒工作从污染最轻区域向污染最严重区域进行，对可能被污染的所有使用过的工具也应当进行消毒； （六）工作人员应当做好卫生安全防护后进行工作。 处理工作结束后，医疗卫生机构应当对事件的起因进行调查，并采取有效的防范措施预防类似事件的发生。"},{"i":29,"n":"第二十九条","txt":"医疗卫生机构应当对本机构工作人员进行培训，提高全体工作人员对医疗废物管理工作的认识。对从事医疗废物分类收集、运送、暂时贮存、处置等工作的人员和管理人员，进行相关法律和专业技术、安全防护以及紧急处理等知识的培训。"},{"i":30,"n":"第三十条","txt":"医疗废物相关工作人员和管理人员应当达到以下要求： （一）掌握国家相关法律、法规、规章和有关规范性文件的规定，熟悉本机构制定的医疗废物管理的规章制度、工作流程和各项工作要求； （二）掌握医疗废物分类收集、运送、暂时贮存的正确方法和操作程序； （三）掌握医疗废物分类中的安全知识、专业技术、职业卫生安全防护等知识； （四）掌握在医疗废物分类收集、运送、暂时贮存及处置过程中预防被医疗废物刺伤、擦伤等伤害的措施及发生后的处理措施； （五）掌握发生医疗废物流失、泄漏、扩散和意外事故情况时的紧急处理措施。"},{"i":31,"n":"第三十一条","txt":"医疗卫生机构应当根据接触医疗废物种类及风险大小的不同，采取适宜、有效的职业卫生防护措施，为机构内从事医疗废物分类收集、运送、暂时贮存和处置等工作的人员和管理人员配备必要的防护用品，定期进行健康检查，必要时，对有关人员进行免疫接种，防止其受到健康损害。"},{"i":32,"n":"第三十二条","txt":"医疗卫生机构的工作人员在工作中发生被医疗废物刺伤、擦伤等伤害时，应当采取相应的处理措施，并及时报告机构内的相关部门。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府卫生行政主管部门应当依照《医疗废物管理条例》和本办法的规定，对所辖区域的医疗卫生机构进行定期监督检查和不定期抽查。"},{"i":34,"n":"第三十四条","txt":"对医疗卫生机构监督检查和抽查的主要内容是： （一）医疗废物管理的规章制度及落实情况； （二）医疗废物分类收集、运送、暂时贮存及机构内处置的工作状况； （三）有关医疗废物管理的登记资料和记录； （四）医疗废物管理工作中，相关人员的安全防护工作； （五）发生医疗废物流失、泄漏、扩散和意外事故的上报及调查处理情况； （六）进行现场卫生学监测。"},{"i":35,"n":"第三十五条","txt":"卫生行政主管部门在监督检查或者抽查中发现医疗卫生机构存在隐患时，应当责令立即消除隐患。"},{"i":36,"n":"第三十六条","txt":"县级以上卫生行政主管部门应当对医疗卫生机构发生违反《医疗废物管理条例》和本办法规定的行为依法进行查处。"},{"i":37,"n":"第三十七条","txt":"发生因医疗废物管理不当导致传染病传播事故，或者有证据证明传染病传播的事故有可能发生时，卫生行政主管部门应当按照《医疗废物管理条例》第四十条的规定及时采取相应措施。"},{"i":38,"n":"第三十八条","txt":"医疗卫生机构对卫生行政主管部门的检查、监测、调查取证等工作，应当予以配合，不得拒绝和阻碍，不得提供虚假材料。"},{"i":39,"n":"第三十九条","txt":"医疗卫生机构违反《医疗废物管理条例》及本办法规定，有下列情形之一的，由县级以上地方人民政府卫生行政主管部门责令限期改正、给予警告；逾期不改正的，处以2000元以上5000元以下的罚款： （一）未建立、健全医疗废物管理制度，或者未设置监控部门或者专（兼）职人员的； （二）未对有关人员进行相关法律和专业技术、安全防护以及紧急处理等知识的培训的； （三）未对医疗废物进行登记或者未保存登记资料的； （四）未对机构内从事医疗废物分类收集、运送、暂时贮存、处置等工作的人员和管理人员采取职业卫生防护措施的； （五）未对使用后的医疗废物运送工具及时进行清洁和消毒的； （六）自行建有医疗废物处置设施的医疗卫生机构，未定期对医疗废物处置设施的卫生学效果进行检测、评价，或者未将检测、评价效果存档、报告的。"},{"i":40,"n":"第四十条","txt":"医疗卫生机构违反《医疗废物管理条例》及本办法规定，有下列情形之一的，由县级以上地方人民政府卫生行政主管部门责令限期改正、给予警告，可以并处5000元以下的罚款；逾期不改正的，处5000元以上3万元以下的罚款： （一）医疗废物暂时贮存地点、设施或者设备不符合卫生要求的； （二）未将医疗废物按类别分置于专用包装物或者容器的； （三）使用的医疗废物运送工具不符合要求的。"},{"i":41,"n":"第四十一条","txt":"医疗卫生机构违反《医疗废物管理条例》及本办法规定，有下列情形之一的，由县级以上地方人民政府卫生行政主管部门责令限期改正，给予警告，并处5000元以上1万元以下的罚款；逾期不改正的，处1万元以上3万元以下的罚款；造成传染病传播的，由原发证部门暂扣或者吊销医疗卫生机构执业许可证件；构成犯罪的，依法追究刑事责任： （一）在医疗卫生机构内丢弃医疗废物和在非贮存地点倾倒、堆放医疗废物或者将医疗废物混入其他废物和生活垃圾的； （二）将医疗废物交给未取得经营许可证的单位或者个人的； （三）未按照条例及本办法的规定对污水、传染病病人和疑似传染病病人的排泄物进行严格消毒，或者未达到国家规定的排放标准，排入污水处理系统的； （四）对收治的传染病病人或者疑似传染病病人产生的生活垃圾，未按照医疗废物进行管理和处置的。"},{"i":42,"n":"第四十二条","txt":"医疗卫生机构转让、买卖医疗废物的，依照《医疗废物管理条例》第五十三条处罚。"},{"i":43,"n":"第四十三条","txt":"医疗卫生机构发生医疗废物流失、泄漏、扩散时，未采取紧急处理措施，或者未及时向卫生行政主管部门报告的，由县级以上地方人民政府卫生行政主管部门责令改正，给予警告，并处1万元以上3万元以下的罚款；造成传染病传播的，由原发证部门暂扣或者吊销医疗卫生机构执业许可证件；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"医疗卫生机构无正当理由，阻碍卫生行政主管部门执法人员执行职务，拒绝执法人员进入现场，或者不配合执法部门的检查、监测、调查取证的，由县级以上地方人民政府卫生行政主管部门责令改正，给予警告；拒不改正的，由原发证部门暂扣或者吊销医疗卫生机构执业许可证件；触犯《中华人民共和国治安管理处罚条例》，构成违反治安管理行为的，由公安机关依法予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"不具备集中处置医疗废物条件的农村，医疗卫生机构未按照《医疗废物管理条例》和本办法的要求处置医疗废物的，由县级以上地方人民政府卫生行政主管部门责令限期改正，给予警告；逾期不改的，处1000元以上5000元以下的罚款；造成传染病传播的，由原发证部门暂扣或者吊销医疗卫生机构执业许可证件；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"医疗卫生机构违反《医疗废物管理条例》及本办法规定，导致传染病传播，给他人造成损害的，依法承担民事赔偿责任。"},{"i":47,"n":"第四十七条","txt":"本办法所称医疗卫生机构指依照《医疗机构管理条例》的规定取得《医疗机构执业许可证》的机构及疾病预防控制机构、采供血机构。"},{"i":48,"n":"第四十八条","txt":"本办法自公布之日起施行。"}],"yiliaoqixielinchuangshiyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗器械临床使用管理，保障医疗器械临床使用安全、有效，根据《医疗器械监督管理条例》《医疗机构管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级各类医疗机构临床使用医疗器械的监督管理工作。 医疗器械临床试验管理不适用本办法。"},{"i":3,"n":"第三条","txt":"国家卫生健康委负责全国医疗器械临床使用监督管理工作。 县级以上地方卫生健康主管部门负责本行政区域内医疗器械临床使用监督管理工作。"},{"i":4,"n":"第四条","txt":"医疗机构主要负责人是本机构医疗器械临床使用管理的第一责任人。 医疗机构应当建立并完善本机构医疗器械临床使用管理制度，确保医疗器械合理使用。"},{"i":5,"n":"第五条","txt":"县级以上地方卫生健康主管部门和医疗机构应当依据国家有关规定建立医疗器械应急保障机制，保障突发事件的应急救治需求。"},{"i":6,"n":"第六条","txt":"医疗机构应当根据国家发布的医疗器械分类目录，对医疗器械实行分类管理。"},{"i":7,"n":"第七条","txt":"卫生健康主管部门应当逐步完善人工智能医疗器械临床使用规范，鼓励医疗机构加强人工智能医疗器械临床使用培训。"},{"i":8,"n":"第八条","txt":"国家卫生健康委组织成立国家医疗器械临床使用专家委员会。国家医疗器械临床使用专家委员会负责分析全国医疗器械临床使用情况，研究医疗器械临床使用中的重点问题，提供政策咨询及建议，指导医疗器械临床合理使用。 省级卫生健康主管部门组织成立省级医疗器械临床使用专家委员会或者委托相关组织、机构负责本行政区域内医疗器械临床使用的监测、评价等工作。"},{"i":9,"n":"第九条","txt":"二级以上医疗机构应当设立医疗器械临床使用管理委员会；其他医疗机构应当根据本机构实际情况，配备负责医疗器械临床使用管理的专（兼）职人员。 医疗器械临床使用管理委员会由本机构负责医疗管理、质量控制、医院感染管理、医学工程、信息等工作的相关职能部门负责人以及相关临床、医技等科室负责人组成，负责指导和监督本机构医疗器械临床使用行为，日常管理工作依托本机构的相关部门负责。"},{"i":10,"n":"第十条","txt":"医疗机构医疗器械临床使用管理委员会和配备的专（兼）职人员对本机构医疗器械临床使用管理承担以下职责： （一）依法拟订医疗器械临床使用工作制度并组织实施； （二）组织开展医疗器械临床使用安全管理、技术评估与论证； （三）监测、评价医疗器械临床使用情况，对临床科室在用医疗器械的使用效能进行分析、评估和反馈；监督、指导高风险医疗器械的临床使用与安全管理；提出干预和改进医疗器械临床使用措施，指导临床合理使用； （四）监测识别医疗器械临床使用安全风险，分析、评估使用安全事件，并提供咨询与指导； （五）组织开展医疗器械管理法律、法规、规章和合理使用相关制度、规范的业务知识培训，宣传医疗器械临床使用安全知识。"},{"i":11,"n":"第十一条","txt":"二级以上医疗机构应当明确本机构各相关职能部门和各相关科室的医疗器械临床使用管理职责；相关职能部门、相关科室应当指定专人负责本部门或者本科室的医疗器械临床使用管理工作。 其他医疗机构应当根据本机构实际情况，明确相关部门、科室和人员的职责。"},{"i":12,"n":"第十二条","txt":"二级以上医疗机构应当配备与其功能、任务、规模相适应的医学工程及其他专业技术人员、设备和设施。"},{"i":13,"n":"第十三条","txt":"医疗器械使用科室负责医疗器械日常管理工作，做好医疗器械的登记、定期核对、日常使用维护保养等工作。"},{"i":14,"n":"第十四条","txt":"医疗机构从事医疗器械相关工作的卫生专业技术人员，应当具备相应的专业学历、卫生专业技术职务任职资格或者依法取得相应资格。"},{"i":15,"n":"第十五条","txt":"医疗机构应当组织开展医疗器械临床使用管理的继续教育和培训，开展医疗器械临床使用范围、质量控制、操作规程、效果评价等培训工作。"},{"i":16,"n":"第十六条","txt":"医疗机构应当加强医疗器械信息管理，建立医疗器械及其使用信息档案。"},{"i":17,"n":"第十七条","txt":"医疗机构应当每年开展医疗器械临床使用管理自查、评估、评价工作，确保医疗器械临床使用的安全、有效。"},{"i":18,"n":"第十八条","txt":"医疗机构应当建立医疗器械临床使用技术评估与论证制度并组织实施，开展技术需求分析和成本效益评估，确保医疗器械满足临床需求。"},{"i":19,"n":"第十九条","txt":"医疗机构购进医疗器械，应当查验供货者的资质和医疗器械的合格证明文件，建立进货查验记录制度。 医疗机构应当妥善保存购入第三类医疗器械的原始资料，并确保信息具有可追溯性。"},{"i":20,"n":"第二十条","txt":"医疗器械需要安装或者集成的，应当由生产厂家或者其授权的具备相关服务资质的单位、医疗机构负责医学工程工作的部门依据国家有关标准实施。 医疗机构应当对医疗器械相关硬件、软件的安装、更新、升级情况进行登记和审核，并应当进行临床验证和技术评估。"},{"i":21,"n":"第二十一条","txt":"医疗机构应当建立医疗器械验收验证制度，保证医疗器械的功能、性能、配置要求符合购置合同以及临床诊疗的要求。医疗器械经验收验证合格后方可应用于临床。"},{"i":22,"n":"第二十二条","txt":"医疗机构及其医务人员临床使用医疗器械，应当遵循安全、有效、经济的原则，采用与患者疾病相适应的医疗器械进行诊疗活动。 需要向患者说明医疗器械临床使用相关事项的，应当如实告知，不得隐瞒或者虚假宣传，误导患者。"},{"i":23,"n":"第二十三条","txt":"医疗机构及其医务人员临床使用医疗器械，应当按照诊疗规范、操作指南、医疗器械使用说明书等，遵守医疗器械适用范围、禁忌症及注意事项，注意主要风险和关键性能指标。"},{"i":24,"n":"第二十四条","txt":"医疗机构应当建立医疗器械临床使用风险管理制度，持续改进医疗器械临床使用行为。"},{"i":25,"n":"第二十五条","txt":"医疗机构应当开展医疗器械临床使用安全管理，对生命支持类、急救类、植入类、辐射类、灭菌类和大型医疗器械实行使用安全监测与报告制度。"},{"i":26,"n":"第二十六条","txt":"医疗机构应当制订与其规模、功能相匹配的生命支持医疗器械和相关重要医疗器械故障紧急替代流程，配备必要的替代设备设施，并对急救的医疗器械实行专管专用，保证临床急救工作正常开展。"},{"i":27,"n":"第二十七条","txt":"发现使用的医疗器械存在安全隐患的，医疗机构应当立即停止使用，并通知医疗器械注册人、备案人或者其他负责产品质量的机构进行检修；经检修仍不能达到使用安全标准的医疗器械，不得继续使用。"},{"i":28,"n":"第二十八条","txt":"医疗机构应当严格执行医院感染管理有关法律法规的规定，使用符合国家规定的消毒器械和一次性使用的医疗器械。按规定可以重复使用的医疗器械，应当严格按照规定清洗、消毒或者灭菌，并进行效果监测；一次性使用的医疗器械不得重复使用，使用过的应当按照国家有关规定销毁并记录。 使用无菌医疗器械前，应当对直接接触医疗器械的包装及其有效期进行常规检查，认真核对其规格、型号、消毒或者灭菌有效日期等。包装破损、标示不清、超过有效期或者可能影响使用安全的，不得使用。"},{"i":29,"n":"第二十九条","txt":"临床使用大型医疗器械以及植入和介入类医疗器械的，应当将医疗器械的名称、关键性技术参数等信息以及与使用质量安全密切相关的必要信息记载到病历等相关记录中。"},{"i":30,"n":"第三十条","txt":"医疗机构应当按照规定开展医疗器械临床使用评价工作，重点加强医疗器械的临床实效性、可靠性和可用性评价。"},{"i":31,"n":"第三十一条","txt":"医疗器械保障维护管理应当重点进行检测和预防性维护。通过开展性能检测和安全监测，验证医疗器械性能的适当性和使用的安全性；通过开展部件更换、清洁等预防性维护，延长医疗器械使用寿命并预防故障发生。"},{"i":32,"n":"第三十二条","txt":"医疗机构应当监测医疗器械的运行状态，对维护与维修的全部过程进行跟踪记录，定期分析评价医疗器械整体维护情况。"},{"i":33,"n":"第三十三条","txt":"医疗机构应当遵照国家有关医疗器械标准、规程、技术指南等，确保系统环境电源、温湿度、辐射防护、磁场屏蔽、光照亮度等因素与医疗器械相适应，定期对医疗器械使用环境进行测试、评估和维护。"},{"i":34,"n":"第三十四条","txt":"医疗机构应当具备与医疗器械品种、数量相适应的贮存场所和条件。对温度、湿度等环境条件有特殊要求的，应当采取相应措施，保证医疗器械安全、有效。"},{"i":35,"n":"第三十五条","txt":"医疗机构应当真实记录医疗器械保障情况并存入医疗器械信息档案，档案保存期限不得少于医疗器械规定使用期限终止后五年。"},{"i":36,"n":"第三十六条","txt":"医疗机构应当对医疗器械使用安全事件进行收集、分析、评价及控制，遵循可疑即报的原则，及时报告。"},{"i":37,"n":"第三十七条","txt":"发生或者发现医疗器械使用安全事件或者可疑医疗器械使用安全事件时，医疗机构及其医务人员应当立即采取有效措施，避免或者减轻对患者身体健康的损害，防止损害扩大，并向所在地县级卫生健康主管部门报告。"},{"i":38,"n":"第三十八条","txt":"发生或者发现因医疗器械使用行为导致或者可能导致患者死亡、残疾或者二人以上人身损害时，医疗机构应当在二十四小时内报告所在地县级卫生健康主管部门，必要时可以同时向上级卫生健康主管部门报告。医疗机构应当立即对医疗器械使用行为进行调查、核实；必要时，应当对发生使用安全事件的医疗器械同批次同规格型号库存产品暂缓使用，对剩余产品进行登记封存。"},{"i":39,"n":"第三十九条","txt":"县级及设区的市级卫生健康主管部门获知医疗机构医疗器械使用安全事件或者可疑医疗器械使用安全事件后，应当进行核实，必要时应当进行调查；对医疗机构医疗器械使用行为导致或者可能导致患者死亡、残疾或者二人以上人身损害的，应当进行现场调查，并将调查结果逐级上报至省级卫生健康主管部门。 省级以上卫生健康主管部门获知医疗机构医疗器械使用安全事件或者可疑医疗器械使用安全事件，认为应当开展现场调查的，应当组织开展调查。省级卫生健康主管部门开展相关调查的，应将调查结果及时报送国家卫生健康委。 对卫生健康主管部门开展的医疗器械使用安全事件调查，医疗机构应当配合。"},{"i":40,"n":"第四十条","txt":"县级以上地方卫生健康主管部门在医疗器械使用安全事件调查结果确定前，对可疑医疗器械质量问题造成患者损害的，应当根据影响采取相应措施；对影响较大的，可以采取风险性提示、暂停辖区内医疗机构使用同批次同规格型号的医疗器械等措施，以有效降低风险，并通报同级药品监督管理部门。 经调查不属于医疗器械使用安全事件的，卫生健康主管部门应当移交同级药品监督管理部门处理。"},{"i":41,"n":"第四十一条","txt":"县级以上地方卫生健康主管部门应当编制并实施本行政区域医疗机构医疗器械使用年度监督检查计划，确定监督检查的重点、频次和覆盖率。对使用风险较高、有特殊保存管理要求医疗器械的医疗机构应当实施重点监管。"},{"i":42,"n":"第四十二条","txt":"县级以上地方卫生健康主管部门应当加强对医疗机构医疗器械临床使用行为的监督管理，并在监督检查中有权行使以下职责： （一）进入现场实施检查、抽取样品； （二）查阅、复制有关档案、记录及其他有关资料； （三）法律法规规定的其他职责。 医疗机构应当积极配合卫生健康主管部门的监督检查，并对检查中发现的问题及时进行整改。"},{"i":43,"n":"第四十三条","txt":"县级以上地方卫生健康主管部门应当组织对医疗机构医疗器械临床使用管理情况进行定期或者不定期抽查，并将抽查结果纳入医疗机构监督管理档案。"},{"i":44,"n":"第四十四条","txt":"医疗机构有下列情形之一的，由县级以上地方卫生健康主管部门依据《医疗器械监督管理条例》的有关规定予以处理： （一）未按照规定建立并执行医疗器械进货查验记录制度的； （二）对重复使用的医疗器械，未按照消毒和管理的规定进行处理的； （三）重复使用一次性使用的医疗器械，或者未按照规定销毁使用过的一次性使用的医疗器械的； （四）未妥善保存购入第三类医疗器械的原始资料，或者未按照规定将大型医疗器械以及植入和介入类医疗器械的信息记载到病历等相关记录中的； （五）发现使用的医疗器械存在安全隐患未立即停止使用、通知检修，或者继续使用经检修仍不能达到使用安全标准的医疗器械的。"},{"i":45,"n":"第四十五条","txt":"医疗机构违反本办法规定，有下列情形之一的，由县级以上地方卫生健康主管部门责令改正，给予警告；情节严重的，可以并处五千元以上三万元以下罚款： （一）未按照规定建立医疗器械临床使用管理工作制度的； （二）未按照规定设立医疗器械临床使用管理委员会或者配备专（兼）职人员负责本机构医疗器械临床使用管理工作的； （三）未按照规定建立医疗器械验收验证制度的； （四）未按照规定报告医疗器械使用安全事件的； （五）不配合卫生健康主管部门开展的医疗器械使用安全事件调查和临床使用行为的监督检查的； （六）其他违反本办法规定的行为。"},{"i":46,"n":"第四十六条","txt":"医疗机构及其医务人员在医疗器械临床使用中违反《执业医师法》《医疗机构管理条例》等有关法律法规的，依据有关法律法规的规定进行处理。"},{"i":47,"n":"第四十七条","txt":"县级以上地方卫生健康主管部门工作人员不履行医疗机构医疗器械临床使用监督管理职责或者滥用职权、玩忽职守、徇私舞弊的，上级卫生健康主管部门可以建议有管理权限的监察机关或者任免机关对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"本办法所称医疗器械使用安全事件，是指医疗机构及其医务人员在诊疗活动中，因医疗器械使用行为存在过错，造成患者人身损害的事件。"},{"i":49,"n":"第四十九条","txt":"取得计划生育技术服务机构执业许可证的计划生育技术服务机构，以及依法执业的血站、单采血浆站等单位的医疗器械使用管理参照本办法执行。"},{"i":50,"n":"第五十条","txt":"对使用环节的医疗器械质量的监督管理，按照国务院药品监督管理部门的有关规定执行。"},{"i":51,"n":"第五十一条","txt":"本办法自2021年3月1日起施行。"}],"yiliaofeiwuguanlixingzhengchufabanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国传染病防治法》、《中华人民共和国固体废物污染环境防治法》和《医疗废物管理条例》（以下简称《条例》），县级以上人民政府卫生行政主管部门和环境保护行政主管部门按照各自职责，对违反医疗废物管理规定的行为实施的行政处罚，适用本办法。"},{"i":2,"n":"第二条","txt":"医疗卫生机构有《条例》第四十五条规定的下列情形之一的，由县级以上地方人民政府卫生行政主管部门责令限期改正，给予警告；逾期不改正的，处2000元以上5000元以下的罚款： （一）未建立、健全医疗废物管理制度，或者未设置监控部门或者专（兼）职人员的； （二）未对有关人员进行相关法律和专业技术、安全防护以及紧急处理等知识培训的； （三）未对医疗废物进行登记或者未保存登记资料的； （四）对使用后的医疗废物运送工具或者运送车辆未在指定地点及时进行消毒和清洁的； （五）依照《条例》自行建有医疗废物处置设施的医疗卫生机构未定期对医疗废物处置设施的污染防治和卫生学效果进行检测、评价，或者未将检测、评价效果存档、报告的。"},{"i":3,"n":"第三条","txt":"医疗废物集中处置单位有《条例》第四十五条规定的下列情形之一的，由县级以上地方人民政府环境保护行政主管部门责令限期改正，给予警告；逾期不改正的，处2000元以上5000元以下的罚款： （一）未建立、健全医疗废物管理制度，或者未设置监控部门或者专（兼）职人员的； （二）未对有关人员进行相关法律和专业技术、安全防护以及紧急处理等知识培训的； （三）未对医疗废物进行登记或者未保存登记资料的； （四）对使用后的医疗废物运送车辆未在指定地点及时进行消毒和清洁的； （五）未及时收集、运送医疗废物的； （六）未定期对医疗废物处置设施的污染防治和卫生学效果进行检测、评价，或者未将检测、评价效果存档、报告的。"},{"i":4,"n":"第四条","txt":"医疗卫生机构、医疗废物集中处置单位有《条例》第四十五条规定的情形，未对从事医疗废物收集、运送、贮存、处置等工作的人员和管理人员采取职业卫生防护措施的，由县级以上地方人民政府卫生行政主管部门责令限期改正，给予警告；逾期不改正的，处2000元以上5000元以下的罚款。"},{"i":5,"n":"第五条","txt":"医疗卫生机构有《条例》第四十六条规定的下列情形之一的，由县级以上地方人民政府卫生行政主管部门责令限期改正，给予警告，可以并处5000元以下的罚款，逾期不改正的，处5000元以上3万元以下的罚款： （一）贮存设施或者设备不符合环境保护、卫生要求的； （二）未将医疗废物按照类别分置于专用包装物或者容器的； （三）未使用符合标准的运送工具运送医疗废物的。"},{"i":6,"n":"第六条","txt":"医疗废物集中处置单位有《条例》第四十六条规定的下列情形之一的，由县级以上地方人民政府环境保护行政主管部门责令限期改正，给予警告，可以并处5000元以下的罚款，逾期不改正的，处5000元以上3万元以下的罚款： （一）贮存设施或者设备不符合环境保护、卫生要求的； （二）未将医疗废物按照类别分置于专用包装物或者容器的； （三）未使用符合标准的专用车辆运送医疗废物的； （四）未安装污染物排放在线监控装置或者监控装置未经常处于正常运行状态的。"},{"i":7,"n":"第七条","txt":"医疗卫生机构有《条例》第四十七条规定的下列情形之一的，由县级以上地方人民政府卫生行政主管部门责令限期改正，给予警告，并处5000元以上1万元以下的罚款；逾期不改正的，处1万元以上3万元以下的罚款： （一）在医疗卫生机构内运送过程中丢弃医疗废物，在非贮存地点倾倒、堆放医疗废物或者将医疗废物混入其他废物和生活垃圾的； （二）未按照《条例》的规定对污水、传染病病人或者疑似传染病病人的排泄物，进行严格消毒的，或者未达到国家规定的排放标准，排入医疗卫生机构内的污水处理系统的； （三）对收治的传染病病人或者疑似传染病病人产生的生活垃圾，未按照医疗废物进行管理和处置的。 医疗卫生机构在医疗卫生机构外运送过程中丢弃医疗废物，在非贮存地点倾倒、堆放医疗废物或者将医疗废物混入其他废物和生活垃圾的，由县级以上地方人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》第七十五条规定责令停止违"},{"i":8,"n":"第八条","txt":"医疗废物集中处置单位有《条例》第四十七条规定的情形，在运送过程中丢弃医疗废物，在非贮存地点倾倒、堆放医疗废物或者将医疗废物混入其他废物和生活垃圾的，由县级以上地方人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》第七十五条规定责令停止违法行为，限期改正，处一万元以上十万元以下的罚款。"},{"i":9,"n":"第九条","txt":"医疗废物集中处置单位和依照《条例》自行建有医疗废物处置设施的医疗卫生机构，有《条例》第四十七条规定的情形，对医疗废物的处置不符合国家规定的环境保护、卫生标准、规范的，由县级以上地方人民政府环境保护行政主管部门责令限期改正，给予警告，并处5000元以上1万元以下的罚款；逾期不改正的，处1万元以上3万元以下的罚款。"},{"i":10,"n":"第十条","txt":"医疗卫生机构、医疗废物集中处置单位有《条例》第四十七条规定的下列情形之一的，由县级以上人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》第七十五条规定责令停止违法行为，限期改正，处二万元以上二十万元以下的罚款： （一）未执行危险废物转移联单管理制度的； （二）将医疗废物交给或委托给未取得经营许可证的单位或者个人收集、运送、贮存、处置的。"},{"i":11,"n":"第十一条","txt":"有《条例》第四十九条规定的情形，医疗卫生机构发生医疗废物流失、泄露、扩散时，未采取紧急处理措施，或者未及时向卫生行政主管部门报告的，由县级以上地方人民政府卫生行政主管部门责令改正，给予警告，并处1万元以上3万元以下的罚款。 医疗废物集中处置单位发生医疗废物流失、泄露、扩散时，未采取紧急处理措施，或者未及时向环境保护行政主管部门报告的，由县级以上地方人民政府环境保护行政主管部门责令改正，给予警告，并处1万元以上3万元以下的罚款。"},{"i":12,"n":"第十二条","txt":"有《条例》第五十条规定的情形，医疗卫生机构、医疗废物集中处置单位阻碍卫生行政主管部门执法人员执行职务，拒绝执法人员进入现场，或者不配合执法部门的检查、监测、调查取证的，由县级以上地方人民政府卫生行政主管部门责令改正，给予警告；拒不改正的，由原发证的卫生行政主管部门暂扣或者吊销医疗卫生机构的执业许可证件。 医疗卫生机构、医疗废物集中处置单位阻碍环境保护行政主管部门执法人员执行职务，拒绝执法人员进入现场，或者不配合执法部门的检查、监测、调查取证的，由县级以上地方人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》第七十条规定责令限期改正；拒不改正或者在检查时弄虚作假的，处二千元以上二万元以下的罚款。"},{"i":13,"n":"第十三条","txt":"有《条例》第五十一条规定的情形，不具备集中处置医疗废物条件的农村，医疗卫生机构未按照卫生行政主管部门有关疾病防治的要求处置医疗废物的，由县级人民政府卫生行政主管部门责令限期改正，给予警告；逾期不改正的，处1000元以上5000元以下的罚款；未按照环境保护行政主管部门有关环境污染防治的要求处置医疗废物的，由县级人民政府环境保护行政主管部门责令限期改正，给予警告；逾期不改正的，处1000元以上5000元以下的罚款。"},{"i":14,"n":"第十四条","txt":"有《条例》第五十二条规定的情形，未取得经营许可证从事医疗废物的收集、运送、贮存、处置等活动的，由县级以上人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》第七十七条规定责令停止违法行为，没收违法所得，可以并处违法所得三倍以下的罚款。"},{"i":15,"n":"第十五条","txt":"有《条例》第四十七条、第四十八条、第四十九条、第五十一条规定的情形，医疗卫生机构造成传染病传播的，由县级以上地方人民政府卫生行政主管部门依法处罚，并由原发证的卫生行政主管部门暂扣或者吊销执业许可证件；造成环境污染事故的，由县级以上地方人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》有关规定予以处罚，并由原发证的卫生行政主管部门暂扣或者吊销执业许可证件。 医疗废物集中处置单位造成传染病传播的，由县级以上地方人民政府卫生行政主管部门依法处罚，并由原发证的环境保护行政主管部门暂扣或者吊销经营许可证件；造成环境污染事故的，由县级以上地方人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》有关规定予以处罚，并由原发证的环境保护行政主管部门暂扣或者吊销经营许可证件。"},{"i":16,"n":"第十六条","txt":"有《条例》第五十三条规定的情形，转让、买卖医疗废物，邮寄或者通过铁路、航空运输医疗废物，或者违反《条例》规定通过水路运输医疗废物的，由县级以上地方人民政府环境保护行政主管部门责令转让、买卖双方、邮寄人、托运人立即停止违法行为，给予警告，没收违法所得；违法所得5000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处5000元以上2万元以下的罚款。 承运人明知托运人违反《条例》的规定运输医疗废物，仍予以运输的，按照前款的规定予以处罚；承运人将医疗废物与旅客在同一工具上载运的，由县级以上人民政府环境保护行政主管部门依照《中华人民共和国固体废物污染环境防治法》第七十五条规定责令停止违法行为，限期改正，处一万元以上十万元以下的罚款。"},{"i":17,"n":"第十七条","txt":"本办法自2004年6月1日起施行。"}],"yiliaojishulinchuangyingyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗技术临床应用管理，促进医学科学发展和医疗技术进步，保障医疗质量和患者安全，维护人民群众健康权益，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称医疗技术，是指医疗机构及其医务人员以诊断和治疗疾病为目的，对疾病作出判断和消除疾病、缓解病情、减轻痛苦、改善功能、延长生命、帮助患者恢复健康而采取的医学专业手段和措施。 本办法所称医疗技术临床应用，是指将经过临床研究论证且安全性、有效性确切的医疗技术应用于临床，用以诊断或者治疗疾病的过程。"},{"i":3,"n":"第三条","txt":"医疗机构和医务人员开展医疗技术临床应用应当遵守本办法。"},{"i":4,"n":"第四条","txt":"医疗技术临床应用应当遵循科学、安全、规范、有效、经济、符合伦理的原则。 安全性、有效性不确切的医疗技术，医疗机构不得开展临床应用。"},{"i":5,"n":"第五条","txt":"国家建立医疗技术临床应用负面清单管理制度，对禁止临床应用的医疗技术实施负面清单管理，对部分需要严格监管的医疗技术进行重点管理。其他临床应用的医疗技术由决定使用该类技术的医疗机构自我管理。"},{"i":6,"n":"第六条","txt":"医疗机构对本机构医疗技术临床应用和管理承担主体责任。医疗机构开展医疗技术服务应当与其技术能力相适应。 医疗机构主要负责人是本机构医疗技术临床应用管理的第一责任人。"},{"i":7,"n":"第七条","txt":"国家卫生健康委负责全国医疗技术临床应用管理工作。 县级以上地方卫生行政部门负责本行政区域内医疗技术临床应用监督管理工作。"},{"i":8,"n":"第八条","txt":"鼓励卫生行业组织参与医疗技术临床应用质量控制、规范化培训和技术评估工作，各级卫生行政部门应当为卫生行业组织参与医疗技术临床应用管理创造条件。"},{"i":9,"n":"第九条","txt":"医疗技术具有下列情形之一的，禁止应用于临床（以下简称禁止类技术）： （一）临床应用安全性、有效性不确切； （二）存在重大伦理问题； （三）该技术已经被临床淘汰； （四）未经临床研究论证的医疗新技术。 禁止类技术目录由国家卫生健康委制定发布或者委托专业组织制定发布，并根据情况适时予以调整。"},{"i":10,"n":"第十条","txt":"禁止类技术目录以外并具有下列情形之一的，作为需要重点加强管理的医疗技术（以下简称限制类技术），由省级以上卫生行政部门严格管理： （一）技术难度大、风险高，对医疗机构的服务能力、人员水平有较高专业要求，需要设置限定条件的； （二）需要消耗稀缺资源的； （三）涉及重大伦理风险的； （四）存在不合理临床应用，需要重点管理的。 国家限制类技术目录及其临床应用管理规范由国家卫生健康委制定发布或者委托专业组织制定发布，并根据临床应用实际情况予以调整。 省级卫生行政部门可以结合本行政区域实际情况，在国家限制类技术目录基础上增补省级限制类技术相关项目，制定发布相关技术临床应用管理规范，并报国家卫生健康委备案。"},{"i":11,"n":"第十一条","txt":"对限制类技术实施备案管理。医疗机构拟开展限制类技术临床应用的，应当按照相关医疗技术临床应用管理规范进行自我评估，符合条件的可以开展临床应用，并于开展首例临床应用之日起15个工作日内，向核发其《医疗机构执业许可证》的卫生行政部门备案。备案材料应当包括以下内容： （一）开展临床应用的限制类技术名称和所具备的条件及有关评估材料； （二）本机构医疗技术临床应用管理专门组织和伦理委员会论证材料； （三）技术负责人（限于在本机构注册的执业医师）资质证明材料。 备案部门应当自收到完整备案材料之日起15个工作日内完成备案，在该医疗机构的《医疗机构执业许可证》副本备注栏予以注明，并逐级上报至省级卫生行政部门。"},{"i":12,"n":"第十二条","txt":"未纳入禁止类技术和限制类技术目录的医疗技术，医疗机构可以根据自身功能、任务、技术能力等自行决定开展临床应用，并应当对开展的医疗技术临床应用实施严格管理。"},{"i":13,"n":"第十三条","txt":"医疗机构拟开展存在重大伦理风险的医疗技术，应当提请本机构伦理委员会审议，必要时可以咨询省级和国家医学伦理专家委员会。未经本机构伦理委员会审查通过的医疗技术，特别是限制类医疗技术，不得应用于临床。"},{"i":14,"n":"第十四条","txt":"国家建立医疗技术临床应用质量管理与控制制度，充分发挥各级、各专业医疗质量控制组织的作用，以“限制类技术”为主加强医疗技术临床应用质量控制，对医疗技术临床应用情况进行日常监测与定期评估，及时向医疗机构反馈质控和评估结果，持续改进医疗技术临床应用质量。"},{"i":15,"n":"第十五条","txt":"二级以上的医院、妇幼保健院及专科疾病防治机构医疗质量管理委员会应当下设医疗技术临床应用管理的专门组织，由医务、质量管理、药学、护理、院感、设备等部门负责人和具有高级技术职务任职资格的临床、管理、伦理等相关专业人员组成。该专门组织的负责人由医疗机构主要负责人担任，由医务部门负责日常管理工作，主要职责是： （一）根据医疗技术临床应用管理相关的法律、法规、规章，制定本机构医疗技术临床应用管理制度并组织实施； （二）审定本机构医疗技术临床应用管理目录和手术分级管理目录并及时调整； （三）对首次应用于本机构的医疗技术组织论证，对本机构已经临床应用的医疗技术定期开展评估； （四）定期检查本机构医疗技术临床应用管理各项制度执行情况，并提出改进措施和要求； （五）省级以上卫生行政部门规定的其他职责。 其他医疗机构应当设立医疗技术临床应用管理工作小组，并指定专(兼)职人员负责本机构医疗技术临床应用管理工"},{"i":16,"n":"第十六条","txt":"医疗机构应当建立本机构医疗技术临床应用管理制度，包括目录管理、手术分级、医师授权、质量控制、档案管理、动态评估等制度，保障医疗技术临床应用质量和安全。"},{"i":17,"n":"第十七条","txt":"医疗机构开展医疗技术临床应用应当具有符合要求的诊疗科目、专业技术人员、相应的设备、设施和质量控制体系，并遵守相关技术临床应用管理规范。"},{"i":18,"n":"第十八条","txt":"医疗机构应当制定本机构医疗技术临床应用管理目录并及时调整，对目录内的手术进行分级管理。 手术管理按照国家关于手术分级管理的有关规定执行。"},{"i":19,"n":"第十九条","txt":"医疗机构应当依法准予医务人员实施与其专业能力相适应的医疗技术，并为医务人员建立医疗技术临床应用管理档案，纳入个人专业技术档案管理。"},{"i":20,"n":"第二十条","txt":"医疗机构应当建立医师手术授权与动态管理制度，根据医师的专业能力和培训情况，授予或者取消相应的手术级别和具体手术权限。"},{"i":21,"n":"第二十一条","txt":"医疗机构应当建立医疗技术临床应用论证制度。对已证明安全有效，但属本机构首次应用的医疗技术，应当组织开展本机构技术能力和安全保障能力论证，通过论证的方可开展医疗技术临床应用。"},{"i":22,"n":"第二十二条","txt":"医疗机构应当建立医疗技术临床应用评估制度，对限制类技术的质量安全和技术保证能力进行重点评估,并根据评估结果及时调整本机构医疗技术临床应用管理目录和有关管理要求。对存在严重质量安全问题或者不再符合有关技术管理要求的，要立即停止该项技术的临床应用。 医疗机构应当根据评估结果，及时调整本机构医师相关技术临床应用权限。"},{"i":23,"n":"第二十三条","txt":"医疗机构应当为医务人员参加医疗技术临床应用规范化培训创造条件，加强医疗技术临床应用管理人才队伍的建设和培养。 医疗机构应当加强首次在本医疗机构临床应用的医疗技术的规范化培训工作。"},{"i":24,"n":"第二十四条","txt":"医疗机构开展的限制类技术目录、手术分级管理目录和限制类技术临床应用情况应当纳入本机构院务公开范围，主动向社会公开，接受社会监督。"},{"i":25,"n":"第二十五条","txt":"医疗机构在医疗技术临床应用过程中出现下列情形之一的，应当立即停止该项医疗技术的临床应用： （一）该医疗技术被国家卫生健康委列为“禁止类技术”； （二）从事该医疗技术的主要专业技术人员或者关键设备、设施及其他辅助条件发生变化，不能满足相关技术临床应用管理规范要求，或者影响临床应用效果； （三）该医疗技术在本机构应用过程中出现重大医疗质量、医疗安全或者伦理问题，或者发生与技术相关的严重不良后果； （四）发现该项医疗技术临床应用效果不确切，或者存在重大质量、安全或者伦理缺陷。 医疗机构出现第一款第二项、第三项情形，属于限制类技术的，应当立即将有关情况向核发其《医疗机构执业许可证》的卫生行政部门报告。卫生行政部门应当及时取消该医疗机构相应医疗技术临床应用备案，在该机构《医疗机构执业许可证》副本备注栏予以注明，并逐级向省级卫生行政部门报告。 医疗机构出现第一款第四项情形的，应当立即将有关情况向核"},{"i":26,"n":"第二十六条","txt":"国家建立医疗技术临床应用规范化培训制度。拟开展限制类技术的医师应当按照相关技术临床应用管理规范要求接受规范化培训。 国家卫生健康委统一组织制定国家限制类技术的培训标准和考核要求，并向社会公布。"},{"i":27,"n":"第二十七条","txt":"省级增补的限制类技术以及省级卫生行政部门认为其他需要重点加强培训的医疗技术，由省级卫生行政部门统一组织制订培训标准，对培训基地管理和参加培训医师（以下简称参培医师）的培训和考核提出统一要求，并向社会公布。"},{"i":28,"n":"第二十八条","txt":"对限制类技术临床应用规范化培训基地实施备案管理。医疗机构拟承担限制类技术临床应用规范化培训工作的，应当达到国家和省级卫生行政部门规定的条件，制定培训方案并向社会公开。"},{"i":29,"n":"第二十九条","txt":"医疗机构拟承担限制类技术临床应用规范化培训工作的，应当于首次发布招生公告之日起3个工作日内，向省级卫生行政部门备案。备案材料应当包括： （一）开展相关限制类技术临床应用的备案证明材料； （二）开展相关限制类技术培训工作所具备的软、硬件条件的自我评估材料； （三）近3年开展相关限制类技术临床应用的医疗质量和医疗安全情况； （四）培训方案、培训师资、课程设置、考核方案等材料。"},{"i":30,"n":"第三十条","txt":"省级卫生行政部门应当及时向社会公布经备案拟承担限制性技术临床应用规范化培训工作的医疗机构名单。 省级卫生行政部门应当加强对限制类技术临床应用规范化培训基地的考核和评估，对不符合培训基地条件或者未按照要求开展培训、考核的，应当责令其停止培训工作，并向社会公布。"},{"i":31,"n":"第三十一条","txt":"培训基地应当建立健全规章制度及流程，明确岗位职责和管理要求，加强对培训导师的管理。严格按照统一的培训大纲和教材制定培训方案与计划，建立医师培训档案，确保培训质量和效果。"},{"i":32,"n":"第三十二条","txt":"申请参加培训的医师应当符合相关医疗技术临床应用管理规范要求。培训基地应当按照公开公平、择优录取、双向选择的原则决定是否接收参培医师。"},{"i":33,"n":"第三十三条","txt":"参培医师完成培训后应当接受考核。考核包括过程考核和结业考核。 考核应当由所在培训基地或者省级卫生行政部门委托的第三方组织实施。"},{"i":34,"n":"第三十四条","txt":"对国家和省级卫生行政部门作出统一培训要求以外的医疗技术，医疗机构应当自行进行规范化培训。"},{"i":35,"n":"第三十五条","txt":"县级以上地方卫生行政部门应当加强对本行政区域内医疗机构医疗技术临床应用的监督管理。"},{"i":36,"n":"第三十六条","txt":"国家卫生健康委负责建立全国医疗技术临床应用信息化管理平台，对国家限制类技术临床应用相关信息进行收集、分析和反馈。 省级卫生行政部门负责建立省级医疗技术临床应用信息化管理平台，对本行政区域内国家和省级限制类技术临床应用情况实施监督管理。 省级医疗技术临床应用信息化管理平台应当与全国医疗技术临床应用信息化管理平台实现互联互通，信息共享。"},{"i":37,"n":"第三十七条","txt":"医疗机构应当按照要求，及时、准确、完整地向全国和省级医疗技术临床应用信息化管理平台逐例报送限制类技术开展情况数据信息。 各级、各专业医疗质量控制组织应当充分利用医疗技术临床应用信息化管理平台，加大数据信息分析和反馈力度，指导医疗机构提高医疗技术临床应用质量安全。"},{"i":38,"n":"第三十八条","txt":"国家建立医疗技术临床应用评估制度。对医疗技术的安全性、有效性、经济适宜性及伦理问题等进行评估，作为调整国家医疗技术临床应用管理政策的决策依据之一。"},{"i":39,"n":"第三十九条","txt":"国家建立医疗机构医疗技术临床应用情况信誉评分制度，与医疗机构、医务人员信用记录挂钩，纳入卫生健康行业社会信用体系管理，接入国家信用信息共享平台，并将信誉评分结果应用于医院评审、评优、临床重点专科评估等工作。"},{"i":40,"n":"第四十条","txt":"县级以上地方卫生行政部门应当将本行政区域内经备案开展限制类技术临床应用的医疗机构名单及相关信息及时向社会公布，接受社会监督。"},{"i":41,"n":"第四十一条","txt":"医疗机构违反本办法规定，有下列情形之一的，由县级以上地方卫生行政部门责令限期改正；逾期不改的，暂停或者停止相关医疗技术临床应用，给予警告，并处以三千元以下罚款；造成严重后果的，处以三千元以上三万元以下罚款，并对医疗机构主要负责人、负有责任的主管人员和其他直接责任人员依法给予处分： （一）未建立医疗技术临床应用管理专门组织或者未指定专（兼）职人员负责具体管理工作的； （二）未建立医疗技术临床应用管理相关规章制度的； （三）医疗技术临床应用管理混乱，存在医疗质量和医疗安全隐患的； （四）未按照要求向卫生行政部门进行医疗技术临床应用备案的； （五）未按照要求报告或者报告不实信息的； （六）未按照要求向国家和省级医疗技术临床应用信息化管理平台报送相关信息的； （七）未将相关信息纳入院务公开范围向社会公开的； （八）未按要求保障医务人员接受医疗技术临床应用规范化培训权益的。"},{"i":42,"n":"第四十二条","txt":"承担限制类技术临床应用规范化培训的医疗机构，有下列情形之一的，由省级卫生行政部门责令其停止医疗技术临床应用规范化培训，并向社会公布；造成严重后果的，对医疗机构主要负责人、负有责任的主管人员和其他直接责任人员依法给予处分： （一）未按照要求向省级卫生行政部门备案的； （二）提供不实备案材料或者弄虚作假的； （三）未按照要求开展培训、考核的； （四）管理混乱导致培训造成严重不良后果，并产生重大社会影响的。"},{"i":43,"n":"第四十三条","txt":"医疗机构有下列情形之一的，由县级以上地方卫生行政部门依据《医疗机构管理条例》第四十七条的规定进行处理；情节严重的，还应当对医疗机构主要负责人和其他直接责任人员依法给予处分： （一）开展相关医疗技术与登记的诊疗科目不相符的； （二）开展禁止类技术临床应用的； （三）不符合医疗技术临床应用管理规范要求擅自开展相关医疗技术的。"},{"i":44,"n":"第四十四条","txt":"医疗机构管理混乱导致医疗技术临床应用造成严重不良后果，并产生重大社会影响的，由县级以上地方卫生行政部门责令限期整改，并给予警告；逾期不改的，给予三万元以下罚款，并对医疗机构主要负责人、负有责任的主管人员和其他直接责任人员依法给予处分。"},{"i":45,"n":"第四十五条","txt":"医务人员有下列情形之一的，由县级以上地方卫生行政部门按照《执业医师法》《护士条例》《乡村医生从业管理条例》等法律法规的有关规定进行处理；构成犯罪的，依法追究刑事责任： （一）违反医疗技术管理相关规章制度或者医疗技术临床应用管理规范的； （二）开展禁止类技术临床应用的； （三）在医疗技术临床应用过程中，未按照要求履行知情同意程序的； （四）泄露患者隐私，造成严重后果的。"},{"i":46,"n":"第四十六条","txt":"县级以上地方卫生行政部门未按照本办法规定履行监管职责，造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予记大过、降级、撤职、开除等行政处分。"},{"i":47,"n":"第四十七条","txt":"人体器官移植技术、人类辅助生殖技术、细胞治疗技术的监督管理不适用本办法。"},{"i":48,"n":"第四十八条","txt":"省级卫生行政部门可以根据本办法，结合地方实际制定具体实施办法。"},{"i":49,"n":"第四十九条","txt":"本办法公布前，已经开展相关限制类技术临床应用的医疗机构，应当自本办法公布之日起按照本办法及相关医疗技术临床应用管理规范进行自我评估。符合临床应用条件的，应当自本办法施行之日起3个月内按照要求向核发其《医疗机构执业许可证》的卫生行政部门备案；不符合要求或者不按照规定备案的，不得再开展该项医疗技术临床应用。"},{"i":50,"n":"第五十条","txt":"中医医疗机构的医疗技术临床应用管理由中医药主管部门负责。"},{"i":51,"n":"第五十一条","txt":"本办法自2018年11月1日起施行。"}],"yiliaojigoulinchuangyongxueguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗机构临床用血管理，推进临床科学合理用血，保护血液资源，保障临床用血安全和医疗质量，根据《中华人民共和国献血法》，制定本办法。"},{"i":2,"n":"第二条","txt":"卫生部负责全国医疗机构临床用血的监督管理。县级以上地方人民政府卫生行政部门负责本行政区域医疗机构临床用血的监督管理。"},{"i":3,"n":"第三条","txt":"医疗机构应当加强临床用血管理，将其作为医疗质量管理的重要内容，完善组织建设，建立健全岗位责任制，制定并落实相关规章制度和技术操作规程。"},{"i":4,"n":"第四条","txt":"本办法适用于各级各类医疗机构的临床用血管理工作。"},{"i":5,"n":"第五条","txt":"卫生部成立临床用血专家委员会，其主要职责是： （一）协助制订国家临床用血相关制度、技术规范和标准； （二）协助指导全国临床用血管理和质量评价工作，促进提高临床合理用血水平； （三）协助临床用血重大安全事件的调查分析，提出处理意见； （四）承担卫生部交办的有关临床用血管理的其他任务。 卫生部建立协调机制，做好临床用血管理工作，提高临床合理用血水平，保证输血治疗质量。"},{"i":6,"n":"第六条","txt":"各省、自治区、直辖市人民政府卫生行政部门成立省级临床用血质量控制中心，负责辖区内医疗机构临床用血管理的指导、评价和培训等工作。"},{"i":7,"n":"第七条","txt":"医疗机构应当加强组织管理，明确岗位职责，健全管理制度。 医疗机构法定代表人为临床用血管理第一责任人。"},{"i":8,"n":"第八条","txt":"二级以上医院和妇幼保健院应当设立临床用血管理委员会，负责本机构临床合理用血管理工作。主任委员由院长或者分管医疗的副院长担任，成员由医务部门、输血科、麻醉科、开展输血治疗的主要临床科室、护理部门、手术室等部门负责人组成。医务、输血部门共同负责临床合理用血日常管理工作。 其他医疗机构应当设立临床用血管理工作组，并指定专（兼）职人员负责日常管理工作。"},{"i":9,"n":"第九条","txt":"临床用血管理委员会或者临床用血管理工作组应当履行以下职责： （一）认真贯彻临床用血管理相关法律、法规、规章、技术规范和标准，制订本机构临床用血管理的规章制度并监督实施； （二）评估确定临床用血的重点科室、关键环节和流程； （三）定期监测、分析和评估临床用血情况，开展临床用血质量评价工作，提高临床合理用血水平； （四）分析临床用血不良事件，提出处理和改进措施； （五）指导并推动开展自体输血等血液保护及输血新技术； （六）承担医疗机构交办的有关临床用血的其他任务。"},{"i":10,"n":"第十条","txt":"医疗机构应当根据有关规定和临床用血需求设置输血科或者血库，并根据自身功能、任务、规模，配备与输血工作相适应的专业技术人员、设施、设备。 不具备条件设置输血科或者血库的医疗机构，应当安排专（兼）职人员负责临床用血工作。"},{"i":11,"n":"第十一条","txt":"输血科及血库的主要职责是： （一）建立临床用血质量管理体系，推动临床合理用血； （二）负责制订临床用血储备计划，根据血站供血的预警信息和医院的血液库存情况协调临床用血； （三）负责血液预订、入库、储存、发放工作； （四）负责输血相关免疫血液学检测； （五）参与推动自体输血等血液保护及输血新技术； （六）参与特殊输血治疗病例的会诊，为临床合理用血提供咨询； （七）参与临床用血不良事件的调查； （八）根据临床治疗需要，参与开展血液治疗相关技术； （九）承担医疗机构交办的有关临床用血的其他任务。"},{"i":12,"n":"第十二条","txt":"医疗机构应当加强临床用血管理，建立并完善管理制度和工作规范，并保证落实。"},{"i":13,"n":"第十三条","txt":"医疗机构应当使用卫生行政部门指定血站提供的血液。 医疗机构科研用血由所在地省级卫生行政部门负责核准。 医疗机构应当配合血站建立血液库存动态预警机制，保障临床用血需求和正常医疗秩序。"},{"i":14,"n":"第十四条","txt":"医疗机构应当科学制订临床用血计划，建立临床合理用血的评价制度，提高临床合理用血水平。"},{"i":15,"n":"第十五条","txt":"医疗机构应当对血液预订、接收、入库、储存、出库及库存预警等进行管理，保证血液储存、运送符合国家有关标准和要求。"},{"i":16,"n":"第十六条","txt":"医疗机构接收血站发送的血液后，应当对血袋标签进行核对。符合国家有关标准和要求的血液入库，做好登记；并按不同品种、血型和采血日期（或有效期），分别有序存放于专用储藏设施内。 血袋标签核对的主要内容是： （一）血站的名称； （二）献血编号或者条形码、血型； （三）血液品种； （四）采血日期及时间或者制备日期及时间； （五）有效期及时间； （六）储存条件。 禁止将血袋标签不合格的血液入库。"},{"i":17,"n":"第十七条","txt":"医疗机构应当在血液发放和输血时进行核对，并指定医务人员负责血液的收领、发放工作。"},{"i":18,"n":"第十八条","txt":"医疗机构的储血设施应当保证运行有效，全血、红细胞的储藏温度应当控制在2-6℃，血小板的储藏温度应当控制在20-24℃。储血保管人员应当做好血液储藏温度的24小时监测记录。储血环境应当符合卫生标准和要求。"},{"i":19,"n":"第十九条","txt":"医务人员应当认真执行临床输血技术规范，严格掌握临床输血适应证，根据患者病情和实验室检测指标，对输血指证进行综合评估，制订输血治疗方案。"},{"i":20,"n":"第二十条","txt":"医疗机构应当建立临床用血申请管理制度。 同一患者一天申请备血量少于800毫升的，由具有中级以上专业技术职务任职资格的医师提出申请，上级医师核准签发后，方可备血。 同一患者一天申请备血量在800毫升至1600毫升的，由具有中级以上专业技术职务任职资格的医师提出申请，经上级医师审核，科室主任核准签发后，方可备血。 同一患者一天申请备血量达到或超过1600毫升的，由具有中级以上专业技术职务任职资格的医师提出申请，科室主任核准签发后，报医务部门批准，方可备血。 以上第二款、第三款和第四款规定不适用于急救用血。"},{"i":21,"n":"第二十一条","txt":"在输血治疗前，医师应当向患者或者其近亲属说明输血目的、方式和风险，并签署临床输血治疗知情同意书。 因抢救生命垂危的患者需要紧急输血，且不能取得患者或者其近亲属意见的，经医疗机构负责人或者授权的负责人批准后，可以立即实施输血治疗。"},{"i":22,"n":"第二十二条","txt":"医疗机构应当积极推行节约用血的新型医疗技术。 三级医院、有条件的二级医院和妇幼保健院应当开展自体输血技术，建立并完善管理制度和技术规范，提高合理用血水平，保证医疗质量和安全。 医疗机构应当动员符合条件的患者接受自体输血技术，提高输血治疗效果和安全性。"},{"i":23,"n":"第二十三条","txt":"医疗机构应当积极推行成分输血，保证医疗质量和安全。"},{"i":24,"n":"第二十四条","txt":"医疗机构应当将无偿献血纳入健康教育内容，积极主动向患者、家属及社会广泛宣传，鼓励健康适龄公民自愿参加无偿献血，提升群众对无偿献血的知晓度和参与度。"},{"i":25,"n":"第二十五条","txt":"医疗机构应当根据国家有关法律法规和规范建立临床用血不良事件监测报告制度。临床发现输血不良反应后，应当积极救治患者，及时向有关部门报告，并做好观察和记录。"},{"i":26,"n":"第二十六条","txt":"各省、自治区、直辖市人民政府卫生行政部门应当制订临床用血保障措施和应急预案，保证自然灾害、突发事件等大量伤员和特殊病例、稀缺血型等应急用血的供应和安全。 因应急用血或者避免血液浪费，在保证血液安全的前提下，经省、自治区、直辖市人民政府卫生行政部门核准，医疗机构之间可以调剂血液。具体方案由省级卫生行政部门制订。"},{"i":27,"n":"第二十七条","txt":"省、自治区、直辖市人民政府卫生行政部门应当加强边远地区医疗机构临床用血保障工作，科学规划和建设中心血库与储血点。 医疗机构应当制订应急用血工作预案。为保证应急用血，医疗机构可以临时采集血液，但必须同时符合以下条件： （一）危及患者生命，急需输血； （二）所在地血站无法及时提供血液，且无法及时从其他医疗机构调剂血液，而其他医疗措施不能替代输血治疗； （三）具备开展交叉配血及乙型肝炎病毒表面抗原、丙型肝炎病毒抗体、艾滋病病毒抗体和梅毒螺旋体抗体的检测能力； （四）遵守采供血相关操作规程和技术标准。 医疗机构应当在临时采集血液后10日内将情况报告县级以上人民政府卫生行政部门。"},{"i":28,"n":"第二十八条","txt":"医疗机构应当建立临床用血医学文书管理制度，确保临床用血信息客观真实、完整、可追溯。医师应当将患者输血适应证的评估、输血过程和输血后疗效评价情况记入病历；临床输血治疗知情同意书、输血记录单等随病历保存。"},{"i":29,"n":"第二十九条","txt":"医疗机构应当建立培训制度，加强对医务人员临床用血和无偿献血知识的培训，将临床用血相关知识培训纳入继续教育内容。新上岗医务人员应当接受岗前临床用血相关知识培训及考核。"},{"i":30,"n":"第三十条","txt":"医疗机构应当建立科室和医师临床用血评价及公示制度。将临床用血情况纳入科室和医务人员工作考核指标体系。 禁止将用血量和经济收入作为输血科或者血库工作的考核指标。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府卫生行政部门应当加强对本行政区域内医疗机构临床用血情况的督导检查。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府卫生行政部门应当建立医疗机构临床用血评价制度，定期对医疗机构临床用血工作进行评价。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府卫生行政部门应当建立临床合理用血情况排名、公布制度。对本行政区域内医疗机构临床用血量和不合理使用等情况进行排名，将排名情况向本行政区域内的医疗机构公布，并报上级卫生行政部门。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府卫生行政部门应当将医疗机构临床用血情况纳入医疗机构考核指标体系；将临床用血情况作为医疗机构评审、评价重要指标。"},{"i":35,"n":"第三十五条","txt":"医疗机构有下列情形之一的，由县级以上人民政府卫生行政部门责令限期改正；逾期不改的，进行通报批评，并予以警告；情节严重或者造成严重后果的，可处3万元以下的罚款，对负有责任的主管人员和其他直接责任人员依法给予处分： （一）未设立临床用血管理委员会或者工作组的； （二）未拟定临床用血计划或者一年内未对计划实施情况进行评估和考核的； （三）未建立血液发放和输血核对制度的； （四）未建立临床用血申请管理制度的； （五）未建立医务人员临床用血和无偿献血知识培训制度的； （六）未建立科室和医师临床用血评价及公示制度的； （七）将经济收入作为对输血科或者血库工作的考核指标的； （八）违反本办法的其他行为。"},{"i":36,"n":"第三十六条","txt":"医疗机构使用未经卫生行政部门指定的血站供应的血液的，由县级以上地方人民政府卫生行政部门给予警告，并处3万元以下罚款；情节严重或者造成严重后果的，对负有责任的主管人员和其他直接责任人员依法给予处分。"},{"i":37,"n":"第三十七条","txt":"医疗机构违反本办法关于应急用血采血规定的，由县级以上人民政府卫生行政部门责令限期改正，给予警告；情节严重或者造成严重后果的，处3万元以下罚款，对负有责任的主管人员和其他直接责任人员依法给予处分。"},{"i":38,"n":"第三十八条","txt":"医疗机构及其医务人员违反本法规定，将不符合国家规定标准的血液用于患者的，由县级以上地方人民政府卫生行政部门责令改正；给患者健康造成损害的，应当依据国家有关法律法规进行处理，并对负有责任的主管人员和其他直接责任人员依法给予处分。"},{"i":39,"n":"第三十九条","txt":"县级以上地方卫生行政部门未按照本办法规定履行监管职责，造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予记大过、降级、撤职、开除等行政处分。"},{"i":40,"n":"第四十条","txt":"医疗机构及其医务人员违反临床用血管理规定，构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本办法自2012年8月1日起施行。卫生部于1999年1月5日公布的《医疗机构临床用血管理办法（试行）》同时废止。"}],"yiliaojigouchuanranbingyujianfenzhenguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范医疗机构传染病预检、分诊工作，有效控制传染病疫情，防止医疗机构内交叉感染，保障人民群众身体健康和生命安全，根据《中华人民共和国传染病防治法》第五十二条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"医疗机构应当建立传染病预检、分诊制度。 二级以上综合医院应当设立感染性疾病科，具体负责本医疗机构传染病的分诊工作，并对本医疗机构的传染病预检、分诊工作进行组织管理。 没有设立感染性疾病科的医疗机构应当设立传染病分诊点。 感染性疾病科和分诊点应当标识明确，相对独立，通风良好，流程合理，具有消毒隔离条件和必要的防护用品。"},{"i":3,"n":"第三条","txt":"医疗机构各科室的医师在接诊过程中，应当注意询问病人有关的流行病学史、职业史，结合病人的主诉、病史、症状和体征等对来诊的病人进行传染病的预检。 经预检为传染病病人或者疑似传染病病人的，应当将病人分诊至感染性疾病科或者分诊点就诊，同时对接诊处采取必要的消毒措施。"},{"i":4,"n":"第四条","txt":"医疗机构应当根据传染病的流行季节、周期和流行趋势做好特定传染病的预检、分诊工作。 医疗机构应当在接到卫生部和省、自治区、直辖市人民政府发布特定传染病预警信息后，或者按照当地卫生行政部门的要求，加强特定传染病的预检、分诊工作。必要时，设立相对独立的针对特定传染病的预检处，引导就诊病人首先到预检处检诊，初步排除特定传染病后，再到相应的普通科室就诊。"},{"i":5,"n":"第五条","txt":"对呼吸道等特殊传染病病人或者疑似病人，医疗机构应当依法采取隔离或者控制传播措施，并按照规定对病人的陪同人员和其他密切接触人员采取医学观察和其他必要的预防措施。"},{"i":6,"n":"第六条","txt":"医疗机构不具备传染病救治能力时，应当及时将病人转诊到具备救治能力的医疗机构诊疗，并将病历资料复印件转至相应的医疗机构。"},{"i":7,"n":"第七条","txt":"转诊传染病病人或疑似传染病病人时，应当按照当地卫生行政部门的规定使用专用车辆。"},{"i":8,"n":"第八条","txt":"感染性疾病科和分诊点应当采取标准防护措施，按照规范严格消毒，并按照《医疗废物管理条例》的规定处理医疗废物。"},{"i":9,"n":"第九条","txt":"医疗机构应当定期对医务人员进行传染病防治知识的培训，培训应当包括传染病防治的法律、法规以及传染病流行动态、诊断、治疗、预防、职业暴露的预防和处理等内容。 从事传染病预检、分诊的医务人员应当严格遵守卫生管理法律、法规和有关规定，认真执行临床技术操作规范、常规以及有关工作制度。"},{"i":10,"n":"第十条","txt":"各级卫生行政部门应当加强对医疗机构预检分诊工作的监督管理，对违反《中华人民共和国传染病防治法》等有关法律、法规和本办法的，应当依法查处。"},{"i":11,"n":"第十一条","txt":"本办法自发布之日起施行。"}],"yiliaojigoutousuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗机构投诉管理，规范投诉处理程序，改善医疗服务，保障医疗安全和医患双方合法权益，维护正常医疗秩序，根据《医疗纠纷预防和处理条例》、《医疗机构管理条例》等法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称投诉管理，是指患者就医疗服务行为、医疗管理、医疗质量安全等方面存在的问题向医疗机构反映情况，提出意见、建议或者投诉请求，医疗机构进行调查、处理和结果反馈的活动。"},{"i":3,"n":"第三条","txt":"本办法适用于各级各类医疗机构的投诉管理。"},{"i":4,"n":"第四条","txt":"国家卫生健康委负责全国医疗机构投诉管理工作的监督指导。 县级以上地方卫生健康主管部门负责本行政区域内医疗机构投诉管理工作的监督指导。"},{"i":5,"n":"第五条","txt":"医疗机构投诉的接待、处理工作应当贯彻“以患者为中心”的理念，遵循合法、公正、及时、便民的原则。"},{"i":6,"n":"第六条","txt":"医疗机构应当按照规定做好信息公开工作，主动接受社会监督。"},{"i":7,"n":"第七条","txt":"医疗机构应当提高管理水平，加强医疗风险管理，优化服务流程，改善就诊环境，提高医疗服务质量，防范安全隐患，减少医疗纠纷及投诉。"},{"i":8,"n":"第八条","txt":"医疗机构应当制订重大医疗纠纷事件应急处置预案，组织开展相关的宣传、培训和演练，确保依法、及时、有效化解矛盾纠纷。"},{"i":9,"n":"第九条","txt":"医疗机构应当将投诉管理纳入患者安全管理体系，定期汇总、分析投诉信息，梳理医疗管理、医疗质量安全的薄弱环节，落实整改措施，持续改进医疗质量安全。"},{"i":10,"n":"第十条","txt":"医疗机构应当做好医疗机构投诉管理与医疗纠纷人民调解、行政调解、诉讼等的衔接。"},{"i":11,"n":"第十一条","txt":"医疗机构主要负责人是医疗机构投诉管理的第一责任人。 二级以上医疗机构应当设置医患关系办公室或者指定部门（以下统称投诉管理部门）统一承担投诉管理工作。其他医疗机构应当配备专（兼）职人员，有条件的也可以设置投诉管理部门。"},{"i":12,"n":"第十二条","txt":"二级以上医疗机构应当指定一名医疗机构负责人分管投诉工作，指导、管理医疗机构投诉管理部门的有关工作。 投诉管理部门履行以下职责： （一）组织、协调、指导本医疗机构的投诉处理工作； （二）统一受理投诉，调查、核实投诉事项，提出处理意见，及时答复患者； （三）建立和完善投诉的接待和处置程序； （四）参与医疗机构医疗质量安全管理； （五）开展医患沟通及投诉处理培训，开展医疗风险防范教育； （六）定期汇总、分析投诉信息，提出加强与改进工作的意见或者建议，并加强督促落实。 仅配备投诉专（兼）职人员的医疗机构，投诉专（兼）职人员应当至少承担前款第二项职责。"},{"i":13,"n":"第十三条","txt":"医疗机构投诉管理人员应当具备以下条件： （一）具备良好的职业道德和工作责任心； （二）具备一定的医学、管理学、法学、心理学、伦理学、社会工作等学科知识，熟悉医疗和投诉管理相关法律法规，以及医疗机构规章制度； （三）社会适应能力较强，具有良好的社会人际交往能力，具备良好的沟通能力和应变能力。"},{"i":14,"n":"第十四条","txt":"二级以上医疗机构应当建立医疗机构、投诉管理部门、科室三级投诉管理机制，医疗机构各部门、各科室应当指定至少1名负责人配合做好投诉管理工作。 医疗机构各部门、各科室应当定期对投诉涉及的风险进行评估，对投诉隐患进行摸排，对高发隐患提出针对性的防范措施，加强与患者沟通，及时做好矛盾纠纷排查化解工作。 医疗机构应当鼓励工作人员主动收集患者对医疗服务、医疗质量安全等方面的意见和建议，通过规定途径向投诉管理部门或者有关职能部门反映。"},{"i":15,"n":"第十五条","txt":"二级以上医疗机构应当健全投诉管理部门与临床、护理、医技和后勤、保卫等部门的联动机制，提高医疗质量，保障医疗安全，维护正常医疗秩序。"},{"i":16,"n":"第十六条","txt":"医疗机构应当逐步建立健全相关机制，鼓励和吸纳社会工作者、志愿者等熟悉医学、法律专业知识的人员或者第三方组织参与医疗机构投诉接待与处理工作。"},{"i":17,"n":"第十七条","txt":"医疗机构应当提高医务人员职业道德水平，增强服务意识和法律意识，注重人文关怀，加强医患沟通，努力构建和谐医患关系。"},{"i":18,"n":"第十八条","txt":"医务人员应当恪守职业道德，以患者为中心，热情、耐心、细致地做好本职工作，把对患者的尊重、理解和关怀体现在医疗服务全过程。"},{"i":19,"n":"第十九条","txt":"医疗机构应当建立健全医患沟通机制，完善医患沟通内容，加强对医务人员医患沟通技巧的培训，提高医患沟通能力。 医务人员对患者在诊疗过程中提出的咨询、意见和建议，应当耐心解释、说明，并按照规定进行处理；对患者就诊疗行为提出的疑问，应当及时予以核实、自查，并与患者沟通，如实说明情况。"},{"i":20,"n":"第二十条","txt":"医务人员应当尊重患者依法享有的隐私权、知情权、选择权等权利，根据患者病情、预后不同以及患者实际需求，突出重点，采取适当方式进行沟通。 医患沟通中有关诊疗情况的重要内容应当及时、完整、准确记入病历，并由患者签字确认。"},{"i":21,"n":"第二十一条","txt":"医疗机构可以结合实际情况，制定医疗风险告知和术前谈话制度，规范具体流程，以患者易懂的方式和语言充分告知患者，并取得其书面同意。"},{"i":22,"n":"第二十二条","txt":"医疗机构应当建立畅通、便捷的投诉渠道，在医疗机构显著位置公布投诉处理程序、地点、接待时间和联系方式。 鼓励医疗机构加强舆情监测，及时掌握患者在其他渠道的诉求。"},{"i":23,"n":"第二十三条","txt":"医疗机构应当设置专门的投诉接待场所，接待场所应当提供有关法律、法规、投诉程序等资料，便于患者查询。 医疗机构应当采取措施，保障投诉管理工作人员的合法权益与人身安全。"},{"i":24,"n":"第二十四条","txt":"医疗机构投诉实行“首诉负责制”，患者向有关部门、科室投诉的，接待投诉的部门、科室工作人员应当热情接待，对于能够当场协调处理的，应当尽量当场协调解决；对于无法当场协调处理的，接待的部门或者科室应当主动将患者引导到投诉管理部门（含投诉管理专（兼）职人员，下同），不得推诿、搪塞。"},{"i":25,"n":"第二十五条","txt":"投诉接待人员应当认真听取患者意见，耐心细致地做好解释工作，避免矛盾激化；应当核实相关信息，如实记录患者反映的情况，及时留存书面投诉材料。"},{"i":26,"n":"第二十六条","txt":"患者应当依法文明表达意见和要求，向医疗机构投诉管理部门提供真实、准确的投诉相关资料，配合医疗机构投诉管理部门的调查和询问，不得扰乱正常医疗秩序，不得有违法犯罪行为。 单次投诉人员数量原则上不超过5人。超过5人的，应当推选代表集中反映诉求。"},{"i":27,"n":"第二十七条","txt":"投诉接待人员在接待场所发现患者有自杀、自残和其他过激行为，或者侮辱、殴打、威胁投诉接待人员的行为，应当及时采取控制和防范措施，同时向公安机关报警，并向当地卫生健康主管部门报告；对接待过程中发现的可能激化矛盾，引起治安案件、刑事案件的投诉，应当及时向当地公安机关报告，依法处理。"},{"i":28,"n":"第二十八条","txt":"医疗机构投诉管理部门接到投诉或者卫生健康主管部门交办的投诉后，应当及时向当事部门、科室和相关人员了解、核实情况，在查清事实、分清责任的基础上提出处理意见，并反馈患者。 投诉涉及的部门、科室和相关人员应当积极配合投诉管理部门开展投诉事项调查、核实、处理工作。"},{"i":29,"n":"第二十九条","txt":"对反复接到相同或者相似问题的投诉，医疗机构投诉管理部门应当汇总并报告医疗机构负责人，医疗机构对有关投诉可视情况予以合并调查，对发现的引发投诉的环节或者多次引发投诉的医务人员应当根据调查结果，及时予以相应处理。"},{"i":30,"n":"第三十条","txt":"医疗机构投诉管理部门应当及时处理投诉，能够当场核查处理的，应当及时查明情况；确有差错的，立即纠正，并当场向患者告知处理意见。 涉及医疗质量安全、可能危及患者健康的，应当立即采取积极措施，避免或者减轻对患者身体健康的损害，防止损害扩大。 情况较复杂，需调查、核实的，一般应当于接到投诉之日起5个工作日内向患者反馈相关处理情况或者处理意见。 涉及多个科室，需组织、协调相关部门共同研究的，应当于接到投诉之日起10个工作日内向患者反馈处理情况或者处理意见。"},{"i":31,"n":"第三十一条","txt":"对投诉已经处理完毕，患者对医疗机构的处理意见有争议并能够提供新情况和证据材料的，按照投诉流程重新予以处理。"},{"i":32,"n":"第三十二条","txt":"投诉内容涉及医疗纠纷的，医疗机构应当告知患者按照医疗纠纷处理的相关法律法规的规定，积极协商；不能协商解决的，引导患者通过调解、诉讼等途径解决，并做好解释疏导工作。"},{"i":33,"n":"第三十三条","txt":"投诉涉及医疗机构工作人员违法违纪问题的，投诉管理部门应当及时移交相关职能部门依法依规处理。"},{"i":34,"n":"第三十四条","txt":"属于下列情形之一的投诉，投诉管理部门不予处理，但应当向患者说明情况，告知相关处理规定： （一）患者已就投诉事项向人民法院起诉的或者向第三方申请调解的； （二）患者已就投诉事项向卫生健康主管部门或者信访部门反映并作出处理的； （三）没有明确的投诉对象和具体事实的； （四）投诉内容已经涉及治安案件、刑事案件的； （五）其他不属于投诉管理部门职权范围的投诉。"},{"i":35,"n":"第三十五条","txt":"发生重大医疗纠纷的，医疗机构应当按照规定向所在地县级以上地方卫生健康主管部门报告。卫生健康主管部门接到报告后，应当及时了解掌握情况，引导医患双方通过合法途径解决纠纷。"},{"i":36,"n":"第三十六条","txt":"医疗机构应当保护与投诉相关的患者和医务人员隐私，妥善应对舆情，严禁发布违背或者夸大事实、渲染投诉处理过程的信息。"},{"i":37,"n":"第三十七条","txt":"医疗机构应当建立健全投诉档案，立卷归档，留档备查。 医疗机构投诉档案应当包括以下内容： （一）患者基本信息； （二）投诉事项及相关证明材料； （三）调查、处理及反馈情况； （四）其他与投诉事项有关的材料。"},{"i":38,"n":"第三十八条","txt":"医疗机构工作人员有权对医疗机构管理、服务等各项工作提出意见、建议，医疗机构及投诉管理等有关部门应当予以重视，并及时处理、反馈。 临床一线工作人员，对于发现的药品、医疗器械、水、电、气等医疗质量安全保障方面的问题，应当向投诉管理部门或者有关职能部门反映，投诉管理等有关部门应当及时处理、反馈。"},{"i":39,"n":"第三十九条","txt":"县级以上地方卫生健康主管部门应当加强对本行政区域内医疗机构投诉管理工作的监督检查，加强日常管理和考评。"},{"i":40,"n":"第四十条","txt":"县级以上地方卫生健康主管部门应当收集、分析并反馈本行政区域医疗机构投诉及医疗纠纷相关信息，指导医疗机构改进工作，提高医疗服务质量。"},{"i":41,"n":"第四十一条","txt":"对在医疗机构投诉管理中表现优秀、有效预防重大群体性事件或者其他严重后果发生的医疗机构及有关人员，卫生健康主管部门应当予以表扬。 对行政区域内未按照规定开展投诉管理工作的医疗机构，卫生健康主管部门应当通报批评，并对医疗机构主要负责人进行约谈。"},{"i":42,"n":"第四十二条","txt":"医疗机构应当规范投诉管理工作，定期统计投诉情况，统计结果应当与年终考核、医师定期考核、医德考评、评优评先等相结合。"},{"i":43,"n":"第四十三条","txt":"医疗机构未建立投诉接待制度、未设置统一投诉管理部门或者配备专（兼）职人员，或者未按规定向卫生健康主管部门报告重大医疗纠纷的，由县级以上地方卫生健康主管部门按照《医疗纠纷预防和处理条例》第四十七条的规定进行处理。"},{"i":44,"n":"第四十四条","txt":"医疗机构违反本办法规定，有下列情形之一的，由县级以上地方卫生健康主管部门责令限期整改；逾期不改的，给予警告，并处以一万元以下罚款；造成严重后果的，处以一万元以上三万元以下罚款，并对医疗机构主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分： （一）未制订重大医疗纠纷事件应急处置预案的； （二）投诉管理混乱的； （三）未按规定建立健全医患沟通机制的； （四）未按规定及时处理投诉并反馈患者的； （五）对接待过程中发现的可能激化矛盾，引起治安案件、刑事案件的投诉，未及时向当地公安机关报告的； （六）发布违背或者夸大事实、渲染事件处理过程的信息的。"},{"i":45,"n":"第四十五条","txt":"医务人员泄露投诉相关患者隐私，造成严重后果的，由县级以上地方卫生健康主管部门按照《执业医师法》、《护士条例》等法律法规的有关规定处理。"},{"i":46,"n":"第四十六条","txt":"县级以上地方卫生健康主管部门在医疗机构投诉管理工作中，未按规定履行职责，造成严重后果的，依法对直接负责的主管人员和其他直接责任人员给予处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"本办法所称患者，包括患者及其近亲属、委托代理人、法定代理人、陪同患者就医人员等有关人员。"},{"i":48,"n":"第四十八条","txt":"省级卫生健康主管部门可以根据本办法，结合本地具体情况制订实施细则。"},{"i":49,"n":"第四十九条","txt":"中医医疗机构的投诉管理工作由中医药主管部门负责。"},{"i":50,"n":"第五十条","txt":"本办法自2019年4月10日起施行。"}],"yiliaojigouguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《医疗机构管理条例》（以下简称条例）制定本细则。"},{"i":2,"n":"第二条","txt":"条例及本细则所称医疗机构，是指依据条例和本细则的规定，经登记取得《医疗机构执业许可证》的机构。"},{"i":3,"n":"第三条","txt":"医疗机构的类别： （一）综合医院、中医医院、中西医结合医院、民族医医院、专科医院、康复医院； （二）妇幼保健院、妇幼保健计划生育服务中心； （三）社区卫生服务中心、社区卫生服务站； （四）中心卫生院、乡（镇）卫生院、街道卫生院； （五）疗养院； （六）综合门诊部、专科门诊部、中医门诊部、中西医结合门诊部、民族医门诊部； （七）诊所、中医诊所、民族医诊所、卫生所、医务室、卫生保健所、卫生站； （八）村卫生室（所）； （九）急救中心、急救站； （十）临床检验中心； （十一）专科疾病防治院、专科疾病防治所、专科疾病防治站； （十二）护理院、护理站； （十三）医学检验实验室、病理诊断中心、医学影像诊断中心、血液透析中心、安宁疗护中心； （十四）其他诊疗机构。"},{"i":4,"n":"第四条","txt":"卫生防疫、国境卫生检疫、医学科研和教学等机构在本机构业务范围之外开展诊疗活动以及美容服务机构开展医疗美容业务的，必须依据条例及本细则，申请设置相应类别的医疗机构。"},{"i":5,"n":"第五条","txt":"中国人民解放军和中国人民武装警察部队编制外的医疗机构，由地方卫生计生行政部门按照条例和本细则管理。 中国人民解放军后勤卫生主管部门负责向地方卫生计生行政部门提供军队编制外医疗机构的名称和地址。"},{"i":6,"n":"第六条","txt":"医疗机构依法从事诊疗活动受法律保护。"},{"i":7,"n":"第七条","txt":"卫生计生行政部门依法独立行使监督管理职权，不受任何单位和个人干涉。"},{"i":8,"n":"第八条","txt":"各省、自治区、直辖市应当按照当地《医疗机构设置规划》合理配置和合理利用医疗资源。 《医疗机构设置规划》由县级以上地方卫生计生行政部门依据《医疗机构设置规划指导原则》制定，经上一级卫生计生行政部门审核，报同级人民政府批准，在本行政区域内发布实施。 《医疗机构设置规划指导原则》另行制定。"},{"i":9,"n":"第九条","txt":"县级以上地方卫生计生行政部门按照《医疗机构设置规划指导原则》规定的权限和程序组织实施本行政区域《医疗机构设置规划》，定期评价实施情况，并将评价结果按年度向上一级卫生计生行政部门和同级人民政府报告。"},{"i":10,"n":"第十条","txt":"医疗机构不分类别、所有制形式、隶属关系、服务对象，其设置必须符合当地《医疗机构设置规划》。"},{"i":11,"n":"第十一条","txt":"床位在一百张以上的综合医院、中医医院、中西医结合医院、民族医医院以及专科医院、疗养院、康复医院、妇幼保健院、急救中心、临床检验中心和专科疾病防治机构的设置审批权限的划分，由省、自治区、直辖市卫生计生行政部门规定；其他医疗机构的设置，由县级卫生计生行政部门负责审批。 医学检验实验室、病理诊断中心、医学影像诊断中心、血液透析中心、安宁疗护中心的设置审批权限另行规定。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，不得申请设置医疗机构： （一）不能独立承担民事责任的单位； （二）正在服刑或者不具有完全民事行为能力的个人； （三）发生二级以上医疗事故未满五年的医务人员； （四）因违反有关法律、法规和规章，已被吊销执业证书的医务人员； （五）被吊销《医疗机构执业许可证》的医疗机构法定代表人或者主要负责人； （六）省、自治区、直辖市政府卫生计生行政部门规定的其他情形。 有前款第（二）、（三）、（四）、（五）项所列情形之一者，不得充任医疗机构的法定代表人或者主要负责人。"},{"i":13,"n":"第十三条","txt":"在城市设置诊所的个人，必须同时具备下列条件： （一）经医师执业技术考核合格，取得《医师执业证书》； （二）取得《医师执业证书》或者医师职称后，从事五年以上同一专业的临床工作； （三）省、自治区、直辖市卫生计生行政部门规定的其他条件。 医师执业技术标准另行制定。 在乡镇和村设置诊所的个人的条件，由省、自治区、直辖市卫生计生行政部门规定。"},{"i":14,"n":"第十四条","txt":"地方各级人民政府设置医疗机构，由政府指定或者任命的拟设医疗机构的筹建负责人申请；法人或者其他组织设置医疗机构，由其代表人申请；个人设置医疗机构，由设置人申请；两人以上合伙设置医疗机构，由合伙人共同申请。"},{"i":15,"n":"第十五条","txt":"条例第十条规定提交的设置可行性研究报告包括以下内容： （一）申请单位名称、基本情况以及申请人姓名、年龄、专业履历、身份证号码； （二）所在地区的人口、经济和社会发展等概况； （三）所在地区人群健康状况和疾病流行以及有关疾病患病率； （四）所在地区医疗资源分布情况以及医疗服务需求分析； （五）拟设医疗机构的名称、选址、功能、任务、服务半径； （六）拟设医疗机构的服务方式、时间、诊疗科目和床位编制； （七）拟设医疗机构的组织结构、人员配备； （八）拟设医疗机构的仪器、设备配备； （九）拟设医疗机构与服务半径区域内其他医疗机构的关系和影响； （十）拟设医疗机构的污水、污物、粪便处理方案； （十一）拟设医疗机构的通讯、供电、上下水道、消防设施情况； （十二）资金来源、投资方式、投资总额、注册资金（资本）； （十三）拟设医疗机构的投资预算； （十四）拟设医疗机构五年内的成本效益预测分析。 并附申"},{"i":16,"n":"第十六条","txt":"条例第十条规定提交的选址报告包括以下内容： （一）选址的依据； （二）选址所在地区的环境和公用设施情况； （三）选址与周围托幼机构、中小学校、食品生产经营单位布局的关系； （四）占地和建筑面积。"},{"i":17,"n":"第十七条","txt":"由两个以上法人或者其他组织共同申请设置医疗机构以及由两人以上合伙申请设置医疗机构的，除提交可行性研究报告和选址报告外，还必须提交由各方共同签署的协议书。"},{"i":18,"n":"第十八条","txt":"医疗机构建筑设计必须按照法律、法规和规章要求经相关审批机关审查同意后，方可施工。"},{"i":19,"n":"第十九条","txt":"条例第十二条规定的设置申请的受理时间，自申请人提供条例和本细则规定的全部材料之日算起。"},{"i":20,"n":"第二十条","txt":"县级以上地方卫生计生行政部门依据当地《医疗机构设置规划》及本细则审查和批准医疗机构的设置。 申请设置医疗机构有下列情形之一的，不予批准： （一）不符合当地《医疗机构设置规划》； （二）设置人不符合规定的条件； （三）不能提供满足投资总额的资信证明； （四）投资总额不能满足各项预算开支； （五）医疗机构选址不合理； （六）污水、污物、粪便处理方案不合理； （七）省、自治区、直辖市卫生计生行政部门规定的其他情形。"},{"i":21,"n":"第二十一条","txt":"卫生计生行政部门应当在核发《设置医疗机构批准书》的同时，向上一级卫生计生行政部门备案。 上级卫生计生行政部门有权在接到备案报告之日起三十日内纠正或者撤销下级卫生计生行政部门作出的不符合当地《医疗机构设置规划》的设置审批。"},{"i":22,"n":"第二十二条","txt":"《设置医疗机构批准书》的有效期，由省、自治区、直辖市卫生计生行政部门规定。"},{"i":23,"n":"第二十三条","txt":"变更《设置医疗机构批准书》中核准的医疗机构的类别、规模、选址和诊疗科目，必须按照条例和本细则的规定，重新申请办理设置审批手续。"},{"i":24,"n":"第二十四条","txt":"法人和其他组织设置的为内部职工服务的门诊部、诊所、卫生所（室），由设置单位在该医疗机构执业登记前，向当地县级卫生计生行政部门备案，并提交下列材料： （一）设置单位或者其主管部门设置医疗机构的决定； （二）《设置医疗机构备案书》。 卫生计生行政部门应当在接到备案后十五日内给予《设置医疗机构备案回执》。"},{"i":25,"n":"第二十五条","txt":"申请医疗机构执业登记必须填写《医疗机构申请执业登记注册书》，并向登记机关提交下列材料： （一）《设置医疗机构批准书》或者《设置医疗机构备案回执》； （二）医疗机构用房产权证明或者使用证明； （三）医疗机构建筑设计平面图； （四）验资证明、资产评估报告； （五）医疗机构规章制度； （六）医疗机构法定代表人或者主要负责人以及各科室负责人名录和有关资格证书、执业证书复印件； （七）省、自治区、直辖市卫生计生行政部门规定提交的其他材料。 申请门诊部、诊所、卫生所、医务室、卫生保健所和卫生站登记的，还应当提交附设药房（柜）的药品种类清单、卫生技术人员名录及其有关资格证书、执业证书复印件以及省、自治区、直辖市卫生计生行政部门规定提交的其他材料。"},{"i":26,"n":"第二十六条","txt":"登记机关在受理医疗机构执业登记申请后，应当按照条例第十六条规定的条件和条例第十九条规定的时限进行审查和实地考察、核实，并对有关执业人员进行消毒、隔离和无菌操作等基本知识和技能的现场抽查考核。经审核合格的，发给《医疗机构执业许可证》；审核不合格的，将审核结果和不予批准的理由以书面形式通知申请人。 《医疗机构执业许可证》及其副本由国家卫生计生委统一印制。 条例第十九条规定的执业登记申请的受理时间，自申请人提供条例和本细则规定的全部材料之日算起。"},{"i":27,"n":"第二十七条","txt":"申请医疗机构执业登记有下列情形之一的，不予登记： （一）不符合《设置医疗机构批准书》核准的事项； （二）不符合《医疗机构基本标准》； （三）投资不到位； （四）医疗机构用房不能满足诊疗服务功能； （五）通讯、供电、上下水道等公共设施不能满足医疗机构正常运转； （六）医疗机构规章制度不符合要求； （七）消毒、隔离和无菌操作等基本知识和技能的现场抽查考核不合格； （八）省、自治区、直辖市卫生计生行政部门规定的其他情形。"},{"i":28,"n":"第二十八条","txt":"医疗机构执业登记的事项： （一）类别、名称、地址、法定代表人或者主要负责人； （二）所有制形式； （三）注册资金（资本）； （四）服务方式； （五）诊疗科目； （六）房屋建筑面积、床位（牙椅）； （七）服务对象； （八）职工人数； （九）执业许可证登记号（医疗机构代码）； （十）省、自治区、直辖市卫生计生行政部门规定的其他登记事项。 门诊部、诊所、卫生所、医务室、卫生保健所、卫生站除登记前款所列事项外，还应当核准登记附设药房（柜）的药品种类。《医疗机构诊疗科目名录》另行制定。"},{"i":29,"n":"第二十九条","txt":"因分立或者合并而保留的医疗机构应当申请变更登记；因分立或者合并而新设置的医疗机构应当申请设置许可和执业登记；因合并而终止的医疗机构应当申请注销登记。"},{"i":30,"n":"第三十条","txt":"医疗机构变更名称、地址、法定代表人或者主要负责人、所有制形式、服务对象、服务方式、注册资金（资本）、诊疗科目、床位（牙椅）的，必须向登记机关申请办理变更登记，并提交下列材料： （一）医疗机构法定代表人或者主要负责人签署的《医疗机构申请变更登记注册书》； （二）申请变更登记的原因和理由； （三）登记机关规定提交的其他材料。"},{"i":31,"n":"第三十一条","txt":"机关、企业和事业单位设置的为内部职工服务的医疗机构向社会开放，必须按照前条规定申请办理变更登记。"},{"i":32,"n":"第三十二条","txt":"医疗机构在原登记机关管辖权限范围内变更登记事项的，由原登记机关办理变更登记；因变更登记超出原登记机关管辖权限的，由有管辖权的卫生计生行政部门办理变更登记。 医疗机构在原登记机关管辖区域内迁移，由原登记机关办理变更登记；向原登记机关管辖区域外迁移的，应当在取得迁移目的地的卫生计生行政部门发给的《设置医疗机构批准书》，并经原登记机关核准办理注销登记后，再向迁移目的地的卫生计生行政部门申请办理执业登记。"},{"i":33,"n":"第三十三条","txt":"登记机关在受理变更登记申请后，依据条例和本细则的有关规定以及当地《医疗机构设置规划》进行审核，按照登记程序或者简化程序办理变更登记，并作出核准变更登记或者不予变更登记的决定。"},{"i":34,"n":"第三十四条","txt":"医疗机构停业，必须经登记机关批准。除改建、扩建、迁建原因，医疗机构停业不得超过一年。"},{"i":35,"n":"第三十五条","txt":"床位在一百张以上的综合医院、中医医院、中西医结合医院、民族医医院以及专科医院、疗养院、康复医院、妇幼保健院、急救中心、临床检验中心和专科疾病防治机构的校验期为三年；其他医疗机构的校验期为一年。 医疗机构应当于校验期满前三个月向登记机关申请办理校验手续。 办理校验应当交验《医疗机构执业许可证》，并提交下列文件： （一）《医疗机构校验申请书》； （二）《医疗机构执业许可证》副本； （三）省、自治区、直辖市卫生计生行政部门规定提交的其他材料。"},{"i":36,"n":"第三十六条","txt":"卫生计生行政部门应当在受理校验申请后的三十日内完成校验。"},{"i":37,"n":"第三十七条","txt":"医疗机构有下列情形之一的，登记机关可以根据情况，给予一至六个月的暂缓校验期： （一）不符合《医疗机构基本标准》； （二）限期改正期间； （三）省、自治区、直辖市卫生计生行政部门规定的其他情形。 不设床位的医疗机构在暂缓校验期内不得执业。 暂缓校验期满仍不能通过校验的，由登记机关注销其《医疗机构执业许可证》。"},{"i":38,"n":"第三十八条","txt":"各级卫生计生行政部门应当采用电子证照等信息化手段对医疗机构实行全程管理和动态监管。有关管理办法另行制定。"},{"i":39,"n":"第三十九条","txt":"医疗机构开业、迁移、更名、改变诊疗科目以及停业、歇业和校验结果由登记机关予以公告。"},{"i":40,"n":"第四十条","txt":"医疗机构的名称由识别名称和通用名称依次组成。 医疗机构的通用名称为：医院、中心卫生院、卫生院、疗养院、妇幼保健院、门诊部、诊所、卫生所、卫生站、卫生室、医务室、卫生保健所、急救中心、急救站、临床检验中心、防治院、防治所、防治站、护理院、护理站、中心以及国家卫生计生委规定或者认可的其他名称。 医疗机构可以下列名称作为识别名称：地名、单位名称、个人姓名、医学学科名称、医学专业和专科名称、诊疗科目名称和核准机关批准使用的名称。"},{"i":41,"n":"第四十一条","txt":"医疗机构的命名必须符合以下原则： （一）医疗机构的通用名称以前条第二款所列的名称为限； （二）前条第三款所列的医疗机构的识别名称可以合并使用； （三）名称必须名副其实； （四）名称必须与医疗机构类别或者诊疗科目相适应； （五）各级地方人民政府设置的医疗机构的识别名称中应当含有省、市、县、区、街道、乡、镇、村等行政区划名称，其他医疗机构的识别名称中不得含有行政区划名称； （六）国家机关、企业和事业单位、社会团体或者个人设置的医疗机构的名称中应当含有设置单位名称或者个人的姓名。"},{"i":42,"n":"第四十二条","txt":"医疗机构不得使用下列名称： （一）有损于国家、社会或者公共利益的名称； （二）侵犯他人利益的名称； （三）以外文字母、汉语拼音组成的名称； （四）以医疗仪器、药品、医用产品命名的名称； （五）含有“疑难病”、“专治”、“专家”、“名医”或者同类含义文字的名称以及其他宣传或者暗示诊疗效果的名称； （六）超出登记的诊疗科目范围的名称； （七）省级以上卫生计生行政部门规定不得使用的名称。"},{"i":43,"n":"第四十三条","txt":"以下医疗机构名称由国家卫生计生委核准；属于中医、中西医结合和民族医医疗机构的，由国家中医药管理局核准： （一）含有外国国家（地区）名称及其简称、国际组织名称的； （二）含有“中国”、“全国”、“中华”、“国家”等字样以及跨省地域名称的； （三）各级地方人民政府设置的医疗机构的识别名称中不含有行政区划名称的。"},{"i":44,"n":"第四十四条","txt":"以“中心”作为医疗机构通用名称的医疗机构名称，由省级以上卫生计生行政部门核准；在识别名称中含有“中心”字样的医疗机构名称的核准，由省、自治区、直辖市卫生计生行政部门规定。 含有“中心”字样的医疗机构名称必须同时含有行政区划名称或者地名。"},{"i":45,"n":"第四十五条","txt":"除专科疾病防治机构以外，医疗机构不得以具体疾病名称作为识别名称，确有需要的由省、自治区、直辖市卫生计生行政部门核准。"},{"i":46,"n":"第四十六条","txt":"医疗机构名称经核准登记，于领取《医疗机构执业许可证》后方可使用，在核准机关管辖范围内享有专用权。"},{"i":47,"n":"第四十七条","txt":"医疗机构只准使用一个名称。确有需要，经核准机关核准可以使用两个或者两个以上名称，但必须确定一个第一名称。"},{"i":48,"n":"第四十八条","txt":"卫生计生行政部门有权纠正已经核准登记的不适宜的医疗机构名称，上级卫生计生行政部门有权纠正下级卫生计生行政部门已经核准登记的不适宜的医疗机构名称。"},{"i":49,"n":"第四十九条","txt":"两个以上申请人向同一核准机关申请相同的医疗机构名称，核准机关依照申请在先原则核定。属于同一天申请的，应当由申请人双方协商解决；协商不成的，由核准机关作出裁决。 两个以上医疗机构因已经核准登记的医疗机构名称相同发生争议时，核准机关依照登记在先原则处理。属于同一天登记的，应当由双方协商解决；协商不成的，由核准机关报上一级卫生计生行政部门作出裁决。"},{"i":50,"n":"第五十条","txt":"医疗机构名称不得买卖、出借。 未经核准机关许可，医疗机构名称不得转让。"},{"i":51,"n":"第五十一条","txt":"医疗机构的印章、银行账户、牌匾以及医疗文件中使用的名称应当与核准登记的医疗机构名称相同；使用两个以上名称的，应当与第一名称相同。"},{"i":52,"n":"第五十二条","txt":"医疗机构应当严格执行无菌消毒、隔离制度，采取科学有效的措施处理污水和废弃物，预防和减少医院感染。"},{"i":53,"n":"第五十三条","txt":"医疗机构的门诊病历的保存期不得少于十五年；住院病历的保存期不得少于三十年。"},{"i":54,"n":"第五十四条","txt":"标有医疗机构标识的票据和病历本册以及处方笺、各种检查的申请单、报告单、证明文书单、药品分装袋、制剂标签等不得买卖、出借和转让。 医疗机构不得冒用标有其他医疗机构标识的票据和病历本册以及处方笺、各种检查的申请单、报告单、证明文书单、药品分装袋、制剂标签等。"},{"i":55,"n":"第五十五条","txt":"医疗机构应当按照卫生计生行政部门的有关规定、标准加强医疗质量管理，实施医疗质量保证方案，确保医疗安全和服务质量，不断提高服务水平。"},{"i":56,"n":"第五十六条","txt":"医疗机构应当定期检查、考核各项规章制度和各级各类人员岗位责任制的执行和落实情况。"},{"i":57,"n":"第五十七条","txt":"医疗机构应当经常对医务人员进行“基础理论、基本知识、基本技能”的训练与考核，把“严格要求、严密组织、严谨态度”落实到各项工作中。"},{"i":58,"n":"第五十八条","txt":"医疗机构应当组织医务人员学习医德规范和有关教材，督促医务人员恪守职业道德。"},{"i":59,"n":"第五十九条","txt":"医疗机构不得使用假劣药品、过期和失效药品以及违禁药品。"},{"i":60,"n":"第六十条","txt":"医疗机构为死因不明者出具的《死亡医学证明书》，只作是否死亡的诊断，不作死亡原因的诊断。如有关方面要求进行死亡原因诊断的，医疗机构必须指派医生对尸体进行解剖和有关死因检查后方能作出死因诊断。"},{"i":61,"n":"第六十一条","txt":"医疗机构在诊疗活动中，应当对患者实行保护性医疗措施，并取得患者家属和有关人员的配合。"},{"i":62,"n":"第六十二条","txt":"医疗机构应当尊重患者对自己的病情、诊断、治疗的知情权利。在实施手术、特殊检查、特殊治疗时，应当向患者作必要的解释。因实施保护性医疗措施不宜向患者说明情况的，应当将有关情况通知患者家属。"},{"i":63,"n":"第六十三条","txt":"门诊部、诊所、卫生所、医务室、卫生保健所和卫生站附设药房（柜）的药品种类由登记机关核定，具体办法由省、自治区、直辖市卫生计生行政部门规定。"},{"i":64,"n":"第六十四条","txt":"为内部职工服务的医疗机构未经许可和变更登记不得向社会开放。"},{"i":65,"n":"第六十五条","txt":"医疗机构被吊销或者注销执业许可证后，不得继续开展诊疗活动。"},{"i":66,"n":"第六十六条","txt":"各级卫生计生行政部门负责所辖区域内医疗机构的监督管理工作。"},{"i":67,"n":"第六十七条","txt":"在监督管理工作中，要充分发挥医院管理学会和卫生工作者协会等学术性和行业性社会团体的作用。"},{"i":68,"n":"第六十八条","txt":"县级以上卫生计生行政部门设立医疗机构监督管理办公室。 各级医疗机构监督管理办公室在同级卫生计生行政部门的领导下开展工作。"},{"i":69,"n":"第六十九条","txt":"各级医疗机构监督管理办公室的职责： （一）拟订医疗机构监督管理工作计划； （二）办理医疗机构监督员的审查、发证、换证； （三）负责医疗机构登记、校验和有关监督管理工作的统计，并向同级卫生计生行政部门报告； （四）负责接待、办理群众对医疗机构的投诉； （五）完成卫生计生行政部门交给的其他监督管理工作。"},{"i":70,"n":"第七十条","txt":"县级以上卫生计生行政部门设医疗机构监督员，履行规定的监督管理职责。医疗机构监督员由同级卫生计生行政部门聘任。 医疗机构监督员应当严格执行国家有关法律、法规和规章，其主要职责是： （一）对医疗机构执行有关法律、法规、规章和标准的情况进行监督、检查、指导； （二）对医疗机构执业活动进行监督、检查、指导； （三）对医疗机构违反条例和本细则的案件进行调查、取证； （四）对经查证属实的案件向卫生计生行政部门提出处理或者处罚意见； （五）实施职权范围内的处罚； （六）完成卫生计生行政部门交付的其他监督管理工作。"},{"i":71,"n":"第七十一条","txt":"医疗机构监督员有权对医疗机构进行现场检查，无偿索取有关资料，医疗机构不得拒绝、隐匿或者隐瞒。 医疗机构监督员在履行职责时应当佩戴证章、出示证件。 医疗机构监督员证章、证件由国家卫生计生委监制。"},{"i":72,"n":"第七十二条","txt":"各级卫生计生行政部门对医疗机构的执业活动检查、指导主要包括： （一）执行国家有关法律、法规、规章和标准情况； （二）执行医疗机构内部各项规章制度和各级各类人员岗位责任制情况； （三）医德医风情况； （四）服务质量和服务水平情况； （五）执行医疗收费标准情况； （六）组织管理情况； （七）人员任用情况； （八）省、自治区、直辖市卫生计生行政部门规定的其他检查、指导项目。"},{"i":73,"n":"第七十三条","txt":"国家实行医疗机构评审制度，对医疗机构的基本标准、服务质量、技术水平、管理水平等进行综合评价。县级以上卫生计生行政部门负责医疗机构评审的组织和管理；各级医疗机构评审委员会负责医疗机构评审的具体实施。"},{"i":74,"n":"第七十四条","txt":"县级以上中医（药）行政管理部门成立医疗机构评审委员会，负责中医、中西医结合和民族医医疗机构的评审。"},{"i":75,"n":"第七十五条","txt":"医疗机构评审包括周期性评审、不定期重点检查。 医疗机构评审委员会在对医疗机构进行评审时，发现有违反条例和本细则的情节，应当及时报告卫生计生行政部门；医疗机构评审委员会委员为医疗机构监督员的，可以直接行使监督权。"},{"i":76,"n":"第七十六条","txt":"《医疗机构监督管理行政处罚程序》另行制定。"},{"i":77,"n":"第七十七条","txt":"对未取得《医疗机构执业许可证》擅自执业的，责令其停止执业活动，没收非法所得和药品、器械，并处以三千元以下的罚款；有下列情形之一的，责令其停止执业活动，没收非法所得和药品、器械，处以三千元以上一万元以下的罚款： （一）因擅自执业曾受过卫生计生行政部门处罚； （二）擅自执业的人员为非卫生技术专业人员； （三）擅自执业时间在三个月以上； （四）给患者造成伤害； （五）使用假药、劣药蒙骗患者； （六）以行医为名骗取患者钱物； （七）省、自治区、直辖市卫生计生行政部门规定的其他情形。"},{"i":78,"n":"第七十八条","txt":"对不按期办理校验《医疗机构执业许可证》又不停止诊疗活动的，责令其限期补办校验手续；在限期内仍不办理校验的，吊销其《医疗机构执业许可证》。"},{"i":79,"n":"第七十九条","txt":"转让、出借《医疗机构执业许可证》的，没收其非法所得。并处以三千元以下的罚款；有下列情形之一的，没收其非法所得，处以三千元以上五千元以下的罚款，并吊销《医疗机构执业许可证》： （一）出卖《医疗机构执业许可证》； （二）转让或者出借《医疗机构执业许可证》是以营利为目的； （三）受让方或者承借方给患者造成伤害； （四）转让、出借《医疗机构执业许可证》给非卫生技术专业人员； （五）省、自治区、直辖市卫生计生行政部门规定的其他情形。"},{"i":80,"n":"第八十条","txt":"除急诊和急救外，医疗机构诊疗活动超出登记的诊疗科目范围，情节轻微的，处以警告；有下列情形之一的，责令其限期改正，并可处以三千元以下罚款： （一）超出登记的诊疗科目范围的诊疗活动累计收入在三千元以下； （二）给患者造成伤害。 有下列情形之一的，处以三千元罚款，并吊销《医疗机构执业许可证》： （一）超出登记的诊疗科目范围的诊疗活动累计收入在三千元以上； （二）给患者造成伤害； （三）省、自治区、直辖市卫生计生行政部门规定的其他情形。"},{"i":81,"n":"第八十一条","txt":"任用非卫生技术人员从事医疗卫生技术工作的，责令其立即改正，并可处以三千元以下的罚款；有下列情形之一的，处以三千元以上五千元以下罚款，并可以吊销其《医疗机构执业许可证》： （一）任用两名以上非卫生技术人员从事诊疗活动； （二）任用的非卫生技术人员给患者造成伤害。 医疗机构使用卫生技术人员从事本专业以外的诊疗活动的，按使用非卫生技术人员处理。"},{"i":82,"n":"第八十二条","txt":"出具虚假证明文件，情节轻微的，给予警告，并可处以五百元以下的罚款；有下列情形之一的，处以五百元以上一千元以下的罚款： （一）出具虚假证明文件造成延误诊治的； （二）出具虚假证明文件给患者精神造成伤害的； （三）造成其他危害后果的。 对直接责任人员由所在单位或者上级机关给予行政处分。"},{"i":83,"n":"第八十三条","txt":"医疗机构有下列情形之一的，登记机关可以责令其限期改正： （一）发生重大医疗事故； （二）连续发生同类医疗事故，不采取有效防范措施； （三）连续发生原因不明的同类患者死亡事件，同时存在管理不善因素； （四）管理混乱，有严重事故隐患，可能直接影响医疗安全； （五）省、自治区、直辖市卫生计生行政部门规定的其他情形。"},{"i":84,"n":"第八十四条","txt":"当事人对行政处罚决定不服的，可以在接到《行政处罚决定通知书》之日起十五日内向作出行政处罚决定的上一级卫生计生行政部门申请复议。上级卫生计生行政部门应当在接到申请书之日起三十日内作出书面答复。 当事人对行政处罚决定不服的，也可以在接到《行政处罚决定通知书》之日起十五日内直接向人民法院提起行政诉讼。 逾期不申请复议、不起诉又不履行行政处罚决定的，由作出行政处罚决定的卫生计生行政部门填写《行政处罚强制执行申请书》，向人民法院申请强制执行。"},{"i":85,"n":"第八十五条","txt":"医疗机构申请办理设置审批、执业登记、校验、评审时，应当交纳费用，医疗机构执业应当交纳管理费，具体办法由省级以上卫生计生行政部门会同物价管理部门规定。"},{"i":86,"n":"第八十六条","txt":"各省、自治区、直辖市根据条例和本细则并结合当地的实际情况，制定实施办法。实施办法中的有关中医、中西结合、民族医医疗机构的条款，由省、自治区、直辖市中医（药）行政部门拟订。"},{"i":87,"n":"第八十七条","txt":"条例及本细则实施前已经批准执业的医疗机构的审核登记办法，由省、自治区、直辖市卫生计生行政部门根据当地的实际情况规定。"},{"i":88,"n":"第八十八条","txt":"条例及本细则中下列用语的含义： 诊疗活动：是指通过各种检查，使用药物、器械及手术等方法，对疾病作出判断和消除疾病、缓解病情、减轻痛苦、改善功能、延长生命、帮助患者恢复健康的活动。 医疗美容：是指使用药物以及手术、物理和其他损伤性或者侵入性手段进行的美容。 特殊检查、特殊治疗：是指具有下列情形之一的诊断治疗活动： （一）有一定危险性，可能产生不良后果的检查和治疗； （二）由于患者体质特殊或者病情危笃，可能对患者产生不良后果和危险的检查和治疗； （三）临床试验性检查和治疗； （四）收费可能对患者造成较大经济负担的检查和治疗。 卫生技术人员：是指按照国家有关法律、法规和规章的规定取得卫生技术人员资格或者职称的人员。 技术规范：是指由国家卫生计生委、国家中医药管理局制定或者认可的与诊疗活动有关的技术标准、操作规程等规范性文件。 军队的医疗机构：是指中国人民解放军和中国人民武装警察部队编制内的医"},{"i":89,"n":"第八十九条","txt":"各级中医（药）行政管理部门依据条例和本细则以及当地医疗机构管理条例实施办法，对管辖范围内各类中医、中西医结合和民族医医疗机构行使设置审批、登记和监督管理权。"},{"i":90,"n":"第九十条","txt":"本细则的解释权在国家卫生计生委。"},{"i":91,"n":"第九十一条","txt":"本细则自1994年9月1日起施行。 附表：（略）"}],"yiliaoqigongguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强医疗气功管理，保护人民健康，根据《中华人民共和国执业医师法》（以下简称《执业医师法》）和《医疗机构管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"运用气功方法治疗疾病构成医疗行为的各类机构和人员，适用本规定。"},{"i":3,"n":"第三条","txt":"国家中医药管理局负责全国医疗气功的监督管理。 县级以上地方人民政府中医药行政管理机构负责本辖区内医疗气功的监督管理。"},{"i":4,"n":"第四条","txt":"“医疗气功”列入医疗机构诊疗科目的“中医科——其他”类中。"},{"i":5,"n":"第五条","txt":"开展医疗气功活动必须在医疗机构内进行。 除本规定发布前，已经县级以上人民政府卫生行政部门或中医药行政管理机构批准开展医疗气功活动的医疗机构，可以按本规定重新申请审批开展医疗气功活动以外，今后新开展医疗气功活动的暂限于县级以上中医医院、中西医结合医院、民族医医院、康复医院、疗养院和综合医院的中医科。"},{"i":6,"n":"第六条","txt":"医疗机构申请开展医疗气功活动，应当向其登记执业的卫生行政部门或者中医药行政管理机构提出申请。经初审同意后，报设区的市级以上地方人民政府中医药行政管理机构审批。对审核合格的，签发同意意见；审核不合格的，书面通知申请单位。"},{"i":7,"n":"第七条","txt":"医疗机构申请开展医疗气功活动应当提交下列材料： （一）开展医疗气功活动申请书； （二）《医疗机构执业许可证》原件及复印件； （三）开展医疗气功活动的场所、设备等基本情况； （四）从事医疗气功活动的人员情况； （五）省级以上人民政府中医药行政管理机构规定的其他材料。"},{"i":8,"n":"第八条","txt":"医疗机构凭设区的市级以上地方人民政府中医药行政管理机构签发的同意意见，向其登记执业的卫生行政部门或者中医药行政管理机构申请办理诊疗科目登记或者变更登记手续。 未经设区的市级以上地方人民政府中医药行政管理机构审批同意，以及未向卫生行政部门或者中医药行政管理机构申请办理诊疗科目登记或者变更登记手续的，不得开展医疗气功活动。"},{"i":9,"n":"第九条","txt":"从事医疗气功活动的人员，应当具备下列条件： （一）具有中医执业医师或中医执业助理医师资格； （二）取得《医师执业证书》； （三）经医疗气功知识与技能考试取得《医疗气功技能合格证书》。"},{"i":10,"n":"第十条","txt":"医疗气功知识与技能考试由国家中医药管理局统一组织，省级人民政府中医药行政管理机构负责具体实施。具体考试办法由国家中医药管理局另行制定。"},{"i":11,"n":"第十一条","txt":"取得中医执业医师资格或中医执业助理医师资格，具有医疗气功专业知识与技能者，均可申请参加医疗气功知识与技能考试。"},{"i":12,"n":"第十二条","txt":"经医疗气功知识与技能考试成绩合格的，取得国家中医药管理局统一印制的《医疗气功技能合格证书》。 《医疗气功技能合格证书》由省级人民政府中医药行政管理机构负责颁发。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府中医药行政管理机构应当按照本规定和有关法律法规，加强对医疗气功活动的日常监督检查。 医疗机构和医疗人员开展医疗气功活动，必须严格遵守《执业医师法》、《医疗机构管理条例》和本规定的各项规定。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府卫生行政部门或者中医药行政管理机构进行医疗机构校验时，应当将医疗气功执业情况列入校验内容，并应当及时将校验结果报其上一级人民政府中医药行政管理机构备案。 对医疗气功人员执业情况的考核，由医师执业注册主管部门在开展医师执业考核时一并进行。"},{"i":15,"n":"第十五条","txt":"经批准开展医疗气功活动的医疗机构不得使用非医疗气功人员开展医疗气功活动。"},{"i":16,"n":"第十六条","txt":"医疗气功人员应当按照其医师执业注册的执业地点开展医疗气功活动。"},{"i":17,"n":"第十七条","txt":"取得中医执业医师资格的医疗气功人员可独立开展医疗气功活动；取得中医执业助理医师资格的医疗气功人员必须在中医执业医师指导下开展医疗气功活动。"},{"i":18,"n":"第十八条","txt":"医疗气功人员开展医疗气功活动，应当严格执行有关操作技术规范，选择合理的医疗气功方法。 在临床进行实验性医疗气功活动的，应当经所在医疗机构批准，向患者本人或其家属说明并征得患者本人或者其家属同意。"},{"i":19,"n":"第十九条","txt":"医疗机构和医疗气功人员，不得借医疗气功之名，损害公民身心健康、宣扬迷信、骗人敛财。"},{"i":20,"n":"第二十条","txt":"医疗机构和医疗气功人员，不得使用、制作、经营或者散发宣称具有医疗气功效力的物品。"},{"i":21,"n":"第二十一条","txt":"组织开展下列活动之一的，应当经省级以上人民政府中医药行政管理机构审核批准： （一）大型医疗气功讲座； （二）大型现场性医疗气功活动； （三）国家中医药管理局规定必须严格管理的其他医疗气功活动。"},{"i":22,"n":"第二十二条","txt":"违反本规定，非医疗机构或非医师开展医疗气功活动的，按照《医疗机构管理条例》第四十四条和《执业医师法》第三十九条的规定进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"违反本规定，医疗机构未经批准擅自开展医疗气功活动的，按照《医疗机构管理条例》第四十七条的规定进行处罚。"},{"i":24,"n":"第二十四条","txt":"违反本规定，使用非医疗气功人员开展医疗气功活动的，按照《医疗机构管理条例实施细则》第八十一条的规定进行处罚。"},{"i":25,"n":"第二十五条","txt":"违反本规定，医疗气功人员在医疗气功活动中违反医学常规或医疗气功基本操作规范，造成严重后果的，按照《执业医师法》第三十七条的规定进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"违反本规定，有下列情形之一的，由县级以上人民政府中医药行政管理机构责令其停止活动，给予警告，并可以处以一万元以下罚款；情节严重的，处以一万元以上三万元以下罚款；构成犯罪的，依法追究刑事责任。 （一）医疗气功人员在注册的执业地点以外开展医疗气功活动的； （二）借医疗气功之名损害公民身心健康、宣扬迷信、骗人敛财的； （三）非医疗气功人员开展医疗气功活动的； （四）制造、使用、经营、散发宣称具有医疗气功效力物品的； （五）未经批准擅自组织开展大型医疗气功讲座、大型现场性医疗气功活动，或未经批准擅自开展国家中医药管理局规定必须严格管理的其他医疗气功活动的。"},{"i":27,"n":"第二十七条","txt":"违反本规定，以不正当手段取得《医疗气功技能合格证书》的，由发给证书的中医药行政管理机构予以收回；对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":28,"n":"第二十八条","txt":"本规定发布前已经县级以上人民政府卫生行政部门或者中医药行政管理机构批准开展医疗气功活动的机构和人员，应当按照本规定重新申请、审批，并于2000年12月31日以前完成。 本规定发布前已经登记执业的医疗气功专门医疗机构，可以在转型为其他医疗机构的基础上，按本规定重新申请登记医疗气功诊疗科目；也可以根据《医疗气功专门医疗机构基本标准》，按照本规定重新申请登记医疗气功专门医疗机构。《医疗气功专门医疗机构基本标准》另行制定。 除上款规定情形外，今后不再审批新的医疗气功专门医疗机构。 本规定发布前已经取得副主任中医师以上专业技术职务，并经县级以上人民政府卫生行政部门或者中医药行政管理机构批准开展医疗气功活动的人员，可由本人向批准其开展医疗气功活动的卫生行政部门或者中医药行政管理机构提出申请，经省级人民政府中医药行政管理机构审核确认后，可以不参加医疗气功知识与技能考试，直接取得《医疗气功技能合格证书"},{"i":29,"n":"第二十九条","txt":"暂不接受境外人员的医疗气功知识与技能考试申请。"},{"i":30,"n":"第三十条","txt":"本规定由国家中医药管理局负责解释。"},{"i":31,"n":"第三十一条","txt":"本规定自发布之日起施行。1989年国家中医药管理局发布的《关于加强气功医疗管理的若干规定》同时废止。"}],"yiliaomeirongfuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范医疗美容服务，促进医疗美容事业的健康发展，维护就医者的合法权益，依据《执业医师法》、《医疗机构管理条例》和《护士管理办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称医疗美容，是指运用手术、药物、医疗器械以及其他具有创伤性或者侵入性的医学技术方法对人的容貌和人体各部位形态进行的修复与再塑。 本办法所称美容医疗机构，是指以开展医疗美容诊疗业务为主的医疗机构。 本办法所称主诊医师是指具备本办法第十一条规定条件，负责实施医疗美容项目的执业医师。 医疗美容科为一级诊疗科目，美容外科、美容牙科、美容皮肤科和美容中医科为二级诊疗科目。 根据医疗美容项目的技术难度、可能发生的医疗风险程度，对医疗美容项目实行分级准入管理。《医疗美容项目分级管理目录》由卫生部另行制定。"},{"i":3,"n":"第三条","txt":"凡开展医疗美容服务的机构和个人必须遵守本办法。"},{"i":4,"n":"第四条","txt":"卫生部（含国家中医药管理局）主管全国医疗美容服务管理工作。县级以上地方人民政府卫生行政部门（含中医药行政管理部门，下同）负责本行政区域内医疗美容服务监督管理工作。"},{"i":5,"n":"第五条","txt":"申请举办美容医疗机构或医疗机构设置医疗美容科室必须同时具备下列条件： （一）具有承担民事责任的能力； （二）有明确的医疗美容诊疗服务范围； （三）符合《医疗机构基本标准（试行）》； （四）省级以上人民政府卫生行政部门规定的其他条件。"},{"i":6,"n":"第六条","txt":"申请举办美容医疗机构的单位或者个人，应按照本办法以及《医疗机构管理条例》和《医疗机构管理条例实施细则》的有关规定办理设置审批和登记注册手续。 卫生行政部门自收到合格申办材料之日起30日内作出批准或不予批准的决定，并书面答复申办者。"},{"i":7,"n":"第七条","txt":"卫生行政部门应在核发美容医疗机构《设置医疗机构批准书》和《医疗机构执业许可证》的同时，向上一级卫生行政部门备案。 上级卫生行政部门对下级卫生行政部门违规作出的审批决定应自发现之日起30日内予以纠正或撤销。"},{"i":8,"n":"第八条","txt":"美容医疗机构必须经卫生行政部门登记注册并获得《医疗机构执业许可证》后方可开展执业活动。"},{"i":9,"n":"第九条","txt":"医疗机构增设医疗美容科目的，必须具备本办法规定的条件，按照《医疗机构管理条例》及其实施细则规定的程序，向登记注册机关申请变更登记。"},{"i":10,"n":"第十条","txt":"美容医疗机构和医疗美容科室开展医疗美容项目应当由登记机关指定的专业学会核准，并向登记机关备案。"},{"i":11,"n":"第十一条","txt":"负责实施医疗美容项目的主诊医师必须同时具备下列条件： （一）具有执业医师资格，经执业医师注册机关注册； （二）具有从事相关临床学科工作经历。其中，负责实施美容外科项目的应具有6年以上从事美容外科或整形外科等相关专业临床工作经历；负责实施美容牙科项目的应具有5年以上从事美容牙科或口腔科专业临床工作经历；负责实施美容中医科和美容皮肤科项目的应分别具有3年以上从事中医专业和皮肤病专业临床工作经历； （三）经过医疗美容专业培训或进修并合格，或已从事医疗美容临床工作1年以上； （四）省级人民政府卫生行政部门规定的其他条件。"},{"i":12,"n":"第十二条","txt":"不具备本办法第十一条规定的主诊医师条件的执业医师，可在主诊医师的指导下从事医疗美容临床技术服务工作。"},{"i":13,"n":"第十三条","txt":"从事医疗美容护理工作的人员，应同时具备下列条件： （一）具有护士资格，并经护士注册机关注册； （二）具有2年以上护理工作经历； （三）经过医疗美容护理专业培训或进修并合格，或已从事医疗美容临床护理工作6个月以上。"},{"i":14,"n":"第十四条","txt":"未经卫生行政部门核定并办理执业注册手续的人员不得从事医疗美容诊疗服务。"},{"i":15,"n":"第十五条","txt":"实施医疗美容项目必须在相应的美容医疗机构或开设医疗美容科室的医疗机构中进行。"},{"i":16,"n":"第十六条","txt":"美容医疗机构和医疗美容科室应根据自身条件和能力在卫生行政部门核定的诊疗科目范围内开展医疗服务，未经批准不得擅自扩大诊疗范围。 美容医疗机构及开设医疗美容科室的医疗机构不得开展未向登记机关备案的医疗美容项目。"},{"i":17,"n":"第十七条","txt":"美容医疗机构执业人员要严格执行有关法律、法规和规章，遵守医疗美容技术操作规程。 美容医疗机构使用的医用材料须经有关部门批准。"},{"i":18,"n":"第十八条","txt":"医疗美容服务实行主诊医师负责制。医疗美容项目必须由主诊医师负责或在其指导下实施。"},{"i":19,"n":"第十九条","txt":"执业医师对就医者实施治疗前，必须向就医者本人或亲属书面告知治疗的适应症、禁忌症、医疗风险和注意事项等，并取得就医者本人或监护人的签字同意。未经监护人同意，不得为无行为能力或者限制行为能力人实施医疗美容项目。"},{"i":20,"n":"第二十条","txt":"美容医疗机构和医疗美容科室的从业人员要尊重就医者的隐私权，未经就医者本人或监护人同意，不得向第三方披露就医者病情及病历资料。"},{"i":21,"n":"第二十一条","txt":"美容医疗机构和医疗美容科室发生重大医疗过失，要按规定及时报告当地人民政府卫生行政部门。"},{"i":22,"n":"第二十二条","txt":"美容医疗机构和医疗美容科室应加强医疗质量管理，不断提高服务水平。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人，未取得《医疗机构执业许可证》并经登记机关核准开展医疗美容诊疗科目，不得开展医疗美容服务。"},{"i":24,"n":"第二十四条","txt":"各级地方人民政府卫生行政部门要加强对医疗美容项目备案的审核。发现美容医疗机构及开设医疗美容科的医疗机构不具备开展某医疗美容项目的条件和能力，应及时通知该机构停止开展该医疗美容项目。"},{"i":25,"n":"第二十五条","txt":"各相关专业学会和行业协会要积极协助卫生行政部门规范医疗美容服务行为，加强行业自律工作。"},{"i":26,"n":"第二十六条","txt":"美容医疗机构和医疗美容科室发生医疗纠纷或医疗事故，按照国家有关规定处理。"},{"i":27,"n":"第二十七条","txt":"发布医疗美容广告必须按照国家有关广告管理的法律、法规的规定办理。"},{"i":28,"n":"第二十八条","txt":"对违反本办法规定的，依据《执业医师法》、《医疗机构管理条例》和《护士管理办法》有关规定予以处罚。"},{"i":29,"n":"第二十九条","txt":"外科、口腔科、眼科、皮肤科、中医科等相关临床学科在疾病治疗过程中涉及的相关医疗美容活动不受本办法调整。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府卫生行政部门应在本办法施行后一年内，按本办法规定对已开办的美容医疗机构和开设医疗美容科室的医疗机构进行审核并重新核发《医疗机构执业许可证》。"},{"i":31,"n":"第三十一条","txt":"本办法自2002年5月1日起施行。"}],"yiliaozhiliangguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗质量管理，规范医疗服务行为，保障医疗安全，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级卫生计生行政部门以及各级各类医疗机构医疗质量管理工作。"},{"i":3,"n":"第三条","txt":"国家卫生计生委负责全国医疗机构医疗质量管理工作。 县级以上地方卫生计生行政部门负责本行政区域内医疗机构医疗质量管理工作。 国家中医药管理局和军队卫生主管部门分别在职责范围内负责中医和军队医疗机构医疗质量管理工作。"},{"i":4,"n":"第四条","txt":"医疗质量管理是医疗管理的核心，各级各类医疗机构是医疗质量管理的第一责任主体，应当全面加强医疗质量管理，持续改进医疗质量，保障医疗安全。"},{"i":5,"n":"第五条","txt":"医疗质量管理应当充分发挥卫生行业组织的作用，各级卫生计生行政部门应当为卫生行业组织参与医疗质量管理创造条件。"},{"i":6,"n":"第六条","txt":"国家卫生计生委负责组织或者委托专业机构、行业组织（以下称专业机构）制订医疗质量管理相关制度、规范、标准和指南，指导地方各级卫生计生行政部门和医疗机构开展医疗质量管理与控制工作。省级卫生计生行政部门可以根据本地区实际，制订行政区域医疗质量管理相关制度、规范和具体实施方案。 县级以上地方卫生计生行政部门在职责范围内负责监督、指导医疗机构落实医疗质量管理有关规章制度。"},{"i":7,"n":"第七条","txt":"国家卫生计生委建立国家医疗质量管理与控制体系，完善医疗质量控制与持续改进的制度和工作机制。 各级卫生计生行政部门组建或者指定各级、各专业医疗质量控制组织（以下称质控组织）落实医疗质量管理与控制的有关工作要求。"},{"i":8,"n":"第八条","txt":"国家级各专业质控组织在国家卫生计生委指导下，负责制订全国统一的质控指标、标准和质量管理要求，收集、分析医疗质量数据，定期发布质控信息。 省级和有条件的地市级卫生计生行政部门组建相应级别、专业的质控组织，开展医疗质量管理与控制工作。"},{"i":9,"n":"第九条","txt":"医疗机构医疗质量管理实行院、科两级责任制。 医疗机构主要负责人是本机构医疗质量管理的第一责任人;临床科室以及药学、护理、医技等部门（以下称业务科室）主要负责人是本科室医疗质量管理的第一责任人。"},{"i":10,"n":"第十条","txt":"医疗机构应当成立医疗质量管理专门部门，负责本机构的医疗质量管理工作。 二级以上的医院、妇幼保健院以及专科疾病防治机构（以下称二级以上医院）应当设立医疗质量管理委员会。医疗质量管理委员会主任由医疗机构主要负责人担任，委员由医疗管理、质量控制、护理、医院感染管理、医学工程、信息、后勤等相关职能部门负责人以及相关临床、药学、医技等科室负责人组成，指定或者成立专门部门具体负责日常管理工作。 其他医疗机构应当设立医疗质量管理工作小组或者指定专（兼）职人员，负责医疗质量具体管理工作。"},{"i":11,"n":"第十一条","txt":"医疗机构医疗质量管理委员会的主要职责是： （一）按照国家医疗质量管理的有关要求，制订本机构医疗质量管理制度并组织实施； （二）组织开展本机构医疗质量监测、预警、分析、考核、评估以及反馈工作，定期发布本机构质量管理信息； （三）制订本机构医疗质量持续改进计划、实施方案并组织实施； （四）制订本机构临床新技术引进和医疗技术临床应用管理相关工作制度并组织实施； （五）建立本机构医务人员医疗质量管理相关法律、法规、规章制度、技术规范的培训制度，制订培训计划并监督实施； （六）落实省级以上卫生计生行政部门规定的其他内容。"},{"i":12,"n":"第十二条","txt":"二级以上医院各业务科室应当成立本科室医疗质量管理工作小组，组长由科室主要负责人担任，指定专人负责日常具体工作。医疗质量管理工作小组主要职责是： （一）贯彻执行医疗质量管理相关的法律、法规、规章、规范性文件和本科室医疗质量管理制度； （二）制订本科室年度质量控制实施方案，组织开展科室医疗质量管理与控制工作； （三）制订本科室医疗质量持续改进计划和具体落实措施； （四）定期对科室医疗质量进行分析和评估，对医疗质量薄弱环节提出整改措施并组织实施； （五）对本科室医务人员进行医疗质量管理相关法律、法规、规章制度、技术规范、标准、诊疗常规及指南的培训和宣传教育； （六）按照有关要求报送本科室医疗质量管理相关信息。"},{"i":13,"n":"第十三条","txt":"各级卫生计生行政部门和医疗机构应当建立健全医疗质量管理人员的培养和考核制度，充分发挥专业人员在医疗质量管理工作中的作用。"},{"i":14,"n":"第十四条","txt":"医疗机构应当加强医务人员职业道德教育，发扬救死扶伤的人道主义精神，坚持“以患者为中心”，尊重患者权利，履行防病治病、救死扶伤、保护人民健康的神圣职责。"},{"i":15,"n":"第十五条","txt":"医务人员应当恪守职业道德，认真遵守医疗质量管理相关法律法规、规范、标准和本机构医疗质量管理制度的规定，规范临床诊疗行为，保障医疗质量和医疗安全。"},{"i":16,"n":"第十六条","txt":"医疗机构应当按照核准登记的诊疗科目执业。卫生技术人员开展诊疗活动应当依法取得执业资质, 医疗机构人力资源配备应当满足临床工作需要。 医疗机构应当按照有关法律法规、规范、标准要求，使用经批准的药品、医疗器械、耗材开展诊疗活动。 医疗机构开展医疗技术应当与其功能任务和技术能力相适应，按照国家关于医疗技术和手术管理有关规定，加强医疗技术临床应用管理。"},{"i":17,"n":"第十七条","txt":"医疗机构及其医务人员应当遵循临床诊疗指南、临床技术操作规范、行业标准和临床路径等有关要求开展诊疗工作，严格遵守医疗质量安全核心制度，做到合理检查、合理用药、合理治疗。"},{"i":18,"n":"第十八条","txt":"医疗机构应当加强药学部门建设和药事质量管理，提升临床药学服务能力，推行临床药师制，发挥药师在处方审核、处方点评、药学监护等合理用药管理方面的作用。临床诊断、预防和治疗疾病用药应当遵循安全、有效、经济的合理用药原则，尊重患者对药品使用的知情权。"},{"i":19,"n":"第十九条","txt":"医疗机构应当加强护理质量管理，完善并实施护理相关工作制度、技术规范和护理指南；加强护理队伍建设，创新管理方法，持续改善护理质量。"},{"i":20,"n":"第二十条","txt":"医疗机构应当加强医技科室的质量管理，建立覆盖检查、检验全过程的质量管理制度，加强室内质量控制，配合做好室间质量评价工作，促进临床检查检验结果互认。"},{"i":21,"n":"第二十一条","txt":"医疗机构应当完善门急诊管理制度，规范门急诊质量管理，加强门急诊专业人员和技术力量配备，优化门急诊服务流程，保证门急诊医疗质量和医疗安全，并把门急诊工作质量作为考核科室和医务人员的重要内容。"},{"i":22,"n":"第二十二条","txt":"医疗机构应当加强医院感染管理，严格执行消毒隔离、手卫生、抗菌药物合理使用和医院感染监测等规定，建立医院感染的风险监测、预警以及多部门协同干预机制，开展医院感染防控知识的培训和教育，严格执行医院感染暴发报告制度。"},{"i":23,"n":"第二十三条","txt":"医疗机构应当加强病历质量管理，建立并实施病历质量管理制度，保障病历书写客观、真实、准确、及时、完整、规范。"},{"i":24,"n":"第二十四条","txt":"医疗机构及其医务人员开展诊疗活动，应当遵循患者知情同意原则，尊重患者的自主选择权和隐私权，并对患者的隐私保密。"},{"i":25,"n":"第二十五条","txt":"医疗机构开展中医医疗服务，应当符合国家关于中医诊疗、技术、药事等管理的有关规定，加强中医医疗质量管理。"},{"i":26,"n":"第二十六条","txt":"医疗机构应当建立本机构全员参与、覆盖临床诊疗服务全过程的医疗质量管理与控制工作制度。医疗机构应当严格按照卫生计生行政部门和质控组织关于医疗质量管理控制工作的有关要求，积极配合质控组织开展工作，促进医疗质量持续改进。 医疗机构应当按照有关要求，向卫生计生行政部门或者质控组织及时、准确地报送本机构医疗质量安全相关数据信息。 医疗机构应当熟练运用医疗质量管理工具开展医疗质量管理与自我评价，根据卫生计生行政部门或者质控组织发布的质控指标和标准完善本机构医疗质量管理相关指标体系，及时收集相关信息，形成本机构医疗质量基础数据。"},{"i":27,"n":"第二十七条","txt":"医疗机构应当加强临床专科服务能力建设，重视专科协同发展，制订专科建设发展规划并组织实施，推行“以患者为中心、以疾病为链条”的多学科诊疗模式。加强继续医学教育，重视人才培养、临床技术创新性研究和成果转化，提高专科临床服务能力与水平。"},{"i":28,"n":"第二十八条","txt":"医疗机构应当加强单病种质量管理与控制工作，建立本机构单病种管理的指标体系，制订单病种医疗质量参考标准，促进医疗质量精细化管理。"},{"i":29,"n":"第二十九条","txt":"医疗机构应当制订满意度监测指标并不断完善，定期开展患者和员工满意度监测，努力改善患者就医体验和员工执业感受。"},{"i":30,"n":"第三十条","txt":"医疗机构应当开展全过程成本精确管理，加强成本核算、过程控制、细节管理和量化分析，不断优化投入产出比，努力提高医疗资源利用效率。"},{"i":31,"n":"第三十一条","txt":"医疗机构应当对各科室医疗质量管理情况进行现场检查和抽查，建立本机构医疗质量内部公示制度，对各科室医疗质量关键指标的完成情况予以内部公示。 医疗机构应当定期对医疗卫生技术人员开展医疗卫生管理法律法规、医院管理制度、医疗质量管理与控制方法、专业技术规范等相关内容的培训和考核。 医疗机构应当将科室医疗质量管理情况作为科室负责人综合目标考核以及聘任、晋升、评先评优的重要指标。 医疗机构应当将科室和医务人员医疗质量管理情况作为医师定期考核、晋升以及科室和医务人员绩效考核的重要依据。"},{"i":32,"n":"第三十二条","txt":"医疗机构应当强化基于电子病历的医院信息平台建设，提高医院信息化工作的规范化水平，使信息化工作满足医疗质量管理与控制需要，充分利用信息化手段开展医疗质量管理与控制。建立完善医疗机构信息管理制度，保障信息安全。"},{"i":33,"n":"第三十三条","txt":"医疗机构应当对本机构医疗质量管理要求执行情况进行评估，对收集的医疗质量信息进行及时分析和反馈，对医疗质量问题和医疗安全风险进行预警，对存在的问题及时采取有效干预措施，并评估干预效果，促进医疗质量的持续改进。"},{"i":34,"n":"第三十四条","txt":"国家建立医疗质量（安全）不良事件报告制度，鼓励医疗机构和医务人员主动上报临床诊疗过程中的不良事件，促进信息共享和持续改进。 医疗机构应当建立医疗质量（安全）不良事件信息采集、记录和报告相关制度，并作为医疗机构持续改进医疗质量的重要基础工作。"},{"i":35,"n":"第三十五条","txt":"医疗机构应当建立药品不良反应、药品损害事件和医疗器械不良事件监测报告制度，并按照国家有关规定向相关部门报告。"},{"i":36,"n":"第三十六条","txt":"医疗机构应当提高医疗安全意识，建立医疗安全与风险管理体系，完善医疗安全管理相关工作制度、应急预案和工作流程，加强医疗质量重点部门和关键环节的安全与风险管理，落实患者安全目标。医疗机构应当提高风险防范意识，建立完善相关制度，利用医疗责任保险、医疗意外保险等风险分担形式，保障医患双方合法权益。制订防范、处理医疗纠纷的预案，预防、减少医疗纠纷的发生。完善投诉管理，及时化解和妥善处理医疗纠纷。"},{"i":37,"n":"第三十七条","txt":"县级以上地方卫生计生行政部门负责对本行政区域医疗机构医疗质量管理情况的监督检查。医疗机构应当予以配合，不得拒绝、阻碍或者隐瞒有关情况。"},{"i":38,"n":"第三十八条","txt":"县级以上地方卫生计生行政部门应当建立医疗机构医疗质量管理评估制度，可以根据当地实际情况，组织或者委托专业机构，利用信息化手段开展第三方评估工作，定期在行业内发布评估结果。 县级以上地方卫生计生行政部门和各级质控组织应当重点加强对县级医院、基层医疗机构和民营医疗机构的医疗质量管理和监督。"},{"i":39,"n":"第三十九条","txt":"国家卫生计生委依托国家级人口健康信息平台建立全国医疗质量管理与控制信息系统，对全国医疗质量管理的主要指标信息进行收集、分析和反馈。 省级卫生计生行政部门应当依托区域人口健康信息平台，建立本行政区域的医疗质量管理与控制信息系统，对本行政区域医疗机构医疗质量管理相关信息进行收集、分析和反馈，对医疗机构医疗质量进行评价，并实现与全国医疗质量管理与控制信息系统互连互通。"},{"i":40,"n":"第四十条","txt":"各级卫生计生行政部门应当建立医疗机构医疗质量管理激励机制，采取适当形式对医疗质量管理先进的医疗机构和管理人员予以表扬和鼓励，积极推广先进经验和做法。"},{"i":41,"n":"第四十一条","txt":"县级以上地方卫生计生行政部门应当建立医疗机构医疗质量管理情况约谈制度。对发生重大或者特大医疗质量安全事件、存在严重医疗质量安全隐患，或者未按要求整改的各级各类医疗机构负责人进行约谈；对造成严重后果的，予以通报，依法处理，同时报上级卫生计生行政部门备案。"},{"i":42,"n":"第四十二条","txt":"各级卫生计生行政部门应当将医疗机构医疗质量管理情况和监督检查结果纳入医疗机构及其主要负责人考核的关键指标，并与医疗机构校验、医院评审、评价以及个人业绩考核相结合。考核不合格的，视情况对医疗机构及其主要负责人进行处理。"},{"i":43,"n":"第四十三条","txt":"医疗机构开展诊疗活动超出登记范围、使用非卫生技术人员从事诊疗工作、违规开展禁止或者限制临床应用的医疗技术、使用不合格或者未经批准的药品、医疗器械、耗材等开展诊疗活动的，由县级以上地方卫生计生行政部门依据国家有关法律法规进行处理。"},{"i":44,"n":"第四十四条","txt":"医疗机构有下列情形之一的，由县级以上卫生计生行政部门责令限期改正；逾期不改的，给予警告，并处三万元以下罚款；对公立医疗机构负有责任的主管人员和其他直接责任人员，依法给予处分： （一）未建立医疗质量管理部门或者未指定专（兼）职人员负责医疗质量管理工作的； （二）未建立医疗质量管理相关规章制度的； （三）医疗质量管理制度不落实或者落实不到位，导致医疗质量管理混乱的； （四）发生重大医疗质量安全事件隐匿不报的； （五）未按照规定报送医疗质量安全相关信息的； （六）其他违反本办法规定的行为。"},{"i":45,"n":"第四十五条","txt":"医疗机构执业的医师、护士在执业活动中，有下列行为之一的，由县级以上地方卫生计生行政部门依据《执业医师法》、《护士条例》等有关法律法规的规定进行处理；构成犯罪的，依法追究刑事责任： （一）违反卫生法律、法规、规章制度或者技术操作规范，造成严重后果的； （二）由于不负责任延误急危患者抢救和诊治，造成严重后果的； （三）未经亲自诊查，出具检查结果和相关医学文书的； （四）泄露患者隐私，造成严重后果的； （五）开展医疗活动未遵守知情同意原则的； （六）违规开展禁止或者限制临床应用的医疗技术、不合格或者未经批准的药品、医疗器械、耗材等开展诊疗活动的； （七）其他违反本办法规定的行为。 其他卫生技术人员违反本办法规定的，根据有关法律、法规的规定予以处理。"},{"i":46,"n":"第四十六条","txt":"县级以上地方卫生计生行政部门未按照本办法规定履行监管职责，造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":47,"n":"第四十七条","txt":"本办法下列用语的含义： （一）医疗质量：指在现有医疗技术水平及能力、条件下，医疗机构及其医务人员在临床诊断及治疗过程中，按照职业道德及诊疗规范要求，给予患者医疗照顾的程度。 （二）医疗质量管理：指按照医疗质量形成的规律和有关法律、法规要求，运用现代科学管理方法，对医疗服务要素、过程和结果进行管理与控制，以实现医疗质量系统改进、持续改进的过程。 （三）医疗质量安全核心制度：指医疗机构及其医务人员在诊疗活动中应当严格遵守的相关制度，主要包括：首诊负责制度、三级查房制度、会诊制度、分级护理制度、值班和交接班制度、疑难病例讨论制度、急危重患者抢救制度、术前讨论制度、死亡病例讨论制度、查对制度、手术安全核查制度、手术分级管理制度、新技术和新项目准入制度、危急值报告制度、病历管理制度、抗菌药物分级管理制度、临床用血审核制度、信息安全管理制度等。 （四）医疗质量管理工具：指为实现医疗质量管理目标和持"},{"i":48,"n":"第四十八条","txt":"本办法自2016年11月1日起施行。"}],"yiyuanganranguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医院感染管理，有效预防和控制医院感染，提高医疗质量，保证医疗安全，根据《传染病防治法》、《医疗机构管理条例》和《突发公共卫生事件应急条例》等法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"医院感染管理是各级卫生行政部门、医疗机构及医务人员针对诊疗活动中存在的医院感染、医源性感染及相关的危险因素进行的预防、诊断和控制活动。"},{"i":3,"n":"第三条","txt":"各级各类医疗机构应当严格按照本办法的规定实施医院感染管理工作。 医务人员的职业卫生防护，按照《职业病防治法》及其配套规章和标准的有关规定执行。"},{"i":4,"n":"第四条","txt":"卫生部负责全国医院感染管理的监督管理工作。 县级以上地方人民政府卫生行政部门负责本行政区域内医院感染管理的监督管理工作。"},{"i":5,"n":"第五条","txt":"各级各类医疗机构应当建立医院感染管理责任制，制定并落实医院感染管理的规章制度和工作规范，严格执行有关技术操作规范和工作标准，有效预防和控制医院感染，防止传染病病原体、耐药菌、条件致病菌及其他病原微生物的传播。"},{"i":6,"n":"第六条","txt":"住院床位总数在100张以上的医院应当设立医院感染管理委员会和独立的医院感染管理部门。 住院床位总数在100张以下的医院应当指定分管医院感染管理工作的部门。 其他医疗机构应当有医院感染管理专（兼）职人员。"},{"i":7,"n":"第七条","txt":"医院感染管理委员会由医院感染管理部门、医务部门、护理部门、临床科室、消毒供应室、手术室、临床检验部门、药事管理部门、设备管理部门、后勤管理部门及其他有关部门的主要负责人组成，主任委员由医院院长或者主管医疗工作的副院长担任。 医院感染管理委员会的职责是： （一）认真贯彻医院感染管理方面的法律法规及技术规范、标准，制定本医院预防和控制医院感染的规章制度、医院感染诊断标准并监督实施； （二）根据预防医院感染和卫生学要求，对本医院的建筑设计、重点科室建设的基本标准、基本设施和工作流程进行审查并提出意见； （三）研究并确定本医院的医院感染管理工作计划，并对计划的实施进行考核和评价； （四）研究并确定本医院的医院感染重点部门、重点环节、重点流程、危险因素以及采取的干预措施，明确各有关部门、人员在预防和控制医院感染工作中的责任； （五）研究并制定本医院发生医院感染暴发及出现不明原因传染性疾病或者特殊"},{"i":8,"n":"第八条","txt":"医院感染管理部门、分管部门及医院感染管理专（兼）职人员具体负责医院感染预防与控制方面的管理和业务工作。主要职责是： （一）对有关预防和控制医院感染管理规章制度的落实情况进行检查和指导； （二）对医院感染及其相关危险因素进行监测、分析和反馈，针对问题提出控制措施并指导实施； （三）对医院感染发生状况进行调查、统计分析，并向医院感染管理委员会或者医疗机构负责人报告； （四）对医院的清洁、消毒灭菌与隔离、无菌操作技术、医疗废物管理等工作提供指导； （五）对传染病的医院感染控制工作提供指导； （六）对医务人员有关预防医院感染的职业卫生安全防护工作提供指导； （七）对医院感染暴发事件进行报告和调查分析，提出控制措施并协调、组织有关部门进行处理； （八）对医务人员进行预防和控制医院感染的培训工作； （九）参与抗菌药物临床应用的管理工作； （十）对消毒药械和一次性使用医疗器械、器具的相关证明进行审核"},{"i":9,"n":"第九条","txt":"卫生部成立医院感染预防与控制专家组，成员由医院感染管理、疾病控制、传染病学、临床检验、流行病学、消毒学、临床药学、护理学等专业的专家组成。主要职责是： （一）研究起草有关医院感染预防与控制、医院感染诊断的技术性标准和规范； （二）对全国医院感染预防与控制工作进行业务指导； （三）对全国医院感染发生状况及危险因素进行调查、分析； （四）对全国重大医院感染事件进行调查和业务指导； （五）完成卫生部交办的其他工作。"},{"i":10,"n":"第十条","txt":"省级人民政府卫生行政部门成立医院感染预防与控制专家组，负责指导本地区医院感染预防与控制的技术性工作。"},{"i":11,"n":"第十一条","txt":"医疗机构应当按照有关医院感染管理的规章制度和技术规范，加强医院感染的预防与控制工作。"},{"i":12,"n":"第十二条","txt":"医疗机构应当按照《消毒管理办法》，严格执行医疗器械、器具的消毒工作技术规范，并达到以下要求： （一）进入人体组织、无菌器官的医疗器械、器具和物品必须达到灭菌水平； （二）接触皮肤、粘膜的医疗器械、器具和物品必须达到消毒水平； （三）各种用于注射、穿刺、采血等有创操作的医疗器具必须一用一灭菌。 医疗机构使用的消毒药械、一次性医疗器械和器具应当符合国家有关规定。一次性使用的医疗器械、器具不得重复使用。"},{"i":13,"n":"第十三条","txt":"医疗机构应当制定具体措施，保证医务人员的手卫生、诊疗环境条件、无菌操作技术和职业卫生防护工作符合规定要求，对医院感染的危险因素进行控制。"},{"i":14,"n":"第十四条","txt":"医疗机构应当严格执行隔离技术规范，根据病原体传播途径，采取相应的隔离措施。"},{"i":15,"n":"第十五条","txt":"医疗机构应当制定医务人员职业卫生防护工作的具体措施，提供必要的防护物品，保障医务人员的职业健康。"},{"i":16,"n":"第十六条","txt":"医疗机构应当严格按照《抗菌药物临床应用指导原则》，加强抗菌药物临床使用和耐药菌监测管理。"},{"i":17,"n":"第十七条","txt":"医疗机构应当按照医院感染诊断标准及时诊断医院感染病例，建立有效的医院感染监测制度，分析医院感染的危险因素，并针对导致医院感染的危险因素，实施预防与控制措施。 医疗机构应当及时发现医院感染病例和医院感染的暴发，分析感染源、感染途径，采取有效的处理和控制措施，积极救治患者。"},{"i":18,"n":"第十八条","txt":"医疗机构经调查证实发生以下情形时，应当于12小时内向所在地的县级地方人民政府卫生行政部门报告，并同时向所在地疾病预防控制机构报告。所在地的县级地方人民政府卫生行政部门确认后，应当于24小时内逐级上报至省级人民政府卫生行政部门。省级人民政府卫生行政部门审核后，应当在24小时内上报至卫生部： （一）5例以上医院感染暴发； （二）由于医院感染暴发直接导致患者死亡； （三）由于医院感染暴发导致3人以上人身损害后果。"},{"i":19,"n":"第十九条","txt":"医疗机构发生以下情形时，应当按照《国家突发公共卫生事件相关信息报告管理工作规范（试行）》的要求进行报告： （一）10例以上的医院感染暴发事件； （二）发生特殊病原体或者新发病原体的医院感染； （三）可能造成重大公共影响或者严重后果的医院感染。"},{"i":20,"n":"第二十条","txt":"医疗机构发生的医院感染属于法定传染病的，应当按照《中华人民共和国传染病防治法》和《国家突发公共卫生事件应急预案》的规定进行报告和处理。"},{"i":21,"n":"第二十一条","txt":"医疗机构发生医院感染暴发时，所在地的疾病预防控制机构应当及时进行流行病学调查，查找感染源、感染途径、感染因素，采取控制措施，防止感染源的传播和感染范围的扩大。"},{"i":22,"n":"第二十二条","txt":"卫生行政部门接到报告，应当根据情况指导医疗机构进行医院感染的调查和控制工作，并可以组织提供相应的技术支持。"},{"i":23,"n":"第二十三条","txt":"各级卫生行政部门和医疗机构应当重视医院感染管理的学科建设，建立专业人才培养制度，充分发挥医院感染专业技术人员在预防和控制医院感染工作中的作用。"},{"i":24,"n":"第二十四条","txt":"省级人民政府卫生行政部门应当建立医院感染专业人员岗位规范化培训和考核制度，加强继续教育，提高医院感染专业人员的业务技术水平。"},{"i":25,"n":"第二十五条","txt":"医疗机构应当制定对本机构工作人员的培训计划，对全体工作人员进行医院感染相关法律法规、医院感染管理相关工作规范和标准、专业技术知识的培训。"},{"i":26,"n":"第二十六条","txt":"医院感染专业人员应当具备医院感染预防与控制工作的专业知识，并能够承担医院感染管理和业务技术工作。"},{"i":27,"n":"第二十七条","txt":"医务人员应当掌握与本职工作相关的医院感染预防与控制方面的知识，落实医院感染管理规章制度、工作规范和要求。工勤人员应当掌握有关预防和控制医院感染的基础卫生学和消毒隔离知识，并在工作中正确运用。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府卫生行政部门应当按照有关法律法规和本办法的规定，对所辖区域的医疗机构进行监督检查。"},{"i":29,"n":"第二十九条","txt":"对医疗机构监督检查的主要内容是： （一）医院感染管理的规章制度及落实情况； （二）针对医院感染危险因素的各项工作和控制措施； （三）消毒灭菌与隔离、医疗废物管理及医务人员职业卫生防护工作状况； （四）医院感染病例和医院感染暴发的监测工作情况； （五）现场检查。"},{"i":30,"n":"第三十条","txt":"卫生行政部门在检查中发现医疗机构存在医院感染隐患时，应当责令限期整改或者暂时关闭相关科室或者暂停相关诊疗科目。"},{"i":31,"n":"第三十一条","txt":"医疗机构对卫生行政部门的检查、调查取证等工作，应当予以配合，不得拒绝和阻碍，不得提供虚假材料。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府卫生行政部门未按照本办法的规定履行监督管理和对医院感染暴发事件的报告、调查处理职责，造成严重后果的，对卫生行政主管部门主要负责人、直接责任人和相关责任人予以降级或者撤职的行政处分。"},{"i":33,"n":"第三十三条","txt":"医疗机构违反本办法，有下列行为之一的，由县级以上地方人民政府卫生行政部门责令改正，逾期不改的，给予警告并通报批评；情节严重的，对主要负责人和直接责任人给予降级或者撤职的行政处分： （一）未建立或者未落实医院感染管理的规章制度、工作规范； （二）未设立医院感染管理部门、分管部门以及指定专（兼）职人员负责医院感染预防与控制工作； （三）违反对医疗器械、器具的消毒工作技术规范； （四）违反无菌操作技术规范和隔离技术规范； （五）未对消毒药械和一次性医疗器械、器具的相关证明进行审核； （六）未对医务人员职业暴露提供职业卫生防护。"},{"i":34,"n":"第三十四条","txt":"医疗机构违反本办法规定，未采取预防和控制措施或者发生医院感染未及时采取控制措施，造成医院感染暴发、传染病传播或者其他严重后果的，对负有责任的主管人员和直接责任人员给予降级、撤职、开除的行政处分；情节严重的，依照《传染病防治法》第六十九条规定，可以依法吊销有关责任人员的执业证书；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"医疗机构发生医院感染暴发事件未按本办法规定报告的，由县级以上地方人民政府卫生行政部门通报批评；造成严重后果的，对负有责任的主管人员和其他直接责任人员给予降级、撤职、开除的处分。"},{"i":36,"n":"第三十六条","txt":"本办法中下列用语的含义： （一）医院感染：指住院病人在医院内获得的感染，包括在住院期间发生的感染和在医院内获得出院后发生的感染，但不包括入院前已开始或者入院时已处于潜伏期的感染。医院工作人员在医院内获得的感染也属医院感染。 （二）医源性感染：指在医学服务中，因病原体传播引起的感染。 （三）医院感染暴发：是指在医疗机构或其科室的患者中，短时间内发生3例以上同种同源感染病例的现象。 （四）消毒：指用化学、物理、生物的方法杀灭或者消除环境中的病原微生物。 （五）灭菌：杀灭或者消除传播媒介上的一切微生物，包括致病微生物和非致病微生物，也包括细菌芽胞和真菌孢子。"},{"i":37,"n":"第三十七条","txt":"中国人民解放军医疗机构的医院感染管理工作，由中国人民解放军卫生部门归口管理。"},{"i":38,"n":"第三十八条","txt":"采供血机构与疾病预防控制机构的医源性感染预防与控制管理参照本办法。"},{"i":39,"n":"第三十九条","txt":"本办法自2006年9月1日起施行，原2000年11月30日颁布的《医院感染管理规范（试行）》同时废止。"}],"dancaixiejiangzhanguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强单采血浆站的监督管理，预防和控制经血液途径传播的疾病，保障供血浆者健康，保证原料血浆质量，根据《血液制品管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称单采血浆站是指根据地区血源资源，按照有关标准和要求并经严格审批设立，采集供应血液制品生产用原料血浆的单位。 单采血浆站由血液制品生产单位设置，具有独立的法人资格。其他任何单位和个人不得从事单采血浆活动。"},{"i":3,"n":"第三条","txt":"本办法所称供血浆者是指提供血液制品生产用原料血浆的人员。 划定采浆区域内具有当地户籍的18岁到55岁健康公民可以申请登记为供血浆者。"},{"i":4,"n":"第四条","txt":"国家卫生计生委根据全国生产用原料血浆的需求、经济发展状况、疾病流行情况等，制定全国采供血机构设置规划指导原则。 省、自治区、直辖市人民政府卫生计生行政部门根据国家卫生计生委《采供血机构设置规划指导原则》，结合本行政区域疾病流行、供血浆能力等实际情况和当地区域卫生发展规划，制定本地区的单采血浆站设置规划，并组织实施。单采血浆站设置规划应当报国家卫生计生委备案。"},{"i":5,"n":"第五条","txt":"国家卫生计生委负责全国单采血浆站的监督管理工作。 县级以上地方人民政府卫生计生行政部门负责本行政区域内单采血浆站的监督管理工作。"},{"i":6,"n":"第六条","txt":"血液制品生产单位设置单采血浆站应当符合当地单采血浆站设置规划，并经省、自治区、直辖市人民政府卫生计生行政部门批准。"},{"i":7,"n":"第七条","txt":"单采血浆站应当设置在县（旗）及县级市，不得与一般血站设置在同一县级行政区域内。 有地方病或者经血传播的传染病流行、高发的地区不得规划设置单采血浆站。 上一年度和本年度自愿无偿献血未能满足临床用血的市级行政区域内不得新建单采血浆站。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市人民政府卫生计生行政部门根据实际情况，划定单采血浆站的采浆区域。采浆区域的选择应当保证供血浆者的数量，能满足原料血浆年采集量不少于30吨。新建单采血浆站在3年内达到年采集量不少于30吨。"},{"i":9,"n":"第九条","txt":"设置单采血浆站必须具备下列条件： （一）符合采供血机构设置规划、单采血浆站设置规划以及《单采血浆站基本标准》要求的条件； （二）具有与所采集原料血浆相适应的卫生专业技术人员； （三）具有与所采集原料血浆相适应的场所及卫生环境； （四）具有识别供血浆者的身份识别系统； （五）具有与所采集原料血浆相适应的单采血浆机械及其他设施； （六）具有对所采集原料血浆进行质量检验的技术人员以及必要的仪器设备； （七）符合国家生物安全管理相关规定。"},{"i":10,"n":"第十条","txt":"申请设置单采血浆站的血液制品生产单位，应当向单采血浆站设置地的县级人民政府卫生计生行政部门提交《设置单采血浆站申请书》，并提交下列材料： （一）申请设置单采血浆站的血液制品生产单位的有关情况以及法人登记证书； （二）拟设单采血浆站的可行性研究报告。内容包括： 1.拟设单采血浆站基本情况，包括名称、地址、规模、任务、功能、组织结构等； 2.拟设单采血浆站血浆采集区域及区域内疾病流行状况、适龄健康供血浆人口情况、机构运行及环境保护措施的预测分析； 3.拟设单采血浆站的选址和建筑设计平面图； 4.申请开展的业务项目、技术设备条件资料； 5.污水、污物以及医疗废物处理方案； （三）单采血浆站用房的房屋产权证明或者使用权证明； （四）拟设单采血浆站的法定代表人及其主要负责人的身份证明文件和专业履历； （五）单采血浆站从业人员名单及资格证书； （六）单采血浆站的各项规章制度。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，不得申请设置新的单采血浆站： （一）拟设置的单采血浆站不符合采供血机构设置规划或者当地单采血浆站设置规划要求的； （二）省级卫生计生行政部门未同意划定采浆区域的； （三）血液制品生产单位被吊销药品生产质量管理规范（GMP）证书未满5年的； （四）血液制品生产单位发生过非法采集血浆或者擅自调用血浆行为的； （五）血液制品生产单位注册的血液制品少于6个品种的，承担国家计划免疫任务的血液制品生产单位少于5个品种的。"},{"i":12,"n":"第十二条","txt":"下列人员不得作为新建单采血浆站的法定代表人或者主要负责人： （一）正在服刑或者不具有完全民事行为能力的人； （二）发生血液安全事故未满5年的责任人； （三）被吊销《单采血浆许可证》或者《血站执业许可证》未满10年的单采血浆站或者血站的法定代表人、主要负责人及责任人； （四）被吊销药品生产质量管理规范（GMP）证书未满5年的血液制品生产单位法定代表人或者主要负责人； （五）被卫生计生行政部门责令限期改正3个月以上或者给予罚款5万-10万元处罚未满3年的单采血浆站的法定代表人、主要负责人及责任人。"},{"i":13,"n":"第十三条","txt":"县级人民政府卫生计生行政部门在收到全部申请材料后进行初审，经设区的市、自治州人民政府卫生计生行政部门审查同意后，报省级人民政府卫生计生行政部门审批。"},{"i":14,"n":"第十四条","txt":"省级人民政府卫生计生行政部门在收到单采血浆站申请材料后，可以组织有关专家或者委托技术机构，根据《单采血浆站质量管理规范》进行技术审查。 经审查符合条件的，由省级人民政府卫生计生行政部门核发《单采血浆许可证》，并在设置审批后10日内报国家卫生计生委备案；经审查不符合条件的，应当将不予批准的理由书面通知申请人。"},{"i":15,"n":"第十五条","txt":"申请设置单采血浆站不符合本办法第九条、第十一条、第十二条规定的不予批准。"},{"i":16,"n":"第十六条","txt":"《单采血浆许可证》有效期为2年。 《单采血浆许可证》的主要内容为： （一）设置单采血浆站的血液制品生产单位名称； （二）单采血浆站的名称、地址、法定代表人或者主要负责人； （三）业务项目及采浆区域（范围）； （四）发证机关、发证日期、许可证号和有效期。"},{"i":17,"n":"第十七条","txt":"《单采血浆许可证》有效期满前3个月，单采血浆站应当向原发证部门申请延续，并提交下列材料： （一）《单采血浆许可证》的复印件； （二）执业期间运行情况的报告，包括原料血浆采集的数量、定期自检报告等； （三）卫生计生行政部门监督检查的意见及整改情况等； （四）技术机构根据《单采血浆站质量管理规范》出具的技术审查报告。"},{"i":18,"n":"第十八条","txt":"省级人民政府卫生计生行政部门根据单采血浆站上一执业周期业务开展情况、技术审查和监督检查等情况进行审核，审核合格的，予以延续。经审核不合格的，责令其限期整改；经整改仍不合格的，注销其《单采血浆许可证》。 未办理延续申请或者被注销《单采血浆许可证》的单采血浆站，不得继续执业。"},{"i":19,"n":"第十九条","txt":"单采血浆站变更名称、地址、法定代表人、业务项目等内容的，应当向原发证部门办理变更登记手续。 设置单采血浆站的血液制品生产单位发生变更的，该单采血浆站应当重新办理《单采血浆许可证》，原《单采血浆许可证》注销。"},{"i":20,"n":"第二十条","txt":"县级以上地方各级人民政府卫生计生行政部门审核批准设置单采血浆站的程序和期限，按照《行政许可法》、《卫生行政许可管理办法》等有关规定执行。"},{"i":21,"n":"第二十一条","txt":"单采血浆站执业，应当遵守有关法律、法规、规章和技术规范。 单采血浆站的法定代表人或者主要负责人应当对采集的原料血浆质量安全负责。"},{"i":22,"n":"第二十二条","txt":"单采血浆站应当在规定的采浆区域内组织、动员供血浆者，并对供血浆者进行相应的健康教育，为供血浆者提供安全、卫生、便利的条件和良好的服务。"},{"i":23,"n":"第二十三条","txt":"单采血浆站应当按照《中华人民共和国药典》血液制品原料血浆规程对申请供血浆者进行健康状况征询、健康检查和血样化验，并按照国家卫生计生委发布的供血浆者须知对供血浆者履行告知义务。 对健康检查合格的申请供血浆者，核对身份证后，填写供血浆者名册，报所在地县级人民政府卫生计生行政部门。省级人民政府卫生计生行政部门应当在本省和相邻省内进行供血浆者信息检索，确认未在其他单采血浆站登记，将有关信息进行反馈，由县级人民政府卫生计生行政部门发给《供血浆证》。 《供血浆证》内容至少应当包括：姓名、性别、血型、民族、身份证号码、2年内免冠证件照、家庭住址、建卡日期和编号。"},{"i":24,"n":"第二十四条","txt":"有下列情况之一的，不予发给《供血浆证》： （一）健康检查、化验不合格的； （二）曾伪造身份证明，持有2个以上《供血浆证》的； （三）已在其他单采血浆站登记为供血浆者的； （四）当地户籍部门未能核实其身份信息的。"},{"i":25,"n":"第二十五条","txt":"单采血浆站应当建立供血浆者管理档案，记录供血浆者供血浆情况、健康检查情况。建立供血浆者永久淘汰、暂时拒绝及不予发放《供血浆证》者档案名册。同时采用计算机管理档案并建立供血浆者身份识别系统。"},{"i":26,"n":"第二十六条","txt":"单采血浆站在采集血浆中发现《供血浆证》内容变更的，或者供血浆者健康检查不合格的，应当收缴《供血浆证》并及时告知当地县级人民政府卫生计生行政部门。"},{"i":27,"n":"第二十七条","txt":"单采血浆站应当根据登记的供血浆者供血浆实际情况和血液制品生产单位原料血浆需求情况，制定采浆工作计划，合理安排供血浆者供血浆。"},{"i":28,"n":"第二十八条","txt":"单采血浆站采集原料血浆应当遵循自愿和知情同意的原则。 对需要进行特殊免疫的供血浆者，应当告知特殊免疫的意义、作用、方法、步骤和不良反应，征得供血浆者本人书面同意后，方可按照国家规定的免疫程序进行免疫。免疫情况和不良反应处理应当详细记录。"},{"i":29,"n":"第二十九条","txt":"单采血浆站在每次采集血浆前，必须将供血浆者持有的身份证或者其他有效身份证明、《供血浆证》与计算机档案管理内容进行核实，确认无误的，方可按照规定程序进行健康检查和血样化验；对检查、化验合格的，按照有关技术操作标准和程序采集血浆，并详细记录。"},{"i":30,"n":"第三十条","txt":"单采血浆站必须使用单采血浆机械采集血浆，严禁手工采集血浆。 每次采集供血浆者的血浆量不得超过580毫升（含抗凝剂溶液，以容积比换算质量比不超过600克）。严禁超量采集血浆。 两次供血浆时间间隔不得少于14天。严禁频繁采集血浆。 严禁采集非划定采浆区域内供血浆者的血浆。严禁采集冒名顶替者及无《供血浆证》者的血浆。 严禁采集血液或者将所采集的原料血浆用于临床。"},{"i":31,"n":"第三十一条","txt":"单采血浆站应当建立对有易感染经血液传播疾病危险行为的供血浆者供血浆后的报告工作程序、供血浆者屏蔽和淘汰制度。"},{"i":32,"n":"第三十二条","txt":"单采血浆站应当对血浆采集工作实行全面质量管理，严格遵守《中华人民共和国药典》血液制品原料血浆规程、《单采血浆站质量管理规范》等技术规范和标准。"},{"i":33,"n":"第三十三条","txt":"单采血浆站应当建立人员岗位责任制和采供血浆管理相关工作制度，并定期检查、考核各项规章制度和各级各类人员岗位责任制的执行和落实情况。"},{"i":34,"n":"第三十四条","txt":"单采血浆站应当对关键岗位工作人员进行岗位培训与考核。单采血浆站关键岗位工作人员应当符合岗位执业资格的规定，并经岗位培训与考核合格后方可上岗。 单采血浆站工作人员每人每年应当接受不少于75学时的岗位继续教育。 省级人民政府卫生计生行政部门应当制定单采血浆站工作人员培训标准或指南，并对单采血浆站开展的岗位培训、考核工作进行指导和监督。"},{"i":35,"n":"第三十五条","txt":"单采血浆站各业务岗位工作记录应当内容真实、项目完整、格式规范、字迹清楚、记录及时，有操作者和复核者签名。 记录内容需要更改时，应当保持原记录内容清晰可辨，注明更改内容和日期，并在更改处签名。 血浆采集、检测和供浆的原始记录应当至少保存10年，法律、法规和国家卫生计生委另有规定的，依照有关规定执行。"},{"i":36,"n":"第三十六条","txt":"单采血浆站应当保证所采集的血浆均进行严格的检测。"},{"i":37,"n":"第三十七条","txt":"血浆采集后必须单人份冰冻保存，严禁混浆。"},{"i":38,"n":"第三十八条","txt":"单采血浆站应当制定实验室室内质控与室间质评制度，并定期参加省级以上室间质量考评，确保试剂、卫生器材、仪器、设备在使用过程中能达到预期效果。 单采血浆站的实验室应当配备必要的生物安全设备和设施，工作人员应当接受生物安全知识培训。"},{"i":39,"n":"第三十九条","txt":"单采血浆站所采集的每袋血浆必须留存血浆标本，保存期应不少于血液制品生产投料后2年。"},{"i":40,"n":"第四十条","txt":"单采血浆站应当加强消毒、隔离工作管理，预防和控制感染性疾病的传播。 单采血浆站产生的医疗废物应当按照《医疗废物管理条例》规定处理，做好记录与签字，避免交叉感染。"},{"i":41,"n":"第四十一条","txt":"单采血浆站及其执行职务的人员发现法定传染病疫情时，应当按照《传染病防治法》和国家卫生计生委的规定向有关部门报告。"},{"i":42,"n":"第四十二条","txt":"原料血浆的采集、包装、储存、运输应当符合《单采血浆站质量管理规范》的要求。 原料血浆包装袋标签上必须标明： （一）单采血浆站的名称； （二）供血浆者姓名、编号或者条形码； （三）血浆重量、血浆类型、采集日期、血浆编号、有效期； （四）储存条件。 原料血浆储存、运输装箱时，每箱内均应有装箱单，并附有化验合格单以及血浆复检标本。"},{"i":43,"n":"第四十三条","txt":"单采血浆站只能向设置其的血液制品生产单位供应原料血浆。 单采血浆站应当保证发出的原料血浆质量符合国家有关标准，其品种、规格、数量无差错，血浆的生物活性保存完好。"},{"i":44,"n":"第四十四条","txt":"单采血浆站使用的药品、体外诊断试剂、一次性卫生器材应当符合国家有关规定。"},{"i":45,"n":"第四十五条","txt":"单采血浆站必须使用计算机系统管理供血浆者信息、采供血浆和相关工作过程。建立血浆标识的管理程序，确保所有血浆可以追溯到相应的供血浆者和供血浆过程，确保所使用的物料批号以及所有制备、检验、运输记录完整。血浆标识应当采用条形码技术。同一血浆条形码至少50年不重复。"},{"i":46,"n":"第四十六条","txt":"单采血浆站应当每半年向所在地县级人民政府卫生计生行政部门报告有关原料血浆采集情况。"},{"i":47,"n":"第四十七条","txt":"单采血浆站应当制定紧急灾害应急预案，并从血源、管理制度、技术能力和设备条件等方面保证预案的实施。在紧急灾害发生时服从县级以上人民政府卫生计生行政部门的调遣。"},{"i":48,"n":"第四十八条","txt":"单采血浆站必须严格执行国家有关报废血处理和有易感染经血液传播疾病危险行为的供血浆者供血浆后保密性弃血处理的规定。"},{"i":49,"n":"第四十九条","txt":"单采血浆站的工作人员必须每年进行一次体格检查，建立职工健康档案。患有传染病、严重皮肤感染和体表伤口未愈者，不得从事采集血浆、检验、消毒、供应等岗位工作。"},{"i":50,"n":"第五十条","txt":"单采血浆站每年应当委托技术机构按照《单采血浆站质量管理规范》要求进行不少于一次的技术审查。"},{"i":51,"n":"第五十一条","txt":"技术机构提供的单采血浆站技术评价、检测结果应当客观、真实。"},{"i":52,"n":"第五十二条","txt":"县级以上地方人民政府卫生计生行政部门负责本行政区域内单采血浆站监督管理工作，制定年度监督检查计划，检查内容包括： （一）执行法律、法规、规章、技术标准和规范情况； （二）单采血浆站各项规章制度和工作人员岗位责任制落实情况； （三）供血浆者管理，检验，原料血浆的采集、保存、供应等； （四）单采血浆站定期自检和重大事故报告情况。 县级人民政府卫生计生行政部门依照本办法的规定负责本行政区域内单采血浆站的日常监督管理工作。 设区的市级人民政府卫生计生行政部门至少每半年对本行政区域内单采血浆站进行一次检查和不定期抽查。 省级人民政府卫生计生行政部门至少每年组织一次对本行政区域内单采血浆站的监督检查和不定期抽查。 上级卫生计生行政部门应当定期或者不定期监督检查辖区内原料血浆管理工作，并及时向下级卫生计生行政部门通报监督检查情况。"},{"i":53,"n":"第五十三条","txt":"负责单采血浆站审批和监督的卫生计生行政部门要建立信息沟通制度，将审批、监督检查情况等信息相互通告，保证工作的有效衔接。 省级人民政府卫生计生行政部门要在单采血浆站建立公示制度，对单采血浆站的基本情况、执业情况、卫生计生行政部门监督检查情况以及投诉、举报电话进行公示。"},{"i":54,"n":"第五十四条","txt":"省级以上人民政府卫生计生行政部门应当指定有关血液检定机构，对单采血浆站采集的血浆质量进行监测，监测结果报同级人民政府卫生计生行政部门。"},{"i":55,"n":"第五十五条","txt":"为单采血浆站出具技术审查报告的技术机构，应当符合条件并由省级以上人民政府卫生计生行政部门指定。"},{"i":56,"n":"第五十六条","txt":"卫生计生行政部门在进行监督检查时，有权索取有关资料，单采血浆站不得隐瞒、阻碍或者拒绝。 卫生计生行政部门对单采血浆站提供的资料负有保密的义务，法律、行政法规或者部门规章另有规定的除外。"},{"i":57,"n":"第五十七条","txt":"各级人民政府卫生计生行政部门应当建立单采血浆站监督管理的举报、投诉机制。 卫生计生行政部门对举报人和投诉人负有保密的义务。"},{"i":58,"n":"第五十八条","txt":"县级以上地方人民政府卫生计生行政部门应当按有关规定定期将原料血浆的采集情况逐级上报。 省、自治区、直辖市人民政府卫生计生行政部门应当每年向国家卫生计生委汇总报告本行政区域内原料血浆的采集情况。"},{"i":59,"n":"第五十九条","txt":"省级人民政府卫生计生行政部门应当建立供血浆者信息管理系统，并向有关部门提供检索查询信息。"},{"i":60,"n":"第六十条","txt":"上一级人民政府卫生计生行政部门有权纠正或者撤销下一级人民政府卫生计生行政部门作出的不符合规定的行政行为。"},{"i":61,"n":"第六十一条","txt":"单采血浆站有下列行为之一的，由县级以上地方人民政府卫生计生行政部门依据《血液制品管理条例》第三十四条的有关规定予以处罚： （一）未取得《单采血浆许可证》开展采供血浆活动的； （二）《单采血浆许可证》已被注销或者吊销仍开展采供血浆活动的； （三）租用、借用、出租、出借、变造、伪造《单采血浆许可证》开展采供血浆活动的。"},{"i":62,"n":"第六十二条","txt":"单采血浆站违反本办法有关规定，有下列行为之一的，由县级以上地方人民政府卫生计生行政部门予以警告，并处3万元以下的罚款： （一）隐瞒、阻碍、拒绝卫生计生行政部门监督检查或者不如实提供有关资料的； （二）对供血浆者未履行事先告知义务，未经供血浆者同意开展特殊免疫的； （三）未按照规定建立供血浆者档案管理及屏蔽、淘汰制度的； （四）未按照规定制订各项工作制度或者不落实的； （五）工作人员未取得相关岗位执业资格或者未经执业注册从事采供血浆工作的； （六）不按照规定记录或者保存工作记录的； （七）未按照规定保存血浆标本的。"},{"i":63,"n":"第六十三条","txt":"单采血浆站有下列情形之一的，按照《血液制品管理条例》第三十五条规定予以处罚： （一）采集血浆前，未按照有关健康检查要求对供血浆者进行健康检查、血液化验的； （二）采集非划定区域内的供血浆者或者其他人员血浆的；或者不对供血浆者进行身份识别，采集冒名顶替者、健康检查不合格者或者无《供血浆证》者的血浆的； （三）超量、频繁采集血浆的； （四）向医疗机构直接供应原料血浆或者擅自采集血液的； （五）未使用单采血浆机械进行血浆采集的； （六）未使用有产品批准文号并经国家药品生物制品检定机构逐批检定合格的体外诊断试剂以及合格的一次性采血浆器材的； （七）未按照国家规定的卫生标准和要求包装、储存、运输原料血浆的； （八）未按照规定对污染的注射器、采血浆器材、不合格或者报废血浆进行处理，擅自倾倒，污染环境，造成社会危害的； （九）重复使用一次性采血浆器材的； （十）向设置单采血浆站的血液制品生产单位以外"},{"i":64,"n":"第六十四条","txt":"单采血浆站已知其采集的血浆检测结果呈阳性，仍向血液制品生产单位供应的，按照《血液制品管理条例》第三十六条规定予以处罚。"},{"i":65,"n":"第六十五条","txt":"涂改、伪造、转让《供血浆证》的，按照《血液制品管理条例》第三十七条规定予以处罚。"},{"i":66,"n":"第六十六条","txt":"违反《血液制品管理条例》和本办法规定，擅自出口原料血浆的，按照《血液制品管理条例》第四十二条规定予以处罚。"},{"i":67,"n":"第六十七条","txt":"承担单采血浆站技术评价、检测的技术机构出具虚假证明文件的，由卫生计生行政部门责令改正，给予警告，并可处2万元以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"本办法自2008年3月1日起实行。"}],"weishengxingzhengchufachengxu":[{"i":1,"n":"第一条","txt":"为保证卫生行政机关正确行使行政处罚职权，保护公民、法人和其他组织的合法权益，维护公共利益和社会秩序，根据《行政处罚法》和有关卫生法律、法规的规定，制定本程序。"},{"i":2,"n":"第二条","txt":"本程序所指行政处罚，是指县级以上卫生行政机关依据卫生法律、法规、规章，对应受制裁的违法行为，作出的警告、罚款、没收违法所得、责令停产停业、吊销许可证以及卫生法律、行政法规规定的其他行政处罚。"},{"i":3,"n":"第三条","txt":"县级以上卫生行政机关对违反卫生法律、法规、规章的单位或个人进行行政处罚，适用本程序。 卫生法律、法规授予卫生行政处罚职权的卫生机构行使卫生行政处罚权的，依照本程序执行。"},{"i":4,"n":"第四条","txt":"卫生行政机关实施行政处罚必须事实清楚，证据确凿，适用法律、法规、规章正确，坚持先调查取证后裁决、合法、适当、公正、公开和处罚与教育相结合的原则。"},{"i":5,"n":"第五条","txt":"卫生行政机关应当建立对卫生行政处罚的监督制度。上级卫生行政机关对下级卫生行政机关实施行政处罚进行监督，卫生行政机关内部法制机构对本机关实施行政处罚进行监督。"},{"i":6,"n":"第六条","txt":"县级以上卫生行政机关负责查处所辖区域内的违反卫生法律、法规、规章的案件。 省级卫生行政机关可依据卫生法律、法规、规章和本地区的实际，规定所辖区内管辖的具体分工。 卫生部负责查处重大、复杂的案件。"},{"i":7,"n":"第七条","txt":"上级卫生行政机关可将自己管辖的案件移交下级卫生行政机关处理；也可根据下级卫生行政机关的请求处理下级卫生行政机关管辖的案件。"},{"i":8,"n":"第八条","txt":"两个以上卫生行政机关，在管辖发生争议时，报请其共同的上级卫生行政机关指定管辖。"},{"i":9,"n":"第九条","txt":"卫生行政机关发现查处的案件不属于自己管辖，应当及时书面移送给有管辖权的卫生行政机关。 受移送的卫生行政机关应当将案件查处结果函告移送的卫生行政机关。 受移送地的卫生行政机关如果认为移送不当，应当报请共同的上级卫生行政机关指定管辖，不得再自行移送。"},{"i":10,"n":"第十条","txt":"上级卫生行政机关在接到有关解决管辖争议或者报请移送管辖的请示后，应当在十日内作出具体管辖决定。"},{"i":11,"n":"第十一条","txt":"国境卫生检疫机关依据国境卫生检疫法律、法规实施的行政处罚，由违法行为发生地的国境卫生检疫机关管辖。 卫生部卫生检疫局负责查处重大、复杂的案件。 卫生部卫生检疫局下设的国境卫生检疫机关间对管辖发生争议时，报请卫生部卫生检疫局指定管辖。"},{"i":12,"n":"第十二条","txt":"法律、法规规定的受卫生部委托的有关部门的卫生主管机构，或者由卫生部会同其规定监督职责的国务院有关部门的卫生主管机构，负责规定管辖范围内的案件。"},{"i":13,"n":"第十三条","txt":"卫生行政机关与第十二条所指的有关部门的卫生主管机构对管辖发生争议的，报请省级卫生行政机关指定管辖。"},{"i":14,"n":"第十四条","txt":"卫生行政机关对下列案件应当及时受理并做好记录： （一）在卫生监督管理中发现的； （二）卫生机构监测报告的； （三）社会举报的； （四）上级卫生行政机关交办、下级卫生行政机关报请的或者有关部门移送的。"},{"i":15,"n":"第十五条","txt":"卫生行政机关受理的案件符合下列条件的，应当在七日内立案： （一）有明确的违法行为人或者危害后果； （二）有来源可靠的事实依据； （三）属于卫生行政处罚的范围； （四）属于本机关管辖。 卫生行政机关对决定立案的应当制作报告，由直接领导批准，并确定立案日期和两名以上卫生执法人员为承办人。"},{"i":16,"n":"第十六条","txt":"承办人有下列情形之一的，应当自行回避： （一）是本案当事人的近亲属； （二）与本案有利害关系； （三）与本案当事人有其他利害关系，可能影响案件公正处理的。 当事人有权申请承办人回避。 回避申请由受理的卫生行政机关负责人决定。"},{"i":17,"n":"第十七条","txt":"对于依法给予卫生行政处罚的违法行为，卫生行政机关应当调查取证，查明违法事实。案件的调查取证，必须有两名以上执法人员参加，并出示有关证件。 对涉及国家机密、商业秘密和个人隐私的，应当保守秘密。"},{"i":18,"n":"第十八条","txt":"卫生执法人员应分别询问当事人或证人，并当场制作询问笔录。询问笔录经核对无误后，卫生执法人员和被询问人应当在笔录上签名。被询问人拒绝签名的，应当由两名卫生执法人员在笔录上签名并注明情况。"},{"i":19,"n":"第十九条","txt":"卫生执法人员进行现场检查时，应制作现场检查笔录，笔录经核对无误后，卫生执法人员和被检查人应当在笔录上签名，被检查人拒绝签名的，应当由两名卫生执法人员在笔录上签名并注明情况。"},{"i":20,"n":"第二十条","txt":"调查取证的证据应当是原件、原物，调查取证原件、原物确有困难的，可由提交证据的单位或个人在复制品、照片等物件上签章，并注明“与原件（物）相同”字样或文字说明。"},{"i":21,"n":"第二十一条","txt":"书证、物证、视听材料、证人证言、当事人陈述、鉴定结论、勘验笔录、现场检查笔录等，经卫生执法人员审查或调查属实，为卫生行政处罚证据。"},{"i":22,"n":"第二十二条","txt":"卫生行政机关在收集证据时，在证据可能灭失、或者以后难以取得的情况下，经卫生行政机关负责人批准，可以先行登记保存。执法人员应向当事人出具由行政机关负责人签发的保存证据通知书。 卫生行政机关应当在七日内作出处理决定。卫生法律、法规另有规定的除外。"},{"i":23,"n":"第二十三条","txt":"卫生执法人员调查违法事实，需要采集鉴定检验样品的，应当填写采样记录。所采集的样品应标明编号并及时进行鉴定检验。"},{"i":24,"n":"第二十四条","txt":"调查终结后，承办人应当写出调查报告。其内容应当包括案由、案情、违法事实、违反法律、法规或规章的具体款项等。"},{"i":25,"n":"第二十五条","txt":"承办人在调查终结后，应当对违法行为的事实、性质、情节以及社会危害程度进行合议并作好记录，合议应当根据认定的违法事实，依照有关卫生法律、法规和规章的规定分别提出下列处理意见： （一）确有应当受行政处罚的违法行为的，依法提出卫生行政处罚的意见； （二）违法行为轻微的，依法提出不予卫生行政处罚的意见； （三）违法事实不能成立的，依法提出不予卫生行政处罚的意见； （四）违法行为不属于本机关管辖的，应当移送有管辖权的机关处理； （五）违法行为构成犯罪需要追究刑事责任的，应当移送司法机关。同时应当予以行政处罚的，还应当依法提出卫生行政处罚的意见。 除前款第一项、第五项所述情形之外，承办人应制作结案报告，并经本机关负责人批准后结案。"},{"i":26,"n":"第二十六条","txt":"卫生行政机关在作出合议之后，应当及时告知当事人行政处罚认定的事实、理由和依据，以及当事人依法享有的权利。适用听证程序的按本程序第三十三条规定。 卫生行政机关必须充分听取当事人的陈述和申辩，并进行复核，当事人提出的事实、理由或者证据成立的，应当采纳。 卫生行政机关不得因当事人申辩而加重处罚。"},{"i":27,"n":"第二十七条","txt":"对当事人违法事实已查清，依据卫生法律、法规、规章的规定应给予行政处罚的，承办人应起草行政处罚决定书文稿，报卫生行政机关负责人审批。 卫生行政机关负责人应根据情节轻重及具体情况作出行政处罚决定。对于重大、复杂的行政处罚案件，应当由卫生行政机关负责人集体讨论决定。 行政处罚决定作出后，卫生行政机关应当制作行政处罚决定书。"},{"i":28,"n":"第二十八条","txt":"卫生行政机关适用一般程序实施行政处罚时，对已有证据证明的违法行为，应当在发现违法行为或调查违法事实时，书面责令当事人改正或限期改正违法行为。"},{"i":29,"n":"第二十九条","txt":"卫生行政机关应当自立案之日起三个月内作出行政处罚决定。 因特殊原因，需要延长前款规定的时间的，应当报请上级卫生行政机关批准。省级卫生行政机关需要延长时间的，由省级卫生行政机关负责人集体讨论决定。"},{"i":30,"n":"第三十条","txt":"卫生行政机关在作出的责令停产停业、吊销许可证或者较大数额罚款等行政处罚决定前，应当告知当事人有要求举行听证的权利。当事人要求听证的，卫生行政机关应当组织听证。听证由卫生行政机关内部法制机构或主管法制工作的综合机构负责。 对较大数额罚款的听证范围依照省、自治区、直辖市人大常委会或人民政府的具体规定执行。 国境卫生检疫机关对二万元以上数额的罚款实行听证。"},{"i":31,"n":"第三十一条","txt":"听证遵循公正、公开的原则。除涉及国家秘密、商业秘密或者个人隐私外，听证应当以公开的方式进行。 听证实行告知、回避制度，依法保障当事人的陈述权和申辩权。"},{"i":32,"n":"第三十二条","txt":"听证由作出行政处罚的卫生行政机关组织。当事人不承担卫生行政机关听证的费用。"},{"i":33,"n":"第三十三条","txt":"卫生行政机关对于适用听证程序的卫生行政处罚案件，应当在作出行政处罚决定前，向当事人送达听证告知书。 听证告知书应当载明下列主要事项： （一）当事人的姓名或者名称； （二）当事人的违法行为、行政处罚的理由、依据和拟作出的行政处罚决定； （三）告知当事人有要求听证的权利； （四）告知提出听证要求的期限和听证组织机关。 听证告知书必须盖有卫生行政机关的印章。"},{"i":34,"n":"第三十四条","txt":"卫生行政机关决定予以听证的，听证主持人应当在当事人提出听证要求之日起二日内确定举行听证时间、地点和方式，并在举行听证的七日前，将听证通知书送达当事人。 听证通知书应载明下列事项并加盖卫生行政机关印章： （一）当事人的姓名或者名称； （二）举行听证的时间、地点和方式； （三）听证人员的姓名； （四）告知当事人有权申请回避； （五）告知当事人准备证据、通知证人等事项。"},{"i":35,"n":"第三十五条","txt":"当事人接到听证通知书后，应当按期出席听证会。因故不能如期参加听证的，应当事先告知主持听证的卫生行政机关，并且获得批准。无正当理由不按期参加听证的，视为放弃听证要求，卫生行政机关予以书面记载。在听证举行过程中当事人放弃申辩和退出听证的，卫生行政机关可以宣布听证终止，并记入听证笔录。"},{"i":36,"n":"第三十六条","txt":"卫生行政机关的听证人员包括听证主持人、听证员和书记员。 听证主持人由行政机关负责人指定本机关内部的非本案调查人员担任，一般由本机关法制机构人员或者专职法制人员担任。 听证员由卫生行政机关指定一至二名本机关内部的非本案调查人员担任。协助听证主持人组织听证。 书记员由卫生行政机关内部的一名非本案调查人员担任，负责听证笔录的制作和其他事务。"},{"i":37,"n":"第三十七条","txt":"当事人认为听证主持人、听证员和书记员与本案有利害关系的，有权申请回避。听证员和书记员的回避，由听证主持人决定；听证主持人的回避由听证机构行政负责人决定。"},{"i":38,"n":"第三十八条","txt":"有下列情形之一的，可以延期举行听证： （一）当事人有正当理由未到场的； （二）当事人提出回避申请理由成立，需要重新确定主持人的； （三）需要通知新的证人到场，或者有新的事实需要重新调查核实的； （四）其他需要延期的情形。"},{"i":39,"n":"第三十九条","txt":"举行听证时，案件调查人提出当事人违法事实、证据和适用听证程序的行政处罚建议，当事人进行陈述、申辩和质证。 案件调查人员对认定的事实负有举证责任，当事人对自己提出的主张负有举证责任。"},{"i":40,"n":"第四十条","txt":"听证应当制作笔录，听证笔录应当载明下列事项： （一）案由； （二）听证参加人姓名或名称、地址； （三）听证主持人、听证员、书记员姓名； （四）举行听证的时间、地点、方式； （五）案件调查人员提出的事实、证据和适用听证程序的行政处罚建议； （六）当事人陈述、申辩和质证的内容； （七）听证参加人签名或盖章。 听证主持人应当在听证后将听证笔录当场交当事人和案件调查人审核，并签名或盖章。当事人拒绝签名的，由听证主持人在听证笔录上说明情况。"},{"i":41,"n":"第四十一条","txt":"听证结束后，听证主持人应当依据听证情况，提出书面意见。"},{"i":42,"n":"第四十二条","txt":"卫生行政机关应当根据听证情况进行复核，违法事实清楚的，依法作出行政处罚决定；违法事实与原来认定有出入的，可以进行调查核实，在查清事实后，作出行政处罚决定。"},{"i":43,"n":"第四十三条","txt":"对于违法事实清楚、证据确凿并有下列情形之一的，卫生行政机关可当场作出卫生行政处罚决定： （一）予以警告的行政处罚； （二）对公民处以五十元以下罚款的行政处罚； （三）对法人或者其他组织处以一千元以下罚款的行政处罚。"},{"i":44,"n":"第四十四条","txt":"卫生行政执法人员当场作出行政处罚决定的，应当向当事人出示证件，填写预定格式、编有号码并加盖卫生行政机关印章的当场行政处罚决定书。 前款规定的行政处罚决定书应当载明当事人的违法行为、行政处罚依据（适用的法律、法规、规章名称及条、款、项、目）、具体处罚决定、时间、地点、卫生行政机关名称，并由执法人员签名或盖章。"},{"i":45,"n":"第四十五条","txt":"卫生行政机关适用简易程序作出卫生行政处罚决定的，应在处罚决定书中书面责令当事人改正或限期改正违法行为。"},{"i":46,"n":"第四十六条","txt":"卫生行政执法人员当场作出的行政处罚决定，应当在七日内报所属卫生行政机关备案。"},{"i":47,"n":"第四十七条","txt":"卫生行政处罚决定书应当在宣告后当场交付当事人并取得送达回执。当事人不在场的，卫生行政机关应当在七日内依照本节规定，将卫生行政处罚决定书送达当事人。 卫生行政处罚决定书由承办人送达被处罚的单位或个人签收，受送达人在送达回执上记明收到日期、签名或盖章。受送达人在送达回执上的签收日期为送达日期。 送达行政处罚决定书应直接送交受送达人。受送达人是公民的，本人不在时，交同住成年家属签收；受送达人是法人或者其他组织的，应由法定代表人、其他组织的主要负责人或者该法人、其他组织负责收件人员签收。"},{"i":48,"n":"第四十八条","txt":"受送达人或者其同住成年家属拒收行政处罚决定书的，送达人应当邀请有关基层组织或者所在单位人员到场并说明情况，在行政处罚决定书送达回执上注明拒收事由和日期，由送达人、见证人签名（盖章），将行政处罚决定书留在被处罚单位或者个人处，即视为送达。"},{"i":49,"n":"第四十九条","txt":"直接送达有困难的，可以委托就近的卫生行政机关代送或者用挂号邮寄送达，回执注明的收件日期即为送达日期。"},{"i":50,"n":"第五十条","txt":"受送达人下落不明，或者依据本程序的其他方式无法送达的，以公告方式送达。 自发出公告之日起，经过六十日，即视为送达。"},{"i":51,"n":"第五十一条","txt":"卫生行政处罚决定作出后，当事人应当在处罚决定的期限内予以履行。"},{"i":52,"n":"第五十二条","txt":"当事人对卫生行政处罚决定不服申请行政复议或者提起行政诉讼的，行政处罚不停止执行，但行政复议或行政诉讼期间裁定停止执行的除外。"},{"i":53,"n":"第五十三条","txt":"作出罚款决定的卫生行政机关应当与收缴罚款的机关分离，除按规定当场收缴的罚款外，作出行政处罚决定的卫生行政机关及卫生执法人员不得自行收缴罚款。"},{"i":54,"n":"第五十四条","txt":"依据本程序第四十三条当场作出卫生行政处罚决定，有下列情形之一的，卫生执法人员可以当场收缴罚款： （一）依法给予二十元以下罚款的； （二）不当场收缴事后难以执行的； 卫生行政机关及其卫生执法人员当场收缴罚款的，必须向当事人出具省、自治区、直辖市财政部门统一制发的罚款收据。"},{"i":55,"n":"第五十五条","txt":"在边远、水上、交通不便地区，卫生行政机关及卫生执法人员依照本程序规定作出处罚决定后，当事人向指定的银行缴纳罚款确有困难的，经当事人提出，卫生行政机关及其卫生执法人员可以当场收缴罚款。"},{"i":56,"n":"第五十六条","txt":"当事人在法定期限内不申请行政复议或者不提起行政诉讼又不履行的，卫生行政机关可以采取下列措施： （一）到期不缴纳罚款的每日按罚款数额的百分之三加处罚款； （二）申请人民法院强制执行。"},{"i":57,"n":"第五十七条","txt":"卫生行政处罚决定履行或者执行后，承办人应当制作结案报告。并将有关案件材料进行整理装订，加盖案件承办人印章，归档保存。"},{"i":58,"n":"第五十八条","txt":"卫生行政机关应当将适用听证程序的行政处罚案件在结案后一个月内报上一级卫生行政机关法制机构备案。 卫生部卫生检疫局适用听证程序的行政处罚案件，应当报卫生部法制机构备案。"},{"i":59,"n":"第五十九条","txt":"本程序所称卫生执法人员是指依照卫生法律、法规、规章聘任的卫生监督员。"},{"i":60,"n":"第六十条","txt":"卫生行政机关及其卫生执法人员违反本程序实施行政处罚，将依照《行政处罚法》的有关规定，追究法律责任。"},{"i":61,"n":"第六十一条","txt":"卫生行政处罚文书规范由卫生部另行制定。"},{"i":62,"n":"第六十二条","txt":"本程序由卫生部负责解释。"},{"i":63,"n":"第六十三条","txt":"本程序自发布之日起实行。以前发布的有关规定与本程序不符的，以本程序为准。"}],"weishengxingzhengzhifawenshuguifan":[{"i":1,"n":"第一条","txt":"为规范卫生行政执法行为，保障公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》和有关法律法规，制定本规范。"},{"i":2,"n":"第二条","txt":"本规范规定的文书适用于监督检查、监督抽检、行政强制、行政处罚等卫生行政执法活动。"},{"i":3,"n":"第三条","txt":"规范确定的各类文书应当按照规定的要求使用。 除本规范规定的文书样式外，省级卫生行政机关可以根据工作需要增加相应文书，并报国家卫生计生委备案。"},{"i":4,"n":"第四条","txt":"制作的文书应当完整、准确、规范，符合相应的要求。 文书中卫生行政机关的名称应当填写机关全称。 文书本身设定文号的，应当在文书标注的“文号”位置编写相应的文号，编号方法为：“地区简称＋卫＋执法类别＋执法性质＋〔年份〕＋序号”。文书本身设定编号的，应当在文书标注的“编号：”后印制编号，编号方法为：“年份＋序号”。"},{"i":5,"n":"第五条","txt":"现场使用的文书应当按照规定的格式印制后填写。两联以上的文书应当使用无碳复写纸印制。 应当用黑色或者蓝黑色的水笔或者签字笔填写，保证字迹清楚、文字规范、文面清洁。 因书写错误需要对文书进行修改的，应当用杠线划去修改处，在其上方或者接下处写上正确内容。对外使用的文书作出修改的，应当在改动处加盖校对章，或者由对方当事人签名或者盖章。 文书也可以按照规范的格式打印。执法过程中需要利用手持移动执法设备现场打印文书的，在文书格式和内容不变的情况下，文书规格大小可以适当调整。"},{"i":6,"n":"第六条","txt":"预先设定的文书栏目，应当逐项填写。摘要填写的，应当简明、完整、准确。签名和注明日期必须清楚无误。"},{"i":7,"n":"第七条","txt":"调查询问所作的记录应当具体详细，涉及案件关键事实和重要线索的，应当尽量记录原话。不得使用推测性词句，以免发生词句歧义。 对方位、状态及程度的描述记录，应当依次有序、准确清楚。"},{"i":8,"n":"第八条","txt":"当场制作的现场笔录、询问笔录、陈述和申辩笔录、听证笔录等文书，应当在记录完成后注明“以下空白”，当场交由有关当事人审阅或者向当事人宣读，并由当事人签字确认。当事人认为记录有遗漏或者有差错的，应当提出补充和修改，在改动处签字或者用指纹、印鉴覆盖。 当事人认为笔录所记录的内容真实无误的，应当在笔录上注明“以上笔录属实”并签名。当事人拒不签名的，应当注明情况。采取行政强制措施时，当事人不到场的，应当邀请见证人到场在现场笔录上签名或者盖章。"},{"i":9,"n":"第九条","txt":"各类文书中有关共性栏目的填写方法： 文书本身设有“当事人”项目的，按照以下要求填写：是法人或者其他组织的，应当填写单位的全称、地址、联系电话，法定代表人（负责人）的姓名、性别、民族、职务等内容；是个人的，应当填写姓名、性别、身份证号、民族、住址、联系电话等内容。“案件来源”按照《卫生行政处罚程序》的规定要求填写。 文书首页不够记录时，可以续页记录，但首页及续页均应当有当事人签名并注明日期。 案由统一写法为当事人名称（姓名）＋具体违法行为＋案。如有多个违法行为，以主要的违法行为作为案由。文书本身设有“当事人”项目的，在填写案由时可以省略有关当事人的内容。"},{"i":10,"n":"第十条","txt":"对外使用的文书本身设定签收栏的，在直接送达的情况下，应当由当事人直接签收。没有设定的，一般应当使用送达回执。"},{"i":11,"n":"第十一条","txt":"产品样品采样记录，是采集用于鉴定检验的健康相关产品及其他产品的书面记录。 采样记录应当写明被采样人、采样地址、采样方法、采样时间、采样目的等内容。 样品基本情况应当写明样品名称、样品规格、样品数量、样品包装状况或者储存条件、样品的生产日期及批号、样品标注的生产或者进口代理单位、采集样品的具体地点。"},{"i":12,"n":"第十二条","txt":"非产品样品采样记录，是从有关场所采集鉴定检验用样品的书面记录。 非产品样品采样记录应当写明被采样人、采样地点、采样方法、采样时间、采样目的、采样设备或者仪器名称、采集样品名称、编号及份数。 此外，还应当对被采集样品的物品或者场所的状况进行客观的描述。"},{"i":13,"n":"第十三条","txt":"产品样品确认告知书，是实施卫生监督抽检的卫生行政机关为确认产品的真实生产或者进口代理单位，向标签标注的生产或者进口代理单位发出的文书。 告知书应当写明样品的基本情况，采样日期、被采样单位或者地址、样品标识的生产或者进口代理单位及地址、生产日期或者批号、标识、规格、样品名称等内容。还应当告知确认的方式、时间、地点、联系人、联系电话、联系地址和邮政编码等，并告知逾期未回复确认的，视为对样品真实性无异议。"},{"i":14,"n":"第十四条","txt":"检验结果告知书，是卫生行政机关将抽检不合格样品的检验结果告知相应当事人的文书。 告知书应当写明被检验的产品或者其他物品的名称，检验结果不符合国家有关卫生标准规定的情况，并告知当事人依照规定是否有申请复核的权利及提出复核申请的期限等内容。"},{"i":15,"n":"第十五条","txt":"卫生监督意见书，是卫生行政机关制作的对被监督单位或者个人具有指导性或者指令性作用的文书。 对存在违法事实，依法需要责令改正的，应当写明法律依据、改正期限及责令改正意见等内容。"},{"i":16,"n":"第十六条","txt":"卫生行政执法事项审批表，是在作出证据先行登记保存、行政强制、行政处罚等行政决定前，由卫生行政机关负责人对拟作出的行政决定意见进行审查，并签署审批意见的文书。也适用于因情况紧急需要当场实施行政强制措施，事后补办批准手续的情形。 审批表应当写明当事人、案由、申请审批事项、承办人处理意见、审核意见及部门负责人审批意见等。 申请行政处罚审批时，申请审批事项中应当写明主要违法事实、证据、处罚理由及依据。申请证据先行登记保存、行政强制审批时，申请审批事项中应当写明原因及依据。"},{"i":17,"n":"第十七条","txt":"卫生行政控制决定书，是卫生行政机关发现当事人生产经营的产品或者场所已经或者可能对人体健康产生危害，需要对物品或者场所采取控制措施时发出的文书。 决定书应当写明当事人全称、控制的原因、控制的法律依据和作出处理决定的期限，对控制的物品或者场所应当写明物品或者场所的名称、控制地点、控制方式等内容。"},{"i":18,"n":"第十八条","txt":"解除卫生行政控制决定书，是卫生行政机关确认被控制的物品或者场所不能或者不可能对人体健康构成危害时，决定对被控制的物品或者场所解除控制时发出的文书。 决定书应当写明当事人全称及控制文书作出的时间及文号。"},{"i":19,"n":"第十九条","txt":"查封、扣押决定书，是卫生行政机关为制止违法行为、防止证据毁损、避免危害发生、控制危险扩大，依法对涉案的场所、设施或者财物采取查封、扣押措施时发出的文书。 决定书中应当写明当事人的姓名或者名称、地址，查封、扣押的理由、依据和期限，查封、扣押场所、设施或者财物的名称、数量等，并告知当事人申请行政复议或者提起行政诉讼的途径和期限。 对物品需要进行检测、检验、检疫或者技术鉴定的，应当告知当事人所需的时间，同时告知查封、扣押的期间不包括检测、检验、检疫或者技术鉴定的期间。"},{"i":20,"n":"第二十条","txt":"查封、扣押处理决定书，是卫生行政机关在规定的期限内对被采取查封、扣押行政强制措施的场所、设施或者财物作出处理决定时发出的文书。 处理决定书应当写明当事人的姓名或者名称，查封扣押决定书作出的时间、文号及具体处理意见。"},{"i":21,"n":"第二十一条","txt":"查封、扣押延期通知书，是因案情复杂，需要延长查封、扣押期限时发出的文书。 延期通知书应当写明当事人的姓名或者名称，查封扣押的期限，并说明理由。"},{"i":22,"n":"第二十二条","txt":"物品清单，是作出查封、扣押、没收物品等行政决定时，附于查封、扣押决定书，行政处罚决定书等文书后，用于登记相关物品所使用的文书。 物品清单应当注明被附文书的名称及文号，并写明物品名称、数量、生产或进口代理单位、生产日期及批号等内容，由当事人、案件承办人签名。"},{"i":23,"n":"第二十三条","txt":"公告，是指卫生行政机关为制止违法行为或者防止危害后果扩大，对当事人的违法行为依法采取执法行为并需要公众知晓或者配合时使用的文书。 公告应当写明违法当事人的姓名或者名称、地点、违法事实、违反的法律条款、处理依据及时间。公告的纸张规格大小可以根据实际需要确定。"},{"i":24,"n":"第二十四条","txt":"封条，是为调查取证、保存证据或者防止危害进一步扩大等，对特定生产经营场所、物品等采取临时停止使用，以及禁止销售、转移、损毁、隐匿物品等措施时使用的文书。 封条上应当注明日期和期限，并加盖公章。封条的规格可以根据实际需要确定。"},{"i":25,"n":"第二十五条","txt":"案件受理记录，是对检查发现、群众检举或者控告，上级卫生行政机关交办、下级卫生行政机关报请、有关部门移送来的案件，按照规定的权限和程序办理案件受理手续，所作的文字记录。 案发单位或者个人的信息应当根据所获得的信息填写。 案情摘要应当写明主要违法事实，包括案发时间、案发地点、重要证据及造成的危害和影响等内容。 负责人意见，是负责人对案件的处理意见。"},{"i":26,"n":"第二十六条","txt":"立案报告，是对受理的案件进行初步核实后，确认有违法事实，属于本机关管辖，并需给予行政处罚的，为了对案件展开调查，向主管卫生行政机关负责人或主管科（处、室）负责人提出的书面报告。 案情摘要应当按照性质和程度，由大到小、从重到轻加以排列，逐个罗列事实并加以简要说明。同时要指明当事人涉嫌违反的具体法律条款。 负责人审批意见，是负责人对查处案件的批示，如是否批准立案，对批准立案的应当确定承办人员。"},{"i":27,"n":"第二十七条","txt":"案件移送书，是将不属于本单位或者本部门管辖的案件，移送有关单位或者部门处理的文书。 案件移送书应当写明移送案件的受理时间、案由、移送原因、移送的法律依据。 卫生行政机关应当将案件材料一并移送，并做好交接记录。"},{"i":28,"n":"第二十八条","txt":"现场笔录，是在案件调查、现场监督检查或者采取行政强制措施过程中，对与案件有关的现场环境、场所、设施、物品、人员、生产经营过程等进行现场检查时作的记录。 检查时间指在现场检查的具体时间，起止时间应当写明：年、月、日、时、分至几时几分。 检查地点应当写明现场检查的具体方位和具体地点。 检查内容记录要将现场监督检查涉及案件事实的有关情况准确、客观地记录下来。"},{"i":29,"n":"第二十九条","txt":"询问笔录，是为查明案件事实，收集证据，而向案件当事人、证人或者其他有关人员调查了解有关情况时作的记录。 被询问人的基本情况应当记录姓名、性别、年龄、住址（联系地址）、身份证号等。 询问时间应当写明起止时间。 询问地点应当写明具体地点。 询问内容应当记录被询问人提供的与案件有关的全部情况，包括案件发生的时间、地点、事实经过、因果关系、后果等。"},{"i":30,"n":"第三十条","txt":"证据先行登记保存决定书，是要求当事人对需要保全的证据在登记造册后进行保管的文书。 决定书应当写明保存方式、保存期限、保存地点以及保存证据的有关内容。"},{"i":31,"n":"第三十一条","txt":"证据先行登记保存处理决定书，是卫生行政机关在规定的期限内对被保存的证据作出处理决定的文书。 处理决定书应当写明当事人全称，保存决定书作出的时间、文号及具体处理决定。"},{"i":32,"n":"第三十二条","txt":"案件调查终结报告，是案件调查终结后，承办人就案情事实、对所调查问题性质的认识、对当事人责任的分析、对当事人的处理意见等，以书面形式向领导或者有关部门所做的正式报告。 承办机构指负主要责任办理该案件的机构，如科（处、室）等。承办人，指负责办理该案件的卫生监督员。 案情及违法事实应当简明扼要，写明案件的经过和结果，违反的法律条款等。 相关证据应当列明已经查证属实的，与案件有关的所有证据。 争议要点，既应当写明当事人与承办人之间对案情事实的不同观点，也应当表明承办人之间对案件的不同意见。如无争议则写“无”。 处理建议，经过调查，据以立案的违法事实并不存在，应当写明建议终结调查并结案等内容。需要给予行政处罚的，应当写明拟实施行政处罚的种类、幅度及法律依据等。 负责人意见，应当写明是否同意调查终结的意见，对需要合议的案件应当提出进行合议的具体意见。"},{"i":33,"n":"第三十三条","txt":"合议记录，是对拟适用听证程序的行政处罚或其他重大行政处罚案件在调查终结后，组织有关人员对案件进行综合分析、审议时记录的文字材料。 合议记录应当写明案由、合议主持人、参加合议人员、合议时间、合议地点等内容。 合议记录应当包括：违法事实、相关证据、处罚依据、合议建议。对不同的合议意见，应当如实记录。 合议结束后，所有参加合议人员都应当在每页合议记录上签名并注明日期。"},{"i":34,"n":"第三十四条","txt":"行政处罚事先告知书，是在作出行政处罚决定前，告知当事人将要作出的行政处罚决定的事实、理由、依据以及当事人依法应当享有的权利的文书。 事先告知书应当写明当事人的违法行为、违反的法律条款、将要作出的行政处罚决定的法律依据、行政处罚的种类和幅度，告知当事人享有的陈述和申辩的权利，适用听证的还应当告知当事人享有要求举行听证的权利及法定期限，并注明联系人、联系电话、地址等。 在当事人表明放弃陈述和申辩权或者放弃听证权时，应当请当事人在“当事人意见记录”处写明“放弃陈述和申辩权”或者“放弃听证权”等内容。"},{"i":35,"n":"第三十五条","txt":"陈述和申辩笔录，是对当事人及陈述申辩人陈述事实、理由和申辩内容的记录。 当事人委托陈述申辩人的，应当写明受委托的陈述申辩人的姓名、性别、职务、现在工作单位等。受委托的陈述申辩人应当出具当事人的委托书。 应当写明陈述和申辩的地点和时间。 应当尽可能记录陈述申辩人原话，不能记录原话的，记录应当真实反映陈述申辩人原意。"},{"i":36,"n":"第三十六条","txt":"陈述和申辩复核意见书，是对当事人提出的事实、理由和证据进行复核的记录。 复核意见书应当写明陈述申辩人的姓名、陈述和申辩的理由和证据，以及复核人和承办机构的意见。当事人收到催告书后所进行的陈述和申辩的复核，应当在复核意见书中写明卫生行政机关的意见。"},{"i":37,"n":"第三十七条","txt":"行政处罚听证通知书，是经有权要求举行听证的当事人提出，卫生行政机关决定举行听证时向当事人发出的书面通知。 通知书应当写明举行听证的时间、地点、听证方式、听证组成人员、申请回避的权利、听证机关的联系方式等。"},{"i":38,"n":"第三十八条","txt":"听证笔录，是对听证过程和内容的记录。 当事人委托代理人的，应当写明代理人的姓名、性别、职务、现在工作单位等。委托代理人应当出具当事人的委托书。 笔录应当写明案件承办人、听证员、听证主持人、书记员、听证方式、听证地点、听证时间、案由等内容。 记录应当写明案件承办人提出的事实、证据和行政处罚建议，当事人陈述、申辩等内容。 所有参加听证的人员都应当在每页笔录上签名并注明日期。"},{"i":39,"n":"第三十九条","txt":"听证意见书，是听证结束后，就听证情况及听证人员对该案件的意见，以书面形式向负责人或者有关部门所做的正式报告。 对当事人和案件承办人的陈述应当抓住要点，归纳概括。听证人员意见是评议后对案件认定的违法事实是否清楚，证据是否确凿和适用法律是否正确、处罚裁量是否合理等提出的意见。 负责人意见是负责人对听证人员意见的具体批示。这里的负责人，可以是卫生行政机关的负责人，也可以是经授权的有关主管科（处、室）负责人。"},{"i":40,"n":"第四十条","txt":"行政处罚决定书，是对事实清楚、证据确凿的卫生违法案件，根据情节轻重依法作出行政处罚决定的文书。 被处罚人是单位的，填写单位全称，以及法定代表人（负责人）、卫生许可证件或者营业执照号码等内容；是个人的，填写姓名，并注明身份证号。同时，还应当写明被处罚人的地（住）址。 决定书应当写明查实的违法事实、相关证据、违反的法律条款、行政处罚依据、理由以及行政处罚决定的内容。决定书还应当将有关告知事项交代清楚，如罚款缴往单位和缴纳期限，复议和诉讼的途径、方法和期限等。"},{"i":41,"n":"第四十一条","txt":"当场行政处罚决定书，是对案情简单、违法事实清楚、证据确凿的违法案件依法当场作出处罚决定的文书。 当场行政处罚决定书的填写与一般程序行政处罚决定书的要求基本相同。"},{"i":42,"n":"第四十二条","txt":"送达回执，是将行政执法文书送交有关当事人后证明受送达人已收到的凭证。 送达回执用于直接送达、邮寄送达、留置送达等方式。 送达回执应当写明受送达人、送达机关、送达文件名称及文号、送达地点等内容。 在直接送达时当事人拒绝签收而采用留置送达方式的，应当在备注栏说明有关情况，并记录留置送达的过程。"},{"i":43,"n":"第四十三条","txt":"催告书，是卫生行政机关作出申请强制执行决定前，事先催告当事人履行法定义务时发出的文书。 催告书应当写明履行法定义务的期限、方式，涉及金钱给付的，应当注明明确的金额和给付方式，并告知当事人依法享有陈述和申辩的权利。"},{"i":44,"n":"第四十四条","txt":"强制执行申请书，是当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行行政决定的，经依法催告仍未履行，卫生行政机关申请人民法院强制执行时提交给人民法院的书面申请。 申请书中的“（）”内填写行政决定的名称、文号或者编号。申请书应当写明当事人基本情况及申请执行的内容，由卫生行政机关负责人签名，加盖卫生行政机关印章并注明日期。"},{"i":45,"n":"第四十五条","txt":"结案报告，是对立案调查的案件，在行政处罚决定履行或者执行后，或者不作行政处罚的案件，报请负责人批准结案的文书。结案报告应当填写当事人、立案日期、案由等，给予行政处罚的应当写明行政处罚决定书文号、执行方式、执行日期、执行结果（如未执行或者未完全执行的需说明原因）等内容，不予行政处罚的应当写明理由。"},{"i":46,"n":"第四十六条","txt":"续页，是接在各类卫生行政执法文书后面完成相关记录内容时所使用的文书。 使用续页应当写明所接执法文书的名称，有相关人员签字并注明页码、日期。"},{"i":47,"n":"第四十七条","txt":"卫生行政执法建议书，是卫生行政机关为促进依法履职、规范执法，在日常监督检查和稽查过程中，结合执法办案，建议下级卫生行政机关及其卫生监督机构完善制度和工作机制，加强内部管理，改进工作、消除隐患，促进执法监管水平提高时发出的文书。 卫生行政执法建议书应当写明提出建议的起因，在日常监督检查和案件调查处理过程中发现的需要重视和解决的问题，对问题产生原因的分析，并依据法律法规及有关规定提出的具体建议、意见，以及其他需要说明的事项。"},{"i":48,"n":"第四十八条","txt":"各级卫生行政机关应当加强对卫生行政执法文书的管理，制定相应的管理制度，落实专人负责管理。 为提高工作效率，现场使用的执法文书可以提前加盖印章，并做好领用登记管理。"},{"i":49,"n":"第四十九条","txt":"卫生行政执法案卷材料应当按照一案一卷形式进行装订，每卷顺序按照有关材料形成的时间先后顺序排列。"},{"i":50,"n":"第五十条","txt":"本规范由国家卫生计生委负责解释。"},{"i":51,"n":"第五十一条","txt":"本规范自2012年12月1日起施行。2002年12月18日卫生部发布的《卫生行政执法文书规范》同时废止。实施卫生行政许可，按照《卫生行政许可管理办法》及卫生行政许可文书样本执行。"}],"weishengxingzhengxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范卫生计生行政部门实施卫生行政许可，根据《中华人民共和国行政许可法》(以下简称《行政许可法》)和有关卫生法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"卫生行政许可是卫生计生行政部门根据公民、法人或者其他组织的申请，按照卫生法律、法规、规章和卫生标准、规范进行审查，准予其从事与卫生管理有关的特定活动的行为。"},{"i":3,"n":"第三条","txt":"实施卫生行政许可，应当遵循公开、公平、公正、便民原则，提高办事效率，提供优质服务。"},{"i":4,"n":"第四条","txt":"各级卫生计生行政部门实施的卫生行政许可应当有下列法定依据： （一）法律、行政法规； （二）国务院决定； （三）地方性法规； （四）省、自治区、直辖市人民政府规章。 各级卫生计生行政部门不得自行设定卫生行政许可项目，不得实施没有法定依据的卫生行政许可。"},{"i":5,"n":"第五条","txt":"卫生计生行政部门实施卫生行政许可必须严格遵守法律、法规、规章规定的权限和程序。 法律、法规、规章规定由上级卫生行政机关实施的卫生行政许可，下级卫生行政机关不得实施；法律、法规、规章规定由下级卫生行政机关实施的卫生行政许可，上级卫生行政机关不得实施，但应当对下级卫生行政机关实施卫生行政许可的行为加强监督。 法律、法规、规章未明确规定实施卫生行政许可的卫生计生行政部门级别的，或者授权省级卫生计生行政部门对此作出规定的，省级卫生计生行政部门应当作出具体规定。"},{"i":6,"n":"第六条","txt":"卫生计生行政部门实施的卫生行政许可需要内设的多个机构办理的，应当确定一个机构统一受理卫生行政许可申请和发放行政许可决定。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织对卫生计生行政部门实施卫生行政许可享有陈述权、申辩权和依法要求听证的权利；有权依法申请行政复议或者提起行政诉讼；其合法权益因卫生计生行政部门违法实施卫生行政许可受到损害的，有权依法要求赔偿。"},{"i":8,"n":"第八条","txt":"任何单位和个人对违法实施卫生行政许可的行为有权进行举报，卫生计生行政部门应当及时核实、处理。"},{"i":9,"n":"第九条","txt":"公民、法人或者其他组织申请卫生行政许可，应当按照法律、法规、规章规定的程序和要求向卫生计生行政部门提出申请。申请书格式文本由卫生计生行政部门提供。 申请人可以委托代理人提出卫生行政许可申请，代理人办理卫生行政许可申请时应当提供委托代理证明。"},{"i":10,"n":"第十条","txt":"卫生计生行政部门应当公示下列与办理卫生行政许可事项相关的内容： （一）卫生行政许可事项、依据、条件、程序、期限、数量； （二）需要提交的全部材料目录； （三）申请书示范文本； （四）办理卫生行政许可的操作流程、通信地址、联系电话、监督电话。 有条件的卫生计生行政部门应当在相关网站上公布前款所列事项，方便申请人提出卫生行政许可，提高办事效率。 卫生计生行政部门应当根据申请人的要求，对公示内容予以说明、解释。"},{"i":11,"n":"第十一条","txt":"申请人申请卫生行政许可，应当如实向卫生计生行政部门提交有关材料，并对其申请材料的真实性负责，承担相应的法律责任。卫生计生行政部门不得要求申请人提交与其申请的卫生行政许可事项无关的技术资料和其他材料。"},{"i":12,"n":"第十二条","txt":"卫生计生行政部门接收卫生行政许可申请时，应当对申请事项是否需要许可、申请材料是否齐全等进行核对，并根据下列情况分别作出处理： （一）申请事项依法不需要取得卫生行政许可的，应当即时告知申请人不受理； （二）申请事项依法不属于卫生计生行政部门职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误，应当允许申请人当场更正，但申请材料中涉及技术性的实质内容除外。申请人应当对更正内容予以书面确认； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5日内出具申请材料补正通知书，一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理；补正的申请材料仍然不符合有关要求的，卫生计生行政部门可以要求继续补正； （五）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，卫生计生行政部门应当受理其卫生行政许"},{"i":13,"n":"第十三条","txt":"卫生计生行政部门受理或者不予受理卫生行政许可申请的，应当出具加盖卫生计生行政部门专用印章和注明日期的文书。"},{"i":14,"n":"第十四条","txt":"卫生行政许可申请受理后至卫生行政许可决定作出前，申请人书面要求撤回卫生行政许可申请的，可以撤回；撤回卫生行政许可申请的，卫生计生行政部门终止办理，并通知申请人。"},{"i":15,"n":"第十五条","txt":"卫生计生行政部门受理申请后，应当及时对申请人提交的申请材料进行审查。 卫生计生行政部门根据法律、法规和规章的规定，确定审查申请材料的方式。"},{"i":16,"n":"第十六条","txt":"卫生计生行政部门对申请材料审查后，应当在受理申请之日起20日内作出卫生行政许可决定； 20日内不能作出卫生行政许可决定的，经本级卫生计生行政部门负责人批准，可以延长10日，并应当将延长期限的理由书面告知申请人。 法律、法规对卫生行政许可期限另有规定的，依照其规定。"},{"i":17,"n":"第十七条","txt":"卫生计生行政部门依法需要对申请人进行现场审查的，应当及时指派两名以上工作人员进行现场审查，并根据现场审查结论在规定期限内作出卫生行政许可决定。"},{"i":18,"n":"第十八条","txt":"卫生计生行政部门依法需要对申请行政许可事项进行检验、检测、检疫的，应当自受理申请之日起5日内指派两名以上工作人员按照技术标准、技术规范进行检验、检测、检疫，并书面告知检验、检测、检疫所需期限。需要延长检验、检测、检疫期限的，应当另行书面告知申请人。检验、检测、检疫所需时间不计算在卫生行政许可期限内。"},{"i":19,"n":"第十九条","txt":"卫生计生行政部门依法需要根据鉴定、专家评审结论作出卫生行政许可决定的，应当书面告知申请人组织专家评审的所需期限。卫生计生行政部门根据专家评审结论作出是否批准的卫生行政许可决定。需要延长专家评审期限的，应当另行书面告知申请人。鉴定、专家评审所需时间不计算在卫生行政许可期限内。"},{"i":20,"n":"第二十条","txt":"卫生计生行政部门依法需要根据考试、考核结果作出卫生行政许可决定的，申请人在考试、考核合格成绩确定后，根据其考试、考核结果向卫生计生行政部门提出申请，卫生计生行政部门应当在规定期限内作出卫生行政许可决定。 卫生计生行政部门根据考试成绩和其他法定条件作出卫生行政许可决定的，应当事先公布资格考试的报名条件、报考办法、考试科目以及考试大纲。但是，不得组织强制性的资格考试的考前培训，不得指定教材或者其他助考材料。"},{"i":21,"n":"第二十一条","txt":"卫生计生行政部门依法需要根据检验、检测、检疫结果作出卫生行政许可决定的，检验、检测、检疫工作由依法认定的具有法定资格的技术服务机构承担。 申请人依法可自主选择具备法定资格的检验、检测、检疫机构，卫生计生行政部门不得为申请人指定检验、检测、检疫机构。"},{"i":22,"n":"第二十二条","txt":"依法应当逐级审批的卫生行政许可，下级卫生计生行政部门应当在法定期限内按规定程序和要求出具初审意见，并将初步审查意见和全部申报材料报送上级卫生计生行政部门审批。法律、法规另有规定的，依照其规定。 符合法定要求的，上级卫生计生行政部门不得要求申请人重复提供申请材料。"},{"i":23,"n":"第二十三条","txt":"卫生计生行政部门作出不予卫生行政许可的书面决定的，应当说明理由，告知申请人享有依法申请行政复议或者提起行政诉讼的权利，并加盖卫生计生行政部门印章。"},{"i":24,"n":"第二十四条","txt":"申请人的申请符合法定条件、标准的，卫生计生行政部门应当依法作出准予卫生行政许可的书面决定。依法需要颁发卫生行政许可证件的，应当向申请人颁发加盖卫生计生行政部门印章的卫生行政许可证件。 卫生行政许可证件应当按照规定载明证件名称、发证机关名称、持证人名称、行政许可事项名称、有效期、编号等内容，并加盖卫生计生行政部门印章，标明发证日期。"},{"i":25,"n":"第二十五条","txt":"卫生计生行政部门作出的卫生行政许可决定，除涉及国家秘密、商业秘密或者个人隐私的外，应当予以公开，公众有权查阅。"},{"i":26,"n":"第二十六条","txt":"卫生计生行政部门应当建立健全卫生行政许可档案管理制度，妥善保存有关申报材料和技术评价资料。"},{"i":27,"n":"第二十七条","txt":"申请人依法取得的卫生行政许可，其适用范围没有地域限制的，在全国范围内有效，各级卫生计生行政部门不得采取备案、登记、注册等方式重复或者变相重复实施卫生行政许可。"},{"i":28,"n":"第二十八条","txt":"同一公民、法人或者其他组织在同一地点的生产经营场所需要多项卫生行政许可，属于同一卫生计生行政部门实施行政许可的，卫生计生行政部门可以只发放一个卫生行政许可证件，其多个许可项目应当分别予以注明。"},{"i":29,"n":"第二十九条","txt":"法律、法规、规章规定实施卫生行政许可应当听证的事项，或者卫生计生行政部门认为需要听证的涉及重大公共利益的卫生行政许可事项，卫生计生行政部门应当在作出卫生行政许可决定前向社会公告，并举行听证。听证公告应当明确听证事项、听证举行的时间、地点、参加人员要求及提出申请的时间和方式等。"},{"i":30,"n":"第三十条","txt":"卫生行政许可直接涉及申请人与他人之间重大利益关系，卫生计生行政部门应当在作出卫生行政许可决定前发出卫生行政许可听证告知书，告知申请人、利害关系人有要求听证的权利。"},{"i":31,"n":"第三十一条","txt":"申请人、利害关系人要求听证的，应当自收到卫生计生行政部门卫生行政许可听证告知书后五日内提交申请听证的书面材料。逾期不提交的，视为放弃听证的权利。"},{"i":32,"n":"第三十二条","txt":"卫生计生行政部门应当在接到申请人、利害关系人申请听证的书面材料二十日内组织听证，并在举行听证的七日前，发出卫生行政许可听证通知书，将听证的事项、时间、地点通知申请人、利害关系人。"},{"i":33,"n":"第三十三条","txt":"申请人、利害关系人在举行听证前，撤回听证申请的，应当准许，并予记录。"},{"i":34,"n":"第三十四条","txt":"申请人、利害关系人可以亲自参加听证，也可以委托代理人参加听证，代理人应当提供委托代理证明。"},{"i":35,"n":"第三十五条","txt":"根据规定需要听证的，由卫生计生行政部门具体实施行政许可的机构负责组织。听证由卫生计生行政部门的法制机构主持。 申请人、利害关系人不承担卫生计生行政部门组织听证的费用。"},{"i":36,"n":"第三十六条","txt":"申请人、利害关系人认为听证主持人与卫生行政许可有直接利害关系的，有权申请回避。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，可以延期举行听证： （一）申请人、利害关系人有正当理由未到场的； （二）申请人、利害关系人提出回避申请理由成立，需要重新确定主持人的； （三）其他需要延期的情形。"},{"i":38,"n":"第三十八条","txt":"举行听证时，卫生行政许可审查人提出许可审查意见，申请人、利害关系人进行陈述、申辩和质证。"},{"i":39,"n":"第三十九条","txt":"听证应当制作笔录，听证笔录应当载明下列事项： （一）卫生行政许可事项； （二）听证参加人姓名、年龄、身份； （三）听证主持人、听证员、书记员姓名； （四）举行听证的时间、地点、方式； （五）卫生行政许可审查人提出的许可审查意见； （六）申请人、利害关系人陈述、申辩和质证的内容。 听证主持人应当在听证后将听证笔录当场交申请人、利害关系人审核，并签名或盖章。申请人、利害关系人拒绝签名的，由听证主持人在听证笔录上说明情况。"},{"i":40,"n":"第四十条","txt":"听证结束后，听证主持人应当依据听证情况，提出书面意见。"},{"i":41,"n":"第四十一条","txt":"听证所需时间不计算在卫生行政许可期限内。"},{"i":42,"n":"第四十二条","txt":"被许可人在卫生行政许可有效期满前要求变更卫生行政许可事项的，应当向作出卫生行政许可决定的卫生计生行政部门提出申请，并按照要求提供有关材料。 卫生计生行政部门对被许可人提出的变更申请，应当按照有关规定进行审查。对符合法定条件和要求的，卫生计生行政部门应当依法予以变更，并换发行政许可证件或者在原许可证件上予以注明；对不符合法定条件和要求的，卫生计生行政部门应当作出不予变更行政许可的书面决定，并说明理由。"},{"i":43,"n":"第四十三条","txt":"按照法律、法规、规章规定不属于可以变更情形的，应当按照规定重新申请卫生行政许可。"},{"i":44,"n":"第四十四条","txt":"被许可人依法需要延续卫生行政许可有效期的，应当在该卫生行政许可有效期届满30日前向作出卫生行政许可决定的卫生计生行政部门提出申请，并按照要求提供有关材料。但法律、法规、规章另有规定的，依照其规定。"},{"i":45,"n":"第四十五条","txt":"卫生计生行政部门接到延续申请后，应当按照本办法的有关规定作出受理或者不予受理的决定。受理延续申请的，应当在该卫生行政许可有效期届满前作出是否准予延续的决定；逾期未作决定的，视为准予延续。 卫生计生行政部门作出不受理延续申请或者不准予延续决定的，应当书面告知理由。 被许可人未按照规定申请延续和卫生计生行政部门不受理延续申请或者不准予延续的，卫生行政许可有效期届满后，原许可无效，由作出卫生行政许可决定的卫生计生行政部门注销并公布。"},{"i":46,"n":"第四十六条","txt":"依法取得的卫生行政许可，除法律、法规规定依照法定条件和程序可以转让的外，不得转让。"},{"i":47,"n":"第四十七条","txt":"卫生计生行政部门应当建立健全行政许可管理制度，对卫生行政许可行为和被许可人从事卫生行政许可事项的活动实施全面监督。"},{"i":48,"n":"第四十八条","txt":"上级卫生计生行政部门应当加强对下级卫生计生行政部门实施的卫生行政许可的监督检查，发现下级卫生计生行政部门实施卫生行政许可违反规定的，应当责令下级卫生计生行政部门纠正或者直接予以纠正。"},{"i":49,"n":"第四十九条","txt":"卫生计生行政部门发现本机关工作人员违反规定实施卫生行政许可的，应当立即予以纠正。 卫生计生行政部门发现其他地方卫生计生行政部门违反规定实施卫生行政许可的，应当立即报告共同上级卫生计生行政部门。接到报告的卫生计生行政部门应当及时进行核实，对情况属实的，应当责令有关卫生计生行政部门立即纠正；必要时，上级卫生计生行政部门可以直接予以纠正。"},{"i":50,"n":"第五十条","txt":"卫生计生行政部门应当加强对被许可人从事卫生行政许可事项活动情况的监督检查，并按照规定记录监督检查情况和处理结果，监督检查记录应当按照要求归档。"},{"i":51,"n":"第五十一条","txt":"卫生计生行政部门依法对被许可人生产、经营、服务的场所和生产经营的产品以及使用的用品用具等进行实地检查、抽样检验、检测时，应当严格遵守卫生行政执法程序和有关规定。"},{"i":52,"n":"第五十二条","txt":"卫生计生行政部门实施监督检查，不得妨碍被许可人正常生产经营和服务活动，不得索取或者收受被许可人的财物，不得谋取其他利益。 卫生计生行政部门对被许可人提供的有关技术资料和商业秘密负有保密责任。"},{"i":53,"n":"第五十三条","txt":"对违法从事卫生行政许可事项活动的，卫生计生行政部门应当及时予以查处。对涉及本辖区外的违法行为，应当通报有关卫生计生行政部门进行协查；接到通报的卫生计生行政部门应当及时组织协查；必要时，可以报告上级卫生计生行政部门组织协查；对于重大案件，由国家卫生计生委组织协查。 卫生计生行政部门应当将查处的违法案件的违法事实、处理结果告知作出卫生行政许可决定的卫生计生行政部门。"},{"i":54,"n":"第五十四条","txt":"卫生计生行政部门应当设立举报、投诉电话，任何单位和个人发现违法从事卫生行政许可事项的活动，有权向卫生计生行政部门举报，卫生计生行政部门应当及时核实、处理。"},{"i":55,"n":"第五十五条","txt":"卫生计生行政部门在安排工作经费时，应当优先保证实施卫生行政许可所需经费。 卫生计生行政部门实施卫生行政许可时，除法律、行政法规规定外，不得收取任何费用。"},{"i":56,"n":"第五十六条","txt":"被许可人取得卫生行政许可后，应当严格按照许可的条件和要求从事相应的活动。 卫生计生行政部门发现被许可人从事卫生行政许可事项的活动，不符合其申请许可时的条件和要求的，应当责令改正；逾期不改正的，应当依法收回或者吊销卫生行政许可。"},{"i":57,"n":"第五十七条","txt":"有下列情况之一的，作出卫生行政许可决定的卫生计生行政部门或者上级卫生计生行政部门，可以撤销卫生行政许可： （一）卫生计生行政部门工作人员滥用职权，玩忽职守，对不符合法定条件的申请人作出准予卫生行政许可决定的； （二）超越法定职权作出准予卫生行政许可决定的； （三）违反法定程序作出准予卫生行政许可决定的； （四）对不具备申请资格或者不符合法定条件的申请人准予卫生行政许可的； （五）依法可以撤销卫生行政许可决定的其他情形。 被许可人以欺骗、贿赂等不正当手段取得卫生行政许可的，应当予以撤销。 撤销卫生行政许可，可能对公共利益造成重大损失的，不予撤销。依照本条第一款的规定撤销卫生行政许可，被许可人的合法权益受到损害的，卫生计生行政部门应当依法予以赔偿。"},{"i":58,"n":"第五十八条","txt":"有下列情形之一的，卫生计生行政部门应当依法办理有关卫生行政许可的注销手续： （一）卫生行政许可复验期届满或者有效期届满未延续的； （二）赋予公民特定资格的卫生行政许可，该公民死亡或者丧失行为能力的； （三）法人或其他组织依法终止的； （四）卫生行政许可被依法撤销、撤回、或者卫生行政许可证件被依法吊销的； （五）因不可抗力导致卫生行政许可事项无法实施的； （六）法律、法规规定的应当注销卫生行政许可的其他情形。"},{"i":59,"n":"第五十九条","txt":"各级卫生计生行政部门应当定期对其负责实施的卫生行政许可工作进行评价，听取公民、法人或者其他组织对卫生行政许可工作的意见和建议，并研究制定改进工作的措施。"},{"i":60,"n":"第六十条","txt":"卫生计生行政部门及其工作人员违反本办法规定，有下列行为之一的，由上级卫生计生行政部门责令改正；拒不改正或者有其他情节严重的情形的，对直接负责的主管人员和其他直接责任人员依法给予行政处分： （一）对符合法定条件的卫生行政许可申请不予受理的； （二）不在卫生行政许可受理场所公示依法应当公示的材料的； （三）在受理、审查、决定卫生行政许可过程中，未向申请人、利害关系人履行法定告知义务的； （四）申请人提交的申请材料不齐全、不符合法定形式，能够一次告知而未一次告知申请人必须补正的全部内容的； （五）未向申请人说明不予受理或者不予卫生行政许可的理由的； （六）依法应当举行听证而不举行听证的。"},{"i":61,"n":"第六十一条","txt":"卫生计生行政部门及其工作人员违反本办法规定，有下列行为之一的，由上级卫生计生行政部门责令改正，并对直接负责的主管人员和其他直接责任人员依法给予行政处分；涉嫌构成犯罪的，移交司法机关追究刑事责任： （一）对不符合法定条件的申请人准予卫生行政许可或者超越法定职权作出准予卫生行政许可决定的； （二）对符合法定条件的申请人不予卫生行政许可或者不在法定期限内作出准予卫生行政许可决定的； （三）索取或者收受财物或者谋取其他利益的； （四）法律、行政法规规定的其他违法情形。"},{"i":62,"n":"第六十二条","txt":"卫生计生行政部门不依法履行监督职责或者监督不力，造成严重后果的，由其上级卫生计生行政部门责令改正，并对直接负责的主管人员和其他责任人员依法给予行政处分；涉嫌构成犯罪的，移交司法机关追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"申请人提供虚假材料或者隐瞒真实情况的，卫生计生行政部门不予受理或者不予许可，并给予警告，申请人在一年内不得再次申请该许可事项。"},{"i":64,"n":"第六十四条","txt":"被许可人以欺骗、贿赂等不正当手段取得卫生行政许可的，卫生计生行政部门应当依法给予行政处罚，申请人在三年内不得再次申请该卫生行政许可；涉嫌构成犯罪的，移交司法机关追究刑事责任。"},{"i":65,"n":"第六十五条","txt":"被许可人有下列行为之一的，卫生计生行政部门应当依法给予行政处罚；涉嫌构成犯罪的，移交司法机关追究刑事责任： （一）涂改、倒卖、出租、出借或者以其他方式非法转让卫生行政许可证件的； （二）超越卫生行政许可范围进行活动的； （三）在卫生监督检查中提供虚假材料、隐瞒活动真实情况或者拒绝提供真实材料的； （四）应依法申请变更的事项未经批准擅自变更的； （五）法律、法规、规章规定的其他违法行为。"},{"i":66,"n":"第六十六条","txt":"公民、法人或者其他组织未经卫生行政许可，擅自从事依法应当取得卫生行政许可的活动的，由卫生计生行政部门依法采取措施予以制止，并依法给予行政处罚；涉嫌构成犯罪的，移交司法机关追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"本办法规定的实施卫生行政许可的期限是指工作日，不包括法定节假日。"},{"i":68,"n":"第六十八条","txt":"本办法规定的卫生行政许可文书样本供各地参照执行。除本办法规定的文书样本外，省级卫生计生行政部门可根据工作需要补充相应文书。"},{"i":69,"n":"第六十九条","txt":"本办法自发布之日起施行。"}],"weishengjishengxitongneibushenjigongzuoguiding":[{"i":1,"n":"第一条","txt":"为进一步加强卫生计生系统内部审计工作，建立健全内部审计工作制度，完善内部监督制约机制，提高卫生计生服务效率，促进事业健康发展，根据《中华人民共和国审计法》、《中华人民共和国审计法实施条例》、《党政主要领导干部和国有企业领导人员经济责任审计规定》、《中国内部审计准则》及有关法律法规，结合实际，制定本规定。"},{"i":2,"n":"第二条","txt":"卫生计生系统内部审计是指卫生计生系统内部审计机构和审计人员对本系统、本单位实施的一种独立客观的监督、评价和咨询活动，通过运用系统、规范的方法，审查和评价业务活动、内部控制和风险管理的适当性和有效性，以促进单位完善治理，提升管理水平和服务能力。"},{"i":3,"n":"第三条","txt":"本规定适用于各级卫生计生行政部门（以下简称各部门）及所属（管）卫生计生单位（以下简称各单位）。"},{"i":4,"n":"第四条","txt":"内部审计工作在国家卫生计生委统一指导下，按照行政隶属关系和预算管理关系实行分级负责管理。各部门、各单位内部审计机构负责本单位及所属（管）单位的内部审计，并指导和监督本系统、本地区及所属（管）单位内部审计工作。"},{"i":5,"n":"第五条","txt":"各部门、各单位主要负责人对本部门、本单位内部审计工作的有效实施负责。"},{"i":6,"n":"第六条","txt":"内部审计工作坚持全面覆盖、应审尽审；实事求是、客观公正；凡审必严、防微杜渐；促进管理、推动改革的工作原则。"},{"i":7,"n":"第七条","txt":"内部审计机构应当依法依规接受国家审计机关的业务指导和监督，并积极支持和配合国家审计机关工作。"},{"i":8,"n":"第八条","txt":"各部门内部审计机构对本系统内部审计业务指导和监督的主要职责： （一）制定规章制度； （二）编制工作发展规划； （三）建立健全机构设置，加强人员配备； （四）落实工作职责； （五）组织质量评估； （六）开展培训交流； （七）法律、法规规定的其他职责。"},{"i":9,"n":"第九条","txt":"各部门、各单位内部审计机构主要职责： （一）制定工作办法和流程； （二）编制年度工作计划； （三）重大政策执行、事业发展目标完成情况审计； （四）预算执行和财务收支、工程建设、采购、国有资产管理及其他所有经济活动事项审计； （五）领导干部经济责任审计； （六）内部控制评价及风险管理审计； （七）其他审计。"},{"i":10,"n":"第十条","txt":"内部审计机构和审计人员主要权限： （一）查阅经济活动相关资料及电子数据； （二）参加或者列席与重要经济活动有关的会议； （三）对有关业务活动进行现场观察、调查和记录； （四）向有关单位和个人开展调查和询问； （五）对可能转移、隐匿、篡改、毁弃的货币资金、会计凭证、会计账簿、财务会计报告及与经济活动有关的资料，经本单位主要负责人批准，予以暂时封存； （六）对违法违规的行为及时予以揭示； （七）提出问题整改要求和管理改进建议。"},{"i":11,"n":"第十一条","txt":"各部门、各单位内部审计机构应当有计划地开展内部审计工作，实现审计全覆盖。 各部门、各单位对本级和所属重点单位要每年审计，其他审计对象1个周期内至少审计1次。审计周期由各部门、各单位结合工作规划、管理需要和审计力量合理确定。没有能力自行开展审计的单位应当委托具有相应资质的社会中介机构开展。 当年已经接受相同项目外部审计并且审计结果可以充分运用的单位，当年可以不再安排审计。"},{"i":12,"n":"第十二条","txt":"内部审计机构和审计人员发现本单位未及时处理严重违法违规问题、本单位负责人存在严重违法违规问题的，应当及时向上级主管部门反映。"},{"i":13,"n":"第十三条","txt":"各部门应当根据国家编制管理相关规定和部门管理需要，设置内部审计机构，配备专职内部审计人员。"},{"i":14,"n":"第十四条","txt":"各单位符合下列条件之一的，应当根据国家编制管理相关规定，设置独立的内部审计机构，专职审计人员不少于2人： （一）二级以上医院； （二）年收入及资产总额均达到3000万元以上； （三）所属及分支机构较多; （四）经济活动复杂； （五）管理工作需要。"},{"i":15,"n":"第十五条","txt":"不设立独立内部审计机构的部门和单位，应当指定内设机构安排专职人员履行内部审计职责。"},{"i":16,"n":"第十六条","txt":"鼓励探索实行总审计师和审计委派等制度，强化内部审计的独立性和权威性，提高监管质量和水平。"},{"i":17,"n":"第十七条","txt":"内部审计机构负责人应当具备中级以上相关专业技术职称或者5年以上审计、会计工作经历，其任免应当征求上级主管部门意见。"},{"i":18,"n":"第十八条","txt":"内部审计人员应当具备必需的专业胜任能力，并定期接受后续教育培训。"},{"i":19,"n":"第十九条","txt":"内部审计机构按照单位领导办公会或者党组（党委）会审批后的年度审计工作计划实施。临时增加的专项审计工作按照规定程序审批后实施。"},{"i":20,"n":"第二十条","txt":"内部审计机构实施审计应当遵循内部审计准则及相关规定明确的程序，主要包括：制订工作方案、组建审计项目工作组、下达审计通知书、组织现场审计、制作工作底稿、沟通审计结果、出具审计报告、督促问题整改等。"},{"i":21,"n":"第二十一条","txt":"内部审计机构开展领导干部经济责任审计及其他特定审计事项时，应当遵守国家规定的审计程序和要求。"},{"i":22,"n":"第二十二条","txt":"内部审计机构根据审计业务的需要，除涉密项目外，可以向社会购买审计服务。应当按照法律法规履行程序，委托具有相应资质的社会中介机构开展内部审计工作，并监督检查审计业务质量。"},{"i":23,"n":"第二十三条","txt":"内部审计机构应当采取督导检查、分级复核、质量评估等方式强化审计工作质量控制。"},{"i":24,"n":"第二十四条","txt":"内部审计机构应当加强内部审计信息化建设，提高审计能力、质量和效率。"},{"i":25,"n":"第二十五条","txt":"内部审计机构应当建立健全审计档案管理制度，并按照有关规定保管档案资料。"},{"i":26,"n":"第二十六条","txt":"内部审计人员与被审计单位、被审计单位主要负责人或者审计事项存在利害关系的，应当回避。"},{"i":27,"n":"第二十七条","txt":"内部审计人员办理审计事项，应当严格遵守审计职业道德和审计工作纪律，严格执行廉政纪律，做到独立、客观、公正、保密。不得歪曲事实、隐瞒问题，不得利用职权谋取私利。"},{"i":28,"n":"第二十八条","txt":"被审计单位是审计整改的主体。单位主要负责人作为第一责任人，应当组织单位领导班子集体研究部署审计整改工作，建立职责明确、分工合作的审计整改联席工作机制，明确整改任务与职责。业务直接主管领导负责主管范围内审计整改工作。"},{"i":29,"n":"第二十九条","txt":"对内部审计提出的问题和建议，被审计单位应当立行立改、全面整改，落实自查自纠，完善内部管理。"},{"i":30,"n":"第三十条","txt":"被审计单位应当在规定时间内逐项完成审计报告反映问题的整改落实，并按时报送审计整改报告。"},{"i":31,"n":"第三十一条","txt":"内部审计机构应当对审计整改工作进展、长效机制建设等情况实施指导监督和跟踪检查。"},{"i":32,"n":"第三十二条","txt":"各部门、各单位要建立健全审计通报制度。审计结果及审计整改情况应当经主要负责人批准后在适当范围内通报。"},{"i":33,"n":"第三十三条","txt":"各部门、各单位应当将审计结果及其整改落实情况作为开展以下工作的重要参考依据： （一）党风廉政建设； （二）被审计单位、领导班子和领导干部年度考核； （三）被审计单位主要负责人的考核、任免、奖惩； （四）审计事项相关责任人的个人年度考核； （五）有关政策规章和制度机制的完善。"},{"i":34,"n":"第三十四条","txt":"领导干部经济责任审计结果报告应当归入被审计领导干部本人档案。"},{"i":35,"n":"第三十五条","txt":"各部门、各单位要建立健全责任追究制度，依法依规对相关责任人严肃问责，给予相应党纪、政纪处分。"},{"i":36,"n":"第三十六条","txt":"对审计工作成效显著的内部审计机构和履行职责、忠于职守、坚持原则、作出突出成绩的内部审计人员，所在单位和上级主管部门应当按照规定给予表彰或者奖励。"},{"i":37,"n":"第三十七条","txt":"内部审计人员因履行职责遭受打击、报复、陷害的，有关部门应当及时给予保护，并依法依规对相关责任人员予以处理。"},{"i":38,"n":"第三十八条","txt":"内部审计机构有下列情形之一，由上级部门或者单位责令改正，并依法依规对相关负责人和其他直接责任人员予以处理： （一）隐瞒审计查出的问题或者提供虚假审计报告的； （二）泄露国家秘密或者被审计对象商业秘密的； （三）滥用职权、徇私舞弊、玩忽职守的； （四）违反国家规定或者单位内部规定的其他情形。"},{"i":39,"n":"第三十九条","txt":"被审计单位和相关人员有下列情形之一的，由上级部门或者单位责令改正，并依法依规对直接负责的主管人员和其他直接责任人员予以处理： （一）拒绝接受或者不配合内部审计工作的； （二）拒绝、拖延提供与内部审计事项有关资料的； （三）提供资料不真实、不完整的； （四）拒绝执行审计处理意见的。"},{"i":40,"n":"第四十条","txt":"各部门、各单位可以根据本规定，结合本地区和本单位实际情况，制订具体规定或者实施办法，并报上级主管部门或者单位备案。 除本规定外的其他卫生计生单位可以根据实际情况参照本规定执行。"},{"i":41,"n":"第四十一条","txt":"本规定自2018年1月1日起施行。2006年8月16日原卫生部公布的《卫生系统内部审计工作规定》同时废止。"}],"weishengbuguanyuweishengjiandutixijianshederuoganga2cae4":[{"i":1,"n":"第一条","txt":"为进一步转变政府职能，加强依法行政，强化政府卫生监管职能，建立健全卫生监督体系，根据《中共中央国务院关于卫生改革与发展的决定》和党的十六大精神，制定本规定。"},{"i":2,"n":"第二条","txt":"卫生监督体系是公共卫生体系的重要组成部分，是执行国家卫生法律法规，维护公共卫生秩序和医疗服务秩序，保护人民群众健康，促进经济社会协调发展的重要保证。"},{"i":3,"n":"第三条","txt":"卫生监督体系建设包括加强卫生监督机构和队伍的建设、明确卫生监督的任务和职责、健全卫生监督工作的运行机制和完善卫生监督工作的保障措施。"},{"i":4,"n":"第四条","txt":"卫生监督体系建设应当适应社会主义市场经济体制和全面推进依法行政的要求，通过进一步转变职能，严格行政执法，不断提高卫生行政部门依法办事的能力和水平。"},{"i":5,"n":"第五条","txt":"卫生监督体系建设应当按照精简、统一、效能的原则和政事分开、综合执法、依法行政的要求，深化卫生监督体制改革，合理设置机构，优化人员结构，解决职能交叉、权责脱节和执法力量薄弱等问题。"},{"i":6,"n":"第六条","txt":"各级人民政府应当加强对卫生监督工作的统一领导，统筹规划，在整合现有卫生资源基础上，加大投入，建立职责明确、行为规范、执法有力、保障到位的卫生监督体系。"},{"i":7,"n":"第七条","txt":"卫生部负责全国卫生监督体系建设的规划与指导，负责卫生部卫生监督机构的管理。 县级以上地方人民政府卫生行政部门负责辖区卫生监督机构的建设和管理。"},{"i":8,"n":"第八条","txt":"卫生监督工作实行分级管理。中央、省、设区的市、县级人民政府卫生行政部门内设卫生监督机构并下设卫生监督执行机构（以下统称卫生监督机构），负责辖区内卫生监督工作。县级卫生监督机构可在乡镇派驻卫生监督人员。"},{"i":9,"n":"第九条","txt":"各级卫生监督机构的人员编制，应当根据辖区人口、工作量、服务范围和经济水平等因素科学合理制定。"},{"i":10,"n":"第十条","txt":"卫生监督人员应当具备以下条件： （一）遵守法律和职业道德； （二）具备卫生监督相关的专业和法律知识； （三）经过卫生监督岗位培训，并考试合格； （四）新录用人员应具有大专以上学历。"},{"i":11,"n":"第十一条","txt":"卫生监督人员资格考试的具体规定由卫生部制定，省级卫生行政部门组织实施。 各级卫生监督机构应当根据监督任务聘任相应的专业人员，不断优化卫生监督队伍的专业结构。"},{"i":12,"n":"第十二条","txt":"国家对卫生监督人员实行定期培训和考核制度。 各级卫生监督机构应当不断提高卫生监督人员的专业素质和政治思想素质。"},{"i":13,"n":"第十三条","txt":"国家和省级卫生监督机构应当设置专门人员监督下级卫生监督工作，其主要任务是： 1.大案要案的督察督办； 2.各种专项整治、执法检查的督察督导； 3.监督检查卫生法律法规的贯彻执行情况； 4.检查下级卫生监督机构和人员的执法行为。"},{"i":14,"n":"第十四条","txt":"卫生监督人员执行公务时应当按照国家规定统一着装。"},{"i":15,"n":"第十五条","txt":"各级卫生监督机构应当根据工作需要配备相关专业技术人员和条件，承担卫生监督的现场检测、执法取证等工作。"},{"i":16,"n":"第十六条","txt":"各级卫生监督机构应当建立执法责任制，认真履行工作职责，做到任务明确、责任到人、各司其职，保证卫生监督的公正和效率。"},{"i":17,"n":"第十七条","txt":"各级卫生监督机构应当建立健全规章制度和工作程序，规范卫生监督行为；完善内部制约机制，建立关键岗位轮换制度和执法回避制度；公开办事程序和办事结果，接受社会监督；强化服务意识，保护和尊重管理相对人的合法权益。"},{"i":18,"n":"第十八条","txt":"各级卫生行政部门按照法律法规的规定，履行卫生监督管理职责；制定相关政策；负责卫生监督工作的宏观管理、组织协调和信息发布。"},{"i":19,"n":"第十九条","txt":"卫生监督的主要职责是：依法监督管理食品、化妆品、消毒产品、生活饮用水及涉及饮用水卫生安全产品；依法监督管理公共场所、职业、放射、学校卫生等工作；依法监督传染病防治工作；依法监督医疗机构和采供血机构及其执业人员的执业活动，整顿和规范医疗服务市场，打击非法行医和非法采供血行为；承担法律法规规定的其他职责。 各级卫生监督机构在同级卫生行政部门领导下承担卫生监督工作任务。"},{"i":20,"n":"第二十条","txt":"卫生部卫生监督机构负责全国卫生监督工作，主要职责为： （一）拟定全国卫生监督政策和工作规划，并制定相应的工作制度和规范； （二）组织实施全国卫生监督工作，对地方卫生监督工作进行指导和监督检查； （三）开展执法稽查，对地方卫生监督机构和人员的执法行为进行督察； （四）组织协调、督察督办有关大案要案的查处； （五）组织全国卫生监督抽检； （六）依法承办职责范围内的卫生行政许可和资质认定； （七）负责全国卫生监督信息的汇总分析； （八）组织全国卫生监督人员培训； （九）组织开展卫生法律法规宣传教育； （十）承担卫生部指定或交办的卫生监督事项。"},{"i":21,"n":"第二十一条","txt":"省级卫生监督机构负责辖区内卫生监督工作的组织协调和监督指导，主要职责为： （一）拟定辖区内卫生监督工作规划和年度计划，并制定相应的工作制度和规范； （二）组织实施辖区内的卫生监督工作，对下级的卫生监督工作进行指导和监督检查； （三）依法承办职责范围内的卫生行政许可、资质认定和日常卫生监督； （四）查处辖区内大案要案，参与重大活动的卫生保障； （五）承担国家卫生监督抽检任务，组织实施辖区内的卫生监督抽检； （六）开展执法稽查，对下级卫生监督机构和人员的执法行为进行督察； （七）组织协调辖区内各级卫生监督机构的分级管理，落实执法责任制； （八）负责辖区内卫生监督人员的资格审定工作，组织开展资格考试； （九）组织辖区内卫生监督人员培训； （十）负责辖区内卫生监督信息的汇总、核实、分析、上报，并按照规定进行发布； （十一）组织开展卫生法律法规宣传教育； （十二）协调和指导辖区内铁路、交通、民航"},{"i":22,"n":"第二十二条","txt":"设区的市、县级卫生监督机构负责辖区内日常卫生监督工作，主要职责为： （一）卫生行政许可 1.承办食品生产经营单位、餐饮业及集体食堂卫生条件的卫生行政许可； 2.承办公共场所卫生条件的卫生行政许可； 3.承办供水单位卫生条件的卫生行政许可； 4.卫生行政部门交办的其他行政许可事项。 （二）公共卫生监督 1.对食品生产经营单位、餐饮业及集体食堂的卫生条件、卫生防护设施、生产经营活动及直接从事食品生产经营活动人员的健康管理进行卫生监督检查，查处违法行为； 2.对化妆品、消毒产品、生活饮用水、涉及饮用水卫生安全产品及其他健康相关产品的卫生及其生产经营活动进行卫生监督检查，查处违法行为； 3.对公共场所的卫生条件及其从业人员的健康管理进行卫生监督检查，查处违法行为； 4.对用人单位开展职业健康监护情况进行卫生监督检查，查处违法行为； 5.对建设项目执行职业病危害评价制度情况进行卫生监督检查，查处"},{"i":23,"n":"第二十三条","txt":"上级卫生行政部门可以直接调查处理下级卫生行政部门管辖范围内有关案件，也可以把管辖范围内有关案件委托下级卫生行政部门调查处理。"},{"i":24,"n":"第二十四条","txt":"下级卫生行政部门对管辖范围的案件，认为需要由上级卫生行政部门调查处理的，可以提请上级卫生行政部门处理。"},{"i":25,"n":"第二十五条","txt":"各级卫生监督机构履行卫生监督管理职责所需经费，包括人员经费、公务费、业务费和发展建设支出，按照财政部、国家计委、卫生部《关于卫生事业补助政策的意见》（财社〔2000〕17号）规定，由同级政府预算根据需要合理安排，保证其履行职责的必要经费。"},{"i":26,"n":"第二十六条","txt":"中央和省级财政对困难地区实施卫生监督机构基础设施建设等项目给予适当补助。"},{"i":27,"n":"第二十七条","txt":"在建立和完善卫生监督体系的同时，卫生部配合有关部门按照公共财政的要求，进一步完善卫生监督机构财政补助有关政策和办法。"},{"i":28,"n":"第二十八条","txt":"各省、自治区、直辖市应当根据本规定，并结合当地实际情况制定具体实施方案。"},{"i":29,"n":"第二十九条","txt":"卫生监督机构应当根据国家有关政府和事业单位改革的规定，继续深化改革。"},{"i":30,"n":"第三十条","txt":"本规定自发布之日起施行。过去颁布的有关文件与本规定抵触的，以本规定为准。"}],"keganranrenleidegaozhibingxingbingyuanweishengwujufbe2ce":[{"i":1,"n":"第一条","txt":"为加强可感染人类的高致病性病原微生物菌（毒）种或样本运输的管理，保障人体健康和公共卫生，依据《中华人民共和国传染病防治法》、《病原微生物实验室生物安全管理条例》等法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称可感染人类的高致病性病原微生物菌（毒）种或样本是指在《人间传染的病原微生物名录》中规定的第一类、第二类病原微生物菌（毒）种或样本。"},{"i":3,"n":"第三条","txt":"本规定适用于可感染人类的高致病性病原微生物菌（毒）种或样本的运输管理工作。 《人间传染的病原微生物名录》中第三类病原微生物运输包装分类为A类的病原微生物菌（毒）种或样本，以及疑似高致病性病原微生物菌（毒）种或样本，按照本规定进行运输管理。"},{"i":4,"n":"第四条","txt":"运输第三条规定的菌（毒）种或样本（以下统称高致病性病原微生物菌（毒）种或样本），应当经省级以上卫生行政部门批准。未经批准，不得运输。"},{"i":5,"n":"第五条","txt":"从事疾病预防控制、医疗、教学、科研、菌（毒）种保藏以及生物制品生产的单位，因工作需要，可以申请运输高致病性病原微生物菌（毒）种或样本。"},{"i":6,"n":"第六条","txt":"申请运输高致病性病原微生物菌（毒）种或样本的单位（以下简称申请单位），在运输前应当向省级卫生行政部门提出申请，并提交以下申请材料（原件一份，复印件三份）： （一）可感染人类的高致病性病原微生物菌（毒）种或样本运输申请表； （二）法人资格证明材料（复印件）； （三）接收高致病性病原微生物菌（毒）种或样本的单位（以下简称接收单位）同意接收的证明文件； （四）本规定第七条第（二）、（三）项所要求的证明文件（复印件）； （五）容器或包装材料的批准文号、合格证书（复印件）或者高致病性病原微生物菌（毒）种或样本运输容器或包装材料承诺书； （六）其他有关资料。"},{"i":7,"n":"第七条","txt":"接收单位应当符合以下条件： （一）具有法人资格； （二）具备从事高致病性病原微生物实验活动资格的实验室； （三）取得有关政府主管部门核发的从事高致病性病原微生物实验活动、菌（毒）种或样本保藏、生物制品生产等的批准文件。"},{"i":8,"n":"第八条","txt":"在固定的申请单位和接收单位之间多次运输相同品种高致病性病原微生物菌（毒）种或样本的，可以申请多次运输。多次运输的有效期为6个月；期满后需要继续运输的，应当重新提出申请。"},{"i":9,"n":"第九条","txt":"申请在省、自治区、直辖市行政区域内运输高致病性病原微生物菌（毒）种或样本的，由省、自治区、直辖市卫生行政部门审批。 省级卫生行政部门应当对申请单位提交的申请材料及时审查，对申请材料不齐全或者不符合法定形式的，应当即时出具申请材料补正通知书；对申请材料齐全或者符合法定形式的，应当即时受理，并在5个工作日内做出是否批准的决定；符合法定条件的，颁发《可感染人类的高致病性病原微生物菌（毒）种或样本准运证书》；不符合法定条件的，应当出具不予批准的决定并说明理由。"},{"i":10,"n":"第十条","txt":"申请跨省、自治区、直辖市运输高致病性病原微生物菌（毒）种或样本的，应当将申请材料提交运输出发地省级卫生行政部门进行初审；对符合要求的，省级卫生行政部门应当在3个工作日内出具初审意见，并将初审意见和申报材料上报卫生部审批。 卫生部应当自收到申报材料后3个工作日内做出是否批准的决定。符合法定条件的，颁发《可感染人类的高致病性病原微生物菌（毒）种或样本准运证书》；不符合法定条件的，应当出具不予批准的决定并说明理由。"},{"i":11,"n":"第十一条","txt":"对于为控制传染病暴发、流行或者突发公共卫生事件应急处理的高致病性病原微生物菌（毒）种或样本的运输申请，省级卫生行政部门与卫生部之间可以通过传真的方式进行上报和审批；需要提交有关材料原件的，应当于事后尽快补齐。 根据疾病控制工作的需要，应当向中国疾病预防控制中心运送高致病性病原微生物菌（毒）种或样本的，向中国疾病预防控制中心直接提出申请，由中国疾病预防控制中心审批；符合法定条件的，颁发《可感染人类的高致病性病原微生物菌（毒）种或样本准运证书》；不符合法定条件的，应当出具不予批准的决定并说明理由。中国疾病预防控制中心应当将审批情况于3日内报卫生部备案。"},{"i":12,"n":"第十二条","txt":"运输高致病性病原微生物菌（毒）种或样本的容器或包装材料应当达到国际民航组织《危险物品航空安全运输技术细则》（Doc9284包装说明PI602）规定的A类包装标准，符合防水、防破损、防外泄、耐高温、耐高压的要求，并应当印有卫生部规定的生物危险标签、标识、运输登记表、警告用语和提示用语。"},{"i":13,"n":"第十三条","txt":"运输高致病性病原微生物菌（毒）种或样本，应当有专人护送，护送人员不得少于两人。申请单位应当对护送人员进行相关的生物安全知识培训，并在护送过程中采取相应的防护措施。"},{"i":14,"n":"第十四条","txt":"申请单位应当凭省级以上卫生行政部门或中国疾病预防控制中心核发的《可感染人类的高致病性病原微生物菌（毒）种或样本准运证书》到民航等相关部门办理手续。 通过民航运输的，托运人应当按照《中国民用航空危险品运输管理规定》（CCAR276）和国际民航组织文件《危险物品航空安全运输技术细则》（Doc9284）的要求，正确进行分类、包装、加标记、贴标签并提交正确填写的危险品航空运输文件，交由民用航空主管部门批准的航空承运人和机场实施运输。如需由未经批准的航空承运人和机场实施运输的，应当经民用航空主管部门批准。"},{"i":15,"n":"第十五条","txt":"高致病性病原微生物菌（毒）种或样本在运输之前的包装以及送达后包装的开启，应当在符合生物安全规定的场所中进行。 申请单位在运输前应当仔细检查容器和包装是否符合安全要求，所有容器和包装的标签以及运输登记表是否完整无误，容器放置方向是否正确。"},{"i":16,"n":"第十六条","txt":"在运输结束后，申请单位应当将运输情况向原批准部门书面报告。"},{"i":17,"n":"第十七条","txt":"对于违反本规定的行为，依照《病原微生物实验室生物安全管理条例》第六十二条、六十七条的有关规定予以处罚。"},{"i":18,"n":"第十八条","txt":"高致病性病原微生物菌（毒）种或样本的出入境，按照卫生部和国家质检总局《关于加强医用特殊物品出入境管理卫生检疫的通知》进行管理。"},{"i":19,"n":"第十九条","txt":"本规定自2006年2月1日起施行。"}],"taiwandiquyishizaidaluduanqixingyiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强台湾地区医师（以下简称台湾医师）在大陆短期行医的管理，根据《中华人民共和国执业医师法》（以下简称《执业医师法》）、《医疗机构管理条例》等法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称台湾医师是指具有台湾地区合法行医资格的医师。 台湾医师在大陆短期行医，是指台湾医师应聘在大陆医疗机构从事不超过3年的临床诊疗活动。"},{"i":3,"n":"第三条","txt":"台湾医师在大陆短期行医应当按照本规定进行执业注册，取得《台湾医师短期行医执业证书》。 《台湾医师短期行医执业证书》由卫生部统一制作。"},{"i":4,"n":"第四条","txt":"台湾医师在大陆短期行医，应当符合大陆有关台湾地区人员的就业规定，由大陆具有独立法人资格的医疗机构邀请并作为聘用单位。"},{"i":5,"n":"第五条","txt":"台湾医师在大陆短期行医的执业注册机关为医疗机构所在地设区的市级以上地方人民政府卫生行政部门和中医药管理部门。 台湾医师申请大陆短期行医执业注册的执业类别可以为临床、中医、口腔三个类别之一。执业范围应当符合《执业医师法》和卫生部有关执业范围的规定。"},{"i":6,"n":"第六条","txt":"台湾医师申请在大陆短期行医执业注册，应当提交下列材料： （一）台湾医师在大陆短期行医执业注册申请； （二）台湾永久居民身份证明材料； （三）近6个月内的2寸免冠正面半身照片2张； （四）与申请执业范围相适应的医学专业最高学历证明； （五）台湾医师的行医执照或者行医资格证明； （六）近3个月内的体检健康证明； （七）无刑事犯罪记录的证明； （八）大陆聘用医疗机构与台湾医师签订的协议书； （九）大陆省级以上人民政府卫生行政部门规定的其他材料。 前款（四）、（五）、（六）、（七）项的内容必须经过台湾地区公证机关的公证。 以上材料应当为中文文本。"},{"i":7,"n":"第七条","txt":"台湾医师可以自行办理或者书面委托大陆的聘用医疗机构代其办理短期行医执业注册手续。"},{"i":8,"n":"第八条","txt":"负责受理台湾医师短期行医执业注册申请的执业注册机关应当自受理申请之日起20日内进行审核。对审核合格的予以注册，并发给《台湾医师短期行医执业证书》。"},{"i":9,"n":"第九条","txt":"《台湾医师短期行医执业证书》有效期应与台湾医师在大陆医疗机构应聘的时间相同，最长为3年。有效期满后，如拟继续执业的，应当重新办理短期行医执业注册手续。"},{"i":10,"n":"第十条","txt":"台湾医师在大陆短期行医必须遵守医疗卫生管理法律、行政法规、部门规章及诊疗护理规范、常规，尊重当地的风俗习惯。"},{"i":11,"n":"第十一条","txt":"台湾医师在大陆短期行医必须在执业有效期内按照注册的执业地点、执业类别、执业范围从事相应的诊疗活动。"},{"i":12,"n":"第十二条","txt":"台湾医师在大陆短期行医应当按照《医师定期考核管理办法》和卫生部有关规定接受定期考核。"},{"i":13,"n":"第十三条","txt":"台湾医师短期行医执业注册后有下列情形之一的，聘用的医疗机构应当在30日内报告准予其执业注册的卫生行政部门，卫生行政部门应当注销注册，收回《台湾医师短期行医执业证书》： （一）医疗机构和台湾医师解除聘用关系的； （二）身体健康状况不适宜继续执业的； （三）在考核周期内因考核不合格，被责令暂停执业活动，并在暂停执业活动期满经培训后再次考核仍不合格的； （四）违反《执业医师法》有关规定，被吊销《台湾医师短期行医执业证书》的； （五）出借、出租、抵押、转让、涂改《台湾医师短期行医执业证书》的； （六）死亡或者被宣告失踪的； （七）受刑事处罚的； （八）被公安机关取消大陆居留资格的； （九）卫生部规定不宜从事医疗、预防、保健业务的其他情形的。"},{"i":14,"n":"第十四条","txt":"台湾医师因本办法第十三条第（三）项、第（四）项、第（七）项、第（八）项情形而被注销执业注册的，2年内不得再次申请在大陆短期行医。"},{"i":15,"n":"第十五条","txt":"卫生部指定的机构设立台湾医师短期行医信息查询系统。 执业注册机关在审核台湾医师短期行医执业注册申请时应当进行有关信息查询。 执业注册机关核发或者注销《台湾医师短期行医执业证书》后10日内将有关信息向卫生部指定的查询机构备案。 聘用台湾医师短期行医的医疗机构应当将台湾医师考核和执业情况向注册机关和卫生部指定的查询机构报告。"},{"i":16,"n":"第十六条","txt":"台湾医师在大陆短期行医期间发生医疗事故争议的，按照《医疗事故处理条例》及有关规定处理。"},{"i":17,"n":"第十七条","txt":"医疗机构聘用未经大陆短期行医执业注册的台湾医师从事诊疗活动，视为聘用非卫生技术人员，按照《医疗机构管理条例》第四十八条规定处理。"},{"i":18,"n":"第十八条","txt":"台湾医师未取得《台湾医师短期行医执业证书》行医或者未按照注册的有效期从事诊疗活动的，按照《执业医师法》第三十九条规定处理。"},{"i":19,"n":"第十九条","txt":"台湾医师未按照注册的执业地点、执业类别、执业范围从事诊疗活动的，由县级以上人民政府卫生行政部门责令改正，并给予警告；逾期不改的，按照《执业医师法》第三十七条第（一）项规定处理。"},{"i":20,"n":"第二十条","txt":"取得大陆《医师资格证书》的台湾居民申请在大陆执业注册的，按照《医师执业注册暂行办法》执行。"},{"i":21,"n":"第二十一条","txt":"本规定自2009年3月1日起施行。原有规定与本规定不符的，以本规定为准。"}],"guojiazhiyeweishengbiaozhunguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强国家职业卫生标准的管理，根据《中华人民共和国职业病防治法》（以下简称《职业病防治法》），制定本办法。"},{"i":2,"n":"第二条","txt":"对下列需要在全国范围内统一的技术要求，须制定国家职业卫生标准： （一）职业卫生专业基础标准； （二）工作场所作业条件卫生标准； （三）工业毒物、生产性粉尘、物理因素职业接触限值； （四）职业病诊断标准； （五）职业照射放射防护标准； （六）职业防护用品卫生标准； （七）职业危害防护导则； （八）劳动生理卫生、工效学标准； （九）职业性危害因素检测、检验方法。"},{"i":3,"n":"第三条","txt":"本办法适用于国家职业卫生标准的立项、起草、审查、公布、复审和解释。"},{"i":4,"n":"第四条","txt":"卫生部主管国家职业卫生标准工作；卫生部委托办事机构，承担国家职业卫生标准的日常管理工作；由卫生部聘请有关技术专家组成全国卫生标准技术委员会，负责国家职业卫生标准的技术审查工作。"},{"i":5,"n":"第五条","txt":"国家职业卫生标准制定的原则： （一）符合国家有关法律、法规和方针、政策，满足职业卫生管理工作的需要； （二）体现科学性和先进性，注重可操作性； （三）在充分考虑我国国情的基础上，积极采用国际通用标准； （四）逐步实现体系化，保持标准的完整性和有机联系。"},{"i":6,"n":"第六条","txt":"国家职业卫生标准分为强制性标准和推荐性标准。强制性标准分为全文强制和条文强制两种形式。 强制性标准包括： （一）工作场所作业条件的卫生标准； （二）工业毒物、生产性粉尘、物理因素职业接触限值； （三）职业病诊断标准； （四）职业照射放射防护标准； （五）职业防护用品卫生标准； 其他标准为推荐性标准。"},{"i":7,"n":"第七条","txt":"任何单位和个人可向卫生部标准办事机构提出制定国家职业卫生标准立项的建议。建议内容包括：标准名称、制定标准的目的、主要技术内容和国内外主要情况说明等。"},{"i":8,"n":"第八条","txt":"制定标准的立项建议经过卫生部标准办事机构审核，并拟定年度计划草案上报卫生部，由卫生部批准后下达执行。 年度标准计划包括标准的名称、研制单位、完成时间等。"},{"i":9,"n":"第九条","txt":"卫生部委托卫生部标准办事机构对年度标准制定计划的执行情况进行监督检查。 承担年度标准制定计划项目的研制单位应按计划组织实施，并按时完成标准编制工作。"},{"i":10,"n":"第十条","txt":"年度标准计划在执行过程中有下列情况之一的，可以进行调整： （一）职业卫生管理工作急需的项目可以增补；对拟增加的标准项目应当进行补充论证； （二）特殊情况下，可以对项目的内容进行调整； （三）不宜制定标准的项目，可以撤销。 计划的调整应经卫生部批准。"},{"i":11,"n":"第十一条","txt":"确定标准的研制单位，应坚持公开、公正、择优原则，鼓励用人单位、行业协会或社会团体参与标准的研制工作。 承担研制标准的单位应当熟悉国内外有关标准现状并有较强的技术水平、条件。"},{"i":12,"n":"第十二条","txt":"研制国家职业卫生标准，应当深入调查研究，总结实践经验，广泛听取有关部门、组织和用人单位的意见。涉及国务院其他部门的职责或与国务院其他部门关系紧密的，研制单位应当充分听取国务院其他部门的意见。研制单位与其他部门有不同意见时，应当充分协商；经过充分协商不能取得一致意见的，研制单位应当在上报标准送审稿时说明情况和理由。"},{"i":13,"n":"第十三条","txt":"研制单位应当将标准送审稿及其说明、对标准送审稿主要问题的不同意见和其他有关材料按规定报送审查。"},{"i":14,"n":"第十四条","txt":"全国卫生标准技术委员会按照《全国卫生标准技术委员会章程》及有关规定，对国家职业卫生标准进行技术审查。"},{"i":15,"n":"第十五条","txt":"对全国卫生标准技术委员会审查通过的标准，由卫生部批准，并以卫生部通告的形式公布。在批准前，根据需要，卫生部可征求有关部门和单位的意见。 国家职业卫生标准的代号由大写汉语拼音字母构成。强制性标准的代号为“GBZ”，推荐性标准的代号为“GBZ/T”。 国家职业卫生标准的编号由国家职业卫生标准的代号、发布的顺序号和发布的年号构成。示例： GBZXXXX-XXXX、GBZ/TXXXX-XXXX。"},{"i":16,"n":"第十六条","txt":"国家职业卫生标准实施后，卫生部应根据情况的变化对标准适时进行复审。复审的结论分为确认、修订、废止。复审的周期一般不超过五年。"},{"i":17,"n":"第十七条","txt":"国家职业卫生标准由卫生部负责解释。国家职业卫生标准的解释同标准具有同等效力。"},{"i":18,"n":"第十八条","txt":"卫生部标准办事机构应调查了解国家职业卫生标准的实施情况，收集和研究国内外有关标准、技术信息资料和实践经验，对标准的实施情况进行评估和分析，开展国家职业卫生标准的交流、宣传、培训、技术指导和技术咨询活动。"},{"i":19,"n":"第十九条","txt":"国家鼓励任何单位和个人参与国家职业卫生标准研制。对水平高、效果好的标准进行奖励。"},{"i":20,"n":"第二十条","txt":"国家职业卫生标准的出版、印刷由卫生部委托指定出版机构负责。"},{"i":21,"n":"第二十一条","txt":"本办法自2002年5月1日起施行。"}],"chufangguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范处方管理，提高处方质量，促进合理用药，保障医疗安全，根据《执业医师法》、《药品管理法》、《医疗机构管理条例》、《麻醉药品和精神药品管理条例》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称处方，是指由注册的执业医师和执业助理医师（以下简称医师）在诊疗活动中为患者开具的、由取得药学专业技术职务任职资格的药学专业技术人员（以下简称药师）审核、调配、核对，并作为患者用药凭证的医疗文书。处方包括医疗机构病区用药医嘱单。 本办法适用于与处方开具、调剂、保管相关的医疗机构及其人员。"},{"i":3,"n":"第三条","txt":"卫生部负责全国处方开具、调剂、保管相关工作的监督管理。 县级以上地方卫生行政部门负责本行政区域内处方开具、调剂、保管相关工作的监督管理。"},{"i":4,"n":"第四条","txt":"医师开具处方和药师调剂处方应当遵循安全、有效、经济的原则。 处方药应当凭医师处方销售、调剂和使用。"},{"i":5,"n":"第五条","txt":"处方标准（附件1）由卫生部统一规定，处方格式由省、自治区、直辖市卫生行政部门（以下简称省级卫生行政部门）统一制定，处方由医疗机构按照规定的标准和格式印制。"},{"i":6,"n":"第六条","txt":"处方书写应当符合下列规则： （一）患者一般情况、临床诊断填写清晰、完整，并与病历记载相一致。 （二）每张处方限于一名患者的用药。 （三）字迹清楚，不得涂改；如需修改，应当在修改处签名并注明修改日期。 （四）药品名称应当使用规范的中文名称书写，没有中文名称的可以使用规范的英文名称书写；医疗机构或者医师、药师不得自行编制药品缩写名称或者使用代号；书写药品名称、剂量、规格、用法、用量要准确规范，药品用法可用规范的中文、英文、拉丁文或者缩写体书写，但不得使用“遵医嘱”、“自用”等含糊不清字句。 （五）患者年龄应当填写实足年龄，新生儿、婴幼儿写日、月龄，必要时要注明体重。 （六）西药和中成药可以分别开具处方，也可以开具一张处方，中药饮片应当单独开具处方。 （七）开具西药、中成药处方，每一种药品应当另起一行，每张处方不得超过5种药品。 （八）中药饮片处方的书写，一般应当按照“君、臣、佐、使”的顺序"},{"i":7,"n":"第七条","txt":"药品剂量与数量用阿拉伯数字书写。剂量应当使用法定剂量单位：重量以克（g）、毫克（mg）、微克（μg）、纳克（ng）为单位；容量以升（L）、毫升（ml）为单位；国际单位（IU）、单位（U）；中药饮片以克（g）为单位。 片剂、丸剂、胶囊剂、颗粒剂分别以片、丸、粒、袋为单位；溶液剂以支、瓶为单位；软膏及乳膏剂以支、盒为单位；注射剂以支、瓶为单位，应当注明含量；中药饮片以剂为单位。"},{"i":8,"n":"第八条","txt":"经注册的执业医师在执业地点取得相应的处方权。 经注册的执业助理医师在医疗机构开具的处方，应当经所在执业地点执业医师签名或加盖专用签章后方有效。"},{"i":9,"n":"第九条","txt":"经注册的执业助理医师在乡、民族乡、镇、村的医疗机构独立从事一般的执业活动，可以在注册的执业地点取得相应的处方权。"},{"i":10,"n":"第十条","txt":"医师应当在注册的医疗机构签名留样或者专用签章备案后，方可开具处方。"},{"i":11,"n":"第十一条","txt":"医疗机构应当按照有关规定，对本机构执业医师和药师进行麻醉药品和精神药品使用知识和规范化管理的培训。执业医师经考核合格后取得麻醉药品和第一类精神药品的处方权，药师经考核合格后取得麻醉药品和第一类精神药品调剂资格。 医师取得麻醉药品和第一类精神药品处方权后，方可在本机构开具麻醉药品和第一类精神药品处方，但不得为自己开具该类药品处方。药师取得麻醉药品和第一类精神药品调剂资格后，方可在本机构调剂麻醉药品和第一类精神药品。"},{"i":12,"n":"第十二条","txt":"试用期人员开具处方，应当经所在医疗机构有处方权的执业医师审核、并签名或加盖专用签章后方有效。"},{"i":13,"n":"第十三条","txt":"进修医师由接收进修的医疗机构对其胜任本专业工作的实际情况进行认定后授予相应的处方权。"},{"i":14,"n":"第十四条","txt":"医师应当根据医疗、预防、保健需要，按照诊疗规范、药品说明书中的药品适应证、药理作用、用法、用量、禁忌、不良反应和注意事项等开具处方。 开具医疗用毒性药品、放射性药品的处方应当严格遵守有关法律、法规和规章的规定。"},{"i":15,"n":"第十五条","txt":"医疗机构应当根据本机构性质、功能、任务，制定药品处方集。"},{"i":16,"n":"第十六条","txt":"医疗机构应当按照经药品监督管理部门批准并公布的药品通用名称购进药品。同一通用名称药品的品种，注射剂型和口服剂型各不得超过2种，处方组成类同的复方制剂1～2种。因特殊诊疗需要使用其他剂型和剂量规格药品的情况除外。"},{"i":17,"n":"第十七条","txt":"医师开具处方应当使用经药品监督管理部门批准并公布的药品通用名称、新活性化合物的专利药品名称和复方制剂药品名称。 医师开具院内制剂处方时应当使用经省级卫生行政部门审核、药品监督管理部门批准的名称。 医师可以使用由卫生部公布的药品习惯名称开具处方。"},{"i":18,"n":"第十八条","txt":"处方开具当日有效。特殊情况下需延长有效期的，由开具处方的医师注明有效期限，但有效期最长不得超过3天。"},{"i":19,"n":"第十九条","txt":"处方一般不得超过7日用量；急诊处方一般不得超过3日用量；对于某些慢性病、老年病或特殊情况，处方用量可适当延长，但医师应当注明理由。 医疗用毒性药品、放射性药品的处方用量应当严格按照国家有关规定执行。"},{"i":20,"n":"第二十条","txt":"医师应当按照卫生部制定的麻醉药品和精神药品临床应用指导原则，开具麻醉药品、第一类精神药品处方。"},{"i":21,"n":"第二十一条","txt":"门（急）诊癌症疼痛患者和中、重度慢性疼痛患者需长期使用麻醉药品和第一类精神药品的，首诊医师应当亲自诊查患者，建立相应的病历，要求其签署《知情同意书》。 病历中应当留存下列材料复印件： （一）二级以上医院开具的诊断证明； （二）患者户籍簿、身份证或者其他相关有效身份证明文件； （三）为患者代办人员身份证明文件。"},{"i":22,"n":"第二十二条","txt":"除需长期使用麻醉药品和第一类精神药品的门（急）诊癌症疼痛患者和中、重度慢性疼痛患者外，麻醉药品注射剂仅限于医疗机构内使用。"},{"i":23,"n":"第二十三条","txt":"为门（急）诊患者开具的麻醉药品注射剂，每张处方为一次常用量；控缓释制剂，每张处方不得超过7日常用量；其他剂型，每张处方不得超过3日常用量。 第一类精神药品注射剂，每张处方为一次常用量；控缓释制剂，每张处方不得超过7日常用量；其他剂型，每张处方不得超过3日常用量。哌醋甲酯用于治疗儿童多动症时，每张处方不得超过15日常用量。 第二类精神药品一般每张处方不得超过7日常用量；对于慢性病或某些特殊情况的患者，处方用量可以适当延长，医师应当注明理由。"},{"i":24,"n":"第二十四条","txt":"为门（急）诊癌症疼痛患者和中、重度慢性疼痛患者开具的麻醉药品、第一类精神药品注射剂，每张处方不得超过3日常用量；控缓释制剂，每张处方不得超过15日常用量；其他剂型，每张处方不得超过7日常用量。"},{"i":25,"n":"第二十五条","txt":"为住院患者开具的麻醉药品和第一类精神药品处方应当逐日开具，每张处方为1日常用量。"},{"i":26,"n":"第二十六条","txt":"对于需要特别加强管制的麻醉药品，盐酸二氢埃托啡处方为一次常用量，仅限于二级以上医院内使用；盐酸哌替啶处方为一次常用量，仅限于医疗机构内使用。"},{"i":27,"n":"第二十七条","txt":"医疗机构应当要求长期使用麻醉药品和第一类精神药品的门（急）诊癌症患者和中、重度慢性疼痛患者，每3个月复诊或者随诊一次。"},{"i":28,"n":"第二十八条","txt":"医师利用计算机开具、传递普通处方时，应当同时打印出纸质处方，其格式与手写处方一致；打印的纸质处方经签名或者加盖签章后有效。药师核发药品时，应当核对打印的纸质处方，无误后发给药品，并将打印的纸质处方与计算机传递处方同时收存备查。"},{"i":29,"n":"第二十九条","txt":"取得药学专业技术职务任职资格的人员方可从事处方调剂工作。"},{"i":30,"n":"第三十条","txt":"药师在执业的医疗机构取得处方调剂资格。药师签名或者专用签章式样应当在本机构留样备查。"},{"i":31,"n":"第三十一条","txt":"具有药师以上专业技术职务任职资格的人员负责处方审核、评估、核对、发药以及安全用药指导；药士从事处方调配工作。"},{"i":32,"n":"第三十二条","txt":"药师应当凭医师处方调剂处方药品，非经医师处方不得调剂。"},{"i":33,"n":"第三十三条","txt":"药师应当按照操作规程调剂处方药品：认真审核处方，准确调配药品，正确书写药袋或粘贴标签，注明患者姓名和药品名称、用法、用量，包装；向患者交付药品时，按照药品说明书或者处方用法，进行用药交待与指导，包括每种药品的用法、用量、注意事项等。"},{"i":34,"n":"第三十四条","txt":"药师应当认真逐项检查处方前记、正文和后记书写是否清晰、完整，并确认处方的合法性。"},{"i":35,"n":"第三十五条","txt":"药师应当对处方用药适宜性进行审核，审核内容包括： （一）规定必须做皮试的药品，处方医师是否注明过敏试验及结果的判定； （二）处方用药与临床诊断的相符性； （三）剂量、用法的正确性； （四）选用剂型与给药途径的合理性； （五）是否有重复给药现象； （六）是否有潜在临床意义的药物相互作用和配伍禁忌； （七）其他用药不适宜情况。"},{"i":36,"n":"第三十六条","txt":"药师经处方审核后，认为存在用药不适宜时，应当告知处方医师，请其确认或者重新开具处方。 药师发现严重不合理用药或者用药错误，应当拒绝调剂，及时告知处方医师，并应当记录，按照有关规定报告。"},{"i":37,"n":"第三十七条","txt":"药师调剂处方时必须做到“四查十对”：查处方，对科别、姓名、年龄；查药品，对药名、剂型、规格、数量；查配伍禁忌，对药品性状、用法用量；查用药合理性，对临床诊断。"},{"i":38,"n":"第三十八条","txt":"药师在完成处方调剂后，应当在处方上签名或者加盖专用签章。"},{"i":39,"n":"第三十九条","txt":"药师应当对麻醉药品和第一类精神药品处方，按年月日逐日编制顺序号。"},{"i":40,"n":"第四十条","txt":"药师对于不规范处方或者不能判定其合法性的处方，不得调剂。"},{"i":41,"n":"第四十一条","txt":"医疗机构应当将本机构基本用药供应目录内同类药品相关信息告知患者。"},{"i":42,"n":"第四十二条","txt":"除麻醉药品、精神药品、医疗用毒性药品和儿科处方外，医疗机构不得限制门诊就诊人员持处方到药品零售企业购药。"},{"i":43,"n":"第四十三条","txt":"医疗机构应当加强对本机构处方开具、调剂和保管的管理。"},{"i":44,"n":"第四十四条","txt":"医疗机构应当建立处方点评制度，填写处方评价表（附件2），对处方实施动态监测及超常预警，登记并通报不合理处方，对不合理用药及时予以干预。"},{"i":45,"n":"第四十五条","txt":"医疗机构应当对出现超常处方3次以上且无正当理由的医师提出警告，限制其处方权；限制处方权后，仍连续2次以上出现超常处方且无正当理由的，取消其处方权。"},{"i":46,"n":"第四十六条","txt":"医师出现下列情形之一的，处方权由其所在医疗机构予以取消： （一）被责令暂停执业； （二）考核不合格离岗培训期间； （三）被注销、吊销执业证书； （四）不按照规定开具处方，造成严重后果的； （五）不按照规定使用药品，造成严重后果的； （六）因开具处方牟取私利。"},{"i":47,"n":"第四十七条","txt":"未取得处方权的人员及被取消处方权的医师不得开具处方。未取得麻醉药品和第一类精神药品处方资格的医师不得开具麻醉药品和第一类精神药品处方。"},{"i":48,"n":"第四十八条","txt":"除治疗需要外，医师不得开具麻醉药品、精神药品、医疗用毒性药品和放射性药品处方。"},{"i":49,"n":"第四十九条","txt":"未取得药学专业技术职务任职资格的人员不得从事处方调剂工作。"},{"i":50,"n":"第五十条","txt":"处方由调剂处方药品的医疗机构妥善保存。普通处方、急诊处方、儿科处方保存期限为1年，医疗用毒性药品、第二类精神药品处方保存期限为2年，麻醉药品和第一类精神药品处方保存期限为3年。 处方保存期满后，经医疗机构主要负责人批准、登记备案，方可销毁。"},{"i":51,"n":"第五十一条","txt":"医疗机构应当根据麻醉药品和精神药品处方开具情况，按照麻醉药品和精神药品品种、规格对其消耗量进行专册登记，登记内容包括发药日期、患者姓名、用药数量。专册保存期限为3年。"},{"i":52,"n":"第五十二条","txt":"县级以上地方卫生行政部门应当定期对本行政区域内医疗机构处方管理情况进行监督检查。 县级以上卫生行政部门在对医疗机构实施监督管理过程中，发现医师出现本办法第四十六条规定情形的，应当责令医疗机构取消医师处方权。"},{"i":53,"n":"第五十三条","txt":"卫生行政部门的工作人员依法对医疗机构处方管理情况进行监督检查时，应当出示证件；被检查的医疗机构应当予以配合，如实反映情况，提供必要的资料，不得拒绝、阻碍、隐瞒。"},{"i":54,"n":"第五十四条","txt":"医疗机构有下列情形之一的，由县级以上卫生行政部门按照《医疗机构管理条例》第四十八条的规定，责令限期改正，并可处以5000元以下的罚款；情节严重的，吊销其《医疗机构执业许可证》： （一）使用未取得处方权的人员、被取消处方权的医师开具处方的； （二）使用未取得麻醉药品和第一类精神药品处方资格的医师开具麻醉药品和第一类精神药品处方的； （三）使用未取得药学专业技术职务任职资格的人员从事处方调剂工作的。"},{"i":55,"n":"第五十五条","txt":"医疗机构未按照规定保管麻醉药品和精神药品处方，或者未依照规定进行专册登记的，按照《麻醉药品和精神药品管理条例》第七十二条的规定，由设区的市级卫生行政部门责令限期改正，给予警告；逾期不改正的，处5000元以上1万元以下的罚款；情节严重的，吊销其印鉴卡；对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职、开除的处分。"},{"i":56,"n":"第五十六条","txt":"医师和药师出现下列情形之一的，由县级以上卫生行政部门按照《麻醉药品和精神药品管理条例》第七十三条的规定予以处罚： （一）未取得麻醉药品和第一类精神药品处方资格的医师擅自开具麻醉药品和第一类精神药品处方的； （二）具有麻醉药品和第一类精神药品处方医师未按照规定开具麻醉药品和第一类精神药品处方，或者未按照卫生部制定的麻醉药品和精神药品临床应用指导原则使用麻醉药品和第一类精神药品的； （三）药师未按照规定调剂麻醉药品、精神药品处方的。"},{"i":57,"n":"第五十七条","txt":"医师出现下列情形之一的，按照《执业医师法》第三十七条的规定，由县级以上卫生行政部门给予警告或者责令暂停六个月以上一年以下执业活动；情节严重的，吊销其执业证书： （一）未取得处方权或者被取消处方权后开具药品处方的； （二）未按照本办法规定开具药品处方的； （三）违反本办法其他规定的。"},{"i":58,"n":"第五十八条","txt":"药师未按照规定调剂处方药品，情节严重的，由县级以上卫生行政部门责令改正、通报批评，给予警告；并由所在医疗机构或者其上级单位给予纪律处分。"},{"i":59,"n":"第五十九条","txt":"县级以上地方卫生行政部门未按照本办法规定履行监管职责的，由上级卫生行政部门责令改正。"},{"i":60,"n":"第六十条","txt":"乡村医生按照《乡村医生从业管理条例》的规定，在省级卫生行政部门制定的乡村医生基本用药目录范围内开具药品处方。"},{"i":61,"n":"第六十一条","txt":"本办法所称药学专业技术人员，是指按照卫生部《卫生技术人员职务试行条例》规定，取得药学专业技术职务任职资格人员，包括主任药师、副主任药师、主管药师、药师、药士。"},{"i":62,"n":"第六十二条","txt":"本办法所称医疗机构，是指按照《医疗机构管理条例》批准登记的从事疾病诊断、治疗活动的医院、社区卫生服务中心（站）、妇幼保健院、卫生院、疗养院、门诊部、诊所、卫生室（所）、急救中心（站）、专科疾病防治院（所、站）以及护理院（站）等医疗机构。"},{"i":63,"n":"第六十三条","txt":"本办法自2007年5月1日起施行。《处方管理办法（试行）》（卫医发〔2004〕269号）和《麻醉药品、精神药品处方管理规定》（卫医法〔2005〕436号）同时废止。"}],"waiguoyishilaihuaduanqixingyizanxingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强外国医师来华短期行医的管理，保障医患双方的合法权益，促进中外医学技术的交流和发展，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称“外国医师来华短期行医”，是指在外国取得合法行医权的外籍医师，应邀、应聘或申请来华从事不超过一年期限的临床诊断、治疗业务活动。"},{"i":3,"n":"第三条","txt":"外国医师来华短期行医必须经过注册，取得《外国医师短期行医许可证》。 《外国医师短期行医许可证》由国家卫生计生委统一印制。"},{"i":4,"n":"第四条","txt":"外国医师来华短期行医，必须有在华医疗机构作为邀请或聘用单位。邀请或聘用单位可以是一个或多个。"},{"i":5,"n":"第五条","txt":"外国医师申请来华短期行医，必须依本办法的规定与聘用单位签订协议。有多个聘用单位的，要分别签订协议。 外国医师应邀、应聘来华短期行医，可以根据情况由双方决定是否签订协议。未签订协议的，所涉及的有关民事责任由邀请或聘用单位承担。"},{"i":6,"n":"第六条","txt":"外国医师来华短期行医的协议书必须包含以下内容： （一）目的； （二）具体项目； （三）地点； （四）时间； （五）责任的承担。"},{"i":7,"n":"第七条","txt":"外国医师可以委托在华的邀请或聘用单位代其办理注册手续。"},{"i":8,"n":"第八条","txt":"外国医师来华短期行医的注册机关为设区的市级以上卫生计生行政部门。"},{"i":9,"n":"第九条","txt":"邀请或聘用单位分别在不同地区的，应当分别向当地设区的市级以上卫生计生行政部门申请注册。"},{"i":10,"n":"第十条","txt":"申请外国医师来华短期行医注册，必须提交下列文件： （一）申请书； （二）外国医师的学位证书； （三）外国行医执照或行医权证明； （四）外国医师的健康证明； （五）邀请或聘用单位证明以及协议书或承担有关民事责任的声明书。 前款（二）、（三）项的内容必须经过公证。"},{"i":11,"n":"第十一条","txt":"注册机关应当在受理申请后30日内进行审核，并将审核结果书面通知申请人或代理申请的单位。对审核合格的予以注册，并发给《外国医师短期行医许可证》。 审核的主要内容包括： （一）有关文字材料的真实性； （二）申请项目的安全性和可靠性； （三）申请项目的先进性和必要性。"},{"i":12,"n":"第十二条","txt":"外国医师来华短期行医注册的有效期不超过一年。 注册期满需要延期的，可以按本办法的规定重新办理注册。"},{"i":13,"n":"第十三条","txt":"外国医师来华短期行医，应当事先依法获得入境签证，入境后按有关规定办理居留或停留手续。"},{"i":14,"n":"第十四条","txt":"外国医师来华短期行医，必须遵守中国的法律法规，尊重中国的风俗习惯。"},{"i":15,"n":"第十五条","txt":"违反本办法第三条规定的，由所在地设区的市级以上卫生计生行政部门予以取缔，没收非法所得，并处以10000元以下罚款；对邀请、聘用或提供场所的单位，处以警告，没收非法所得，并处以5000元以下罚款。"},{"i":16,"n":"第十六条","txt":"违反本办法第十四条规定的，由有关主管机关依法处理。"},{"i":17,"n":"第十七条","txt":"外国医疗团体来华短期行医的，由邀请或合作单位所在地的设区的市级卫生计生行政部门依照本办法的有关规定进行审批。"},{"i":18,"n":"第十八条","txt":"香港、澳门、台湾的医师或医疗团体参照本办法执行。 具有香港或澳门合法行医权的香港或澳门永久性居民在内地短期行医注册的有效期不超过3年。注册期满需要延期的，可以重新办理短期行医注册手续。"},{"i":19,"n":"第十九条","txt":"本办法的解释权在国家卫生计生委。"},{"i":20,"n":"第二十条","txt":"本办法自1993年1月1日起施行。"}],"shitichurujingheshitichulideguanliguiding-2":[{"i":1,"n":"第一条","txt":"为保护社会公共利益，维护社会公共道德，防止传染病由境外传入或者由境内传出，根据《中华人民共和国国境卫生检疫法》、《中华人民共和国海关法》和《殡葬管理条例》等有关法律法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称尸体，是指人去世后的遗体及其标本（含人体器官组织、人体骨骼及其标本）。"},{"i":3,"n":"第三条","txt":"需要入境或者出境对遗体进行殡葬的，应当按照民政部、公安部、外交部、铁道部、交通部、卫生部、海关总署、民用航空局《关于尸体运输管理的若干规定》（民事发〔1993〕2号）和民政部、海关总署、国家出入境检验检疫局《关于遗体运输入出境事宜有关问题的通知》（民事发〔1998〕11号）以及国家其他有关规定，向民政部门、海关、出入境检验检疫机构办理有关殡葬和出入境手续。"},{"i":4,"n":"第四条","txt":"因医学科研需要，由境内运出或者由境外运进尸体，应当按照国务院办公厅转发的《人类遗传资源管理暂行办法》和卫生部、质检总局《关于加强医用特殊物品出入境卫生检疫管理的通知》（卫科教发〔2003〕230号）的规定，办理相关审批手续。"},{"i":5,"n":"第五条","txt":"除第三条、第四条规定情形外，尸体不得由境内运出或者由境外运进。"},{"i":6,"n":"第六条","txt":"对属于殡葬遗体出入境的，出入境检验检疫机构应当对申报资料进行认真核查，并对承运物进行卫生监管，合格者签发《尸体/棺柩/骸骨/骨灰入/出境许可证》。 对因医学科研原因出入境的尸体，出入境检验检疫机构凭中国人类遗传资源管理办公室核发的《人类遗传资源材料出口、出境证明》或者卫生部和省、自治区、直辖市卫生行政部门出具的《医用特殊物品准出入境证明》，按照规定实施卫生检疫审批，并依法实施卫生检疫查验和卫生处理；对符合条件的，签发《出入境货物通关单》。"},{"i":7,"n":"第七条","txt":"申请办理尸体出入境的单位和个人应主动、如实地向海关申报进出口尸体的相关情况，包括尸体来源等，并提交有关进出口证件。 对属于殡葬遗体出入境的，海关凭出入境检验检疫机构签发的《尸体/棺柩/骸骨/骨灰入/出境许可证》办理验放手续。 对属医学科研原因出入境的，海关凭出入境检验检疫机构签发的《出入境货物通关单》办理验放手续；对涉及我国人类遗传资源的出境尸体，海关加验中国人类遗传资源管理办公室核发的《人类遗传资源材料出口、出境证明》。 对经海关查验可能为尸体的，无论是否列入《出入境检验检疫机构实施检验检疫的进出境商品目录》，海关一律验凭出入境检验检疫机构签发的《出入境货物通关单》或者《尸体/棺柩/骸骨/骨灰入/出境许可证》放行。"},{"i":8,"n":"第八条","txt":"严禁进行尸体买卖，严禁利用尸体进行商业性活动。"},{"i":9,"n":"第九条","txt":"除医疗机构、医学院校、医学科研机构以及法医鉴定科研机构因临床、医学教学和科研需要外，任何单位和个人不得接受尸体捐赠。 前款规定情况下使用完毕的尸体，由接受尸体的单位负责对尸体进行殡葬意义上的最终处理。"},{"i":10,"n":"第十条","txt":"违反上述规定的，由有关主管部门按照相关规定查处；构成犯罪的，依法追究刑事责任。"},{"i":11,"n":"第十一条","txt":"本规定由各部门按照各自职责进行解释。"},{"i":12,"n":"第十二条","txt":"本规定自2006年8月1日起施行。"}],"shitichurujingheshitichulideguanliguiding":[{"i":1,"n":"第一条","txt":"为保护社会公共利益，维护社会公共道德，防止传染病由境外传入或者由境内传出，根据《中华人民共和国国境卫生检疫法》、《中华人民共和国海关法》和《殡葬管理条例》等有关法律法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称尸体，是指人去世后的遗体及其标本（含人体器官组织、人体骨骼及其标本）。"},{"i":3,"n":"第三条","txt":"需要入境或者出境对遗体进行殡葬的，应当按照民政部、公安部、外交部、铁道部、交通部、卫生部、海关总署、民用航空局《关于尸体运输管理的若干规定》（民事发〔1993〕2号）和民政部、海关总署、国家出入境检验检疫局《关于遗体运输入出境事宜有关问题的通知》（民事发〔1998〕11号）以及国家其他有关规定，向民政部门、海关、出入境检验检疫机构办理有关殡葬和出入境手续。"},{"i":4,"n":"第四条","txt":"因医学科研需要，由境内运出或者由境外运进尸体，应当按照国务院办公厅转发的《人类遗传资源管理暂行办法》和卫生部、质检总局《关于加强医用特殊物品出入境卫生检疫管理的通知》（卫科教发〔2003〕230号）的规定，办理相关审批手续。"},{"i":5,"n":"第五条","txt":"除第三条、第四条规定情形外，尸体不得由境内运出或者由境外运进。"},{"i":6,"n":"第六条","txt":"对属于殡葬遗体出入境的，出入境检验检疫机构应当对申报资料进行认真核查，并对承运物进行卫生监管，合格者签发《尸体／棺柩／骸骨／骨灰入／出境许可证》。对因医学科研原因出入境的尸体，出入境检验检疫机构凭中国人类遗传资源管理办公室核发的《人类遗传资源材料出口、出境证明》或者卫生部和省、自治区、直辖市卫生行政部门出具的《医用特殊物品准出入境证明》，按照规定实施卫生检疫审批，并依法实施卫生检疫查验和卫生处理；对符合条件的，签发《出入境货物通关单》。"},{"i":7,"n":"第七条","txt":"申请办理尸体出入境的单位和个人应主动、如实地向海关申报进出口尸体的相关情况，包括尸体来源等，并提交有关进出口证件。对属于殡葬遗体出入境的，海关凭出入境检验检疫机构签发的《尸体／棺柩／骸骨／骨灰入／出境许可证》办理验放手续。对属医学科研原因出入境的，海关凭出入境检验检疫机构签发的《出入境货物通关单》办理验放手续；对涉及我国人类遗传资源的出境尸体，海关加验中国人类遗传资源管理办公室核发的《人类遗传资源材料出口、出境证明》。对经海关查验可能为尸体的，无论是否列入《出入境检验检疫机构实施检验检疫的进出境商品目录》，海关一律验凭出入境检验检疫机构签发的《出入境货物通关单》或者《尸体／棺柩／骸骨／骨灰入／出境许可证》放行。"},{"i":8,"n":"第八条","txt":"严禁进行尸体买卖，严禁利用尸体进行商业性活动。"},{"i":9,"n":"第九条","txt":"除医疗机构、医学院校、医学科研机构以及法医鉴定科研机构因临床、医学教学和科研需要外，任何单位和个人不得接受尸体捐赠。前款规定情况下使用完毕的尸体，由接受尸体的单位负责对尸体进行殡葬意义上的最终处理。"},{"i":10,"n":"第十条","txt":"违反上述规定的，由有关主管部门按照相关规定查处；构成犯罪的，依法追究刑事责任。"},{"i":11,"n":"第十一条","txt":"本规定由各部门按照各自职责进行解释。"},{"i":12,"n":"第十二条","txt":"本规定自2006年8月1日起施行。"}],"gongzuochangsuozhiyeweishengguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强职业卫生管理工作，强化用人单位职业病防治的主体责任，预防、控制职业病危害，保障劳动者健康和相关权益，根据《中华人民共和国职业病防治法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"用人单位的职业病防治和卫生健康主管部门对其实施监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"用人单位应当加强职业病防治工作，为劳动者提供符合法律、法规、规章、国家职业卫生标准和卫生要求的工作环境和条件，并采取有效措施保障劳动者的职业健康。"},{"i":4,"n":"第四条","txt":"用人单位是职业病防治的责任主体，并对本单位产生的职业病危害承担责任。 用人单位的主要负责人对本单位的职业病防治工作全面负责。"},{"i":5,"n":"第五条","txt":"国家卫生健康委依照《中华人民共和国职业病防治法》和国务院规定的职责，负责全国用人单位职业卫生的监督管理工作。 县级以上地方卫生健康主管部门依照《中华人民共和国职业病防治法》和本级人民政府规定的职责，负责本行政区域内用人单位职业卫生的监督管理工作。"},{"i":6,"n":"第六条","txt":"为职业病防治提供技术服务的职业卫生技术服务机构，应当依照国家有关职业卫生技术服务机构管理的相关法律法规及标准、规范的要求，为用人单位提供技术服务。"},{"i":7,"n":"第七条","txt":"任何单位和个人均有权向卫生健康主管部门举报用人单位违反本规定的行为和职业病危害事故。"},{"i":8,"n":"第八条","txt":"职业病危害严重的用人单位，应当设置或者指定职业卫生管理机构或者组织，配备专职职业卫生管理人员。 其他存在职业病危害的用人单位，劳动者超过一百人的，应当设置或者指定职业卫生管理机构或者组织，配备专职职业卫生管理人员；劳动者在一百人以下的，应当配备专职或者兼职的职业卫生管理人员，负责本单位的职业病防治工作。"},{"i":9,"n":"第九条","txt":"用人单位的主要负责人和职业卫生管理人员应当具备与本单位所从事的生产经营活动相适应的职业卫生知识和管理能力，并接受职业卫生培训。 对用人单位主要负责人、职业卫生管理人员的职业卫生培训，应当包括下列主要内容： （一）职业卫生相关法律、法规、规章和国家职业卫生标准； （二）职业病危害预防和控制的基本知识； （三）职业卫生管理相关知识； （四）国家卫生健康委规定的其他内容。"},{"i":10,"n":"第十条","txt":"用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及职业卫生知识，督促劳动者遵守职业病防治的法律、法规、规章、国家职业卫生标准和操作规程。 用人单位应当对职业病危害严重的岗位的劳动者，进行专门的职业卫生培训，经培训合格后方可上岗作业。 因变更工艺、技术、设备、材料，或者岗位调整导致劳动者接触的职业病危害因素发生变化的，用人单位应当重新对劳动者进行上岗前的职业卫生培训。"},{"i":11,"n":"第十一条","txt":"存在职业病危害的用人单位应当制定职业病危害防治计划和实施方案，建立、健全下列职业卫生管理制度和操作规程： （一）职业病危害防治责任制度； （二）职业病危害警示与告知制度； （三）职业病危害项目申报制度； （四）职业病防治宣传教育培训制度； （五）职业病防护设施维护检修制度； （六）职业病防护用品管理制度； （七）职业病危害监测及评价管理制度； （八）建设项目职业病防护设施“三同时”管理制度； （九）劳动者职业健康监护及其档案管理制度； （十）职业病危害事故处置与报告制度； （十一）职业病危害应急救援与管理制度； （十二）岗位职业卫生操作规程； （十三）法律、法规、规章规定的其他职业病防治制度。"},{"i":12,"n":"第十二条","txt":"产生职业病危害的用人单位的工作场所应当符合下列基本要求： （一）生产布局合理，有害作业与无害作业分开； （二）工作场所与生活场所分开，工作场所不得住人； （三）有与职业病防治工作相适应的有效防护设施； （四）职业病危害因素的强度或者浓度符合国家职业卫生标准； （五）有配套的更衣间、洗浴间、孕妇休息间等卫生设施； （六）设备、工具、用具等设施符合保护劳动者生理、心理健康的要求； （七）法律、法规、规章和国家职业卫生标准的其他规定。"},{"i":13,"n":"第十三条","txt":"用人单位工作场所存在职业病目录所列职业病的危害因素的，应当按照《职业病危害项目申报办法》的规定，及时、如实向所在地卫生健康主管部门申报职业病危害项目，并接受卫生健康主管部门的监督检查。"},{"i":14,"n":"第十四条","txt":"新建、改建、扩建的工程建设项目和技术改造、技术引进项目（以下统称建设项目）可能产生职业病危害的，建设单位应当按照国家有关建设项目职业病防护设施“三同时”监督管理的规定，进行职业病危害预评价、职业病防护设施设计、职业病危害控制效果评价及相应的评审，组织职业病防护设施验收。"},{"i":15,"n":"第十五条","txt":"产生职业病危害的用人单位，应当在醒目位置设置公告栏，公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施和工作场所职业病危害因素检测结果。 存在或者产生职业病危害的工作场所、作业岗位、设备、设施，应当按照《工作场所职业病危害警示标识》（GBZ158）的规定，在醒目位置设置图形、警示线、警示语句等警示标识和中文警示说明。警示说明应当载明产生职业病危害的种类、后果、预防和应急处置措施等内容。 存在或者产生高毒物品的作业岗位，应当按照《高毒物品作业岗位职业病危害告知规范》（GBZ/T203）的规定，在醒目位置设置高毒物品告知卡，告知卡应当载明高毒物品的名称、理化特性、健康危害、防护措施及应急处理等告知内容与警示标识。"},{"i":16,"n":"第十六条","txt":"用人单位应当为劳动者提供符合国家职业卫生标准的职业病防护用品，并督促、指导劳动者按照使用规则正确佩戴、使用，不得发放钱物替代发放职业病防护用品。 用人单位应当对职业病防护用品进行经常性的维护、保养，确保防护用品有效，不得使用不符合国家职业卫生标准或者已经失效的职业病防护用品。"},{"i":17,"n":"第十七条","txt":"在可能发生急性职业损伤的有毒、有害工作场所，用人单位应当设置报警装置，配置现场急救用品、冲洗设备、应急撤离通道和必要的泄险区。 现场急救用品、冲洗设备等应当设在可能发生急性职业损伤的工作场所或者临近地点，并在醒目位置设置清晰的标识。 在可能突然泄漏或者逸出大量有害物质的密闭或者半密闭工作场所，除遵守本条第一款、第二款规定外，用人单位还应当安装事故通风装置以及与事故排风系统相连锁的泄漏报警装置。 生产、销售、使用、贮存放射性同位素和射线装置的场所，应当按照国家有关规定设置明显的放射性标志，其入口处应当按照国家有关安全和防护标准的要求，设置安全和防护设施以及必要的防护安全联锁、报警装置或者工作信号。放射性装置的生产调试和使用场所，应当具有防止误操作、防止工作人员受到意外照射的安全措施。用人单位必须配备与辐射类型和辐射水平相适应的防护用品和监测仪器，包括个人剂量测量报警、固定式和便携式辐射监"},{"i":18,"n":"第十八条","txt":"用人单位应当对职业病防护设备、应急救援设施进行经常性的维护、检修和保养，定期检测其性能和效果，确保其处于正常状态，不得擅自拆除或者停止使用。"},{"i":19,"n":"第十九条","txt":"存在职业病危害的用人单位，应当实施由专人负责的工作场所职业病危害因素日常监测，确保监测系统处于正常工作状态。"},{"i":20,"n":"第二十条","txt":"职业病危害严重的用人单位，应当委托具有相应资质的职业卫生技术服务机构，每年至少进行一次职业病危害因素检测，每三年至少进行一次职业病危害现状评价。 职业病危害一般的用人单位，应当委托具有相应资质的职业卫生技术服务机构，每三年至少进行一次职业病危害因素检测。 检测、评价结果应当存入本单位职业卫生档案，并向卫生健康主管部门报告和劳动者公布。"},{"i":21,"n":"第二十一条","txt":"存在职业病危害的用人单位发生职业病危害事故或者国家卫生健康委规定的其他情形的，应当及时委托具有相应资质的职业卫生技术服务机构进行职业病危害现状评价。 用人单位应当落实职业病危害现状评价报告中提出的建议和措施，并将职业病危害现状评价结果及整改情况存入本单位职业卫生档案。"},{"i":22,"n":"第二十二条","txt":"用人单位在日常的职业病危害监测或者定期检测、现状评价过程中，发现工作场所职业病危害因素不符合国家职业卫生标准和卫生要求时，应当立即采取相应治理措施，确保其符合职业卫生环境和条件的要求；仍然达不到国家职业卫生标准和卫生要求的，必须停止存在职业病危害因素的作业；职业病危害因素经治理后，符合国家职业卫生标准和卫生要求的，方可重新作业。"},{"i":23,"n":"第二十三条","txt":"向用人单位提供可能产生职业病危害的设备的，应当提供中文说明书，并在设备的醒目位置设置警示标识和中文警示说明。警示说明应当载明设备性能、可能产生的职业病危害、安全操作和维护注意事项、职业病防护措施等内容。 用人单位应当检查前款规定的事项，不得使用不符合要求的设备。"},{"i":24,"n":"第二十四条","txt":"向用人单位提供可能产生职业病危害的化学品、放射性同位素和含有放射性物质的材料的，应当提供中文说明书。说明书应当载明产品特性、主要成份、存在的有害因素、可能产生的危害后果、安全使用注意事项、职业病防护和应急救治措施等内容。产品包装应当有醒目的警示标识和中文警示说明。贮存上述材料的场所应当在规定的部位设置危险物品标识或者放射性警示标识。 用人单位应当检查前款规定的事项，不得使用不符合要求的材料。"},{"i":25,"n":"第二十五条","txt":"任何用人单位不得使用国家明令禁止使用的可能产生职业病危害的设备或者材料。"},{"i":26,"n":"第二十六条","txt":"任何单位和个人不得将产生职业病危害的作业转移给不具备职业病防护条件的单位和个人。不具备职业病防护条件的单位和个人不得接受产生职业病危害的作业。"},{"i":27,"n":"第二十七条","txt":"用人单位应当优先采用有利于防治职业病危害和保护劳动者健康的新技术、新工艺、新材料、新设备，逐步替代产生职业病危害的技术、工艺、材料、设备。"},{"i":28,"n":"第二十八条","txt":"用人单位对采用的技术、工艺、材料、设备，应当知悉其可能产生的职业病危害，并采取相应的防护措施。对有职业病危害的技术、工艺、设备、材料，故意隐瞒其危害而采用的，用人单位对其所造成的职业病危害后果承担责任。"},{"i":29,"n":"第二十九条","txt":"用人单位与劳动者订立劳动合同时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在履行劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。 用人单位违反本条规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。"},{"i":30,"n":"第三十条","txt":"对从事接触职业病危害因素作业的劳动者，用人单位应当按照《用人单位职业健康监护监督管理办法》、《放射工作人员职业健康管理办法》、《职业健康监护技术规范》（GBZ188）、《放射工作人员职业健康监护技术规范》（GBZ235）等有关规定组织上岗前、在岗期间、离岗时的职业健康检查，并将检查结果书面如实告知劳动者。 职业健康检查费用由用人单位承担。"},{"i":31,"n":"第三十一条","txt":"用人单位应当按照《用人单位职业健康监护监督管理办法》的规定，为劳动者建立职业健康监护档案，并按照规定的期限妥善保存。 职业健康监护档案应当包括劳动者的职业史、职业病危害接触史、职业健康检查结果、处理结果和职业病诊疗等有关个人健康资料。 劳动者离开用人单位时，有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章。"},{"i":32,"n":"第三十二条","txt":"劳动者健康出现损害需要进行职业病诊断、鉴定的，用人单位应当如实提供职业病诊断、鉴定所需的劳动者职业史和职业病危害接触史、工作场所职业病危害因素检测结果和放射工作人员个人剂量监测结果等资料。"},{"i":33,"n":"第三十三条","txt":"用人单位不得安排未成年工从事接触职业病危害的作业，不得安排有职业禁忌的劳动者从事其所禁忌的作业，不得安排孕期、哺乳期女职工从事对本人和胎儿、婴儿有危害的作业。"},{"i":34,"n":"第三十四条","txt":"用人单位应当建立健全下列职业卫生档案资料： （一）职业病防治责任制文件； （二）职业卫生管理规章制度、操作规程； （三）工作场所职业病危害因素种类清单、岗位分布以及作业人员接触情况等资料； （四）职业病防护设施、应急救援设施基本信息，以及其配置、使用、维护、检修与更换等记录； （五）工作场所职业病危害因素检测、评价报告与记录； （六）职业病防护用品配备、发放、维护与更换等记录； （七）主要负责人、职业卫生管理人员和职业病危害严重工作岗位的劳动者等相关人员职业卫生培训资料； （八）职业病危害事故报告与应急处置记录； （九）劳动者职业健康检查结果汇总资料，存在职业禁忌证、职业健康损害或者职业病的劳动者处理和安置情况记录； （十）建设项目职业病防护设施“三同时”有关资料； （十一）职业病危害项目申报等有关回执或者批复文件； （十二）其他有关职业卫生管理的资料或者文件。"},{"i":35,"n":"第三十五条","txt":"用人单位发生职业病危害事故，应当及时向所在地卫生健康主管部门和有关部门报告，并采取有效措施，减少或者消除职业病危害因素，防止事故扩大。对遭受或者可能遭受急性职业病危害的劳动者，用人单位应当及时组织救治、进行健康检查和医学观察，并承担所需费用。 用人单位不得故意破坏事故现场、毁灭有关证据，不得迟报、漏报、谎报或者瞒报职业病危害事故。"},{"i":36,"n":"第三十六条","txt":"用人单位发现职业病病人或者疑似职业病病人时，应当按照国家规定及时向所在地卫生健康主管部门和有关部门报告。"},{"i":37,"n":"第三十七条","txt":"用人单位在卫生健康主管部门行政执法人员依法履行监督检查职责时，应当予以配合，不得拒绝、阻挠。"},{"i":38,"n":"第三十八条","txt":"卫生健康主管部门应当依法对用人单位执行有关职业病防治的法律、法规、规章和国家职业卫生标准的情况进行监督检查，重点监督检查下列内容： （一）设置或者指定职业卫生管理机构或者组织，配备专职或者兼职的职业卫生管理人员情况； （二）职业卫生管理制度和操作规程的建立、落实及公布情况； （三）主要负责人、职业卫生管理人员和职业病危害严重的工作岗位的劳动者职业卫生培训情况； （四）建设项目职业病防护设施“三同时”制度落实情况； （五）工作场所职业病危害项目申报情况； （六）工作场所职业病危害因素监测、检测、评价及结果报告和公布情况； （七）职业病防护设施、应急救援设施的配置、维护、保养情况，以及职业病防护用品的发放、管理及劳动者佩戴使用情况； （八）职业病危害因素及危害后果警示、告知情况； （九）劳动者职业健康监护、放射工作人员个人剂量监测情况； （十）职业病危害事故报告情况； （十一）提供劳动者健"},{"i":39,"n":"第三十九条","txt":"卫生健康主管部门应当建立健全职业卫生监督检查制度，加强行政执法人员职业卫生知识的培训，提高行政执法人员的业务素质。"},{"i":40,"n":"第四十条","txt":"卫生健康主管部门应当加强建设项目职业病防护设施“三同时”的监督管理，建立健全相关资料的档案管理制度。"},{"i":41,"n":"第四十一条","txt":"卫生健康主管部门应当加强职业卫生技术服务机构的资质认可管理和技术服务工作的监督检查，督促职业卫生技术服务机构公平、公正、客观、科学地开展职业卫生技术服务。"},{"i":42,"n":"第四十二条","txt":"卫生健康主管部门应当建立健全职业病危害防治信息统计分析制度，加强对用人单位职业病危害因素检测、评价结果、劳动者职业健康监护信息以及职业卫生监督检查信息等资料的统计、汇总和分析。"},{"i":43,"n":"第四十三条","txt":"卫生健康主管部门应当按照有关规定，支持、配合有关部门和机构开展职业病的诊断、鉴定工作。"},{"i":44,"n":"第四十四条","txt":"卫生健康主管部门行政执法人员依法履行监督检查职责时，应当出示有效的执法证件。 行政执法人员应当忠于职守，秉公执法，严格遵守执法规范；涉及被检查单位的技术秘密、业务秘密以及个人隐私的，应当为其保密。"},{"i":45,"n":"第四十五条","txt":"卫生健康主管部门履行监督检查职责时，有权采取下列措施： （一）进入被检查单位及工作场所，进行职业病危害检测，了解情况，调查取证； （二）查阅、复制被检查单位有关职业病危害防治的文件、资料，采集有关样品； （三）责令违反职业病防治法律、法规的单位和个人停止违法行为； （四）责令暂停导致职业病危害事故的作业，封存造成职业病危害事故或者可能导致职业病危害事故发生的材料和设备； （五）组织控制职业病危害事故现场。 在职业病危害事故或者危害状态得到有效控制后，卫生健康主管部门应当及时解除前款第四项、第五项规定的控制措施。"},{"i":46,"n":"第四十六条","txt":"发生职业病危害事故，卫生健康主管部门应当依照国家有关规定报告事故和组织事故的调查处理。"},{"i":47,"n":"第四十七条","txt":"用人单位有下列情形之一的，责令限期改正，给予警告，可以并处五千元以上二万元以下的罚款： （一）未按照规定实行有害作业与无害作业分开、工作场所与生活场所分开的； （二）用人单位的主要负责人、职业卫生管理人员未接受职业卫生培训的； （三）其他违反本规定的行为。"},{"i":48,"n":"第四十八条","txt":"用人单位有下列情形之一的，责令限期改正，给予警告；逾期未改正的，处十万元以下的罚款： （一）未按照规定制定职业病防治计划和实施方案的； （二）未按照规定设置或者指定职业卫生管理机构或者组织，或者未配备专职或者兼职的职业卫生管理人员的； （三）未按照规定建立、健全职业卫生管理制度和操作规程的； （四）未按照规定建立、健全职业卫生档案和劳动者健康监护档案的； （五）未建立、健全工作场所职业病危害因素监测及评价制度的； （六）未按照规定公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施的； （七）未按照规定组织劳动者进行职业卫生培训，或者未对劳动者个体防护采取有效的指导、督促措施的； （八）工作场所职业病危害因素检测、评价结果未按照规定存档、上报和公布的。"},{"i":49,"n":"第四十九条","txt":"用人单位有下列情形之一的，责令限期改正，给予警告，可以并处五万元以上十万元以下的罚款： （一）未按照规定及时、如实申报产生职业病危害的项目的； （二）未实施由专人负责职业病危害因素日常监测，或者监测系统不能正常监测的； （三）订立或者变更劳动合同时，未告知劳动者职业病危害真实情况的； （四）未按照规定组织劳动者进行职业健康检查、建立职业健康监护档案或者未将检查结果书面告知劳动者的； （五）未按照规定在劳动者离开用人单位时提供职业健康监护档案复印件的。"},{"i":50,"n":"第五十条","txt":"用人单位有下列情形之一的，责令限期改正，给予警告；逾期未改正的，处五万元以上二十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）工作场所职业病危害因素的强度或者浓度超过国家职业卫生标准的； （二）未提供职业病防护设施和劳动者使用的职业病防护用品，或者提供的职业病防护设施和劳动者使用的职业病防护用品不符合国家职业卫生标准和卫生要求的； （三）未按照规定对职业病防护设备、应急救援设施和劳动者职业病防护用品进行维护、检修、检测，或者不能保持正常运行、使用状态的； （四）未按照规定对工作场所职业病危害因素进行检测、现状评价的； （五）工作场所职业病危害因素经治理仍然达不到国家职业卫生标准和卫生要求时，未停止存在职业病危害因素的作业的； （六）发生或者可能发生急性职业病危害事故，未立即采取应急救援和控制措施或者未按照规定及时报告"},{"i":51,"n":"第五十一条","txt":"用人单位有下列情形之一的，依法责令限期改正，并处五万元以上三十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）隐瞒技术、工艺、设备、材料所产生的职业病危害而采用的； （二）隐瞒本单位职业卫生真实情况的； （三）可能发生急性职业损伤的有毒、有害工作场所或者放射工作场所不符合法律有关规定的； （四）使用国家明令禁止使用的可能产生职业病危害的设备或者材料的； （五）将产生职业病危害的作业转移给没有职业病防护条件的单位和个人，或者没有职业病防护条件的单位和个人接受产生职业病危害的作业的； （六）擅自拆除、停止使用职业病防护设备或者应急救援设施的； （七）安排未经职业健康检查的劳动者、有职业禁忌的劳动者、未成年工或者孕期、哺乳期女职工从事接触产生职业病危害的作业或者禁忌作业的； （八）违章指挥和强令劳动者进行没有职业病防护措施的"},{"i":52,"n":"第五十二条","txt":"用人单位违反《中华人民共和国职业病防治法》的规定，已经对劳动者生命健康造成严重损害的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭，并处十万元以上五十万元以下的罚款。 造成重大职业病危害事故或者其他严重后果，构成犯罪的，对直接负责的主管人员和其他直接责任人员，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"向用人单位提供可能产生职业病危害的设备或者材料，未按照规定提供中文说明书或者设置警示标识和中文警示说明的，责令限期改正，给予警告，并处五万元以上二十万元以下的罚款。"},{"i":54,"n":"第五十四条","txt":"用人单位未按照规定报告职业病、疑似职业病的，责令限期改正，给予警告，可以并处一万元以下的罚款；弄虚作假的，并处二万元以上五万元以下的罚款。"},{"i":55,"n":"第五十五条","txt":"卫生健康主管部门及其行政执法人员未按照规定报告职业病危害事故的，依照有关规定给予处理；构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"本规定所规定的行政处罚，由县级以上地方卫生健康主管部门决定。法律、行政法规和国务院有关规定对行政处罚决定机关另有规定的，依照其规定。"},{"i":57,"n":"第五十七条","txt":"本规定下列用语的含义： 工作场所，是指劳动者进行职业活动的所有地点，包括建设单位施工场所。 职业病危害严重的用人单位，是指建设项目职业病危害风险分类管理目录中所列职业病危害严重行业的用人单位。建设项目职业病危害风险分类管理目录由国家卫生健康委公布。各省级卫生健康主管部门可以根据本地区实际情况，对分类管理目录作出补充规定。 建设项目职业病防护设施“三同时”，是指建设项目的职业病防护设施与主体工程同时设计、同时施工、同时投入生产和使用。"},{"i":58,"n":"第五十八条","txt":"本规定未规定的其他有关职业病防治事项，依照《中华人民共和国职业病防治法》和其他有关法律、法规、规章的规定执行。"},{"i":59,"n":"第五十九条","txt":"医疗机构放射卫生管理按照放射诊疗管理相关规定执行。"},{"i":60,"n":"第六十条","txt":"本规定自2021年2月1日起施行。原国家安全生产监督管理总局2012年4月27日公布的《工作场所职业卫生监督管理规定》同时废止。"}],"xingbingfangzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为预防、控制性病的传播流行，保护人体健康，根据《中华人民共和国传染病防治法》(以下简称《传染病防治法》)和《艾滋病防治条例》有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"性病是以性接触为主要传播途径的疾病。本办法所称性病包括以下几类： (一)《传染病防治法》规定的乙类传染病中的梅毒和淋病; (二)生殖道沙眼衣原体感染、尖锐湿疣、生殖器疱疹; (三)卫生部根据疾病危害程度、流行情况等因素，确定需要管理的其他性病。 艾滋病防治管理工作依照《艾滋病防治条例》的有关规定执行。"},{"i":3,"n":"第三条","txt":"性病防治坚持预防为主、防治结合的方针，遵循依法防治、科学管理、分级负责、专业指导、部门合作、社会参与的原则。"},{"i":4,"n":"第四条","txt":"性病防治工作与艾滋病防治工作相结合，将性病防治工作纳入各级艾滋病防治工作协调机制，整合防治资源，实行性病艾滋病综合防治。"},{"i":5,"n":"第五条","txt":"卫生部负责全国性病防治工作。根据需要制定国家性病防治规划;确定需要管理的性病目录，决定并公布需要列入乙类、丙类传染病管理的性病病种。 县级以上地方卫生行政部门负责本行政区域内性病防治工作，依照本办法和国家性病防治规划，结合当地性病流行情况和防治需求，制定并组织实施本行政区域性病防治计划。 卫生行政部门应当在同级人民政府的领导下，建立和完善性病防治管理和服务体系，将性病防治工作逐步纳入基本公共卫生服务内容;加强性病防治队伍建设，负责安排性病防治所需经费，组织开展性病防治工作。"},{"i":6,"n":"第六条","txt":"卫生行政部门应当鼓励和支持社会组织参与性病防治工作，开展宣传教育、行为干预、心理支持和社会关怀等活动。 鼓励和支持医疗卫生、科研等相关机构开展性病防治工作研究和学术交流，参加性病防治公益活动。"},{"i":7,"n":"第七条","txt":"医学院校、医务人员培训机构和医学考试机构，应当将性病防治政策和知识等纳入医学院校教育、住院医师培训、继续教育等各类培训以及医学考试的内容。"},{"i":8,"n":"第八条","txt":"任何单位和个人不得歧视性病患者及其家属。性病患者就医、入学、就业、婚育等合法权益受法律保护。"},{"i":9,"n":"第九条","txt":"卫生行政部门应当根据当地性病防治工作需求，指定承担性病防治任务的疾病预防控制机构，合理规划开展性病诊疗业务的医疗机构。"},{"i":10,"n":"第十条","txt":"中国疾病预防控制中心在性病防治中的职责是： (一)协助卫生部制定全国性病防治规划; (二)指导全国性病防治工作，开展性病监测、疫情分析及管理、培训督导、防治效果评估等工作; (三)组织制定和完善性病实验室检测等技术规范，开展性病实验室质量管理，定期开展性病诊断试剂临床应用质量评价。"},{"i":11,"n":"第十一条","txt":"省级、设区的市和县级疾病预防控制机构在性病防治中的职责是： (一)组织有关机构和专家，协助同级卫生行政部门制定本行政区域性病防治计划，开展性病的监测、流行病学调查、疫情分析及管理、培训督导等工作; (二)组织并指导下级疾病预防控制机构和社会组织开展性病防治宣传教育、有易感染性病危险行为的人群干预工作; (三)组织开展本行政区域性病实验室质量管理。"},{"i":12,"n":"第十二条","txt":"医疗机构应当积极提供性病诊疗服务，方便患者就医。 医疗机构开展性病诊疗业务应当取得与性传播疾病诊疗相关的诊疗科目，确定相应科室，并应当具备以下条件： (一)具有相应的诊疗场所，包括诊室、治疗室和检验科等; (二)具备性病诊断治疗、消毒灭菌所必需的设备、设施及药品等; (三)具有依法取得执业资格，并经性病诊疗培训考核合格的人员。"},{"i":13,"n":"第十三条","txt":"开展性病诊疗业务的医疗机构职责是： (一)根据性病诊断标准和技术规范对性病患者或者疑似病人进行诊断治疗，并按照规定报告疫情; (二)开展性病防治知识宣传、健康教育、咨询和必要的干预; (三)协助卫生行政部门开展性病诊疗业务培训; (四)开展实验室检测质量控制; (五)协助疾病预防控制机构开展性病疫情漏报调查和流行病学调查等工作。"},{"i":14,"n":"第十四条","txt":"省级卫生行政部门应当定期组织从事性病诊断治疗和预防控制工作的专业人员进行岗位培训，并进行考核。 卫生行政部门和行业学会开展对皮肤科、妇产科、泌尿外科等相关学科医师的培训，应当包括性病防治知识和专业技术培训内容。"},{"i":15,"n":"第十五条","txt":"医疗机构人员开展性病诊疗业务，应当依法取得执业资格，并应当定期接受性病防治知识和专业技术岗位培训。 疾病预防控制机构的人员开展性病预防控制工作，应当定期接受性病防治知识和专业技术岗位培训。"},{"i":16,"n":"第十六条","txt":"县级以上地方卫生行政部门应当及时公布取得与性传播疾病诊疗相关科目的医疗机构信息。 开展性病诊疗业务的医疗机构发布有关医疗广告应当依法进行。"},{"i":17,"n":"第十七条","txt":"疾病预防控制机构和开展性病诊疗业务的医疗机构应当根据当地性病流行特点，确定性病宣传和健康教育内容，对大众开展性病防治知识的宣传。"},{"i":18,"n":"第十八条","txt":"各级疾病预防控制机构应当通过多种形式在有易感染性病危险行为的人群集中的场所宣传性病防治知识，倡导安全性行为，鼓励有易感染性病危险行为的人群定期到具备性病诊疗资质的医疗机构进行性病检查。"},{"i":19,"n":"第十九条","txt":"开展性病诊疗业务的医疗机构应当为性病就诊者提供性病和生殖健康教育、咨询检测以及其他疾病的转诊服务。"},{"i":20,"n":"第二十条","txt":"基层医疗卫生机构和开展性病防治工作的社会组织，应当在当地卫生行政部门的统一规划和疾病预防控制机构的指导下，对有易感染性病危险行为的人群开展性病、生殖健康知识宣传和行为干预，提供咨询等服务。"},{"i":21,"n":"第二十一条","txt":"艾滋病自愿咨询检测机构和社区药物维持治疗门诊应当将梅毒免费咨询检测纳入日常服务内容;对咨询检测中发现的梅毒阳性患者，应当告知其到开展性病诊疗业务的医疗机构就诊。"},{"i":22,"n":"第二十二条","txt":"开展妇幼保健和助产服务的医疗机构应当对孕产妇进行梅毒筛查检测、咨询、必要的诊疗或者转诊服务，预防先天梅毒的发生。"},{"i":23,"n":"第二十三条","txt":"性病患者应当采取必要的防护措施，防止感染他人，不得以任何方式故意传播性病。"},{"i":24,"n":"第二十四条","txt":"性病流行严重的地区，卫生行政部门可以根据当地情况，对特定人群采取普查普治的防治措施。"},{"i":25,"n":"第二十五条","txt":"开展性病诊疗业务的医疗机构，应当实行首诊医师负责制，建立门诊日志，对就诊者逐例登记，对有可能感染性病或者具有性病可疑症状、体征的就诊者应当及时进行相关性病检查，不得以任何理由推诿。当性病患者存在严重危及健康和生命的伴随疾病，可以转诊至伴随疾病的专科诊治，并给予性病诊治支持。 不具备开展性病诊疗条件的医疗机构或者科室，在诊治、体检、筛查活动中发现疑似或者确诊的性病患者时，应当及时转诊至具备性病诊疗条件的医疗机构或者科室处置。当患者存在严重危及健康和生命的伴随疾病，可以安排在伴随疾病的专科继续诊治，开展性病诊疗业务的医疗机构或者科室应当给予性病诊治支持。"},{"i":26,"n":"第二十六条","txt":"医疗机构及其医务人员对就诊者进行性病相关检查时，应当遵循知情同意的原则。"},{"i":27,"n":"第二十七条","txt":"开展性病诊疗业务的医疗机构，应当按照安全、有效、经济、方便的原则提供性病治疗服务，优先使用基本药物。 开展性病诊疗业务的医疗机构，应当公示诊疗、检验及药品、医疗器械等服务价格，按照有关规定收费。 性病治疗基本用药纳入基本药物目录并逐步提高报销比例，性病基本诊疗服务费用纳入报销范围。"},{"i":28,"n":"第二十八条","txt":"开展性病诊疗业务的医务人员，应当严格按照卫生部发布的性病诊断标准及相关规范的要求，采集完整病史，进行体格检查、临床检验和诊断治疗。"},{"i":29,"n":"第二十九条","txt":"开展性病诊疗业务的医务人员，应当规范书写病历，准确填报传染病报告卡报告疫情，对性病患者进行复查，提供健康教育与咨询等预防服务，并予以记录。"},{"i":30,"n":"第三十条","txt":"开展性病诊疗业务的医务人员，应当告知性病患者及早通知与其有性关系者及时就医。"},{"i":31,"n":"第三十一条","txt":"开展性病诊疗业务并提供孕产期保健和助产服务的医疗机构，应当按照国家推荐方案及时为感染梅毒的孕产妇提供治疗，并为其婴幼儿提供必要的预防性治疗、随访、梅毒相关检测服务等。对确诊的先天梅毒的患儿根据国家推荐治疗方案给予治疗或者转诊。"},{"i":32,"n":"第三十二条","txt":"开展性病诊疗业务的医疗机构进行性病临床检验，应当制定检验标准操作和质量控制程序，按照技术规范进行检验和结果报告，参加性病实验室间质量评价，加强实验室生物安全管理。"},{"i":33,"n":"第三十三条","txt":"医疗机构应当采取措施预防性病的医源性感染，加强医务人员的职业安全防护。"},{"i":34,"n":"第三十四条","txt":"中国疾病预防控制中心制定全国性病监测方案。省级疾病预防控制机构根据全国性病监测方案和本地性病疫情，制定本行政区域的性病监测实施方案;组织开展性病监测和专题调查，了解不同人群性病发病特点和流行趋势。"},{"i":35,"n":"第三十五条","txt":"开展性病诊疗业务的医疗机构是性病疫情责任报告单位，开展性病诊疗的医务人员是性病疫情责任报告人。 性病疫情责任报告单位应当建立健全性病疫情登记和报告制度;性病疫情责任报告人发现应当报告的性病病例时，应当按照要求及时报告疫情。"},{"i":36,"n":"第三十六条","txt":"开展性病诊疗业务的医疗机构应当结合流行病学史、临床表现和实验室检验结果等做出诊断，按照规定进行疫情报告，不得隐瞒、谎报、缓报疫情。 艾滋病自愿咨询检测机构和社区药物维持治疗门诊应当按照要求收集和上报相关信息。 医疗卫生机构不得泄露性病患者涉及个人隐私的有关信息、资料。"},{"i":37,"n":"第三十七条","txt":"各级卫生行政部门负责本行政区域内性病疫情报告网络建设，为网络的正常运行提供必要的保障条件。"},{"i":38,"n":"第三十八条","txt":"疾病预防控制机构负责本行政区域内性病疫情信息报告的业务管理和技术指导工作，对性病疫情信息进行收集、核实、分析、报告和反馈，预测疫情趋势，对疫情信息报告质量进行检查。"},{"i":39,"n":"第三十九条","txt":"卫生部负责对全国性病防治工作进行监督管理，组织开展性病防治工作绩效考核和效果评估。"},{"i":40,"n":"第四十条","txt":"县级以上地方卫生行政部门负责对本行政区域内性病防治工作进行监督管理，定期开展性病防治工作绩效考核与督导检查。督导检查内容包括： (一)疾病预防控制机构性病防治工作职责落实情况; (二)开展性病诊疗业务的医疗机构工作职责落实情况; (三)不具备开展性病诊疗资质的医疗机构发现疑似性病患者的转诊情况; (四)疾病预防控制机构与开展性病诊疗业务的医疗机构性病防治培训情况。"},{"i":41,"n":"第四十一条","txt":"卫生行政部门对开展性病诊疗服务的医疗机构进行校验和评审时，应当将性病诊治情况列入校验和评审内容。"},{"i":42,"n":"第四十二条","txt":"卫生行政部门应当受理个人或者组织对违反本办法行为的举报，并依法进行处理。"},{"i":43,"n":"第四十三条","txt":"卫生行政部门工作人员依法进行监督检查时，应当出示证件;被检查单位应当予以配合，如实反映情况，提供必要的资料，不得拒绝、阻碍或者隐瞒。"},{"i":44,"n":"第四十四条","txt":"疾病预防控制机构和开展性病诊疗业务的医疗机构应当加强本机构性病防治工作管理，对违反本办法规定的本机构工作人员，应当根据情节轻重，给予批评教育或者相应的纪律处分。"},{"i":45,"n":"第四十五条","txt":"县级以上卫生行政部门对督导检查中发现的或者接到举报查实的违反本办法的行为，应当依法及时予以纠正和处理;对工作不力、管理不规范的医疗卫生机构及其工作人员，应当予以通报批评;对负有责任的主管人员和其他直接责任人员，可以根据情节依法给予处分。"},{"i":46,"n":"第四十六条","txt":"县级以上卫生行政部门违反本办法规定，造成性病疫情传播扩散的，按照《传染病防治法》的有关规定进行处理;构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"未取得《医疗机构执业许可证》擅自开展性病诊疗活动的，按照《医疗机构管理条例》的有关规定进行处理。"},{"i":48,"n":"第四十八条","txt":"医疗机构违反本办法规定，超出诊疗科目登记范围开展性病诊疗活动的，按照《医疗机构管理条例》及其实施细则的有关规定进行处理。 医疗机构违反本办法规定，未按照有关规定报告疫情或者隐瞒、谎报、缓报传染病疫情或者泄露性病患者涉及个人隐私的有关信息、资料，按照《传染病防治法》有关规定进行处理。"},{"i":49,"n":"第四十九条","txt":"医疗机构提供性病诊疗服务时违反诊疗规范的，由县级以上卫生行政部门责令限期改正，给予警告;逾期不改的，可以根据情节轻重处以三万元以下罚款。"},{"i":50,"n":"第五十条","txt":"医师在性病诊疗活动中违反本办法规定，有下列情形之一的，由县级以上卫生行政部门按照《执业医师法》第三十七条的有关规定进行处理： (一)违反性病诊疗规范，造成严重后果的; (二)泄露患者隐私，造成严重后果的; (三)未按照规定报告性病疫情，造成严重后果的; (四)违反本办法其他规定，造成严重后果的。"},{"i":51,"n":"第五十一条","txt":"护士在性病诊疗活动中违反本办法规定泄露患者隐私或者发现医嘱违反法律、法规、规章、诊疗技术规范未按照规定提出或者报告的，按照《护士条例》第三十一条的有关规定进行处理。"},{"i":52,"n":"第五十二条","txt":"医疗机构违反有关规定发布涉及性病诊断治疗内容的医疗广告，由县级以上卫生行政部门按照国家有关法律法规的规定进行处理。"},{"i":53,"n":"第五十三条","txt":"性病患者违反规定，导致性病传播扩散，给他人人身、财产造成损害的，应当依法承担民事赔偿责任;构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"省、自治区、直辖市卫生行政部门可以结合本地实际情况，根据本办法的规定制定实施细则。"},{"i":55,"n":"第五十五条","txt":"医疗机构实验室的性病检测质量控制工作按照医疗机构临床实验室有关规定进行统一管理和质控。"},{"i":56,"n":"第五十六条","txt":"本办法下列用语的含义： 承担性病防治任务的疾病预防控制机构，指按照卫生行政部门要求，承担性病防治工作职责的各级疾病预防控制中心或者皮肤病性病防治院、所、站。 有易感染性病危险行为的人群，指有婚外性行为、多性伴、同性性行为等行为的人群。"},{"i":57,"n":"第五十七条","txt":"本办法自2013年1月1日起施行。1991年8月12日卫生部公布的《性病防治管理办法》同时废止。"}],"tuoersuoyoueryuanweishengbaojianguanlibanfa":[{"i":1,"n":"第一条","txt":"为提高托儿所、幼儿园卫生保健工作水平，预防和减少疾病发生，保障儿童身心健康，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于招收0～6岁儿童的各级各类托儿所、幼儿园（以下简称托幼机构）。"},{"i":3,"n":"第三条","txt":"托幼机构应当贯彻保教结合、预防为主的方针，认真做好卫生保健工作。"},{"i":4,"n":"第四条","txt":"县级以上各级人民政府卫生行政部门应当将托幼机构的卫生保健工作作为公共卫生服务的重要内容，加强监督和指导。 县级以上各级人民政府教育行政部门协助卫生行政部门检查指导托幼机构的卫生保健工作。"},{"i":5,"n":"第五条","txt":"县级以上妇幼保健机构负责对辖区内托幼机构卫生保健工作进行业务指导。业务指导的内容包括：膳食营养、体格锻炼、健康检查、卫生消毒、疾病预防等。 疾病预防控制机构应当定期为托幼机构提供疾病预防控制咨询服务和指导。 卫生监督执法机构应当依法对托幼机构的饮用水卫生、传染病预防和控制等工作进行监督检查。"},{"i":6,"n":"第六条","txt":"托幼机构设有食堂提供餐饮服务的，应当按照《食品安全法》、《食品安全法实施条例》以及有关规章的要求，认真落实各项食品安全要求。 食品药品监督管理部门等负责餐饮服务监督管理的部门应当依法加强对托幼机构食品安全的指导与监督检查。"},{"i":7,"n":"第七条","txt":"托幼机构的建筑、设施、设备、环境及提供的食品、饮用水等应当符合国家有关卫生标准、规范的要求。"},{"i":8,"n":"第八条","txt":"新设立的托幼机构，招生前应当取得县级以上地方人民政府卫生行政部门指定的医疗卫生机构出具的符合《托儿所幼儿园卫生保健工作规范》的卫生评价报告。 各级教育行政部门应当将卫生保健工作质量纳入托幼机构的分级定类管理。"},{"i":9,"n":"第九条","txt":"托幼机构的法定代表人或者负责人是本机构卫生保健工作的第一责任人。"},{"i":10,"n":"第十条","txt":"托幼机构应当根据规模、接收儿童数量等设立相应的卫生室或者保健室，具体负责卫生保健工作。 卫生室应当符合医疗机构基本标准，取得卫生行政部门颁发的《医疗机构执业许可证》。 保健室不得开展诊疗活动，其配置应当符合保健室设置基本要求。"},{"i":11,"n":"第十一条","txt":"托幼机构应当聘用符合国家规定的卫生保健人员。卫生保健人员包括医师、护士和保健员。 在卫生室工作的医师应当取得卫生行政部门颁发的《医师执业证书》，护士应当取得《护士执业证书》。 在保健室工作的保健员应当具有高中以上学历，经过卫生保健专业知识培训，具有托幼机构卫生保健基础知识，掌握卫生消毒、传染病管理和营养膳食管理等技能。"},{"i":12,"n":"第十二条","txt":"托幼机构聘用卫生保健人员应当按照收托150名儿童至少设1名专职卫生保健人员的比例配备卫生保健人员。收托150名以下儿童的，应当配备专职或者兼职卫生保健人员。"},{"i":13,"n":"第十三条","txt":"托幼机构卫生保健人员应当定期接受当地妇幼保健机构组织的卫生保健专业知识培训。 托幼机构卫生保健人员应当对机构内的工作人员进行卫生知识宣传教育、疾病预防、卫生消毒、膳食营养、食品卫生、饮用水卫生等方面的具体指导。"},{"i":14,"n":"第十四条","txt":"托幼机构工作人员上岗前必须经县级以上人民政府卫生行政部门指定的医疗卫生机构进行健康检查，取得《托幼机构工作人员健康合格证》后方可上岗。 托幼机构应当组织在岗工作人员每年进行1次健康检查；在岗人员患有传染性疾病的，应当立即离岗治疗，治愈后方可上岗工作。 精神病患者、有精神病史者不得在托幼机构工作。"},{"i":15,"n":"第十五条","txt":"托幼机构应当严格按照《托儿所幼儿园卫生保健工作规范》开展卫生保健工作。 托幼机构卫生保健工作包括以下内容： （一）根据儿童不同年龄特点，建立科学、合理的一日生活制度，培养儿童良好的卫生习惯； （二）为儿童提供合理的营养膳食，科学制订食谱，保证膳食平衡； （三）制订与儿童生理特点相适应的体格锻炼计划，根据儿童年龄特点开展游戏及体育活动，并保证儿童户外活动时间，增进儿童身心健康； （四）建立健康检查制度，开展儿童定期健康检查工作，建立健康档案。坚持晨检及全日健康观察，做好常见病的预防，发现问题及时处理； （五）严格执行卫生消毒制度，做好室内外环境及个人卫生。加强饮食卫生管理，保证食品安全； （六）协助落实国家免疫规划，在儿童入托时应当查验其预防接种证，未按规定接种的儿童要告知其监护人，督促监护人带儿童到当地规定的接种单位补种； （七）加强日常保育护理工作，对体弱儿进行专案管理。配合妇幼保健"},{"i":16,"n":"第十六条","txt":"托幼机构应当在疾病预防控制机构指导下，做好传染病预防和控制管理工作。 托幼机构发现传染病患儿应当及时按照法律、法规和卫生部的规定进行报告，在疾病预防控制机构的指导下，对环境进行严格消毒处理。 在传染病流行期间，托幼机构应当加强预防控制措施。"},{"i":17,"n":"第十七条","txt":"疾病预防控制机构应当收集、分析、调查、核实托幼机构的传染病疫情，发现问题及时通报托幼机构，并向卫生行政部门和教育行政部门报告。"},{"i":18,"n":"第十八条","txt":"儿童入托幼机构前应当经医疗卫生机构进行健康检查，合格后方可进入托幼机构。 托幼机构发现在园（所）的儿童患疑似传染病时应当及时通知其监护人离园（所）诊治。患传染病的患儿治愈后，凭医疗卫生机构出具的健康证明方可入园（所）。 儿童离开托幼机构3个月以上应当进行健康检查后方可再次入托幼机构。 医疗卫生机构应当按照规定的体检项目开展健康检查，不得违反规定擅自改变。"},{"i":19,"n":"第十九条","txt":"托幼机构有下列情形之一的，由卫生行政部门责令限期改正，通报批评；逾期不改的，给予警告；情节严重的，由教育行政部门依法给予行政处罚： （一）未按要求设立保健室、卫生室或者配备卫生保健人员的； （二）聘用未进行健康检查或者健康检查不合格的工作人员的； （三）未定期组织工作人员健康检查的； （四）招收未经健康检查或健康检查不合格的儿童入托幼机构的； （五）未严格按照《托儿所幼儿园卫生保健工作规范》开展卫生保健工作的。 卫生行政部门应当及时将处理结果通报教育行政部门，教育行政部门将其作为托幼机构分级定类管理和质量评估的依据。"},{"i":20,"n":"第二十条","txt":"托幼机构未取得《医疗机构执业许可证》擅自设立卫生室，进行诊疗活动的，按照《医疗机构管理条例》的有关规定进行处罚。"},{"i":21,"n":"第二十一条","txt":"托幼机构未按照规定履行卫生保健工作职责，造成传染病流行、食物中毒等突发公共卫生事件的，卫生行政部门、教育行政部门依据相关法律法规给予处罚。 县级以上医疗卫生机构未按照本办法规定履行职责，导致托幼机构发生突发公共卫生事件的，卫生行政部门依据相关法律法规给予处罚。"},{"i":22,"n":"第二十二条","txt":"小学附设学前班、单独设立的学前班参照本办法执行。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市可以结合当地实际，根据本办法制定实施细则。"},{"i":24,"n":"第二十四条","txt":"对认真执行本办法，在托幼机构卫生保健工作中做出显著成绩的单位和个人，由各级人民政府卫生行政部门和教育行政部门给予表彰和奖励。"},{"i":25,"n":"第二十五条","txt":"《托儿所幼儿园卫生保健工作规范》由卫生部负责制定。"},{"i":26,"n":"第二十六条","txt":"本办法自2010年11月1日起施行。1994年12月1日由卫生部、原国家教委联合发布的《托儿所、幼儿园卫生保健管理办法》同时废止。"}],"kangjunyaowulinchuangyingyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗机构抗菌药物临床应用管理，规范抗菌药物临床应用行为，提高抗菌药物临床应用水平，促进临床合理应用抗菌药物，控制细菌耐药，保障医疗质量和医疗安全，根据相关卫生法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称抗菌药物是指治疗细菌、支原体、衣原体、立克次体、螺旋体、真菌等病原微生物所致感染性疾病病原的药物，不包括治疗结核病、寄生虫病和各种病毒所致感染性疾病的药物以及具有抗菌作用的中药制剂。"},{"i":3,"n":"第三条","txt":"卫生部负责全国医疗机构抗菌药物临床应用的监督管理。 县级以上地方卫生行政部门负责本行政区域内医疗机构抗菌药物临床应用的监督管理。"},{"i":4,"n":"第四条","txt":"本办法适用于各级各类医疗机构抗菌药物临床应用管理工作。"},{"i":5,"n":"第五条","txt":"抗菌药物临床应用应当遵循安全、有效、经济的原则。"},{"i":6,"n":"第六条","txt":"抗菌药物临床应用实行分级管理。根据安全性、疗效、细菌耐药性、价格等因素，将抗菌药物分为三级：非限制使用级、限制使用级与特殊使用级。具体划分标准如下： （一）非限制使用级抗菌药物是指经长期临床应用证明安全、有效，对细菌耐药性影响较小，价格相对较低的抗菌药物； （二）限制使用级抗菌药物是指经长期临床应用证明安全、有效，对细菌耐药性影响较大，或者价格相对较高的抗菌药物； （三）特殊使用级抗菌药物是指具有以下情形之一的抗菌药物： 1.具有明显或者严重不良反应，不宜随意使用的抗菌药物； 2.需要严格控制使用，避免细菌过快产生耐药的抗菌药物； 3.疗效、安全性方面的临床资料较少的抗菌药物； 4.价格昂贵的抗菌药物。 抗菌药物分级管理目录由各省级卫生行政部门制定，报卫生部备案。"},{"i":7,"n":"第七条","txt":"医疗机构主要负责人是本机构抗菌药物临床应用管理的第一责任人。"},{"i":8,"n":"第八条","txt":"医疗机构应当建立本机构抗菌药物管理工作制度。"},{"i":9,"n":"第九条","txt":"医疗机构应当设立抗菌药物管理工作机构或者配备专（兼）职人员负责本机构的抗菌药物管理工作。 二级以上的医院、妇幼保健院及专科疾病防治机构（以下简称二级以上医院）应当在药事管理与药物治疗学委员会下设立抗菌药物管理工作组。抗菌药物管理工作组由医务、药学、感染性疾病、临床微生物、护理、医院感染管理等部门负责人和具有相关专业高级技术职务任职资格的人员组成，医务、药学等部门共同负责日常管理工作。 其他医疗机构设立抗菌药物管理工作小组或者指定专（兼）职人员，负责具体管理工作。"},{"i":10,"n":"第十条","txt":"医疗机构抗菌药物管理工作机构或者专（兼）职人员的主要职责是： （一）贯彻执行抗菌药物管理相关的法律、法规、规章，制定本机构抗菌药物管理制度并组织实施； （二）审议本机构抗菌药物供应目录，制定抗菌药物临床应用相关技术性文件，并组织实施； （三）对本机构抗菌药物临床应用与细菌耐药情况进行监测，定期分析、评估、上报监测数据并发布相关信息，提出干预和改进措施； （四）对医务人员进行抗菌药物管理相关法律、法规、规章制度和技术规范培训，组织对患者合理使用抗菌药物的宣传教育。"},{"i":11,"n":"第十一条","txt":"二级以上医院应当设置感染性疾病科，配备感染性疾病专业医师。 感染性疾病科和感染性疾病专业医师负责对本机构各临床科室抗菌药物临床应用进行技术指导，参与抗菌药物临床应用管理工作。"},{"i":12,"n":"第十二条","txt":"二级以上医院应当配备抗菌药物等相关专业的临床药师。 临床药师负责对本机构抗菌药物临床应用提供技术支持，指导患者合理使用抗菌药物，参与抗菌药物临床应用管理工作。"},{"i":13,"n":"第十三条","txt":"二级以上医院应当根据实际需要，建立符合实验室生物安全要求的临床微生物室。 临床微生物室开展微生物培养、分离、鉴定和药物敏感试验等工作，提供病原学诊断和细菌耐药技术支持，参与抗菌药物临床应用管理工作。"},{"i":14,"n":"第十四条","txt":"卫生行政部门和医疗机构加强涉及抗菌药物临床应用管理的相关学科建设，建立专业人才培养和考核制度，充分发挥相关专业技术人员在抗菌药物临床应用管理工作中的作用。"},{"i":15,"n":"第十五条","txt":"医疗机构应当严格执行《处方管理办法》、《医疗机构药事管理规定》、《抗菌药物临床应用指导原则》、《国家处方集》等相关规定及技术规范，加强对抗菌药物遴选、采购、处方、调剂、临床应用和药物评价的管理。"},{"i":16,"n":"第十六条","txt":"医疗机构应当按照省级卫生行政部门制定的抗菌药物分级管理目录，制定本机构抗菌药物供应目录，并向核发其《医疗机构执业许可证》的卫生行政部门备案。医疗机构抗菌药物供应目录包括采购抗菌药物的品种、品规。未经备案的抗菌药物品种、品规，医疗机构不得采购。"},{"i":17,"n":"第十七条","txt":"医疗机构应当严格控制本机构抗菌药物供应目录的品种数量。同一通用名称抗菌药物品种，注射剂型和口服剂型各不得超过2种。具有相似或者相同药理学特征的抗菌药物不得重复列入供应目录。"},{"i":18,"n":"第十八条","txt":"医疗机构确因临床工作需要，抗菌药物品种和品规数量超过规定的，应当向核发其《医疗机构执业许可证》的卫生行政部门详细说明原因和理由；说明不充分或者理由不成立的，卫生行政部门不得接受其抗菌药物品种和品规数量的备案。"},{"i":19,"n":"第十九条","txt":"医疗机构应当定期调整抗菌药物供应目录品种结构，并于每次调整后15个工作日内向核发其《医疗机构执业许可证》的卫生行政部门备案。调整周期原则上为2年，最短不得少于1年。"},{"i":20,"n":"第二十条","txt":"医疗机构应当按照国家药品监督管理部门批准并公布的药品通用名称购进抗菌药物，优先选用《国家基本药物目录》、《国家处方集》和《国家基本医疗保险、工伤保险和生育保险药品目录》收录的抗菌药物品种。 基层医疗卫生机构只能选用基本药物（包括各省区市增补品种）中的抗菌药物品种。"},{"i":21,"n":"第二十一条","txt":"医疗机构抗菌药物应当由药学部门统一采购供应，其他科室或者部门不得从事抗菌药物的采购、调剂活动。临床上不得使用非药学部门采购供应的抗菌药物。"},{"i":22,"n":"第二十二条","txt":"因特殊治疗需要，医疗机构需使用本机构抗菌药物供应目录以外抗菌药物的，可以启动临时采购程序。临时采购应当由临床科室提出申请，说明申请购入抗菌药物名称、剂型、规格、数量、使用对象和使用理由，经本机构抗菌药物管理工作组审核同意后，由药学部门临时一次性购入使用。 医疗机构应当严格控制临时采购抗菌药物品种和数量，同一通用名抗菌药物品种启动临时采购程序原则上每年不得超过5例次。如果超过5例次，应当讨论是否列入本机构抗菌药物供应目录。调整后的抗菌药物供应目录总品种数不得增加。 医疗机构应当每半年将抗菌药物临时采购情况向核发其《医疗机构执业许可证》的卫生行政部门备案。"},{"i":23,"n":"第二十三条","txt":"医疗机构应当建立抗菌药物遴选和定期评估制度。 医疗机构遴选和新引进抗菌药物品种，应当由临床科室提交申请报告，经药学部门提出意见后，由抗菌药物管理工作组审议。 抗菌药物管理工作组三分之二以上成员审议同意，并经药事管理与药物治疗学委员会三分之二以上委员审核同意后方可列入采购供应目录。 抗菌药物品种或者品规存在安全隐患、疗效不确定、耐药率高、性价比差或者违规使用等情况的，临床科室、药学部门、抗菌药物管理工作组可以提出清退或者更换意见。清退意见经抗菌药物管理工作组二分之一以上成员同意后执行，并报药事管理与药物治疗学委员会备案；更换意见经药事管理与药物治疗学委员会讨论通过后执行。 清退或者更换的抗菌药物品种或者品规原则上12个月内不得重新进入本机构抗菌药物供应目录。"},{"i":24,"n":"第二十四条","txt":"具有高级专业技术职务任职资格的医师，可授予特殊使用级抗菌药物处方权；具有中级以上专业技术职务任职资格的医师，可授予限制使用级抗菌药物处方权；具有初级专业技术职务任职资格的医师，在乡、民族乡、镇、村的医疗机构独立从事一般执业活动的执业助理医师以及乡村医生，可授予非限制使用级抗菌药物处方权。药师经培训并考核合格后，方可获得抗菌药物调剂资格。 二级以上医院应当定期对医师和药师进行抗菌药物临床应用知识和规范化管理的培训。医师经本机构培训并考核合格后，方可获得相应的处方权。 其他医疗机构依法享有处方权的医师、乡村医生和从事处方调剂工作的药师，由县级以上地方卫生行政部门组织相关培训、考核。经考核合格的，授予相应的抗菌药物处方权或者抗菌药物调剂资格。"},{"i":25,"n":"第二十五条","txt":"抗菌药物临床应用知识和规范化管理培训和考核内容应当包括： （一）《药品管理法》、《执业医师法》、《抗菌药物临床应用管理办法》、《处方管理办法》、《医疗机构药事管理规定》、《抗菌药物临床应用指导原则》、《国家基本药物处方集》、《国家处方集》和《医院处方点评管理规范（试行）》等相关法律、法规、规章和规范性文件； （二）抗菌药物临床应用及管理制度； （三）常用抗菌药物的药理学特点与注意事项； （四）常见细菌的耐药趋势与控制方法； （五）抗菌药物不良反应的防治。"},{"i":26,"n":"第二十六条","txt":"医疗机构和医务人员应当严格掌握使用抗菌药物预防感染的指证。预防感染、治疗轻度或者局部感染应当首选非限制使用级抗菌药物；严重感染、免疫功能低下合并感染或者病原菌只对限制使用级抗菌药物敏感时，方可选用限制使用级抗菌药物。"},{"i":27,"n":"第二十七条","txt":"严格控制特殊使用级抗菌药物使用。特殊使用级抗菌药物不得在门诊使用。 临床应用特殊使用级抗菌药物应当严格掌握用药指证，经抗菌药物管理工作组指定的专业技术人员会诊同意后，由具有相应处方权医师开具处方。 特殊使用级抗菌药物会诊人员由具有抗菌药物临床应用经验的感染性疾病科、呼吸科、重症医学科、微生物检验科、药学部门等具有高级专业技术职务任职资格的医师、药师或具有高级专业技术职务任职资格的抗菌药物专业临床药师担任。"},{"i":28,"n":"第二十八条","txt":"因抢救生命垂危的患者等紧急情况，医师可以越级使用抗菌药物。越级使用抗菌药物应当详细记录用药指证，并应当于24小时内补办越级使用抗菌药物的必要手续。"},{"i":29,"n":"第二十九条","txt":"医疗机构应当制定并严格控制门诊患者静脉输注使用抗菌药物比例。 村卫生室、诊所和社区卫生服务站使用抗菌药物开展静脉输注活动，应当经县级卫生行政部门核准。"},{"i":30,"n":"第三十条","txt":"医疗机构应当开展抗菌药物临床应用监测工作，分析本机构及临床各专业科室抗菌药物使用情况，评估抗菌药物使用适宜性；对抗菌药物使用趋势进行分析，对抗菌药物不合理使用情况应当及时采取有效干预措施。"},{"i":31,"n":"第三十一条","txt":"医疗机构应当根据临床微生物标本检测结果合理选用抗菌药物。临床微生物标本检测结果未出具前，医疗机构可以根据当地和本机构细菌耐药监测情况经验选用抗菌药物，临床微生物标本检测结果出具后根据检测结果进行相应调整。"},{"i":32,"n":"第三十二条","txt":"医疗机构应当开展细菌耐药监测工作，建立细菌耐药预警机制，并采取下列相应措施： （一）主要目标细菌耐药率超过30%的抗菌药物，应当及时将预警信息通报本机构医务人员； （二）主要目标细菌耐药率超过40%的抗菌药物，应当慎重经验用药； （三）主要目标细菌耐药率超过50%的抗菌药物，应当参照药敏试验结果选用； （四）主要目标细菌耐药率超过75%的抗菌药物，应当暂停针对此目标细菌的临床应用，根据追踪细菌耐药监测结果，再决定是否恢复临床应用。"},{"i":33,"n":"第三十三条","txt":"医疗机构应当建立本机构抗菌药物临床应用情况排名、内部公示和报告制度。 医疗机构应当对临床科室和医务人员抗菌药物使用量、使用率和使用强度等情况进行排名并予以内部公示；对排名后位或者发现严重问题的医师进行批评教育，情况严重的予以通报。 医疗机构应当按照要求对临床科室和医务人员抗菌药物临床应用情况进行汇总，并向核发其《医疗机构执业许可证》的卫生行政部门报告。非限制使用级抗菌药物临床应用情况，每年报告一次；限制使用级和特殊使用级抗菌药物临床应用情况，每半年报告一次。"},{"i":34,"n":"第三十四条","txt":"医疗机构应当充分利用信息化手段促进抗菌药物合理应用。"},{"i":35,"n":"第三十五条","txt":"医疗机构应当对以下抗菌药物临床应用异常情况开展调查，并根据不同情况作出处理： （一）使用量异常增长的抗菌药物； （二）半年内使用量始终居于前列的抗菌药物； （三）经常超适应证、超剂量使用的抗菌药物； （四）企业违规销售的抗菌药物； （五）频繁发生严重不良事件的抗菌药物。"},{"i":36,"n":"第三十六条","txt":"医疗机构应当加强对抗菌药物生产、经营企业在本机构销售行为的管理，对存在不正当销售行为的企业，应当及时采取暂停进药、清退等措施。"},{"i":37,"n":"第三十七条","txt":"县级以上卫生行政部门应当加强对本行政区域内医疗机构抗菌药物临床应用情况的监督检查。"},{"i":38,"n":"第三十八条","txt":"卫生行政部门工作人员依法对医疗机构抗菌药物临床应用情况进行监督检查时，应当出示证件，被检查医疗机构应当予以配合，提供必要的资料，不得拒绝、阻碍和隐瞒。"},{"i":39,"n":"第三十九条","txt":"县级以上地方卫生行政部门应当建立医疗机构抗菌药物临床应用管理评估制度。"},{"i":40,"n":"第四十条","txt":"县级以上地方卫生行政部门应当建立抗菌药物临床应用情况排名、公布和诫勉谈话制度。对本行政区域内医疗机构抗菌药物使用量、使用率和使用强度等情况进行排名，将排名情况向本行政区域内医疗机构公布，并报上级卫生行政部门备案；对发生重大、特大医疗质量安全事件或者存在严重医疗质量安全隐患的各级各类医疗机构的负责人进行诫勉谈话，情况严重的予以通报。"},{"i":41,"n":"第四十一条","txt":"县级卫生行政部门负责对辖区内乡镇卫生院、社区卫生服务中心（站）抗菌药物使用量、使用率等情况进行排名并予以公示。 受县级卫生行政部门委托，乡镇卫生院负责对辖区内村卫生室抗菌药物使用量、使用率等情况进行排名并予以公示，并向县级卫生行政部门报告。"},{"i":42,"n":"第四十二条","txt":"卫生部建立全国抗菌药物临床应用监测网和全国细菌耐药监测网，对全国抗菌药物临床应用和细菌耐药情况进行监测；根据监测情况定期公布抗菌药物临床应用控制指标，开展抗菌药物临床应用质量管理与控制工作。 省级卫生行政部门应当建立本行政区域的抗菌药物临床应用监测网和细菌耐药监测网，对医疗机构抗菌药物临床应用和细菌耐药情况进行监测，开展抗菌药物临床应用质量管理与控制工作。 抗菌药物临床应用和细菌耐药监测技术方案由卫生部另行制定。"},{"i":43,"n":"第四十三条","txt":"卫生行政部门应当将医疗机构抗菌药物临床应用情况纳入医疗机构考核指标体系；将抗菌药物临床应用情况作为医疗机构定级、评审、评价重要指标，考核不合格的，视情况对医疗机构作出降级、降等、评价不合格处理。"},{"i":44,"n":"第四十四条","txt":"医疗机构抗菌药物管理机构应当定期组织相关专业技术人员对抗菌药物处方、医嘱实施点评，并将点评结果作为医师定期考核、临床科室和医务人员绩效考核依据。"},{"i":45,"n":"第四十五条","txt":"医疗机构应当对出现抗菌药物超常处方3次以上且无正当理由的医师提出警告，限制其特殊使用级和限制使用级抗菌药物处方权。"},{"i":46,"n":"第四十六条","txt":"医师出现下列情形之一的，医疗机构应当取消其处方权： （一）抗菌药物考核不合格的； （二）限制处方权后，仍出现超常处方且无正当理由的； （三）未按照规定开具抗菌药物处方，造成严重后果的； （四）未按照规定使用抗菌药物，造成严重后果的； （五）开具抗菌药物处方牟取不正当利益的。"},{"i":47,"n":"第四十七条","txt":"药师未按照规定审核抗菌药物处方与用药医嘱，造成严重后果的，或者发现处方不适宜、超常处方等情况未进行干预且无正当理由的，医疗机构应当取消其药物调剂资格。"},{"i":48,"n":"第四十八条","txt":"医师处方权和药师药物调剂资格取消后，在六个月内不得恢复其处方权和药物调剂资格。"},{"i":49,"n":"第四十九条","txt":"医疗机构有下列情形之一的，由县级以上卫生行政部门责令限期改正；逾期不改的，进行通报批评，并给予警告；造成严重后果的，对负有责任的主管人员和其他直接责任人员，给予处分： （一）未建立抗菌药物管理组织机构或者未指定专（兼）职技术人员负责具体管理工作的； （二）未建立抗菌药物管理规章制度的； （三）抗菌药物临床应用管理混乱的； （四）未按照本办法规定执行抗菌药物分级管理、医师抗菌药物处方权限管理、药师抗菌药物调剂资格管理或者未配备相关专业技术人员的； （五）其他违反本办法规定行为的。"},{"i":50,"n":"第五十条","txt":"医疗机构有下列情形之一的，由县级以上卫生行政部门责令限期改正，给予警告，并可根据情节轻重处以三万元以下罚款；对负有责任的主管人员和其他直接责任人员，可根据情节给予处分： （一）使用未取得抗菌药物处方权的医师或者使用被取消抗菌药物处方权的医师开具抗菌药物处方的； （二）未对抗菌药物处方、医嘱实施适宜性审核，情节严重的； （三）非药学部门从事抗菌药物购销、调剂活动的； （四）将抗菌药物购销、临床应用情况与个人或者科室经济利益挂钩的； （五）在抗菌药物购销、临床应用中牟取不正当利益的。"},{"i":51,"n":"第五十一条","txt":"医疗机构的负责人、药品采购人员、医师等有关人员索取、收受药品生产企业、药品经营企业或者其代理人给予的财物或者通过开具抗菌药物牟取不正当利益的，由县级以上地方卫生行政部门依据国家有关法律法规进行处理。"},{"i":52,"n":"第五十二条","txt":"医师有下列情形之一的，由县级以上卫生行政部门按照《执业医师法》第三十七条的有关规定，给予警告或者责令暂停六个月以上一年以下执业活动；情节严重的，吊销其执业证书；构成犯罪的，依法追究刑事责任： （一）未按照本办法规定开具抗菌药物处方，造成严重后果的； （二）使用未经国家药品监督管理部门批准的抗菌药物的； （三）使用本机构抗菌药物供应目录以外的品种、品规，造成严重后果的； （四）违反本办法其他规定，造成严重后果的。 乡村医生有前款规定情形之一的，由县级卫生行政部门按照《乡村医师从业管理条例》第三十八条有关规定处理。"},{"i":53,"n":"第五十三条","txt":"药师有下列情形之一的，由县级以上卫生行政部门责令限期改正，给予警告；构成犯罪的，依法追究刑事责任： （一）未按照规定审核、调剂抗菌药物处方，情节严重的； （二）未按照规定私自增加抗菌药物品种或者品规的； （三）违反本办法其他规定的。"},{"i":54,"n":"第五十四条","txt":"未经县级卫生行政部门核准，村卫生室、诊所、社区卫生服务站擅自使用抗菌药物开展静脉输注活动的，由县级以上地方卫生行政部门责令限期改正，给予警告；逾期不改的，可根据情节轻重处以一万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"县级以上地方卫生行政部门未按照本办法规定履行监管职责，造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予记大过、降级、撤职、开除等行政处分。"},{"i":56,"n":"第五十六条","txt":"医疗机构及其医务人员违反《药品管理法》的，依照《药品管理法》的有关规定处理。"},{"i":57,"n":"第五十七条","txt":"国家中医药管理部门在职责范围内负责中医医疗机构抗菌药物临床应用的监督管理。"},{"i":58,"n":"第五十八条","txt":"各省级卫生行政部门应当于本办法发布之日起3个月内，制定本行政区域抗菌药物分级管理目录。"},{"i":59,"n":"第五十九条","txt":"本办法自2012年8月1日起施行。"}],"hushizhiyezhuceguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范护士执业注册管理，根据《护士条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"护士经执业注册取得《护士执业证书》后，方可按照注册的执业地点从事护理工作。 未经执业注册取得《护士执业证书》者，不得从事诊疗技术规范规定的护理活动。"},{"i":3,"n":"第三条","txt":"国家卫生健康委负责全国护士执业注册监督管理工作。 县级以上地方卫生健康主管部门是护士执业注册的主管部门，负责本行政区域的护士执业注册监督管理工作。"},{"i":4,"n":"第四条","txt":"省、自治区、直辖市卫生健康主管部门结合本行政区域的实际情况，制定护士执业注册工作的具体实施办法，并报国家卫生健康委备案。"},{"i":5,"n":"第五条","txt":"国家建立护士管理信息系统，实行护士电子化注册管理。"},{"i":6,"n":"第六条","txt":"申请护士执业注册，应当具备下列条件： （一）具有完全民事行为能力； （二）在中等职业学校、高等学校完成教育部和国家卫生健康委规定的普通全日制3年以上的护理、助产专业课程学习，包括在教学、综合医院完成8个月以上护理临床实习，并取得相应学历证书； （三）通过国家卫生健康委组织的护士执业资格考试； （四）符合本办法第七条规定的健康标准。"},{"i":7,"n":"第七条","txt":"申请护士执业注册，应当符合下列健康标准： （一）无精神病史； （二）无色盲、色弱、双耳听力障碍； （三）无影响履行护理职责的疾病、残疾或者功能障碍。"},{"i":8,"n":"第八条","txt":"申请护士执业注册，应当向批准设立拟执业医疗机构或者为该医疗机构备案的卫生健康主管部门提出申请。"},{"i":9,"n":"第九条","txt":"申请护士执业注册，应当提交下列材料： （一）护士执业注册申请审核表； （二）申请人身份证明； （三）申请人学历证书及专业学习中的临床实习证明； （四）医疗卫生机构拟聘用的相关材料。"},{"i":10,"n":"第十条","txt":"卫生健康主管部门应当自受理申请之日起20个工作日内，对申请人提交的材料进行审核、注册，发给国家卫生健康委统一印制的《护士执业证书》；对不符合规定条件的，不予注册，并书面说明理由。 《护士执业证书》上应当注明护士的姓名、性别、出生日期等个人信息及证书编号、注册日期和执业地点。"},{"i":11,"n":"第十一条","txt":"护士执业注册申请，应当自通过护士执业资格考试之日起3年内提出；逾期提出申请的，除本办法第九条规定的材料外，还应当提交在省、自治区、直辖市卫生健康主管部门规定的教学、综合医院接受3个月临床护理培训并考核合格的证明。"},{"i":12,"n":"第十二条","txt":"护士执业注册有效期为5年。护士执业注册有效期届满需要继续执业的，应当在有效期届满前30日，向批准设立执业医疗机构或者为该医疗机构备案的卫生健康主管部门申请延续注册。"},{"i":13,"n":"第十三条","txt":"护士申请延续注册，应当提交护士执业注册申请审核表和申请人的《护士执业证书》。"},{"i":14,"n":"第十四条","txt":"注册部门自受理延续注册申请之日起20个工作日内进行审核。审核合格的，予以延续注册；审核不合格的，不予延续注册，并书面说明理由。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不予延续注册： （一）不符合本办法第七条规定的健康标准的； （二）被处暂停执业活动处罚期限未满的。"},{"i":16,"n":"第十六条","txt":"医疗卫生机构可以为本机构聘用的护士集体办理护士执业注册和延续注册。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，拟在医疗卫生机构执业时，应当重新申请注册： （一）注册有效期届满未延续注册的； （二）受吊销《护士执业证书》处罚，自吊销之日起满2年的。 重新申请注册的，按照本办法第九条的规定提交材料；中断护理执业活动超过3年的，还应当提交在省、自治区、直辖市卫生健康主管部门规定的教学、综合医院接受3个月临床护理培训并考核合格的证明。"},{"i":18,"n":"第十八条","txt":"护士在其执业注册有效期内变更执业地点等注册项目，应当办理变更注册。 护士承担经注册执业机构批准的卫生支援、进修、学术交流、政府交办事项等任务和参加卫生健康主管部门批准的义诊，在签订帮扶或者托管协议的医疗卫生机构内执业，以及从事执业机构派出的上门护理服务等，不需办理执业地点变更等手续。"},{"i":19,"n":"第十九条","txt":"护士在其执业注册有效期内变更执业地点等注册项目的，应当向批准设立执业医疗机构或者为该医疗机构备案的卫生健康主管部门报告，并提交护士执业注册申请审核表和申请人的《护士执业证书》。 注册部门应当自受理之日起7个工作日内为其办理变更手续。 护士跨省、自治区、直辖市变更执业地点的，收到报告的注册部门还应当向其原执业地注册部门通报。 县级以上地方卫生健康主管部门应当通过护士管理信息系统，为护士变更注册提供便利。"},{"i":20,"n":"第二十条","txt":"护士执业注册后有下列情形之一的，原注册部门办理注销执业注册： （一）注册有效期届满未延续注册； （二）受吊销《护士执业证书》处罚； （三）护士死亡或者丧失民事行为能力。"},{"i":21,"n":"第二十一条","txt":"卫生健康主管部门实施护士执业注册，有下列情形之一的，由其上级卫生健康主管部门或者监察机关责令改正，对直接负责的主管人员或者其他直接责任人员依法给予行政处分： （一）对不符合护士执业注册条件者准予护士执业注册的； （二）对符合护士执业注册条件者不予护士执业注册的。"},{"i":22,"n":"第二十二条","txt":"护士执业注册申请人隐瞒有关情况或者提供虚假材料申请护士执业注册的，卫生健康主管部门不予受理或者不予护士执业注册，并给予警告；已经注册的，应当撤销注册。"},{"i":23,"n":"第二十三条","txt":"在内地完成护理、助产专业学习的香港、澳门特别行政区及台湾地区人员，符合本办法第六条、第七条、第九条规定的，可以申请护士执业注册。"},{"i":24,"n":"第二十四条","txt":"计划生育技术服务机构护士的执业注册管理适用本办法的规定。"},{"i":25,"n":"第二十五条","txt":"本办法下列用语的含义： 教学医院，是指与中等职业学校、高等学校有承担护理临床实习任务的合同关系，并能够按照护理临床实习教学计划完成教学任务的医院。 综合医院，是指依照《医疗机构管理条例》、《医疗机构基本标准》的规定，符合综合医院基本标准的医院。"},{"i":26,"n":"第二十六条","txt":"本办法自2008年5月12日起施行。"}],"hushizhiyezigekaoshibanfa":[{"i":1,"n":"第一条","txt":"为规范全国护士执业资格考试工作，加强护理专业队伍建设，根据《护士条例》第七条规定，制定本办法。"},{"i":2,"n":"第二条","txt":"卫生部负责组织实施护士执业资格考试。国家护士执业资格考试是评价申请护士执业资格者是否具备执业所必须的护理专业知识与工作能力的考试。 考试成绩合格者，可申请护士执业注册。 具有护理、助产专业中专和大专学历的人员，参加护士执业资格考试并成绩合格，可取得护理初级（士）专业技术资格证书；护理初级（师）专业技术资格按照有关规定通过参加全国卫生专业技术资格考试取得。 具有护理、助产专业本科以上学历的人员，参加护士执业资格考试并成绩合格，可以取得护理初级（士）专业技术资格证书；在达到《卫生技术人员职务试行条例》规定的护师专业技术职务任职资格年限后，可直接聘任护师专业技术职务。"},{"i":3,"n":"第三条","txt":"护士执业资格考试实行国家统一考试制度。统一考试大纲，统一命题，统一合格标准。 护士执业资格考试原则上每年举行一次，具体考试日期在举行考试3个月前向社会公布。"},{"i":4,"n":"第四条","txt":"护士执业资格考试包括专业实务和实践能力两个科目。一次考试通过两个科目为考试成绩合格。 为加强对考生实践能力的考核，原则上采用“人机对话”考试方式进行。"},{"i":5,"n":"第五条","txt":"护士执业资格考试遵循公平、公开、公正的原则。"},{"i":6,"n":"第六条","txt":"卫生部和人力资源社会保障部成立全国护士执业资格考试委员会。主要职责是： （一）对涉及护士执业资格考试的重大事项进行协调、决策； （二）审定护士执业资格考试大纲、考试内容和方案； （三）确定并公布护士执业资格考试成绩合格线； （四）指导全国护士执业资格考试工作。 全国护士执业资格考试委员会下设办公室，办公室设在卫生部，负责具体工作。"},{"i":7,"n":"第七条","txt":"护士执业资格考试考务管理实行承办考试机构、考区、考点三级责任制。"},{"i":8,"n":"第八条","txt":"承办考试机构具体组织实施护士执业资格考试考务工作。主要职责是： （一）组织制定护士执业资格考试考务管理规定，负责全国护士执业资格考试考务管理； （二）组织专家拟定护士执业资格考试大纲和命题审卷的有关规定并承担具体工作； （三）负责护士执业资格考试考生信息处理； （四）组织评定考试成绩，提供考生成绩单和护士执业资格考试成绩合格证明； （五）负责考试结果的统计分析和考试工作总结，并向护士执业资格考试委员会提交工作报告； （六）负责建立护士执业资格考试命题专家库和考试题库； （七）指导考区有关考试的业务工作。"},{"i":9,"n":"第九条","txt":"各省、自治区、直辖市及新疆生产建设兵团设立考区。省、自治区、直辖市人民政府卫生行政部门及新疆生产建设兵团卫生局负责本辖区的考试工作。其主要职责是： （一）负责本考区护士执业资格考试的考务管理； （二）制定本考区护士执业资格考试考务管理具体措施； （三）负责审定考生报名资格； （四）负责指导考区内各考点的业务工作； （五）负责处理、上报考试期间本考区发生的重大问题。 省、自治区、直辖市人民政府卫生行政部门及新疆生产建设兵团卫生局可根据实际情况，会同人力资源社会保障部门成立护士执业资格考试领导小组。"},{"i":10,"n":"第十条","txt":"考区根据考生情况设置考点，报全国护士执业资格考试委员会备案。考点设在设区的市。考点的主要职责是： （一）负责本考点护士执业资格考试的考务工作； （二）执行本考点护士执业资格考试考务管理具体措施； （三）受理考生报名，核实报名材料，初审考生报名资格； （四）负责为不能自行上网打印准考证的考生打印准考证； （五）处理、上报本考点考试期间发生的问题； （六）发给考生成绩单和护士执业资格考试成绩合格证明。"},{"i":11,"n":"第十一条","txt":"各级考试管理机构要有计划地培训考务工作人员和监考人员，提高考试管理水平。"},{"i":12,"n":"第十二条","txt":"在中等职业学校、高等学校完成国务院教育主管部门和国务院卫生主管部门规定的普通全日制3年以上的护理、助产专业课程学习，包括在教学、综合医院完成8个月以上护理临床实习，并取得相应学历证书的，可以申请参加护士执业资格考试。"},{"i":13,"n":"第十三条","txt":"申请参加护士执业资格考试的人员，应当在公告规定的期限内报名，并提交以下材料： （一）护士执业资格考试报名申请表； （二）本人身份证明； （三）近6个月二寸免冠正面半身照片3张； （四）本人毕业证书； （五）报考所需的其他材料。 申请人为在校应届毕业生的，应当持有所在学校出具的应届毕业生毕业证明，到学校所在地的考点报名。学校可以为本校应届毕业生办理集体报名手续。 申请人为非应届毕业生的，可以选择到人事档案所在地报名。"},{"i":14,"n":"第十四条","txt":"申请参加护士执业资格考试者，应当按国家价格主管部门确定的收费标准缴纳考试费。"},{"i":15,"n":"第十五条","txt":"护士执业资格考试成绩于考试结束后45个工作日内公布。考生成绩单由报名考点发给考生。"},{"i":16,"n":"第十六条","txt":"考试成绩合格者，取得考试成绩合格证明，作为申请护士执业注册的有效证明。"},{"i":17,"n":"第十七条","txt":"考试考务管理工作要严格执行有关规章和纪律，切实做好试卷命制、印刷、发送和保管过程中的保密工作，严防泄密。"},{"i":18,"n":"第十八条","txt":"护士执业资格考试实行回避制度。考试工作人员有下列情形之一的，应当回避： （一）是考生近亲属的； （二）与考生有其他利害关系，可能影响考试公正的。"},{"i":19,"n":"第十九条","txt":"对违反考试纪律和有关规定的，按照《专业技术人员资格考试违纪违规行为处理规定》处理。"},{"i":20,"n":"第二十条","txt":"军队有关部门负责军队人员参加全国护士执业资格考试的报名、成绩发布等工作。"},{"i":21,"n":"第二十一条","txt":"香港特别行政区、澳门特别行政区和台湾地区居民符合本办法规定和《内地与香港关于建立更紧密经贸关系的安排》、《内地与澳门关于建立更紧密经贸关系的安排》或者内地有关主管部门规定的，可以申请参加护士执业资格考试。"},{"i":22,"n":"第二十二条","txt":"本办法自2010年7月1日起施行。"}],"fangshegongzuorenyuanzhiyejiankangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保障放射工作人员的职业健康与安全，根据《中华人民共和国职业病防治法》（以下简称《职业病防治法》）和《放射性同位素与射线装置安全和防护条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的放射工作单位及其放射工作人员，应当遵守本办法。 本办法所称放射工作单位，是指开展下列活动的企业、事业单位和个体经济组织： （一）放射性同位素（非密封放射性物质和放射源）的生产、使用、运输、贮存和废弃处理； （二）射线装置的生产、使用和维修； （三）核燃料循环中的铀矿开采、铀矿水冶、铀的浓缩和转化、燃料制造、反应堆运行、燃料后处理和核燃料循环中的研究活动； （四）放射性同位素、射线装置和放射工作场所的辐射监测； （五）卫生部规定的与电离辐射有关的其他活动。 本办法所称放射工作人员，是指在放射工作单位从事放射职业活动中受到电离辐射照射的人员。"},{"i":3,"n":"第三条","txt":"卫生部主管全国放射工作人员职业健康的监督管理工作。 县级以上地方人民政府卫生行政部门负责本行政区域内放射工作人员职业健康的监督管理。"},{"i":4,"n":"第四条","txt":"放射工作单位应当采取有效措施，使本单位放射工作人员职业健康的管理符合本办法和有关标准及规范的要求。"},{"i":5,"n":"第五条","txt":"放射工作人员应当具备下列基本条件： （一）年满18周岁； （二）经职业健康检查，符合放射工作人员的职业健康要求； （三）放射防护和有关法律知识培训考核合格； （四）遵守放射防护法规和规章制度，接受职业健康监护和个人剂量监测管理； （五）持有《放射工作人员证》。"},{"i":6,"n":"第六条","txt":"放射工作人员上岗前，放射工作单位负责向所在地县级以上地方人民政府卫生行政部门为其申请办理《放射工作人员证》。 开展放射诊疗工作的医疗机构，向为其发放《放射诊疗许可证》的卫生行政部门申请办理《放射工作人员证》。 开展本办法第二条第二款第（三）项所列活动以及非医用加速器运行、辐照加工、射线探伤和油田测井等活动的放射工作单位，向所在地省级卫生行政部门申请办理《放射工作人员证》。 其他放射工作单位办理《放射工作人员证》的规定，由所在地省级卫生行政部门结合本地区实际情况确定。 《放射工作人员证》的格式由卫生部统一制定。"},{"i":7,"n":"第七条","txt":"放射工作人员上岗前应当接受放射防护和有关法律知识培训，考核合格方可参加相应的工作。培训时间不少于4天。"},{"i":8,"n":"第八条","txt":"放射工作单位应当定期组织本单位的放射工作人员接受放射防护和有关法律知识培训。放射工作人员两次培训的时间间隔不超过2年，每次培训时间不少于2天。"},{"i":9,"n":"第九条","txt":"放射工作单位应当建立并按照规定的期限妥善保存培训档案。培训档案应当包括每次培训的课程名称、培训时间、考试或考核成绩等资料。"},{"i":10,"n":"第十条","txt":"放射防护及有关法律知识培训应当由符合省级卫生行政部门规定条件的单位承担，培训单位可会同放射工作单位共同制定培训计划，并按照培训计划和有关规范、标准实施和考核。 放射工作单位应当将每次培训的情况及时记录在《放射工作人员证》中。"},{"i":11,"n":"第十一条","txt":"放射工作单位应当按照本办法和国家有关标准、规范的要求，安排本单位的放射工作人员接受个人剂量监测，并遵守下列规定： （一）外照射个人剂量监测周期一般为30天，最长不应超过90天；内照射个人剂量监测周期按照有关标准执行； （二）建立并终生保存个人剂量监测档案； （三）允许放射工作人员查阅、复印本人的个人剂量监测档案。"},{"i":12,"n":"第十二条","txt":"个人剂量监测档案应当包括： （一）常规监测的方法和结果等相关资料； （二）应急或者事故中受到照射的剂量和调查报告等相关资料。 放射工作单位应当将个人剂量监测结果及时记录在《放射工作人员证》中。"},{"i":13,"n":"第十三条","txt":"放射工作人员进入放射工作场所，应当遵守下列规定： （一）正确佩戴个人剂量计； （二）操作结束离开非密封放射性物质工作场所时，按要求进行个人体表、衣物及防护用品的放射性表面污染监测，发现污染要及时处理，做好记录并存档； （三）进入辐照装置、工业探伤、放射治疗等强辐射工作场所时，除佩戴常规个人剂量计外，还应当携带报警式剂量计。"},{"i":14,"n":"第十四条","txt":"个人剂量监测工作应当由具备资质的个人剂量监测技术服务机构承担。个人剂量监测技术服务机构的资质审定由中国疾病预防控制中心协助卫生部组织实施。 个人剂量监测技术服务机构的资质审定按照《职业病防治法》、《职业卫生技术服务机构管理办法》和卫生部有关规定执行。"},{"i":15,"n":"第十五条","txt":"个人剂量监测技术服务机构应当严格按照国家职业卫生标准、技术规范开展监测工作，参加质量控制和技术培训。 个人剂量监测报告应当在每个监测周期结束后1个月内送达放射工作单位，同时报告当地卫生行政部门。"},{"i":16,"n":"第十六条","txt":"县级以上地方卫生行政部门按规定时间和格式，将本行政区域内的放射工作人员个人剂量监测数据逐级上报到卫生部。"},{"i":17,"n":"第十七条","txt":"中国疾病预防控制中心协助卫生部拟定个人剂量监测技术服务机构的资质审定程序和标准，组织实施全国个人剂量监测的质量控制和技术培训，汇总分析全国个人剂量监测数据。"},{"i":18,"n":"第十八条","txt":"放射工作人员上岗前，应当进行上岗前的职业健康检查，符合放射工作人员健康标准的，方可参加相应的放射工作。 放射工作单位不得安排未经职业健康检查或者不符合放射工作人员职业健康标准的人员从事放射工作。"},{"i":19,"n":"第十九条","txt":"放射工作单位应当组织上岗后的放射工作人员定期进行职业健康检查，两次检查的时间间隔不应超过2年，必要时可增加临时性检查。"},{"i":20,"n":"第二十条","txt":"放射工作人员脱离放射工作岗位时，放射工作单位应当对其进行离岗前的职业健康检查。"},{"i":21,"n":"第二十一条","txt":"对参加应急处理或者受到事故照射的放射工作人员，放射工作单位应当及时组织健康检查或者医疗救治，按照国家有关标准进行医学随访观察。"},{"i":22,"n":"第二十二条","txt":"从事放射工作人员职业健康检查的医疗机构（以下简称职业健康检查机构）应当经省级卫生行政部门批准。"},{"i":23,"n":"第二十三条","txt":"职业健康检查机构应当自体检工作结束之日起1个月内，将职业健康检查报告送达放射工作单位。 职业健康检查机构出具的职业健康检查报告应当客观、真实，并对职业健康检查报告负责。"},{"i":24,"n":"第二十四条","txt":"职业健康检查机构发现有可能因放射性因素导致健康损害的，应当通知放射工作单位，并及时告知放射工作人员本人。 职业健康检查机构发现疑似职业性放射性疾病病人应当通知放射工作人员及其所在放射工作单位，并按规定向放射工作单位所在地卫生行政部门报告。"},{"i":25,"n":"第二十五条","txt":"放射工作单位应当在收到职业健康检查报告的7日内，如实告知放射工作人员，并将检查结论记录在《放射工作人员证》中。 放射工作单位对职业健康检查中发现不宜继续从事放射工作的人员，应当及时调离放射工作岗位，并妥善安置；对需要复查和医学随访观察的放射工作人员，应当及时予以安排。"},{"i":26,"n":"第二十六条","txt":"放射工作单位不得安排怀孕的妇女参与应急处理和有可能造成职业性内照射的工作。哺乳期妇女在其哺乳期间应当避免接受职业性内照射。"},{"i":27,"n":"第二十七条","txt":"放射工作单位应当为放射工作人员建立并终生保存职业健康监护档案。职业健康监护档案应包括以下内容： （一）职业史、既往病史和职业照射接触史； （二）历次职业健康检查结果及评价处理意见； （三）职业性放射性疾病诊疗、医学随访观察等健康资料。"},{"i":28,"n":"第二十八条","txt":"放射工作人员有权查阅、复印本人的职业健康监护档案。放射工作单位应当如实、无偿提供。"},{"i":29,"n":"第二十九条","txt":"放射工作人员职业健康检查、职业性放射性疾病的诊断、鉴定、医疗救治和医学随访观察的费用，由其所在单位承担。"},{"i":30,"n":"第三十条","txt":"职业性放射性疾病的诊断鉴定工作按照《职业病诊断与鉴定管理办法》和国家有关标准执行。"},{"i":31,"n":"第三十一条","txt":"放射工作人员的保健津贴按照国家有关规定执行。"},{"i":32,"n":"第三十二条","txt":"在国家统一规定的休假外，放射工作人员每年可以享受保健休假2～4周。享受寒、暑假的放射工作人员不再享受保健休假。从事放射工作满20年的在岗放射工作人员，可以由所在单位利用休假时间安排健康疗养。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府卫生行政部门应当定期对本行政区域内放射工作单位的放射工作人员职业健康管理进行监督检查。检查内容包括： （一）有关法规和标准执行情况； （二）放射防护措施落实情况； （三）人员培训、职业健康检查、个人剂量监测及其档案管理情况； （四）《放射工作人员证》持证及相关信息记录情况； （五）放射工作人员其他职业健康权益保障情况。"},{"i":34,"n":"第三十四条","txt":"卫生行政执法人员依法进行监督检查时，应当出示证件。被检查的单位应当予以配合，如实反映情况，提供必要的资料，不得拒绝、阻碍、隐瞒。"},{"i":35,"n":"第三十五条","txt":"卫生行政执法人员依法检查时，应当保守被检查单位的技术秘密和业务秘密。"},{"i":36,"n":"第三十六条","txt":"卫生行政部门接到对违反本办法行为的举报后应当及时核实、处理。"},{"i":37,"n":"第三十七条","txt":"放射工作单位违反本办法，有下列行为之一的，按照《职业病防治法》第六十三条处罚： （一）未按照规定组织放射工作人员培训的； （二）未建立个人剂量监测档案的； （三）拒绝放射工作人员查阅、复印其个人剂量监测档案和职业健康监护档案的。"},{"i":38,"n":"第三十八条","txt":"放射工作单位违反本办法，未按照规定组织职业健康检查、未建立职业健康监护档案或者未将检查结果如实告知劳动者的，按照《职业病防治法》第六十四条处罚。"},{"i":39,"n":"第三十九条","txt":"放射工作单位违反本办法，未给从事放射工作的人员办理《放射工作人员证》的，由卫生行政部门责令限期改正，给予警告，并可处3万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"放射工作单位违反本办法，有下列行为之一的，按照《职业病防治法》第六十五条处罚： （一）未按照规定进行个人剂量监测的； （二）个人剂量监测或者职业健康检查发现异常，未采取相应措施的。"},{"i":41,"n":"第四十一条","txt":"放射工作单位违反本办法，有下列行为之一的，按照《职业病防治法》第六十八条处罚： （一）安排未经职业健康检查的劳动者从事放射工作的； （二）安排未满18周岁的人员从事放射工作的； （三）安排怀孕的妇女参加应急处理或者有可能造成内照射工作的，或者安排哺乳期的妇女接受职业性内照射的； （四）安排不符合职业健康标准要求的人员从事放射工作的。"},{"i":42,"n":"第四十二条","txt":"技术服务机构未取得资质擅自从事个人剂量监测技术服务的，或者医疗机构未经批准擅自从事放射工作人员职业健康检查的，按照《职业病防治法》第七十二条处罚。"},{"i":43,"n":"第四十三条","txt":"开展个人剂量监测的职业卫生技术服务机构和承担放射工作人员职业健康检查的医疗机构违反本办法，有下列行为之一的，按照《职业病防治法》第七十三条处罚： （一）超出资质范围从事个人剂量监测技术服务的，或者超出批准范围从事放射工作人员职业健康检查的； （二）未按《职业病防治法》和本办法规定履行法定职责的； （三）出具虚假证明文件的。"},{"i":44,"n":"第四十四条","txt":"卫生行政部门及其工作人员违反本办法，不履行法定职责，造成严重后果的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"放射工作人员职业健康检查项目及职业健康检查表由卫生部制定。"},{"i":46,"n":"第四十六条","txt":"本办法自2007年11月1日起施行。1997年6月5日卫生部发布的《放射工作人员健康管理规定》同时废止。"}],"fangshezhenliaoguanliguiding":[{"i":1,"n":"第一条","txt":"为加强放射诊疗工作的管理，保证医疗质量和医疗安全，保障放射诊疗工作人员、患者和公众的健康权益，依据《中华人民共和国职业病防治法》、《放射性同位素与射线装置安全和防护条例》和《医疗机构管理条例》等法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于开展放射诊疗工作的医疗机构。 本规定所称放射诊疗工作，是指使用放射性同位素、射线装置进行临床医学诊断、治疗和健康检查的活动。"},{"i":3,"n":"第三条","txt":"卫生部负责全国放射诊疗工作的监督管理。 县级以上地方人民政府卫生行政部门负责本行政区域内放射诊疗工作的监督管理。"},{"i":4,"n":"第四条","txt":"放射诊疗工作按照诊疗风险和技术难易程度分为四类管理： （一）放射治疗； （二）核医学； （三）介入放射学； （四）X射线影像诊断。 医疗机构开展放射诊疗工作，应当具备与其开展的放射诊疗工作相适应的条件，经所在地县级以上地方卫生行政部门的放射诊疗技术和医用辐射机构许可（以下简称放射诊疗许可）。"},{"i":5,"n":"第五条","txt":"医疗机构应当采取有效措施，保证放射防护、安全与放射诊疗质量符合有关规定、标准和规范的要求。"},{"i":6,"n":"第六条","txt":"医疗机构开展放射诊疗工作，应当具备以下基本条件： （一）具有经核准登记的医学影像科诊疗科目； （二）具有符合国家相关标准和规定的放射诊疗场所和配套设施； （三）具有质量控制与安全防护专（兼）职管理人员和管理制度，并配备必要的防护用品和监测仪器； （四）产生放射性废气、废液、固体废物的，具有确保放射性废气、废液、固体废物达标排放的处理能力或者可行的处理方案； （五）具有放射事件应急处理预案。"},{"i":7,"n":"第七条","txt":"医疗机构开展不同类别放射诊疗工作，应当分别具有下列人员： （一）开展放射治疗工作的，应当具有： 1.中级以上专业技术职务任职资格的放射肿瘤医师； 2.病理学、医学影像学专业技术人员； 3.大学本科以上学历或中级以上专业技术职务任职资格的医学物理人员； 4.放射治疗技师和维修人员。 （二）开展核医学工作的，应当具有： 1.中级以上专业技术职务任职资格的核医学医师； 2.病理学、医学影像学专业技术人员； 3.大学本科以上学历或中级以上专业技术职务任职资格的技术人员或核医学技师。 （三）开展介入放射学工作的，应当具有： 1.大学本科以上学历或中级以上专业技术职务任职资格的放射影像医师； 2.放射影像技师； 3.相关内、外科的专业技术人员。 （四）开展X射线影像诊断工作的，应当具有专业的放射影像医师。"},{"i":8,"n":"第八条","txt":"医疗机构开展不同类别放射诊疗工作，应当分别具有下列设备： （一）开展放射治疗工作的，至少有一台远距离放射治疗装置，并具有模拟定位设备和相应的治疗计划系统等设备； （二）开展核医学工作的，具有核医学设备及其他相关设备； （三）开展介入放射学工作的，具有带影像增强器的医用诊断X射线机、数字减影装置等设备； （四）开展X射线影像诊断工作的，有医用诊断X射线机或CT机等设备。"},{"i":9,"n":"第九条","txt":"医疗机构应当按照下列要求配备并使用安全防护装置、辐射检测仪器和个人防护用品： （一）放射治疗场所应当按照相应标准设置多重安全联锁系统、剂量监测系统、影像监控、对讲装置和固定式剂量监测报警装置；配备放疗剂量仪、剂量扫描装置和个人剂量报警仪； （二）开展核医学工作的，设有专门的放射性同位素分装、注射、储存场所，放射性废物屏蔽设备和存放场所；配备活度计、放射性表面污染监测仪； （三）介入放射学与其他X射线影像诊断工作场所应当配备工作人员防护用品和受检者个人防护用品。"},{"i":10,"n":"第十条","txt":"医疗机构应当对下列设备和场所设置醒目的警示标志： （一）装有放射性同位素和放射性废物的设备、容器，设有电离辐射标志； （二）放射性同位素和放射性废物储存场所，设有电离辐射警告标志及必要的文字说明； （三）放射诊疗工作场所的入口处，设有电离辐射警告标志； （四）放射诊疗工作场所应当按照有关标准的要求分为控制区、监督区，在控制区进出口及其他适当位置，设有电离辐射警告标志和工作指示灯。"},{"i":11,"n":"第十一条","txt":"医疗机构设置放射诊疗项目，应当按照其开展的放射诊疗工作的类别，分别向相应的卫生行政部门提出建设项目卫生审查、竣工验收和设置放射诊疗项目申请： （一）开展放射治疗、核医学工作的，向省级卫生行政部门申请办理； （二）开展介入放射学工作的，向设区的市级卫生行政部门申请办理； （三）开展X射线影像诊断工作的，向县级卫生行政部门申请办理。 同时开展不同类别放射诊疗工作的，向具有高类别审批权的卫生行政部门申请办理。"},{"i":12,"n":"第十二条","txt":"新建、扩建、改建放射诊疗建设项目，医疗机构应当在建设项目施工前向相应的卫生行政部门提交职业病危害放射防护预评价报告，申请进行建设项目卫生审查。立体定向放射治疗、质子治疗、重离子治疗、带回旋加速器的正电子发射断层扫描诊断等放射诊疗建设项目，还应当提交卫生部指定的放射卫生技术机构出具的预评价报告技术审查意见。 卫生行政部门应当自收到预评价报告之日起三十日内，作出审核决定。经审核符合国家相关卫生标准和要求的，方可施工。"},{"i":13,"n":"第十三条","txt":"医疗机构在放射诊疗建设项目竣工验收前，应当进行职业病危害控制效果评价；并向相应的卫生行政部门提交下列资料，申请进行卫生验收: （一）建设项目竣工卫生验收申请； （二）建设项目卫生审查资料； （三）职业病危害控制效果放射防护评价报告； （四）放射诊疗建设项目验收报告。 立体定向放射治疗、质子治疗、重离子治疗、带回旋加速器的正电子发射断层扫描诊断等放射诊疗建设项目，应当提交卫生部指定的放射卫生技术机构出具的职业病危害控制效果评价报告技术审查意见和设备性能检测报告。"},{"i":14,"n":"第十四条","txt":"医疗机构在开展放射诊疗工作前，应当提交下列资料，向相应的卫生行政部门提出放射诊疗许可申请： （一）放射诊疗许可申请表； （二）《医疗机构执业许可证》或《设置医疗机构批准书》（复印件）； （三）放射诊疗专业技术人员的任职资格证书（复印件）； （四）放射诊疗设备清单； （五）放射诊疗建设项目竣工验收合格证明文件。"},{"i":15,"n":"第十五条","txt":"卫生行政部门对符合受理条件的申请应当即时受理；不符合要求的，应当在五日内一次性告知申请人需要补正的资料或者不予受理的理由。 卫生行政部门应当自受理之日起二十日内作出审查决定，对合格的予以批准, 发给《放射诊疗许可证》；不予批准的，应当书面说明理由。 《放射诊疗许可证》的格式由卫生部统一规定（见附件）。"},{"i":16,"n":"第十六条","txt":"医疗机构取得《放射诊疗许可证》后，到核发《医疗机构执业许可证》的卫生行政执业登记部门办理相应诊疗科目登记手续。执业登记部门应根据许可情况，将医学影像科核准到二级诊疗科目。 未取得《放射诊疗许可证》或未进行诊疗科目登记的，不得开展放射诊疗工作。"},{"i":17,"n":"第十七条","txt":"《放射诊疗许可证》与《医疗机构执业许可证》同时校验，申请校验时应当提交本周期有关放射诊疗设备性能与辐射工作场所的检测报告、放射诊疗工作人员健康监护资料和工作开展情况报告。 医疗机构变更放射诊疗项目的，应当向放射诊疗许可批准机关提出许可变更申请，并提交变更许可项目名称、放射防护评价报告等资料；同时向卫生行政执业登记部门提出诊疗科目变更申请，提交变更登记项目及变更理由等资料。 卫生行政部门应当自收到变更申请之日起二十日内做出审查决定。未经批准不得变更。"},{"i":18,"n":"第十八条","txt":"有下列情况之一的，由原批准部门注销放射诊疗许可，并登记存档，予以公告： （一）医疗机构申请注销的； （二）逾期不申请校验或者擅自变更放射诊疗科目的； （三）校验或者办理变更时不符合相关要求，且逾期不改进或者改进后仍不符合要求的； （四）歇业或者停止诊疗科目连续一年以上的； （五）被卫生行政部门吊销《医疗机构执业许可证》的。"},{"i":19,"n":"第十九条","txt":"医疗机构应当配备专（兼）职的管理人员，负责放射诊疗工作的质量保证和安全防护。其主要职责是： （一）组织制定并落实放射诊疗和放射防护管理制度； （二）定期组织对放射诊疗工作场所、设备和人员进行放射防护检测、监测和检查； （三）组织本机构放射诊疗工作人员接受专业技术、放射防护知识及有关规定的培训和健康检查； （四）制定放射事件应急预案并组织演练； （五）记录本机构发生的放射事件并及时报告卫生行政部门。"},{"i":20,"n":"第二十条","txt":"医疗机构的放射诊疗设备和检测仪表，应当符合下列要求： （一）新安装、维修或更换重要部件后的设备，应当经省级以上卫生行政部门资质认证的检测机构对其进行检测，合格后方可启用； （二）定期进行稳定性检测、校正和维护保养，由省级以上卫生行政部门资质认证的检测机构每年至少进行一次状态检测； （三）按照国家有关规定检验或者校准用于放射防护和质量控制的检测仪表； （四）放射诊疗设备及其相关设备的技术指标和安全、防护性能，应当符合有关标准与要求。 不合格或国家有关部门规定淘汰的放射诊疗设备不得购置、使用、转让和出租。"},{"i":21,"n":"第二十一条","txt":"医疗机构应当定期对放射诊疗工作场所、放射性同位素储存场所和防护设施进行放射防护检测，保证辐射水平符合有关规定或者标准。 放射性同位素不得与易燃、易爆、腐蚀性物品同库储存；储存场所应当采取有效的防泄漏等措施，并安装必要的报警装置。 放射性同位素储存场所应当有专人负责，有完善的存入、领取、归还登记和检查的制度，做到交接严格，检查及时，账目清楚，账物相符，记录资料完整。"},{"i":22,"n":"第二十二条","txt":"放射诊疗工作人员应当按照有关规定配戴个人剂量计。"},{"i":23,"n":"第二十三条","txt":"医疗机构应当按照有关规定和标准，对放射诊疗工作人员进行上岗前、在岗期间和离岗时的健康检查，定期进行专业及防护知识培训，并分别建立个人剂量、职业健康管理和教育培训档案。"},{"i":24,"n":"第二十四条","txt":"医疗机构应当制定与本单位从事的放射诊疗项目相适应的质量保证方案，遵守质量保证监测规范。"},{"i":25,"n":"第二十五条","txt":"放射诊疗工作人员对患者和受检者进行医疗照射时，应当遵守医疗照射正当化和放射防护最优化的原则，有明确的医疗目的，严格控制受照剂量；对邻近照射野的敏感器官和组织进行屏蔽防护，并事先告知患者和受检者辐射对健康的影响。"},{"i":26,"n":"第二十六条","txt":"医疗机构在实施放射诊断检查前应当对不同检查方法进行利弊分析，在保证诊断效果的前提下，优先采用对人体健康影响较小的诊断技术。 实施检查应当遵守下列规定： （一）严格执行检查资料的登记、保存、提取和借阅制度，不得因资料管理、受检者转诊等原因使受检者接受不必要的重复照射； （二）不得将核素显像检查和X射线胸部检查列入对婴幼儿及少年儿童体检的常规检查项目； （三）对育龄妇女腹部或骨盆进行核素显像检查或X射线检查前，应问明是否怀孕；非特殊需要，对受孕后八至十五周的育龄妇女，不得进行下腹部放射影像检查； （四）应当尽量以胸部X射线摄影代替胸部荧光透视检查； （五）实施放射性药物给药和X射线照射操作时，应当禁止非受检者进入操作现场；因患者病情需要其他人员陪检时，应当对陪检者采取防护措施。"},{"i":27,"n":"第二十七条","txt":"医疗机构使用放射影像技术进行健康普查的，应当经过充分论证，制定周密的普查方案，采取严格的质量控制措施。"},{"i":28,"n":"第二十八条","txt":"开展放射治疗的医疗机构，在对患者实施放射治疗前，应当进行影像学、病理学及其他相关检查，严格掌握放射治疗的适应证。对确需进行放射治疗的，应当制定科学的治疗计划，并按照下列要求实施： （一）对体外远距离放射治疗，放射诊疗工作人员在进入治疗室前，应首先检查操作控制台的源位显示，确认放射线束或放射源处于关闭位时，方可进入； （二）对近距离放射治疗，放射诊疗工作人员应当使用专用工具拿取放射源，不得徒手操作；对接受敷贴治疗的患者采取安全护理，防止放射源被患者带走或丢失； （三）在实施永久性籽粒插植治疗时，放射诊疗工作人员应随时清点所使用的放射性籽粒，防止在操作过程中遗失；放射性籽粒植入后，必须进行医学影像学检查，确认植入部位和放射性籽粒的数量； （四）治疗过程中，治疗现场至少应有2名放射诊疗工作人员，并密切注视治疗装置的显示及病人情况，及时解决治疗中出现的问题；严禁其他无关人员进入治疗场所； （五"},{"i":29,"n":"第二十九条","txt":"开展核医学诊疗的医疗机构，应当遵守相应的操作规范、规程，防止放射性同位素污染人体、设备、工作场所和环境；按照有关标准的规定对接受体内放射性药物诊治的患者进行控制，避免其他患者和公众受到超过允许水平的照射。"},{"i":30,"n":"第三十条","txt":"核医学诊疗产生的放射性固体废物、废液及患者的放射性排出物应当单独收集，与其他废物、废液分开存放，按照国家有关规定处理。"},{"i":31,"n":"第三十一条","txt":"医疗机构应当制定防范和处置放射事件的应急预案；发生放射事件后应当立即采取有效应急救援和控制措施，防止事件的扩大和蔓延。"},{"i":32,"n":"第三十二条","txt":"医疗机构发生下列放射事件情形之一的，应当及时进行调查处理，如实记录，并按照有关规定及时报告卫生行政部门和有关部门： （一）诊断放射性药物实际用量偏离处方剂量50%以上的； （二）放射治疗实际照射剂量偏离处方剂量25%以上的； （三）人员误照或误用放射性药物的； （四）放射性同位素丢失、被盗和污染的； （五）设备故障或人为失误引起的其他放射事件。"},{"i":33,"n":"第三十三条","txt":"医疗机构应当加强对本机构放射诊疗工作的管理，定期检查放射诊疗管理法律、法规、规章等制度的落实情况，保证放射诊疗的医疗质量和医疗安全。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府卫生行政部门应当定期对本行政区域内开展放射诊疗活动的医疗机构进行监督检查。检查内容包括： （一）执行法律、法规、规章、标准和规范等情况； （二）放射诊疗规章制度和工作人员岗位责任制等制度的落实情况； （三）健康监护制度和防护措施的落实情况； （四）放射事件调查处理和报告情况。"},{"i":35,"n":"第三十五条","txt":"卫生行政部门的执法人员依法进行监督检查时，应当出示证件；被检查的单位应当予以配合，如实反映情况，提供必要的资料，不得拒绝、阻碍、隐瞒。"},{"i":36,"n":"第三十六条","txt":"卫生行政部门的执法人员或者卫生行政部门授权实施检查、检测的机构及其工作人员依法检查时，应当保守被检查单位的技术秘密和业务秘密。"},{"i":37,"n":"第三十七条","txt":"卫生行政部门应当加强监督执法队伍建设，提高执法人员的业务素质和执法水平，建立健全对执法人员的监督管理制度。"},{"i":38,"n":"第三十八条","txt":"医疗机构有下列情形之一的，由县级以上卫生行政部门给予警告、责令限期改正，并可以根据情节处以3000元以下的罚款；情节严重的，吊销其《医疗机构执业许可证》。 （一）未取得放射诊疗许可从事放射诊疗工作的； （二）未办理诊疗科目登记或者未按照规定进行校验的； （三）未经批准擅自变更放射诊疗项目或者超出批准范围从事放射诊疗工作的。"},{"i":39,"n":"第三十九条","txt":"医疗机构使用不具备相应资质的人员从事放射诊疗工作的，由县级以上卫生行政部门责令限期改正，并可以处以5000元以下的罚款；情节严重的，吊销其《医疗机构执业许可证》。"},{"i":40,"n":"第四十条","txt":"医疗机构违反建设项目卫生审查、竣工验收有关规定的，按照《中华人民共和国职业病防治法》的规定进行处罚。"},{"i":41,"n":"第四十一条","txt":"医疗机构违反本规定，有下列行为之一的，由县级以上卫生行政部门给予警告，责令限期改正；并可处一万元以下的罚款： （一）购置、使用不合格或国家有关部门规定淘汰的放射诊疗设备的； （二）未按照规定使用安全防护装置和个人防护用品的； （三）未按照规定对放射诊疗设备、工作场所及防护设施进行检测和检查的； （四）未按照规定对放射诊疗工作人员进行个人剂量监测、健康检查、建立个人剂量和健康档案的； （五）发生放射事件并造成人员健康严重损害的； （六）发生放射事件未立即采取应急救援和控制措施或者未按照规定及时报告的； （七）违反本规定的其他情形。"},{"i":42,"n":"第四十二条","txt":"卫生行政部门及其工作人员违反本规定，对不符合条件的医疗机构发放《放射诊疗许可证》的，或者不履行法定职责，造成放射事故的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"本规定中下列用语的含义： 放射治疗：是指利用电离辐射的生物效应治疗肿瘤等疾病的技术。 核医学：是指利用放射性同位素诊断或治疗疾病或进行医学研究的技术。 介入放射学：是指在医学影像系统监视引导下，经皮针穿刺或引入导管做抽吸注射、引流或对管腔、血管等做成型、灌注、栓塞等，以诊断与治疗疾病的技术。 X射线影像诊断：是指利用X射线的穿透等性质取得人体内器官与组织的影像信息以诊断疾病的技术。"},{"i":44,"n":"第四十四条","txt":"已开展放射诊疗项目的医疗机构应当于2006年9月1日前按照本办法规定，向卫生行政部门申请放射诊疗技术和医用辐射机构许可，并重新核定医学影像科诊疗科目。"},{"i":45,"n":"第四十五条","txt":"本规定由卫生部负责解释。"},{"i":46,"n":"第四十六条","txt":"本规定自2006年3月1日起施行。2001年10月23日发布的《放射工作卫生防护管理办法》同时废止。"}],"xinshengerjibingshaichaguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范新生儿疾病筛查的管理，保证新生儿疾病筛查工作质量，依据《中华人民共和国母婴保健法》和《中华人民共和国母婴保健法实施办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称新生儿疾病筛查是指在新生儿期对严重危害新生儿健康的先天性、遗传性疾病施行专项检查，提供早期诊断和治疗的母婴保健技术。"},{"i":3,"n":"第三条","txt":"本办法规定的全国新生儿疾病筛查病种包括先天性甲状腺功能减低症、苯丙酮尿症等新生儿遗传代谢病和听力障碍。 卫生部根据需要对全国新生儿疾病筛查病种进行调整。 省、自治区、直辖市人民政府卫生行政部门可以根据本行政区域的医疗资源、群众需求、疾病发生率等实际情况，增加本行政区域内新生儿疾病筛查病种，并报卫生部备案。"},{"i":4,"n":"第四条","txt":"新生儿遗传代谢病筛查程序包括血片采集、送检、实验室检测、阳性病例确诊和治疗。 新生儿听力筛查程序包括初筛、复筛、阳性病例确诊和治疗。"},{"i":5,"n":"第五条","txt":"新生儿疾病筛查是提高出生人口素质，减少出生缺陷的预防措施之一。各级各类医疗机构和医务人员应当在工作中开展新生儿疾病筛查的宣传教育工作。"},{"i":6,"n":"第六条","txt":"卫生部负责全国新生儿疾病筛查的监督管理工作，根据医疗需求、技术发展状况、组织与管理的需要等实际情况制定全国新生儿疾病筛查工作规划和技术规范。 省、自治区、直辖市人民政府卫生行政部门负责本行政区域新生儿疾病筛查的监督管理工作，建立新生儿疾病筛查管理网络，组织医疗机构开展新生儿疾病筛查工作。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府卫生行政部门应当根据本行政区域的实际情况，制定本地区新生儿遗传代谢病筛查中心和新生儿听力筛查中心（以下简称新生儿疾病筛查中心）设置规划，指定具备能力的医疗机构为本行政区域新生儿疾病筛查中心。 新生儿疾病筛查中心应当开展以下工作： （一）开展新生儿遗传代谢疾病筛查的实验室检测、阳性病例确诊和治疗或者听力筛查阳性病例确诊、治疗； （二）掌握本地区新生儿疾病筛查、诊断、治疗、转诊情况； （三）负责本地区新生儿疾病筛查人员培训、技术指导、质量管理和相关的健康宣传教育； （四）承担本地区新生儿疾病筛查有关信息的收集、统计、分析、上报和反馈工作。 开展新生儿疾病筛查的医疗机构应当及时提供病例信息，协助新生儿疾病筛查中心做好前款工作。"},{"i":8,"n":"第八条","txt":"诊疗科目中设有产科或者儿科的医疗机构，应当按照《新生儿疾病筛查技术规范》的要求，开展新生儿遗传代谢病血片采集及送检、新生儿听力初筛及复筛工作。 不具备开展新生儿疾病筛查血片采集、新生儿听力初筛和复筛服务条件的医疗机构，应当告知新生儿监护人到有条件的医疗机构进行新生儿疾病筛查血片采集及听力筛查。"},{"i":9,"n":"第九条","txt":"新生儿遗传代谢病筛查实验室设在新生儿疾病筛查中心，并应当具备下列条件： （一）具有与所开展工作相适应的卫生专业技术人员，具有与所开展工作相适应的技术和设备； （二）符合《医疗机构临床实验室管理办法》的规定； （三）符合《新生儿疾病筛查技术规范》的要求。"},{"i":10,"n":"第十条","txt":"新生儿遗传代谢病筛查中心发现新生儿遗传代谢病阳性病例时，应当及时通知新生儿监护人进行确诊。 开展新生儿听力初筛、复筛的医疗机构发现新生儿疑似听力障碍的，应当及时通知新生儿监护人到新生儿听力筛查中心进行听力确诊。"},{"i":11,"n":"第十一条","txt":"新生儿疾病筛查遵循自愿和知情选择的原则。医疗机构在实施新生儿疾病筛查前，应当将新生儿疾病筛查的项目、条件、方式、灵敏度和费用等情况如实告知新生儿的监护人，并取得签字同意。"},{"i":12,"n":"第十二条","txt":"从事新生儿疾病筛查的医疗机构和人员，应当严格执行新生儿疾病筛查技术规范，保证筛查质量。 医疗机构发现新生儿患有遗传代谢病和听力障碍的，应当及时告知其监护人，并提出治疗和随诊建议。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府卫生行政部门根据本行政区域的具体情况，协调有关部门，采取措施，为患有遗传代谢病和听力障碍的新生儿提供治疗方面的便利条件。 有条件的医疗机构应当开展新生儿遗传代谢病的治疗工作。"},{"i":14,"n":"第十四条","txt":"卫生部组织专家定期对新生儿疾病筛查中心进行抽查评估。经评估不合格的，省级人民政府卫生行政部门应当及时撤销其资格。 新生儿遗传代谢病筛查实验室应当接受卫生部临床检验中心的质量监测和检查。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府卫生行政部门应当对本行政区域内开展新生儿疾病筛查工作的医疗机构进行监督检查。"},{"i":16,"n":"第十六条","txt":"医疗机构未经省、自治区、直辖市人民政府卫生行政部门指定擅自开展新生儿遗传代谢病筛查实验室检测的，按照《医疗机构管理条例》第四十七条的规定予以处罚。"},{"i":17,"n":"第十七条","txt":"开展新生儿疾病筛查的医疗机构违反本办法规定，有下列行为之一的，由县级以上地方人民政府卫生行政部门责令改正，通报批评，给予警告： （一）违反《新生儿疾病筛查技术规范》的； （二）未履行告知程序擅自进行新生儿疾病筛查的； （三）未按规定进行实验室质量监测、检查的； （四）违反本办法其他规定的。"},{"i":18,"n":"第十八条","txt":"省、自治区、直辖市人民政府卫生行政部门可以依据本办法和当地实际制定实施细则。"},{"i":19,"n":"第十九条","txt":"本办法公布后6个月内，省、自治区、直辖市人民政府卫生行政部门应当组织专家对开展新生儿疾病筛查的医疗机构进行评估考核，指定新生儿疾病筛查中心。"},{"i":20,"n":"第二十条","txt":"本办法自2009年6月1日起施行。"}],"xinshipinyuanliaoanquanxingshenchaguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范新食品原料安全性评估材料审查工作，根据《中华人民共和国食品安全法》及其实施条例的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"新食品原料是指在我国无传统食用习惯的以下物品： （一）动物、植物和微生物； （二）从动物、植物和微生物中分离的成分； （三）原有结构发生改变的食品成分； （四）其他新研制的食品原料。"},{"i":3,"n":"第三条","txt":"新食品原料应当具有食品原料的特性，符合应当有的营养要求，且无毒、无害，对人体健康不造成任何急性、亚急性、慢性或者其他潜在性危害。"},{"i":4,"n":"第四条","txt":"新食品原料应当经过国家卫生计生委安全性审查后，方可用于食品生产经营。"},{"i":5,"n":"第五条","txt":"国家卫生计生委负责新食品原料安全性评估材料的审查和许可工作。 国家卫生计生委新食品原料技术审评机构（以下简称审评机构）负责新食品原料安全性技术审查，提出综合审查结论及建议。"},{"i":6,"n":"第六条","txt":"拟从事新食品原料生产、使用或者进口的单位或者个人（以下简称申请人），应当提出申请并提交以下材料： （一）申请表； （二）新食品原料研制报告； （三）安全性评估报告； （四）生产工艺； （五）执行的相关标准（包括安全要求、质量规格、检验方法等）； （六）标签及说明书； （七）国内外研究利用情况和相关安全性评估资料； （八）有助于评审的其他资料。 另附未启封的产品样品1件或者原料30克。"},{"i":7,"n":"第七条","txt":"申请进口新食品原料的，除提交第六条规定的材料外，还应当提交以下材料： （一）出口国（地区）相关部门或者机构出具的允许该产品在本国（地区）生产或者销售的证明材料； （二）生产企业所在国（地区）有关机构或者组织出具的对生产企业审查或者认证的证明材料。"},{"i":8,"n":"第八条","txt":"申请人应当如实提交有关材料，反映真实情况，对申请材料内容的真实性负责，并承担法律责任。"},{"i":9,"n":"第九条","txt":"申请人在提交本办法第六条第一款第二项至第六项材料时，应当注明其中不涉及商业秘密，可以向社会公开的内容。"},{"i":10,"n":"第十条","txt":"国家卫生计生委受理新食品原料申请后，向社会公开征求意见。"},{"i":11,"n":"第十一条","txt":"国家卫生计生委自受理新食品原料申请之日起60日内，应当组织专家对新食品原料安全性评估材料进行审查，作出审查结论。"},{"i":12,"n":"第十二条","txt":"审查过程中需要补充资料的，应当及时书面告知申请人，申请人应当按照要求及时补充有关资料。 根据审查工作需要，可以要求申请人现场解答有关技术问题，申请人应当予以配合。"},{"i":13,"n":"第十三条","txt":"审查过程中需要对生产工艺进行现场核查的，可以组织专家对新食品原料研制及生产现场进行核查，并出具现场核查意见，专家对出具的现场核查意见承担责任。省级卫生监督机构应当予以配合。 参加现场核查的专家不参与该产品安全性评估材料的审查表决。"},{"i":14,"n":"第十四条","txt":"新食品原料安全性评估材料审查和许可的具体程序按照《行政许可法》、《卫生行政许可管理办法》等有关法律法规规定执行。"},{"i":15,"n":"第十五条","txt":"审评机构提出的综合审查结论，应当包括安全性审查结果和社会稳定风险评估结果。"},{"i":16,"n":"第十六条","txt":"国家卫生计生委根据新食品原料的安全性审查结论，对符合食品安全要求的，准予许可并予以公告；对不符合食品安全要求的，不予许可并书面说明理由。 对与食品或者已公告的新食品原料具有实质等同性的，应当作出终止审查的决定，并书面告知申请人。"},{"i":17,"n":"第十七条","txt":"根据新食品原料的不同特点，公告可以包括以下内容： （一）名称； （二）来源； （三）生产工艺； （四）主要成分； （五）质量规格要求； （六）标签标识要求； （七）其他需要公告的内容。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，国家卫生计生委应当及时组织对已公布的新食品原料进行重新审查： （一）随着科学技术的发展，对新食品原料的安全性产生质疑的； （二）有证据表明新食品原料的安全性可能存在问题的； （三）其他需要重新审查的情形。 对重新审查不符合食品安全要求的新食品原料，国家卫生计生委可以撤销许可。"},{"i":19,"n":"第十九条","txt":"新食品原料生产单位应当按照新食品原料公告要求进行生产，保证新食品原料的食用安全。"},{"i":20,"n":"第二十条","txt":"食品中含有新食品原料的，其产品标签标识应当符合国家法律、法规、食品安全标准和国家卫生计生委公告要求。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，生产或者使用未经安全性评估的新食品原料的，按照《食品安全法》的有关规定处理。"},{"i":22,"n":"第二十二条","txt":"申请人隐瞒有关情况或者提供虚假材料申请新食品原料许可的，国家卫生计生委不予受理或者不予许可，并给予警告，且申请人在一年内不得再次申请该新食品原料许可。 以欺骗、贿赂等不正当手段通过新食品原料安全性审查并取得许可的，国家卫生计生委应当撤销许可，且申请人在三年内不得再次申请新食品原料许可。"},{"i":23,"n":"第二十三条","txt":"本办法下列用语的含义： 实质等同，是指如某个新申报的食品原料与食品或者已公布的新食品原料在种属、来源、生物学特征、主要成分、食用部位、使用量、使用范围和应用人群等方面相同，所采用工艺和质量要求基本一致，可以视为它们是同等安全的，具有实质等同性。 传统食用习惯，是指某种食品在省辖区域内有30年以上作为定型或者非定型包装食品生产经营的历史，并且未载入《中华人民共和国药典》。"},{"i":24,"n":"第二十四条","txt":"本办法所称的新食品原料不包括转基因食品、保健食品、食品添加剂新品种。转基因食品、保健食品、食品添加剂新品种的管理依照国家有关法律法规执行。"},{"i":25,"n":"第二十五条","txt":"本办法自2013年10月1日起施行。原卫生部2007年7月2日公布的《新资源食品管理办法》同时废止。"}],"muyingbaojianzhuanxiangjishufuwuxukejirenyuanzigega83eee":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国母婴保健法》第三十二条、第三十三条和《中华人民共和国母婴保健法实施办法》第三十五条的规定制定本办法。"},{"i":2,"n":"第二条","txt":"凡开展《中华人民共和国母婴保健法》及其实施办法规定的婚前医学检查、遗传病诊断、产前诊断、施行助产技术、结扎手术和终止妊娠手术技术服务的医疗保健机构，必须符合本办法规定的条件，经卫生健康主管部门审查批准，取得《母婴保健技术服务执业许可证》。"},{"i":3,"n":"第三条","txt":"施行助产技术、结扎手术、终止妊娠手术的机构和人员的审批，由县级卫生健康主管部门负责；开展婚前医学检查的机构和人员的审批，由设区的市级卫生健康主管部门负责；开展遗传病诊断、产前诊断的机构和人员的审批，由省级卫生健康主管部门负责。"},{"i":4,"n":"第四条","txt":"申请开展婚前医学检查、遗传病诊断、产前诊断以及施行助产技术、结扎手术、终止妊娠手术的医疗保健机构，必须同时具备下列条件： （一） 符合当地医疗保健机构设置规划； （二） 取得《医疗机构执业许可证》； （三） 符合母婴保健专项技术服务基本标准； （四） 法律法规规章规定的其他条件。"},{"i":5,"n":"第五条","txt":"申请婚前医学检查、遗传病诊断、产前诊断以及施行助产技术、结扎手术、终止妊娠手术许可的医疗保健机构，必须向审批机关提交《母婴保健技术服务执业许可申请登记书》并交验下列材料： （一）《医疗机构执业许可证》及其副本； （二）有关医师的《母婴保健技术考核合格证书》或者加注母婴保健技术考核合格及技术类别的《医师执业证书》； （三）可行性报告； （四）与拟开展母婴保健专项技术相应的技术、设备条件及人员配备情况； （五）开展母婴保健专项技术的规章制度； （六）法律法规规章规定的其他材料。"},{"i":6,"n":"第六条","txt":"审批机关受理申请后，应当在45日内，按照本办法规定的条件及母婴保健专项技术服务基本标准进行审查和核实。经审核合格的，发给《母婴保健技术服务执业许可证》；审核不合格的，将审核结果和理由以书面形式通知申请人。"},{"i":7,"n":"第七条","txt":"《母婴保健技术服务执业许可证》每3年校验1次，校验由原登记机关办理。"},{"i":8,"n":"第八条","txt":"申请变更《母婴保健技术服务执业许可证》的许可项目的，应当依照本办法规定的程序重新报批。"},{"i":9,"n":"第九条","txt":"医疗保健机构应当把《母婴保健技术服务执业许可证》悬挂在明显处所。"},{"i":10,"n":"第十条","txt":"凡从事《中华人民共和国母婴保健法》及其实施办法规定的婚前医学检查、遗传病诊断、产前诊断以及施行助产技术、结扎手术、终止妊娠手术技术服务的人员，必须符合母婴保健专项技术服务基本标准的有关规定，经考核合格，取得《母婴保健技术考核合格证书》或者在《医师执业证书》上加注母婴保健技术考核合格及技术类别。"},{"i":11,"n":"第十一条","txt":"从事遗传病诊断、产前诊断技术服务人员的资格考核，由省级卫生健康主管部门负责；从事婚前医学检查技术服务人员的资格考核，由设区的市级卫生健康主管部门负责；从事助产技术、结扎手术和终止妊娠手术技术服务人员的资格考核，由县级卫生健康主管部门负责。 母婴保健技术人员资格考核内容由国家卫生健康委规定。"},{"i":12,"n":"第十二条","txt":"母婴保健技术人员资格考核办法由各省、自治区、直辖市卫生健康主管部门规定。"},{"i":13,"n":"第十三条","txt":"经考核合格，具备母婴保健技术服务相应资格的卫生技术人员，不得私自或者在未取得《母婴保健技术服务执业许可证》的机构中开展母婴保健专项技术服务。"},{"i":14,"n":"第十四条","txt":"《母婴保健技术服务执业许可证》和《母婴保健技术考核合格证书》应当妥善保管，不得出借或者涂改，禁止伪造、变造、盗用以及买卖。"},{"i":15,"n":"第十五条","txt":"《母婴保健技术服务执业许可证》和《母婴保健技术考核合格证书》遗失后，应当及时报告原发证机关，并申请办理补发证书的手续。"},{"i":16,"n":"第十六条","txt":"本办法实施前已经开展婚前医学检查、遗传病诊断、产前诊断以及施行结扎手术和终止妊娠手术的医疗保健机构，应当在本办法施行后的6个月内，按照本办法的规定补办审批手续。"},{"i":17,"n":"第十七条","txt":"《母婴保健技术服务执业许可证》和《母婴保健技术考核合格证书》由国家卫生健康委统一印制。"},{"i":18,"n":"第十八条","txt":"本办法由国家卫生健康委负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自发布之日起施行。"}],"xiaoduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强消毒管理，预防和控制感染性疾病的传播，保障人体健康，根据《中华人民共和国传染病防治法》及其实施办法的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于医疗卫生机构、消毒服务机构以及从事消毒产品生产、经营活动的单位和个人。 其他需要消毒的场所和物品管理也适用于本办法。"},{"i":3,"n":"第三条","txt":"国家卫生计生委主管全国消毒监督管理工作。 铁路、交通卫生主管机构依照本办法负责本系统的消毒监督管理工作。"},{"i":4,"n":"第四条","txt":"医疗卫生机构应当建立消毒管理组织，制定消毒管理制度，执行国家有关规范、标准和规定，定期开展消毒与灭菌效果检测工作。"},{"i":5,"n":"第五条","txt":"医疗卫生机构工作人员应当接受消毒技术培训、掌握消毒知识，并按规定严格执行消毒隔离制度。"},{"i":6,"n":"第六条","txt":"医疗卫生机构使用的进入人体组织或无菌器官的医疗用品必须达到灭菌要求。各种注射、穿刺、采血器具应当一人一用一灭菌。凡接触皮肤、粘膜的器械和用品必须达到消毒要求。 医疗卫生机构使用的一次性使用医疗用品用后应当及时进行无害化处理。"},{"i":7,"n":"第七条","txt":"医疗卫生机构购进消毒产品必须建立并执行进货检查验收制度。"},{"i":8,"n":"第八条","txt":"医疗卫生机构的环境、物品应当符合国家有关规范、标准和规定。排放废弃的污水、污物应当按照国家有关规定进行无害化处理。运送传染病病人及其污染物品的车辆、工具必须随时进行消毒处理。"},{"i":9,"n":"第九条","txt":"医疗卫生机构发生感染性疾病暴发、流行时，应当及时报告当地卫生计生行政部门，并采取有效消毒措施。"},{"i":10,"n":"第十条","txt":"加工、出售、运输被传染病病原体污染或者来自疫区可能被传染病病原体污染的皮毛，应当进行消毒处理。"},{"i":11,"n":"第十一条","txt":"托幼机构应当健全和执行消毒管理制度，对室内空气、餐（饮）具、毛巾、玩具和其他幼儿活动的场所及接触的物品定期进行消毒。"},{"i":12,"n":"第十二条","txt":"出租衣物及洗涤衣物的单位和个人，应当对相关物品及场所进行消毒。"},{"i":13,"n":"第十三条","txt":"从事致病微生物实验的单位应当执行有关的管理制度、操作规程，对实验的器材、污染物品等按规定进行消毒，防止实验室感染和致病微生物的扩散。"},{"i":14,"n":"第十四条","txt":"殡仪馆、火葬场内与遗体接触的物品及运送遗体的车辆应当及时消毒。"},{"i":15,"n":"第十五条","txt":"招用流动人员200人以上的用工单位，应当对流动人员集中生活起居的场所及使用的物品定期进行消毒。"},{"i":16,"n":"第十六条","txt":"疫源地的消毒应当执行国家有关规范、标准和规定。"},{"i":17,"n":"第十七条","txt":"公共场所、食品、生活饮用水、血液制品的消毒管理，按有关法律、法规的规定执行。"},{"i":18,"n":"第十八条","txt":"消毒产品应当符合国家有关规范、标准和规定。"},{"i":19,"n":"第十九条","txt":"消毒产品的生产应当符合国家有关规范、标准和规定，对生产的消毒产品应当进行检验，不合格者不得出厂。"},{"i":20,"n":"第二十条","txt":"消毒剂、消毒器械和卫生用品生产企业取得工商行政管理部门颁发的营业执照后，还应当取得所在地省级卫生计生行政部门发放的卫生许可证，方可从事消毒产品的生产。"},{"i":21,"n":"第二十一条","txt":"省级卫生计生行政部门应当自受理消毒产品生产企业的申请之日起二十日内作出是否批准的决定。对符合《消毒产品生产企业卫生规范》要求的，发给卫生许可证；对不符合的，不予批准，并说明理由。"},{"i":22,"n":"第二十二条","txt":"消毒产品生产企业卫生许可证编号格式为：（省、自治区、直辖市简称）卫消证字（发证年份）第XXXX号。 消毒产品生产企业卫生许可证的生产项目分为消毒剂类、消毒器械类、卫生用品类。"},{"i":23,"n":"第二十三条","txt":"消毒产品生产企业卫生许可证有效期为四年。 消毒产品生产企业卫生许可证有效期届满三十日前，生产企业应当向原发证机关申请延续。经审查符合要求的，予以延续，换发新证。新证延用原卫生许可证编号。"},{"i":24,"n":"第二十四条","txt":"消毒产品生产企业迁移厂址或者另设分厂（车间），应当按本办法规定向生产场所所在地的省级卫生计生行政部门申请消毒产品生产企业卫生许可证。 产品包装上标注的厂址、卫生许可证号应当是实际生产地地址和其卫生许可证号。"},{"i":25,"n":"第二十五条","txt":"取得卫生许可证的消毒产品生产企业变更企业名称、法定代表人或者生产类别的，应当向原发证机关提出申请，经审查同意，换发新证。新证延用原卫生许可证编号。"},{"i":26,"n":"第二十六条","txt":"生产、进口利用新材料、新工艺技术和新杀菌原理生产消毒剂和消毒器械（以下简称新消毒产品）应当按照本办法规定取得国家卫生计生委颁发的卫生许可批件。 生产、进口新消毒产品外的消毒剂、消毒器械和卫生用品中的抗（抑）菌制剂，生产、进口企业应当按照有关规定进行卫生安全评价，符合卫生标准和卫生规范要求。产品上市时要将卫生安全评价报告向省级卫生计生行政部门备案，备案应当按照规定要求提供材料。"},{"i":27,"n":"第二十七条","txt":"生产企业申请新消毒产品卫生许可批件、在华责任单位申请进口新消毒产品卫生许可批件的，应当按照国家卫生计生委新消毒产品卫生行政许可管理规定的要求，向国家卫生计生委提出申请。国家卫生计生委应当按照有关法律法规和相关规定，作出是否批准的决定。 国家卫生计生委对批准的新消毒产品，发给卫生许可批件，批准文号格式为：卫消新准字（年份）第XXXX号。不予批准的，应当说明理由。"},{"i":28,"n":"第二十八条","txt":"新消毒产品卫生许可批件的有效期为四年。"},{"i":29,"n":"第二十九条","txt":"国家卫生计生委定期公告取得卫生行政许可的新消毒产品批准内容。公告发布之日起，列入公告的同类产品不再按新消毒产品进行卫生行政许可。"},{"i":30,"n":"第三十条","txt":"经营者采购消毒产品时，应当索取下列有效证件： （一）生产企业卫生许可证复印件； （二）产品卫生安全评价报告或者新消毒产品卫生许可批件复印件。 有效证件的复印件应当加盖原件持有者的印章。"},{"i":31,"n":"第三十一条","txt":"消毒产品的命名、标签（含说明书）应当符合国家卫生计生委的有关规定。 消毒产品的标签（含说明书）和宣传内容必须真实，不得出现或暗示对疾病的治疗效果。"},{"i":32,"n":"第三十二条","txt":"禁止生产经营下列消毒产品： （一）无生产企业卫生许可证或新消毒产品卫生许可批准文件的； （二）产品卫生安全评价不合格或产品卫生质量不符合要求的。"},{"i":33,"n":"第三十三条","txt":"消毒服务机构应当符合以下要求： （一）具备符合国家有关规范、标准和规定的消毒与灭菌设备； （二）其消毒与灭菌工艺流程和工作环境必须符合卫生要求； （三）具有能对消毒与灭菌效果进行检测的人员和条件，建立自检制度； （四）用环氧乙烷和电离辐射的方法进行消毒与灭菌的，其安全与环境保护等方面的要求按国家有关规定执行。"},{"i":34,"n":"第三十四条","txt":"消毒服务机构不得购置和使用不符合本办法规定的消毒产品。"},{"i":35,"n":"第三十五条","txt":"消毒服务机构应当接受当地卫生计生行政部门的监督。"},{"i":36,"n":"第三十六条","txt":"县级以上卫生计生行政部门对消毒工作行使下列监督管理职权： （一）对有关机构、场所和物品的消毒工作进行监督检查； （二）对消毒产品生产企业执行《消毒产品生产企业卫生规范》情况进行监督检查； （三）对消毒产品的卫生质量进行监督检查； （四）对消毒服务机构的消毒服务质量进行监督检查； （五）对违反本办法的行为采取行政控制措施； （六）对违反本办法的行为给予行政处罚。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，国家卫生计生委可以对已获得卫生许可批件的新消毒产品进行重新审查： （一）产品原料、杀菌原理和生产工艺受到质疑的； （二）产品安全性、消毒效果受到质疑的。"},{"i":38,"n":"第三十八条","txt":"新消毒产品卫生许可批件的持有者应当在接到国家卫生计生委重新审查通知之日起30日内，按照通知的有关要求提交材料。超过期限未提交有关材料的，视为放弃重新审查，国家卫生计生委可以注销产品卫生许可批件。"},{"i":39,"n":"第三十九条","txt":"国家卫生计生委自收到重新审查所需的全部材料之日起30日内，应当作出重新审查决定。有下列情形之一的，注销产品卫生许可批件： （一）产品原料、杀菌原理和生产工艺不符合利用新材料、新工艺技术和新杀菌原理生产消毒剂和消毒器械的判定依据的； （二）产品安全性、消毒效果达不到要求的。"},{"i":40,"n":"第四十条","txt":"消毒产品生产企业应当按照国家卫生标准和卫生规范要求对消毒产品理化指标、微生物指标、杀灭微生物指标、毒理学指标等进行检验。不具备检验能力的，可以委托检验。 消毒产品的检验活动应当符合国家有关规定。检验报告应当客观、真实，符合有关法律、法规、标准、规范和规定。检验报告在全国范围内有效。"},{"i":41,"n":"第四十一条","txt":"医疗卫生机构违反本办法第四、五、六、七、八、九条规定的，由县级以上地方卫生计生行政部门责令限期改正，可以处5000元以下罚款；造成感染性疾病暴发的，可以处5000元以上20000元以下罚款。"},{"i":42,"n":"第四十二条","txt":"加工、出售、运输被传染病病原体污染或者来自疫区可能被传染病病原体污染的皮毛，未按国家有关规定进行消毒处理的，应当按照《传染病防治法实施办法》第六十八条的有关规定给予处罚。"},{"i":43,"n":"第四十三条","txt":"消毒产品生产经营单位违反本办法第三十一条、第三十二条规定的，由县级以上地方卫生计生行政部门责令其限期改正，可以处5000元以下罚款；造成感染性疾病暴发的，可以处5000元以上20000元以下的罚款。"},{"i":44,"n":"第四十四条","txt":"消毒服务机构违反本办法规定，有下列情形之一的，由县级以上卫生计生行政部门责令其限期改正，可以处5000元以下的罚款；造成感染性疾病发生的，可以处5000元以上20000元以下的罚款： 消毒后的物品未达到卫生标准和要求的。"},{"i":45,"n":"第四十五条","txt":"本办法下列用语的含义： 感染性疾病：由微生物引起的疾病。 消毒产品：包括消毒剂、消毒器械（含生物指示物、化学指示物和灭菌物品包装物）、卫生用品和一次性使用医疗用品。 消毒服务机构：指为社会提供可能被污染的物品及场所、卫生用品和一次性使用医疗用品等进行消毒与灭菌服务的单位。 医疗卫生机构：指医疗保健、疾病控制、采供血机构及与上述机构业务活动相同的单位。"},{"i":46,"n":"第四十六条","txt":"本办法由国家卫生计生委负责解释。"},{"i":47,"n":"第四十七条","txt":"本办法自2002年7月1日起施行。1992年8月31日卫生部发布的《消毒管理办法》同时废止。"}],"shejirendeshengwuyixueyanjiulunlishenchabanfa":[{"i":1,"n":"第一条","txt":"为保护人的生命和健康，维护人的尊严，尊重和保护受试者的合法权益，规范涉及人的生物医学研究伦理审查工作，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级各类医疗卫生机构开展涉及人的生物医学研究伦理审查工作。"},{"i":3,"n":"第三条","txt":"本办法所称涉及人的生物医学研究包括以下活动： （一）采用现代物理学、化学、生物学、中医药学和心理学等方法对人的生理、心理行为、病理现象、疾病病因和发病机制，以及疾病的预防、诊断、治疗和康复进行研究的活动； （二）医学新技术或者医疗新产品在人体上进行试验研究的活动； （三）采用流行病学、社会学、心理学等方法收集、记录、使用、报告或者储存有关人的样本、医疗记录、行为等科学研究资料的活动。"},{"i":4,"n":"第四条","txt":"伦理审查应当遵守国家法律法规规定，在研究中尊重受试者的自主意愿,同时遵守有益、不伤害以及公正的原则。"},{"i":5,"n":"第五条","txt":"国家卫生计生委负责全国涉及人的生物医学研究伦理审查工作的监督管理，成立国家医学伦理专家委员会。国家中医药管理局负责中医药研究伦理审查工作的监督管理，成立国家中医药伦理专家委员会。省级卫生计生行政部门成立省级医学伦理专家委员会。 县级以上地方卫生计生行政部门负责本行政区域涉及人的生物医学研究伦理审查工作的监督管理。"},{"i":6,"n":"第六条","txt":"国家医学伦理专家委员会、国家中医药伦理专家委员会（以下称国家医学伦理专家委员会）负责对涉及人的生物医学研究中的重大伦理问题进行研究，提供政策咨询意见，指导省级医学伦理专家委员会的伦理审查相关工作。 省级医学伦理专家委员会协助推动本行政区域涉及人的生物医学研究伦理审查工作的制度化、规范化，指导、检查、评估本行政区域从事涉及人的生物医学研究的医疗卫生机构伦理委员会的工作，开展相关培训、咨询等工作。"},{"i":7,"n":"第七条","txt":"从事涉及人的生物医学研究的医疗卫生机构是涉及人的生物医学研究伦理审查工作的管理责任主体，应当设立伦理委员会，并采取有效措施保障伦理委员会独立开展伦理审查工作。 医疗卫生机构未设立伦理委员会的，不得开展涉及人的生物医学研究工作。"},{"i":8,"n":"第八条","txt":"伦理委员会的职责是保护受试者合法权益，维护受试者尊严，促进生物医学研究规范开展；对本机构开展涉及人的生物医学研究项目进行伦理审查，包括初始审查、跟踪审查和复审等；在本机构组织开展相关伦理审查培训。"},{"i":9,"n":"第九条","txt":"伦理委员会的委员应当从生物医学领域和伦理学、法学、社会学等领域的专家和非本机构的社会人士中遴选产生，人数不得少于7人，并且应当有不同性别的委员，少数民族地区应当考虑少数民族委员。必要时，伦理委员会可以聘请独立顾问。独立顾问对所审查项目的特定问题提供咨询意见，不参与表决。"},{"i":10,"n":"第十条","txt":"伦理委员会委员任期5年，可以连任。伦理委员会设主任委员一人，副主任委员若干人，由伦理委员会委员协商推举产生。 伦理委员会委员应当具备相应的伦理审查能力，并定期接受生物医学研究伦理知识及相关法律法规知识培训。"},{"i":11,"n":"第十一条","txt":"伦理委员会对受理的申报项目应当及时开展伦理审查，提供审查意见；对已批准的研究项目进行定期跟踪审查，受理受试者的投诉并协调处理，确保项目研究不会将受试者置于不合理的风险之中。"},{"i":12,"n":"第十二条","txt":"伦理委员会在开展伦理审查时，可以要求研究者提供审查所需材料、知情同意书等文件以及修改研究项目方案，并根据职责对研究项目方案、知情同意书等文件提出伦理审查意见。"},{"i":13,"n":"第十三条","txt":"伦理委员会委员应当签署保密协议，承诺对所承担的伦理审查工作履行保密义务，对所受理的研究项目方案、受试者信息以及委员审查意见等保密。"},{"i":14,"n":"第十四条","txt":"医疗卫生机构应当在伦理委员会设立之日起3个月内向本机构的执业登记机关备案，并在医学研究登记备案信息系统登记。医疗卫生机构还应当于每年3月31日前向备案的执业登记机关提交上一年度伦理委员会工作报告。 伦理委员会备案材料包括： （一）人员组成名单和每位委员工作简历； （二）伦理委员会章程； （三）工作制度或者相关工作程序； （四）备案的执业登记机关要求提供的其他相关材料。 以上信息发生变化时，医疗卫生机构应当及时向备案的执业登记机关更新信息。"},{"i":15,"n":"第十五条","txt":"伦理委员会应当配备专（兼）职工作人员、设备、场所等，保障伦理审查工作顺利开展。"},{"i":16,"n":"第十六条","txt":"伦理委员会应当接受所在医疗卫生机构的管理和受试者的监督。"},{"i":17,"n":"第十七条","txt":"伦理委员会应当建立伦理审查工作制度或者操作规程，保证伦理审查过程独立、客观、公正。"},{"i":18,"n":"第十八条","txt":"涉及人的生物医学研究应当符合以下伦理原则： （一）知情同意原则。尊重和保障受试者是否参加研究的自主决定权，严格履行知情同意程序，防止使用欺骗、利诱、胁迫等手段使受试者同意参加研究，允许受试者在任何阶段无条件退出研究； （二）控制风险原则。首先将受试者人身安全、健康权益放在优先地位，其次才是科学和社会利益，研究风险与受益比例应当合理，力求使受试者尽可能避免伤害； （三）免费和补偿原则。应当公平、合理地选择受试者，对受试者参加研究不得收取任何费用，对于受试者在受试过程中支出的合理费用还应当给予适当补偿； （四）保护隐私原则。切实保护受试者的隐私，如实将受试者个人信息的储存、使用及保密措施情况告知受试者，未经授权不得将受试者个人信息向第三方透露； （五）依法赔偿原则。受试者参加研究受到损害时，应当得到及时、免费治疗，并依据法律法规及双方约定得到赔偿； （六）特殊保护原则。对儿童、孕妇、智力低"},{"i":19,"n":"第十九条","txt":"涉及人的生物医学研究项目的负责人作为伦理审查申请人，在申请伦理审查时应当向负责项目研究的医疗卫生机构的伦理委员会提交下列材料： （一）伦理审查申请表； （二）研究项目负责人信息、研究项目所涉及的相关机构的合法资质证明以及研究项目经费来源说明； （三）研究项目方案、相关资料，包括文献综述、临床前研究和动物实验数据等资料； （四）受试者知情同意书； （五）伦理委员会认为需要提交的其他相关材料。"},{"i":20,"n":"第二十条","txt":"伦理委员会收到申请材料后，应当及时组织伦理审查，并重点审查以下内容： （一）研究者的资格、经验、技术能力等是否符合试验要求； （二）研究方案是否科学，并符合伦理原则的要求。中医药项目研究方案的审查，还应当考虑其传统实践经验； （三）受试者可能遭受的风险程度与研究预期的受益相比是否在合理范围之内； （四）知情同意书提供的有关信息是否完整易懂，获得知情同意的过程是否合规恰当； （五）是否有对受试者个人信息及相关资料的保密措施； （六）受试者的纳入和排除标准是否恰当、公平； （七）是否向受试者明确告知其应当享有的权益，包括在研究过程中可以随时无理由退出且不受歧视的权利等； （八）受试者参加研究的合理支出是否得到了合理补偿；受试者参加研究受到损害时，给予的治疗和赔偿是否合理、合法； （九）是否有具备资格或者经培训后的研究者负责获取知情同意，并随时接受有关安全问题的咨询； （十）对受试者在研究中"},{"i":21,"n":"第二十一条","txt":"伦理委员会委员与研究项目存在利害关系的，应当回避；伦理委员会对与研究项目有利害关系的委员应当要求其回避。"},{"i":22,"n":"第二十二条","txt":"伦理委员会批准研究项目的基本标准是： （一）坚持生命伦理的社会价值； （二）研究方案科学； （三）公平选择受试者； （四）合理的风险与受益比例； （五）知情同意书规范； （六）尊重受试者权利； （七）遵守科研诚信规范。"},{"i":23,"n":"第二十三条","txt":"伦理委员会应当对审查的研究项目作出批准、不批准、修改后批准、修改后再审、暂停或者终止研究的决定，并说明理由。 伦理委员会作出决定应当得到伦理委员会全体委员的二分之一以上同意。伦理审查时应当通过会议审查方式，充分讨论达成一致意见。"},{"i":24,"n":"第二十四条","txt":"经伦理委员会批准的研究项目需要修改研究方案时，研究项目负责人应当将修改后的研究方案再报伦理委员会审查；研究项目未获得伦理委员会审查批准的，不得开展项目研究工作。 对已批准研究项目的研究方案作较小修改且不影响研究的风险受益比的研究项目和研究风险不大于最小风险的研究项目可以申请简易审查程序。 简易审查程序可以由伦理委员会主任委员或者由其指定的一个或者几个委员进行审查。审查结果和理由应当及时报告伦理委员会。"},{"i":25,"n":"第二十五条","txt":"经伦理委员会批准的研究项目在实施前，研究项目负责人应当将该研究项目的主要内容、伦理审查决定在医学研究登记备案信息系统进行登记。"},{"i":26,"n":"第二十六条","txt":"在项目研究过程中，项目研究者应当将发生的严重不良反应或者严重不良事件及时向伦理委员会报告；伦理委员会应当及时审查并采取相应措施，以保护受试者的人身安全与健康权益。"},{"i":27,"n":"第二十七条","txt":"对已批准实施的研究项目，伦理委员会应当指定委员进行跟踪审查。跟踪审查包括以下内容： （一）是否按照已通过伦理审查的研究方案进行试验； （二）研究过程中是否擅自变更项目研究内容； （三）是否发生严重不良反应或者不良事件； （四）是否需要暂停或者提前终止研究项目； （五）其他需要审查的内容。 跟踪审查的委员不得少于2人，在跟踪审查时应当及时将审查情况报告伦理委员会。"},{"i":28,"n":"第二十八条","txt":"对风险较大或者比较特殊的涉及人的生物医学研究伦理审查项目，伦理委员会可以根据需要申请省级医学伦理专家委员会协助提供咨询意见。"},{"i":29,"n":"第二十九条","txt":"多中心研究可以建立协作审查机制，确保各项目研究机构遵循一致性和及时性原则。 牵头机构的伦理委员会负责项目审查，并对参与机构的伦理审查结果进行确认。 参与机构的伦理委员会应当及时对本机构参与的研究进行伦理审查，并对牵头机构反馈审查意见。 为了保护受试者的人身安全，各机构均有权暂停或者终止本机构的项目研究。"},{"i":30,"n":"第三十条","txt":"境外机构或者个人与国内医疗卫生机构合作开展涉及人的生物医学研究的，应当向国内合作机构的伦理委员会申请研究项目伦理审查。"},{"i":31,"n":"第三十一条","txt":"在学术期刊发表涉及人的生物医学研究成果的项目研究者，应当出具该研究项目经过伦理审查批准的证明文件。"},{"i":32,"n":"第三十二条","txt":"伦理审查工作具有独立性，任何单位和个人不得干预伦理委员会的伦理审查过程及审查决定。"},{"i":33,"n":"第三十三条","txt":"项目研究者开展研究，应当获得受试者自愿签署的知情同意书；受试者不能以书面方式表示同意时，项目研究者应当获得其口头知情同意，并提交过程记录和证明材料。"},{"i":34,"n":"第三十四条","txt":"对无行为能力、限制行为能力的受试者，项目研究者应当获得其监护人或者法定代理人的书面知情同意。"},{"i":35,"n":"第三十五条","txt":"知情同意书应当含有必要、完整的信息，并以受试者能够理解的语言文字表达。"},{"i":36,"n":"第三十六条","txt":"知情同意书应当包括以下内容： （一）研究目的、基本研究内容、流程、方法及研究时限； （二）研究者基本信息及研究机构资质； （三）研究结果可能给受试者、相关人员和社会带来的益处，以及给受试者可能带来的不适和风险； （四）对受试者的保护措施； （五）研究数据和受试者个人资料的保密范围和措施； （六）受试者的权利，包括自愿参加和随时退出、知情、同意或不同意、保密、补偿、受损害时获得免费治疗和赔偿、新信息的获取、新版本知情同意书的再次签署、获得知情同意书等； （七）受试者在参与研究前、研究后和研究过程中的注意事项。"},{"i":37,"n":"第三十七条","txt":"在知情同意获取过程中，项目研究者应当按照知情同意书内容向受试者逐项说明，其中包括：受试者所参加的研究项目的目的、意义和预期效果，可能遇到的风险和不适，以及可能带来的益处或者影响；有无对受试者有益的其他措施或者治疗方案；保密范围和措施；补偿情况，以及发生损害的赔偿和免费治疗；自愿参加并可以随时退出的权利，以及发生问题时的联系人和联系方式等。 项目研究者应当给予受试者充分的时间理解知情同意书的内容，由受试者作出是否同意参加研究的决定并签署知情同意书。 在心理学研究中，因知情同意可能影响受试者对问题的回答，从而影响研究结果的准确性的，研究者可以在项目研究完成后充分告知受试者并获得知情同意书。"},{"i":38,"n":"第三十八条","txt":"当发生下列情形时，研究者应当再次获取受试者签署的知情同意书： （一）研究方案、范围、内容发生变化的； （二）利用过去用于诊断、治疗的有身份标识的样本进行研究的； （三）生物样本数据库中有身份标识的人体生物学样本或者相关临床病史资料，再次使用进行研究的； （四）研究过程中发生其他变化的。"},{"i":39,"n":"第三十九条","txt":"以下情形经伦理委员会审查批准后，可以免除签署知情同意书： （一）利用可识别身份信息的人体材料或者数据进行研究，已无法找到该受试者，且研究项目不涉及个人隐私和商业利益的； （二）生物样本捐献者已经签署了知情同意书，同意所捐献样本及相关信息可用于所有医学研究的。"},{"i":40,"n":"第四十条","txt":"国家卫生计生委负责组织全国涉及人的生物医学研究伦理审查工作的检查、督导；国家中医药管理局负责组织全国中医药研究伦理审查工作的检查、督导。 县级以上地方卫生计生行政部门应当加强对本行政区域涉及人的生物医学研究伦理审查工作的日常监督管理。主要监督检查以下内容： （一）医疗卫生机构是否按照要求设立伦理委员会，并进行备案； （二）伦理委员会是否建立伦理审查制度； （三）伦理审查内容和程序是否符合要求； （四）审查的研究项目是否如实在我国医学研究登记备案信息系统进行登记； （五）伦理审查结果执行情况； （六）伦理审查文档管理情况； （七）伦理委员会委员的伦理培训、学习情况； （八）对国家和省级医学伦理专家委员会提出的改进意见或者建议是否落实； （九）其他需要监督检查的相关内容。"},{"i":41,"n":"第四十一条","txt":"国家医学伦理专家委员会应当对省级医学伦理专家委员会的工作进行指导、检查和评估。 省级医学伦理专家委员会应当对本行政区域内医疗卫生机构的伦理委员会进行检查和评估，重点对伦理委员会的组成、规章制度及审查程序的规范性、审查过程的独立性、审查结果的可靠性、项目管理的有效性等内容进行评估，并对发现的问题提出改进意见或者建议。"},{"i":42,"n":"第四十二条","txt":"医疗卫生机构应当加强对本机构设立的伦理委员会开展的涉及人的生物医学研究伦理审查工作的日常管理，定期评估伦理委员会工作质量，对发现的问题及时提出改进意见或者建议，根据需要调整伦理委员会委员等。"},{"i":43,"n":"第四十三条","txt":"医疗卫生机构应当督促本机构的伦理委员会落实县级以上卫生计生行政部门提出的整改意见；伦理委员会未在规定期限内完成整改或者拒绝整改，违规情节严重或者造成严重后果的，其所在医疗卫生机构应当撤销伦理委员会主任委员资格，追究相关人员责任。"},{"i":44,"n":"第四十四条","txt":"任何单位或者个人均有权举报涉及人的生物医学研究中存在的违规或者不端行为。"},{"i":45,"n":"第四十五条","txt":"医疗卫生机构未按照规定设立伦理委员会擅自开展涉及人的生物医学研究的，由县级以上地方卫生计生行政部门责令限期整改；逾期不改的，由县级以上地方卫生计生行政部门予以警告，并可处以3万元以下罚款；对机构主要负责人和其他责任人员，依法给予处分。"},{"i":46,"n":"第四十六条","txt":"医疗卫生机构及其伦理委员会违反本办法规定，有下列情形之一的，由县级以上地方卫生计生行政部门责令限期整改，并可根据情节轻重给予通报批评、警告；对机构主要负责人和其他责任人员，依法给予处分： （一）伦理委员会组成、委员资质不符合要求的； （二）未建立伦理审查工作制度或者操作规程的； （三）未按照伦理审查原则和相关规章制度进行审查的； （四）泄露研究项目方案、受试者个人信息以及委员审查意见的； （五）未按照规定进行备案的； （六）其他违反本办法规定的情形。"},{"i":47,"n":"第四十七条","txt":"项目研究者违反本办法规定，有下列情形之一的，由县级以上地方卫生计生行政部门责令限期整改，并可根据情节轻重给予通报批评、警告；对主要负责人和其他责任人员，依法给予处分： （一）研究项目或者研究方案未获得伦理委员会审查批准擅自开展项目研究工作的； （二）研究过程中发生严重不良反应或者严重不良事件未及时报告伦理委员会的； （三）违反知情同意相关规定开展项目研究的； （四）其他违反本办法规定的情形。"},{"i":48,"n":"第四十八条","txt":"医疗卫生机构、项目研究者在开展涉及人的生物医学研究工作中，违反《执业医师法》、《医疗机构管理条例》等法律法规相关规定的，由县级以上地方卫生计生行政部门依法进行处理。"},{"i":49,"n":"第四十九条","txt":"违反本办法规定的机构和个人，给他人人身、财产造成损害的，应当依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"本办法自2016年12月1日起施行。本办法发布前，从事涉及人的生物医学研究的医疗卫生机构已设立伦理委员会的，应当自本办法发布之日起3个月内向本机构的执业登记机关备案，并在医学研究登记备案信息系统登记。"}],"zaihaishiguyiliaojiuyuangongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为提高对灾害事故的应急反应能力和医疗救援水平，避免和减少人员伤亡，保障公民身体健康和生命安全，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称医疗救援，系指因灾害事故发生人群伤亡时的抢救治疗工作。"},{"i":3,"n":"第三条","txt":"对灾害事故的医疗救援工作实行规范管理，做到常备不懈，及时有效。"},{"i":4,"n":"第四条","txt":"县级以上政府卫生行政部门主管灾害事故医疗救援工作。"},{"i":5,"n":"第五条","txt":"卫生部成立“卫生部灾害事故医疗救援领导小组”，由卫生部部长任组长，主管副部长、医政司司长任副组长，办公厅、疾病控制司、计财司、药政局、爱委会、监督司、外事司等有关领导为成员。"},{"i":6,"n":"第六条","txt":"各省、自治区、直辖市政府卫生行政部门成立与“卫生部灾害事故医疗救援工作领导小组”相应的组织。 灾害事故多发地区的县级以上政府卫生行政部门，根据需要也可以设立相应的领导协调组织。"},{"i":7,"n":"第七条","txt":"各级灾害事故医疗救援领导小组要及时了解掌握全国或当地灾害事故的特征、规律、医疗救护资源、地理交通状况等信息，组织、协调、部署与灾害事故医疗救护有关的工作。"},{"i":8,"n":"第八条","txt":"要组织好灾害事故的现场医疗救护。在灾害事故发生后，到达事故现场的当地最高卫生行政主管部门领导即为灾害事故现场医疗救援总指挥，负责现场医疗救援工作。"},{"i":9,"n":"第九条","txt":"县级以上地方政府卫生行政部门要加强对急救中心、急救站、医院急诊科（室）为主体的急救医疗服务网络建设，提高其急救反应能力。"},{"i":10,"n":"第十条","txt":"各级政府卫生行政部门要制定救援预案；要建立数支救灾医疗队，并配备一定数量的急救医疗药械（见附件），由医疗队所在单位保管，定期更换。"},{"i":11,"n":"第十一条","txt":"灾害事故发生地的医疗卫生单位或医疗卫生人员应当及时将灾情报告其所在地的县级以上政府卫生行政部门。 凡事故发生地丧失报告能力的，由相邻地区政府卫生行政部门、医疗卫生单位或医疗卫生人员履行报告程序。"},{"i":12,"n":"第十二条","txt":"卫生行政部门接到灾情报告或救援指令后，应当立即通知有关单位，组织现场抢救，并及时报告当地人民政府和上一级政府卫生行政部门。"},{"i":13,"n":"第十三条","txt":"医疗救援情况按以下规定报告： （一）伤亡20人以下的，6小时内报市级卫生行政部门； （二）伤亡20—50人的，12小时内报省级卫生行政部门； （三）伤亡50人以上的，24小时内报国务院卫生行政部门； （四）地震、水灾、风灾、火灾和其他重大灾害事故，虽一时不明伤亡情况的，应尽快逐级上报至国务院卫生行政部门。"},{"i":14,"n":"第十四条","txt":"报告内容： （一）灾害发生的时间、地点、伤亡人数及种类； （二）伤员主要的伤情、采取的措施及投入的医疗资源； （三）急需解决的卫生问题； （四）卫生系统受损情况。"},{"i":15,"n":"第十五条","txt":"疫情的报告和公布根据《中华人民共和国传染病防治法》的规定实施。"},{"i":16,"n":"第十六条","txt":"灾害事故发生后，凡就近的医护人员都要主动及时到达现场，并组织起来参加医疗救护。"},{"i":17,"n":"第十七条","txt":"参加医疗救援工作的单位和个人，到达现场后应当立即向灾害事故医疗救援现场指挥部报到，并接受其统一指挥和调遣。"},{"i":18,"n":"第十八条","txt":"灾害事故医疗救援现场指挥部的任务为： （一）视伤亡情况设置伤病员分检处； （二）对现场伤亡情况和事态发展作出快速、准确评估； （三）指挥、调遣现场及辖区内各医疗救护力量； （四）向当地灾害事故医疗救援领导小组汇报有关情况并接受指令。"},{"i":19,"n":"第十九条","txt":"在现场医疗救护中，依据受害者的伤病情况，按轻、中、重、残废分类，分别以“红、黄、蓝、黑”的伤病卡作出标志，（伤病卡以5×3cm的不干胶材料做成），置于伤病员的左胸部或其他明显部位，便于医疗救护人员辨认并采取相应的急救措施。"},{"i":20,"n":"第二十条","txt":"现场医疗救护过程中，要本着先救命后治伤、先治重伤后治轻伤的原则，要将经治的伤员的血型、伤情、急救处置、注意事项等逐一填写伤员情况单（见附件2），并置于伤员衣袋内。"},{"i":21,"n":"第二十一条","txt":"根据现场伤员情况设手术、急救处置室（部）。"},{"i":22,"n":"第二十二条","txt":"凡伤员需要后送，由当地灾害事故医疗救援领导小组视实际需要决定设伤员后送指挥部，负责伤员后送的指挥协调工作。"},{"i":23,"n":"第二十三条","txt":"伤病员经现场检伤分类、处置后要根据病情向就近的省、市级医院或专科医院分流，原则如下： （一）当地医疗机构有能力收治全部伤员的，由急救中心（站）或后送指挥部指定有关单位后送到就近的医院； （二）伤员现场经治的医疗文书要一式二份，及时向现场指挥部报告汇总，并向接纳后送伤员的医疗机构提交； （三）后送途中需要监护的伤员，由灾害事故现场医疗救护指挥部派医护人员护送； （四）灾害事故发生后医疗机构不得以任何理由拒诊、推诿后送的伤员。"},{"i":24,"n":"第二十四条","txt":"各级卫生行政部门负责制定灾害事故医疗救援工作计划；负责组织派遣医疗队，救治伤病员；负责灾害事故医疗救援工作的对外宣传口径；承接上级灾害事故医疗救援领导小组分配的任务。"},{"i":25,"n":"第二十五条","txt":"灾害事故医疗救援领导小组视情况提请地方政府协调铁路、邮电、交通、民航、航运、军队、武警、国家医药管理局等有关部门协助解决医疗救援有关的交通，伤病员的转送、药械调拨等工作。"},{"i":26,"n":"第二十六条","txt":"各级红十字会、爱国卫生运动委员会办公室要协同卫生行政部门，参与灾害事故的医疗救援工作。"},{"i":27,"n":"第二十七条","txt":"各级卫生行政部门要制订和落实灾害事故医疗救护人员的培训计划。重点掌握检伤分类、徒手复苏、骨折固定、止血、气管插管、气管切开、清创、缝合、饮用水消毒等基本技能，并定期举行模拟演习，达到实战要求。"},{"i":28,"n":"第二十八条","txt":"要利用报刊、广播、影视、培训班等多种形式，向公众普及灾害事故医疗救护、自救和互救的知识及基本技术。"},{"i":29,"n":"第二十九条","txt":"本办法由卫生部负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自发布之日起实施。 附件1：灾害事故医疗救护队基本装备表（略） 附件2：伤员情况单（略）"}],"jinzhifeiyixuexuyaodetaierxingbiejiandinghexuanzexa67d89-2":[{"i":1,"n":"第一条","txt":"为了贯彻计划生育基本国策，促进出生人口性别结构平衡，促进人口均衡发展，根据《中华人民共和国人口与计划生育法》、《中华人民共和国母婴保健法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"非医学需要的胎儿性别鉴定和选择性别人工终止妊娠，是指除经医学诊断胎儿可能为伴性遗传病等需要进行胎儿性别鉴定和选择性别人工终止妊娠以外，所进行的胎儿性别鉴定和选择性别人工终止妊娠。"},{"i":3,"n":"第三条","txt":"禁止任何单位或者个人实施非医学需要的胎儿性别鉴定和选择性别人工终止妊娠。 禁止任何单位或者个人介绍、组织孕妇实施非医学需要的胎儿性别鉴定和选择性别人工终止妊娠。"},{"i":4,"n":"第四条","txt":"各级卫生计生行政部门和食品药品监管部门应当建立查处非医学需要的胎儿性别鉴定和选择性别人工终止妊娠违法行为的协作机制和联动执法机制，共同实施监督管理。 卫生计生行政部门和食品药品监管部门应当按照各自职责，制定胎儿性别鉴定、人工终止妊娠以及相关药品和医疗器械等管理制度。"},{"i":5,"n":"第五条","txt":"县级以上卫生计生行政部门履行以下职责: （一）监管并组织、协调非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的查处工作； （二）负责医疗卫生机构及其从业人员的执业准入和相关医疗器械使用监管，以及相关法律法规、执业规范的宣传培训等工作； （三）负责人口信息管理系统的使用管理，指导医疗卫生机构及时准确地采集新生儿出生、死亡等相关信息； （四）法律、法规、规章规定的涉及非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的其他事项。"},{"i":6,"n":"第六条","txt":"县级以上工商行政管理部门（包括履行工商行政管理职责的市场监督管理部门，下同）对含有胎儿性别鉴定和人工终止妊娠内容的广告实施监管，并依法查处违法行为。"},{"i":7,"n":"第七条","txt":"食品药品监管部门依法对与胎儿性别鉴定和人工终止妊娠相关的药品和超声诊断仪、染色体检测专用设备等医疗器械的生产、销售和使用环节的产品质量实施监管，并依法查处相关违法行为。"},{"i":8,"n":"第八条","txt":"禁止非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的工作应当纳入计划生育目标管理责任制。"},{"i":9,"n":"第九条","txt":"符合法定生育条件，除下列情形外，不得实施选择性别人工终止妊娠： （一）胎儿患严重遗传性疾病的； （二）胎儿有严重缺陷的； （三）因患严重疾病，继续妊娠可能危及孕妇生命安全或者严重危害孕妇健康的； （四）法律法规规定的或医学上认为确有必要终止妊娠的其他情形。"},{"i":10,"n":"第十条","txt":"医学需要的胎儿性别鉴定，由省、自治区、直辖市卫生计生行政部门批准设立的医疗卫生机构按照国家有关规定实施。 实施医学需要的胎儿性别鉴定，应当由医疗卫生机构组织三名以上具有临床经验和医学遗传学知识，并具有副主任医师以上的专业技术职称的专家集体审核。经诊断，确需人工终止妊娠的，应当出具医学诊断报告，并由医疗卫生机构通报当地县级卫生计生行政部门。"},{"i":11,"n":"第十一条","txt":"医疗卫生机构应当在工作场所设置禁止非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的醒目标志；医务人员应当严格遵守有关法律法规和超声诊断、染色体检测、人工终止妊娠手术管理等相关制度。"},{"i":12,"n":"第十二条","txt":"实施人工终止妊娠手术的机构应当在手术前登记、查验受术者身份证明信息，并及时将手术实施情况通报当地县级卫生计生行政部门。"},{"i":13,"n":"第十三条","txt":"医疗卫生机构发生新生儿死亡的，应当及时出具死亡证明，并向当地县级卫生计生行政部门报告。 新生儿在医疗卫生机构以外地点死亡的，监护人应当及时向当地乡（镇）人民政府、街道办事处卫生计生工作机构报告；乡（镇）人民政府、街道办事处卫生计生工作机构应当予以核查，并向乡镇卫生院或社区卫生服务中心通报有关信息。"},{"i":14,"n":"第十四条","txt":"终止妊娠药品目录由国务院食品药品监管部门会同国务院卫生计生行政部门制定发布。 药品生产、批发企业仅能将终止妊娠药品销售给药品批发企业或者获准施行终止妊娠手术的医疗卫生机构。药品生产、批发企业销售终止妊娠药品时，应当按照药品追溯有关规定，严格查验购货方资质，并做好销售记录。禁止药品零售企业销售终止妊娠药品。 终止妊娠的药品，仅限于在获准施行终止妊娠手术的医疗卫生机构的医师指导和监护下使用。 经批准实施人工终止妊娠手术的医疗卫生机构应当建立真实、完整的终止妊娠药品购进记录，并为终止妊娠药品使用者建立完整档案。"},{"i":15,"n":"第十五条","txt":"医疗器械销售企业销售超声诊断仪、染色体检测专用设备等医疗器械，应当核查购买者的资质，验证机构资质并留存复印件，建立真实、完整的购销记录；不得将超声诊断仪、染色体检测专用设备等医疗器械销售给不具有相应资质的机构和个人。"},{"i":16,"n":"第十六条","txt":"医疗卫生、教学科研机构购置可用于鉴定胎儿性别的超声诊断仪、染色体检测专用设备等医疗器械时，应当提供机构资质原件和复印件，交销售企业核查、登记，并建立进货查验记录制度。"},{"i":17,"n":"第十七条","txt":"违法发布非医学需要的胎儿性别鉴定或者非医学需要的选择性别人工终止妊娠广告的，由工商行政管理部门依据《中华人民共和国广告法》等相关法律法规进行处罚。 对广告中涉及的非医学需要的胎儿性别鉴定或非医学需要的选择性别人工终止妊娠等专业技术内容，工商行政管理部门可根据需要提请同级卫生计生行政部门予以认定。"},{"i":18,"n":"第十八条","txt":"违反规定利用相关技术为他人实施非医学需要的胎儿性别鉴定或者选择性别人工终止妊娠的，由县级以上卫生计生行政部门依据《中华人民共和国人口与计划生育法》等有关法律法规进行处理；对医疗卫生机构的主要负责人、直接负责的主管人员和直接责任人员，依法给予处分。"},{"i":19,"n":"第十九条","txt":"对未取得母婴保健技术许可的医疗卫生机构或者人员擅自从事终止妊娠手术的、从事母婴保健技术服务的人员出具虚假的医学需要的人工终止妊娠相关医学诊断意见书或者证明的，由县级以上卫生计生行政部门依据《中华人民共和国母婴保健法》及其实施办法的有关规定进行处理；对医疗卫生机构的主要负责人、直接负责的主管人员和直接责任人员，依法给予处分。"},{"i":20,"n":"第二十条","txt":"经批准实施人工终止妊娠手术的机构未建立真实完整的终止妊娠药品购进记录，或者未按照规定为终止妊娠药品使用者建立完整用药档案的，由县级以上卫生计生行政部门责令改正；拒不改正的，给予警告，并可处1万元以上3万元以下罚款；对医疗卫生机构的主要负责人、直接负责的主管人员和直接责任人员，依法进行处理。"},{"i":21,"n":"第二十一条","txt":"药品生产企业、批发企业将终止妊娠药品销售给未经批准实施人工终止妊娠的医疗卫生机构和个人，或者销售终止妊娠药品未查验购药者的资格证明、未按照规定作销售记录的，以及药品零售企业销售终止妊娠药品的，由县级以上食品药品监管部门按照《中华人民共和国药品管理法》的有关规定进行处理。"},{"i":22,"n":"第二十二条","txt":"医疗器械生产经营企业将超声诊断仪、染色体检测专用设备等医疗器械销售给无购买资质的机构或者个人的，由县级以上食品药品监管部门责令改正，处1万元以上3万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"介绍、组织孕妇实施非医学需要的胎儿性别鉴定或者选择性别人工终止妊娠的，由县级以上卫生计生行政部门责令改正，给予警告；情节严重的，没收违法所得，并处5000元以上3万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"鼓励任何单位和个人举报违反本规定的行为。举报内容经查证属实的，应当依据有关规定给予举报人相应的奖励。"},{"i":25,"n":"第二十五条","txt":"本规定自2016年5月1日起施行。2002年11月29日原国家计生委、原卫生部、原国家药品监管局公布的《关于禁止非医学需要的胎儿性别鉴定和选择性别的人工终止妊娠的规定》同时废止。"}],"tufagonggongweishengshijianyuchuanranbingyiqingjia66cca8":[{"i":1,"n":"第一条","txt":"为加强突发公共卫生事件与传染病疫情监测信息报告管理工作，提供及时、科学的防治决策信息，有效预防、及时控制和消除突发公共卫生事件和传染病的危害，保障公众身体健康与生命安全，根据《中华人民共和国传染病防治法》（以下简称传染病防治法）和《突发公共卫生事件应急条例》（以下简称应急条例）等法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于传染病防治法、应急条例和国家有关法律法规中规定的突发公共卫生事件与传染病疫情监测信息报告管理工作。"},{"i":3,"n":"第三条","txt":"突发公共卫生事件与传染病疫情监测信息报告，坚持依法管理，分级负责，快速准确，安全高效的原则。"},{"i":4,"n":"第四条","txt":"国务院卫生行政部门对全国突发公共卫生事件与传染病疫情监测信息报告实施统一监督管理。 县级以上地方卫生行政部门对本行政区域突发公共卫生事件与传染病疫情监测信息报告实施监督管理。"},{"i":5,"n":"第五条","txt":"国务院卫生行政部门及省、自治区、直辖市卫生行政部门鼓励、支持开展突发公共卫生事件与传染病疫情监测信息报告管理的科学技术研究和国际交流合作。"},{"i":6,"n":"第六条","txt":"县级以上各级人民政府及其卫生行政部门，应当对在突发公共卫生事件与传染病疫情监测信息报告管理工作中做出贡献的人员，给予表彰和奖励。"},{"i":7,"n":"第七条","txt":"任何单位和个人必须按照规定及时如实报告突发公共卫生事件与传染病疫情信息，不得瞒报、缓报、谎报或者授意他人瞒报、缓报、谎报。"},{"i":8,"n":"第八条","txt":"各级疾病预防控制机构按照专业分工，承担责任范围内突发公共卫生事件和传染病疫情监测、信息报告与管理工作，具体职责为： （一）按照属地化管理原则，当地疾病预防控制机构负责，对行政辖区内的突发公共卫生事件和传染病疫情进行监测、信息报告与管理；负责收集、核实辖区内突发公共卫生事件、疫情信息和其他信息资料；设置专门的举报、咨询热线电话，接受突发公共卫生事件和疫情的报告、咨询和监督；设置专门工作人员搜集各种来源的突发公共卫生事件和疫情信息。 （二）建立流行病学调查队伍和实验室，负责开展现场流行病学调查与处理，搜索密切接触者、追踪传染源，必要时进行隔离观察；进行疫点消毒及其技术指导；标本的实验室检测检验及报告。 （三）负责公共卫生信息网络维护和管理，疫情资料的报告、分析、利用与反馈；建立监测信息数据库，开展技术指导。 （四）对重点涉外机构或单位发生的疫情，由省级以上疾病预防控制机构进行报告管理和检查"},{"i":9,"n":"第九条","txt":"国家建立公共卫生信息监测体系，构建覆盖国家、省、市（地）、县（区）疾病预防控制机构、医疗卫生机构和卫生行政部门的信息网络系统，并向乡（镇）、村和城市社区延伸。 国家建立公共卫生信息管理平台、基础卫生资源数据库和管理应用软件，适应突发公共卫生事件、法定传染病、公共卫生和专病监测的信息采集、汇总、分析、报告等工作的需要。"},{"i":10,"n":"第十条","txt":"各级各类医疗机构承担责任范围内突发公共卫生事件和传染病疫情监测信息报告任务，具体职责为： （一）建立突发公共卫生事件和传染病疫情信息监测报告制度，包括报告卡和总登记簿、疫情收报、核对、自查、奖惩。 （二）执行首诊负责制，严格门诊工作日志制度以及突发公共卫生事件和疫情报告制度，负责突发公共卫生事件和疫情监测信息报告工作。 （三）建立或指定专门的部门和人员，配备必要的设备，保证突发公共卫生事件和疫情监测信息的网络直接报告。 门诊部、诊所、卫生所（室）等应按照规定时限，以最快通讯方式向发病地疾病预防控制机构进行报告，并同时报出传染病报告卡。 报告卡片邮寄信封应当印有明显的“突发公共卫生事件或疫情”标志及写明××疾病预防控制机构收的字样。 （四）对医生和实习生进行有关突发公共卫生事件和传染病疫情监测信息报告工作的培训。 （五）配合疾病预防控制机构开展流行病学调查和标本采样。"},{"i":11,"n":"第十一条","txt":"流动人员中发生的突发公共卫生事件和传染病病人、病原携带者和疑似传染病病人的报告、处理、疫情登记、统计，由诊治地负责。"},{"i":12,"n":"第十二条","txt":"铁路、交通、民航、厂（场）矿所属的医疗卫生机构发现突发公共卫生事件和传染病疫情，应按属地管理原则向所在地县级疾病预防控制机构报告。"},{"i":13,"n":"第十三条","txt":"军队内的突发公共卫生事件和军人中的传染病疫情监测信息，由中国人民解放军卫生主管部门根据有关规定向国务院卫生行政部门直接报告。 军队所属医疗卫生机构发现地方就诊的传染病病人、病原携带者、疑似传染病病人时，应按属地管理原则向所在地疾病预防控制机构报告。"},{"i":14,"n":"第十四条","txt":"医疗卫生人员未经当事人同意，不得将传染病病人及其家属的姓名、住址和个人病史以任何形式向社会公开。"},{"i":15,"n":"第十五条","txt":"各级政府卫生行政部门对辖区内各级医疗卫生机构负责的突发公共卫生事件和传染病疫情监测信息报告情况，定期进行监督、检查和指导。"},{"i":16,"n":"第十六条","txt":"各级各类医疗机构、疾病预防控制机构、采供血机构均为责任报告单位；其执行职务的人员和乡村医生、个体开业医生均为责任疫情报告人，必须按照传染病防治法的规定进行疫情报告，履行法律规定的义务。"},{"i":17,"n":"第十七条","txt":"责任报告人在首次诊断传染病病人后，应立即填写传染病报告卡。 传染病报告卡由录卡单位保留三年。"},{"i":18,"n":"第十八条","txt":"责任报告单位和责任疫情报告人发现甲类传染病和乙类传染病中的肺炭疽、传染性非典型肺炎、脊髓灰质炎、人感染高致病性禽流感病人或疑似病人时，或发现其他传染病和不明原因疾病暴发时，应于2小时内将传染病报告卡通过网络报告；未实行网络直报的责任报告单位应于2小时内以最快的通讯方式（电话、传真）向当地县级疾病预防控制机构报告，并于2小时内寄送出传染病报告卡。 对其他乙、丙类传染病病人、疑似病人和规定报告的传染病病原携带者在诊断后，实行网络直报的责任报告单位应于24小时内进行网络报告；未实行网络直报的责任报告单位应于24小时内寄送出传染病报告卡。 县级疾病预防控制机构收到无网络直报条件责任报告单位报送的传染病报告卡后，应于2小时内通过网络进行直报。"},{"i":19,"n":"第十九条","txt":"获得突发公共卫生事件相关信息的责任报告单位和责任报告人，应当在2小时内以电话或传真等方式向属地卫生行政部门指定的专业机构报告，具备网络直报条件的要同时进行网络直报，直报的信息由指定的专业机构审核后进入国家数据库。不具备网络直报条件的责任报告单位和责任报告人，应采用最快的通讯方式将《突发公共卫生事件相关信息报告卡》报送属地卫生行政部门指定的专业机构，接到《突发公共卫生事件相关信息报告卡》的专业机构，应对信息进行审核，确定真实性，2小时内进行网络直报，同时以电话或传真等方式报告同级卫生行政部门。 接到突发公共卫生事件相关信息报告的卫生行政部门应当尽快组织有关专家进行现场调查，如确认为实际发生突发公共卫生事件，应根据不同的级别，及时组织采取相应的措施，并在2小时内向本级人民政府报告，同时向上一级人民政府卫生行政部门报告。如尚未达到突发公共卫生事件标准的，由专业防治机构密切跟踪事态发展，随时报"},{"i":20,"n":"第二十条","txt":"突发公共卫生事件及传染病信息报告的其它事项按照《突发公共卫生事件相关信息报告管理工作规范（试行）》及《传染病信息报告管理规范》有关规定执行。"},{"i":21,"n":"第二十一条","txt":"接到突发公共卫生事件报告的地方卫生行政部门，应当立即组织力量对报告事项调查核实、判定性质，采取必要的控制措施，并及时报告调查情况。 不同类别的突发公共卫生事件的调查应当按照《全国突发公共卫生事件应急预案》规定要求执行。"},{"i":22,"n":"第二十二条","txt":"突发公共卫生事件与传染病疫情现场调查应包括以下工作内容： （一）流行病学个案调查、密切接触者追踪调查和传染病发病原因、发病情况、疾病流行的可能因素等调查； （二）相关标本或样品的采样、技术分析、检验； （三）突发公共卫生事件的确证； （四）卫生监测，包括生活资源受污染范围和严重程度，必要时应在突发事件发生地及相邻省市同时进行。"},{"i":23,"n":"第二十三条","txt":"各级卫生行政部门应当组织疾病预防控制机构等有关领域的专业人员，建立流行病学调查队伍，负责突发公共卫生事件与传染病疫情的流行病学调查工作。"},{"i":24,"n":"第二十四条","txt":"疾病预防控制机构发现传染病疫情或接到传染病疫情报告时，应当及时采取下列措施： （一）对传染病疫情进行流行病学调查，根据调查情况提出划定疫点、疫区的建议，对被污染的场所进行卫生处理，对密切接触者，在指定场所进行医学观察和采取其他必要的预防措施，并向卫生行政部门提出疫情控制方案； （二）传染病暴发、流行时，对疫点、疫区进行卫生处理，向卫生行政部门提出疫情控制方案，并按照卫生行政部门的要求采取措施； （三）指导下级疾病预防控制机构实施传染病预防、控制措施，组织、指导有关单位对传染病疫情的处理。"},{"i":25,"n":"第二十五条","txt":"各级疾病预防控制机构负责管理国家突发公共卫生事件与传染病疫情监测报告信息系统，各级责任报告单位使用统一的信息系统进行报告。"},{"i":26,"n":"第二十六条","txt":"各级各类医疗机构应积极配合疾病预防控制机构专业人员进行突发公共卫生事件和传染病疫情调查、采样与处理。"},{"i":27,"n":"第二十七条","txt":"各级各类医疗机构所设与诊治传染病有关的科室应当建立门诊日志、住院登记簿和传染病疫情登记簿。"},{"i":28,"n":"第二十八条","txt":"各级各类医疗机构指定的部门和人员，负责本单位突发公共卫生事件和传染病疫情报告卡的收发和核对，设立传染病报告登记簿，统一填报有关报表。"},{"i":29,"n":"第二十九条","txt":"县级疾病预防控制机构负责本辖区内突发公共卫生事件和传染病疫情报告卡、报表的收发、核对、疫情的报告和管理工作。 各级疾病预防控制机构应当按照国家公共卫生监测体系网络系统平台的要求，充分利用报告的信息资料，建立突发公共卫生事件和传染病疫情定期分析通报制度，常规监测时每月不少于三次疫情分析与通报，紧急情况下需每日进行疫情分析与通报。"},{"i":30,"n":"第三十条","txt":"国境口岸所在地卫生行政部门指定的疾病预防控制机构和港口、机场、铁路等疾病预防控制机构及国境卫生检疫机构，发现国境卫生检疫法规定的检疫传染病时，应当互相通报疫情。"},{"i":31,"n":"第三十一条","txt":"发现人畜共患传染病时，当地疾病预防控制机构和农、林部门应当互相通报疫情。"},{"i":32,"n":"第三十二条","txt":"国务院卫生行政部门应当及时通报和公布突发公共卫生事件和传染病疫情，省（自治区、直辖市）人民政府卫生行政部门根据国务院卫生行政部门的授权，及时通报和公布本行政区域的突发公共卫生事件和传染病疫情。 突发公共卫生事件和传染病疫情发布内容包括： （一）突发公共卫生事件和传染病疫情性质、原因； （二）突发公共卫生事件和传染病疫情发生地及范围； （三）突发公共卫生事件和传染病疫情的发病、伤亡及涉及的人员范围； （四）突发公共卫生事件和传染病疫情处理措施和控制情况； （五）突发公共卫生事件和传染病疫情发生地的解除。 与港澳台地区及有关国家和世界卫生组织之间的交流与通报办法另行制订。"},{"i":33,"n":"第三十三条","txt":"国务院卫生行政部门对全国突发公共卫生事件与传染病疫情监测信息报告管理工作进行监督、指导。 县级以上地方人民政府卫生行政部门对本行政区域的突发公共卫生事件与传染病疫情监测信息报告管理工作进行监督、指导。"},{"i":34,"n":"第三十四条","txt":"各级卫生监督机构在卫生行政部门的领导下，具体负责本行政区内的突发公共卫生事件与传染病疫情监测信息报告管理工作的监督检查。"},{"i":35,"n":"第三十五条","txt":"各级疾病预防控制机构在卫生行政部门的领导下，具体负责对本行政区域内的突发公共卫生事件与传染病疫情监测信息报告管理工作的技术指导。"},{"i":36,"n":"第三十六条","txt":"各级各类医疗卫生机构在卫生行政部门的领导下，积极开展突发公共卫生事件与传染病疫情监测信息报告管理工作。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人发现责任报告单位或责任疫情报告人有瞒报、缓报、谎报突发公共卫生事件和传染病疫情情况时，应向当地卫生行政部门报告。"},{"i":38,"n":"第三十八条","txt":"医疗机构有下列行为之一的，由县级以上地方卫生行政部门责令改正、通报批评、给予警告；情节严重的，会同有关部门对主要负责人、负有责任的主管人员和其他责任人员依法给予降级、撤职的行政处分；造成传染病传播、流行或者对社会公众健康造成其他严重危害后果，构成犯罪的，依据刑法追究刑事责任： （一）未建立传染病疫情报告制度的； （二）未指定相关部门和人员负责传染病疫情报告管理工作的； （三）瞒报、缓报、谎报发现的传染病病人、病原携带者、疑似病人的。"},{"i":39,"n":"第三十九条","txt":"疾病预防控制机构有下列行为之一的，由县级以上地方卫生行政部门责令改正、通报批评、给予警告；对主要负责人、负有责任的主管人员和其他责任人员依法给予降级、撤职的行政处分；造成传染病传播、流行或者对社会公众健康造成其他严重危害后果，构成犯罪的，依法追究刑事责任： （一）瞒报、缓报、谎报发现的传染病病人、病原携带者、疑似病人的； （二）未按规定建立专门的流行病学调查队伍，进行传染病疫情的流行病学调查工作； （三）在接到传染病疫情报告后，未按规定派人进行现场调查的； （四）未按规定上报疫情或报告突发公共卫生事件的。"},{"i":40,"n":"第四十条","txt":"执行职务的医疗卫生人员瞒报、缓报、谎报传染病疫情的，由县级以上卫生行政部门给予警告，情节严重的，责令暂停六个月以上一年以下执业活动，或者吊销其执业证书。 责任报告单位和事件发生单位瞒报、缓报、谎报或授意他人不报告突发性公共卫生事件或传染病疫情的，对其主要领导、主管人员和直接责任人由其单位或上级主管机关给予行政处分，造成疫情播散或事态恶化等严重后果的，由司法机关追究其刑事责任。"},{"i":41,"n":"第四十一条","txt":"个体或私营医疗保健机构瞒报、缓报、谎报传染病疫情或突发性公共卫生事件的，由县级以上卫生行政部门责令限期改正，可以处100元以上500元以下罚款；对造成突发性公共卫生事件和传染病传播流行的，责令停业整改，并可以处200元以上2000元以下罚款，触犯刑律的，对其经营者、主管人员和直接责任人移交司法机关追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"县级以上卫生行政部门未按照规定履行突发公共卫生事件和传染病疫情报告职责，瞒报、缓报、谎报或者授意他人瞒报、缓报、谎报的，对主要负责人依法给予降级或者撤职的行政处分；造成传染病传播、流行或者对社会公众造成其他严重危害后果的，给予开除处分；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"中国人民解放军、武装警察部队医疗卫生机构突发公共卫生事件与传染病疫情监测信息报告管理工作，参照本办法的规定和军队的相关规定执行。"},{"i":44,"n":"第四十四条","txt":"本办法自发布之日起实施。"}],"jiehebingfangzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步做好结核病防治工作，有效预防、控制结核病的传播和流行，保障人体健康和公共卫生安全，根据《中华人民共和国传染病防治法》及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"坚持预防为主、防治结合的方针，建立政府组织领导、部门各负其责、全社会共同参与的结核病防治机制。加强宣传教育，实行以及时发现患者、规范治疗管理和关怀救助为重点的防治策略。"},{"i":3,"n":"第三条","txt":"卫生部负责全国结核病防治及其监督管理工作，县级以上地方卫生行政部门负责本辖区内的结核病防治及其监督管理工作。 卫生行政部门应当积极协调有关部门加强结核病防治能力建设，逐步构建结核病定点医疗机构、基层医疗卫生机构、疾病预防控制机构分工明确、协调配合的防治服务体系。"},{"i":4,"n":"第四条","txt":"各级各类医疗卫生机构应当按照有关法律法规和卫生行政部门的规定，在职责范围内做好结核病防治的疫情监测和报告、诊断治疗、感染控制、转诊服务、患者管理、宣传教育等工作。"},{"i":5,"n":"第五条","txt":"卫生部组织制定全国结核病防治规划、技术规范和标准；统筹医疗卫生资源，建设和管理全国结核病防治服务体系；对全国结核病防治工作进行监督检查及评价。"},{"i":6,"n":"第六条","txt":"县级以上地方卫生行政部门负责拟订本辖区内结核病防治规划并组织实施；组织协调辖区内结核病防治服务体系的建设和管理，指定结核病定点医疗机构；统筹规划辖区内结核病防治资源，对结核病防治服务体系给予必要的政策和经费支持；组织开展结核病防治工作的监督、检查和绩效评估。"},{"i":7,"n":"第七条","txt":"疾病预防控制机构在结核病防治工作中履行以下职责： （一）协助卫生行政部门开展规划管理及评估工作； （二）收集、分析信息，监测肺结核疫情；及时准确报告、通报疫情及相关信息；开展流行病学调查、疫情处置等工作； （三）组织落实肺结核患者治疗期间的规范管理； （四）组织开展肺结核或者疑似肺结核患者及密切接触者的追踪工作； （五）组织开展结核病高发和重点行业人群的防治工作； （六）开展结核病实验室检测，对辖区内的结核病实验室进行质量控制； （七）组织开展结核病防治培训，提供防治技术指导； （八）组织开展结核病防治健康教育工作； （九）开展结核病防治应用性研究。"},{"i":8,"n":"第八条","txt":"结核病定点医疗机构在结核病防治工作中履行以下职责： （一）负责肺结核患者诊断治疗，落实治疗期间的随访检查； （二）负责肺结核患者报告、登记和相关信息的录入工作； （三）对传染性肺结核患者的密切接触者进行检查； （四）对患者及其家属进行健康教育。"},{"i":9,"n":"第九条","txt":"非结核病定点医疗机构在结核病防治工作中履行以下职责： （一）指定内设职能科室和人员负责结核病疫情的报告； （二）负责结核病患者和疑似患者的转诊工作； （三）开展结核病防治培训工作； （四）开展结核病防治健康教育工作。"},{"i":10,"n":"第十条","txt":"基层医疗卫生机构在结核病防治工作中履行以下职责： （一）负责肺结核患者居家治疗期间的督导管理； （二）负责转诊、追踪肺结核或者疑似肺结核患者及有可疑症状的密切接触者； （三）对辖区内居民开展结核病防治知识宣传。"},{"i":11,"n":"第十一条","txt":"各级各类医疗卫生机构应当开展结核病防治的宣传教育，对就诊的肺结核患者及家属进行健康教育，宣传结核病防治政策和知识。 基层医疗卫生机构定期对辖区内居民进行健康教育和宣传。 疾病预防控制机构对易患结核病重点人群和重点场所进行有针对性的健康教育和宣传工作。"},{"i":12,"n":"第十二条","txt":"根据国家免疫规划对适龄儿童开展卡介苗预防接种工作。 承担预防接种工作的医疗卫生机构应当按照《疫苗流通和预防接种管理条例》和预防接种工作规范的要求，规范提供预防接种服务。"},{"i":13,"n":"第十三条","txt":"医疗卫生机构在组织开展健康体检和预防性健康检查时，应当重点做好以下人群的肺结核筛查工作： （一）从事结核病防治的医疗卫生人员； （二）食品、药品、化妆品从业人员； （三）《公共场所卫生管理条例》中规定的从业人员； （四）各级各类学校、托幼机构的教职员工及学校入学新生； （五）接触粉尘或者有害气体的人员； （六）乳牛饲养业从业人员； （七）其他易使肺结核扩散的人员。"},{"i":14,"n":"第十四条","txt":"医疗卫生机构要制订结核病感染预防与控制计划，健全规章制度和工作规范，开展结核病感染预防与控制相关工作，落实各项结核病感染防控措施，防止医源性感染和传播。 结核病定点医疗机构应当重点采取以下感染预防与控制措施： （一）结核病门诊、病房设置应当符合国家有关规定； （二）严格执行环境卫生及消毒隔离制度，注意环境通风； （三）对于被结核分枝杆菌污染的痰液等排泄物和污物、污水以及医疗废物，应当按照医疗废物管理的相关规定进行分类收集、暂存及处置； （四）为肺结核可疑症状者或者肺结核患者采取必要的防护措施，避免交叉感染发生。"},{"i":15,"n":"第十五条","txt":"医务人员在工作中严格遵守个人防护的基本原则，接触传染性肺结核患者或者疑似肺结核患者时，应当采取必要的防护措施。"},{"i":16,"n":"第十六条","txt":"疾病预防控制机构、医疗机构、科研等单位的结核病实验室和实验活动，应当符合病原微生物生物安全管理各项规定。 医疗机构实验室的结核病检测工作，按照卫生部医疗机构临床实验室管理的规定进行统一管理和质量控制。"},{"i":17,"n":"第十七条","txt":"肺结核疫情构成突发公共卫生事件的，应当按照有关预案采取以下控制措施： （一）依法做好疫情信息报告和风险评估； （二）开展疫情流行病学调查和现场处置； （三）将发现的肺结核患者纳入规范化治疗管理； （四）对传染性肺结核患者的密切接触者进行医学观察，必要时在征得本人同意后对其实施预防性化疗； （五）开展疫情风险沟通和健康教育工作，及时向社会公布疫情处置情况。"},{"i":18,"n":"第十八条","txt":"各级各类医疗机构应当对肺结核可疑症状者及时进行检查，对发现的确诊和疑似肺结核患者应当按照有关规定进行疫情报告，并将其转诊到患者居住地或者就诊医疗机构所在地的结核病定点医疗机构。"},{"i":19,"n":"第十九条","txt":"卫生行政部门指定的医疗卫生机构应当按照有关工作规范，对艾滋病病毒感染者和艾滋病患者进行结核病筛查和确诊。"},{"i":20,"n":"第二十条","txt":"基层医疗卫生机构协助县级疾病预防控制机构，对已进行疫情报告但未到结核病定点医疗机构就诊的肺结核患者和疑似肺结核患者进行追踪，督促其到结核病定点医疗机构进行诊断。"},{"i":21,"n":"第二十一条","txt":"结核病定点医疗机构应当对肺结核患者进行诊断，并对其中的传染性肺结核患者的密切接触者进行结核病筛查。 承担耐多药肺结核防治任务的结核病定点医疗机构应当对耐多药肺结核可疑者进行痰分枝杆菌培养检查和抗结核药物敏感性试验。"},{"i":22,"n":"第二十二条","txt":"结核病定点医疗机构对肺结核患者进行管理登记。登记内容包括患者诊断、治疗及管理等相关信息。结核病定点医疗机构应当根据患者治疗管理等情况，及时更新患者管理登记内容。"},{"i":23,"n":"第二十三条","txt":"结核病疫情的报告、通报和公布，依照《传染病防治法》的有关规定执行。"},{"i":24,"n":"第二十四条","txt":"对发现的肺结核患者进行规范化治疗和督导管理。"},{"i":25,"n":"第二十五条","txt":"结核病定点医疗机构应当为肺结核患者制定合理的治疗方案，提供规范化的治疗服务。 设区的市级以上结核病定点医疗机构严格按照实验室检测结果，为耐多药肺结核患者制定治疗方案，并规范提供治疗。"},{"i":26,"n":"第二十六条","txt":"各级各类医疗机构对危、急、重症肺结核患者负有救治的责任，应当及时对患者进行医学处置，不得以任何理由推诿，不得因就诊的患者是结核病病人拒绝对其其他疾病进行治疗。"},{"i":27,"n":"第二十七条","txt":"疾病预防控制机构应当及时掌握肺结核患者的相关信息，督促辖区内医疗卫生机构落实肺结核患者的治疗和管理工作。"},{"i":28,"n":"第二十八条","txt":"基层医疗卫生机构应当对居家治疗的肺结核患者进行定期访视、督导服药等管理。"},{"i":29,"n":"第二十九条","txt":"卫生行政部门指定的医疗机构应当按照有关工作规范对结核菌/艾滋病病毒双重感染患者进行抗结核和抗艾滋病病毒治疗、随访复查和管理。"},{"i":30,"n":"第三十条","txt":"医疗卫生机构对流动人口肺结核患者实行属地化管理，提供与当地居民同等的服务。 转出地和转入地结核病定点医疗机构应当及时交换流动人口肺结核患者的信息，确保落实患者的治疗和管理措施。"},{"i":31,"n":"第三十一条","txt":"县级以上地方卫生行政部门对结核病防治工作行使下列监管职责： （一）对结核病的预防、患者发现、治疗管理、疫情报告及监测等管理措施落实情况进行监管； （二）对违反本办法的行为责令被检查单位或者个人限期进行改进，依法查处； （三）负责预防与控制结核病的其他监管事项。"},{"i":32,"n":"第三十二条","txt":"县级以上地方卫生行政部门要重点加强对相关单位以下结核病防治工作的监管： （一）结核病定点医疗机构的诊断、治疗、管理和信息录入等工作； （二）疾病预防控制机构的结核病疫情监测与处置、流行病学调查、高发和重点行业人群防治、实验室检测和质量控制、实验室生物安全、督导、培训和健康促进等工作； （三）基层医疗卫生机构的转诊、追踪、患者督导管理和健康教育等工作； （四）非结核病定点医疗机构的结核病疫情报告、转诊、培训、健康教育等工作。"},{"i":33,"n":"第三十三条","txt":"卫生行政部门依照本办法实施监管职责时，根据结核病防治工作的需要，可向有关单位和个人了解情况，索取必要的资料，对有关场所进行检查。在执行公务中应当保护患者的隐私，不得泄漏患者个人信息及相关资料等。被检查单位和个人应当予以配合，如实提供有关情况，不得拒绝、阻挠。"},{"i":34,"n":"第三十四条","txt":"县级以上地方卫生行政部门有下列情形之一的，由上级卫生行政部门责令改正，通报批评；造成肺结核传播、流行或者其他严重后果的，对负有责任的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）未履行肺结核疫情报告职责，或者瞒报、谎报、缓报肺结核疫情的； （二）未及时采取预防、控制措施导致发生或者可能发生肺结核传播的； （三）未履行监管职责，或者发现违法行为不及时查处的。"},{"i":35,"n":"第三十五条","txt":"疾病预防控制机构违反本办法规定，有下列情形之一的，由县级以上卫生行政部门责令限期改正，通报批评，给予警告；对负有责任的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未依法履行肺结核疫情监测、报告职责，或者隐瞒、谎报、缓报肺结核疫情的； （二）发现肺结核疫情时，未依据职责及时采取措施的； （三）故意泄露涉及肺结核患者、疑似肺结核患者、密切接触者个人隐私的有关信息、资料的； （四）未履行对辖区实验室质量控制、培训等防治职责的。"},{"i":36,"n":"第三十六条","txt":"医疗机构违反本办法规定，有下列情形之一的，由县级以上卫生行政部门责令改正，通报批评，给予警告；造成肺结核传播、流行或者其他严重后果的，对负有责任的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未按照规定报告肺结核疫情，或者隐瞒、谎报、缓报肺结核疫情的； （二）非结核病定点医疗机构发现确诊或者疑似肺结核患者，未按照规定进行转诊的； （三）结核病定点医疗机构未按照规定对肺结核患者或者疑似肺结核患者诊断治疗的，或者拒绝接诊的； （四）未按照有关规定严格执行隔离消毒制度，对结核菌污染的痰液、污物和污水未进行卫生处理的； （五）故意泄露涉及肺结核患者、疑似肺结核患者、密切接触者个人隐私的有关信息和资料的。"},{"i":37,"n":"第三十七条","txt":"基层医疗卫生机构违反本办法规定，有下列情形之一的，由县级卫生行政部门责令改正，给予警告： （一）未履行对辖区内肺结核患者居家治疗期间的督导管理职责的； （二）未按照规定转诊、追踪肺结核患者或者疑似肺结核患者及有可疑症状的密切接触者。"},{"i":38,"n":"第三十八条","txt":"其他单位和个人违反本办法规定，导致肺结核传播或者流行，给他人人身、财产造成损害的，应当依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"本办法下列用语含义： 肺结核可疑症状者：咳嗽、咯痰2周以上以及咯血或者血痰是肺结核的主要症状，具有以上任何一项症状者为肺结核可疑症状者。 疑似肺结核患者：凡符合下列条件之一者为疑似病例。（1）有肺结核可疑症状的5岁以下儿童，同时伴有与传染性肺结核患者密切接触史或者结核菌素试验强阳性；（2）仅胸部影像学检查显示与活动性肺结核相符的病变。 传染性肺结核：指痰涂片检测阳性的肺结核。 密切接触者：指与传染性肺结核患者直接接触的人员，包括患者的家庭成员、同事和同学等。 耐多药肺结核：肺结核患者感染的结核分枝杆菌体外被证实至少同时对异烟肼和利福平耐药。 结核菌/艾滋病病毒双重感染：指艾滋病病毒感染者或者艾滋病患者发生活动性肺结核，或者结核病患者感染艾滋病病毒。 转诊：指各级医疗卫生机构将发现的疑似或确诊的肺结核患者转至结核病定点医疗机构。 追踪：指基层医疗卫生机构在疾病预防控制机构的指导下，对未到"},{"i":40,"n":"第四十条","txt":"本办法由卫生部负责解释。"},{"i":41,"n":"第四十一条","txt":"本办法自2013年3月24日起施行。1991年9月12日卫生部公布的《结核病防治管理办法》同时废止。"}],"zhiyejiankangjianchaguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强职业健康检查工作，规范职业健康检查机构管理，保护劳动者健康权益，根据《中华人民共和国职业病防治法》（以下简称《职业病防治法》），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称职业健康检查是指医疗卫生机构按照国家有关规定，对从事接触职业病危害作业的劳动者进行的上岗前、在岗期间、离岗时的健康检查。"},{"i":3,"n":"第三条","txt":"国家卫生健康委负责全国范围内职业健康检查工作的监督管理。 县级以上地方卫生健康主管部门负责本辖区职业健康检查工作的监督管理；结合职业病防治工作实际需要，充分利用现有资源，统一规划、合理布局；加强职业健康检查机构能力建设，并提供必要的保障条件。"},{"i":4,"n":"第四条","txt":"医疗卫生机构开展职业健康检查，应当在开展之日起15个工作日内向省级卫生健康主管部门备案。备案的具体办法由省级卫生健康主管部门依据本办法制定，并向社会公布。 省级卫生健康主管部门应当及时向社会公布备案的医疗卫生机构名单、地址、检查类别和项目等相关信息，并告知核发其《医疗机构执业许可证》的卫生健康主管部门。核发其《医疗机构执业许可证》的卫生健康主管部门应当在该机构的《医疗机构执业许可证》副本备注栏注明检查类别和项目等信息。"},{"i":5,"n":"第五条","txt":"承担职业健康检查的医疗卫生机构（以下简称职业健康检查机构）应当具备以下条件： （一）持有《医疗机构执业许可证》，涉及放射检查项目的还应当持有《放射诊疗许可证》； （二）具有相应的职业健康检查场所、候检场所和检验室，建筑总面积不少于400平方米，每个独立的检查室使用面积不少于6平方米； （三）具有与备案开展的职业健康检查类别和项目相适应的执业医师、护士等医疗卫生技术人员； （四）至少具有1名取得职业病诊断资格的执业医师； （五）具有与备案开展的职业健康检查类别和项目相适应的仪器、设备，具有相应职业卫生生物监测能力；开展外出职业健康检查，应当具有相应的职业健康检查仪器、设备、专用车辆等条件； （六）建立职业健康检查质量管理制度； （七）具有与职业健康检查信息报告相应的条件。 医疗卫生机构进行职业健康检查备案时，应当提交证明其符合以上条件的有关资料。"},{"i":6,"n":"第六条","txt":"开展职业健康检查工作的医疗卫生机构对备案的职业健康检查信息的真实性、准确性、合法性承担全部法律责任。 当备案信息发生变化时，职业健康检查机构应当自信息发生变化之日起10个工作日内提交变更信息。"},{"i":7,"n":"第七条","txt":"职业健康检查机构具有以下职责： （一）在备案开展的职业健康检查类别和项目范围内，依法开展职业健康检查工作，并出具职业健康检查报告； （二）履行疑似职业病的告知和报告义务； （三）报告职业健康检查信息； （四）定期向卫生健康主管部门报告职业健康检查工作情况，包括外出职业健康检查工作情况； （五）开展职业病防治知识宣传教育； （六）承担卫生健康主管部门交办的其他工作。"},{"i":8,"n":"第八条","txt":"职业健康检查机构应当指定主检医师。主检医师应当具备以下条件： （一）具有执业医师证书； （二）具有中级以上专业技术职务任职资格； （三）具有职业病诊断资格； （四）从事职业健康检查相关工作三年以上，熟悉职业卫生和职业病诊断相关标准。 主检医师负责确定职业健康检查项目和周期，对职业健康检查过程进行质量控制，审核职业健康检查报告。"},{"i":9,"n":"第九条","txt":"职业健康检查机构及其工作人员应当关心、爱护劳动者，尊重和保护劳动者的知情权及个人隐私。"},{"i":10,"n":"第十条","txt":"省级卫生健康主管部门应当指定机构负责本辖区内职业健康检查机构的质量控制管理工作，组织开展实验室间比对和职业健康检查质量考核。 职业健康检查质量控制规范由中国疾病预防控制中心制定。"},{"i":11,"n":"第十一条","txt":"按照劳动者接触的职业病危害因素，职业健康检查分为以下六类： （一）接触粉尘类； （二）接触化学因素类； （三）接触物理因素类； （四）接触生物因素类； （五）接触放射因素类； （六）其他类（特殊作业等）。 以上每类中包含不同检查项目。职业健康检查机构应当在备案的检查类别和项目范围内开展相应的职业健康检查。"},{"i":12,"n":"第十二条","txt":"职业健康检查机构开展职业健康检查应当与用人单位签订委托协议书，由用人单位统一组织劳动者进行职业健康检查；也可以由劳动者持单位介绍信进行职业健康检查。"},{"i":13,"n":"第十三条","txt":"职业健康检查机构应当依据相关技术规范，结合用人单位提交的资料，明确用人单位应当检查的项目和周期。"},{"i":14,"n":"第十四条","txt":"在职业健康检查中，用人单位应当如实提供以下职业健康检查所需的相关资料，并承担检查费用： （一）用人单位的基本情况； （二）工作场所职业病危害因素种类及其接触人员名册、岗位（或工种）、接触时间； （三）工作场所职业病危害因素定期检测等相关资料。"},{"i":15,"n":"第十五条","txt":"职业健康检查的项目、周期按照《职业健康监护技术规范》（GBZ 188)执行，放射工作人员职业健康检查按照《放射工作人员职业健康监护技术规范》(GBZ 235)等规定执行。"},{"i":16,"n":"第十六条","txt":"职业健康检查机构可以在执业登记机关管辖区域内或者省级卫生健康主管部门指定区域内开展外出职业健康检查。外出职业健康检查进行医学影像学检查和实验室检测，必须保证检查质量并满足放射防护和生物安全的管理要求。"},{"i":17,"n":"第十七条","txt":"职业健康检查机构应当在职业健康检查结束之日起30个工作日内将职业健康检查结果，包括劳动者个人职业健康检查报告和用人单位职业健康检查总结报告，书面告知用人单位，用人单位应当将劳动者个人职业健康检查结果及职业健康检查机构的建议等情况书面告知劳动者。"},{"i":18,"n":"第十八条","txt":"职业健康检查机构发现疑似职业病病人时，应当告知劳动者本人并及时通知用人单位，同时向所在地卫生健康主管部门报告。发现职业禁忌的，应当及时告知用人单位和劳动者。"},{"i":19,"n":"第十九条","txt":"职业健康检查机构要依托现有的信息平台，加强职业健康检查的统计报告工作，逐步实现信息的互联互通和共享。"},{"i":20,"n":"第二十条","txt":"职业健康检查机构应当建立职业健康检查档案。职业健康检查档案保存时间应当自劳动者最后一次职业健康检查结束之日起不少于15年。 职业健康检查档案应当包括下列材料： （一）职业健康检查委托协议书； （二）用人单位提供的相关资料； （三）出具的职业健康检查结果总结报告和告知材料； （四）其他有关材料。"},{"i":21,"n":"第二十一条","txt":"县级以上地方卫生健康主管部门应当加强对本辖区职业健康检查机构的监督管理。按照属地化管理原则，制定年度监督检查计划，做好职业健康检查机构的监督检查工作。监督检查主要内容包括： （一）相关法律法规、标准的执行情况； （二）按照备案的类别和项目开展职业健康检查工作的情况； （三）外出职业健康检查工作情况； （四）职业健康检查质量控制情况； （五）职业健康检查结果、疑似职业病的报告与告知以及职业健康检查信息报告情况； （六）职业健康检查档案管理情况等。"},{"i":22,"n":"第二十二条","txt":"省级卫生健康主管部门应当对本辖区内的职业健康检查机构进行定期或者不定期抽查；设区的市级卫生健康主管部门每年应当至少组织一次对本辖区内职业健康检查机构的监督检查；县级卫生健康主管部门负责日常监督检查。"},{"i":23,"n":"第二十三条","txt":"县级以上地方卫生健康主管部门监督检查时，有权查阅或者复制有关资料，职业健康检查机构应当予以配合。"},{"i":24,"n":"第二十四条","txt":"无《医疗机构执业许可证》擅自开展职业健康检查的，由县级以上地方卫生健康主管部门依据《医疗机构管理条例》第四十四条的规定进行处理。"},{"i":25,"n":"第二十五条","txt":"职业健康检查机构有下列行为之一的，由县级以上地方卫生健康主管部门责令改正，给予警告，可以并处3万元以下罚款： （一）未按规定备案开展职业健康检查的； （二）未按规定告知疑似职业病的； （三）出具虚假证明文件的。"},{"i":26,"n":"第二十六条","txt":"职业健康检查机构未按照规定报告疑似职业病的，由县级以上地方卫生健康主管部门依据《职业病防治法》第七十四条的规定进行处理。"},{"i":27,"n":"第二十七条","txt":"职业健康检查机构有下列行为之一的，由县级以上地方卫生健康主管部门给予警告，责令限期改正；逾期不改的，处以三万元以下罚款： （一）未指定主检医师或者指定的主检医师未取得职业病诊断资格的； （二）未按要求建立职业健康检查档案的； （三）未履行职业健康检查信息报告义务的； （四）未按照相关职业健康监护技术规范规定开展工作的； （五）违反本办法其他有关规定的。"},{"i":28,"n":"第二十八条","txt":"职业健康检查机构未按规定参加实验室比对或者职业健康检查质量考核工作，或者参加质量考核不合格未按要求整改仍开展职业健康检查工作的，由县级以上地方卫生健康主管部门给予警告，责令限期改正；逾期不改的，处以三万元以下罚款。"},{"i":29,"n":"第二十九条","txt":"本办法自2015年5月1日起施行。2002年3月28日原卫生部公布的《职业健康监护管理办法》同时废止。"}],"zhiyeweishengjishufuwujigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对职业卫生技术服务机构的监督管理，规范职业卫生技术服务行为，根据《中华人民共和国职业病防治法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请职业卫生技术服务机构资质，从事职业卫生检测、评价技术服务以及卫生健康主管部门实施职业卫生技术服务机构资质认可与监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称职业卫生技术服务机构，是指为用人单位提供职业病危害因素检测、职业病危害现状评价、职业病防护设备设施与防护用品的效果评价等技术服务的机构。"},{"i":4,"n":"第四条","txt":"国家对职业卫生技术服务机构实行资质认可制度。职业卫生技术服务机构应当依照本办法取得职业卫生技术服务机构资质；未取得职业卫生技术服务机构资质的，不得从事职业卫生检测、评价技术服务。"},{"i":5,"n":"第五条","txt":"职业卫生技术服务机构资质由省、自治区、直辖市卫生健康主管部门认可及颁发证书。 省、自治区、直辖市卫生健康主管部门统称资质认可机关。"},{"i":6,"n":"第六条","txt":"取得资质的职业卫生技术服务机构，可以根据认可的业务范围在全国从事职业卫生技术服务活动。"},{"i":7,"n":"第七条","txt":"国家卫生健康委、国家疾控局依据各自职责负责指导全国职业卫生技术服务机构的监督管理工作。 县级以上地方卫生健康、疾病预防控制主管部门依据各自职责负责本行政区域内职业卫生技术服务机构的监督管理工作。"},{"i":8,"n":"第八条","txt":"国家鼓励职业卫生技术服务行业加强自律，规范执业行为，维护行业秩序。"},{"i":9,"n":"第九条","txt":"申请职业卫生技术服务机构资质的申请人，应当具备下列条件： （一）能够独立承担民事责任； （二）有固定工作场所，实验室、档案室等场所的面积与所申请资质、业务范围相适应； （三）具有符合要求的实验室，具备与所申请资质、业务范围相适应的仪器设备； （四）有健全的内部管理制度和质量保证体系； （五）具有满足学历、专业、技术职称等要求的专业技术人员，专业技术人员不少于十五名； （六）有专职技术负责人和质量控制负责人。专职技术负责人具有高级专业技术职称和三年以上职业卫生相关工作经验，或者中级专业技术职称和八年以上职业卫生相关工作经验。质量控制负责人具有高级专业技术职称和三年以上相关工作经验，或者中级专业技术职称和五年以上相关工作经验； （七）具有与所申请业务范围相适应的检测、评价能力； （八）截至申请之日五年内无严重违法失信记录； （九）正常运行并可以供公众查询信息的网站； （十）法律、行政法规规"},{"i":10,"n":"第十条","txt":"申请人应当组织专业技术人员接受专业培训，确保专业技术人员熟悉职业病防治法律、法规和标准规范，并具备与其从事的职业卫生技术服务相适应的专业能力。 对专业技术人员的培训，申请人可以自行开展或者委托有条件的培训机构开展。专业技术人员的培训计划、培训记录（包括书面及影像资料）等应当归档备查。"},{"i":11,"n":"第十一条","txt":"申请人应当提交下列材料： （一）法定代表人或者主要负责人签署的申请表； （二）法定代表人或者主要负责人签署的知悉承担职业卫生技术服务的法律责任、义务、权利和风险的承诺书； （三）营业执照或者其他法人资格证明； （四）工作场所产权证明或者租赁合同； （五）专业技术人员、专职技术负责人、质量控制负责人的名单及其技术职称证书、劳动关系证明； （六）仪器设备清单、工作场所布局与面积示意图； （七）在申请职业卫生技术服务业务范围内，能够证明具有相应业务能力的其他材料。 申请人对申请材料的真实性负责。"},{"i":12,"n":"第十二条","txt":"申请职业卫生技术服务机构资质，按照下列程序办理： （一）申请人按照本办法第五条的规定向其机构所在地资质认可机关提出申请，并提交本办法第十一条第一款规定的材料； （二）资质认可机关应当自收到申请材料之日起五个工作日内作出是否受理的决定。对材料齐全，符合规定形式的，应当予以受理，并出具书面受理文书；对材料不齐全或者不符合规定形式的，应当当场或者在五个工作日内一次性告知申请人需要补正的全部内容；决定不予受理的，应当向申请人书面说明理由； （三）资质认可机关应当自受理资质申请之日起二十个工作日内，依据职业卫生技术服务机构资质认可技术评审准则，组织对申请人进行技术评审，并根据技术评审结论作出资质认可决定。决定认可的，应当自作出决定之日起十个工作日内向申请人颁发资质证书；决定不予认可的，应当向申请人书面说明理由。二十个工作日内不能作出认可决定的，经资质认可机关负责人批准，可以延长十个工作日，并应当"},{"i":13,"n":"第十三条","txt":"国家卫生健康委制定职业卫生技术服务机构资质认可有关文书样式和内容、职业卫生技术服务机构资质认可技术评审准则以及资质证书的样式，并向社会公布。"},{"i":14,"n":"第十四条","txt":"资质认可机关应当建立技术评审专家库（以下简称专家库）及其管理制度。 技术评审专家应当熟悉职业病防治法律、法规和标准规范，具有相关专业高级技术职称，连续五年以上职业卫生工作经验，良好的职业道德。 技术评审专家应当依据技术评审准则开展工作，出具评审意见，并对评审意见负责。 技术评审专家不得从事与本人有利害关系的技术评审活动。"},{"i":15,"n":"第十五条","txt":"国家卫生健康委制定并公开职业卫生技术服务机构专业技术人员考核评估大纲，资质认可机关建立题库。"},{"i":16,"n":"第十六条","txt":"资质认可机关应当从专家库中随机抽取相关专业的三至七名专家（应为单数）组成专家组，对申请人进行技术评审。 技术评审包括申请材料的技术审查和现场技术考核。申请材料的技术审查结论分为“通过”、“不通过”。技术审查结论为“通过”的，继续开展现场技术考核；技术审查结论为“不通过”的，不开展现场技术考核。 现场技术考核应当包括下列内容： （一）核查现场有关设备、设施、仪器、仪表等； （二）依据考核评估大纲和题库，考核评估专职技术负责人、质量控制负责人及有关专业技术人员专业知识和实际操作能力； （三）抽查原始工作记录、影像资料、报告、总结、档案等资料； （四）进行必要的盲样检测。 现场技术考核的时间一般不超过十个工作日。现场技术考核结论分为“通过”、“不通过”。"},{"i":17,"n":"第十七条","txt":"职业卫生技术服务机构资质证书有效期为五年。资质证书有效期届满需要延续的，职业卫生技术服务机构应当在有效期届满三个月前向原资质认可机关提出申请。经审核合格的，予以批准延续；不合格的，不予批准延续，并向申请人书面说明理由。"},{"i":18,"n":"第十八条","txt":"职业卫生技术服务机构取得资质一年以上，需要增加业务范围的，应当向原资质认可机关提出申请。资质认可机关应当按照本办法的规定进行认可。"},{"i":19,"n":"第十九条","txt":"职业卫生技术服务机构变更名称、法定代表人或者主要负责人、注册地址、实验室地址的，应当向原资质认可机关申请办理变更手续。 职业卫生技术服务机构分立、合并的，应当申请办理资质认可变更手续或者重新申请职业卫生技术服务机构资质认可。"},{"i":20,"n":"第二十条","txt":"职业卫生技术服务机构资质证书遗失的，应当自证书遗失之日起三十日内向原资质认可机关书面申请补发。"},{"i":21,"n":"第二十一条","txt":"职业卫生技术服务机构不得涂改、倒卖、出租、出借职业卫生技术服务机构资质证书，或者以其他形式非法转让职业卫生技术服务机构资质证书。"},{"i":22,"n":"第二十二条","txt":"资质认可机关对取得资质的职业卫生技术服务机构应当及时向社会公布，接受社会监督。"},{"i":23,"n":"第二十三条","txt":"职业卫生技术服务机构应当建立、健全职业卫生技术服务责任制。主要负责人对本机构的职业卫生技术服务工作全面负责。专职技术负责人和质量控制负责人应当按照法律、法规和标准规范的规定，加强职业卫生技术服务的全过程管理。报告审核人、授权签字人、技术服务项目负责人及参与人员按照职责分工参与技术服务，在技术报告及原始记录上签字，并承担相应责任。未达到技术评审考核评估要求的专业技术人员，职业卫生技术服务机构不得安排其参与职业卫生技术服务。 职业卫生技术服务机构应当组织专业技术人员每年接受不少于八学时的继续教育培训。"},{"i":24,"n":"第二十四条","txt":"职业卫生技术服务机构应当按照法律法规和《工作场所空气中有害物质监测的采样规范》（GBZ159）、《电离辐射防护与辐射源安全基本标准》(GB18871)、《工业企业设计卫生标准》（GBZ1）、《工作场所有害因素职业接触限值》（GBZ2.1、GBZ2.2）等标准规范的要求，开展现场调查、职业病危害因素识别、现场采样、现场检测、样品管理、实验室分析、数据处理及应用、危害程度评价、防护措施及其效果评价、技术报告编制等职业卫生技术服务活动，如实记录技术服务原始信息，确保相关数据信息可溯源，科学、客观、真实地反映技术服务事项，并对出具的职业卫生技术报告承担法律责任。"},{"i":25,"n":"第二十五条","txt":"职业卫生技术服务机构应当依法独立开展职业卫生技术服务活动。因检测项目限制或者样品保存时限有特殊要求而无法自行检测的，可以委托具备相应检测能力的职业卫生技术服务机构进行样品测定。样品现场采集和检测结果分析及应用等工作不得委托其他机构实施。"},{"i":26,"n":"第二十六条","txt":"职业卫生技术服务机构应当公开办事制度和程序，方便服务对象，并采取措施保证服务质量。"},{"i":27,"n":"第二十七条","txt":"职业卫生技术服务机构应当在认可的范围内开展技术服务工作，并接受技术服务所在地卫生健康、疾病预防控制主管部门的监督管理。 职业卫生技术服务机构应当按照规定及时报送职业卫生技术服务内容、时间、参与人员等相关信息。职业卫生技术服务信息报送管理规定由国家卫生健康委统一制定，并向社会公布。"},{"i":28,"n":"第二十八条","txt":"职业卫生技术服务机构开展技术服务时，应当以书面形式与用人单位明确技术服务内容、范围以及双方的责任。 用人单位提出的技术服务内容、范围及要求违反法律、法规和标准规范规定的，职业卫生技术服务机构应当予以拒绝。"},{"i":29,"n":"第二十九条","txt":"职业卫生技术服务机构及其工作人员在从事职业卫生技术服务活动中，不得有下列行为： （一）超出资质认可范围从事技术服务活动； （二）出具虚假或者失实的职业卫生技术报告； （三）转包职业卫生技术服务项目； （四）擅自更改、简化职业卫生技术服务程序和相关内容； （五）法律、法规规定的其他违法行为。"},{"i":30,"n":"第三十条","txt":"职业卫生技术服务机构不得使用非本机构专业技术人员从事职业卫生技术服务活动。 职业卫生技术服务机构专业技术人员不得有下列行为： （一）在职业卫生技术报告或者有关原始记录上代替他人签字； （二）未参与相应职业卫生技术服务事项而在技术报告或者有关原始记录上签字； （三）其他违反法律、法规和标准规范的行为。"},{"i":31,"n":"第三十一条","txt":"职业卫生技术服务机构应当建立职业卫生技术服务档案，并长期妥善保管。职业卫生技术服务档案包括职业卫生技术服务过程控制记录、现场勘查记录、相关原始记录、影像资料、技术报告及相关证明材料。 职业卫生技术服务机构应当为专业技术人员提供必要的个体防护用品。 职业卫生技术服务机构应当自出具职业卫生技术报告之日起二十个工作日内,在本单位网站上公开技术报告相关信息（涉及国家秘密、商业秘密、技术秘密及个人隐私的信息和法律、法规规定可不予公开的除外），公开的时间不少于五年。公开的信息应包括以下内容： （一）用人单位名称、地址及联系人； （二）技术服务项目组人员名单； （三）现场调查、现场采样、现场检测的专业技术人员名单、时间，用人单位陪同人； （四）证明现场调查、现场采样、现场检测的图像影像。"},{"i":32,"n":"第三十二条","txt":"资质认可机关应当对其认可的职业卫生技术服务机构在资质认可有效期内至少进行一次评估检查，重点检查资质条件保持和符合情况。 评估检查可以通过能力验证、现场核查等方式开展。"},{"i":33,"n":"第三十三条","txt":"县级以上地方卫生健康、疾病预防控制主管部门应当依据各自职责按照有关“双随机、一公开”的规定，加强对本行政区域内从业的职业卫生技术服务机构事中事后监管。"},{"i":34,"n":"第三十四条","txt":"县级以上地方卫生健康、疾病预防控制主管部门对职业卫生技术服务机构的监督检查，主要包括下列内容： （一）是否以书面形式与用人单位明确技术服务内容、范围以及双方的责任； （二）是否按照标准规范要求开展现场调查、职业病危害因素识别、现场采样、现场检测、样品管理、实验室分析、数据处理及应用、危害程度评价、防护措施及其效果评价、技术报告编制等职业卫生技术服务活动； （三）技术服务内部审核、原始信息记录等是否规范； （四）职业卫生技术服务档案是否完整； （五）技术服务过程是否存在弄虚作假等违法违规情况； （六）是否按照规定向技术服务所在地卫生健康主管部门报送职业卫生技术服务相关信息； （七）是否按照规定在网上公开职业卫生技术报告相关信息； （八）依法应当监督检查的其他内容。 县级以上地方卫生健康、疾病预防控制主管部门在对用人单位职业病防治工作进行监督检查过程中，应当加强对有关职业卫生技术服务机构提"},{"i":35,"n":"第三十五条","txt":"县级以上卫生健康主管部门应当建立职业卫生技术服务机构信息管理系统，会同疾病预防控制主管部门建立职业卫生技术服务机构及其从业人员信用档案，记录违法失信行为并依法向社会公开，依据职业卫生技术服务机构信用状况，实行分类监管。"},{"i":36,"n":"第三十六条","txt":"职业卫生技术服务机构有下列情形之一的，资质认可机关应当注销其资质： （一）资质认可有效期届满未延续的； （二）依法终止的； （三）资质认可依法被撤销、撤回，或者资质证书依法被吊销的； （四）法律、法规规定的应当注销资质认可的其他情形。"},{"i":37,"n":"第三十七条","txt":"卫生健康、疾病预防控制主管部门及其工作人员不得有下列行为： （一）要求用人单位接受指定的职业卫生技术服务机构进行职业卫生技术服务； （二）变相设立法律、法规规定以外的行政许可； （三）限制本行政区域外职业卫生技术服务机构到本地区开展职业卫生技术服务； （四）干预职业卫生技术服务机构开展正常活动； （五）向职业卫生技术服务机构收取或者变相收取费用； （六）向职业卫生技术服务机构摊派财物、推销产品； （七）在职业卫生技术服务机构报销任何费用； （八）对不具备资质条件的申请人予以资质认可。"},{"i":38,"n":"第三十八条","txt":"任何单位或者个人发现职业卫生技术服务机构及其从业人员、卫生健康和疾病预防控制主管部门及其工作人员、技术评审专家违反有关职业病防治的法律、法规和本办法规定的行为，有权向县级以上卫生健康、疾病预防控制主管部门或者其他有关部门举报。 卫生健康、疾病预防控制主管部门应当为举报人保密，并依法进行核查和处理。"},{"i":39,"n":"第三十九条","txt":"县级以上卫生健康、疾病预防控制主管部门工作人员不履行本办法规定的职责，徇私舞弊、滥用职权、弄虚作假、玩忽职守，依法给予相应处分。 技术评审专家在职业卫生技术服务机构技术评审工作中徇私舞弊、弄虚作假、玩忽职守的，撤销其技术评审专家资格，终身不得再进入专家库。"},{"i":40,"n":"第四十条","txt":"申请人隐瞒有关情况或者提供虚假材料申请职业卫生技术服务机构资质认可的，资质认可机关不予受理或者不予认可，并给予警告；申请人自资质认可机关作出不予受理或者不予认可决定之日起一年内不得再次申请职业卫生技术服务机构资质。 职业卫生技术服务机构以欺骗、贿赂等不正当手段取得职业卫生技术服务机构资质认可的，资质认可机关应当撤销其资质认可，并给予警告；申请人自资质认可机关撤销其资质认可之日起三年内不得再次申请职业卫生技术服务机构资质。"},{"i":41,"n":"第四十一条","txt":"未取得职业卫生技术服务资质认可擅自从事职业卫生检测、评价技术服务的，由县级以上地方疾病预防控制主管部门责令立即停止违法行为，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上五万元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分。"},{"i":42,"n":"第四十二条","txt":"职业卫生技术服务机构有下列行为之一的，由县级以上地方疾病预防控制主管部门责令立即停止违法行为，给予警告，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上二万元以下的罚款；情节严重的，由原资质认可机关取消其资质认可；对直接负责的主管人员和其他责任人员，依法给予降级、撤职或者开除的处分；构成犯罪的，依法追究刑事责任： （一）超出资质认可范围从事职业卫生技术服务的； （二）未按照《职业病防治法》的规定履行法定职责的； （三）出具虚假证明文件的。"},{"i":43,"n":"第四十三条","txt":"职业卫生技术服务机构有下列行为之一的，由县级以上地方疾病预防控制主管部门责令改正，给予警告，并处一万元以上三万元以下罚款；构成犯罪的，依法追究刑事责任： （一）涂改、倒卖、出租、出借职业卫生技术服务机构资质证书，或者以其他形式非法转让职业卫生技术服务机构资质证书的； （二）未按规定向技术服务所在地卫生健康主管部门报送职业卫生技术服务相关信息的； （三）未按规定在网上公开职业卫生技术报告相关信息的； （四）其他违反本办法规定的行为。"},{"i":44,"n":"第四十四条","txt":"职业卫生技术服务机构有下列情形之一的，由县级以上地方疾病预防控制主管部门责令改正，给予警告，可以并处三万元以下罚款： （一）未按标准规范开展职业卫生技术服务，或者擅自更改、简化服务程序和相关内容的； （二）未按规定实施委托检测的； （三）转包职业卫生技术服务项目的；职业卫生技术服务机构管理办法 （四）未按规定以书面形式与用人单位明确技术服务内容、范围以及双方责任的； （五）使用非本机构专业技术人员从事职业卫生技术服务活动的； （六）安排未达到技术评审考核评估要求的专业技术人员参与职业卫生技术服务的。"},{"i":45,"n":"第四十五条","txt":"职业卫生技术服务机构专业技术人员有下列情形之一的，由县级以上地方疾病预防控制主管部门责令改正，给予警告，并处一万元以下罚款： （一）在职业卫生技术报告或者有关原始记录上代替他人签字的； （二）未参与相应职业卫生技术服务事项而在技术报告或者有关原始记录上签字的； （三）其他违反本办法规定的行为。"},{"i":46,"n":"第四十六条","txt":"已经取得资质认可的职业卫生技术服务机构，不再符合规定的资质条件的，由原资质认可机关责令其改正，通报批评；情节严重的，依法撤销其资质认可。"},{"i":47,"n":"第四十七条","txt":"本办法所规定的行政处罚，除规定由原资质认可机关实施的以外，由技术服务所在地的县级以上地方疾病预防控制主管部门决定。"},{"i":48,"n":"第四十八条","txt":"本办法下列用语的含义： 专业技术人员，是指在职业卫生技术服务机构或者拟申请职业卫生技术服务机构资质的单位中专职从事职业卫生技术服务工作的人员。"},{"i":49,"n":"第四十九条","txt":"个人剂量监测、放射防护器材和含放射性产品检测、医疗机构放射性危害评价等技术服务机构的管理另行规定。"},{"i":50,"n":"第五十条","txt":"本办法施行前已经取得职业卫生技术服务机构资质的，资质继续有效。资质有效期满后，需要继续从事职业卫生技术服务的，按照本办法的规定申请资质认可延续。"},{"i":51,"n":"第五十一条","txt":"本办法自2021年2月1日起施行。原国家安全生产监督管理总局2012年4月27日公布、2015年5月29日修改的《职业卫生技术服务机构监督管理暂行办法》同时废止。"}],"zhiyebingzhenduanyujiandingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范职业病诊断与鉴定工作，加强职业病诊断与鉴定管理，根据《中华人民共和国职业病防治法》（以下简称《职业病防治法》），制定本办法。"},{"i":2,"n":"第二条","txt":"职业病诊断与鉴定工作应当按照《职业病防治法》、本办法的有关规定及《职业病分类和目录》、国家职业病诊断标准进行，遵循科学、公正、及时、便捷的原则。"},{"i":3,"n":"第三条","txt":"国家卫生健康委负责全国范围内职业病诊断与鉴定的监督管理工作，县级以上地方卫生健康主管部门依据职责负责本行政区域内职业病诊断与鉴定的监督管理工作。 省、自治区、直辖市卫生健康主管部门（以下简称省级卫生健康主管部门）应当结合本行政区域职业病防治工作实际和医疗卫生服务体系规划，充分利用现有医疗卫生资源，实现职业病诊断机构区域覆盖。"},{"i":4,"n":"第四条","txt":"各地要加强职业病诊断机构能力建设，提供必要的保障条件，配备相关的人员、设备和工作经费，以满足职业病诊断工作的需要。"},{"i":5,"n":"第五条","txt":"各地要加强职业病诊断与鉴定信息化建设，建立健全劳动者接触职业病危害、开展职业健康检查、进行职业病诊断与鉴定等全过程的信息化系统，不断提高职业病诊断与鉴定信息报告的准确性、及时性和有效性。"},{"i":6,"n":"第六条","txt":"用人单位应当依法履行职业病诊断、鉴定的相关义务： （一）及时安排职业病病人、疑似职业病病人进行诊治； （二）如实提供职业病诊断、鉴定所需的资料； （三）承担职业病诊断、鉴定的费用和疑似职业病病人在诊断、医学观察期间的费用； （四）报告职业病和疑似职业病； （五）《职业病防治法》规定的其他相关义务。"},{"i":7,"n":"第七条","txt":"医疗卫生机构开展职业病诊断工作，应当在开展之日起十五个工作日内向省级卫生健康主管部门备案。 省级卫生健康主管部门应当自收到完整备案材料之日起十五个工作日内向社会公布备案的医疗卫生机构名单、地址、诊断项目（即《职业病分类和目录》中的职业病类别和病种）等相关信息。"},{"i":8,"n":"第八条","txt":"医疗卫生机构开展职业病诊断工作应当具备下列条件： （一）持有《医疗机构执业许可证》； （二）具有相应的诊疗科目及与备案开展的诊断项目相适应的职业病诊断医师及相关医疗卫生技术人员； （三）具有与备案开展的诊断项目相适应的场所和仪器、设备； （四）具有健全的职业病诊断质量管理制度。"},{"i":9,"n":"第九条","txt":"医疗卫生机构进行职业病诊断备案时，应当提交以下证明其符合本办法第八条规定条件的有关资料： （一）《医疗机构执业许可证》原件、副本及复印件； （二）职业病诊断医师资格等相关资料； （三）相关的仪器设备清单； （四）负责职业病信息报告人员名单； （五）职业病诊断质量管理制度等相关资料。"},{"i":10,"n":"第十条","txt":"职业病诊断机构对备案信息的真实性、准确性、合法性负责。 当备案信息发生变化时，应当自信息发生变化之日起十个工作日内向省级卫生健康主管部门提交变更信息。"},{"i":11,"n":"第十一条","txt":"设区的市没有医疗卫生机构备案开展职业病诊断的，省级卫生健康主管部门应当根据职业病诊断工作的需要，指定符合本办法第八条规定条件的医疗卫生机构承担职业病诊断工作。"},{"i":12,"n":"第十二条","txt":"职业病诊断机构的职责是： （一）在备案的诊断项目范围内开展职业病诊断； （二）及时向所在地卫生健康主管部门报告职业病； （三）按照卫生健康主管部门要求报告职业病诊断工作情况； （四）承担《职业病防治法》中规定的其他职责。"},{"i":13,"n":"第十三条","txt":"职业病诊断机构依法独立行使诊断权，并对其作出的职业病诊断结论负责。"},{"i":14,"n":"第十四条","txt":"职业病诊断机构应当建立和健全职业病诊断管理制度，加强职业病诊断医师等有关医疗卫生人员技术培训和政策、法律培训，并采取措施改善职业病诊断工作条件，提高职业病诊断服务质量和水平。"},{"i":15,"n":"第十五条","txt":"职业病诊断机构应当公开职业病诊断程序和诊断项目范围，方便劳动者进行职业病诊断。 职业病诊断机构及其相关工作人员应当尊重、关心、爱护劳动者，保护劳动者的隐私。"},{"i":16,"n":"第十六条","txt":"从事职业病诊断的医师应当具备下列条件，并取得省级卫生健康主管部门颁发的职业病诊断资格证书： （一）具有医师执业证书； （二）具有中级以上卫生专业技术职务任职资格； （三）熟悉职业病防治法律法规和职业病诊断标准； （四）从事职业病诊断、鉴定相关工作三年以上； （五）按规定参加职业病诊断医师相应专业的培训，并考核合格。 省级卫生健康主管部门应当依据本办法的规定和国家卫生健康委制定的职业病诊断医师培训大纲，制定本行政区域职业病诊断医师培训考核办法并组织实施。"},{"i":17,"n":"第十七条","txt":"职业病诊断医师应当依法在职业病诊断机构备案的诊断项目范围内从事职业病诊断工作，不得从事超出其职业病诊断资格范围的职业病诊断工作；职业病诊断医师应当按照有关规定参加职业卫生、放射卫生、职业医学等领域的继续医学教育。"},{"i":18,"n":"第十八条","txt":"省级卫生健康主管部门应当加强本行政区域内职业病诊断机构的质量控制管理工作，组织开展职业病诊断机构质量控制评估。 职业病诊断质量控制规范和医疗卫生机构职业病报告规范另行制定。"},{"i":19,"n":"第十九条","txt":"劳动者可以在用人单位所在地、本人户籍所在地或者经常居住地的职业病诊断机构进行职业病诊断。"},{"i":20,"n":"第二十条","txt":"职业病诊断应当按照《职业病防治法》、本办法的有关规定及《职业病分类和目录》、国家职业病诊断标准，依据劳动者的职业史、职业病危害接触史和工作场所职业病危害因素情况、临床表现以及辅助检查结果等，进行综合分析。材料齐全的情况下，职业病诊断机构应当在收齐材料之日起三十日内作出诊断结论。 没有证据否定职业病危害因素与病人临床表现之间的必然联系的，应当诊断为职业病。"},{"i":21,"n":"第二十一条","txt":"职业病诊断需要以下资料： （一）劳动者职业史和职业病危害接触史（包括在岗时间、工种、岗位、接触的职业病危害因素名称等）； （二）劳动者职业健康检查结果； （三）工作场所职业病危害因素检测结果； （四）职业性放射性疾病诊断还需要个人剂量监测档案等资料。"},{"i":22,"n":"第二十二条","txt":"劳动者依法要求进行职业病诊断的，职业病诊断机构不得拒绝劳动者进行职业病诊断的要求,并告知劳动者职业病诊断的程序和所需材料。劳动者应当填写《职业病诊断就诊登记表》，并提供本人掌握的职业病诊断有关资料。"},{"i":23,"n":"第二十三条","txt":"职业病诊断机构进行职业病诊断时，应当书面通知劳动者所在的用人单位提供本办法第二十一条规定的职业病诊断资料，用人单位应当在接到通知后的十日内如实提供。"},{"i":24,"n":"第二十四条","txt":"用人单位未在规定时间内提供职业病诊断所需要资料的，职业病诊断机构可以依法提请卫生健康主管部门督促用人单位提供。"},{"i":25,"n":"第二十五条","txt":"劳动者对用人单位提供的工作场所职业病危害因素检测结果等资料有异议，或者因劳动者的用人单位解散、破产，无用人单位提供上述资料的，职业病诊断机构应当依法提请用人单位所在地卫生健康主管部门进行调查。 卫生健康主管部门应当自接到申请之日起三十日内对存在异议的资料或者工作场所职业病危害因素情况作出判定。 职业病诊断机构在卫生健康主管部门作出调查结论或者判定前应当中止职业病诊断。"},{"i":26,"n":"第二十六条","txt":"职业病诊断机构需要了解工作场所职业病危害因素情况时，可以对工作场所进行现场调查，也可以依法提请卫生健康主管部门组织现场调查。卫生健康主管部门应当在接到申请之日起三十日内完成现场调查。"},{"i":27,"n":"第二十七条","txt":"在确认劳动者职业史、职业病危害接触史时，当事人对劳动关系、工种、工作岗位或者在岗时间有争议的，职业病诊断机构应当告知当事人依法向用人单位所在地的劳动人事争议仲裁委员会申请仲裁。"},{"i":28,"n":"第二十八条","txt":"经卫生健康主管部门督促，用人单位仍不提供工作场所职业病危害因素检测结果、职业健康监护档案等资料或者提供资料不全的，职业病诊断机构应当结合劳动者的临床表现、辅助检查结果和劳动者的职业史、职业病危害接触史，并参考劳动者自述或工友旁证资料、卫生健康等有关部门提供的日常监督检查信息等，作出职业病诊断结论。对于作出无职业病诊断结论的病人，可依据病人的临床表现以及辅助检查结果，作出疾病的诊断，提出相关医学意见或者建议。"},{"i":29,"n":"第二十九条","txt":"职业病诊断机构可以根据诊断需要，聘请其他单位职业病诊断医师参加诊断。必要时，可以邀请相关专业专家提供咨询意见。"},{"i":30,"n":"第三十条","txt":"职业病诊断机构作出职业病诊断结论后，应当出具职业病诊断证明书。职业病诊断证明书应当由参与诊断的取得职业病诊断资格的执业医师签署。 职业病诊断机构应当对职业病诊断医师签署的职业病诊断证明书进行审核，确认诊断的依据与结论符合有关法律法规、标准的要求，并在职业病诊断证明书上盖章。 职业病诊断证明书的书写应当符合相关标准的要求。 职业病诊断证明书一式五份，劳动者一份，用人单位所在地县级卫生健康主管部门一份，用人单位两份，诊断机构存档一份。 职业病诊断证明书应当于出具之日起十五日内由职业病诊断机构送达劳动者、用人单位及用人单位所在地县级卫生健康主管部门。"},{"i":31,"n":"第三十一条","txt":"职业病诊断机构应当建立职业病诊断档案并永久保存，档案应当包括： （一）职业病诊断证明书； （二）职业病诊断记录； （三）用人单位、劳动者和相关部门、机构提交的有关资料； （四）临床检查与实验室检验等资料。 职业病诊断机构拟不再开展职业病诊断工作的，应当在拟停止开展职业病诊断工作的十五个工作日之前告知省级卫生健康主管部门和所在地县级卫生健康主管部门，妥善处理职业病诊断档案。"},{"i":32,"n":"第三十二条","txt":"职业病诊断机构发现职业病病人或者疑似职业病病人时，应当及时向所在地县级卫生健康主管部门报告。职业病诊断机构应当在作出职业病诊断之日起十五日内通过职业病及健康危害因素监测信息系统进行信息报告，并确保报告信息的完整、真实和准确。 确诊为职业病的，职业病诊断机构可以根据需要，向卫生健康主管部门、用人单位提出专业建议；告知职业病病人依法享有的职业健康权益。"},{"i":33,"n":"第三十三条","txt":"未承担职业病诊断工作的医疗卫生机构，在诊疗活动中发现劳动者的健康损害可能与其所从事的职业有关时，应及时告知劳动者到职业病诊断机构进行职业病诊断。"},{"i":34,"n":"第三十四条","txt":"当事人对职业病诊断机构作出的职业病诊断有异议的，可以在接到职业病诊断证明书之日起三十日内，向作出诊断的职业病诊断机构所在地设区的市级卫生健康主管部门申请鉴定。 职业病诊断争议由设区的市级以上地方卫生健康主管部门根据当事人的申请组织职业病诊断鉴定委员会进行鉴定。"},{"i":35,"n":"第三十五条","txt":"职业病鉴定实行两级鉴定制，设区的市级职业病诊断鉴定委员会负责职业病诊断争议的首次鉴定。 当事人对设区的市级职业病鉴定结论不服的，可以在接到诊断鉴定书之日起十五日内，向原鉴定组织所在地省级卫生健康主管部门申请再鉴定，省级鉴定为最终鉴定。"},{"i":36,"n":"第三十六条","txt":"设区的市级以上地方卫生健康主管部门可以指定办事机构，具体承担职业病诊断鉴定的组织和日常性工作。职业病鉴定办事机构的职责是： （一）接受当事人申请； （二）组织当事人或者接受当事人委托抽取职业病诊断鉴定专家； （三）组织职业病诊断鉴定会议，负责会议记录、职业病诊断鉴定相关文书的收发及其他事务性工作； （四）建立并管理职业病诊断鉴定档案； （五）报告职业病诊断鉴定相关信息； （六）承担卫生健康主管部门委托的有关职业病诊断鉴定的工作。 职业病诊断机构不能作为职业病鉴定办事机构。"},{"i":37,"n":"第三十七条","txt":"设区的市级以上地方卫生健康主管部门应当向社会公布本行政区域内依法承担职业病诊断鉴定工作的办事机构的名称、工作时间、地点、联系人、联系电话和鉴定工作程序。"},{"i":38,"n":"第三十八条","txt":"省级卫生健康主管部门应当设立职业病诊断鉴定专家库（以下简称专家库），并根据实际工作需要及时调整其成员。专家库可以按照专业类别进行分组。"},{"i":39,"n":"第三十九条","txt":"专家库应当以取得职业病诊断资格的不同专业类别的医师为主要成员，吸收临床相关学科、职业卫生、放射卫生、法律等相关专业的专家组成。专家应当具备下列条件： （一）具有良好的业务素质和职业道德； （二）具有相关专业的高级专业技术职务任职资格； （三）熟悉职业病防治法律法规和职业病诊断标准； （四）身体健康，能够胜任职业病诊断鉴定工作。"},{"i":40,"n":"第四十条","txt":"参加职业病诊断鉴定的专家，应当由当事人或者由其委托的职业病鉴定办事机构从专家库中按照专业类别以随机抽取的方式确定。抽取的专家组成职业病诊断鉴定委员会（以下简称鉴定委员会）。 经当事人同意，职业病鉴定办事机构可以根据鉴定需要聘请本省、自治区、直辖市以外的相关专业专家作为鉴定委员会成员，并有表决权。"},{"i":41,"n":"第四十一条","txt":"鉴定委员会人数为五人以上单数，其中相关专业职业病诊断医师应当为本次鉴定专家人数的半数以上。疑难病例应当增加鉴定委员会人数，充分听取意见。鉴定委员会设主任委员一名，由鉴定委员会成员推举产生。 职业病诊断鉴定会议由鉴定委员会主任委员主持。"},{"i":42,"n":"第四十二条","txt":"参加职业病诊断鉴定的专家有下列情形之一的，应当回避： （一）是职业病诊断鉴定当事人或者当事人近亲属的； （二）已参加当事人职业病诊断或者首次鉴定的； （三）与职业病诊断鉴定当事人有利害关系的； （四）与职业病诊断鉴定当事人有其他关系，可能影响鉴定公正的。"},{"i":43,"n":"第四十三条","txt":"当事人申请职业病诊断鉴定时，应当提供以下资料： （一）职业病诊断鉴定申请书； （二）职业病诊断证明书； （三）申请省级鉴定的还应当提交市级职业病诊断鉴定书。"},{"i":44,"n":"第四十四条","txt":"职业病鉴定办事机构应当自收到申请资料之日起五个工作日内完成资料审核，对资料齐全的发给受理通知书；资料不全的，应当当场或者在五个工作日内一次性告知当事人补充。资料补充齐全的，应当受理申请并组织鉴定。 职业病鉴定办事机构收到当事人鉴定申请之后，根据需要可以向原职业病诊断机构或者组织首次鉴定的办事机构调阅有关的诊断、鉴定资料。原职业病诊断机构或者组织首次鉴定的办事机构应当在接到通知之日起十日内提交。 职业病鉴定办事机构应当在受理鉴定申请之日起四十日内组织鉴定、形成鉴定结论，并出具职业病诊断鉴定书。"},{"i":45,"n":"第四十五条","txt":"根据职业病诊断鉴定工作需要，职业病鉴定办事机构可以向有关单位调取与职业病诊断、鉴定有关的资料，有关单位应当如实、及时提供。 鉴定委员会应当听取当事人的陈述和申辩，必要时可以组织进行医学检查，医学检查应当在三十日内完成。 需要了解被鉴定人的工作场所职业病危害因素情况时，职业病鉴定办事机构根据鉴定委员会的意见可以组织对工作场所进行现场调查，或者依法提请卫生健康主管部门组织现场调查。现场调查应当在三十日内完成。 医学检查和现场调查时间不计算在职业病鉴定规定的期限内。 职业病诊断鉴定应当遵循客观、公正的原则，鉴定委员会进行职业病诊断鉴定时，可以邀请有关单位人员旁听职业病诊断鉴定会议。所有参与职业病诊断鉴定的人员应当依法保护当事人的个人隐私、商业秘密。"},{"i":46,"n":"第四十六条","txt":"鉴定委员会应当认真审阅鉴定资料，依照有关规定和职业病诊断标准，经充分合议后，根据专业知识独立进行鉴定。在事实清楚的基础上，进行综合分析，作出鉴定结论，并制作职业病诊断鉴定书。 鉴定结论应当经鉴定委员会半数以上成员通过。"},{"i":47,"n":"第四十七条","txt":"职业病诊断鉴定书应当包括以下内容： （一）劳动者、用人单位的基本信息及鉴定事由； （二）鉴定结论及其依据，鉴定为职业病的，应当注明职业病名称、程度（期别）； （三）鉴定时间。 诊断鉴定书加盖职业病鉴定委员会印章。 首次鉴定的职业病诊断鉴定书一式五份，劳动者、用人单位、用人单位所在地市级卫生健康主管部门、原诊断机构各一份，职业病鉴定办事机构存档一份；省级鉴定的职业病诊断鉴定书一式六份，劳动者、用人单位、用人单位所在地省级卫生健康主管部门、原诊断机构、首次职业病鉴定办事机构各一份，省级职业病鉴定办事机构存档一份。 职业病诊断鉴定书的格式由国家卫生健康委员会统一规定。"},{"i":48,"n":"第四十八条","txt":"职业病鉴定办事机构出具职业病诊断鉴定书后，应当于出具之日起十日内送达当事人，并在出具职业病诊断鉴定书后的十日内将职业病诊断鉴定书等有关信息告知原职业病诊断机构或者首次职业病鉴定办事机构，并通过职业病及健康危害因素监测信息系统报告职业病鉴定相关信息。"},{"i":49,"n":"第四十九条","txt":"职业病鉴定结论与职业病诊断结论或者首次职业病鉴定结论不一致的，职业病鉴定办事机构应当在出具职业病诊断鉴定书后十日内向相关卫生健康主管部门报告。"},{"i":50,"n":"第五十条","txt":"职业病鉴定办事机构应当如实记录职业病诊断鉴定过程，内容应当包括： （一）鉴定委员会的专家组成； （二）鉴定时间； （三）鉴定所用资料； （四）鉴定专家的发言及其鉴定意见； （五）表决情况； （六）经鉴定专家签字的鉴定结论。 有当事人陈述和申辩的，应当如实记录。 鉴定结束后，鉴定记录应当随同职业病诊断鉴定书一并由职业病鉴定办事机构存档，永久保存。"},{"i":51,"n":"第五十一条","txt":"县级以上地方卫生健康主管部门应当定期对职业病诊断机构进行监督检查，检查内容包括： （一）法律法规、标准的执行情况； （二）规章制度建立情况； （三）备案的职业病诊断信息真实性情况； （四）按照备案的诊断项目开展职业病诊断工作情况； （五）开展职业病诊断质量控制、参加质量控制评估及整改情况； （六）人员、岗位职责落实和培训情况； （七）职业病报告情况。"},{"i":52,"n":"第五十二条","txt":"设区的市级以上地方卫生健康主管部门应当加强对职业病鉴定办事机构的监督管理，对职业病鉴定工作程序、制度落实情况及职业病报告等相关工作情况进行监督检查。"},{"i":53,"n":"第五十三条","txt":"县级以上地方卫生健康主管部门监督检查时，有权查阅或者复制有关资料，职业病诊断机构应当予以配合。"},{"i":54,"n":"第五十四条","txt":"医疗卫生机构未按照规定备案开展职业病诊断的，由县级以上地方卫生健康主管部门责令改正，给予警告，可以并处三万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"职业病诊断机构有下列行为之一的，其作出的职业病诊断无效，由县级以上地方卫生健康主管部门按照《职业病防治法》的第八十条的规定进行处理： （一）超出诊疗项目登记范围从事职业病诊断的； （二）不按照《职业病防治法》规定履行法定职责的； （三）出具虚假证明文件的。"},{"i":56,"n":"第五十六条","txt":"职业病诊断机构未按照规定报告职业病、疑似职业病的，由县级以上地方卫生健康主管部门按照《职业病防治法》第七十四条的规定进行处理。"},{"i":57,"n":"第五十七条","txt":"职业病诊断机构违反本办法规定，有下列情形之一的，由县级以上地方卫生健康主管部门责令限期改正；逾期不改的，给予警告，并可以根据情节轻重处以三万元以下罚款： （一）未建立职业病诊断管理制度的； （二）未按照规定向劳动者公开职业病诊断程序的； （三）泄露劳动者涉及个人隐私的有关信息、资料的； （四）未按照规定参加质量控制评估，或者质量控制评估不合格且未按要求整改的； （五）拒不配合卫生健康主管部门监督检查的。"},{"i":58,"n":"第五十八条","txt":"职业病诊断鉴定委员会组成人员收受职业病诊断争议当事人的财物或者其他好处的，由省级卫生健康主管部门按照《职业病防治法》第八十一条的规定进行处理。"},{"i":59,"n":"第五十九条","txt":"县级以上地方卫生健康主管部门及其工作人员未依法履行职责，按照《职业病防治法》第八十三条第二款规定进行处理。"},{"i":60,"n":"第六十条","txt":"用人单位有下列行为之一的，由县级以上地方卫生健康主管部门按照《职业病防治法》第七十二条规定进行处理： （一）未按照规定安排职业病病人、疑似职业病病人进行诊治的； （二）拒不提供职业病诊断、鉴定所需资料的； （三）未按照规定承担职业病诊断、鉴定费用。"},{"i":61,"n":"第六十一条","txt":"用人单位未按照规定报告职业病、疑似职业病的，由县级以上地方卫生健康主管部门按照《职业病防治法》第七十四条规定进行处理。"},{"i":62,"n":"第六十二条","txt":"本办法所称“证据”，包括疾病的证据、接触职业病危害因素的证据，以及用于判定疾病与接触职业病危害因素之间因果关系的证据。"},{"i":63,"n":"第六十三条","txt":"本办法自公布之日起施行。原卫生部2013年2月19日公布的《职业病诊断与鉴定管理办法》同时废止。"}],"yaopinbuliangfanyingbaogaohejianceguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强药品的上市后监管，规范药品不良反应报告和监测，及时、有效控制药品风险，保障公众用药安全，依据《中华人民共和国药品管理法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内开展药品不良反应报告、监测以及监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"国家实行药品不良反应报告制度。药品生产企业（包括进口药品的境外制药厂商）、药品经营企业、医疗机构应当按照规定报告所发现的药品不良反应。"},{"i":4,"n":"第四条","txt":"国家食品药品监督管理局主管全国药品不良反应报告和监测工作，地方各级药品监督管理部门主管本行政区域内的药品不良反应报告和监测工作。各级卫生行政部门负责本行政区域内医疗机构与实施药品不良反应报告制度有关的管理工作。 地方各级药品监督管理部门应当建立健全药品不良反应监测机构，负责本行政区域内药品不良反应报告和监测的技术工作。"},{"i":5,"n":"第五条","txt":"国家鼓励公民、法人和其他组织报告药品不良反应。"},{"i":6,"n":"第六条","txt":"国家食品药品监督管理局负责全国药品不良反应报告和监测的管理工作，并履行以下主要职责： （一）与卫生部共同制定药品不良反应报告和监测的管理规定和政策，并监督实施； （二）与卫生部联合组织开展全国范围内影响较大并造成严重后果的药品群体不良事件的调查和处理，并发布相关信息； （三）对已确认发生严重药品不良反应或者药品群体不良事件的药品依法采取紧急控制措施，作出行政处理决定，并向社会公布； （四）通报全国药品不良反应报告和监测情况； （五）组织检查药品生产、经营企业的药品不良反应报告和监测工作的开展情况，并与卫生部联合组织检查医疗机构的药品不良反应报告和监测工作的开展情况。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市药品监督管理部门负责本行政区域内药品不良反应报告和监测的管理工作，并履行以下主要职责： （一）根据本办法与同级卫生行政部门共同制定本行政区域内药品不良反应报告和监测的管理规定，并监督实施； （二）与同级卫生行政部门联合组织开展本行政区域内发生的影响较大的药品群体不良事件的调查和处理，并发布相关信息； （三）对已确认发生严重药品不良反应或者药品群体不良事件的药品依法采取紧急控制措施，作出行政处理决定，并向社会公布； （四）通报本行政区域内药品不良反应报告和监测情况； （五）组织检查本行政区域内药品生产、经营企业的药品不良反应报告和监测工作的开展情况，并与同级卫生行政部门联合组织检查本行政区域内医疗机构的药品不良反应报告和监测工作的开展情况； （六）组织开展本行政区域内药品不良反应报告和监测的宣传、培训工作。"},{"i":8,"n":"第八条","txt":"设区的市级、县级药品监督管理部门负责本行政区域内药品不良反应报告和监测的管理工作；与同级卫生行政部门联合组织开展本行政区域内发生的药品群体不良事件的调查，并采取必要控制措施；组织开展本行政区域内药品不良反应报告和监测的宣传、培训工作。"},{"i":9,"n":"第九条","txt":"县级以上卫生行政部门应当加强对医疗机构临床用药的监督管理，在职责范围内依法对已确认的严重药品不良反应或者药品群体不良事件采取相关的紧急控制措施。"},{"i":10,"n":"第十条","txt":"国家药品不良反应监测中心负责全国药品不良反应报告和监测的技术工作，并履行以下主要职责： （一）承担国家药品不良反应报告和监测资料的收集、评价、反馈和上报，以及全国药品不良反应监测信息网络的建设和维护； （二）制定药品不良反应报告和监测的技术标准和规范，对地方各级药品不良反应监测机构进行技术指导； （三）组织开展严重药品不良反应的调查和评价，协助有关部门开展药品群体不良事件的调查； （四）发布药品不良反应警示信息； （五）承担药品不良反应报告和监测的宣传、培训、研究和国际交流工作。"},{"i":11,"n":"第十一条","txt":"省级药品不良反应监测机构负责本行政区域内的药品不良反应报告和监测的技术工作，并履行以下主要职责： （一）承担本行政区域内药品不良反应报告和监测资料的收集、评价、反馈和上报，以及药品不良反应监测信息网络的维护和管理； （二）对设区的市级、县级药品不良反应监测机构进行技术指导； （三）组织开展本行政区域内严重药品不良反应的调查和评价，协助有关部门开展药品群体不良事件的调查； （四）组织开展本行政区域内药品不良反应报告和监测的宣传、培训工作。"},{"i":12,"n":"第十二条","txt":"设区的市级、县级药品不良反应监测机构负责本行政区域内药品不良反应报告和监测资料的收集、核实、评价、反馈和上报；开展本行政区域内严重药品不良反应的调查和评价；协助有关部门开展药品群体不良事件的调查；承担药品不良反应报告和监测的宣传、培训等工作。"},{"i":13,"n":"第十三条","txt":"药品生产、经营企业和医疗机构应当建立药品不良反应报告和监测管理制度。药品生产企业应当设立专门机构并配备专职人员，药品经营企业和医疗机构应当设立或者指定机构并配备专（兼）职人员，承担本单位的药品不良反应报告和监测工作。"},{"i":14,"n":"第十四条","txt":"从事药品不良反应报告和监测的工作人员应当具有医学、药学、流行病学或者统计学等相关专业知识，具备科学分析评价药品不良反应的能力。"},{"i":15,"n":"第十五条","txt":"药品生产、经营企业和医疗机构获知或者发现可能与用药有关的不良反应，应当通过国家药品不良反应监测信息网络报告；不具备在线报告条件的，应当通过纸质报表报所在地药品不良反应监测机构，由所在地药品不良反应监测机构代为在线报告。 报告内容应当真实、完整、准确。"},{"i":16,"n":"第十六条","txt":"各级药品不良反应监测机构应当对本行政区域内的药品不良反应报告和监测资料进行评价和管理。"},{"i":17,"n":"第十七条","txt":"药品生产、经营企业和医疗机构应当配合药品监督管理部门、卫生行政部门和药品不良反应监测机构对药品不良反应或者群体不良事件的调查，并提供调查所需的资料。"},{"i":18,"n":"第十八条","txt":"药品生产、经营企业和医疗机构应当建立并保存药品不良反应报告和监测档案。"},{"i":19,"n":"第十九条","txt":"药品生产、经营企业和医疗机构应当主动收集药品不良反应，获知或者发现药品不良反应后应当详细记录、分析和处理，填写《药品不良反应/事件报告表》（见附表1）并报告。"},{"i":20,"n":"第二十条","txt":"新药监测期内的国产药品应当报告该药品的所有不良反应；其他国产药品，报告新的和严重的不良反应。 进口药品自首次获准进口之日起5年内，报告该进口药品的所有不良反应；满5年的，报告新的和严重的不良反应。"},{"i":21,"n":"第二十一条","txt":"药品生产、经营企业和医疗机构发现或者获知新的、严重的药品不良反应应当在15日内报告，其中死亡病例须立即报告；其他药品不良反应应当在30日内报告。有随访信息的，应当及时报告。"},{"i":22,"n":"第二十二条","txt":"药品生产企业应当对获知的死亡病例进行调查，详细了解死亡病例的基本信息、药品使用情况、不良反应发生及诊治情况等，并在15日内完成调查报告，报药品生产企业所在地的省级药品不良反应监测机构。"},{"i":23,"n":"第二十三条","txt":"个人发现新的或者严重的药品不良反应，可以向经治医师报告，也可以向药品生产、经营企业或者当地的药品不良反应监测机构报告，必要时提供相关的病历资料。"},{"i":24,"n":"第二十四条","txt":"设区的市级、县级药品不良反应监测机构应当对收到的药品不良反应报告的真实性、完整性和准确性进行审核。严重药品不良反应报告的审核和评价应当自收到报告之日起3个工作日内完成，其他报告的审核和评价应当在15个工作日内完成。 设区的市级、县级药品不良反应监测机构应当对死亡病例进行调查，详细了解死亡病例的基本信息、药品使用情况、不良反应发生及诊治情况等，自收到报告之日起15个工作日内完成调查报告，报同级药品监督管理部门和卫生行政部门，以及上一级药品不良反应监测机构。"},{"i":25,"n":"第二十五条","txt":"省级药品不良反应监测机构应当在收到下一级药品不良反应监测机构提交的严重药品不良反应评价意见之日起7个工作日内完成评价工作。 对死亡病例，事件发生地和药品生产企业所在地的省级药品不良反应监测机构均应当及时根据调查报告进行分析、评价，必要时进行现场调查，并将评价结果报省级药品监督管理部门和卫生行政部门，以及国家药品不良反应监测中心。"},{"i":26,"n":"第二十六条","txt":"国家药品不良反应监测中心应当及时对死亡病例进行分析、评价，并将评价结果报国家食品药品监督管理局和卫生部。"},{"i":27,"n":"第二十七条","txt":"药品生产、经营企业和医疗机构获知或者发现药品群体不良事件后，应当立即通过电话或者传真等方式报所在地的县级药品监督管理部门、卫生行政部门和药品不良反应监测机构，必要时可以越级报告；同时填写《药品群体不良事件基本信息表》（见附表2），对每一病例还应当及时填写《药品不良反应/事件报告表》，通过国家药品不良反应监测信息网络报告。"},{"i":28,"n":"第二十八条","txt":"设区的市级、县级药品监督管理部门获知药品群体不良事件后，应当立即与同级卫生行政部门联合组织开展现场调查，并及时将调查结果逐级报至省级药品监督管理部门和卫生行政部门。 省级药品监督管理部门与同级卫生行政部门联合对设区的市级、县级的调查进行督促、指导，对药品群体不良事件进行分析、评价，对本行政区域内发生的影响较大的药品群体不良事件，还应当组织现场调查，评价和调查结果应当及时报国家食品药品监督管理局和卫生部。 对全国范围内影响较大并造成严重后果的药品群体不良事件，国家食品药品监督管理局应当与卫生部联合开展相关调查工作。"},{"i":29,"n":"第二十九条","txt":"药品生产企业获知药品群体不良事件后应当立即开展调查，详细了解药品群体不良事件的发生、药品使用、患者诊治以及药品生产、储存、流通、既往类似不良事件等情况，在7日内完成调查报告，报所在地省级药品监督管理部门和药品不良反应监测机构；同时迅速开展自查，分析事件发生的原因，必要时应当暂停生产、销售、使用和召回相关药品，并报所在地省级药品监督管理部门。"},{"i":30,"n":"第三十条","txt":"药品经营企业发现药品群体不良事件应当立即告知药品生产企业，同时迅速开展自查，必要时应当暂停药品的销售，并协助药品生产企业采取相关控制措施。"},{"i":31,"n":"第三十一条","txt":"医疗机构发现药品群体不良事件后应当积极救治患者，迅速开展临床调查，分析事件发生的原因，必要时可采取暂停药品的使用等紧急措施。"},{"i":32,"n":"第三十二条","txt":"药品监督管理部门可以采取暂停生产、销售、使用或者召回药品等控制措施。卫生行政部门应当采取措施积极组织救治患者。"},{"i":33,"n":"第三十三条","txt":"进口药品和国产药品在境外发生的严重药品不良反应（包括自发报告系统收集的、上市后临床研究发现的、文献报道的），药品生产企业应当填写《境外发生的药品不良反应/事件报告表》（见附表3），自获知之日起30日内报送国家药品不良反应监测中心。国家药品不良反应监测中心要求提供原始报表及相关信息的，药品生产企业应当在5日内提交。"},{"i":34,"n":"第三十四条","txt":"国家药品不良反应监测中心应当对收到的药品不良反应报告进行分析、评价，每半年向国家食品药品监督管理局和卫生部报告，发现提示药品可能存在安全隐患的信息应当及时报告。"},{"i":35,"n":"第三十五条","txt":"进口药品和国产药品在境外因药品不良反应被暂停销售、使用或者撤市的，药品生产企业应当在获知后24小时内书面报国家食品药品监督管理局和国家药品不良反应监测中心。"},{"i":36,"n":"第三十六条","txt":"药品生产企业应当对本企业生产药品的不良反应报告和监测资料进行定期汇总分析，汇总国内外安全性信息，进行风险和效益评估，撰写定期安全性更新报告。定期安全性更新报告的撰写规范由国家药品不良反应监测中心负责制定。"},{"i":37,"n":"第三十七条","txt":"设立新药监测期的国产药品，应当自取得批准证明文件之日起每满1年提交一次定期安全性更新报告，直至首次再注册，之后每5年报告一次；其他国产药品，每5年报告一次。 首次进口的药品，自取得进口药品批准证明文件之日起每满一年提交一次定期安全性更新报告，直至首次再注册，之后每5年报告一次。 定期安全性更新报告的汇总时间以取得药品批准证明文件的日期为起点计，上报日期应当在汇总数据截止日期后60日内。"},{"i":38,"n":"第三十八条","txt":"国产药品的定期安全性更新报告向药品生产企业所在地省级药品不良反应监测机构提交。进口药品（包括进口分包装药品）的定期安全性更新报告向国家药品不良反应监测中心提交。"},{"i":39,"n":"第三十九条","txt":"省级药品不良反应监测机构应当对收到的定期安全性更新报告进行汇总、分析和评价，于每年4月1日前将上一年度定期安全性更新报告统计情况和分析评价结果报省级药品监督管理部门和国家药品不良反应监测中心。"},{"i":40,"n":"第四十条","txt":"国家药品不良反应监测中心应当对收到的定期安全性更新报告进行汇总、分析和评价，于每年7月1日前将上一年度国产药品和进口药品的定期安全性更新报告统计情况和分析评价结果报国家食品药品监督管理局和卫生部。"},{"i":41,"n":"第四十一条","txt":"药品生产企业应当经常考察本企业生产药品的安全性，对新药监测期内的药品和首次进口5年内的药品，应当开展重点监测，并按要求对监测数据进行汇总、分析、评价和报告；对本企业生产的其他药品，应当根据安全性情况主动开展重点监测。"},{"i":42,"n":"第四十二条","txt":"省级以上药品监督管理部门根据药品临床使用和不良反应监测情况，可以要求药品生产企业对特定药品进行重点监测；必要时，也可以直接组织药品不良反应监测机构、医疗机构和科研单位开展药品重点监测。"},{"i":43,"n":"第四十三条","txt":"省级以上药品不良反应监测机构负责对药品生产企业开展的重点监测进行监督、检查，并对监测报告进行技术评价。"},{"i":44,"n":"第四十四条","txt":"省级以上药品监督管理部门可以联合同级卫生行政部门指定医疗机构作为监测点，承担药品重点监测工作。"},{"i":45,"n":"第四十五条","txt":"药品生产企业应当对收集到的药品不良反应报告和监测资料进行分析、评价，并主动开展药品安全性研究。 药品生产企业对已确认发生严重不良反应的药品，应当通过各种有效途径将药品不良反应、合理用药信息及时告知医务人员、患者和公众；采取修改标签和说明书，暂停生产、销售、使用和召回等措施，减少和防止药品不良反应的重复发生。对不良反应大的药品，应当主动申请注销其批准证明文件。 药品生产企业应当将药品安全性信息及采取的措施报所在地省级药品监督管理部门和国家食品药品监督管理局。"},{"i":46,"n":"第四十六条","txt":"药品经营企业和医疗机构应当对收集到的药品不良反应报告和监测资料进行分析和评价，并采取有效措施减少和防止药品不良反应的重复发生。"},{"i":47,"n":"第四十七条","txt":"省级药品不良反应监测机构应当每季度对收到的药品不良反应报告进行综合分析，提取需要关注的安全性信息，并进行评价，提出风险管理建议，及时报省级药品监督管理部门、卫生行政部门和国家药品不良反应监测中心。 省级药品监督管理部门根据分析评价结果，可以采取暂停生产、销售、使用和召回药品等措施，并监督检查，同时将采取的措施通报同级卫生行政部门。"},{"i":48,"n":"第四十八条","txt":"国家药品不良反应监测中心应当每季度对收到的严重药品不良反应报告进行综合分析，提取需要关注的安全性信息，并进行评价，提出风险管理建议，及时报国家食品药品监督管理局和卫生部。"},{"i":49,"n":"第四十九条","txt":"国家食品药品监督管理局根据药品分析评价结果，可以要求企业开展药品安全性、有效性相关研究。必要时，应当采取责令修改药品说明书，暂停生产、销售、使用和召回药品等措施，对不良反应大的药品，应当撤销药品批准证明文件，并将有关措施及时通报卫生部。"},{"i":50,"n":"第五十条","txt":"省级以上药品不良反应监测机构根据分析评价工作需要，可以要求药品生产、经营企业和医疗机构提供相关资料，相关单位应当积极配合。"},{"i":51,"n":"第五十一条","txt":"各级药品不良反应监测机构应当对收到的药品不良反应报告和监测资料进行统计和分析，并以适当形式反馈。"},{"i":52,"n":"第五十二条","txt":"国家药品不良反应监测中心应当根据对药品不良反应报告和监测资料的综合分析和评价结果，及时发布药品不良反应警示信息。"},{"i":53,"n":"第五十三条","txt":"省级以上药品监督管理部门应当定期发布药品不良反应报告和监测情况。"},{"i":54,"n":"第五十四条","txt":"下列信息由国家食品药品监督管理局和卫生部统一发布： （一）影响较大并造成严重后果的药品群体不良事件； （二）其他重要的药品不良反应信息和认为需要统一发布的信息。 前款规定统一发布的信息，国家食品药品监督管理局和卫生部也可以授权省级药品监督管理部门和卫生行政部门发布。"},{"i":55,"n":"第五十五条","txt":"在药品不良反应报告和监测过程中获取的商业秘密、个人隐私、患者和报告者信息应当予以保密。"},{"i":56,"n":"第五十六条","txt":"鼓励医疗机构、药品生产企业、药品经营企业之间共享药品不良反应信息。"},{"i":57,"n":"第五十七条","txt":"药品不良反应报告的内容和统计资料是加强药品监督管理、指导合理用药的依据。"},{"i":58,"n":"第五十八条","txt":"药品生产企业有下列情形之一的，由所在地药品监督管理部门给予警告，责令限期改正，可以并处五千元以上三万元以下的罚款： （一）未按照规定建立药品不良反应报告和监测管理制度，或者无专门机构、专职人员负责本单位药品不良反应报告和监测工作的； （二）未建立和保存药品不良反应监测档案的； （三）未按照要求开展药品不良反应或者群体不良事件报告、调查、评价和处理的； （四）未按照要求提交定期安全性更新报告的； （五）未按照要求开展重点监测的； （六）不配合严重药品不良反应或者群体不良事件相关调查工作的； （七）其他违反本办法规定的。 药品生产企业有前款规定第（四）项、第（五）项情形之一的，按照《药品注册管理办法》的规定对相应药品不予再注册。"},{"i":59,"n":"第五十九条","txt":"药品经营企业有下列情形之一的，由所在地药品监督管理部门给予警告，责令限期改正；逾期不改的，处三万元以下的罚款： （一）无专职或者兼职人员负责本单位药品不良反应监测工作的； （二）未按照要求开展药品不良反应或者群体不良事件报告、调查、评价和处理的； （三）不配合严重药品不良反应或者群体不良事件相关调查工作的。"},{"i":60,"n":"第六十条","txt":"医疗机构有下列情形之一的，由所在地卫生行政部门给予警告，责令限期改正；逾期不改的，处三万元以下的罚款。情节严重并造成严重后果的，由所在地卫生行政部门对相关责任人给予行政处分： （一）无专职或者兼职人员负责本单位药品不良反应监测工作的； （二）未按照要求开展药品不良反应或者群体不良事件报告、调查、评价和处理的； （三）不配合严重药品不良反应和群体不良事件相关调查工作的。 药品监督管理部门发现医疗机构有前款规定行为之一的，应当移交同级卫生行政部门处理。 卫生行政部门对医疗机构作出行政处罚决定的，应当及时通报同级药品监督管理部门。"},{"i":61,"n":"第六十一条","txt":"各级药品监督管理部门、卫生行政部门和药品不良反应监测机构及其有关工作人员在药品不良反应报告和监测管理工作中违反本办法，造成严重后果的，依照有关规定给予行政处分。"},{"i":62,"n":"第六十二条","txt":"药品生产、经营企业和医疗机构违反相关规定，给药品使用者造成损害的，依法承担赔偿责任。"},{"i":63,"n":"第六十三条","txt":"本办法下列用语的含义： （一）药品不良反应，是指合格药品在正常用法用量下出现的与用药目的无关的有害反应。 （二）药品不良反应报告和监测，是指药品不良反应的发现、报告、评价和控制的过程。 （三）严重药品不良反应，是指因使用药品引起以下损害情形之一的反应： 1.导致死亡； 2.危及生命； 3.致癌、致畸、致出生缺陷； 4.导致显著的或者永久的人体伤残或者器官功能的损伤； 5.导致住院或者住院时间延长； 6.导致其他重要医学事件，如不进行治疗可能出现上述所列情况的。 （四）新的药品不良反应，是指药品说明书中未载明的不良反应。说明书中已有描述，但不良反应发生的性质、程度、后果或者频率与说明书描述不一致或者更严重的，按照新的药品不良反应处理。 （五）药品群体不良事件，是指同一药品在使用过程中，在相对集中的时间、区域内，对一定数量人群的身体健康或者生命安全造成损害或者威胁，需要予以紧急处置的事件。"},{"i":64,"n":"第六十四条","txt":"进口药品的境外制药厂商可以委托其驻中国境内的办事机构或者中国境内代理机构，按照本办法对药品生产企业的规定，履行药品不良反应报告和监测义务。"},{"i":65,"n":"第六十五条","txt":"卫生部和国家食品药品监督管理局对疫苗不良反应报告和监测另有规定的，从其规定。"},{"i":66,"n":"第六十六条","txt":"医疗机构制剂的不良反应报告和监测管理办法由各省、自治区、直辖市药品监督管理部门会同同级卫生行政部门制定。"},{"i":67,"n":"第六十七条","txt":"本办法自2011年7月1日起施行。国家食品药品监督管理局和卫生部于2004年3月4日公布的《药品不良反应报告和监测管理办法》（国家食品药品监督管理局令第7号）同时废止。 附表：1.药品不良反应/事件报告表 2.群体不良事件基本信息表 3.境外发生的药品不良反应/事件报告表 附表1 药品不良反应/事件报告表 首次报告□ 跟踪报告□ 编码： 报告类型：新的□ 严重□ 一般□ 报告单位类别：医疗机构□ 经营企业□ 生产企业□ 个人□ 其他□ 严重药品不良反应，是指因使用药品引起以下损害情形之一的反应： 1） 导致死亡； 2）危及生命； 3）致癌、致畸、致出生缺陷； 4）导致显著的或者永久的人体伤残或者器官功能的损伤； 5）导致住院或者住院时间延长； 6）导致其他重要医学事件，如不进行治疗可能出现上述所列情况的。 新的药品不良反应：是指药品说明书中未载明的不良反应。说明书中已有描述，但不良反应"}],"yaopinshengchanzhiliangguanliguifan":[{"i":1,"n":"第一条","txt":"为规范药品生产质量管理，根据《中华人民共和国药品管理法》、《中华人民共和国药品管理法实施条例》，制定本规范。"},{"i":2,"n":"第二条","txt":"企业应当建立药品质量管理体系。该体系应当涵盖影响药品质量的所有因素，包括确保药品质量符合预定用途的有组织、有计划的全部活动。"},{"i":3,"n":"第三条","txt":"本规范作为质量管理体系的一部分，是药品生产管理和质量控制的基本要求，旨在最大限度地降低药品生产过程中污染、交叉污染以及混淆、差错等风险，确保持续稳定地生产出符合预定用途和注册要求的药品。"},{"i":4,"n":"第四条","txt":"企业应当严格执行本规范，坚持诚实守信，禁止任何虚假、欺骗行为。"},{"i":5,"n":"第五条","txt":"企业应当建立符合药品质量管理要求的质量目标，将药品注册的有关安全、有效和质量可控的所有要求，系统地贯彻到药品生产、控制及产品放行、贮存、发运的全过程中，确保所生产的药品符合预定用途和注册要求。"},{"i":6,"n":"第六条","txt":"企业高层管理人员应当确保实现既定的质量目标，不同层次的人员以及供应商、经销商应当共同参与并承担各自的责任。"},{"i":7,"n":"第七条","txt":"企业应当配备足够的、符合要求的人员、厂房、设施和设备，为实现质量目标提供必要的条件。"},{"i":8,"n":"第八条","txt":"质量保证是质量管理体系的一部分。企业必须建立质量保证系统，同时建立完整的文件体系，以保证系统有效运行。"},{"i":9,"n":"第九条","txt":"质量保证系统应当确保： （一）药品的设计与研发体现本规范的要求； （二）生产管理和质量控制活动符合本规范的要求； （三）管理职责明确； （四）采购和使用的原辅料和包装材料正确无误； （五）中间产品得到有效控制； （六）确认、验证的实施； （七）严格按照规程进行生产、检查、检验和复核； （八）每批产品经质量受权人批准后方可放行； （九）在贮存、发运和随后的各种操作过程中有保证药品质量的适当措施； （十）按照自检操作规程，定期检查评估质量保证系统的有效性和适用性。"},{"i":10,"n":"第十条","txt":"药品生产质量管理的基本要求： （一）制定生产工艺，系统地回顾并证明其可持续稳定地生产出符合要求的产品； （二）生产工艺及其重大变更均经过验证； （三）配备所需的资源，至少包括： 1.具有适当的资质并经培训合格的人员； 2.足够的厂房和空间； 3.适用的设备和维修保障； 4.正确的原辅料、包装材料和标签； 5.经批准的工艺规程和操作规程； 6.适当的贮运条件。 （四）应当使用准确、易懂的语言制定操作规程； （五）操作人员经过培训，能够按照操作规程正确操作； （六）生产全过程应当有记录，偏差均经过调查并记录； （七）批记录和发运记录应当能够追溯批产品的完整历史，并妥善保存、便于查阅； （八）降低药品发运过程中的质量风险； （九）建立药品召回系统，确保能够召回任何一批已发运销售的产品； （十）调查导致药品投诉和质量缺陷的原因，并采取措施，防止类似质量缺陷再次发生。"},{"i":11,"n":"第十一条","txt":"质量控制包括相应的组织机构、文件系统以及取样、检验等，确保物料或产品在放行前完成必要的检验，确认其质量符合要求。"},{"i":12,"n":"第十二条","txt":"质量控制的基本要求： （一）应当配备适当的设施、设备、仪器和经过培训的人员，有效、可靠地完成所有质量控制的相关活动； （二）应当有批准的操作规程，用于原辅料、包装材料、中间产品、待包装产品和成品的取样、检查、检验以及产品的稳定性考察，必要时进行环境监测，以确保符合本规范的要求； （三）由经授权的人员按照规定的方法对原辅料、包装材料、中间产品、待包装产品和成品取样； （四）检验方法应当经过验证或确认； （五）取样、检查、检验应当有记录，偏差应当经过调查并记录； （六）物料、中间产品、待包装产品和成品必须按照质量标准进行检查和检验，并有记录； （七）物料和最终包装的成品应当有足够的留样，以备必要的检查或检验；除最终包装容器过大的成品外，成品的留样包装应当与最终包装相同。"},{"i":13,"n":"第十三条","txt":"质量风险管理是在整个产品生命周期中采用前瞻或回顾的方式，对质量风险进行评估、控制、沟通、审核的系统过程。"},{"i":14,"n":"第十四条","txt":"应当根据科学知识及经验对质量风险进行评估，以保证产品质量。"},{"i":15,"n":"第十五条","txt":"质量风险管理过程所采用的方法、措施、形式及形成的文件应当与存在风险的级别相适应。"},{"i":16,"n":"第十六条","txt":"企业应当建立与药品生产相适应的管理机构，并有组织机构图。 企业应当设立独立的质量管理部门，履行质量保证和质量控制的职责。质量管理部门可以分别设立质量保证部门和质量控制部门。"},{"i":17,"n":"第十七条","txt":"质量管理部门应当参与所有与质量有关的活动，负责审核所有与本规范有关的文件。质量管理部门人员不得将职责委托给其他部门的人员。"},{"i":18,"n":"第十八条","txt":"企业应当配备足够数量并具有适当资质（含学历、培训和实践经验）的管理和操作人员，应当明确规定每个部门和每个岗位的职责。岗位职责不得遗漏，交叉的职责应当有明确规定。每个人所承担的职责不应当过多。 所有人员应当明确并理解自己的职责，熟悉与其职责相关的要求，并接受必要的培训，包括上岗前培训和继续培训。"},{"i":19,"n":"第十九条","txt":"职责通常不得委托给他人。确需委托的，其职责可委托给具有相当资质的指定人员。"},{"i":20,"n":"第二十条","txt":"关键人员应当为企业的全职人员，至少应当包括企业负责人、生产管理负责人、质量管理负责人和质量受权人。 质量管理负责人和生产管理负责人不得互相兼任。质量管理负责人和质量受权人可以兼任。应当制定操作规程确保质量受权人独立履行职责，不受企业负责人和其他人员的干扰。"},{"i":21,"n":"第二十一条","txt":"企业负责人 企业负责人是药品质量的主要责任人，全面负责企业日常管理。为确保企业实现质量目标并按照本规范要求生产药品，企业负责人应当负责提供必要的资源，合理计划、组织和协调，保证质量管理部门独立履行其职责。"},{"i":22,"n":"第二十二条","txt":"生产管理负责人 （一）资质： 生产管理负责人应当至少具有药学或相关专业本科学历（或中级专业技术职称或执业药师资格），具有至少三年从事药品生产和质量管理的实践经验，其中至少有一年的药品生产管理经验，接受过与所生产产品相关的专业知识培训。 （二）主要职责： 1.确保药品按照批准的工艺规程生产、贮存，以保证药品质量； 2.确保严格执行与生产操作相关的各种操作规程； 3.确保批生产记录和批包装记录经过指定人员审核并送交质量管理部门； 4.确保厂房和设备的维护保养，以保持其良好的运行状态； 5.确保完成各种必要的验证工作； 6.确保生产相关人员经过必要的上岗前培训和继续培训，并根据实际需要调整培训内容。"},{"i":23,"n":"第二十三条","txt":"质量管理负责人 （一）资质： 质量管理负责人应当至少具有药学或相关专业本科学历（或中级专业技术职称或执业药师资格），具有至少五年从事药品生产和质量管理的实践经验，其中至少一年的药品质量管理经验，接受过与所生产产品相关的专业知识培训。 （二）主要职责： 1.确保原辅料、包装材料、中间产品、待包装产品和成品符合经注册批准的要求和质量标准； 2.确保在产品放行前完成对批记录的审核； 3.确保完成所有必要的检验； 4.批准质量标准、取样方法、检验方法和其他质量管理的操作规程； 5.审核和批准所有与质量有关的变更； 6.确保所有重大偏差和检验结果超标已经过调查并得到及时处理； 7.批准并监督委托检验； 8.监督厂房和设备的维护，以保持其良好的运行状态； 9.确保完成各种必要的确认或验证工作，审核和批准确认或验证方案和报告； 10.确保完成自检； 11.评估和批准物料供应商； 12.确保所有与产品"},{"i":24,"n":"第二十四条","txt":"生产管理负责人和质量管理负责人通常有下列共同的职责： （一）审核和批准产品的工艺规程、操作规程等文件； （二）监督厂区卫生状况； （三）确保关键设备经过确认； （四）确保完成生产工艺验证； （五）确保企业所有相关人员都已经过必要的上岗前培训和继续培训，并根据实际需要调整培训内容； （六）批准并监督委托生产； （七）确定和监控物料和产品的贮存条件； （八）保存记录； （九）监督本规范执行状况； （十）监控影响产品质量的因素。"},{"i":25,"n":"第二十五条","txt":"质量受权人 （一）资质： 质量受权人应当至少具有药学或相关专业本科学历（或中级专业技术职称或执业药师资格），具有至少五年从事药品生产和质量管理的实践经验，从事过药品生产过程控制和质量检验工作。 质量受权人应当具有必要的专业理论知识，并经过与产品放行有关的培训，方能独立履行其职责。 （二）主要职责： 1.参与企业质量体系建立、内部自检、外部质量审计、验证以及药品不良反应报告、产品召回等质量管理活动； 2.承担产品放行的职责，确保每批已放行产品的生产、检验均符合相关法规、药品注册要求和质量标准； 3.在产品放行前，质量受权人必须按照上述第2项的要求出具产品放行审核记录，并纳入批记录。"},{"i":26,"n":"第二十六条","txt":"企业应当指定部门或专人负责培训管理工作，应当有经生产管理负责人或质量管理负责人审核或批准的培训方案或计划，培训记录应当予以保存。"},{"i":27,"n":"第二十七条","txt":"与药品生产、质量有关的所有人员都应当经过培训，培训的内容应当与岗位的要求相适应。除进行本规范理论和实践的培训外，还应当有相关法规、相应岗位的职责、技能的培训，并定期评估培训的实际效果。"},{"i":28,"n":"第二十八条","txt":"高风险操作区（如：高活性、高毒性、传染性、高致敏性物料的生产区）的工作人员应当接受专门的培训。"},{"i":29,"n":"第二十九条","txt":"所有人员都应当接受卫生要求的培训，企业应当建立人员卫生操作规程，最大限度地降低人员对药品生产造成污染的风险。"},{"i":30,"n":"第三十条","txt":"人员卫生操作规程应当包括与健康、卫生习惯及人员着装相关的内容。生产区和质量控制区的人员应当正确理解相关的人员卫生操作规程。企业应当采取措施确保人员卫生操作规程的执行。"},{"i":31,"n":"第三十一条","txt":"企业应当对人员健康进行管理，并建立健康档案。直接接触药品的生产人员上岗前应当接受健康检查，以后每年至少进行一次健康检查。"},{"i":32,"n":"第三十二条","txt":"企业应当采取适当措施，避免体表有伤口、患有传染病或其他可能污染药品疾病的人员从事直接接触药品的生产。"},{"i":33,"n":"第三十三条","txt":"参观人员和未经培训的人员不得进入生产区和质量控制区，特殊情况确需进入的，应当事先对个人卫生、更衣等事项进行指导。"},{"i":34,"n":"第三十四条","txt":"任何进入生产区的人员均应当按照规定更衣。工作服的选材、式样及穿戴方式应当与所从事的工作和空气洁净度级别要求相适应。"},{"i":35,"n":"第三十五条","txt":"进入洁净生产区的人员不得化妆和佩带饰物。"},{"i":36,"n":"第三十六条","txt":"生产区、仓储区应当禁止吸烟和饮食，禁止存放食品、饮料、香烟和个人用药品等非生产用物品。"},{"i":37,"n":"第三十七条","txt":"操作人员应当避免裸手直接接触药品、与药品直接接触的包装材料和设备表面。"},{"i":38,"n":"第三十八条","txt":"厂房的选址、设计、布局、建造、改造和维护必须符合药品生产要求，应当能够最大限度地避免污染、交叉污染、混淆和差错，便于清洁、操作和维护。"},{"i":39,"n":"第三十九条","txt":"应当根据厂房及生产防护措施综合考虑选址，厂房所处的环境应当能够最大限度地降低物料或产品遭受污染的风险。"},{"i":40,"n":"第四十条","txt":"企业应当有整洁的生产环境；厂区的地面、路面及运输等不应当对药品的生产造成污染；生产、行政、生活和辅助区的总体布局应当合理，不得互相妨碍；厂区和厂房内的人、物流走向应当合理。"},{"i":41,"n":"第四十一条","txt":"应当对厂房进行适当维护，并确保维修活动不影响药品的质量。应当按照详细的书面操作规程对厂房进行清洁或必要的消毒。"},{"i":42,"n":"第四十二条","txt":"厂房应当有适当的照明、温度、湿度和通风，确保生产和贮存的产品质量以及相关设备性能不会直接或间接地受到影响。"},{"i":43,"n":"第四十三条","txt":"厂房、设施的设计和安装应当能够有效防止昆虫或其它动物进入。应当采取必要的措施，避免所使用的灭鼠药、杀虫剂、烟熏剂等对设备、物料、产品造成污染。"},{"i":44,"n":"第四十四条","txt":"应当采取适当措施，防止未经批准人员的进入。生产、贮存和质量控制区不应当作为非本区工作人员的直接通道。"},{"i":45,"n":"第四十五条","txt":"应当保存厂房、公用设施、固定管道建造或改造后的竣工图纸。"},{"i":46,"n":"第四十六条","txt":"为降低污染和交叉污染的风险，厂房、生产设施和设备应当根据所生产药品的特性、工艺流程及相应洁净度级别要求合理设计、布局和使用，并符合下列要求： （一）应当综合考虑药品的特性、工艺和预定用途等因素，确定厂房、生产设施和设备多产品共用的可行性，并有相应评估报告； （二）生产特殊性质的药品，如高致敏性药品（如青霉素类）或生物制品（如卡介苗或其他用活性微生物制备而成的药品），必须采用专用和独立的厂房、生产设施和设备。青霉素类药品产尘量大的操作区域应当保持相对负压，排至室外的废气应当经过净化处理并符合要求，排风口应当远离其他空气净化系统的进风口； （三）生产β-内酰胺结构类药品、性激素类避孕药品必须使用专用设施（如独立的空气净化系统）和设备，并与其他药品生产区严格分开； （四）生产某些激素类、细胞毒性类、高活性化学药品应当使用专用设施（如独立的空气净化系统）和设备；特殊情况下，如采取特别防护措施并"},{"i":47,"n":"第四十七条","txt":"生产区和贮存区应当有足够的空间，确保有序地存放设备、物料、中间产品、待包装产品和成品，避免不同产品或物料的混淆、交叉污染，避免生产或质量控制操作发生遗漏或差错。"},{"i":48,"n":"第四十八条","txt":"应当根据药品品种、生产操作要求及外部环境状况等配置空调净化系统，使生产区有效通风，并有温度、湿度控制和空气净化过滤，保证药品的生产环境符合要求。 洁净区与非洁净区之间、不同级别洁净区之间的压差应当不低于10帕斯卡。必要时，相同洁净度级别的不同功能区域（操作间）之间也应当保持适当的压差梯度。 口服液体和固体制剂、腔道用药（含直肠用药）、表皮外用药品等非无菌制剂生产的暴露工序区域及其直接接触药品的包装材料最终处理的暴露工序区域，应当参照“无菌药品”附录中D级洁净区的要求设置，企业可根据产品的标准和特性对该区域采取适当的微生物监控措施。"},{"i":49,"n":"第四十九条","txt":"洁净区的内表面（墙壁、地面、天棚）应当平整光滑、无裂缝、接口严密、无颗粒物脱落，避免积尘，便于有效清洁，必要时应当进行消毒。"},{"i":50,"n":"第五十条","txt":"各种管道、照明设施、风口和其他公用设施的设计和安装应当避免出现不易清洁的部位，应当尽可能在生产区外部对其进行维护。"},{"i":51,"n":"第五十一条","txt":"排水设施应当大小适宜，并安装防止倒灌的装置。应当尽可能避免明沟排水；不可避免时，明沟宜浅，以方便清洁和消毒。"},{"i":52,"n":"第五十二条","txt":"制剂的原辅料称量通常应当在专门设计的称量室内进行。"},{"i":53,"n":"第五十三条","txt":"产尘操作间（如干燥物料或产品的取样、称量、混合、包装等操作间）应当保持相对负压或采取专门的措施，防止粉尘扩散、避免交叉污染并便于清洁。"},{"i":54,"n":"第五十四条","txt":"用于药品包装的厂房或区域应当合理设计和布局，以避免混淆或交叉污染。如同一区域内有数条包装线，应当有隔离措施。"},{"i":55,"n":"第五十五条","txt":"生产区应当有适度的照明，目视操作区域的照明应当满足操作要求。"},{"i":56,"n":"第五十六条","txt":"生产区内可设中间控制区域，但中间控制操作不得给药品带来质量风险。"},{"i":57,"n":"第五十七条","txt":"仓储区应当有足够的空间，确保有序存放待验、合格、不合格、退货或召回的原辅料、包装材料、中间产品、待包装产品和成品等各类物料和产品。"},{"i":58,"n":"第五十八条","txt":"仓储区的设计和建造应当确保良好的仓储条件，并有通风和照明设施。仓储区应当能够满足物料或产品的贮存条件（如温湿度、避光）和安全贮存的要求，并进行检查和监控。"},{"i":59,"n":"第五十九条","txt":"高活性的物料或产品以及印刷包装材料应当贮存于安全的区域。"},{"i":60,"n":"第六十条","txt":"接收、发放和发运区域应当能够保护物料、产品免受外界天气（如雨、雪）的影响。接收区的布局和设施应当能够确保到货物料在进入仓储区前可对外包装进行必要的清洁。"},{"i":61,"n":"第六十一条","txt":"如采用单独的隔离区域贮存待验物料，待验区应当有醒目的标识，且只限于经批准的人员出入。 不合格、退货或召回的物料或产品应当隔离存放。 如果采用其他方法替代物理隔离，则该方法应当具有同等的安全性。"},{"i":62,"n":"第六十二条","txt":"通常应当有单独的物料取样区。取样区的空气洁净度级别应当与生产要求一致。如在其他区域或采用其他方式取样，应当能够防止污染或交叉污染。"},{"i":63,"n":"第六十三条","txt":"质量控制实验室通常应当与生产区分开。生物检定、微生物和放射性同位素的实验室还应当彼此分开。"},{"i":64,"n":"第六十四条","txt":"实验室的设计应当确保其适用于预定的用途，并能够避免混淆和交叉污染，应当有足够的区域用于样品处置、留样和稳定性考察样品的存放以及记录的保存。"},{"i":65,"n":"第六十五条","txt":"必要时，应当设置专门的仪器室，使灵敏度高的仪器免受静电、震动、潮湿或其他外界因素的干扰。"},{"i":66,"n":"第六十六条","txt":"处理生物样品或放射性样品等特殊物品的实验室应当符合国家的有关要求。"},{"i":67,"n":"第六十七条","txt":"实验动物房应当与其他区域严格分开，其设计、建造应当符合国家有关规定，并设有独立的空气处理设施以及动物的专用通道。"},{"i":68,"n":"第六十八条","txt":"休息室的设置不应当对生产区、仓储区和质量控制区造成不良影响。"},{"i":69,"n":"第六十九条","txt":"更衣室和盥洗室应当方便人员进出，并与使用人数相适应。盥洗室不得与生产区和仓储区直接相通。"},{"i":70,"n":"第七十条","txt":"维修间应当尽可能远离生产区。存放在洁净区内的维修用备件和工具，应当放置在专门的房间或工具柜中。"},{"i":71,"n":"第七十一条","txt":"设备的设计、选型、安装、改造和维护必须符合预定用途，应当尽可能降低产生污染、交叉污染、混淆和差错的风险，便于操作、清洁、维护，以及必要时进行的消毒或灭菌。"},{"i":72,"n":"第七十二条","txt":"应当建立设备使用、清洁、维护和维修的操作规程，并保存相应的操作记录。"},{"i":73,"n":"第七十三条","txt":"应当建立并保存设备采购、安装、确认的文件和记录。"},{"i":74,"n":"第七十四条","txt":"生产设备不得对药品质量产生任何不利影响。与药品直接接触的生产设备表面应当平整、光洁、易清洗或消毒、耐腐蚀，不得与药品发生化学反应、吸附药品或向药品中释放物质。"},{"i":75,"n":"第七十五条","txt":"应当配备有适当量程和精度的衡器、量具、仪器和仪表。"},{"i":76,"n":"第七十六条","txt":"应当选择适当的清洗、清洁设备，并防止这类设备成为污染源。"},{"i":77,"n":"第七十七条","txt":"设备所用的润滑剂、冷却剂等不得对药品或容器造成污染，应当尽可能使用食用级或级别相当的润滑剂。"},{"i":78,"n":"第七十八条","txt":"生产用模具的采购、验收、保管、维护、发放及报废应当制定相应操作规程，设专人专柜保管，并有相应记录。"},{"i":79,"n":"第七十九条","txt":"设备的维护和维修不得影响产品质量。"},{"i":80,"n":"第八十条","txt":"应当制定设备的预防性维护计划和操作规程，设备的维护和维修应当有相应的记录。"},{"i":81,"n":"第八十一条","txt":"经改造或重大维修的设备应当进行再确认，符合要求后方可用于生产。"},{"i":82,"n":"第八十二条","txt":"主要生产和检验设备都应当有明确的操作规程。"},{"i":83,"n":"第八十三条","txt":"生产设备应当在确认的参数范围内使用。"},{"i":84,"n":"第八十四条","txt":"应当按照详细规定的操作规程清洁生产设备。 生产设备清洁的操作规程应当规定具体而完整的清洁方法、清洁用设备或工具、清洁剂的名称和配制方法、去除前一批次标识的方法、保护已清洁设备在使用前免受污染的方法、已清洁设备最长的保存时限、使用前检查设备清洁状况的方法，使操作者能以可重现的、有效的方式对各类设备进行清洁。 如需拆装设备，还应当规定设备拆装的顺序和方法；如需对设备消毒或灭菌，还应当规定消毒或灭菌的具体方法、消毒剂的名称和配制方法。必要时，还应当规定设备生产结束至清洁前所允许的最长间隔时限。"},{"i":85,"n":"第八十五条","txt":"已清洁的生产设备应当在清洁、干燥的条件下存放。"},{"i":86,"n":"第八十六条","txt":"用于药品生产或检验的设备和仪器，应当有使用日志，记录内容包括使用、清洁、维护和维修情况以及日期、时间、所生产及检验的药品名称、规格和批号等。"},{"i":87,"n":"第八十七条","txt":"生产设备应当有明显的状态标识，标明设备编号和内容物（如名称、规格、批号）；没有内容物的应当标明清洁状态。"},{"i":88,"n":"第八十八条","txt":"不合格的设备如有可能应当搬出生产和质量控制区，未搬出前，应当有醒目的状态标识。"},{"i":89,"n":"第八十九条","txt":"主要固定管道应当标明内容物名称和流向。"},{"i":90,"n":"第九十条","txt":"应当按照操作规程和校准计划定期对生产和检验用衡器、量具、仪表、记录和控制设备以及仪器进行校准和检查，并保存相关记录。校准的量程范围应当涵盖实际生产和检验的使用范围。"},{"i":91,"n":"第九十一条","txt":"应当确保生产和检验使用的关键衡器、量具、仪表、记录和控制设备以及仪器经过校准，所得出的数据准确、可靠。"},{"i":92,"n":"第九十二条","txt":"应当使用计量标准器具进行校准，且所用计量标准器具应当符合国家有关规定。校准记录应当标明所用计量标准器具的名称、编号、校准有效期和计量合格证明编号，确保记录的可追溯性。"},{"i":93,"n":"第九十三条","txt":"衡器、量具、仪表、用于记录和控制的设备以及仪器应当有明显的标识，标明其校准有效期。"},{"i":94,"n":"第九十四条","txt":"不得使用未经校准、超过校准有效期、失准的衡器、量具、仪表以及用于记录和控制的设备、仪器。"},{"i":95,"n":"第九十五条","txt":"在生产、包装、仓储过程中使用自动或电子设备的，应当按照操作规程定期进行校准和检查，确保其操作功能正常。校准和检查应当有相应的记录。"},{"i":96,"n":"第九十六条","txt":"制药用水应当适合其用途，并符合《中华人民共和国药典》的质量标准及相关要求。制药用水至少应当采用饮用水。"},{"i":97,"n":"第九十七条","txt":"水处理设备及其输送系统的设计、安装、运行和维护应当确保制药用水达到设定的质量标准。水处理设备的运行不得超出其设计能力。"},{"i":98,"n":"第九十八条","txt":"纯化水、注射用水储罐和输送管道所用材料应当无毒、耐腐蚀；储罐的通气口应当安装不脱落纤维的疏水性除菌滤器；管道的设计和安装应当避免死角、盲管。"},{"i":99,"n":"第九十九条","txt":"纯化水、注射用水的制备、贮存和分配应当能够防止微生物的滋生。纯化水可采用循环，注射用水可采用70℃以上保温循环。"},{"i":100,"n":"第一百条","txt":"应当对制药用水及原水的水质进行定期监测，并有相应的记录。"},{"i":101,"n":"第一百零一条","txt":"应当按照操作规程对纯化水、注射用水管道进行清洗消毒，并有相关记录。发现制药用水微生物污染达到警戒限度、纠偏限度时应当按照操作规程处理。"},{"i":102,"n":"第一百零二条","txt":"药品生产所用的原辅料、与药品直接接触的包装材料应当符合相应的质量标准。药品上直接印字所用油墨应当符合食用标准要求。 进口原辅料应当符合国家相关的进口管理规定。"},{"i":103,"n":"第一百零三条","txt":"应当建立物料和产品的操作规程，确保物料和产品的正确接收、贮存、发放、使用和发运，防止污染、交叉污染、混淆和差错。 物料和产品的处理应当按照操作规程或工艺规程执行，并有记录。"},{"i":104,"n":"第一百零四条","txt":"物料供应商的确定及变更应当进行质量评估，并经质量管理部门批准后方可采购。"},{"i":105,"n":"第一百零五条","txt":"物料和产品的运输应当能够满足其保证质量的要求，对运输有特殊要求的，其运输条件应当予以确认。"},{"i":106,"n":"第一百零六条","txt":"原辅料、与药品直接接触的包装材料和印刷包装材料的接收应当有操作规程，所有到货物料均应当检查，以确保与订单一致，并确认供应商已经质量管理部门批准。 物料的外包装应当有标签，并注明规定的信息。必要时，还应当进行清洁，发现外包装损坏或其他可能影响物料质量的问题，应当向质量管理部门报告并进行调查和记录。 每次接收均应当有记录，内容包括： （一）交货单和包装容器上所注物料的名称； （二）企业内部所用物料名称和（或）代码； （三）接收日期； （四）供应商和生产商（如不同）的名称； （五）供应商和生产商（如不同）标识的批号； （六）接收总量和包装容器数量； （七）接收后企业指定的批号或流水号； （八）有关说明（如包装状况）。"},{"i":107,"n":"第一百零七条","txt":"物料接收和成品生产后应当及时按照待验管理，直至放行。"},{"i":108,"n":"第一百零八条","txt":"物料和产品应当根据其性质有序分批贮存和周转，发放及发运应当符合先进先出和近效期先出的原则。"},{"i":109,"n":"第一百零九条","txt":"使用计算机化仓储管理的，应当有相应的操作规程，防止因系统故障、停机等特殊情况而造成物料和产品的混淆和差错。 使用完全计算机化仓储管理系统进行识别的，物料、产品等相关信息可不必以书面可读的方式标出。"},{"i":110,"n":"第一百一十条","txt":"应当制定相应的操作规程，采取核对或检验等适当措施，确认每一包装内的原辅料正确无误。"},{"i":111,"n":"第一百一十一条","txt":"一次接收数个批次的物料，应当按批取样、检验、放行。"},{"i":112,"n":"第一百一十二条","txt":"仓储区内的原辅料应当有适当的标识，并至少标明下述内容： （一）指定的物料名称和企业内部的物料代码； （二）企业接收时设定的批号； （三）物料质量状态（如待验、合格、不合格、已取样）； （四）有效期或复验期。"},{"i":113,"n":"第一百一十三条","txt":"只有经质量管理部门批准放行并在有效期或复验期内的原辅料方可使用。"},{"i":114,"n":"第一百一十四条","txt":"原辅料应当按照有效期或复验期贮存。贮存期内，如发现对质量有不良影响的特殊情况，应当进行复验。"},{"i":115,"n":"第一百一十五条","txt":"应当由指定人员按照操作规程进行配料，核对物料后，精确称量或计量，并作好标识。"},{"i":116,"n":"第一百一十六条","txt":"配制的每一物料及其重量或体积应当由他人独立进行复核，并有复核记录。"},{"i":117,"n":"第一百一十七条","txt":"用于同一批药品生产的所有配料应当集中存放，并作好标识。"},{"i":118,"n":"第一百一十八条","txt":"中间产品和待包装产品应当在适当的条件下贮存。"},{"i":119,"n":"第一百一十九条","txt":"中间产品和待包装产品应当有明确的标识，并至少标明下述内容： （一）产品名称和企业内部的产品代码； （二）产品批号； （三）数量或重量（如毛重、净重等）； （四）生产工序（必要时）； （五）产品质量状态（必要时，如待验、合格、不合格、已取样）。"},{"i":120,"n":"第一百二十条","txt":"与药品直接接触的包装材料和印刷包装材料的管理和控制要求与原辅料相同。"},{"i":121,"n":"第一百二十一条","txt":"包装材料应当由专人按照操作规程发放，并采取措施避免混淆和差错，确保用于药品生产的包装材料正确无误。"},{"i":122,"n":"第一百二十二条","txt":"应当建立印刷包装材料设计、审核、批准的操作规程，确保印刷包装材料印制的内容与药品监督管理部门核准的一致，并建立专门的文档，保存经签名批准的印刷包装材料原版实样。"},{"i":123,"n":"第一百二十三条","txt":"印刷包装材料的版本变更时，应当采取措施，确保产品所用印刷包装材料的版本正确无误。宜收回作废的旧版印刷模版并予以销毁。"},{"i":124,"n":"第一百二十四条","txt":"印刷包装材料应当设置专门区域妥善存放，未经批准人员不得进入。切割式标签或其他散装印刷包装材料应当分别置于密闭容器内储运，以防混淆。"},{"i":125,"n":"第一百二十五条","txt":"印刷包装材料应当由专人保管，并按照操作规程和需求量发放。"},{"i":126,"n":"第一百二十六条","txt":"每批或每次发放的与药品直接接触的包装材料或印刷包装材料，均应当有识别标志，标明所用产品的名称和批号。"},{"i":127,"n":"第一百二十七条","txt":"过期或废弃的印刷包装材料应当予以销毁并记录。"},{"i":128,"n":"第一百二十八条","txt":"成品放行前应当待验贮存。"},{"i":129,"n":"第一百二十九条","txt":"成品的贮存条件应当符合药品注册批准的要求。"},{"i":130,"n":"第一百三十条","txt":"麻醉药品、精神药品、医疗用毒性药品（包括药材）、放射性药品、药品类易制毒化学品及易燃、易爆和其他危险品的验收、贮存、管理应当执行国家有关的规定。"},{"i":131,"n":"第一百三十一条","txt":"不合格的物料、中间产品、待包装产品和成品的每个包装容器上均应当有清晰醒目的标志，并在隔离区内妥善保存。"},{"i":132,"n":"第一百三十二条","txt":"不合格的物料、中间产品、待包装产品和成品的处理应当经质量管理负责人批准，并有记录。"},{"i":133,"n":"第一百三十三条","txt":"产品回收需经预先批准，并对相关的质量风险进行充分评估，根据评估结论决定是否回收。回收应当按照预定的操作规程进行，并有相应记录。回收处理后的产品应当按照回收处理中最早批次产品的生产日期确定有效期。"},{"i":134,"n":"第一百三十四条","txt":"制剂产品不得进行重新加工。不合格的制剂中间产品、待包装产品和成品一般不得进行返工。只有不影响产品质量、符合相应质量标准，且根据预定、经批准的操作规程以及对相关风险充分评估后，才允许返工处理。返工应当有相应记录。"},{"i":135,"n":"第一百三十五条","txt":"对返工或重新加工或回收合并后生产的成品，质量管理部门应当考虑需要进行额外相关项目的检验和稳定性考察。"},{"i":136,"n":"第一百三十六条","txt":"企业应当建立药品退货的操作规程，并有相应的记录，内容至少应当包括：产品名称、批号、规格、数量、退货单位及地址、退货原因及日期、最终处理意见。 同一产品同一批号不同渠道的退货应当分别记录、存放和处理。"},{"i":137,"n":"第一百三十七条","txt":"只有经检查、检验和调查，有证据证明退货质量未受影响，且经质量管理部门根据操作规程评价后，方可考虑将退货重新包装、重新发运销售。评价考虑的因素至少应当包括药品的性质、所需的贮存条件、药品的现状、历史，以及发运与退货之间的间隔时间等因素。不符合贮存和运输要求的退货，应当在质量管理部门监督下予以销毁。对退货质量存有怀疑时，不得重新发运。 对退货进行回收处理的，回收后的产品应当符合预定的质量标准和第一百三十三条的要求。 退货处理的过程和结果应当有相应记录。"},{"i":138,"n":"第一百三十八条","txt":"企业应当确定需要进行的确认或验证工作，以证明有关操作的关键要素能够得到有效控制。确认或验证的范围和程度应当经过风险评估来确定。"},{"i":139,"n":"第一百三十九条","txt":"企业的厂房、设施、设备和检验仪器应当经过确认，应当采用经过验证的生产工艺、操作规程和检验方法进行生产、操作和检验，并保持持续的验证状态。"},{"i":140,"n":"第一百四十条","txt":"应当建立确认与验证的文件和记录，并能以文件和记录证明达到以下预定的目标： （一）设计确认应当证明厂房、设施、设备的设计符合预定用途和本规范要求； （二）安装确认应当证明厂房、设施、设备的建造和安装符合设计标准； （三）运行确认应当证明厂房、设施、设备的运行符合设计标准； （四）性能确认应当证明厂房、设施、设备在正常操作方法和工艺条件下能够持续符合标准； （五）工艺验证应当证明一个生产工艺按照规定的工艺参数能够持续生产出符合预定用途和注册要求的产品。"},{"i":141,"n":"第一百四十一条","txt":"采用新的生产处方或生产工艺前，应当验证其常规生产的适用性。生产工艺在使用规定的原辅料和设备条件下，应当能够始终生产出符合预定用途和注册要求的产品。"},{"i":142,"n":"第一百四十二条","txt":"当影响产品质量的主要因素，如原辅料、与药品直接接触的包装材料、生产设备、生产环境（或厂房）、生产工艺、检验方法等发生变更时，应当进行确认或验证。必要时，还应当经药品监督管理部门批准。"},{"i":143,"n":"第一百四十三条","txt":"清洁方法应当经过验证，证实其清洁的效果，以有效防止污染和交叉污染。清洁验证应当综合考虑设备使用情况、所使用的清洁剂和消毒剂、取样方法和位置以及相应的取样回收率、残留物的性质和限度、残留物检验方法的灵敏度等因素。"},{"i":144,"n":"第一百四十四条","txt":"确认和验证不是一次性的行为。首次确认或验证后，应当根据产品质量回顾分析情况进行再确认或再验证。关键的生产工艺和操作规程应当定期进行再验证，确保其能够达到预期结果。"},{"i":145,"n":"第一百四十五条","txt":"企业应当制定验证总计划，以文件形式说明确认与验证工作的关键信息。"},{"i":146,"n":"第一百四十六条","txt":"验证总计划或其他相关文件中应当作出规定，确保厂房、设施、设备、检验仪器、生产工艺、操作规程和检验方法等能够保持持续稳定。"},{"i":147,"n":"第一百四十七条","txt":"应当根据确认或验证的对象制定确认或验证方案，并经审核、批准。确认或验证方案应当明确职责。"},{"i":148,"n":"第一百四十八条","txt":"确认或验证应当按照预先确定和批准的方案实施，并有记录。确认或验证工作完成后，应当写出报告，并经审核、批准。确认或验证的结果和结论（包括评价和建议）应当有记录并存档。"},{"i":149,"n":"第一百四十九条","txt":"应当根据验证的结果确认工艺规程和操作规程。"},{"i":150,"n":"第一百五十条","txt":"文件是质量保证系统的基本要素。企业必须有内容正确的书面质量标准、生产处方和工艺规程、操作规程以及记录等文件。"},{"i":151,"n":"第一百五十一条","txt":"企业应当建立文件管理的操作规程，系统地设计、制定、审核、批准和发放文件。与本规范有关的文件应当经质量管理部门的审核。"},{"i":152,"n":"第一百五十二条","txt":"文件的内容应当与药品生产许可、药品注册等相关要求一致，并有助于追溯每批产品的历史情况。"},{"i":153,"n":"第一百五十三条","txt":"文件的起草、修订、审核、批准、替换或撤销、复制、保管和销毁等应当按照操作规程管理，并有相应的文件分发、撤销、复制、销毁记录。"},{"i":154,"n":"第一百五十四条","txt":"文件的起草、修订、审核、批准均应当由适当的人员签名并注明日期。"},{"i":155,"n":"第一百五十五条","txt":"文件应当标明题目、种类、目的以及文件编号和版本号。文字应当确切、清晰、易懂，不能模棱两可。"},{"i":156,"n":"第一百五十六条","txt":"文件应当分类存放、条理分明，便于查阅。"},{"i":157,"n":"第一百五十七条","txt":"原版文件复制时，不得产生任何差错；复制的文件应当清晰可辨。"},{"i":158,"n":"第一百五十八条","txt":"文件应当定期审核、修订；文件修订后，应当按照规定管理，防止旧版文件的误用。分发、使用的文件应当为批准的现行文本，已撤销的或旧版文件除留档备查外，不得在工作现场出现。"},{"i":159,"n":"第一百五十九条","txt":"与本规范有关的每项活动均应当有记录，以保证产品生产、质量控制和质量保证等活动可以追溯。记录应当留有填写数据的足够空格。记录应当及时填写，内容真实，字迹清晰、易读，不易擦除。"},{"i":160,"n":"第一百六十条","txt":"应当尽可能采用生产和检验设备自动打印的记录、图谱和曲线图等，并标明产品或样品的名称、批号和记录设备的信息，操作人应当签注姓名和日期。"},{"i":161,"n":"第一百六十一条","txt":"记录应当保持清洁，不得撕毁和任意涂改。记录填写的任何更改都应当签注姓名和日期，并使原有信息仍清晰可辨，必要时，应当说明更改的理由。记录如需重新誊写，则原有记录不得销毁，应当作为重新誊写记录的附件保存。"},{"i":162,"n":"第一百六十二条","txt":"每批药品应当有批记录，包括批生产记录、批包装记录、批检验记录和药品放行审核记录等与本批产品有关的记录。批记录应当由质量管理部门负责管理，至少保存至药品有效期后一年。 质量标准、工艺规程、操作规程、稳定性考察、确认、验证、变更等其他重要文件应当长期保存。"},{"i":163,"n":"第一百六十三条","txt":"如使用电子数据处理系统、照相技术或其他可靠方式记录数据资料，应当有所用系统的操作规程；记录的准确性应当经过核对。 使用电子数据处理系统的，只有经授权的人员方可输入或更改数据，更改和删除情况应当有记录；应当使用密码或其他方式来控制系统的登录；关键数据输入后，应当由他人独立进行复核。 用电子方法保存的批记录，应当采用磁带、缩微胶卷、纸质副本或其他方法进行备份，以确保记录的安全，且数据资料在保存期内便于查阅。"},{"i":164,"n":"第一百六十四条","txt":"物料和成品应当有经批准的现行质量标准；必要时，中间产品或待包装产品也应当有质量标准。"},{"i":165,"n":"第一百六十五条","txt":"物料的质量标准一般应当包括： （一）物料的基本信息： 1.企业统一指定的物料名称和内部使用的物料代码； 2.质量标准的依据； 3.经批准的供应商； 4.印刷包装材料的实样或样稿。 （二）取样、检验方法或相关操作规程编号； （三）定性和定量的限度要求； （四）贮存条件和注意事项； （五）有效期或复验期。"},{"i":166,"n":"第一百六十六条","txt":"外购或外销的中间产品和待包装产品应当有质量标准；如果中间产品的检验结果用于成品的质量评价，则应当制定与成品质量标准相对应的中间产品质量标准。"},{"i":167,"n":"第一百六十七条","txt":"成品的质量标准应当包括： （一）产品名称以及产品代码； （二）对应的产品处方编号（如有）； （三）产品规格和包装形式； （四）取样、检验方法或相关操作规程编号； （五）定性和定量的限度要求； （六）贮存条件和注意事项； （七）有效期。"},{"i":168,"n":"第一百六十八条","txt":"每种药品的每个生产批量均应当有经企业批准的工艺规程，不同药品规格的每种包装形式均应当有各自的包装操作要求。工艺规程的制定应当以注册批准的工艺为依据。"},{"i":169,"n":"第一百六十九条","txt":"工艺规程不得任意更改。如需更改，应当按照相关的操作规程修订、审核、批准。"},{"i":170,"n":"第一百七十条","txt":"制剂的工艺规程的内容至少应当包括： （一）生产处方： 1.产品名称和产品代码； 2.产品剂型、规格和批量； 3.所用原辅料清单（包括生产过程中使用，但不在成品中出现的物料），阐明每一物料的指定名称、代码和用量；如原辅料的用量需要折算时，还应当说明计算方法。 （二）生产操作要求： 1.对生产场所和所用设备的说明（如操作间的位置和编号、洁净度级别、必要的温湿度要求、设备型号和编号等）； 2.关键设备的准备（如清洗、组装、校准、灭菌等）所采用的方法或相应操作规程编号； 3.详细的生产步骤和工艺参数说明（如物料的核对、预处理、加入物料的顺序、混合时间、温度等）； 4.所有中间控制方法及标准； 5.预期的最终产量限度，必要时，还应当说明中间产品的产量限度，以及物料平衡的计算方法和限度； 6.待包装产品的贮存要求，包括容器、标签及特殊贮存条件； 7.需要说明的注意事项。 （三）包装操作要求： 1."},{"i":171,"n":"第一百七十一条","txt":"每批产品均应当有相应的批生产记录，可追溯该批产品的生产历史以及与质量有关的情况。"},{"i":172,"n":"第一百七十二条","txt":"批生产记录应当依据现行批准的工艺规程的相关内容制定。记录的设计应当避免填写差错。批生产记录的每一页应当标注产品的名称、规格和批号。"},{"i":173,"n":"第一百七十三条","txt":"原版空白的批生产记录应当经生产管理负责人和质量管理负责人审核和批准。批生产记录的复制和发放均应当按照操作规程进行控制并有记录，每批产品的生产只能发放一份原版空白批生产记录的复制件。"},{"i":174,"n":"第一百七十四条","txt":"在生产过程中，进行每项操作时应当及时记录，操作结束后，应当由生产操作人员确认并签注姓名和日期。"},{"i":175,"n":"第一百七十五条","txt":"批生产记录的内容应当包括： （一）产品名称、规格、批号； （二）生产以及中间工序开始、结束的日期和时间； （三）每一生产工序的负责人签名； （四）生产步骤操作人员的签名；必要时，还应当有操作（如称量）复核人员的签名； （五）每一原辅料的批号以及实际称量的数量（包括投入的回收或返工处理产品的批号及数量）； （六）相关生产操作或活动、工艺参数及控制范围，以及所用主要生产设备的编号； （七）中间控制结果的记录以及操作人员的签名； （八）不同生产工序所得产量及必要时的物料平衡计算； （九）对特殊问题或异常事件的记录，包括对偏离工艺规程的偏差情况的详细说明或调查报告，并经签字批准。"},{"i":176,"n":"第一百七十六条","txt":"每批产品或每批中部分产品的包装，都应当有批包装记录，以便追溯该批产品包装操作以及与质量有关的情况。"},{"i":177,"n":"第一百七十七条","txt":"批包装记录应当依据工艺规程中与包装相关的内容制定。记录的设计应当注意避免填写差错。批包装记录的每一页均应当标注所包装产品的名称、规格、包装形式和批号。"},{"i":178,"n":"第一百七十八条","txt":"批包装记录应当有待包装产品的批号、数量以及成品的批号和计划数量。原版空白的批包装记录的审核、批准、复制和发放的要求与原版空白的批生产记录相同。"},{"i":179,"n":"第一百七十九条","txt":"在包装过程中，进行每项操作时应当及时记录，操作结束后，应当由包装操作人员确认并签注姓名和日期。"},{"i":180,"n":"第一百八十条","txt":"批包装记录的内容包括： （一）产品名称、规格、包装形式、批号、生产日期和有效期； （二）包装操作日期和时间； （三）包装操作负责人签名； （四）包装工序的操作人员签名； （五）每一包装材料的名称、批号和实际使用的数量； （六）根据工艺规程所进行的检查记录，包括中间控制结果； （七）包装操作的详细情况，包括所用设备及包装生产线的编号； （八）所用印刷包装材料的实样，并印有批号、有效期及其他打印内容；不易随批包装记录归档的印刷包装材料可采用印有上述内容的复制品； （九）对特殊问题或异常事件的记录，包括对偏离工艺规程的偏差情况的详细说明或调查报告，并经签字批准； （十）所有印刷包装材料和待包装产品的名称、代码，以及发放、使用、销毁或退库的数量、实际产量以及物料平衡检查。"},{"i":181,"n":"第一百八十一条","txt":"操作规程的内容应当包括：题目、编号、版本号、颁发部门、生效日期、分发部门以及制定人、审核人、批准人的签名并注明日期，标题、正文及变更历史。"},{"i":182,"n":"第一百八十二条","txt":"厂房、设备、物料、文件和记录应当有编号（或代码），并制定编制编号（或代码）的操作规程，确保编号（或代码）的唯一性。"},{"i":183,"n":"第一百八十三条","txt":"下述活动也应当有相应的操作规程，其过程和结果应当有记录： （一）确认和验证； （二）设备的装配和校准； （三）厂房和设备的维护、清洁和消毒； （四）培训、更衣及卫生等与人员相关的事宜； （五）环境监测； （六）虫害控制； （七）变更控制； （八）偏差处理； （九）投诉； （十）药品召回； （十一）退货。"},{"i":184,"n":"第一百八十四条","txt":"所有药品的生产和包装均应当按照批准的工艺规程和操作规程进行操作并有相关记录，以确保药品达到规定的质量标准，并符合药品生产许可和注册批准的要求。"},{"i":185,"n":"第一百八十五条","txt":"应当建立划分产品生产批次的操作规程，生产批次的划分应当能够确保同一批次产品质量和特性的均一性。"},{"i":186,"n":"第一百八十六条","txt":"应当建立编制药品批号和确定生产日期的操作规程。每批药品均应当编制唯一的批号。除另有法定要求外，生产日期不得迟于产品成型或灌装（封）前经最后混合的操作开始日期，不得以产品包装日期作为生产日期。"},{"i":187,"n":"第一百八十七条","txt":"每批产品应当检查产量和物料平衡，确保物料平衡符合设定的限度。如有差异，必须查明原因，确认无潜在质量风险后，方可按照正常产品处理。"},{"i":188,"n":"第一百八十八条","txt":"不得在同一生产操作间同时进行不同品种和规格药品的生产操作，除非没有发生混淆或交叉污染的可能。"},{"i":189,"n":"第一百八十九条","txt":"在生产的每一阶段，应当保护产品和物料免受微生物和其他污染。"},{"i":190,"n":"第一百九十条","txt":"在干燥物料或产品，尤其是高活性、高毒性或高致敏性物料或产品的生产过程中，应当采取特殊措施，防止粉尘的产生和扩散。"},{"i":191,"n":"第一百九十一条","txt":"生产期间使用的所有物料、中间产品或待包装产品的容器及主要设备、必要的操作室应当贴签标识或以其他方式标明生产中的产品或物料名称、规格和批号，如有必要，还应当标明生产工序。"},{"i":192,"n":"第一百九十二条","txt":"容器、设备或设施所用标识应当清晰明了，标识的格式应当经企业相关部门批准。除在标识上使用文字说明外，还可采用不同的颜色区分被标识物的状态（如待验、合格、不合格或已清洁等）。"},{"i":193,"n":"第一百九十三条","txt":"应当检查产品从一个区域输送至另一个区域的管道和其他设备连接，确保连接正确无误。"},{"i":194,"n":"第一百九十四条","txt":"每次生产结束后应当进行清场，确保设备和工作场所没有遗留与本次生产有关的物料、产品和文件。下次生产开始前，应当对前次清场情况进行确认。"},{"i":195,"n":"第一百九十五条","txt":"应当尽可能避免出现任何偏离工艺规程或操作规程的偏差。一旦出现偏差，应当按照偏差处理操作规程执行。"},{"i":196,"n":"第一百九十六条","txt":"生产厂房应当仅限于经批准的人员出入。"},{"i":197,"n":"第一百九十七条","txt":"生产过程中应当尽可能采取措施，防止污染和交叉污染，如： （一）在分隔的区域内生产不同品种的药品； （二）采用阶段性生产方式； （三）设置必要的气锁间和排风；空气洁净度级别不同的区域应当有压差控制； （四）应当降低未经处理或未经充分处理的空气再次进入生产区导致污染的风险； （五）在易产生交叉污染的生产区内，操作人员应当穿戴该区域专用的防护服； （六）采用经过验证或已知有效的清洁和去污染操作规程进行设备清洁；必要时，应当对与物料直接接触的设备表面的残留物进行检测； （七）采用密闭系统生产； （八）干燥设备的进风应当有空气过滤器，排风应当有防止空气倒流装置； （九）生产和清洁过程中应当避免使用易碎、易脱屑、易发霉器具；使用筛网时，应当有防止因筛网断裂而造成污染的措施； （十）液体制剂的配制、过滤、灌封、灭菌等工序应当在规定时间内完成； （十一）软膏剂、乳膏剂、凝胶剂等半固体制剂以及栓剂的中间"},{"i":198,"n":"第一百九十八条","txt":"应当定期检查防止污染和交叉污染的措施并评估其适用性和有效性。"},{"i":199,"n":"第一百九十九条","txt":"生产开始前应当进行检查，确保设备和工作场所没有上批遗留的产品、文件或与本批产品生产无关的物料，设备处于已清洁及待用状态。检查结果应当有记录。 生产操作前，还应当核对物料或中间产品的名称、代码、批号和标识，确保生产所用物料或中间产品正确且符合要求。"},{"i":200,"n":"第二百条","txt":"应当进行中间控制和必要的环境监测，并予以记录。"},{"i":201,"n":"第二百零一条","txt":"每批药品的每一生产阶段完成后必须由生产操作人员清场，并填写清场记录。清场记录内容包括：操作间编号、产品名称、批号、生产工序、清场日期、检查项目及结果、清场负责人及复核人签名。清场记录应当纳入批生产记录。"},{"i":202,"n":"第二百零二条","txt":"包装操作规程应当规定降低污染和交叉污染、混淆或差错风险的措施。"},{"i":203,"n":"第二百零三条","txt":"包装开始前应当进行检查，确保工作场所、包装生产线、印刷机及其他设备已处于清洁或待用状态，无上批遗留的产品、文件或与本批产品包装无关的物料。检查结果应当有记录。"},{"i":204,"n":"第二百零四条","txt":"包装操作前，还应当检查所领用的包装材料正确无误，核对待包装产品和所用包装材料的名称、规格、数量、质量状态，且与工艺规程相符。"},{"i":205,"n":"第二百零五条","txt":"每一包装操作场所或包装生产线，应当有标识标明包装中的产品名称、规格、批号和批量的生产状态。"},{"i":206,"n":"第二百零六条","txt":"有数条包装线同时进行包装时，应当采取隔离或其他有效防止污染、交叉污染或混淆的措施。"},{"i":207,"n":"第二百零七条","txt":"待用分装容器在分装前应当保持清洁，避免容器中有玻璃碎屑、金属颗粒等污染物。"},{"i":208,"n":"第二百零八条","txt":"产品分装、封口后应当及时贴签。未能及时贴签时，应当按照相关的操作规程操作，避免发生混淆或贴错标签等差错。"},{"i":209,"n":"第二百零九条","txt":"单独打印或包装过程中在线打印的信息（如产品批号或有效期）均应当进行检查，确保其正确无误，并予以记录。如手工打印，应当增加检查频次。"},{"i":210,"n":"第二百一十条","txt":"使用切割式标签或在包装线以外单独打印标签，应当采取专门措施，防止混淆。"},{"i":211,"n":"第二百一十一条","txt":"应当对电子读码机、标签计数器或其他类似装置的功能进行检查，确保其准确运行。检查应当有记录。"},{"i":212,"n":"第二百一十二条","txt":"包装材料上印刷或模压的内容应当清晰，不易褪色和擦除。"},{"i":213,"n":"第二百一十三条","txt":"包装期间，产品的中间控制检查应当至少包括下述内容： （一）包装外观； （二）包装是否完整； （三）产品和包装材料是否正确； （四）打印信息是否正确； （五）在线监控装置的功能是否正常。 样品从包装生产线取走后不应当再返还，以防止产品混淆或污染。"},{"i":214,"n":"第二百一十四条","txt":"因包装过程产生异常情况而需要重新包装产品的，必须经专门检查、调查并由指定人员批准。重新包装应当有详细记录。"},{"i":215,"n":"第二百一十五条","txt":"在物料平衡检查中，发现待包装产品、印刷包装材料以及成品数量有显著差异时，应当进行调查，未得出结论前，成品不得放行。"},{"i":216,"n":"第二百一十六条","txt":"包装结束时，已打印批号的剩余包装材料应当由专人负责全部计数销毁，并有记录。如将未打印批号的印刷包装材料退库，应当按照操作规程执行。"},{"i":217,"n":"第二百一十七条","txt":"质量控制实验室的人员、设施、设备应当与产品性质和生产规模相适应。 企业通常不得进行委托检验，确需委托检验的，应当按照第十一章中委托检验部分的规定，委托外部实验室进行检验，但应当在检验报告中予以说明。"},{"i":218,"n":"第二百一十八条","txt":"质量控制负责人应当具有足够的管理实验室的资质和经验，可以管理同一企业的一个或多个实验室。"},{"i":219,"n":"第二百一十九条","txt":"质量控制实验室的检验人员至少应当具有相关专业中专或高中以上学历，并经过与所从事的检验操作相关的实践培训且通过考核。"},{"i":220,"n":"第二百二十条","txt":"质量控制实验室应当配备药典、标准图谱等必要的工具书，以及标准品或对照品等相关的标准物质。"},{"i":221,"n":"第二百二十一条","txt":"质量控制实验室的文件应当符合第八章的原则，并符合下列要求： （一）质量控制实验室应当至少有下列详细文件： 1.质量标准； 2.取样操作规程和记录； 3.检验操作规程和记录（包括检验记录或实验室工作记事簿）； 4.检验报告或证书； 5.必要的环境监测操作规程、记录和报告； 6.必要的检验方法验证报告和记录； 7.仪器校准和设备使用、清洁、维护的操作规程及记录。 （二）每批药品的检验记录应当包括中间产品、待包装产品和成品的质量检验记录，可追溯该批药品所有相关的质量检验情况； （三）宜采用便于趋势分析的方法保存某些数据（如检验数据、环境监测数据、制药用水的微生物监测数据）； （四）除与批记录相关的资料信息外，还应当保存其他原始资料或记录，以方便查阅。"},{"i":222,"n":"第二百二十二条","txt":"取样应当至少符合以下要求： （一）质量管理部门的人员有权进入生产区和仓储区进行取样及调查； （二）应当按照经批准的操作规程取样，操作规程应当详细规定： 1.经授权的取样人； 2.取样方法； 3.所用器具； 4.样品量； 5.分样的方法； 6.存放样品容器的类型和状态； 7.取样后剩余部分及样品的处置和标识； 8.取样注意事项，包括为降低取样过程产生的各种风险所采取的预防措施，尤其是无菌或有害物料的取样以及防止取样过程中污染和交叉污染的注意事项； 9.贮存条件； 10.取样器具的清洁方法和贮存要求。 （三）取样方法应当科学、合理，以保证样品的代表性； （四）留样应当能够代表被取样批次的产品或物料，也可抽取其他样品来监控生产过程中最重要的环节（如生产的开始或结束）； （五）样品的容器应当贴有标签，注明样品名称、批号、取样日期、取自哪一包装容器、取样人等信息； （六）样品应当按照规定的贮存要"},{"i":223,"n":"第二百二十三条","txt":"物料和不同生产阶段产品的检验应当至少符合以下要求： （一）企业应当确保药品按照注册批准的方法进行全项检验； （二）符合下列情形之一的，应当对检验方法进行验证： 1.采用新的检验方法； 2.检验方法需变更的； 3.采用《中华人民共和国药典》及其他法定标准未收载的检验方法； 4.法规规定的其他需要验证的检验方法。 （三）对不需要进行验证的检验方法，企业应当对检验方法进行确认，以确保检验数据准确、可靠； （四）检验应当有书面操作规程，规定所用方法、仪器和设备，检验操作规程的内容应当与经确认或验证的检验方法一致； （五）检验应当有可追溯的记录并应当复核，确保结果与记录一致。所有计算均应当严格核对； （六）检验记录应当至少包括以下内容： 1.产品或物料的名称、剂型、规格、批号或供货批号，必要时注明供应商和生产商（如不同）的名称或来源； 2.依据的质量标准和检验操作规程； 3.检验所用的仪器或设备"},{"i":224,"n":"第二百二十四条","txt":"质量控制实验室应当建立检验结果超标调查的操作规程。任何检验结果超标都必须按照操作规程进行完整的调查，并有相应的记录。"},{"i":225,"n":"第二百二十五条","txt":"企业按规定保存的、用于药品质量追溯或调查的物料、产品样品为留样。用于产品稳定性考察的样品不属于留样。 留样应当至少符合以下要求： （一）应当按照操作规程对留样进行管理； （二）留样应当能够代表被取样批次的物料或产品； （三）成品的留样： 1.每批药品均应当有留样；如果一批药品分成数次进行包装，则每次包装至少应当保留一件最小市售包装的成品； 2.留样的包装形式应当与药品市售包装形式相同，原料药的留样如无法采用市售包装形式的，可采用模拟包装； 3.每批药品的留样数量一般至少应当能够确保按照注册批准的质量标准完成两次全检（无菌检查和热原检查等除外）； 4.如果不影响留样的包装完整性，保存期间内至少应当每年对留样进行一次目检观察，如有异常，应当进行彻底调查并采取相应的处理措施； 5.留样观察应当有记录； 6.留样应当按照注册批准的贮存条件至少保存至药品有效期后一年； 7.如企业终止药品生产或关"},{"i":226,"n":"第二百二十六条","txt":"试剂、试液、培养基和检定菌的管理应当至少符合以下要求： （一）试剂和培养基应当从可靠的供应商处采购，必要时应当对供应商进行评估； （二）应当有接收试剂、试液、培养基的记录，必要时，应当在试剂、试液、培养基的容器上标注接收日期； （三）应当按照相关规定或使用说明配制、贮存和使用试剂、试液和培养基。特殊情况下，在接收或使用前，还应当对试剂进行鉴别或其他检验； （四）试液和已配制的培养基应当标注配制批号、配制日期和配制人员姓名，并有配制（包括灭菌）记录。不稳定的试剂、试液和培养基应当标注有效期及特殊贮存条件。标准液、滴定液还应当标注最后一次标化的日期和校正因子，并有标化记录； （五）配制的培养基应当进行适用性检查，并有相关记录。应当有培养基使用记录； （六）应当有检验所需的各种检定菌，并建立检定菌保存、传代、使用、销毁的操作规程和相应记录； （七）检定菌应当有适当的标识，内容至少包括菌种名称"},{"i":227,"n":"第二百二十七条","txt":"标准品或对照品的管理应当至少符合以下要求： （一）标准品或对照品应当按照规定贮存和使用； （二）标准品或对照品应当有适当的标识，内容至少包括名称、批号、制备日期（如有）、有效期（如有）、首次开启日期、含量或效价、贮存条件； （三）企业如需自制工作标准品或对照品，应当建立工作标准品或对照品的质量标准以及制备、鉴别、检验、批准和贮存的操作规程，每批工作标准品或对照品应当用法定标准品或对照品进行标化，并确定有效期，还应当通过定期标化证明工作标准品或对照品的效价或含量在有效期内保持稳定。标化的过程和结果应当有相应的记录。"},{"i":228,"n":"第二百二十八条","txt":"应当分别建立物料和产品批准放行的操作规程，明确批准放行的标准、职责，并有相应的记录。"},{"i":229,"n":"第二百二十九条","txt":"物料的放行应当至少符合以下要求： （一）物料的质量评价内容应当至少包括生产商的检验报告、物料包装完整性和密封性的检查情况和检验结果； （二）物料的质量评价应当有明确的结论，如批准放行、不合格或其他决定； （三）物料应当由指定人员签名批准放行。"},{"i":230,"n":"第二百三十条","txt":"产品的放行应当至少符合以下要求： （一）在批准放行前，应当对每批药品进行质量评价，保证药品及其生产应当符合注册和本规范要求，并确认以下各项内容： 1.主要生产工艺和检验方法经过验证； 2.已完成所有必需的检查、检验，并综合考虑实际生产条件和生产记录； 3.所有必需的生产和质量控制均已完成并经相关主管人员签名； 4.变更已按照相关规程处理完毕，需要经药品监督管理部门批准的变更已得到批准； 5.对变更或偏差已完成所有必要的取样、检查、检验和审核； 6.所有与该批产品有关的偏差均已有明确的解释或说明，或者已经过彻底调查和适当处理；如偏差还涉及其他批次产品，应当一并处理。 （二）药品的质量评价应当有明确的结论，如批准放行、不合格或其他决定； （三）每批药品均应当由质量受权人签名批准放行； （四）疫苗类制品、血液制品、用于血源筛查的体外诊断试剂以及国家食品药品监督管理局规定的其他生物制品放行前还"},{"i":231,"n":"第二百三十一条","txt":"持续稳定性考察的目的是在有效期内监控已上市药品的质量，以发现药品与生产相关的稳定性问题（如杂质含量或溶出度特性的变化），并确定药品能够在标示的贮存条件下，符合质量标准的各项要求。"},{"i":232,"n":"第二百三十二条","txt":"持续稳定性考察主要针对市售包装药品，但也需兼顾待包装产品。例如，当待包装产品在完成包装前，或从生产厂运输到包装厂，还需要长期贮存时，应当在相应的环境条件下，评估其对包装后产品稳定性的影响。此外，还应当考虑对贮存时间较长的中间产品进行考察。"},{"i":233,"n":"第二百三十三条","txt":"持续稳定性考察应当有考察方案，结果应当有报告。用于持续稳定性考察的设备（尤其是稳定性试验设备或设施）应当按照第七章和第五章的要求进行确认和维护。"},{"i":234,"n":"第二百三十四条","txt":"持续稳定性考察的时间应当涵盖药品有效期，考察方案应当至少包括以下内容： （一）每种规格、每个生产批量药品的考察批次数； （二）相关的物理、化学、微生物和生物学检验方法，可考虑采用稳定性考察专属的检验方法； （三）检验方法依据； （四）合格标准； （五）容器密封系统的描述； （六）试验间隔时间（测试时间点）； （七）贮存条件（应当采用与药品标示贮存条件相对应的《中华人民共和国药典》规定的长期稳定性试验标准条件）； （八）检验项目，如检验项目少于成品质量标准所包含的项目，应当说明理由。"},{"i":235,"n":"第二百三十五条","txt":"考察批次数和检验频次应当能够获得足够的数据，以供趋势分析。通常情况下，每种规格、每种内包装形式的药品，至少每年应当考察一个批次，除非当年没有生产。"},{"i":236,"n":"第二百三十六条","txt":"某些情况下，持续稳定性考察中应当额外增加批次数，如重大变更或生产和包装有重大偏差的药品应当列入稳定性考察。此外，重新加工、返工或回收的批次，也应当考虑列入考察，除非已经过验证和稳定性考察。"},{"i":237,"n":"第二百三十七条","txt":"关键人员，尤其是质量受权人，应当了解持续稳定性考察的结果。当持续稳定性考察不在待包装产品和成品的生产企业进行时，则相关各方之间应当有书面协议，且均应当保存持续稳定性考察的结果以供药品监督管理部门审查。"},{"i":238,"n":"第二百三十八条","txt":"应当对不符合质量标准的结果或重要的异常趋势进行调查。对任何已确认的不符合质量标准的结果或重大不良趋势，企业都应当考虑是否可能对已上市药品造成影响，必要时应当实施召回，调查结果以及采取的措施应当报告当地药品监督管理部门。"},{"i":239,"n":"第二百三十九条","txt":"应当根据所获得的全部数据资料，包括考察的阶段性结论，撰写总结报告并保存。应当定期审核总结报告。"},{"i":240,"n":"第二百四十条","txt":"企业应当建立变更控制系统，对所有影响产品质量的变更进行评估和管理。需要经药品监督管理部门批准的变更应当在得到批准后方可实施。"},{"i":241,"n":"第二百四十一条","txt":"应当建立操作规程，规定原辅料、包装材料、质量标准、检验方法、操作规程、厂房、设施、设备、仪器、生产工艺和计算机软件变更的申请、评估、审核、批准和实施。质量管理部门应当指定专人负责变更控制。"},{"i":242,"n":"第二百四十二条","txt":"变更都应当评估其对产品质量的潜在影响。企业可以根据变更的性质、范围、对产品质量潜在影响的程度将变更分类（如主要、次要变更）。判断变更所需的验证、额外的检验以及稳定性考察应当有科学依据。"},{"i":243,"n":"第二百四十三条","txt":"与产品质量有关的变更由申请部门提出后，应当经评估、制定实施计划并明确实施职责，最终由质量管理部门审核批准。变更实施应当有相应的完整记录。"},{"i":244,"n":"第二百四十四条","txt":"改变原辅料、与药品直接接触的包装材料、生产工艺、主要生产设备以及其他影响药品质量的主要因素时，还应当对变更实施后最初至少三个批次的药品质量进行评估。如果变更可能影响药品的有效期，则质量评估还应当包括对变更实施后生产的药品进行稳定性考察。"},{"i":245,"n":"第二百四十五条","txt":"变更实施时，应当确保与变更相关的文件均已修订。"},{"i":246,"n":"第二百四十六条","txt":"质量管理部门应当保存所有变更的文件和记录。"},{"i":247,"n":"第二百四十七条","txt":"各部门负责人应当确保所有人员正确执行生产工艺、质量标准、检验方法和操作规程，防止偏差的产生。"},{"i":248,"n":"第二百四十八条","txt":"企业应当建立偏差处理的操作规程，规定偏差的报告、记录、调查、处理以及所采取的纠正措施，并有相应的记录。"},{"i":249,"n":"第二百四十九条","txt":"任何偏差都应当评估其对产品质量的潜在影响。企业可以根据偏差的性质、范围、对产品质量潜在影响的程度将偏差分类（如重大、次要偏差），对重大偏差的评估还应当考虑是否需要对产品进行额外的检验以及对产品有效期的影响，必要时，应当对涉及重大偏差的产品进行稳定性考察。"},{"i":250,"n":"第二百五十条","txt":"任何偏离生产工艺、物料平衡限度、质量标准、检验方法、操作规程等的情况均应当有记录，并立即报告主管人员及质量管理部门，应当有清楚的说明，重大偏差应当由质量管理部门会同其他部门进行彻底调查，并有调查报告。偏差调查报告应当由质量管理部门的指定人员审核并签字。 企业还应当采取预防措施有效防止类似偏差的再次发生。"},{"i":251,"n":"第二百五十一条","txt":"质量管理部门应当负责偏差的分类，保存偏差调查、处理的文件和记录。"},{"i":252,"n":"第二百五十二条","txt":"企业应当建立纠正措施和预防措施系统，对投诉、召回、偏差、自检或外部检查结果、工艺性能和质量监测趋势等进行调查并采取纠正和预防措施。调查的深度和形式应当与风险的级别相适应。纠正措施和预防措施系统应当能够增进对产品和工艺的理解，改进产品和工艺。"},{"i":253,"n":"第二百五十三条","txt":"企业应当建立实施纠正和预防措施的操作规程，内容至少包括： （一）对投诉、召回、偏差、自检或外部检查结果、工艺性能和质量监测趋势以及其他来源的质量数据进行分析，确定已有和潜在的质量问题。必要时，应当采用适当的统计学方法； （二）调查与产品、工艺和质量保证系统有关的原因； （三）确定所需采取的纠正和预防措施，防止问题的再次发生； （四）评估纠正和预防措施的合理性、有效性和充分性； （五）对实施纠正和预防措施过程中所有发生的变更应当予以记录； （六）确保相关信息已传递到质量受权人和预防问题再次发生的直接负责人； （七）确保相关信息及其纠正和预防措施已通过高层管理人员的评审。"},{"i":254,"n":"第二百五十四条","txt":"实施纠正和预防措施应当有文件记录，并由质量管理部门保存。"},{"i":255,"n":"第二百五十五条","txt":"质量管理部门应当对所有生产用物料的供应商进行质量评估，会同有关部门对主要物料供应商（尤其是生产商）的质量体系进行现场质量审计，并对质量评估不符合要求的供应商行使否决权。 主要物料的确定应当综合考虑企业所生产的药品质量风险、物料用量以及物料对药品质量的影响程度等因素。 企业法定代表人、企业负责人及其他部门的人员不得干扰或妨碍质量管理部门对物料供应商独立作出质量评估。"},{"i":256,"n":"第二百五十六条","txt":"应当建立物料供应商评估和批准的操作规程，明确供应商的资质、选择的原则、质量评估方式、评估标准、物料供应商批准的程序。 如质量评估需采用现场质量审计方式的，还应当明确审计内容、周期、审计人员的组成及资质。需采用样品小批量试生产的，还应当明确生产批量、生产工艺、产品质量标准、稳定性考察方案。"},{"i":257,"n":"第二百五十七条","txt":"质量管理部门应当指定专人负责物料供应商质量评估和现场质量审计，分发经批准的合格供应商名单。被指定的人员应当具有相关的法规和专业知识，具有足够的质量评估和现场质量审计的实践经验。"},{"i":258,"n":"第二百五十八条","txt":"现场质量审计应当核实供应商资质证明文件和检验报告的真实性，核实是否具备检验条件。应当对其人员机构、厂房设施和设备、物料管理、生产工艺流程和生产管理、质量控制实验室的设备、仪器、文件管理等进行检查，以全面评估其质量保证系统。现场质量审计应当有报告。"},{"i":259,"n":"第二百五十九条","txt":"必要时，应当对主要物料供应商提供的样品进行小批量试生产，并对试生产的药品进行稳定性考察。"},{"i":260,"n":"第二百六十条","txt":"质量管理部门对物料供应商的评估至少应当包括：供应商的资质证明文件、质量标准、检验报告、企业对物料样品的检验数据和报告。如进行现场质量审计和样品小批量试生产的，还应当包括现场质量审计报告，以及小试产品的质量检验报告和稳定性考察报告。"},{"i":261,"n":"第二百六十一条","txt":"改变物料供应商，应当对新的供应商进行质量评估；改变主要物料供应商的，还需要对产品进行相关的验证及稳定性考察。"},{"i":262,"n":"第二百六十二条","txt":"质量管理部门应当向物料管理部门分发经批准的合格供应商名单，该名单内容至少包括物料名称、规格、质量标准、生产商名称和地址、经销商（如有）名称等，并及时更新。"},{"i":263,"n":"第二百六十三条","txt":"质量管理部门应当与主要物料供应商签订质量协议，在协议中应当明确双方所承担的质量责任。"},{"i":264,"n":"第二百六十四条","txt":"质量管理部门应当定期对物料供应商进行评估或现场质量审计，回顾分析物料质量检验结果、质量投诉和不合格处理记录。如物料出现质量问题或生产条件、工艺、质量标准和检验方法等可能影响质量的关键因素发生重大改变时，还应当尽快进行相关的现场质量审计。"},{"i":265,"n":"第二百六十五条","txt":"企业应当对每家物料供应商建立质量档案，档案内容应当包括供应商的资质证明文件、质量协议、质量标准、样品检验数据和报告、供应商的检验报告、现场质量审计报告、产品稳定性考察报告、定期的质量回顾分析报告等。"},{"i":266,"n":"第二百六十六条","txt":"应当按照操作规程，每年对所有生产的药品按品种进行产品质量回顾分析，以确认工艺稳定可靠，以及原辅料、成品现行质量标准的适用性，及时发现不良趋势，确定产品及工艺改进的方向。应当考虑以往回顾分析的历史数据，还应当对产品质量回顾分析的有效性进行自检。 当有合理的科学依据时，可按照产品的剂型分类进行质量回顾，如固体制剂、液体制剂和无菌制剂等。 回顾分析应当有报告。 企业至少应当对下列情形进行回顾分析： （一）产品所用原辅料的所有变更，尤其是来自新供应商的原辅料； （二）关键中间控制点及成品的检验结果； （三）所有不符合质量标准的批次及其调查； （四）所有重大偏差及相关的调查、所采取的整改措施和预防措施的有效性； （五）生产工艺或检验方法等的所有变更； （六）已批准或备案的药品注册所有变更； （七）稳定性考察的结果及任何不良趋势； （八）所有因质量原因造成的退货、投诉、召回及调查； （九）与产品工"},{"i":267,"n":"第二百六十七条","txt":"应当对回顾分析的结果进行评估，提出是否需要采取纠正和预防措施或进行再确认或再验证的评估意见及理由，并及时、有效地完成整改。"},{"i":268,"n":"第二百六十八条","txt":"药品委托生产时，委托方和受托方之间应当有书面的技术协议，规定产品质量回顾分析中各方的责任，确保产品质量回顾分析按时进行并符合要求。"},{"i":269,"n":"第二百六十九条","txt":"应当建立药品不良反应报告和监测管理制度，设立专门机构并配备专职人员负责管理。"},{"i":270,"n":"第二百七十条","txt":"应当主动收集药品不良反应，对不良反应应当详细记录、评价、调查和处理，及时采取措施控制可能存在的风险，并按照要求向药品监督管理部门报告。"},{"i":271,"n":"第二百七十一条","txt":"应当建立操作规程，规定投诉登记、评价、调查和处理的程序，并规定因可能的产品缺陷发生投诉时所采取的措施，包括考虑是否有必要从市场召回药品。"},{"i":272,"n":"第二百七十二条","txt":"应当有专人及足够的辅助人员负责进行质量投诉的调查和处理，所有投诉、调查的信息应当向质量受权人通报。"},{"i":273,"n":"第二百七十三条","txt":"所有投诉都应当登记与审核，与产品质量缺陷有关的投诉，应当详细记录投诉的各个细节，并进行调查。"},{"i":274,"n":"第二百七十四条","txt":"发现或怀疑某批药品存在缺陷，应当考虑检查其他批次的药品，查明其是否受到影响。"},{"i":275,"n":"第二百七十五条","txt":"投诉调查和处理应当有记录，并注明所查相关批次产品的信息。"},{"i":276,"n":"第二百七十六条","txt":"应当定期回顾分析投诉记录，以便发现需要警觉、重复出现以及可能需要从市场召回药品的问题，并采取相应措施。"},{"i":277,"n":"第二百七十七条","txt":"企业出现生产失误、药品变质或其他重大质量问题，应当及时采取相应措施，必要时还应当向当地药品监督管理部门报告。"},{"i":278,"n":"第二百七十八条","txt":"为确保委托生产产品的质量和委托检验的准确性和可靠性，委托方和受托方必须签订书面合同，明确规定各方责任、委托生产或委托检验的内容及相关的技术事项。"},{"i":279,"n":"第二百七十九条","txt":"委托生产或委托检验的所有活动，包括在技术或其他方面拟采取的任何变更，均应当符合药品生产许可和注册的有关要求。"},{"i":280,"n":"第二百八十条","txt":"委托方应当对受托方进行评估，对受托方的条件、技术水平、质量管理情况进行现场考核，确认其具有完成受托工作的能力，并能保证符合本规范的要求。"},{"i":281,"n":"第二百八十一条","txt":"委托方应当向受托方提供所有必要的资料，以使受托方能够按照药品注册和其他法定要求正确实施所委托的操作。 委托方应当使受托方充分了解与产品或操作相关的各种问题，包括产品或操作对受托方的环境、厂房、设备、人员及其他物料或产品可能造成的危害。"},{"i":282,"n":"第二百八十二条","txt":"委托方应当对受托生产或检验的全过程进行监督。"},{"i":283,"n":"第二百八十三条","txt":"委托方应当确保物料和产品符合相应的质量标准。"},{"i":284,"n":"第二百八十四条","txt":"受托方必须具备足够的厂房、设备、知识和经验以及人员，满足委托方所委托的生产或检验工作的要求。"},{"i":285,"n":"第二百八十五条","txt":"受托方应当确保所收到委托方提供的物料、中间产品和待包装产品适用于预定用途。"},{"i":286,"n":"第二百八十六条","txt":"受托方不得从事对委托生产或检验的产品质量有不利影响的活动。"},{"i":287,"n":"第二百八十七条","txt":"委托方与受托方之间签订的合同应当详细规定各自的产品生产和控制职责，其中的技术性条款应当由具有制药技术、检验专业知识和熟悉本规范的主管人员拟订。委托生产及检验的各项工作必须符合药品生产许可和药品注册的有关要求并经双方同意。"},{"i":288,"n":"第二百八十八条","txt":"合同应当详细规定质量受权人批准放行每批药品的程序，确保每批产品都已按照药品注册的要求完成生产和检验。"},{"i":289,"n":"第二百八十九条","txt":"合同应当规定何方负责物料的采购、检验、放行、生产和质量控制（包括中间控制），还应当规定何方负责取样和检验。 在委托检验的情况下，合同应当规定受托方是否在委托方的厂房内取样。"},{"i":290,"n":"第二百九十条","txt":"合同应当规定由受托方保存的生产、检验和发运记录及样品，委托方应当能够随时调阅或检查；出现投诉、怀疑产品有质量缺陷或召回时，委托方应当能够方便地查阅所有与评价产品质量相关的记录。"},{"i":291,"n":"第二百九十一条","txt":"合同应当明确规定委托方可以对受托方进行检查或现场质量审计。"},{"i":292,"n":"第二百九十二条","txt":"委托检验合同应当明确受托方有义务接受药品监督管理部门检查。"},{"i":293,"n":"第二百九十三条","txt":"企业应当建立产品召回系统，必要时可迅速、有效地从市场召回任何一批存在安全隐患的产品。"},{"i":294,"n":"第二百九十四条","txt":"因质量原因退货和召回的产品，均应当按照规定监督销毁，有证据证明退货产品质量未受影响的除外。"},{"i":295,"n":"第二百九十五条","txt":"每批产品均应当有发运记录。根据发运记录，应当能够追查每批产品的销售情况，必要时应当能够及时全部追回，发运记录内容应当包括：产品名称、规格、批号、数量、收货单位和地址、联系方式、发货日期、运输方式等。"},{"i":296,"n":"第二百九十六条","txt":"药品发运的零头包装只限两个批号为一个合箱，合箱外应当标明全部批号，并建立合箱记录。"},{"i":297,"n":"第二百九十七条","txt":"发运记录应当至少保存至药品有效期后一年。"},{"i":298,"n":"第二百九十八条","txt":"应当制定召回操作规程，确保召回工作的有效性。"},{"i":299,"n":"第二百九十九条","txt":"应当指定专人负责组织协调召回工作，并配备足够数量的人员。产品召回负责人应当独立于销售和市场部门；如产品召回负责人不是质量受权人，则应当向质量受权人通报召回处理情况。"},{"i":300,"n":"第三百条","txt":"召回应当能够随时启动，并迅速实施。"},{"i":301,"n":"第三百零一条","txt":"因产品存在安全隐患决定从市场召回的，应当立即向当地药品监督管理部门报告。"},{"i":302,"n":"第三百零二条","txt":"产品召回负责人应当能够迅速查阅到药品发运记录。"},{"i":303,"n":"第三百零三条","txt":"已召回的产品应当有标识，并单独、妥善贮存，等待最终处理决定。"},{"i":304,"n":"第三百零四条","txt":"召回的进展过程应当有记录，并有最终报告。产品发运数量、已召回数量以及数量平衡情况应当在报告中予以说明。"},{"i":305,"n":"第三百零五条","txt":"应当定期对产品召回系统的有效性进行评估。"},{"i":306,"n":"第三百零六条","txt":"质量管理部门应当定期组织对企业进行自检，监控本规范的实施情况，评估企业是否符合本规范要求，并提出必要的纠正和预防措施。"},{"i":307,"n":"第三百零七条","txt":"自检应当有计划，对机构与人员、厂房与设施、设备、物料与产品、确认与验证、文件管理、生产管理、质量控制与质量保证、委托生产与委托检验、产品发运与召回等项目定期进行检查。"},{"i":308,"n":"第三百零八条","txt":"应当由企业指定人员进行独立、系统、全面的自检，也可由外部人员或专家进行独立的质量审计。"},{"i":309,"n":"第三百零九条","txt":"自检应当有记录。自检完成后应当有自检报告，内容至少包括自检过程中观察到的所有情况、评价的结论以及提出纠正和预防措施的建议。自检情况应当报告企业高层管理人员。"},{"i":310,"n":"第三百一十条","txt":"本规范为药品生产质量管理的基本要求。对无菌药品、生物制品、血液制品等药品或生产质量管理活动的特殊要求，由国家食品药品监督管理局以附录方式另行制定。"},{"i":311,"n":"第三百一十一条","txt":"企业可以采用经过验证的替代方法，达到本规范的要求。"},{"i":312,"n":"第三百一十二条","txt":"本规范下列术语（按汉语拼音排序）的含义是： （一）包装 待包装产品变成成品所需的所有操作步骤，包括分装、贴签等。但无菌生产工艺中产品的无菌灌装，以及最终灭菌产品的灌装等不视为包装。 （二）包装材料 药品包装所用的材料，包括与药品直接接触的包装材料和容器、印刷包装材料，但不包括发运用的外包装材料。 （三）操作规程 经批准用来指导设备操作、维护与清洁、验证、环境控制、取样和检验等药品生产活动的通用性文件，也称标准操作规程。 （四）产品 包括药品的中间产品、待包装产品和成品。 （五）产品生命周期 产品从最初的研发、上市直至退市的所有阶段。 （六）成品 已完成所有生产操作步骤和最终包装的产品。 （七）重新加工 将某一生产工序生产的不符合质量标准的一批中间产品或待包装产品的一部分或全部，采用不同的生产工艺进行再加工，以符合预定的质量标准。 （八）待包装产品 尚未进行包装但已完成所有其他加工工序的"},{"i":313,"n":"第三百一十三条","txt":"本规范自2011年3月1日起施行。按照《中华人民共和国药品管理法》第九条规定，具体实施办法和实施步骤由国家食品药品监督管理局规定。"}],"yaopinleiyizhiduhuaxuepinguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强药品类易制毒化学品管理，防止流入非法渠道，根据《易制毒化学品管理条例》（以下简称《条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"药品类易制毒化学品是指《条例》中所确定的麦角酸、麻黄素等物质，品种目录见本办法附件1。 国务院批准调整易制毒化学品分类和品种，涉及药品类易制毒化学品的，国家食品药品监督管理局应当及时调整并予公布。"},{"i":3,"n":"第三条","txt":"药品类易制毒化学品的生产、经营、购买以及监督管理，适用本办法。"},{"i":4,"n":"第四条","txt":"国家食品药品监督管理局主管全国药品类易制毒化学品生产、经营、购买等方面的监督管理工作。 县级以上地方食品药品监督管理部门负责本行政区域内的药品类易制毒化学品生产、经营、购买等方面的监督管理工作。"},{"i":5,"n":"第五条","txt":"生产、经营药品类易制毒化学品，应当依照《条例》和本办法的规定取得药品类易制毒化学品生产、经营许可。 生产药品类易制毒化学品中属于药品的品种，还应当依照《药品管理法》和相关规定取得药品批准文号。"},{"i":6,"n":"第六条","txt":"药品生产企业申请生产药品类易制毒化学品，应当符合《条例》第七条规定的条件，向所在地省、自治区、直辖市食品药品监督管理部门提出申请，报送以下资料： （一）药品类易制毒化学品生产申请表（见附件2）； （二）《药品生产许可证》、《药品生产质量管理规范》认证证书和企业营业执照复印件； （三）企业药品类易制毒化学品管理的组织机构图（注明各部门职责及相互关系、部门负责人）； （四）反映企业现有状况的周边环境图、总平面布置图、仓储平面布置图、质量检验场所平面布置图、药品类易制毒化学品生产场所平面布置图（注明药品类易制毒化学品相应安全管理设施）； （五）药品类易制毒化学品安全管理制度文件目录； （六）重点区域设置电视监控设施的说明以及与公安机关联网报警的证明； （七）企业法定代表人、企业负责人和技术、管理人员具有药品类易制毒化学品有关知识的说明材料； （八）企业法定代表人及相关工作人员无毒品犯罪记录的"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市食品药品监督管理部门应当在收到申请之日起5日内，对申报资料进行形式审查，决定是否受理。受理的，在30日内完成现场检查，将检查结果连同企业申报资料报送国家食品药品监督管理局。国家食品药品监督管理局应当在30日内完成实质性审查，对符合规定的，发给《药品类易制毒化学品生产许可批件》（以下简称《生产许可批件》，见附件3），注明许可生产的药品类易制毒化学品名称；不予许可的，应当书面说明理由。"},{"i":8,"n":"第八条","txt":"药品生产企业收到《生产许可批件》后，应当向所在地省、自治区、直辖市食品药品监督管理部门提出变更《药品生产许可证》生产范围的申请。省、自治区、直辖市食品药品监督管理部门应当根据《生产许可批件》，在《药品生产许可证》正本的生产范围中标注“药品类易制毒化学品”；在副本的生产范围中标注“药品类易制毒化学品”后，括弧内标注药品类易制毒化学品名称。"},{"i":9,"n":"第九条","txt":"药品类易制毒化学品生产企业申请换发《药品生产许可证》的，省、自治区、直辖市食品药品监督管理部门除按照《药品生产监督管理办法》审查外，还应当对企业的药品类易制毒化学品生产条件和安全管理情况进行审查。对符合规定的，在换发的《药品生产许可证》中继续标注药品类易制毒化学品生产范围和品种名称；对不符合规定的，报国家食品药品监督管理局。 国家食品药品监督管理局收到省、自治区、直辖市食品药品监督管理部门报告后，对不符合规定的企业注销其《生产许可批件》，并通知企业所在地省、自治区、直辖市食品药品监督管理部门注销该企业《药品生产许可证》中的药品类易制毒化学品生产范围。"},{"i":10,"n":"第十条","txt":"药品类易制毒化学品生产企业不再生产药品类易制毒化学品的，应当在停止生产经营后3个月内办理注销相关许可手续。 药品类易制毒化学品生产企业连续1年未生产的，应当书面报告所在地省、自治区、直辖市食品药品监督管理部门；需要恢复生产的，应当经所在地省、自治区、直辖市食品药品监督管理部门对企业的生产条件和安全管理情况进行现场检查。"},{"i":11,"n":"第十一条","txt":"药品类易制毒化学品生产企业变更生产地址、品种范围的，应当重新申办《生产许可批件》。 药品类易制毒化学品生产企业变更企业名称、法定代表人的，由所在地省、自治区、直辖市食品药品监督管理部门办理《药品生产许可证》变更手续，报国家食品药品监督管理局备案。"},{"i":12,"n":"第十二条","txt":"药品类易制毒化学品以及含有药品类易制毒化学品的制剂不得委托生产。 药品生产企业不得接受境外厂商委托加工药品类易制毒化学品以及含有药品类易制毒化学品的产品；特殊情况需要委托加工的，须经国家食品药品监督管理局批准。"},{"i":13,"n":"第十三条","txt":"药品类易制毒化学品的经营许可，国家食品药品监督管理局委托省、自治区、直辖市食品药品监督管理部门办理。 药品类易制毒化学品单方制剂和小包装麻黄素，纳入麻醉药品销售渠道经营，仅能由麻醉药品全国性批发企业和区域性批发企业经销，不得零售。 未实行药品批准文号管理的品种，纳入药品类易制毒化学品原料药渠道经营。"},{"i":14,"n":"第十四条","txt":"药品经营企业申请经营药品类易制毒化学品原料药，应当符合《条例》第九条规定的条件，向所在地省、自治区、直辖市食品药品监督管理部门提出申请，报送以下资料： （一）药品类易制毒化学品原料药经营申请表（见附件4）； （二）具有麻醉药品和第一类精神药品定点经营资格或者第二类精神药品定点经营资格的《药品经营许可证》、《药品经营质量管理规范》认证证书和企业营业执照复印件； （三）企业药品类易制毒化学品管理的组织机构图（注明各部门职责及相互关系、部门负责人）； （四）反映企业现有状况的周边环境图、总平面布置图、仓储平面布置图（注明药品类易制毒化学品相应安全管理设施）； （五）药品类易制毒化学品安全管理制度文件目录； （六）重点区域设置电视监控设施的说明以及与公安机关联网报警的证明； （七）企业法定代表人、企业负责人和销售、管理人员具有药品类易制毒化学品有关知识的说明材料； （八）企业法定代表人及相关工"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市食品药品监督管理部门应当在收到申请之日起5日内，对申报资料进行形式审查，决定是否受理。受理的，在30日内完成现场检查和实质性审查，对符合规定的，在《药品经营许可证》经营范围中标注“药品类易制毒化学品”，并报国家食品药品监督管理局备案；不予许可的，应当书面说明理由。"},{"i":16,"n":"第十六条","txt":"国家对药品类易制毒化学品实行购买许可制度。购买药品类易制毒化学品的，应当办理《药品类易制毒化学品购用证明》（以下简称《购用证明》），但本办法第二十一条规定的情形除外。 《购用证明》由国家食品药品监督管理局统一印制（样式见附件5），有效期为3个月。"},{"i":17,"n":"第十七条","txt":"《购用证明》申请范围： （一）经批准使用药品类易制毒化学品用于药品生产的药品生产企业； （二）使用药品类易制毒化学品的教学、科研单位； （三）具有药品类易制毒化学品经营资格的药品经营企业； （四）取得药品类易制毒化学品出口许可的外贸出口企业； （五）经农业部会同国家食品药品监督管理局下达兽用盐酸麻黄素注射液生产计划的兽药生产企业。 药品类易制毒化学品生产企业自用药品类易制毒化学品原料药用于药品生产的，也应当按照本办法规定办理《购用证明》。"},{"i":18,"n":"第十八条","txt":"购买药品类易制毒化学品应当符合《条例》第十四条规定，向所在地省、自治区、直辖市食品药品监督管理部门或者省、自治区食品药品监督管理部门确定并公布的设区的市级食品药品监督管理部门提出申请，填报购买药品类易制毒化学品申请表（见附件6），提交相应资料（见附件7）。"},{"i":19,"n":"第十九条","txt":"设区的市级食品药品监督管理部门应当在收到申请之日起5日内，对申报资料进行形式审查，决定是否受理。受理的，必要时组织现场检查，5日内将检查结果连同企业申报资料报送省、自治区食品药品监督管理部门。省、自治区食品药品监督管理部门应当在5日内完成审查，对符合规定的，发给《购用证明》；不予许可的，应当书面说明理由。 省、自治区、直辖市食品药品监督管理部门直接受理的，应当在收到申请之日起10日内完成审查和必要的现场检查，对符合规定的，发给《购用证明》；不予许可的，应当书面说明理由。 省、自治区、直辖市食品药品监督管理部门在批准发给《购用证明》之前，应当请公安机关协助核查相关内容；公安机关核查所用的时间不计算在上述期限之内。"},{"i":20,"n":"第二十条","txt":"《购用证明》只能在有效期内一次使用。《购用证明》不得转借、转让。购买药品类易制毒化学品时必须使用《购用证明》原件，不得使用复印件、传真件。"},{"i":21,"n":"第二十一条","txt":"符合以下情形之一的，豁免办理《购用证明》： （一）医疗机构凭麻醉药品、第一类精神药品购用印鉴卡购买药品类易制毒化学品单方制剂和小包装麻黄素的； （二）麻醉药品全国性批发企业、区域性批发企业持麻醉药品调拨单购买小包装麻黄素以及单次购买麻黄素片剂6万片以下、注射剂l.5万支以下的； （三）按规定购买药品类易制毒化学品标准品、对照品的； （四）药品类易制毒化学品生产企业凭药品类易制毒化学品出口许可自营出口药品类易制毒化学品的。"},{"i":22,"n":"第二十二条","txt":"药品类易制毒化学品生产企业应当将药品类易制毒化学品原料药销售给取得《购用证明》的药品生产企业、药品经营企业和外贸出口企业。"},{"i":23,"n":"第二十三条","txt":"药品类易制毒化学品经营企业应当将药品类易制毒化学品原料药销售给本省、自治区、直辖市行政区域内取得《购用证明》的单位。药品类易制毒化学品经营企业之间不得购销药品类易制毒化学品原料药。"},{"i":24,"n":"第二十四条","txt":"教学科研单位只能凭《购用证明》从麻醉药品全国性批发企业、区域性批发企业和药品类易制毒化学品经营企业购买药品类易制毒化学品。"},{"i":25,"n":"第二十五条","txt":"药品类易制毒化学品生产企业应当将药品类易制毒化学品单方制剂和小包装麻黄素销售给麻醉药品全国性批发企业。麻醉药品全国性批发企业、区域性批发企业应当按照《麻醉药品和精神药品管理条例》第三章规定的渠道销售药品类易制毒化学品单方制剂和小包装麻黄素。麻醉药品区域性批发企业之间不得购销药品类易制毒化学品单方制剂和小包装麻黄素。 麻醉药品区域性批发企业之间因医疗急需等特殊情况需要调剂药品类易制毒化学品单方制剂的，应当在调剂后2日内将调剂情况分别报所在地省、自治区、直辖市食品药品监督管理部门备案。"},{"i":26,"n":"第二十六条","txt":"药品类易制毒化学品禁止使用现金或者实物进行交易。"},{"i":27,"n":"第二十七条","txt":"药品类易制毒化学品生产企业、经营企业销售药品类易制毒化学品，应当逐一建立购买方档案。 购买方为非医疗机构的，档案内容至少包括： （一）购买方《药品生产许可证》、《药品经营许可证》、企业营业执照等资质证明文件复印件； （二）购买方企业法定代表人、主管药品类易制毒化学品负责人、采购人员姓名及其联系方式； （三）法定代表人授权委托书原件及采购人员身份证明文件复印件； （四）《购用证明》或者麻醉药品调拨单原件； （五）销售记录及核查情况记录。 购买方为医疗机构的，档案应当包括医疗机构麻醉药品、第一类精神药品购用印鉴卡复印件和销售记录。"},{"i":28,"n":"第二十八条","txt":"药品类易制毒化学品生产企业、经营企业销售药品类易制毒化学品时，应当核查采购人员身份证明和相关购买许可证明，无误后方可销售，并保存核查记录。 发货应当严格执行出库复核制度，认真核对实物与药品销售出库单是否相符，并确保将药品类易制毒化学品送达购买方《药品生产许可证》或者《药品经营许可证》所载明的地址，或者医疗机构的药库。 在核查、发货、送货过程中发现可疑情况的，应当立即停止销售，并向所在地食品药品监督管理部门和公安机关报告。"},{"i":29,"n":"第二十九条","txt":"除药品类易制毒化学品经营企业外，购用单位应当按照《购用证明》载明的用途使用药品类易制毒化学品，不得转售；外贸出口企业购买的药品类易制毒化学品不得内销。 购用单位需要将药品类易制毒化学品退回原供货单位的，应当分别报其所在地和原供货单位所在地省、自治区、直辖市食品药品监督管理部门备案。原供货单位收到退货后，应当分别向其所在地和原购用单位所在地省、自治区、直辖市食品药品监督管理部门报告。"},{"i":30,"n":"第三十条","txt":"药品类易制毒化学品生产企业、经营企业、使用药品类易制毒化学品的药品生产企业和教学科研单位，应当配备保障药品类易制毒化学品安全管理的设施，建立层层落实责任制的药品类易制毒化学品管理制度。"},{"i":31,"n":"第三十一条","txt":"药品类易制毒化学品生产企业、经营企业和使用药品类易制毒化学品的药品生产企业，应当设置专库或者在药品仓库中设立独立的专库（柜）储存药品类易制毒化学品。 麻醉药品全国性批发企业、区域性批发企业可在其麻醉药品和第一类精神药品专库中设专区存放药品类易制毒化学品。 教学科研单位应当设立专柜储存药品类易制毒化学品。 专库应当设有防盗设施，专柜应当使用保险柜；专库和专柜应当实行双人双锁管理。 药品类易制毒化学品生产企业、经营企业和使用药品类易制毒化学品的药品生产企业，其关键生产岗位、储存场所应当设置电视监控设施，安装报警装置并与公安机关联网。"},{"i":32,"n":"第三十二条","txt":"药品类易制毒化学品生产企业、经营企业和使用药品类易制毒化学品的药品生产企业，应当建立药品类易制毒化学品专用账册。专用账册保存期限应当自药品类易制毒化学品有效期期满之日起不少于2年。 药品类易制毒化学品生产企业自营出口药品类易制毒化学品的，必须在专用账册中载明，并留存出口许可及相应证明材料备查。 药品类易制毒化学品入库应当双人验收，出库应当双人复核，做到账物相符。"},{"i":33,"n":"第三十三条","txt":"发生药品类易制毒化学品被盗、被抢、丢失或者其他流入非法渠道情形的，案发单位应当立即报告当地公安机关和县级以上地方食品药品监督管理部门。接到报案的食品药品监督管理部门应当逐级上报，并配合公安机关查处。"},{"i":34,"n":"第三十四条","txt":"县级以上地方食品药品监督管理部门负责本行政区域内药品类易制毒化学品生产企业、经营企业、使用药品类易制毒化学品的药品生产企业和教学科研单位的监督检查。"},{"i":35,"n":"第三十五条","txt":"食品药品监督管理部门应当建立对本行政区域内相关企业的监督检查制度和监督检查档案。监督检查至少应当包括药品类易制毒化学品的安全管理状况、销售流向、使用情况等内容；对企业的监督检查档案应当全面详实，应当有现场检查等情况的记录。每次检查后应当将检查结果以书面形式告知被检查单位；需要整改的应当提出整改内容及整改期限，并实施跟踪检查。"},{"i":36,"n":"第三十六条","txt":"食品药品监督管理部门对药品类易制毒化学品的生产、经营、购买活动进行监督检查时，可以依法查看现场、查阅和复制有关资料、记录有关情况、扣押相关的证据材料和违法物品；必要时，可以临时查封有关场所。 被检查单位及其工作人员应当配合食品药品监督管理部门的监督检查，如实提供有关情况和材料、物品，不得拒绝或者隐匿。"},{"i":37,"n":"第三十七条","txt":"食品药品监督管理部门应当将药品类易制毒化学品许可、依法吊销或者注销许可的情况及时通报有关公安机关和工商行政管理部门。 食品药品监督管理部门收到工商行政管理部门关于药品类易制毒化学品生产企业、经营企业吊销营业执照或者注销登记的情况通报后，应当及时注销相应的药品类易制毒化学品许可。"},{"i":38,"n":"第三十八条","txt":"药品类易制毒化学品生产企业、经营企业应当于每月10日前，向所在地县级食品药品监督管理部门、公安机关及中国麻醉药品协会报送上月药品类易制毒化学品生产、经营和库存情况；每年3月31日前向所在地县级食品药品监督管理部门、公安机关及中国麻醉药品协会报送上年度药品类易制毒化学品生产、经营和库存情况。食品药品监督管理部门应当将汇总情况及时报告上一级食品药品监督管理部门。 药品类易制毒化学品生产企业、经营企业应当按照食品药品监督管理部门制定的药品电子监管实施要求，及时联入药品电子监管网，并通过网络报送药品类易制毒化学品生产、经营和库存情况。"},{"i":39,"n":"第三十九条","txt":"药品类易制毒化学品生产企业、经营企业、使用药品类易制毒化学品的药品生产企业和教学科研单位，对过期、损坏的药品类易制毒化学品应当登记造册，并向所在地县级以上地方食品药品监督管理部门申请销毁。食品药品监督管理部门应当自接到申请之日起5日内到现场监督销毁。"},{"i":40,"n":"第四十条","txt":"有《行政许可法》第六十九条第一款、第二款所列情形的，省、自治区、直辖市食品药品监督管理部门或者国家食品药品监督管理局应当撤销根据本办法作出的有关许可。"},{"i":41,"n":"第四十一条","txt":"药品类易制毒化学品生产企业、经营企业、使用药品类易制毒化学品的药品生产企业、教学科研单位，未按规定执行安全管理制度的，由县级以上食品药品监督管理部门按照《条例》第四十条第一款第一项的规定给予处罚。"},{"i":42,"n":"第四十二条","txt":"药品类易制毒化学品生产企业自营出口药品类易制毒化学品，未按规定在专用账册中载明或者未按规定留存出口许可、相应证明材料备查的，由县级以上食品药品监督管理部门按照《条例》第四十条第一款第四项的规定给予处罚。"},{"i":43,"n":"第四十三条","txt":"有下列情形之一的，由县级以上食品药品监督管理部门给予警告，责令限期改正，可以并处1万元以上3万元以下的罚款： （一）药品类易制毒化学品生产企业连续停产1年以上未按规定报告的，或者未经所在地省、自治区、直辖市食品药品监督管理部门现场检查即恢复生产的； （二）药品类易制毒化学品生产企业、经营企业未按规定渠道购销药品类易制毒化学品的； （三）麻醉药品区域性批发企业因特殊情况调剂药品类易制毒化学品后未按规定备案的； （四）药品类易制毒化学品发生退货，购用单位、供货单位未按规定备案、报告的。"},{"i":44,"n":"第四十四条","txt":"药品类易制毒化学品生产企业、经营企业、使用药品类易制毒化学品的药品生产企业和教学科研单位，拒不接受食品药品监督管理部门监督检查的，由县级以上食品药品监督管理部门按照《条例》第四十二条规定给予处罚。"},{"i":45,"n":"第四十五条","txt":"对于由公安机关、工商行政管理部门按照《条例》第三十八条作出行政处罚决定的单位，食品药品监督管理部门自该行政处罚决定作出之日起3年内不予受理其药品类易制毒化学品生产、经营、购买许可的申请。"},{"i":46,"n":"第四十六条","txt":"食品药品监督管理部门工作人员在药品类易制毒化学品管理工作中有应当许可而不许可、不应当许可而滥许可，以及其他滥用职权、玩忽职守、徇私舞弊行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"申请单位按照本办法的规定申请行政许可事项的，应当对提交资料的真实性负责，提供资料为复印件的，应当加盖申请单位的公章。"},{"i":48,"n":"第四十八条","txt":"本办法所称小包装麻黄素是指国家食品药品监督管理局指定生产的供教学、科研和医疗机构配制制剂使用的特定包装的麻黄素原料药。"},{"i":49,"n":"第四十九条","txt":"对兽药生产企业购用盐酸麻黄素原料药以及兽用盐酸麻黄素注射液生产、经营等监督管理，按照农业部和国家食品药品监督管理局的规定执行。"},{"i":50,"n":"第五十条","txt":"本办法自2010年5月1日起施行。原国家药品监督管理局1999年6月26日发布的《麻黄素管理办法》（试行）同时废止。 附件：1.药品类易制毒化学品品种目录 2.药品类易制毒化学品生产申请表 3.药品类易制毒化学品生产许可批件 4.药品类易制毒化学品原料药经营申请表 5.药品类易制毒化学品购用证明 6.购买药品类易制毒化学品申请表 7.购买药品类易制毒化学品申报资料要求 附件1 药品类易制毒化学品品种目录 1.麦角酸 2.麦角胺 3.麦角新碱 4.麻黄素、伪麻黄素、消旋麻黄素、去甲麻黄素、甲基麻黄素、麻黄浸膏、麻黄浸膏粉等麻黄素类物质 说明： 一、所列物质包括可能存在的盐类。 二、药品类易制毒化学品包括原料药及其单方制剂。 附件2 药品类易制毒化学品生产申请表 附件3 药品类易制毒化学品生产许可批件 受理号：　　　　　　　　　　　　　　　批件号： 国家食品药品监督管理局盖章 年　 月"}],"xuezhanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了确保血液安全，规范血站执业行为，促进血站的建设与发展，根据《献血法》制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称血站是指不以营利为目的，采集、提供临床用血的公益性卫生机构。"},{"i":3,"n":"第三条","txt":"血站分为一般血站和特殊血站。 一般血站包括血液中心、中心血站和中心血库。 特殊血站包括脐带血造血干细胞库和国家卫生计生委根据医学发展需要批准、设置的其他类型血库。"},{"i":4,"n":"第四条","txt":"血液中心、中心血站和中心血库由地方人民政府设立。 血站的建设和发展纳入当地国民经济和社会发展计划。"},{"i":5,"n":"第五条","txt":"国家卫生计生委根据全国医疗资源配置、临床用血需求，制定全国采供血机构设置规划指导原则，并负责全国血站建设规划的指导。 省、自治区、直辖市人民政府卫生计生行政部门应当根据前款规定，结合本行政区域人口、医疗资源、临床用血需求等实际情况和当地区域卫生发展规划，制定本行政区域血站设置规划，报同级人民政府批准，并报国家卫生计生委备案。"},{"i":6,"n":"第六条","txt":"国家卫生计生委主管全国血站的监督管理工作。 县级以上地方人民政府卫生计生行政部门负责本行政区域内血站的监督管理工作。"},{"i":7,"n":"第七条","txt":"鼓励和支持开展血液应用研究和技术创新工作，以及与临床输血有关的科学技术的国际交流与合作。"},{"i":8,"n":"第八条","txt":"血液中心应当设置在直辖市、省会市、自治区首府市。其主要职责是： （一）按照省级人民政府卫生计生行政部门的要求，在规定范围内开展无偿献血者的招募、血液的采集与制备、临床用血供应以及医疗用血的业务指导等工作； （二）承担所在省、自治区、直辖市血站的质量控制与评价； （三）承担所在省、自治区、直辖市血站的业务培训与技术指导； （四）承担所在省、自治区、直辖市血液的集中化检测任务； （五）开展血液相关的科研工作； （六）承担卫生计生行政部门交办的任务。 血液中心应当具有较高综合质量评价的技术能力。"},{"i":9,"n":"第九条","txt":"中心血站应当设置在设区的市。其主要职责是： （一）按照省级人民政府卫生计生行政部门的要求，在规定范围内开展无偿献血者的招募、血液的采集与制备、临床用血供应以及医疗用血的业务指导等工作； （二）承担供血区域范围内血液储存的质量控制； （三）对所在行政区域内的中心血库进行质量控制； （四）承担卫生计生行政部门交办的任务。 直辖市、省会市、自治区首府市已经设置血液中心的，不再设置中心血站；尚未设置血液中心的，可以在已经设置的中心血站基础上加强能力建设，履行血液中心的职责。"},{"i":10,"n":"第十条","txt":"中心血库应当设置在中心血站服务覆盖不到的县级综合医院内。其主要职责是，按照省级人民政府卫生计生行政部门的要求，在规定范围内开展无偿献血者的招募、血液的采集与制备、临床用血供应以及医疗用血业务指导等工作。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市人民政府卫生计生行政部门依据采供血机构设置规划批准设置血站，并报国家卫生计生委备案。 省、自治区、直辖市人民政府卫生计生行政部门负责明确辖区内各级卫生计生行政部门监管责任和血站的职责；根据实际供血距离与能力等情况，负责划定血站采供血服务区域，采供血服务区域可以不受行政区域的限制。 同一行政区域内不得重复设置血液中心、中心血站。 血站与单采血浆站不得在同一县级行政区域内设置。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市人民政府卫生计生行政部门应当统一规划、设置集中化检测实验室，并逐步实施。"},{"i":13,"n":"第十三条","txt":"血站开展采供血活动，应当向所在省、自治区、直辖市人民政府卫生计生行政部门申请办理执业登记，取得《血站执业许可证》。没有取得《血站执业许可证》的，不得开展采供血活动。 《血站执业许可证》有效期为三年。"},{"i":14,"n":"第十四条","txt":"血站申请办理执业登记必须填写《血站执业登记申请书》。 省级人民政府卫生计生行政部门在受理血站执业登记申请后，应当组织有关专家或者委托技术部门，根据《血站质量管理规范》和《血站实验室质量管理规范》，对申请单位进行技术审查，并提交技术审查报告。 省级人民政府卫生计生行政部门应当在接到专家或者技术部门的技术审查报告后二十日内对申请事项进行审核。审核合格的，予以执业登记，发给国家卫生计生委统一样式的《血站执业许可证》及其副本。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不予执业登记： （一）《血站质量管理规范》技术审查不合格的； （二）《血站实验室质量管理规范》技术审查不合格的； （三）血液质量检测结果不合格的。 执业登记机关对审核不合格、不予执业登记的，将结果和理由以书面形式通知申请人。"},{"i":16,"n":"第十六条","txt":"《血站执业许可证》有效期满前三个月，血站应当办理再次执业登记，并提交《血站再次执业登记申请书》及《血站执业许可证》。 省级人民政府卫生计生行政部门应当根据血站业务开展和监督检查情况进行审核，审核合格的，予以继续执业。未通过审核的，责令其限期整改；经整改仍审核不合格的，注销其《血站执业许可证》。 未办理再次执业登记手续或者被注销《血站执业许可证》的血站，不得继续执业。"},{"i":17,"n":"第十七条","txt":"血站因采供血需要，在规定的服务区域内设置分支机构，应当报所在省、自治区、直辖市人民政府卫生计生行政部门批准；设置固定采血点（室）或者流动采血车的，应当报省、自治区、直辖市人民政府卫生计生行政部门备案。 为保证辖区内临床用血需要，血站可以设置储血点储存血液。储血点应当具备必要的储存条件，并由省级卫生计生行政部门批准。"},{"i":18,"n":"第十八条","txt":"根据规划予以撤销的血站，应当在撤销后十五日内向执业登记机关申请办理注销执业登记。逾期不办理的，由执业登记机关依程序予以注销，并收回《血站执业许可证》及其副本和全套印章。"},{"i":19,"n":"第十九条","txt":"血站执业，应当遵守有关法律、行政法规、规章和技术规范。"},{"i":20,"n":"第二十条","txt":"血站应当根据医疗机构临床用血需求，制定血液采集、制备、供应计划，保障临床用血安全、及时、有效。"},{"i":21,"n":"第二十一条","txt":"血站应当开展无偿献血宣传。 血站开展献血者招募，应当为献血者提供安全、卫生、便利的条件和良好的服务。"},{"i":22,"n":"第二十二条","txt":"血站应当按照国家有关规定对献血者进行健康检查和血液采集。 血站采血前应当对献血者身份进行核对并进行登记。 严禁采集冒名顶替者的血液。严禁超量、频繁采集血液。 血站不得采集血液制品生产用原料血浆。"},{"i":23,"n":"第二十三条","txt":"献血者应当按照要求出示真实的身份证明。 任何单位和个人不得组织冒名顶替者献血。"},{"i":24,"n":"第二十四条","txt":"血站采集血液应当遵循自愿和知情同意的原则，并对献血者履行规定的告知义务。 血站应当建立献血者信息保密制度，为献血者保密。"},{"i":25,"n":"第二十五条","txt":"血站应当建立对有易感染经血液传播疾病危险行为的献血者献血后的报告工作程序、献血屏蔽和淘汰制度。"},{"i":26,"n":"第二十六条","txt":"血站开展采供血业务应当实行全面质量管理，严格遵守《中国输血技术操作规程》、《血站质量管理规范》和《血站实验室质量管理规范》等技术规范和标准。 血站应当建立人员岗位责任制度和采供血管理相关工作制度，并定期检查、考核各项规章制度和各级各类人员岗位责任制的执行和落实情况。"},{"i":27,"n":"第二十七条","txt":"血站应当对血站工作人员进行岗位培训与考核。血站工作人员应当符合岗位执业资格的规定，并经岗位培训与考核合格后方可上岗。 血站工作人员每人每年应当接受不少于75学时的岗位继续教育。 省级人民政府卫生计生行政部门应当制定血站工作人员培训标准或指南，并对血站开展的岗位培训、考核工作进行指导和监督。"},{"i":28,"n":"第二十八条","txt":"血站各业务岗位工作记录应当内容真实、项目完整、格式规范、字迹清楚、记录及时，有操作者签名。 记录内容需要更改时，应当保持原记录内容清晰可辨，注明更改内容、原因和日期，并在更改处签名。 献血、检测和供血的原始记录应当至少保存十年，法律、行政法规和国家卫生计生委另有规定的，依照有关规定执行。"},{"i":29,"n":"第二十九条","txt":"血站应当保证所采集的血液由具有血液检测实验室资格的实验室进行检测。 对检测不合格或者报废的血液，血站应当严格按照有关规定处理。"},{"i":30,"n":"第三十条","txt":"血站应当制定实验室室内质控与室间质评制度，确保试剂、卫生器材、仪器、设备在使用过程中能达到预期效果。 血站的实验室应当配备必要的生物安全设备和设施，并对工作人员进行生物安全知识培训。"},{"i":31,"n":"第三十一条","txt":"血液标本的保存期为全血或成分血使用后二年。"},{"i":32,"n":"第三十二条","txt":"血站应当加强消毒、隔离工作管理，预防和控制感染性疾病的传播。 血站产生的医疗废物应当按《医疗废物管理条例》规定处理，做好记录与签字，避免交叉感染。"},{"i":33,"n":"第三十三条","txt":"血站及其执行职务的人员发现法定传染病疫情时，应当按照《传染病防治法》和国家卫生计生委的规定向有关部门报告。"},{"i":34,"n":"第三十四条","txt":"血液的包装、储存、运输应当符合《血站质量管理规范》的要求。血液包装袋上应当标明： （一）血站的名称及其许可证号； （二）献血编号或者条形码； （三）血型； （四）血液品种； （五）采血日期及时间或者制备日期及时间； （六）有效日期及时间； （七）储存条件。"},{"i":35,"n":"第三十五条","txt":"血站应当保证发出的血液质量符合国家有关标准，其品种、规格、数量、活性、血型无差错；未经检测或者检测不合格的血液，不得向医疗机构提供。"},{"i":36,"n":"第三十六条","txt":"血站应当建立质量投诉、不良反应监测和血液收回制度。"},{"i":37,"n":"第三十七条","txt":"血站应当加强对其所设储血点的质量监督，确保储存条件，保证血液储存质量；按照临床需要进行血液储存和调换。"},{"i":38,"n":"第三十八条","txt":"血站使用的药品、体外诊断试剂、一次性卫生器材应当符合国家有关规定。"},{"i":39,"n":"第三十九条","txt":"血站应当按照有关规定，认真填写采供血机构统计报表，及时准确上报。"},{"i":40,"n":"第四十条","txt":"血站应当制定紧急灾害应急预案，并从血源、管理制度、技术能力和设备条件等方面保证预案的实施。在紧急灾害发生时服从县级以上人民政府卫生计生行政部门的调遣。"},{"i":41,"n":"第四十一条","txt":"因临床、科研或者特殊需要，需要从外省、自治区、直辖市调配血液的，由省级人民政府卫生计生行政部门组织实施。 禁止临床医疗用途的人体血液、血浆进出口。"},{"i":42,"n":"第四十二条","txt":"无偿献血的血液必须用于临床，不得买卖。 血站剩余成分血浆由省、自治区、直辖市人民政府卫生计生行政部门协调血液制品生产单位解决。"},{"i":43,"n":"第四十三条","txt":"血站必须严格执行国家有关报废血处理和有易感染经血液传播疾病危险行为的献血者献血后保密性弃血处理的规定。"},{"i":44,"n":"第四十四条","txt":"血站剩余成分血浆以及因科研或者特殊需要用血而进行的调配所得的收入，全部用于无偿献血者用血返还费用，血站不得挪作他用。"},{"i":45,"n":"第四十五条","txt":"国家卫生计生委根据全国人口分布、卫生资源、临床造血干细胞移植需要等实际情况，统一制定我国脐带血造血干细胞库等特殊血站的设置规划和原则。 国家不批准设置以营利为目的的脐带血造血干细胞库等特殊血站。"},{"i":46,"n":"第四十六条","txt":"申请设置脐带血造血干细胞库等特殊血站的，应当按照国家卫生计生委规定的条件向所在地省级人民政府卫生计生行政部门申请。省级人民政府卫生计生行政部门组织初审后报国家卫生计生委。 国家卫生计生委对脐带血造血干细胞库等特殊血站设置审批按照申请的先后次序进行。"},{"i":47,"n":"第四十七条","txt":"脐带血造血干细胞库等特殊血站执业，应当向所在地省级人民政府卫生计生行政部门申请办理执业登记。 省级卫生计生行政部门应当组织有关专家和技术部门，按照本办法和国家卫生计生委制定的脐带血造血干细胞库等特殊血站的基本标准、技术规范，对申请单位进行技术审查及执业验收。审查合格的，发给《血站执业许可证》，并注明开展的业务。《血站执业许可证》有效期为三年。 未取得《血站执业许可证》的，不得开展采供脐带血造血干细胞等业务。"},{"i":48,"n":"第四十八条","txt":"脐带血造血干细胞库等特殊血站在《血站执业许可证》有效期满后继续执业的，应当在《血站执业许可证》有效期满前三个月向原执业登记的省级人民政府卫生计生行政部门申请办理再次执业登记手续。"},{"i":49,"n":"第四十九条","txt":"脐带血造血干细胞库等特殊血站执业除应当遵守本办法第二章第二节一般血站的执业要求外，还应当遵守以下规定： （一）按照国家卫生计生委规定的脐带血造血干细胞库等特殊血站的基本标准、技术规范等执业； （二）脐带血等特殊血液成分的采集必须符合医学伦理的有关要求，并遵循自愿和知情同意的原则。脐带血造血干细胞库必须与捐献者签署经执业登记机关审核的知情同意书； （三）脐带血造血干细胞库等特殊血站只能向有造血干细胞移植经验和基础，并装备有造血干细胞移植所需的无菌病房和其他必须设施的医疗机构提供脐带血造血干细胞； （四）脐带血等特殊血液成分必须用于临床。"},{"i":50,"n":"第五十条","txt":"县级以上人民政府卫生计生行政部门对采供血活动履行下列职责： （一）制定临床用血储存、配送管理办法，并监督实施； （二）对下级卫生计生行政部门履行本办法规定的血站管理职责进行监督检查； （三）对辖区内血站执业活动进行日常监督检查，组织开展对采供血质量的不定期抽检； （四）对辖区内临床供血活动进行监督检查； （五）对违反本办法的行为依法进行查处。"},{"i":51,"n":"第五十一条","txt":"各级人民政府卫生计生行政部门应当对无偿献血者的招募、采血、供血活动予以支持、指导。"},{"i":52,"n":"第五十二条","txt":"省级人民政府卫生计生行政部门应当对本辖区内的血站执行有关规定情况和无偿献血比例、采供血服务质量、业务指导、人员培训、综合质量评价技术能力等情况进行评价及监督检查，按照国家卫生计生委的有关规定将结果上报，同时向社会公布。"},{"i":53,"n":"第五十三条","txt":"国家卫生计生委定期对血液中心执行有关规定情况和无偿献血比例、采供血服务质量、业务指导、人员培训、综合质量评价技术能力等情况以及脐带血造血干细胞库等特殊血站的质量管理状况进行评价及监督检查，并将结果向社会公布。"},{"i":54,"n":"第五十四条","txt":"卫生计生行政部门在进行监督检查时，有权索取有关资料，血站不得隐瞒、阻碍或者拒绝。 卫生计生行政部门对血站提供的资料负有保密的义务，法律、行政法规或者部门规章另有规定的除外。"},{"i":55,"n":"第五十五条","txt":"卫生计生行政部门和工作人员在履行职责时，不得有以下行为： （一）对不符合法定条件的，批准其设置、执业登记或者变更登记，或者超越职权批准血站设置、执业登记或者变更登记； （二）对符合法定条件和血站设置规划的，不予批准其设置、执业登记或者变更登记；或者不在法定期限内批准其设置、执业登记或者变更登记； （三）对血站不履行监督管理职责； （四）其他违反本办法的行为。"},{"i":56,"n":"第五十六条","txt":"各级人民政府卫生计生行政部门应当建立血站监督管理的举报、投诉机制。 卫生计生行政部门对举报人和投诉人负有保密的义务。"},{"i":57,"n":"第五十七条","txt":"国家实行血液质量监测、检定制度，对血站质量管理、血站实验室质量管理实行技术评审制度，具体办法由国家卫生计生委另行制定。"},{"i":58,"n":"第五十八条","txt":"血站有下列情形之一的，由省级人民政府卫生计生行政部门注销其《血站执业许可证》： （一）《血站执业许可证》有效期届满未办理再次执业登记的； （二）取得《血站执业许可证》后一年内未开展采供血工作的。"},{"i":59,"n":"第五十九条","txt":"有下列行为之一的，属于非法采集血液，由县级以上地方人民政府卫生计生行政部门按照《献血法》第十八条的有关规定予以处罚；构成犯罪的，依法追究刑事责任： （一）未经批准，擅自设置血站，开展采供血活动的； （二）已被注消的血站，仍开展采供血活动的； （三）已取得设置批准但尚未取得《血站执业许可证》即开展采供血活动，或者《血站执业许可证》有效期满未再次登记仍开展采供血活动的； （四）租用、借用、出租、出借、变造、伪造《血站执业许可证》开展采供血活动的。"},{"i":60,"n":"第六十条","txt":"血站出售无偿献血血液的，由县级以上地方人民政府卫生计生行政部门按照《献血法》第十八条的有关规定，予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"血站有下列行为之一的，由县级以上地方人民政府卫生计生行政部门予以警告、责令改正；逾期不改正，或者造成经血液传播疾病发生，或者其他严重后果的，对负有责任的主管人员和其他直接负责人员，依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）超出执业登记的项目、内容、范围开展业务活动的； （二）工作人员未取得相关岗位执业资格或者未经执业注册而从事采供血工作的； （三）血液检测实验室未取得相应资格即进行检测的； （四）擅自采集原料血浆、买卖血液的； （五）采集血液前，未按照国家颁布的献血者健康检查要求对献血者进行健康检查、检测的； （六）采集冒名顶替者、健康检查不合格者血液以及超量、频繁采集血液的； （七）违反输血技术操作规程、有关质量规范和标准的； （八）采血前未向献血者、特殊血液成分捐赠者履行规定的告知义务的； （九）擅自涂改、毁损或者不按规定保存工作记录的； （十）使用的药品、体外诊断试"},{"i":62,"n":"第六十二条","txt":"临床用血的包装、储存、运输，不符合国家规定的卫生标准和要求的，由县级以上地方人民政府卫生计生行政部门责令改正，给予警告。"},{"i":63,"n":"第六十三条","txt":"血站违反规定，向医疗机构提供不符合国家规定标准的血液的，由县级以上人民政府卫生计生行政部门责令改正；情节严重，造成经血液途径传播的疾病传播或者有传播严重危险的，限期整顿，对直接负责的主管人员和其他责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":64,"n":"第六十四条","txt":"卫生计生行政部门及其工作人员违反本办法有关规定，有下列情形之一的，依据《献血法》、《行政许可法》的有关规定，由上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）未按规定的程序审查而使不符合条件的申请者得到许可的； （二）对不符合条件的申请者准予许可或者超越法定职权作出准予许可决定的； （三）在许可审批过程中弄虚作假的； （四）对符合条件的设置及执业登记申请不予受理的； （五）对符合条件的申请不在法定期限内作出许可决定的； （六）不依法履行监督职责，或者监督不力造成严重后果的； （七）其他在执行本办法过程中，存在滥用职权，玩忽职守，徇私舞弊，索贿受贿等行为的。"},{"i":65,"n":"第六十五条","txt":"本办法下列用语的含义： 血液，是指全血、血液成分和特殊血液成分。 脐带血，是指与孕妇和新生儿血容量和血循环无关的，由新生儿脐带扎断后的远端所采集的胎盘血。 脐带血造血干细胞库，是指以人体造血干细胞移植为目的，具有采集、处理、保存和提供造血干细胞的能力，并具有相当研究实力的特殊血站。"},{"i":66,"n":"第六十六条","txt":"本办法实施前已经设立的血站应当在本办法实施后九个月内，依照本办法规定进行调整。 省级人民政府卫生计生行政部门应当按照血液中心标准对现有血液中心进行审核，未达到血液中心标准的，应当责令限期整改。整改仍不合格的，卫生计生行政部门应当取消血液中心设置。对符合中心血站执业标准的，按照中心血站标准审核设置与执业登记。"},{"i":67,"n":"第六十七条","txt":"本办法自2006年3月1日起施行。1998年9月21日颁布的《血站管理办法》（暂行）同时废止。"}],"yuanqianyiliaojijiuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强院前医疗急救管理，规范院前医疗急救行为，提高院前医疗急救服务水平，促进院前医疗急救事业发展，根据《执业医师法》、《医疗机构管理条例》、《护士条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于从事院前医疗急救工作的医疗机构和人员。 本办法所称院前医疗急救，是指由急救中心（站）和承担院前医疗急救任务的网络医院（以下简称急救网络医院）按照统一指挥调度，在患者送达医疗机构救治前，在医疗机构外开展的以现场抢救、转运途中紧急救治以及监护为主的医疗活动。"},{"i":3,"n":"第三条","txt":"院前医疗急救是政府举办的公益性事业，鼓励、支持社会力量参与。卫生计生行政部门按照“统筹规划、整合资源、合理配置、提高效能”的原则，统一组织、管理、实施。 卫生计生行政部门应当建立稳定的经费保障机制，保证院前医疗急救与当地社会、经济发展和医疗服务需求相适应。"},{"i":4,"n":"第四条","txt":"国家卫生计生委负责规划和指导全国院前医疗急救体系建设，监督管理全国院前医疗急救工作。 县级以上地方卫生计生行政部门负责规划和实施本辖区院前医疗急救体系建设，监督管理本辖区院前医疗急救工作。"},{"i":5,"n":"第五条","txt":"院前医疗急救以急救中心（站）为主体，与急救网络医院组成院前医疗急救网络共同实施。"},{"i":6,"n":"第六条","txt":"县级以上地方卫生计生行政部门应当将院前医疗急救网络纳入当地医疗机构设置规划，按照就近、安全、迅速、有效的原则设立，统一规划、统一设置、统一管理。"},{"i":7,"n":"第七条","txt":"急救中心（站）由卫生计生行政部门按照《医疗机构管理条例》设置、审批和登记。"},{"i":8,"n":"第八条","txt":"设区的市设立一个急救中心。因地域或者交通原因，设区的市院前医疗急救网络未覆盖的县（县级市），可以依托县级医院或者独立设置一个县级急救中心（站）。 设区的市级急救中心统一指挥调度县级急救中心（站）并提供业务指导。"},{"i":9,"n":"第九条","txt":"急救中心（站）应当符合医疗机构基本标准。县级以上地方卫生计生行政部门根据院前医疗急救网络布局、医院专科情况等指定急救网络医院，并将急救网络医院名单向社会公告。急救网络医院按照其承担任务达到急救中心（站）基本要求。 未经卫生计生行政部门批准，任何单位及其内设机构、个人不得使用急救中心（站）的名称开展院前医疗急救工作。"},{"i":10,"n":"第十条","txt":"急救中心（站）负责院前医疗急救工作的指挥和调度，按照院前医疗急救需求配备通讯系统、救护车和医务人员，开展现场抢救和转运途中救治、监护。急救网络医院按照急救中心（站）指挥和调度开展院前医疗急救工作。"},{"i":11,"n":"第十一条","txt":"县级以上地方卫生计生行政部门根据区域服务人口、服务半径、地理环境、交通状况等因素，合理配置救护车。 救护车应当符合救护车卫生行业标准，标志图案、标志灯具和警报器应当符合国家、行业标准和有关规定。"},{"i":12,"n":"第十二条","txt":"急救中心（站）、急救网络医院救护车以及院前医疗急救人员的着装应当统一标识，统一标注急救中心（站）名称和院前医疗急救呼叫号码。"},{"i":13,"n":"第十三条","txt":"全国院前医疗急救呼叫号码为“120”。 急救中心（站）设置“120”呼叫受理系统和指挥中心，其他单位和个人不得设置“120”呼叫号码或者其他任何形式的院前医疗急救呼叫电话。"},{"i":14,"n":"第十四条","txt":"急救中心（站）通讯系统应当具备系统集成、救护车定位追踪、呼叫号码和位置显示、计算机辅助指挥、移动数据传输、无线集群语音通讯等功能。"},{"i":15,"n":"第十五条","txt":"县级以上地方卫生计生行政部门应当加强对院前医疗急救专业人员的培训，定期组织急救中心（站）和急救网络医院开展演练，推广新知识和先进技术，提高院前医疗急救和突发事件紧急医疗救援能力与水平。"},{"i":16,"n":"第十六条","txt":"县级以上地方卫生计生行政部门应当按照有关规定，根据行政区域内人口数量、地域范围、经济条件等因素，加强急救中心（站）的应急储备工作。"},{"i":17,"n":"第十七条","txt":"急救中心（站）和急救网络医院开展院前医疗急救工作应当遵守医疗卫生管理法律、法规、规章和技术操作规范、诊疗指南。"},{"i":18,"n":"第十八条","txt":"急救中心（站）应当制定院前医疗急救工作规章制度及人员岗位职责，保证院前医疗急救工作的医疗质量、医疗安全、规范服务和迅速处置。"},{"i":19,"n":"第十九条","txt":"从事院前医疗急救的专业人员包括医师、护士和医疗救护员。 医师和护士应当按照有关法律法规规定取得相应执业资格证书。 医疗救护员应当按照国家有关规定经培训考试合格取得国家职业资格证书；上岗前，应当经设区的市级急救中心培训考核合格。 在专业技术职务评审、考核、聘任等方面应当对上述人员给予倾斜。"},{"i":20,"n":"第二十条","txt":"医疗救护员可以从事的相关辅助医疗救护工作包括： （一）对常见急症进行现场初步处理； （二）对患者进行通气、止血、包扎、骨折固定等初步救治； （三）搬运、护送患者； （四）现场心肺复苏； （五）在现场指导群众自救、互救。"},{"i":21,"n":"第二十一条","txt":"急救中心（站）应当配备专人每天24小时受理“120”院前医疗急救呼叫。“120”院前医疗急救呼叫受理人员应当经设区的市级急救中心培训合格。"},{"i":22,"n":"第二十二条","txt":"急救中心（站）应当在接到“120”院前医疗急救呼叫后，根据院前医疗急救需要迅速派出或者从急救网络医院派出救护车和院前医疗急救专业人员。不得因指挥调度原因拒绝、推诿或者延误院前医疗急救服务。"},{"i":23,"n":"第二十三条","txt":"急救中心（站）和急救网络医院应当按照就近、就急、满足专业需要、兼顾患者意愿的原则，将患者转运至医疗机构救治。"},{"i":24,"n":"第二十四条","txt":"急救中心（站）和急救网络医院应当做好“120”院前医疗急救呼叫受理、指挥调度等记录及保管工作，并按照医疗机构病历管理相关规定，做好现场抢救、监护运送、途中救治和医院接收等记录及保管工作。"},{"i":25,"n":"第二十五条","txt":"急救中心（站）和急救网络医院按照国家有关规定收取院前医疗急救服务费用，不得因费用问题拒绝或者延误院前医疗急救服务。"},{"i":26,"n":"第二十六条","txt":"急救中心（站）应当按照有关规定做好突发事件紧急医疗救援的现场救援和信息报告工作。"},{"i":27,"n":"第二十七条","txt":"急救中心（站）和急救网络医院不得将救护车用于非院前医疗急救服务。 除急救中心（站）和急救网络医院外，任何单位和个人不得使用救护车开展院前医疗急救工作。"},{"i":28,"n":"第二十八条","txt":"急救中心（站）应当按照相关规定作好应急储备物资管理等相关工作。"},{"i":29,"n":"第二十九条","txt":"急救中心（站）和急救网络医院应当向公众提供急救知识和技能的科普宣传和培训，提高公众急救意识和能力。"},{"i":30,"n":"第三十条","txt":"县级以上地方卫生计生行政部门应当加强对院前医疗急救工作的监督与管理。"},{"i":31,"n":"第三十一条","txt":"县级以上地方卫生计生行政部门应当加强急救中心（站）和急救网络医院的设置管理工作，对其执业活动进行检查指导。"},{"i":32,"n":"第三十二条","txt":"县级以上地方卫生计生行政部门发现本辖区任何单位及其内设机构、个人未经批准使用急救中心（站）的名称或救护车开展院前医疗急救工作的，应当依法依规严肃处理，并向同级公安机关通报情况。"},{"i":33,"n":"第三十三条","txt":"上级卫生计生行政部门应当加强对下级卫生计生行政部门的监督检查，发现下级卫生计生行政部门未履行职责的，应当责令其纠正或者直接予以纠正。"},{"i":34,"n":"第三十四条","txt":"急救中心（站）和急救网络医院应当对本机构从业人员的业务水平、工作成绩和职业道德等情况进行管理、培训和考核，并依法依规给予相应的表彰、奖励、处理等。"},{"i":35,"n":"第三十五条","txt":"任何单位或者个人未经卫生计生行政部门批准擅自开展院前医疗急救服务的，由县级以上地方卫生计生行政部门按照《医疗机构管理条例》等有关规定予以处理。"},{"i":36,"n":"第三十六条","txt":"急救中心（站）和急救网络医院使用非卫生专业技术人员从事院前医疗急救服务的，由县级以上地方卫生计生行政部门按照《执业医师法》、《医疗机构管理条例》和《护士条例》等有关法律法规的规定予以处理。"},{"i":37,"n":"第三十七条","txt":"医疗机构有下列情形之一的，由县级以上地方卫生计生行政部门责令改正、通报批评、给予警告；对直接负责的主管人员和其他直接责任人员，根据情节轻重，依法给予警告、记过、降低岗位等级、撤职、开除等处分： （一）未经批准擅自使用“120”院前医疗急救呼叫号码或者其他带有院前医疗急救呼叫性质号码的； （二）未经批准擅自使用救护车开展院前医疗急救服务的； （三）急救中心（站）因指挥调度或者费用等因素拒绝、推诿或者延误院前医疗急救服务的； （四）违反本办法其他规定的。"},{"i":38,"n":"第三十八条","txt":"本办法所称医疗救护员，是指人力资源社会保障部第四批新职业情况说明所定义，运用救护知识和技能，对各种急症、意外事故、创伤和突发公共卫生事件施行现场初步紧急救护的人员。"},{"i":39,"n":"第三十九条","txt":"本办法所称救护车，是指符合救护车卫生行业标准、用于院前医疗急救的特种车辆。"},{"i":40,"n":"第四十条","txt":"在突发事件中，公民、法人和其他单位开展的卫生救护不适用于本办法。"},{"i":41,"n":"第四十一条","txt":"本办法自2014年2月1日起施行。"}],"yufangjiezhongyichangfanyingjiandingbanfa":[{"i":1,"n":"第一条","txt":"为规范预防接种异常反应鉴定工作，根据《疫苗流通和预防接种管理条例》和《医疗事故处理条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"预防接种异常反应，是指合格的疫苗在实施规范接种过程中或者实施规范接种后造成受种者机体组织器官、功能损害，相关各方均无过错的药品不良反应。"},{"i":3,"n":"第三条","txt":"受种者或者监护人（以下简称受种方）、接种单位、疫苗生产企业对预防接种异常反应调查诊断结论有争议申请预防接种异常反应鉴定的，适用本办法。 预防接种异常反应调查诊断按照卫生部的规定及《预防接种工作规范》进行。 因接种单位违反预防接种工作规范、免疫程序、疫苗使用指导原则、接种方案等原因给受种者造成损害，需要进行医疗事故技术鉴定的，按照医疗事故技术鉴定办法办理。 对疫苗质量原因或者疫苗检验结果有争议的，按照《药品管理法》的规定，向药品监督管理部门申请处理。"},{"i":4,"n":"第四条","txt":"预防接种异常反应鉴定工作应当遵循公开、公正的原则，坚持实事求是的科学态度，做到事实清楚、定性准确。"},{"i":5,"n":"第五条","txt":"预防接种异常反应鉴定由设区的市级和省、自治区、直辖市医学会负责。"},{"i":6,"n":"第六条","txt":"省、自治区、直辖市医学会建立预防接种异常反应鉴定专家库，为省级、设区的市级医学会的预防接种异常反应鉴定提供专家。专家库由临床、流行病、医学检验、药学、法医等相关学科的专家组成，并依据相关学科设置专业组。 医学会可以根据预防接种异常反应鉴定的实际情况，对专家库学科专业组予以适当增减，对专家库成员进行调整。"},{"i":7,"n":"第七条","txt":"具备下列条件的医药卫生等专业技术人员可以作为专家库候选人： （一）有良好的业务素质和执业品德； （二）受聘于医药卫生机构或者医药卫生教学、科研等机构并担任相应专业高级技术职务3年以上； （三）流行病学专家应当有3年以上免疫预防相关工作经验；药学专家应当有3年以上疫苗相关工作经验； （四）健康状况能够胜任预防接种异常反应鉴定工作。 符合前款（一）、（四）项规定条件并具备高级技术职务任职资格的法医可以受聘进入专家库。 省、自治区、直辖市医学会原则上聘请本行政区域内的专家进入专家库；当本行政区域内的专家不能满足建立专家库需要时，可以聘请本行政区域外的专家进入专家库。"},{"i":8,"n":"第八条","txt":"医药卫生机构或者医药卫生教学、科研机构、医药卫生专业学会应当按照医学会要求，推荐专家库候选人；符合条件的个人经所在单位同意后也可以直接向组建专家库的医学会申请进入专家库。 医学会对专家库成员候选人进行审核。审核合格的，予以聘任，并发给中华医学会统一格式的聘书和证件。"},{"i":9,"n":"第九条","txt":"专家库成员聘用期为4年。在聘用期间出现下列情形之一的，医学会根据实际情况及时进行调整： （一）因健康原因不能胜任预防接种异常反应鉴定的； （二）变更受聘单位或者被解聘的； （三）不具备完全民事行为能力的； （四）受刑事处罚的； （五）违反鉴定工作纪律，情节严重的； （六）省级以上卫生行政部门和药品监督管理部门规定的其他情形。 聘用期满需继续聘用的，由原聘医学会重新审核、聘用。"},{"i":10,"n":"第十条","txt":"各级各类医疗机构、疾病预防控制机构和接种单位及其执行职务的人员发现预防接种异常反应、疑似预防接种异常反应或者接到相关报告，应当及时向所在地的县级卫生行政部门、药品监督管理部门报告。"},{"i":11,"n":"第十一条","txt":"省级、设区的市级和县级疾病预防控制机构应当成立预防接种异常反应调查诊断专家组，负责预防接种异常反应调查诊断。调查诊断专家组由流行病学、临床医学、药学等专家组成。 县级卫生行政部门、药品监督管理部门接到疑似预防接种异常反应的报告后，对需要进行调查诊断的，交由县级疾病预防控制机构组织专家进行调查诊断。 有下列情形之一的，应当由设区的市级或者省级预防接种异常反应调查诊断专家组进行调查诊断： （一）受种者死亡、严重残疾的； （二）群体性疑似预防接种异常反应的； （三）对社会有重大影响的疑似预防接种异常反应。"},{"i":12,"n":"第十二条","txt":"预防接种异常反应调查诊断专家组应当依据法律、行政法规、部门规章和技术规范，结合临床表现、医学检查结果和疫苗质量检验结果等，进行综合分析，作出调查诊断结论。 死亡病例调查诊断需要尸检结果的，受种方拒绝或者不配合尸检，承担无法进行调查诊断的责任。 调查诊断专家组在作出调查诊断后10日内，将调查诊断结论报同级卫生行政部门和药品监督管理部门。"},{"i":13,"n":"第十三条","txt":"调查诊断怀疑引起疑似预防接种异常反应的疫苗有质量问题的，药品监督管理部门负责组织对相关疫苗质量进行检验，出具检验结果报告。"},{"i":14,"n":"第十四条","txt":"受种方、接种单位、疫苗生产企业对预防接种异常反应调查诊断结论有争议时，可以在收到预防接种异常反应调查诊断结论之日起60日内向接种单位所在地设区的市级医学会申请进行预防接种异常反应鉴定，并提交预防接种异常反应鉴定所需的材料。"},{"i":15,"n":"第十五条","txt":"有关预防接种异常反应鉴定材料应当包括下列内容： （一）预防接种异常反应调查诊断结论； （二）受种者健康状况、知情同意告知以及医学建议等预防接种有关记录； （三）与诊断治疗有关的门诊病历、住院志、体温单、医嘱单、化验单（检验报告）、医学影像检查资料、病理资料、护理记录等病历资料； （四）疫苗接收、购进记录和储存温度记录等； （五）相关疫苗该批次检验合格或者抽样检验报告，进口疫苗还应当由批发企业提供进口药品通关文件； （六）与预防接种异常反应鉴定有关的其他材料。 受种方、接种单位、疫苗生产企业应当根据要求，分别提供由自己保存或者掌握的上述材料。 负责组织鉴定的医学会因鉴定需要可以向医疗机构调取受种者的病程记录、死亡病例讨论记录、会诊意见等病历资料。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，医学会不予受理预防接种异常反应鉴定： （一）无预防接种异常反应调查诊断结论的； （二）已向人民法院提起诉讼的（人民法院、检察院委托的除外），或者已经人民法院调解达成协议或者判决的； （三）受种方、接种单位、疫苗生产企业未按规定提交有关材料的； （四）提供的材料不真实的； （五）不缴纳鉴定费的； （六）省级卫生行政部门规定的其他情形。 不予受理鉴定的，医学会应当书面说明理由。"},{"i":17,"n":"第十七条","txt":"对设区的市级医学会鉴定结论不服的，可以在收到预防接种异常反应鉴定书之日起15日内，向接种单位所在地的省、自治区、直辖市医学会申请再鉴定。"},{"i":18,"n":"第十八条","txt":"申请预防接种异常反应鉴定，由申请鉴定方预缴鉴定费。经鉴定属于一类疫苗引起的预防接种异常反应的，鉴定费用由同级财政部门按照规定统筹安排；由二类疫苗引起的预防接种异常反应的，鉴定费用由相关的疫苗生产企业承担。不属于异常反应的，鉴定费用由提出异常反应鉴定的申请方承担。预防接种异常反应鉴定收费标准按照国家有关规定执行。"},{"i":19,"n":"第十九条","txt":"负责鉴定的医学会应当根据受理的预防接种异常反应鉴定所涉及的学科专业，确定专家鉴定组的构成和人数。专家鉴定组人数为5人以上单数。专家鉴定组的人员由受种方在专家库中随机抽取。受种方人员较多的，可以由受种方推选1—2名代表人随机抽取专家鉴定组成员。推选不出的，由医学会负责抽取。"},{"i":20,"n":"第二十条","txt":"鉴定组成员有下列情形之一的，应当回避： （一）受种者的亲属； （二）接种单位的工作人员； （三）与预防接种异常反应鉴定结果有利害关系的人员； （四）参与预防接种异常反应调查诊断的人员； （五）其他可能影响公正鉴定的人员。"},{"i":21,"n":"第二十一条","txt":"专家鉴定组应当认真审查材料，必要时可以听取受种方、接种单位、疫苗生产企业的陈述，对受种者进行医学检查。 负责鉴定的医学会可以根据专家鉴定组的要求进行调查取证，进行调查取证时不得少于2人。调查取证结束后，调查人员和调查对象应当在有关文书上签字。如调查对象拒绝签字的，应当记录在案。 医学会组织鉴定时可以要求受种方、接种单位、疫苗生产企业必须如实提供相关材料，如不提供则承担相关不利后果。"},{"i":22,"n":"第二十二条","txt":"专家鉴定组应当妥善保管鉴定材料，保护当事人的隐私，保守有关秘密。"},{"i":23,"n":"第二十三条","txt":"专家鉴定组组长由专家鉴定组成员推选产生，也可以由预防接种异常反应争议所涉及的主要学科中资深的专家担任。"},{"i":24,"n":"第二十四条","txt":"专家鉴定组可以根据需要，提请医学会邀请其他专家参加预防接种异常反应鉴定。邀请的专家可以提出技术意见、提供有关资料，但不参加鉴定结论的表决。 邀请的专家不得有本办法第二十条规定的情形。"},{"i":25,"n":"第二十五条","txt":"疑难、复杂并在全国有重大影响的预防接种异常反应鉴定，地方医学会可以要求中华医学会给予技术指导和支持。"},{"i":26,"n":"第二十六条","txt":"专家鉴定组应当认真审阅有关资料，依照有关规定和技术标准，运用科学原理和专业知识，独立进行鉴定。在事实清楚的基础上，进行综合分析，作出鉴定结论，并制作鉴定书。鉴定书格式由中华医学会统一制定。 鉴定结论应当按半数以上专家鉴定组成员的一致意见形成。专家鉴定组成员在鉴定结论上签名。专家鉴定组成员对鉴定结论的不同意见，应当予以注明。"},{"i":27,"n":"第二十七条","txt":"预防接种异常反应鉴定书由专家鉴定组组长签发。鉴定书应当加盖预防接种异常反应鉴定专用章。 医学会应当在作出鉴定结论10日内将预防接种异常反应鉴定书送达申请人，并报送所在地同级卫生行政部门和药品监督管理部门。"},{"i":28,"n":"第二十八条","txt":"预防接种异常反应鉴定书应当包括下列内容： （一）申请人申请鉴定的理由； （二）有关人员、单位提交的材料和医学会的调查材料； （三）接种、诊治经过； （四）对鉴定过程的说明； （五）预防接种异常反应的判定及依据； （六）预防接种异常反应损害程度分级。 经鉴定不属于预防接种异常反应的，应当在鉴定书中说明理由。"},{"i":29,"n":"第二十九条","txt":"医学会参加预防接种异常反应鉴定会的工作人员，对鉴定过程应当如实记录。"},{"i":30,"n":"第三十条","txt":"医学会应当自收到有关预防接种异常反应鉴定材料之日起45日内组织鉴定，出具预防接种异常反应鉴定书。情况特殊的可延长至90日。"},{"i":31,"n":"第三十一条","txt":"卫生行政部门、药品监督管理部门等有关部门发现鉴定违反本办法有关规定的，可以要求医学会重新组织鉴定。"},{"i":32,"n":"第三十二条","txt":"医学会应当将鉴定的文书档案和有关资料存档，保存期限不得少于20年。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市医学会应当于每年4月30日前将本行政区域上一年度预防接种异常反应鉴定情况报中华医学会，同时报同级卫生行政部门、药品监督管理部门。 设区的市级医学会应当于每年3月31日前将本行政区域上一年度预防接种异常反应鉴定情况报省、自治区、直辖市医学会，同时报同级卫生行政部门、药品监督管理部门。"},{"i":34,"n":"第三十四条","txt":"因预防接种异常反应需要对受种者予以补偿的，按照《疫苗流通和预防接种管理条例》第四十六条的规定执行。"},{"i":35,"n":"第三十五条","txt":"本办法自2008年12月1日起施行。1980年1月22日卫生部发布的《预防接种后异常反应和事故的处理试行办法》同时废止。"}],"shipintianjiajixinpinzhongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强食品添加剂新品种管理，根据《食品安全法》和《食品安全法实施条例》有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"食品添加剂新品种是指： （一）未列入食品安全国家标准的食品添加剂品种； （二）未列入国家卫生计生委公告允许使用的食品添加剂品种； （三）扩大使用范围或者用量的食品添加剂品种。"},{"i":3,"n":"第三条","txt":"食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠。"},{"i":4,"n":"第四条","txt":"使用食品添加剂应当符合下列要求： （一）不应当掩盖食品腐败变质； （二）不应当掩盖食品本身或者加工过程中的质量缺陷； （三）不以掺杂、掺假、伪造为目的而使用食品添加剂； （四）不应当降低食品本身的营养价值； （五）在达到预期的效果下尽可能降低在食品中的用量； （六）食品工业用加工助剂应当在制成最后成品之前去除，有规定允许残留量的除外。"},{"i":5,"n":"第五条","txt":"国家卫生计生委负责食品添加剂新品种的审查许可工作，组织制定食品添加剂新品种技术评价和审查规范。 国家卫生计生委食品添加剂新品种技术审评机构（以下简称审评机构）负责食品添加剂新品种技术审查，提出综合审查结论及建议。"},{"i":6,"n":"第六条","txt":"申请食品添加剂新品种生产、经营、使用或者进口的单位或者个人（以下简称申请人），应当提出食品添加剂新品种许可申请，并提交以下材料： （一）添加剂的通用名称、功能分类，用量和使用范围； （二）证明技术上确有必要和使用效果的资料或者文件； （三）食品添加剂的质量规格要求、生产工艺和检验方法，食品中该添加剂的检验方法或者相关情况说明； （四）安全性评估材料，包括生产原料或者来源、化学结构和物理特性、生产工艺、毒理学安全性评价资料或者检验报告、质量规格检验报告； （五）标签、说明书和食品添加剂产品样品； （六）其他国家（地区）、国际组织允许生产和使用等有助于安全性评估的资料。 申请食品添加剂品种扩大使用范围或者用量的，可以免于提交前款第四项材料，但是技术评审中要求补充提供的除外。"},{"i":7,"n":"第七条","txt":"申请首次进口食品添加剂新品种的，除提交第六条规定的材料外，还应当提交以下材料： （一）出口国（地区）相关部门或者机构出具的允许该添加剂在本国（地区）生产或者销售的证明材料； （二）生产企业所在国（地区）有关机构或者组织出具的对生产企业审查或者认证的证明材料。"},{"i":8,"n":"第八条","txt":"申请人应当如实提交有关材料，反映真实情况，并对申请材料内容的真实性负责，承担法律后果。"},{"i":9,"n":"第九条","txt":"申请人应当在其提交的本办法第六条第一款第一项、第二项、第三项材料中注明不涉及商业秘密，可以向社会公开的内容。 食品添加剂新品种技术上确有必要和使用效果等情况，应当向社会公开征求意见，同时征求质量监督、工商行政管理、食品药品监督管理、工业和信息化、商务等有关部门和相关行业组织的意见。 对有重大意见分歧，或者涉及重大利益关系的，可以举行听证会听取意见。 反映的有关意见作为技术评审的参考依据。"},{"i":10,"n":"第十条","txt":"国家卫生计生委应当在受理后60日内组织医学、农业、食品、营养、工艺等方面的专家对食品添加剂新品种技术上确有必要性和安全性评估资料进行技术审查，并作出技术评审结论。对技术评审中需要补充有关资料的，应当及时通知申请人，申请人应当按照要求及时补充有关材料。 必要时，可以组织专家对食品添加剂新品种研制及生产现场进行核实、评价。"},{"i":11,"n":"第十一条","txt":"食品添加剂新品种行政许可的具体程序按照《行政许可法》和《卫生行政许可管理办法》等有关规定执行。"},{"i":12,"n":"第十二条","txt":"审评机构提出的综合审查结论，应当包括安全性、技术必要性审查结果和社会稳定风险评估结果。"},{"i":13,"n":"第十三条","txt":"根据技术评审结论，国家卫生计生委决定对在技术上确有必要性和符合食品安全要求的食品添加剂新品种准予许可并列入允许使用的食品添加剂名单予以公布。 对缺乏技术上必要性和不符合食品安全要求的，不予许可并书面说明理由。 对发现可能添加到食品中的非食用化学物质或者其他危害人体健康的物质，按照《食品安全法实施条例》第四十九条执行。"},{"i":14,"n":"第十四条","txt":"国家卫生计生委根据技术上必要性和食品安全风险评估结果，将公告允许使用的食品添加剂的品种、使用范围、用量按照食品安全国家标准的程序，制定、公布为食品安全国家标准。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，国家卫生计生委应当及时组织对食品添加剂进行重新评估： （一）科学研究结果或者有证据表明食品添加剂安全性可能存在问题的； （二）不再具备技术上必要性的。 对重新审查认为不符合食品安全要求的，国家卫生计生委可以公告撤销已批准的食品添加剂品种或者修订其使用范围和用量。"},{"i":16,"n":"第十六条","txt":"申请人隐瞒有关情况或者提供虚假材料申请食品添加剂新品种许可的，国家卫生计生委不予受理或者不予行政许可，并给予警告，且申请人在一年内不得再次申请食品添加剂新品种许可。 以欺骗、贿赂等不正当手段通过食品添加剂新品种审查并取得许可的，国家卫生计生委应当撤销许可，且申请人在三年内不得再次申请食品添加剂新品种许可。"},{"i":17,"n":"第十七条","txt":"本办法自公布之日起施行。国家卫生计生委2002年3月28日发布的《食品添加剂卫生管理办法》同时废止。"}],"xianggangaomentebiexingzhengquyishizaineididuanqix3caa14":[{"i":1,"n":"第一条","txt":"为了加强香港特别行政区、澳门特别行政区医师（以下简称港澳医师）在内地短期行医的管理，根据《中华人民共和国执业医师法》（以下简称《执业医师法》）、《医疗机构管理条例》等法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称港澳医师是指具有香港特别行政区或者澳门特别行政区合法行医资格的医师。 港澳医师在内地短期行医，是指港澳医师应聘在内地医疗机构从事不超过3年的临床诊疗活动。"},{"i":3,"n":"第三条","txt":"港澳医师在内地短期行医应当按照本规定进行执业注册，取得《港澳医师短期行医执业证书》。 《港澳医师短期行医执业证书》由卫生部统一制作。"},{"i":4,"n":"第四条","txt":"港澳医师在内地短期行医，应当符合内地有关港澳人员的就业规定，由内地具有独立法人资格的医疗机构邀请并作为聘用单位。"},{"i":5,"n":"第五条","txt":"港澳医师在内地短期行医的执业注册机关为医疗机构所在地设区的市级以上地方人民政府卫生行政部门和中医药管理部门。 港澳医师申请内地短期行医执业注册的执业类别可以为临床、中医、口腔三个类别之一。执业范围应当符合《执业医师法》和卫生部有关执业范围的规定。"},{"i":6,"n":"第六条","txt":"港澳医师申请在内地短期行医执业注册，应当提交下列材料： （一）港澳医师在内地短期行医执业注册申请； （二）港澳永久居民身份证明材料； （三）近6个月内的2寸免冠正面半身照片2张； （四）与申请执业范围相适应的医学专业最高学历证明； （五）港澳医师的行医执照或者行医资格证明； （六）近3个月内的体检健康证明； （七）无刑事犯罪记录的证明； （八）内地聘用医疗机构与港澳医师签订的协议书； （九）内地省级以上人民政府卫生行政部门规定的其他材料。 前款（四）、（五）、（六）、（七）项的内容必须经过港澳地区公证机关的公证。 以上材料应当为中文文本。"},{"i":7,"n":"第七条","txt":"港澳医师可以自行办理或者书面委托内地的聘用医疗机构代其办理短期行医执业注册手续。"},{"i":8,"n":"第八条","txt":"负责受理港澳医师短期行医执业注册申请的执业注册机关应当自受理申请之日起20日内进行审核。对审核合格的予以注册，并发给《港澳医师短期行医执业证书》。"},{"i":9,"n":"第九条","txt":"《港澳医师短期行医执业证书》有效期应与港澳医师在内地医疗机构应聘的时间相同，最长为3年。有效期满后，如拟继续执业的，应当重新办理短期行医执业注册手续。"},{"i":10,"n":"第十条","txt":"港澳医师在内地短期行医必须遵守医疗卫生管理法律、行政法规、部门规章及诊疗护理规范、常规，尊重当地的风俗习惯。"},{"i":11,"n":"第十一条","txt":"港澳医师在内地短期行医必须在执业有效期内按照注册的执业地点、执业类别、执业范围从事相应的诊疗活动。"},{"i":12,"n":"第十二条","txt":"港澳医师在内地短期行医应当按照《医师定期考核管理办法》和卫生部有关规定接受定期考核。"},{"i":13,"n":"第十三条","txt":"港澳医师短期行医执业注册后有下列情形之一的，聘用的医疗机构应当在30日内报告准予其执业注册的卫生行政部门，卫生行政部门应当注销注册，收回《港澳医师短期行医执业证书》： （一）医疗机构和港澳医师解除聘用关系的； （二）身体健康状况不适宜继续执业的； （三）在考核周期内因考核不合格，被责令暂停执业活动，并在暂停执业活动期满经培训后再次考核仍不合格的； （四）违反《执业医师法》有关规定，被吊销《港澳医师短期行医执业证书》的； （五）出借、出租、抵押、转让、涂改《港澳医师短期行医执业证书》的； （六）死亡或者被宣告失踪的； （七）受刑事处罚的； （八）被公安机关取消内地居留资格的； （九）卫生部规定不宜从事医疗、预防、保健业务的其他情形的。"},{"i":14,"n":"第十四条","txt":"港澳医师因本办法第十三条第（三）项、第（四）项、第（七）项、第（八）项情形而被注销执业注册的，2年内不得再次申请在内地短期行医。"},{"i":15,"n":"第十五条","txt":"卫生部指定的机构设立港澳医师短期行医信息查询系统。 执业注册机关在审核港澳医师短期行医执业注册申请时应当进行有关信息查询。 执业注册机关核发或者注销《港澳医师短期行医执业证书》后10日内将有关信息向卫生部指定的查询机构备案。 聘用港澳医师短期行医的医疗机构应当将港澳医师考核和执业情况向注册机关和卫生部指定的查询机构报告。"},{"i":16,"n":"第十六条","txt":"港澳医师在内地短期行医期间发生医疗事故争议的，按照《医疗事故处理条例》及有关规定处理。"},{"i":17,"n":"第十七条","txt":"医疗机构聘用未经内地短期行医执业注册的港澳医师从事诊疗活动，视为聘用非卫生技术人员，按照《医疗机构管理条例》第四十八条规定处理。"},{"i":18,"n":"第十八条","txt":"港澳医师未取得《港澳医师短期行医执业证书》行医或者未按照注册的有效期从事诊疗活动的，按照《执业医师法》第三十九条规定处理。"},{"i":19,"n":"第十九条","txt":"港澳医师未按照注册的执业地点、执业类别、执业范围从事诊疗活动的，由县级以上人民政府卫生行政部门责令改正，并给予警告；逾期不改的，按照《执业医师法》第三十七条第（一）项规定处理。"},{"i":20,"n":"第二十条","txt":"取得内地《医师资格证书》的香港、澳门居民申请在内地执业注册的，按照《医师执业注册暂行办法》执行。"},{"i":21,"n":"第二十一条","txt":"本规定自2009年3月1日起施行。原有规定与本规定不符的，以本规定为准。"}]};
